insert into public.bible_verses (translation_id, book_id, chapter, verse, text)
values
('kam', 'NUM', 10, 12, 'Na ana ma Isilaeli makũsya makĩthi o ũndũ maendaa syalo kuma weũnĩ wa Sinai; na ũla mũumbĩ waũngama weũnĩ wa Valani.'),
('kam', 'NUM', 10, 13, 'Na mamba kũthi kyalo o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 10, 14, 'Na kya mbee kya kũkũsya kyaĩ kĩvevelo kya mwako wa maeema wa ana ma Yuta kwĩanana na nguthu syoo: na mũnene wa nguthu yake aĩ Nasoni mwana wa Aminatavu.'),
('kam', 'NUM', 10, 15, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Isakali aĩ Nethaneli mwana wa Nzuali.'),
('kam', 'NUM', 10, 16, 'Na mũnene wa nguthu ya mbai ya ana ma Nzevuluni aĩ Eliavu mwana wa Eeloni.'),
('kam', 'NUM', 10, 17, 'Na wĩkalo wathaw’a; na ana ma Ngelisoni na ana ma Melali, ala makuaa wĩkalo, makũsya.'),
('kam', 'NUM', 10, 18, 'Na kĩvevelo kya mwako wa maeema wa Leuveni kyakũsya kwĩanana na nguthu syoo: na mũnene wa nguthu yake aĩ Elisuli mwana wa Seteuli.'),
('kam', 'NUM', 10, 19, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Simeoni aĩ Selumieli mwana wa Nzuli‐satai.'),
('kam', 'NUM', 10, 20, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Ngati aĩ Eliasavu mwana wa Ndeueli.'),
('kam', 'NUM', 10, 21, 'Na Akoathi makũsya makuĩte vala vandũ vatheu: na asu angĩ maĩ manaũngamya wĩkalo Akoathi matanavika.'),
('kam', 'NUM', 10, 22, 'Na kĩvevelo kya mwako wa maeema wa Evalaimu kyakũsya kwĩanana na nguthu syoo: na mũnene wa nguthu yake aĩ Elisama mwana wa Amiuti.'),
('kam', 'NUM', 10, 23, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Manase aĩ Ngamalieli mwana wa Vetasuli.'),
('kam', 'NUM', 10, 24, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Mbenyamini aĩ Avitani mwana wa Kiteoni.'),
('kam', 'NUM', 10, 25, 'Na kĩvevelo kya mwako wa maeema wa ana ma Ndani, ũla waĩ ĩtina wa myako ya maeema yonthe, kyakũsya kwĩanana na nguthu syoo: na mũnene wa nguthu yake aĩ Aieseli mwana wa Amisatai.'),
('kam', 'NUM', 10, 26, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Aseli aĩ Vakieli mwana wa Okalanĩ.'),
('kam', 'NUM', 10, 27, 'Na mũnene wa nguthu ya mbaĩ ya ana ma Navitali aĩ Aila mwana wa Enani.'),
('kam', 'NUM', 10, 28, 'Ũu nĩw’o ana ma Isilaeli maendaa syalo kwĩanana na nguthu syoo; na makũsya.'),
('kam', 'NUM', 10, 29, 'Na Mose amwĩa Ovavu, mwana wa Leueli Mũmitiani, mũthoni wa Mose, atĩĩ, Nĩtũendete kyalo vandũ vala Yeova waisye ũndũ wa vo, Ngamũnenga inyw’ĩ: ũka ũendan’ye naitũ, na tũkakwĩka nesa; nũndũ Yeova nĩwaĩtye kana akeeka Isilaeli nesa.'),
('kam', 'NUM', 10, 30, 'Na amwĩa, Ndithi; ĩndĩ nĩngũthi nthĩ yakwa, na kwa ũko wakwa.'),
('kam', 'NUM', 10, 31, 'Nake asya, Ndũkatũtie, nĩngũkwĩsũva; nĩkwĩthĩwa nĩwĩsĩ ũndũ twĩambaa maeema maitũ weũnĩ, naku ũkeethĩwa kwitũ vandũ va metho.'),
('kam', 'NUM', 10, 32, 'Na kũkeethĩwa, wathi naitũ, ĩĩ, kũkeethĩwa kana ũseo o na wĩva ũla Yeova ũkatwĩka, o ũsu tũkakwĩka we.'),
('kam', 'NUM', 10, 33, 'Na makũsya kuma kũmanĩ kya Yeova kyalo kya mĩthenya ĩtatũ; na ĩsandũkũ ya ũtianĩo ya Yeova yaenda mbee wamo kyalo kya mĩthenya ĩtatũ, kũmamanthĩa vandũ va ũthũmũo.'),
('kam', 'NUM', 10, 34, 'Na mũumbĩ wa Yeova waĩ ĩũlũ woo mũthenya, yĩla makũasya makyuma mwakonĩ wa maeema.'),
('kam', 'NUM', 10, 35, 'Na kweethĩwa yĩla ĩsandũkũ yakũisye, Mose asya, Ũkĩla, ame Yeova, na amaitha maku nĩmanyaĩĩkw’e; na ala makũmenaa nĩmakũke makũkĩe.'),
('kam', 'NUM', 10, 36, 'Nayo yaũngama, asya, Ame Yeova, syokea ngili ĩkũmi sya ngili sya Isilaeli.'),
('kam', 'NUM', 11, 1, 'Na andũ manyungunyĩasya, makĩneena ũthũku matũnĩ ma Yeova: na Yeova eew’a ũu, ũthatu wake wakana; na mwaki wa Yeova wakana katĩ woo, na wavĩvya kũvika mũminũkĩlyo wa mwako wa maeema.'),
('kam', 'NUM', 11, 2, 'Na andũ asu mamwĩkaĩla Mose; na Mose amũvoya Yeova, na mwaki wanyiva.'),
('kam', 'NUM', 11, 3, 'Na syĩtwa ya vandũ vau veetwa Tavela: nĩkwĩthĩwa mwaki wa Yeova wakana katĩ woo.'),
('kam', 'NUM', 11, 4, 'Na nguthu ya elikya yĩla yaĩ katĩ wamo maya ĩtomo mũno: na ana ma Isilaeli namo maĩa ĩngĩ, na masya, Nũũ wĩtũnenga nyama tũye?'),
('kam', 'NUM', 11, 5, 'Nĩtũũlilikana makũyũ ma manzĩnĩ ala twaĩsaa Misili mana; na mongũ, na matikitiki, na ĩtũngũũ sya liki, na itũngũũ, na itũngũũ sya sumu:'),
('kam', 'NUM', 11, 6, 'ĩndĩ yu ngoo sitũ nĩ ndevu; na vati kĩndũ nongi kya kũsisya ate o lĩu ũũ wĩtawa mana.'),
('kam', 'NUM', 11, 7, 'Na mana ũsu wailyĩ ta mbeke ya kolianda, na kwoneka kwaw’o wailyĩ ta veteliumi.'),
('kam', 'NUM', 11, 8, 'Andũ nĩmangangaa, na makyũkolan’ya, na kũthiĩa ithiinĩ, kana kũkima na ndĩĩ, na kũua na mbisũ, na maiseũvya tũmũtũ naw’o: na ũsamo waw’o waĩ ta ũsamo wa mauta ma mĩtũkĩ.'),
('kam', 'NUM', 11, 9, 'Na yĩla kwaya ĩmwe ũtukũ mwakonĩ wa maeema, mana ũsu nĩwavalũkaa ĩũlũ wayo.'),
('kam', 'NUM', 11, 10, 'Na Mose eew’a andũ ma mĩvĩa yonthe makĩĩa, kĩla mũndũ mũomonĩ wa ĩeema yake: na ũthatu wa Yeova wakana mũno; nake Mose eew’a woo.'),
('kam', 'NUM', 11, 11, 'Na Mose amwĩa Yeova, Nũndũ wa kĩ kũmbĩka naĩ nyie mũthũkũmi waku? Na nũndũ wa kĩ ndekwona ũseo methonĩ maku, ũndũ ũũmbaĩkya mũio wa andũ aa onthe?'),
('kam', 'NUM', 11, 12, 'Ninyie namaitavie andũ aa onthe? Ninyie namasyaie, ũndũ ũũmbĩa, Makue kĩthũinĩ kyaku, o tondũ ĩthe ũla ũeaa syana ũkuaa kana kala kongaa, kũvika nthĩ ĩla weevĩtie kũmanenga aaĩthe moo?'),
('kam', 'NUM', 11, 13, 'Nĩumya nyama va sya kũnenga andũ aa onthe? Nũndũ nĩmeũndĩĩa, makĩmbĩa, Tũnenge nyama, tũye.'),
('kam', 'NUM', 11, 14, 'Nditonya kũkua andũ aa onthe nĩ nyioka, nũndũ nĩ mũio mũito kũthonoka ũndũ ndonya.'),
('kam', 'NUM', 11, 15, 'Na ethĩwa nũũmbĩka ũu, mbũaa vyũ, nĩngũkwĩsũva, ethĩwa nĩnonete ũseo methonĩ maku; nĩeke kwona mathĩna aa nĩ namo.'),
('kam', 'NUM', 11, 16, 'Na Yeova amwĩa Mose, Mbũmbanĩsya andũ mĩongo mũonza ma atumĩa ma Isilaeli, ala wĩsĩ nĩ atumĩa ma andũ, na anene kwoo; na ũimaete ĩeemanĩ ya kũmbanĩa, nĩ kana maũngame vo vamwe naku.'),
('kam', 'NUM', 11, 17, 'Nakwa ngatheea na kũneenea naku vo: na ngoosa kĩlungu kya Veva ũla wĩ nake na ngamekĩa mo; namo makakuan’ya naku mũio ũsu wa andũ, nĩ kana ndũkokue wĩ weka.'),
('kam', 'NUM', 11, 18, 'Matavye andũ, Ivathan’yei mwĩthĩwe mwĩ atheu ũnĩ, na mũkaya nyama; nũndũ nĩmũnaĩie matũnĩ ma Yeova, mũkĩmwĩa, Nũũ wĩtũnenga nyama sya ũya? Nũndũ twaĩ na ũseo kũya Misili: kwondũ wa ũu Yeova akamũnenga nyama, na mũkaya.'),
('kam', 'NUM', 11, 19, 'Mũtiiya mũthenya ũmwe, kana mĩthenya ĩlĩ, kana mĩthenya ĩtano, kana mĩthenya ĩkũmi, kana mĩthenya mĩongo ĩlĩ,'),
('kam', 'NUM', 11, 20, 'ĩndĩ mũkaya mwei mũima, kũvika yĩla ikaumĩla manyiũũnĩ menyu, na kwĩw’a tiiki nĩsyo; nũndũ nĩmwaleile Yeova ũla wĩ katĩ wenyu, na mwamũĩĩa, mũkyasya, Nĩ ũndũ wa kĩ twaumie Misili?'),
('kam', 'NUM', 11, 21, 'Na Mose asya, Andũ ala nĩ namo nĩ andũ ngili maana thanthatũ ala maendaa na maũũ; naku waĩtye, Ngamanenga nyama, maye mwei mũima.'),
('kam', 'NUM', 11, 22, 'Ndĩthya sya mbũi na malondu na ndĩthya sya ng’ombe ikoawa ũndũ woo, nĩ kana imeanĩe? Kana makũyũ onthe me ũkanganĩ makombanw’a ũndũ woo, nĩ kana mameanĩe?'),
('kam', 'NUM', 11, 23, 'Na Yeova amũkũlya Mose, Kw’oko kwa Yeova nĩkũkuvĩvĩte? Yu ũkoona ethĩwa ndeto yakwa ĩkeanĩw’a kwaku kana ti w’o.'),
('kam', 'NUM', 11, 24, 'Na Mose aumaala, na atavya andũ ndeto sya Yeova: na aumya andũ mĩongo mũonza ma atumĩa ma andũ, na amaia mathyũlũlũkĩte yĩla Ĩeema.'),
('kam', 'NUM', 11, 25, 'Na Yeova atheea mũumbĩnĩ na aneena nake, na oosa kĩlungu kya Veva ũla Mose waĩ nake, na amekĩa ala atumĩa mĩongo mũonza: na kweethĩwa, yĩla Veva wekalile ĩũlũ wamo, mathana, ĩndĩ matyaambĩla kwĩka ũu ĩngĩ.'),
('kam', 'NUM', 11, 26, 'Ĩndĩ matiala andũ elĩ mwakonĩ wa maeema, syĩtwa ya ũmwe eetawa Elitati, na syĩtwa ya ũla ũngĩ eetawa Metati: na Veva amekalĩla; maĩ ma asu ala maandĩkĩtwe, ĩndĩ matyaĩ manaenda Ĩeemanĩ; na mathanĩa mwakonĩ wa maeema.'),
('kam', 'NUM', 11, 27, 'Na kwasemba mwanake ũmwe, na atavya Mose, na amwĩa, Elitati na Metati nĩmekwathanĩa mwakonĩ wa maeema.'),
('kam', 'NUM', 11, 28, 'Na Yosua mwana wa Nuni, mũthũkũmi wa Mose, ũmwe wa andũ make anyuve, asũngĩa na amwĩa, Vwana wakwa Mose, mavate.'),
('kam', 'NUM', 11, 29, 'Na Mose amũkũlya, Wĩ na kĩwĩu nũndũ wakwa? Nenda kethĩwa andũ onthe ma Yeova nĩ athani, na kethĩwa Yeova nũmekĩa Veva wake!'),
('kam', 'NUM', 11, 30, 'Na Mose athi alika mwakonĩ wa maeema, we na atumĩa ma Isilaeli.'),
('kam', 'NUM', 11, 31, 'Na kĩuutani kyaumie vala ve Yeova kĩuutanĩte, na kyaumya ngwae ũkanganĩ, nakyo kyaitiĩla iũlũkae vakuvĩ na mwako wa maeema, ta mũendo wa mũthenya ũmwe ngalĩ ĩno na mũendo wa mũthenya ũmwe ngalĩ ĩla ĩngĩ, kũthyũlũlũka mwako wa maeema, na vakĩthimwa kuma nthĩ kũvika ĩũlũ ta mĩkono ĩlĩ.'),
('kam', 'NUM', 11, 32, 'Na andũ mookĩla mũthenya ũsu mũima, na ũtukũ mũima, na ũnĩ ũsu w’onthe, na moomban’ya ngwae: ũla wombanisye nini ombanasya sya omeli ĩkũmi: na masyanĩka maithyũlũlũkĩtye mwako wa maeema syĩthĩwe syoo ene.'),
('kam', 'NUM', 11, 33, 'O yĩla nyama syaĩ maeonĩ moo, mataitanyukĩte, ũthatu wa Yeova wamakanĩa, na Yeova akũna andũ na ũthĩn’yo mũnene.'),
('kam', 'NUM', 11, 34, 'Na syĩtwa ya vandũ vau veetwa Kivilothi‐ataava; nĩkwĩthĩwa nĩvo menzĩe nthĩ andũ ala maĩ na ĩtomo.'),
('kam', 'NUM', 11, 35, 'Kuma Kivilothi‐ataava andũ maenda kyalo kũvika Aaselothi; na mekala kũu Aaselothi.'),
('kam', 'NUM', 12, 1, 'Na Miliamu na Aluni mamũneenea Mose naĩ nũndũ wa mũndũ mũka Mũkusi ũla watwaĩte: nũndũ atwaĩte mũndũ mũka Mũkusi.'),
('kam', 'NUM', 12, 2, 'Na masya, Nĩ w’o, Yeova aneenaa na Mose e weka? Ndaaneena o naitũ? Na Yeova eew’a ũu.'),
('kam', 'NUM', 12, 3, 'Na mũndũ ũsu Mose aĩ mũuu mũno, kũvĩtũka andũ onthe ala maĩ ĩũlũ wa nthĩ.'),
('kam', 'NUM', 12, 4, 'Na kavenya o kau Yeova aneena na Mose, na Aluni, na Miliamu, Umaalai mwĩ atatũ mũthi ĩeemanĩ ya kũmbanĩa. Na asu atatũ maumaala.'),
('kam', 'NUM', 12, 5, 'Na Yeova atheea e kĩtuĩnĩ kya mũumbĩ, na aũngama mũomonĩ wa yĩla Ĩeema, na ameta Aluni na Miliamu; na me elĩ maumaala.'),
('kam', 'NUM', 12, 6, 'Nake amea, Yu ĩw’ai ndeto syakwa: ethĩwa ve mwathani katĩ wenyu, nyie Yeova ngeemanyĩthya kwake woninĩ, nganeena nake ndotonĩ.'),
('kam', 'NUM', 12, 7, 'Mũthũkũmi wakwa Mose ndailyĩ ũu; nake e na kĩthito nyũmbanĩ yakwa yonthe:'),
('kam', 'NUM', 12, 8, 'nganeenaa nake kanyw’a kwa kanyw’a, o ũtheinĩ, na ti ndetonĩ sya nthimo; na mũvw’ano wa Yeova akawona: nũndũ wa kĩ ĩndĩ mũtaneekĩa kũneenea mũthũkũmi wakwa naĩ, kũneenea Mose?'),
('kam', 'NUM', 12, 9, 'Na ũthatu wa Yeova wamakanĩa; na athi.'),
('kam', 'NUM', 12, 10, 'Na mũumbĩ wauma ĩũlũ wa Ĩeema; na, sisya, Miliamu aĩ na mangũ, mweũ ta ĩa: na Aluni amũketeea Miliamu, na, sisya, aĩ na mangũ.'),
('kam', 'NUM', 12, 11, 'Na Aluni amwĩa Mose, Ame vwana wakwa, nĩngũkwĩsũva, ndũkatwiĩe naĩ, nũndũ twĩkĩte na ũtumanu, na nũndũ twĩkĩte naĩ.'),
('kam', 'NUM', 12, 12, 'Nĩngũkwĩsũva, ndakethĩwe ta ũmwe mũkw’ũ, ũla nyunzu ya mwĩĩ nĩ mwanangĩku akyuma ĩvunĩ ya nyinyia.'),
('kam', 'NUM', 12, 13, 'Na Mose amwĩkaĩla Yeova, akĩmwĩa, Mũvosye, ame Ngai, nĩngũkwĩsũva.'),
('kam', 'NUM', 12, 14, 'Na Yeova amwĩa Mose, Ethĩwa ĩthe wake nowamũtwĩlile mata ũthyũnĩ wake, ndeĩthĩwa aisonoka mĩthenya mũonza? Navingĩwe ũtee wa mwako wa maeema mĩthenya mũonza, na ĩtina wa ũu akaetwe nthĩnĩ ĩngĩ.'),
('kam', 'NUM', 12, 15, 'Na Miliamu avingĩwa ũtee wa mwako wa maeema mĩthenya mũonza: na andũ matyaathi kyalo kũvika Miliamu aetwe nthĩnĩ ĩngĩ.'),
('kam', 'NUM', 12, 16, 'Na ĩtina wa ũu andũ mauma Aaselothi mathi kyalo, na mamba maeema moo weũnĩ wa Valani.'),
('kam', 'NUM', 13, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 13, 2, 'Tũma andũ mathi makathiane nthĩ ya Kanaani, ĩla ngũmanenga ana ma Isilaeli: ũkatũme mũndũ wa kĩla mbaĩ ya aaĩthe moo, kĩla ũmwe mũnene nthĩnĩ wamo.'),
('kam', 'NUM', 13, 3, 'Na Mose amatũma kuma weũnĩ wa Valani kwĩanana na mwĩao wa Yeova: onthe maĩ andũ ala maĩ atongoi ma ana ma Isilaeli.'),
('kam', 'NUM', 13, 4, 'Na masyĩtwa moo nĩ aa: Wa mbaĩ ya Leuveni, Samua mwana wa Nzakuli.'),
('kam', 'NUM', 13, 5, 'Wa mbaĩ ya Simeoni, Savati mwana wa Oli.'),
('kam', 'NUM', 13, 6, 'Wa mbaĩ ya Yuta, Kalevu mwana wa Yevune.'),
('kam', 'NUM', 13, 7, 'Wa mbaĩ ya Isakali, Ikali mwana wa Yosevu.'),
('kam', 'NUM', 13, 8, 'Wa mbaĩ ya Evalaimu, Osea mwana wa Nuni.'),
('kam', 'NUM', 13, 9, 'Wa mbaĩ ya Mbenyamini, Valiti mwana wa Lavu.'),
('kam', 'NUM', 13, 10, 'Wa mbaĩ ya Nzevuluni, Ngatieli mwana wa Soti.'),
('kam', 'NUM', 13, 11, 'Wa mbaĩ ya Yosevu wa mbaĩ ya Manase, Ngatiti mwana wa Susi.'),
('kam', 'NUM', 13, 12, 'Wa mbaĩ ya Ndani, Amieli mwana wa Ngemali.'),
('kam', 'NUM', 13, 13, 'Wa mbaĩ ya Aseli, Sethuli mwana wa Mikaeli.'),
('kam', 'NUM', 13, 14, 'Wa mbaĩ ya Navitali, Navi mwana wa Vovisi.'),
('kam', 'NUM', 13, 15, 'Wa mbaĩ ya Ngati, Ngeueli mwana wa Maki.'),
('kam', 'NUM', 13, 16, 'Asu nĩmo masyĩtwa ma andũ ala Mose watũmie mathi mathiane nthĩ. Na Osea mwana wa Nuni, Mose amwĩta Yosua.'),
('kam', 'NUM', 13, 17, 'Na Mose amatũma mathi kũthiana nthĩ ya Kanaani, na amea, Ambatai na nzĩa ĩno ya ngalĩ ya Ĩtheo, na ambatai mũvike nthĩ yĩ iĩma:'),
('kam', 'NUM', 13, 18, 'mwone nthĩ, ũndũ ĩilyĩ; na andũ ala matwĩe vo, ethĩwa me na vinya kana mati na vinya, ethĩwa nĩ avũthũ kana aingĩ;'),
('kam', 'NUM', 13, 19, 'na nthĩ ũndũ ĩilyĩ ĩla matwĩe, ethĩwa nĩ nzeo kana nĩ nthũku; na ndũa ila matwĩe ũndũ iilyĩ, ethĩwa matũaa myakonĩ ya maeema, kana ngomenĩ syĩ vinya;'),
('kam', 'NUM', 13, 20, 'na ũndũ nthĩ ĩilyĩ, ethĩwa nĩ nou kana nĩ mosu, ethĩwa yĩ na mĩtĩ kana ndĩĩ. Na ĩthĩwai na ũkũmbaũ mũnene, na mũiete ũsyao wa nthĩ ĩsu. Na ĩndĩ ĩvinda yĩu yaĩ ĩvinda ya nzavivũ kwambĩlĩlya kwĩw’a.'),
('kam', 'NUM', 13, 21, 'Na kwondũ wa ũu mambata, na mathiana nthĩ kuma weũ wa Nzini kũvika Leovu, kũvika ũlikĩlonĩ wa Amathi.'),
('kam', 'NUM', 13, 22, 'Na mambata ngalĩ ya Ĩtheo, na mavika Eviloni; na Aimani na Sesai na Talimai, ana ma Anaki maĩ vo. (Na ĩndĩ Eviloni nĩyakiwe myaka mũonza Nzoani ku Misili ĩtanamba kwakwa.)'),
('kam', 'NUM', 13, 23, 'Na mavika kyandanĩ kya Esikoli, na matema vo mũkoi wĩ na kĩtũngo kĩmwe kya nzavivũ, na andũ elĩ makĩkua na mũtĩ makwatanĩe; na maete o na makũngũmanga na makũyũ.'),
('kam', 'NUM', 13, 24, 'Vandũ vau veetwa kyanda kya Esikoli, nũndũ wa kĩtũngo kĩla ana ma Isilaeli matemie vo.'),
('kam', 'NUM', 13, 25, 'Na matukũ mĩongo ĩna mathela masyoka kuma kũthiana nthĩ.'),
('kam', 'NUM', 13, 26, 'Na mathi na mavika vala ve Mose, na Aluni, na ũmbano w’onthe wa ana ma Isilaeli, kũvika Katesi weũnĩ wa Valani; na mamatavya ũvoo, vamwe na ũmbano w’onthe, na mamon’ya ũsyao wa nthĩ ĩsu.'),
('kam', 'NUM', 13, 27, 'Na mamũtavya, makĩmwĩa, Twavika nthĩ ĩla watũtũmie; na nĩ w’o, yusũĩte ĩia na ũkĩ wa nzũkĩ; na ũũ nĩ ũsyao wayo.'),
('kam', 'NUM', 13, 28, 'Ĩndĩ andũ ala matwĩe nthĩ ĩsu me na vinya, na ndũa nithyũlũlũkĩtwe nĩ maũvai, na nĩ nene mũno: na ũndũ ũngĩ twoonie ana ma Anaki kw’o.'),
('kam', 'NUM', 13, 29, 'Amaleki nũtwĩe nthĩ ya ngalĩ ya Ĩtheo: na Mũititi na Mũyevusi na Mũamoli matwĩe nthĩ yĩ iĩma; na Mũkanaani nũtwĩe vakuvĩ na ũkanga, na ũtee wa ũsĩ wa Yolotani.'),
('kam', 'NUM', 13, 30, 'Na Kalevu avindĩthya andũ me mbee wa Mose, na amea, Twambatei oyu, na kũmĩmesya: nũndũ nĩtũtonya mũno kũmĩkĩlya vinya.'),
('kam', 'NUM', 13, 31, 'Ĩndĩ andũ ala mambatie nake masya, Tũtitonya kwambata kũkita na andũ asu; nũndũ me na vinya kwĩ ithyĩ.'),
('kam', 'NUM', 13, 32, 'Na mamaetee ana ma Isilaeli ũvoo mũthũku wa nthĩ ĩsu ĩla manathianaa, makĩmea, Nthĩ ĩla tũnangangaa tũkĩmĩthiana, nĩ nthĩ ĩla ĩthelelaa andũ ala mamĩtũaa; na andũ onthe ala twoonie vo nĩ andũ aasa mũno.'),
('kam', 'NUM', 13, 33, 'Na vo twoonie Nevilimu, ana ma Anaki, ala maumaa kwa Nevilimu; naitũ tweeyonie ta itooli, nao now’o matwonie.'),
('kam', 'NUM', 14, 1, 'Na ũmbano w’onthe wookĩlya wasya woo, na kũĩa; na andũ asu maĩa ũtukũ ũsu.'),
('kam', 'NUM', 14, 2, 'Na ana onthe ma Isilaeli mamanyungunyĩĩsya Mose na Aluni: na ũmbano w’onthe wamea, Twenda kethĩwa twakw’ĩĩe nthĩ ya Misili! Kana twenda kethĩwa twakw’ĩĩe weũnĩ ũũ!'),
('kam', 'NUM', 14, 3, 'Na nũndũ wa kĩ Yeova watũetie nthĩ ĩno, tũvalũkw’e na ũvyũ? Iveti sitũ na syana sitũ nini ikeethĩwa syĩ syĩndũ sya mbuta: ti kavaa kwitũ tũsyoke Misili?'),
('kam', 'NUM', 14, 4, 'Na maneenan’ya, Twie ũmwe ethĩwe kavuteni, na tũkĩsyoka Misili.'),
('kam', 'NUM', 14, 5, 'Nĩvo ĩndĩ Mose na Aluni mavalũkile na mothyũ moo mbee wa ũmbano w’onthe ũla wũmbanĩte wa ana ma Isilaeli.'),
('kam', 'NUM', 14, 6, 'Na Yosua mwana wa Nuni na Kalevu mwana wa Yevune, ala maĩ na asu ala mathianie nthĩ, matembũanga ngũa syoo:'),
('kam', 'NUM', 14, 7, 'na maneena na ũmbano w’onthe wa ana ma Isilaeli, makyasya, Nthĩ, ĩla tũnangangaa tũkĩmĩthiana, nĩ nthĩ nzeo mũno.'),
('kam', 'NUM', 14, 8, 'Ethĩwa Yeova nĩwendeeaw’a nĩ ithyĩ, akatũtwaa nthĩ ĩsu, na kũtũnenga yo; nthĩ ĩla yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'NUM', 14, 9, 'Ĩndĩ mũtikamũng’endee Yeova, o na mũtikakĩe andũ ma nthĩ ĩsu; nũndũ nĩo kya ũya kitũ: muunyĩ ũla melingĩtye ũla waĩ ĩũlũ woo nĩ mũvete, na Yeova e vamwe naitũ: mũikamakĩe.'),
('kam', 'NUM', 14, 10, 'Ĩndĩ ũmbano w’onthe wasya makimangwe na mavia. Na ũtheu mũtisu wa Yeova wamaumĩlĩla ana onthe ma Isilaeli ĩeemanĩ ya kũmbanĩa.'),
('kam', 'NUM', 14, 11, 'Na Yeova amwĩa Mose, Andũ aa makambũthya kũvika ĩndĩĩ? Na makalea kũndĩkĩĩa ĩvinda yĩana ata, nũndũ wa syama syonthe ila neekie katĩ wamo?'),
('kam', 'NUM', 14, 12, 'Ngamakũna na mũimũ, na kũmavata ũtĩĩwa woo, na ngakũtw’ĩkĩthya mbaĩ nene na yĩ vinya kwĩ mo.'),
('kam', 'NUM', 14, 13, 'Na Mose amwĩa Yeova, Nĩvo ĩndĩ Amisili meĩw’a ũu; nũndũ nĩwaumisye andũ aa kwoo na vinya waku;'),
('kam', 'NUM', 14, 14, 'nao makatavya andũ ala matwĩe nthĩ ĩno. Nĩmwew’ĩte kana we Yeova wĩ katĩ wa andũ aa; nũndũ we Yeova nĩwonawa ũthyũ kwa ũthyũ, na mũumbĩ waku ũũngamaa ĩũlũ woo, na nũendaa ũmatongoesye kĩtuĩnĩ kya mũumbĩ mũthenya, na kĩtũĩnĩ kya mwaki ũtukũ.'),
('kam', 'NUM', 14, 15, 'Na yu ethĩwa ũkooaa andũ aa o ta kũaa mũndũ ũmwe, nĩvo ĩndĩ mbaĩ ila syeewie nguma yaku ikaneena, ikyasya,'),
('kam', 'NUM', 14, 16, 'Nĩkwĩthĩwa Yeova ndaatonya kũtwaa andũ aa nthĩ ĩla wameavĩe, kwondũ wa ũu amoaĩa weũnĩ.'),
('kam', 'NUM', 14, 17, 'Na yu, nĩngũkũvoya, vinya wa Mwĩaĩi wĩthĩwe wĩ mũnene, kwĩanana na ũndũ waneenie, ũkyasya,'),
('kam', 'NUM', 14, 18, 'Yeova ndathataa na mĩtũkĩ, e na wingĩ wa ũseo wĩ wendo, akĩekea ũthũku na ĩvĩtyo; na ũla ũtakatw’a mũvĩtan’ya kwĩthĩwa ti mũvĩtan’ya o na ata, na akĩĩvanĩsya kwa syana ũthũku wa aaĩthe moo, kũvika nzyawa ya katatũ na ya kana.'),
('kam', 'NUM', 14, 19, 'Ekea, nĩngũkũvoya, ũthũku wa andũ aa kwĩanana na ũnene wa ũseo waku wĩ wendo, na kwĩanana na ũndũ wamaekeaa andũ aa, kuma Misili kũvika o na yu.'),
('kam', 'NUM', 14, 20, 'Na Yeova amwĩa, Nĩnamaekea kwĩanana na ndeto yaku:'),
('kam', 'NUM', 14, 21, 'ĩndĩ nĩ w’o, o tondũ nĩ thayũ, na o tondũ nthĩ yonthe ĩkausũwa nĩ ndaĩa ya Yeova;'),
('kam', 'NUM', 14, 22, 'nĩkwĩthĩwa andũ asu onthe ala moonie ũnene wakwa, na syama syakwa, ila neekie Misili na weũnĩ, ĩndĩ mandatie mavinda aa ĩkũmi, na matyaaĩthukĩĩsya wasya wakwa;'),
('kam', 'NUM', 14, 23, 'vate ndĩi matikona nthĩ ĩla nameavĩe aaĩthe moo, o na vai ũmwe wa asu ala mambũthisye ũkamyona:'),
('kam', 'NUM', 14, 24, 'ĩndĩ mũthũkũmi wakwa Kalevu, nĩkwĩthĩwa aĩ na veva ũngĩ nthĩnĩ wake, na nũmbikĩlĩte vyũ, ũsu ngamũtwaa nthĩ vala walikile, na ĩkeethĩwa yĩ ng’ũndũ ya ũsyao wake.'),
('kam', 'NUM', 14, 25, 'Na ĩndĩ Mũamaleki na Mũkanaani matũaa mwandanĩ: ũnĩ ĩthyũũei na mũithi weũnĩ na nzĩa ĩelete Ũkanganĩ Mũtene.'),
('kam', 'NUM', 14, 26, 'Na Yeova aneena na Mose na Aluni, aimea,'),
('kam', 'NUM', 14, 27, 'Ngoomĩĩsya ũmbano ũũ mũthũku ũla ũnyungunyĩĩasya ĩvinda yĩana ata? Nĩneewie monyungunyĩsyo ma ana ma Isilaeli ala manyungunyĩĩasya.'),
('kam', 'NUM', 14, 28, 'Matavyei, O tondũ nĩ thayũ, easya ũu Yeova, nĩ w’o, o tondũ mũneenete matũnĩ makwa, ngamwĩka o ta ũu:'),
('kam', 'NUM', 14, 29, 'simba syenyu ikavalũka weũnĩ ũũ; na inyw’onthe ala mũtalilwe, kwĩanana na ũtalo wenyu w’onthe, ala mũvikĩtye myaka mĩongo ĩlĩ na mbee, ala mũnyungunyĩĩasya,'),
('kam', 'NUM', 14, 30, 'nĩ w’o mũtikalika nthĩ ĩsu, ĩla neeavĩe ngamwĩkalya vo, ate o Kalevu mwana wa Yevune, na Yosua mwana wa Nuni.'),
('kam', 'NUM', 14, 31, 'Ĩndĩ syana syenyu nini, ila mwaisye ikeethĩwa syĩndũ sya mbuta, isu nĩsyo ngaitwaa vo, nasyo ikamanya nthĩ ĩla mũleete.'),
('kam', 'NUM', 14, 32, 'Ĩndĩ ũndũ wenyu, simba syenyu ikavalũka weũnĩ ũũ.'),
('kam', 'NUM', 14, 33, 'Na syana syenyu ikeethĩwa angangi weũnĩ myaka mĩongo ĩna, na ikakua mũio wa ũmalwaya wenyu, kũvika yĩla simba syenyu ikanangĩkĩa weũnĩ.'),
('kam', 'NUM', 14, 34, 'O ta ũtalo wa mĩthenya ĩla mũnathianie nthĩ, o mĩthenya mĩongo ĩna, mwaka vandũ va kĩla mũthenya, mũkakua ũthũku wenyu, o myaka mĩongo ĩna, na mũkamanya kũtaanĩsya nakwa ũndũ kũilyĩ.'),
('kam', 'NUM', 14, 35, 'Nyie, Yeova, nĩneenete, nditĩa kwĩka ũu ũmbano ũũ w’onthe mũthũku, ũla wambũmbanĩe: makanangĩkĩa weũnĩ ũũ, na nĩvo makakw’ĩa.'),
('kam', 'NUM', 14, 36, 'Na andũ, ala Mose watũmie kũthiana nthĩ, ala masyokie, na matuma ũmbano w’onthe ũmũnyungunyĩĩsya, kwondũ wa kũete ũvoo mũthũku ũndũ wa nthĩ,'),
('kam', 'NUM', 14, 37, 'o andũ asu ala maetie ũvoo mũthũku wa nthĩ, makwie na ũ mũimũ Yeova ene.'),
('kam', 'NUM', 14, 38, 'Ĩndĩ Yosua mwana wa Nuni, na Kalevu mwana wa Yevune, nĩmo mekalile thayũ, ma andũ asu ala maendie kũthiana nthĩ.'),
('kam', 'NUM', 14, 39, 'Na Mose atavya ana onthe ma Isilaeli ndeto isu: na andũ maĩa mũno.'),
('kam', 'NUM', 14, 40, 'Na mookĩla kĩoko tene, na mambata mũtumbĩnĩ wa kĩĩma, makyasya, Sisya, twĩ vaa, na tũkambata tũthi vandũ vala Yeova watwathie: nũndũ nĩtwavĩtisye.'),
('kam', 'NUM', 14, 41, 'Na Mose amea, Yu nũndũ wa kĩ mũũvĩtya mwĩao wa Yeova, nũndũ ũndũ ũsu ndũkaathimĩka?'),
('kam', 'NUM', 14, 42, 'Mũtikambate, nũndũ Yeova nde vamwe nenyu; mũikakũnwe mũvalũkw’e nthĩ nĩ amaitha menyu.'),
('kam', 'NUM', 14, 43, 'Nũndũ Mũamaleki na Mũkanaani me vo mbee wenyu, nenyu mũkavalũkw’a na ũvyũ: nĩkwĩthĩwa nĩmũsyokete na ĩtina mũkaeka kũmũatĩĩa Yeova, kwondũ wa ũu Yeova ndakethĩwa vamwe nenyu.'),
('kam', 'NUM', 14, 44, 'Ĩndĩ maema na mambata mũtumbĩnĩ wa kĩĩma: ĩndĩ ĩsandũkũ ya ũtianĩo ya Yeova yĩtyaauma mwakonĩ wa maeema, o na Mose nake ndaauma.'),
('kam', 'NUM', 14, 45, 'Nĩvo ĩndĩ Mũamaleki na Mũkanaani ala matwĩe kĩĩmanĩ kyu matheeie, na mamakũna na mamavalũkya nthĩ, o na kũvika Olima.'),
('kam', 'NUM', 15, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 15, 2, 'Neena na ana ma Isilaeli, na ũmatavye, Yĩla mwĩlika nthĩ ĩla mwĩtũa, ĩla nĩmũnenga,'),
('kam', 'NUM', 15, 3, 'na mũkenda kũmũthembea Yeova nthembo ĩvĩvaw’a na mwaki, nthembo ya kũvĩvw’a, kana nthembo ya kwĩanĩsya wĩvĩto, kana nthembo ya kumya na ngoo ya kwenda, kana mbokanĩ syenyu ila itw’ĩtwe sya kũmumĩsya Yeova nthembo yĩ mũuke mũseo, ya ndĩthya ya ng’ombe, kana ya mbũi na malondu;'),
('kam', 'NUM', 15, 4, 'nĩvo ĩndĩ ũla ũetae nthembo yake ũkamũthembea Yeova nthembo ya mũtu ya kĩlungu kya ĩkũmi kya eva ya mũtu mũvinyu ũvulanĩtw’e na kĩlungu kya kana kya ini ya mauta:'),
('kam', 'NUM', 15, 5, 'na kwondũ wa kĩla katena ka ĩlondu ũkaseũvye mbinyu yĩthĩwe nthembo ya kũnyuwa, kĩlungu kya kana kya ini, vamwe na nthembo ya kũvĩvw’a, kana nthembo ya kũtonywa.'),
('kam', 'NUM', 15, 6, 'Kana kwondũ wa ndũũme, ũkaseũvye nthembo ya mũtu ya ilungu ilĩ sya ĩkũmi sya eva ya mũtu mũvinyu ũvulanĩtw’e na kĩlungu kya katatũ kya ini ya mauta:'),
('kam', 'NUM', 15, 7, 'na ũndũ wa nthembo ya kũnyuwa ũkathembe kĩlungu kya katatũ kya ini ya mbinyu, yĩthĩwe mũuke mũseo kwa Yeova.'),
('kam', 'NUM', 15, 8, 'Na yĩla wĩseũvya kasalũ ka mũew’a kethĩwe nthembo ya kũvĩvw’a, kana kethĩwe nthembo ya kũtonywa, ya kwĩanĩsya wĩvĩto, kana kethĩwe nthembo sya mũuo kwa Yeova;'),
('kam', 'NUM', 15, 9, 'nĩvo ĩndĩ wĩthembanĩsya na kala kasalũ nthembo ya mũtu ya ilungu itatũ sya ĩkũmi sya eva ya mũtu mũvinyu ũvulanĩtw’e na nyunzu ya ini ya mauta:'),
('kam', 'NUM', 15, 10, 'na ũkathembe ũndũ wa nthembo ya kũnyuwa nyunzu ya ini ya mbinyu, yĩthĩwe nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'NUM', 15, 11, 'Ũu nĩw’o wĩĩkwa kwondũ wa kĩla kasalũ ka mũew’a, kana kĩla ndũũme, kana kĩla katũlũme, kana kĩla katena ka mbũi.'),
('kam', 'NUM', 15, 12, 'Kwĩanana na ũndũ syĩana ila mũkaseũvya, ũu nĩw’o mwĩĩka kĩla imwe kwĩanana na ũndũ syĩana.'),
('kam', 'NUM', 15, 13, 'Onthe ala masyaawa kwenyu makeke maũndũ asu kwĩanana na ũu, makĩthemba nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'NUM', 15, 14, 'Na ethĩwa mũeni ekalaa ũeni kwenyu, kana mũndũ o na wĩva ũla ũkethĩwa e kwenyu mosyaanĩonĩ menyu, nake enda kũthemba nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova; o tondũ inyw’ĩ mwĩkaa, nake now’o wĩĩka.'),
('kam', 'NUM', 15, 15, 'Nthĩnĩ wa ũmbano kũkeethĩwa mwamũlo ũmwe kwondũ wenyu, na kwondũ wa mũeni ũla wĩkalaa ũeni kwenyu, mwamũlo wa tene na tene mosyaanĩonĩ menyu: o tondũ mũilyĩ, ũu nĩw’o mũeni wĩĩthĩwa ailyĩ vala ve Yeova.'),
('kam', 'NUM', 15, 16, 'Kũkeethĩwa mwĩao ũmwe na ũtw’ĩo umwe kwondũ wenyu na kwondũ wa mũeni ũla wĩkalaa ũeni kwenyu.'),
('kam', 'NUM', 15, 17, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 15, 18, 'Neena na ana ma Isilaeli, na ũmatavye, Yĩla mwĩlika nthĩ ĩla nĩmũtwaĩte,'),
('kam', 'NUM', 15, 19, 'nĩvo ĩndĩ kwĩĩthĩwa, atĩ, yĩla mwĩya lĩu wa nthĩ ĩsu, mũkamũthembee Yeova nthembo ya kũkĩlw’a.'),
('kam', 'NUM', 15, 20, 'Mũkathembe kamũtũ kamwe kethĩwe nthembo ya kũkĩlw’a kuma mũtunĩ wenyu wa mbee; o tondũ mwĩkaa na nthembo ya kũkĩlw’a ya kĩvũĩonĩ, mũkamyũkĩlye o ta ũu.'),
('kam', 'NUM', 15, 21, 'Mũkanenge Yeova nthembo ya kukĩlw’a ya mũtu wenyu wa mbee mosyaanĩonĩ menyu onthe.'),
('kam', 'NUM', 15, 22, 'Na yĩla mũkavĩtya, na kũlea kũkwata mĩao ĩsu yonthe ĩla Yeova wamũtavisye Mose,'),
('kam', 'NUM', 15, 23, 'o maũndũ onthe ala Yeova wamwĩaĩe na kanyw’a wa Mose, kuma mũthenya ũla Yeova weaie, o na ĩtina wa ũu mosyaanĩonĩ menyu onthe;'),
('kam', 'NUM', 15, 24, 'nĩvo ĩndĩ kũkethĩwa, ethĩwa kweekiwe kwa kũlea kũmanya, ũmbano ũtesĩ, kana ũmbano w’onthe ũkathembanĩsya kasalũ kamwe kethĩwe nthembo ya kũvĩvw’a, yĩ mũuke mũseo kwa Yeova, na nthembo ya mũtu ya kũthembanĩsya nako, na nthembo ya kũnyuwa ya kũthembanĩsya nako, kwĩanana na ũtw’ĩo, na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ.'),
('kam', 'NUM', 15, 25, 'Na mũthembi akathemba nthembo ya wĩw’anĩthyo kwondũ wa ũmbano w’onthe wa ana ma Isilaeli, na makaekewa; nĩkwĩthĩwa kweekiwe kwa kũlea kũmanya, namo maetie nthembo yoo, o nthembo ya kũmũvĩvĩsya Yeova na mwaki, na nthembo yoo kwondũ wa naĩ kwa Yeova kwondũ wa kũlea kũmanya kwoo:'),
('kam', 'NUM', 15, 26, 'na ũmbano w’onthe wa ana ma Isilaeli ũkaekewa, na mũeni ũla wĩkalaa ũeni katĩ woo: nũndũ kwa andũ asu onthe ũndũ ũsu weekiwe kwa kũlea kũmanya.'),
('kam', 'NUM', 15, 27, 'Na ethĩwa mũndũ ũmwe akavĩtya ateũmanya, nĩvo ĩndĩ wĩthemba mbaika ya mwaka ũmwe yĩthĩwe nthembo kwondũ wa naĩ.'),
('kam', 'NUM', 15, 28, 'Na mũthembi akathemba nthembo ya wĩw’anĩthyo kwondũ wa mũndũ ũla ũnũũvĩtya, yĩla wĩmũvĩtanĩsya Yeova ateũmanya, amwĩw’anĩthye; na akaekewa.'),
('kam', 'NUM', 15, 29, 'Mũkeethĩwa na mwĩao ũmwe ũndũ wa ũla wĩkaa ũndũ o na wĩva ateũmanya, ũndũ wa ũla wasyaĩwe nthĩ yenyu ananĩ ma Isilaeli, na ũndũ wa mũeni ũla wĩkalaa ũeni kwoo.'),
('kam', 'NUM', 15, 30, 'Ĩndĩ mũndũ ũla wĩkaa ũndũ na ngũlũ, ethĩwa nĩ mũndũ ũla wasyaĩwe nthĩ yenyu kana mwĩkali wa ũeninĩ, ũsu aumĩte Yeova; na mũndũ ũsu akavetwa andũnĩ make.'),
('kam', 'NUM', 15, 31, 'Nĩkwĩthĩwa nũvũthĩtye ndeto ya Yeova, na kũtũla mwĩao wake, mũndũ ũsu akavetwa vyũ; ũthũku wake ũkeethĩwa ĩũlũ wake.'),
('kam', 'NUM', 15, 32, 'Na yĩla ana ma Isilaeli maĩ weũnĩ, moona mũndũ aikolan’ya ngũ mũthenya wa savato.'),
('kam', 'NUM', 15, 33, 'Na ala mamwonie aikolan’ya ngũ mamũtwaa vala ve Mose na Aluni, na ũmbano w’onthe.'),
('kam', 'NUM', 15, 34, 'Na mamwĩkĩa ũsũvĩonĩ, nĩkwĩthĩwa kũtyaĩ kũnamba ũneenw’a ũndũ wĩĩkwa.'),
('kam', 'NUM', 15, 35, 'Na Yeova amwĩa Mose, Mũndũ, ũsu ndatĩa kũawa: ũmbano w’onthe ũkamũkimangĩe na mavia ũtee wa mwako wa maeema.'),
('kam', 'NUM', 15, 36, 'Na ũmbano w’onthe wamũtwaa ũtee wa mwako wa maeema, na wamũkimanga na mavia akw’a; o tondũ Yeova weaĩe Mose.'),
('kam', 'NUM', 15, 37, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 15, 38, 'Neena na ana ma Isilaeli, na matavye meseũvĩsye manyenze motiivonĩ ma ngũa syoo mosyaanĩonĩ moo onthe, na mekĩe manyenzenĩ ma kĩla ũtiivo ũlii wa vuluu:'),
('kam', 'NUM', 15, 39, 'naw’o ũkeethĩwa kwenyu manyenze, nĩ kana mũtonye kũmasiasya, na kũlilikanaa mĩao yonthe ya Yeova, na kũmĩkaa: na nĩ kana mũtikaatĩĩe ngoo syenyu ene na metho menyu ene, ala mwamaatĩĩaa na kwĩkaa ũmalwaya namo;'),
('kam', 'NUM', 15, 40, 'nĩ kana mũlilikanae na kwĩkaa mĩao yakwa yonthe, na mwĩthĩwe atheu kwa Ngai wenyu.'),
('kam', 'NUM', 15, 41, 'Ninyie Yeova Ngai wenyu, ũla wamumisye nthĩ ya Misili, nĩthĩwe Ngai wenyu: ninyie Yeova Ngai wenyu.'),
('kam', 'NUM', 16, 1, 'Na ĩndĩ Kola, mwana wa Isali, mwana wa Koathi, mwana wa Livai, vamwe na Ndathani na Avilamu, ana ma Eliavu, na Oni, mwana wa Velethi, ana ma Leuveni, moosa andũ:'),
('kam', 'NUM', 16, 2, 'na mookĩla mathi vala ve Mose, vamwe na ana amwe ma Isilaeli, anene maana elĩ na mĩongo ĩtano ma ũmbano, ala meetiwe maende ũmbanonĩ, andũ me nguma;'),
('kam', 'NUM', 16, 3, 'na mamombanĩa Mose na Aluni, na mamea, Nĩtwamũkola, nũndũ ũmbano w’onthe nĩ mũtheu, kĩla ũmwe wamo, na Yeova e katĩ woo: nũndũ wa kĩ ĩndĩ mũkwĩtũlya ĩũlũ wa ũmbano wa Yeova?'),
('kam', 'NUM', 16, 4, 'Na Mose eew’a ũu, avalũka na ũthyũ wake:'),
('kam', 'NUM', 16, 5, 'na aneena na Kola na nguthu yake yonthe, akĩmea, Ũnĩ kĩoko Yeova akoonan’ya naaũ ala make na nũũ ũla mũtheu, na ũsu akamũthengeesya vakuvĩ nake: o ũla wĩnyuva akamũthengeesya vakuvĩ nake.'),
('kam', 'NUM', 16, 6, 'Ĩkai ũũ: we Kola, na inyw’ĩ ma nguthu yake yonthe, osai itoeesya;'),
('kam', 'NUM', 16, 7, 'nokĩkĩa mwaki nthĩnĩ wasyo, nokĩkĩa ũvani ĩũlũ wasyo vu mbee wa Yeova ũnĩ: na kũkeethĩwa atĩ mũndũ ũla Yeova wĩnyuva, nĩwe wĩĩthĩwa e mũtheu: nĩtwamũkola, inyw’ĩ ana ma Livai.'),
('kam', 'NUM', 16, 8, 'Na Mose amwĩa Kola, Ĩthukĩĩsyei yu, inyw’ĩ ana ma Livai:'),
('kam', 'NUM', 16, 9, 'nĩmũkwona nĩ ũndũ ũnini kana Ngai wa Isilaeli nũmũvathĩte inyw’ĩ kũmumya ũmbanonĩ wa Isilaeli, amũete vakuvĩ nake, mũthũkũmae wĩa wa wĩkalo wa Yeova, na kũũngamaa mbee wa ũmbano mũmathũkũmae;'),
('kam', 'NUM', 16, 10, 'na ĩngĩ kana akũete vakuvĩ, na ana‐a‐ĩthe maku onthe ana ma Livai vamwe naku? Nenyu nĩmũkwenda ũthembi naw’o?'),
('kam', 'NUM', 16, 11, 'Kwondũ wa ũu we na nguthu yaku yonthe nĩmũmũmbanĩe Yeova: na Aluni, nĩwe ũũ ũndũ mũmũnyungunyĩĩsya?'),
('kam', 'NUM', 16, 12, 'Na Mose atũmana Ndathani na Avilamu, ana ma Eliavu, metwe; na masya, Tũtiũka:'),
('kam', 'NUM', 16, 13, 'nĩ ũndũ ũnini atĩ nĩwatumisye nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, ũtũaĩe weũnĩ, ĩndĩ vamwe na ũu wĩtw’ĩĩa mwene wĩthĩwe mũnene ĩũlũ waitũ?'),
('kam', 'NUM', 16, 14, 'O na mbee wa ũu ndwaatũtwaa nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, kana kũtũnenga ũtiĩwa wa mĩũnda na mĩũnda ya nzavivũ: naku nũkwenda kũtonya metho ma andũ aa? Tũtiũka.'),
('kam', 'NUM', 16, 15, 'Na Mose athilĩka, na amwĩa Yeova, Ndũketĩkĩle nthembo yoo: ndyaamavuta ĩng’oi yĩmwe yoo, o na ndyaamwĩka ũmwe wamo ũthũku.'),
('kam', 'NUM', 16, 16, 'Na Mose amwĩa Kola, We na nguthu yaku yonthe mũkethĩwe mbee wa Yeova, we, namo, na Aluni, ũnĩ:'),
('kam', 'NUM', 16, 17, 'na kĩla mũndũ wenyu natwae kĩtoeesya kyake, na kwĩkĩa ũvani ĩũlũ wasyo, na kĩla mũndũ naete mbee wa Yeova kĩtoeesya kyake, itoeesya maana elĩ na mĩongo ĩtano; we naku, na Aluni, kĩla ũmwe kĩtoeesya kyake.'),
('kam', 'NUM', 16, 18, 'Na kĩla mũndũ oosa kĩtoeesya kyake, na eekĩa mwaki nthĩnĩ wakyo, na eekĩa ũvani ĩũlũ waw’o, na maũngama mũomonĩ wa ĩeema ya kũmbanĩa vamwe na Mose na Aluni.'),
('kam', 'NUM', 16, 19, 'Na Kola oombanĩsya ũmbano w’onthe mũomonĩ wa ĩeema ya kũmbanĩa: na ũtheu mũtisu wa Yeova waumĩlĩla ũmbano w’onthe.'),
('kam', 'NUM', 16, 20, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'NUM', 16, 21, 'Ĩvathei inyw’ĩ mume ũmbanonĩ ũũ, nĩ kana nĩmamine o ĩmwe.'),
('kam', 'NUM', 16, 22, 'Na mavalũka na mothyũ moo, na masya, Ame Ngai, Ngai wa maveva ma mĩĩ yonthe, mũndũ ũmwe eeka naĩ, naku ũkathilĩkĩla ũmbano w’onthe?'),
('kam', 'NUM', 16, 23, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 16, 24, 'Neena na ũmbano, ũkĩwĩa, Ũkĩlai, mume vakuvĩ na wĩkalo wa Kola, na Ndathani, na Avilamu.'),
('kam', 'NUM', 16, 25, 'Na Mose ookĩla na amaendea Ndathani na Avilamu; na atumĩa ma Isilaeli maatĩanĩa nake.'),
('kam', 'NUM', 16, 26, 'Nake aneena na ũmbano, akĩwĩa, Nĩngũmwĩsũva, umai maeemanĩ ma andũ aa athũku, na mũikakiite kĩndũ o na kĩva kyoo, mũikese kwanangwa naĩnĩ syoo syonthe.'),
('kam', 'NUM', 16, 27, 'Kwondũ wa ũu mookĩla kuma vakuvĩ na wĩkalo wa Kola, na Ndathani, na Avilamu, ngalĩ syonthe: na Ndathani na Avilamu maumaala, na maũngama mũomonĩ wa maeema moo, me na iveti syoo, na ana moo, na syana syoo nini.'),
('kam', 'NUM', 16, 28, 'Na Mose amea, Kwondũ wa ũũ mũkamanya kana Yeova nũndũmĩte nĩke mawĩa aa onthe; nũndũ ndimekĩte kwondũ wa kũsũanĩa kwakwa mwene.'),
('kam', 'NUM', 16, 29, 'Ethĩwa andũ aa nĩmeũkw’a kĩkw’ũ kĩla kĩkusawa nĩ andũ onthe, kana ethĩwa nĩmeũkwatwa nĩ maũndũ o tondũ andũ onthe makwatawa nĩmo; nĩvo ĩndĩ Yeova ndaandũma.'),
('kam', 'NUM', 16, 30, 'Ĩndĩ ethĩwa Yeova akeeka ũndũ weũ, na nthĩ ĩkathamya kanyw’a wayo, na kũmamelya, vamwe na syonthe ila me nasyo, na matheea me thayũ Seoli; nĩvo ĩndĩ mwĩmanya kana andũ aa mamũvũthĩtye Yeova.'),
('kam', 'NUM', 16, 31, 'Na kweethĩwa, aimina kũneena ndeto isu syonthe, nthĩ vala maũngamĩte yaatũka;'),
('kam', 'NUM', 16, 32, 'na nthĩ yaathamya kanyw’a wayo, na yamamelya, vamwe na andũ ma nyũmba syoo, o na andũ onthe ala maĩ na Kola, na syĩndũ syoo syonthe.'),
('kam', 'NUM', 16, 33, 'Kwondũ wa ũu mo, na onthe ala maĩ namo, nĩmatheeie me thayũ Seoli: na nthĩ yamatumĩsya, namo maaa kuma ũmbanonĩ.'),
('kam', 'NUM', 16, 34, 'Na Isilaeli onthe ala mamathyũlũlũkĩte makĩa ũndũ wa kũkaya kwoo; nũndũ masya, Nthĩ ndĩkatũmelye ithyĩ.'),
('kam', 'NUM', 16, 35, 'Na mwaki wauma kwa Yeova, na wamamina andũ asu maana elĩ na mĩongo ĩtano ala matoeeasya ũvani.'),
('kam', 'NUM', 16, 36, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 16, 37, 'Neena na Eleasali mwana wa mũthembi, Aluni, aumye itoeesya mwakinĩ, naku nyaĩĩkya mwaki na ku; nũndũ syo nĩ ntheu,'),
('kam', 'NUM', 16, 38, 'o itoeesya isu sya andũ asu athe ala mavĩtĩsye mathayũ moo ene, na imandwe mũno ikavũtha syĩthĩwe kĩndũ kya kũvw’ĩka kĩthembeo: nũndũ nĩmainenganĩte vala ve Yeova: kwondũ wa ũu nĩ ntheu; nasyo ikeethĩwa wonan’yo kwa ana ma Isilaeli.'),
('kam', 'NUM', 16, 39, 'Na mũthembi Eleasali oosa itoeesya isu sya ũthuku, ila andũ ala mavĩviwe mainenganie; na maimanda syĩthĩwe sya kũvw’ĩka kĩthembeo:'),
('kam', 'NUM', 16, 40, 'syĩthĩwe syĩ ũlilikan’yo kwa ana ma Isilaeli, nĩ kana mũeni o na wĩva, ũla ũte wa ũsyao wa Aluni, ndakathengee atoeesye ũvani vala ve Yeova; ndakethĩwe ailyĩ ta Kola, na ta nguthu vake: o tondũ Yeova waneenie nake na kanyw’a wa Mose.'),
('kam', 'NUM', 16, 41, 'Ĩndĩ ũnĩ ũsu ũmbano w’onthe wa ana ma Isilaeli mamanyungunyĩĩsya Mose na Aluni, makĩmea, Inyw’ĩ nĩmũnooaie andũ ma Yeova.'),
('kam', 'NUM', 16, 42, 'Na kweethĩwa, yĩla ũmbano wamombanĩe Mose na Aluni, masisya kwelekela ĩeemanĩ ya kũmbanĩa: na, sisya, ũla mũumbĩ wayĩvw’ĩka, na ũtheu mũtisu wa Yeova wooneka.'),
('kam', 'NUM', 16, 43, 'Na Mose na Aluni maenda ngalĩ ya mbee ya ĩeema ya kũmbanĩa'),
('kam', 'NUM', 16, 44, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 16, 45, 'Ũkĩlai mume ũmbanonĩ ũũ, nĩ kana nĩmanange o ĩmwe. Nao mavalũka na mothyũ moo.'),
('kam', 'NUM', 16, 46, 'Na Mose amwĩa Aluni, Osa kĩtoeesya kyaku, nokĩkĩa mwaki nthĩnĩ wakyo kĩthembeonĩ, nokia ũvani ĩũlũ waw’o, ũkakue mĩtũkĩ vala ve ũmbano, ũkathembe nthembo ya wĩw’anĩthyo kwondũ woo: nũndũ ũthilĩku nĩwumĩte kwa Yeova; mũimũ nĩwambĩlĩlw’e.'),
('kam', 'NUM', 16, 47, 'Na Aluni oosa o tondũ Mose waneenie, na asemba nthĩnĩ wa ũmbano; na, sisya, mũimũ waĩ ũnambĩlĩlya andũnĩ: nake eekĩa ũvani, na athemba nthembo ya wĩw’anĩthyo kwondũ wa andũ asu.'),
('kam', 'NUM', 16, 48, 'Na aũngama katĩ wa ala akw’ũ na ala maĩ thayũ; na mũimũ ũsu wasiĩĩwa.'),
('kam', 'NUM', 16, 49, 'Na ĩndĩ ala makwie nĩ ũ mũimũ maĩ ngili ĩkũmi na inya na maana mũonza, eka ala makwie ũndũ wa ũvoo wa Kola.'),
('kam', 'NUM', 16, 50, 'Na Aluni asyoka vala ve Mose mũomonĩ wa ĩeema ya kũmbanĩa: na mũimũ wasiĩĩwa.'),
('kam', 'NUM', 17, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 17, 2, 'Neena na ana ma Isilaeli, na osa ndata kwoo, ĩmwe ya kĩla nyũmba ya aaĩthe, ya anene moo onthe kwĩanana na nyũmba sya aaĩthe moo, o ndata ĩkũmi na ilĩ: andĩka syĩtwa ya kĩla mũndũ ndatanĩ yake.'),
('kam', 'NUM', 17, 3, 'Na ũkaandĩke syĩtwa ya Aluni ndatanĩ ya Livai; nũndũ kũkeethĩwa ndata ĩmwe ya kĩla mũtongoi wa nyũmba sya aaĩthe moo.'),
('kam', 'NUM', 17, 4, 'Na ũkasia ĩeemanĩ va kũmbanĩa ngalĩ ya mbee ya ĩsandũkũ ya ũkũsĩ, vala nĩkomanĩaa nenyu.'),
('kam', 'NUM', 17, 5, 'Na kũkeethĩwa, kana ndata ya mũndũ ũla nĩnyuva ĩkeethongoosya: na ngamina kwakwa monyungunyĩsyo ma ana ma Isilaeli, ala makũnyungunyĩĩasya.'),
('kam', 'NUM', 17, 6, 'Na Mose aneena na ana ma Isilaeli; na anene moo onthe mamũnenga ndata, ĩmwe ya kĩla mũnene, kwĩanana na nyũmba sya aaĩthe moo, o ndata ĩkũmi na ilĩ: na ndata ya Aluni yaĩ vamwe na ndata syoo.'),
('kam', 'NUM', 17, 7, 'Na Mose aia ndata vala ve Yeova ĩeemanĩ ya ũkũsĩ.'),
('kam', 'NUM', 17, 8, 'Na kweethĩwa ũnĩ ũsu, Mose alika ĩeemanĩ ya ũkũsĩ; na, sisya, ndata ya Aluni ĩla yaĩ ya nyũmba ya Livai yaĩ nthongoou, na kũete wenze, na yalaũka malaa, na yasyaa malosi meũ.'),
('kam', 'NUM', 17, 9, 'Na Mose aumaalya nza ndata syonthe kuma vala ve Yeova na amatwaĩa ana onthe ma Isilaeli: na masisya, na kĩla mũndũ oosa ndata yake.'),
('kam', 'NUM', 17, 10, 'Na Yeova amwĩa Mose, Tũnga ndata ya Aluni ngalĩ ya mbee ya ĩsandũkũ ya ũkũsĩ, ĩsũvĩwe yĩthĩwe wonan’yo wa kũlilikan’ya ana ma ũng’endu; nĩ kana ũmine kũnyungunyĩsya kwoo kũla manyungunyĩĩasya, matikakw’e.'),
('kam', 'NUM', 17, 11, 'Na Mose eeka ũu: o tondũ Yeova wamwĩaĩe, nĩw’o wekie.'),
('kam', 'NUM', 17, 12, 'Na ana ma Isilaeli maneena na Mose, makĩmwĩa, Sisya, nĩtũũkw’a, ithyĩ nĩtũkwaa, ithyonthe nĩtũkwaa.'),
('kam', 'NUM', 17, 13, 'Kĩla mũndũ ũla ũnũũthengeea, ũla ũnũũthengeea vakuvĩ na wĩkalo wa Yeova, nũnũũkw’a; kaĩ, nĩtũũthela ithyonthe?'),
('kam', 'NUM', 18, 1, 'Na Yeova amwĩa Aluni, We na ana maku na nyũmba ya aaĩthe maku vamwe naku mũkakua ũthũku wa vala vandũ vatheu; na we na ana maku vamwe naku mũkakua ũthũku wa ũthembi wenyu.'),
('kam', 'NUM', 18, 2, 'Na ana‐a‐ĩthe maku nao, mbaĩ ya Livai, mbaĩ ya ĩthe waku, mathengeesye methĩwe vakuvĩ naku, makwatanw’e vamwe naku, na ũkũthũkũmaa: ĩndĩ we na ana maku vamwe naku mũkeethĩawa vu mbee wa ĩeema ya ũkũsĩ.'),
('kam', 'NUM', 18, 3, 'Namo makasũvĩaa wĩaĩo waku, na wĩaĩo wa Ĩeema yonthe: no matikathengeee mĩio ya vala vandũ vatheu o na kĩthembeo, matikakw’e, mo, o nenyu.'),
('kam', 'NUM', 18, 4, 'Na makakwatanw’a naku, na kũsũvĩaa wĩaĩo wa ĩeema ya kũmbanĩa, kwondũ wa ũthũkũmi w’onthe wa Ĩeema: na mũeni ndakamũthengeee inyw’ĩ.'),
('kam', 'NUM', 18, 5, 'Na mũkasũvĩaa wĩaĩo wa vala vandũ vatheu, na wĩaĩo wa kĩthembeo; kũikethĩwe ĩngĩ ũthilĩku ĩũlũ wa ana ma Isilaeli'),
('kam', 'NUM', 18, 6, 'Na nyie, sisya, nĩnoosie ana‐a‐ĩthe menyu Alivai kũmaumya nthĩnĩ wa ana ma Isilaeli: kwenyu andũ asu nĩ mũthĩnzĩo wanengĩwe Yeova, mathũkũmae wĩa wa ĩeema ya kũmbanĩa.'),
('kam', 'NUM', 18, 7, 'Na we na ana maku vamwe naku makasũvĩaa ũthembi wenyu kwondũ wa kĩla ũndũnĩ wa kĩthembeo, na kwondũ wa kĩla kĩ nthĩnĩ wa tũtũ; na mũkathũkũmaa: nĩngũmũnenga ũthembi wĩthĩwe ũthũkũmi wa mũthĩnzĩo; na mũeni ũla wĩthengeea mũvaka oawe.'),
('kam', 'NUM', 18, 8, 'Na Yeova amwĩa Aluni, Nyie, sisya, nĩkũnengete wĩaĩo wa kũsũvĩaa nthembo syakwa sya kũkĩlw’a, o syĩndũ syonthe ivathĩtwe sya ana ma Isilaeli; nĩkũnengete we na ana maku kwondũ wa kwĩtĩkĩw’a mauta, mwĩao wa tene na tene.'),
('kam', 'NUM', 18, 9, 'Syĩndũ ii nĩsyo ikeethĩwa syaku nthĩnĩ wa syĩndũ ntheu mũno mbee, ila itialĩtw’e itavĩvĩtw’e na mwaki: kĩla kĩthembeawa nĩo, o kĩla nthembo yoo ya mũtu, na kĩla nthembo yoo kwondũ wa naĩ, na kĩla nthembo yoo kwondũ wa ĩvĩtyo, ila makanthembea, ikeethĩwa syĩ ntheu mũno kwondũ waku we na kwondũ wa ana maku.'),
('kam', 'NUM', 18, 10, 'Ũkaya syĩndũ ntheu mũno mbee; kĩla mũndũ mũũme akaiya: ikeethĩwa syĩ ntheu kwaku.'),
('kam', 'NUM', 18, 11, 'Na kĩĩ nĩ kyaku: nthembo ya kũkĩlw’a ya mũthĩnzĩo woo, o nthembo syonthe sya kũvyũlw’a sya ana ma Isilaeli; ii nĩnĩkũnengete we, na ana maku na eĩtu maku vamwe naku, kĩlungu kya tene na tene; kĩla mũndũ mũtheu nyũmbanĩ yaku akaiya.'),
('kam', 'NUM', 18, 12, 'Mauta onthe ala maseo mbee, na ngetha yonthe ya nzavivũ ĩla nzeo mbee, na ya lĩu wa mbaa ngetha, ũsyao wa mbee wa syĩndũ ila mamũnengae Yeova, isu nĩkũnengete we.'),
('kam', 'NUM', 18, 13, 'Mosyao ma mbee meũ ma kĩla kĩndũ kĩ nthĩ yoo, ala mamũeteae Yeova, makeethĩwa me maku; kĩla mũndũ mũtheu nyũmbanĩ yaku, akamaya.'),
('kam', 'NUM', 18, 14, 'Kĩla kĩndũ kĩvathĩtwe kĩthĩwe kĩtheu nthĩnĩ wa Isilaeli kĩkeethĩwa kyaku.'),
('kam', 'NUM', 18, 15, 'Kyonthe kĩla kyambaa kuma ĩvunĩ ya nyinyia kya mĩĩ yonthe, kĩla memũnenga Yeova, mũndũ o na nyamũ kĩkeethĩwa kyaku: ĩndĩ ĩkithathi ya mũndũ mũvaka wovosye, na ĩkithathi ya nyamũ ĩte ntheu ũkayovosye.'),
('kam', 'NUM', 18, 16, 'Na ala ma kwovow’a katĩ woo ala mavikĩtye mwei ũmwe na mbee ũkovosye, kwĩanana na ũndũ wĩmatalĩla wovosyo, na mbesa sya sekeli itano, kwĩanana na sekeli ya vala vandũ vatheu (nayo nĩ ngela mĩongo ĩlĩ).'),
('kam', 'NUM', 18, 17, 'Ĩndĩ ĩkithathi ya ng’ombe, kana ya ĩlondu, kana ya mbũi, ndũkovosye; nĩ ĩtheu: ũkaminzangĩsye nthakame yayo kĩthembeonĩ na kũvĩvya mathunya mayo methĩwe nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'NUM', 18, 18, 'Na nyama syayo ikeethĩwa syaku, o ta kĩng’eng’eto kya kũvyũlw’a, na ta kũũ kwa ngalĩ ya kw’oko kwa aũme, ikeethĩwa syaku.'),
('kam', 'NUM', 18, 19, 'Nthembo syonthe sya kũkĩlw’a sya syĩndũ ntheu, ila ana ma Isilaeli mamũthembeaa Yeova, nĩngũnengete, na ana maku na eĩtu maku vamwe naku, kĩlungu kya tene na tene: nĩ ũtianĩo wa mũnyũ wa tene na tene vala ve Yeova kwondũ waku na kwondũ wa ũsyao waku vamwe naku.'),
('kam', 'NUM', 18, 20, 'Na Yeova amwĩa Aluni, Ndũkethĩwa na ũtiĩwa nthĩ yoo, o na ndũkethĩwa na kĩanda o na kĩva katĩ woo: ninyie kĩanda kyaku na ũtiĩwa waku katĩ wa ana ma Isilaeli.'),
('kam', 'NUM', 18, 21, 'Na, sisya, nao ana ma Livai nĩnĩmanengete kĩlungu kya ĩkũmi kyonthe kya Isilaeli kĩthĩwe ũtiĩwa woo, ũndũ wa ũthũkũmi woo ũla mathũkũmaa, naw’o nĩ ũthũkũmi wa ĩeema ya kũmbanĩa.'),
('kam', 'NUM', 18, 22, 'Na kuma yu ana ma Isilaeli matikathengeee ĩeema ya kũmbanĩa, maikevĩtĩthye, na kũkw’a.'),
('kam', 'NUM', 18, 23, 'Ĩndĩ Alivai makathũkũmaa wĩa wa ĩeema ya kũmbanĩa, na makakua naĩ syoo ene: ũu ũkeethĩwa mwamũlo wa tene na tene mosyaanĩonĩ maku onthe; na katĩ wa ana ma Isilaeli matikethĩwa na ũtiĩwa.'),
('kam', 'NUM', 18, 24, 'Nũndũ kĩlungu kya ĩkũmi kya ana ma Isilaeli, kĩla manenganae kĩthĩwe nthembo ya kũkĩlĩlw’a Yeova, nĩnĩmanengete Alivai kĩthĩwe ũtiĩwa woo: kwondũ wa ũu nĩmatavĩtye, Katĩ wa ana ma Isilaeli matikethĩwa na ũtiĩwa o na wĩva.'),
('kam', 'NUM', 18, 25, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 18, 26, 'Na ĩngĩ ũkaneene na Alivai, na kũmea, Yĩla inyw’ĩ mũkosa kwa ana ma Isilaeli kĩlungu kya ĩkũmi kĩla nĩmũnengete kuma kwoo kĩthĩwe ũtiĩwa wenyu, nĩvo ĩndĩ mũkathemba nthembo ya kũkĩlw’a yakyo yĩthĩwe ya Yeova, kĩlungu kya ĩkũmi kya kĩlungu kyu kya ikũmi.'),
('kam', 'NUM', 18, 27, 'Na nthembo yenyu ya kũkilw’a ĩkatalwa kwenyu ta yĩthĩwa nĩyo lĩu wa mbaa ngetha wa kĩvũĩonĩ, na ta kusũa kwa mbinyu kĩangĩonĩ kya nzavivũ.'),
('kam', 'NUM', 18, 28, 'Ũu nĩw’o mũkamũthembea Yeova nthembo ya kũlĩlw’a ya ilungu syenyu syonthe sya ĩkũmi, ila mwosaa kuma kwa ana ma Isilaeli; na nthĩnĩ wasyo mũkamũnenge mũthembi Aluni nthembo ya kũkĩlĩlw’a Yeova.'),
('kam', 'NUM', 18, 29, 'Kuma mĩthĩnzĩonĩ yenyu yonthe mũkanengane kĩla nthembo ya kũkĩlĩlw’a Yeova, kya kĩla kiseo kyonthe kyayo, o kĩlungu kĩvathitwe kĩthĩwe kĩtheu kyayo.'),
('kam', 'NUM', 18, 30, 'Kwondũ wa ũu ũkamea, Yĩla mũkokĩlya kyu kĩseo mbee kyayo, nĩvo ĩndĩ kĩkatalĩlwa kwa Alivai ta wingĩvo wa kĩvũio, na ta wingĩvo wa kĩangĩo kya nzavivũ.'),
('kam', 'NUM', 18, 31, 'Na mũkamĩya kĩla vandũ, inyw’ĩ na andũ ma nyũmba syenyu: nũndũ nĩ ĩtuvi yenyu ũndũ wa ũthũkũmi wenyu ĩeemanĩ ya kũmbanĩa.'),
('kam', 'NUM', 18, 32, 'Na mũtikakua naĩ kwondũ wayo, yĩla mwamina kũkĩlya kĩla kĩseo mbee kyayo; na mũtikavukye syĩndũ ntheu sya ana ma Isilaeli, mũtikakw’e.'),
('kam', 'NUM', 19, 1, 'Na Yeova aneena na Mose na Aluni, akĩmea,'),
('kam', 'NUM', 19, 2, 'Ũũ nĩw’o mwamũlo wa mĩao ĩla Yeova weaie, akyasya, Neena na ana ma Isilaeli, makũetee moi ndune ĩte ĩlanga, na ĩte kĩema, na ĩla ĩtaaĩkĩwa ĩsoki.'),
('kam', 'NUM', 19, 3, 'Na mũkamĩnenge mũthembi Eleasali, nake akamĩtwae ũtee wa mwako wa maeema, na mũndũ ũmwe akamyũaĩa vu mbee wa ũthyũ wake:'),
('kam', 'NUM', 19, 4, 'na mũthembi Eleasali akose nthakame yayo na kyaa kyake, na kũminzangĩsya nthakame ĩsu kwelekela ngalĩ ya mbee ya ĩeema ya kũmbanĩa maminzangĩsya mũonza.'),
('kam', 'NUM', 19, 5, 'Na mũndũ ũmwe akavĩvye moi ĩsu Eleasali asyaĩtye; kĩthuma kyayo, na nyama syayo, na nthakame yayo, vamwe na mũyoo wayo, akavĩvye:'),
('kam', 'NUM', 19, 6, 'na mũthembi akose mũtĩ wa mũkũũ, na wa ĩsovo, na langi mũtune mũno, na kwĩkya mwakinĩ ũla ũũvĩvya ĩla moi.'),
('kam', 'NUM', 19, 7, 'Nĩvo ĩndĩ mũthembi wĩthambya ngũa syake, na kũthamba mwĩĩ wake manzĩnĩ, na ĩtina wa ũu akalika mwakonĩ wa maeema, na mũthembi akeethĩwa e mũvuku kũvika wĩoo.'),
('kam', 'NUM', 19, 8, 'Na ũla wĩmĩvĩvya akathambye ngũa syake manzĩnĩ, na kũthamba mwĩĩ wake manzĩnĩ, na akeethĩwa e mũvuku kũvika wĩoo.'),
('kam', 'NUM', 19, 9, 'Na mũndũ ũla mũtheu akoke mũu wa ila moi, na kũwia ũtee wa mwako wa maeema vandũ vatheu; na ũkasũvĩwe kwondũ wa ũmbano wa ana ma Isilaeli wĩthĩwe wa kũseũvasya manzĩ ma kũthesya ũvuku: nĩ nthembo kwondũ wa naĩ.'),
('kam', 'NUM', 19, 10, 'Na ũla wĩoka mũu wa moi ĩsu akathambye ngũa syake, na kwĩthĩwa e mũvuku kũvika wĩoo; na ũu ũkethĩwa mwamũlo wa tene na tena kwa ana ma Isilaeli, na kwa mũeni ũla wĩkalaa ũeni kwoo.'),
('kam', 'NUM', 19, 11, 'Ũla ũkakiita kimba kya mũndũ o na wĩva akeethĩwa e mũvuku matukũ mũonza:'),
('kam', 'NUM', 19, 12, 'ũsu akethesya namo mũthenya wa katatũ, na mũthenya wa mũonza akeethĩwa e mũtheu: ĩndĩ ethĩwa ndeĩthesya mũthenya wa katatũ, ĩndĩ mũthenya wa mũonza ndakethĩwa e mũtheu.'),
('kam', 'NUM', 19, 13, 'O ũla ũkakiita kimba, o mwĩĩ wa mũndũ ũla ũkw’ĩte, nake ndeĩthesya mwene, nũvukasya wĩkalo wa Yeova; na mũndũ ũsu akavetwa kuma nthĩnĩ wa Isilaeli: nũndũ manzĩ asu ma kũthesya ũvuku matyaaminzangĩw’a ĩũlũ wake, akeethĩwa e mũvuku; ũvuku wake ũkeethĩwa o ĩũlũ wake.'),
('kam', 'NUM', 19, 14, 'Ũũ nĩw’o mwĩao yĩla mũndũ ũkakw’ĩa ĩeemanĩ: kĩla mũndũ ũla wĩlika ĩeemanĩ, na kĩla mũndũ ũla wĩ nthĩnĩ wa ĩeema, akeethĩwa e mũvuku matukũ mũonza.'),
('kam', 'NUM', 19, 15, 'Na kĩla kĩndũ kĩkunũe, kĩla kĩte kĩkunĩke na ngunĩko, nĩ kĩvuku.'),
('kam', 'NUM', 19, 16, 'Na mũndũ o na wĩva ũla wĩ weũnĩ ũla ũkakiita ũla woaiwe na ũvyũ, kana kimba, kana ĩvĩndĩ ya mũndũ, kana mbũa, ũsu akeethĩwa e mũvuku matukũ mũonza.'),
('kam', 'NUM', 19, 17, 'Na kwondũ wa ũla wĩ mũvuku makose mũu ũsu wa kũvĩvw’a kwa ĩla nthembo kwondũ wa naĩ; na manzĩ ala mavĩtĩte makavulanw’a naw’o ĩsaaninĩ:'),
('kam', 'NUM', 19, 18, 'na mũndũ ũte mũvuku akose mũtĩ wa ĩsovo, na kũvotya manzĩnĩ asu, na kũmaminzangĩsya ĩũlũ wa ĩeema, na mĩionĩ yonthe, na andũnĩ ala me vo, na mũndũnĩ ũla ũnakiitie yĩla ĩvĩndĩ, kana ũsu woaiwe, kana ũsu mũkw’ũ, kana mbũa:'),
('kam', 'NUM', 19, 19, 'na mũndũ mũtheu akamũminzangĩĩsye ũsu mũvuku mũthenya wa katatũ, na mũthenya wa mũonza: na mũthenya wa mũonza akamũthesya; nake akathambya ngũa syake, ina kũthamba manzĩnĩ, na akeethĩwa e mũtheu wĩoo.'),
('kam', 'NUM', 19, 20, 'Ĩndĩ mũndũ ũla ũkethĩwa e mũvuku na akalea kwĩthesya, mũndũ ũsu akavetwa kuma ũmbanonĩ, nĩkwĩthĩwa nũvukĩtye vala vandũ vatheu va Yeova: manzĩ ma kũthesya ũvuku mainaminzangĩw’a ĩũlũ wake; nake nĩ mũvuku.'),
('kam', 'NUM', 19, 21, 'Naw’o ũkeethĩwa mwamũlo wa tene na tene kwoo: na ũla ũkaminzanĩsya manzĩ ma kũthesya ũvuku akathambye ngũa syake; na ũla ũkakiita manzĩ ma kũthesya ũvuku akeethĩwa e mũvuku kũvika wĩoo.'),
('kam', 'NUM', 19, 22, 'Na kĩndũ o na kĩva kĩla mũndũ ũla wĩ mũvuku ũkakiita kĩkeethĩwa kĩvuku; na mũndũ ũla ũkakĩtiita akeethĩwa e mũvuku kũvika wĩoo.'),
('kam', 'NUM', 20, 1, 'Na ana ma Isilaeli, o ũmbano w’onthe, malika weũnĩ wa Nzini mwei wa mbee: na andũ mekala Katesi; na Miliamu akw’ĩa vo, na enzĩwa nthĩ vo.'),
('kam', 'NUM', 20, 2, 'Na vatyaĩ manzĩ ũndũ wa ũmbano: na mamombanĩa Mose na Aluni.'),
('kam', 'NUM', 20, 3, 'Na andũ matetan’ya na Mose, na maneena, makĩmwĩa, Twenda kethĩwa twakwie yĩla ana‐a‐ĩthe maitũ makw’ĩĩe vu mbee wa Yeova!'),
('kam', 'NUM', 20, 4, 'Na nũndũ wa kĩ mwaetie ũmbano wa Yeova weũnĩ ũũ, tũkw’ĩe vo, ithyĩ na ndĩthya sitũ.'),
('kam', 'NUM', 20, 5, 'Na nũndũ wa kĩ mwatwambatisye kũtumya Misili, kũtũete vandũ vaa vanthũku? Ti vandũ va kũvanda mbeũ, kana va makũyũ, kana mĩsavivũ, kana makũngũmanga; o na ĩngĩ kũiĩ manzĩ ma ũnyuwa.'),
('kam', 'NUM', 20, 6, 'Na Mose na Aluni mauma vala ve ũmbano na maenda mũomonĩ wa ĩeema ya kũmbanĩa, na mavalũka na mothyũ moo: na ũtheu mũtisu wa Yeova wamaumĩlĩla.'),
('kam', 'NUM', 20, 7, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 20, 8, 'Osa ĩla ndata, na ũmban’ya ũmbano, we, na Aluni mwana‐a‐mwenyu, na neenai na yĩla ĩvia mene, yumye manzĩ mayo; na ũkamaumĩsya manzĩ ĩvianĩ; na ĩndĩ ũkanenga ũmbano na indo syoo manzĩ ma ũnyw’a.'),
('kam', 'NUM', 20, 9, 'Na Mose oosa ĩla ndata kuma vu mbee wa Yeova, o tondũ wamwĩaĩe.'),
('kam', 'NUM', 20, 10, 'Na Mose na Aluni moombanĩsya ũmbano vu mbee wa ĩvĩa, na amea, Ĩthukĩĩsyei yu, inyw’ĩ ang’endu; nĩtũũmumĩsya manzĩ ĩvianĩ yĩĩ?'),
('kam', 'NUM', 20, 11, 'Na Mose ookĩlya kw’oko kwake, na akũna ĩvia na ndata yake kelĩ: na manzĩ maingĩ mauma, na ũmbano wanyw’a, na indo syoo.'),
('kam', 'NUM', 20, 12, 'Na Yeova amea Mose na Aluni, Nĩkwĩthĩwa mũinandĩkĩĩa, mwonan’ye methonĩ ma ana ma Isilaeli atĩ nĩ mũtheu, kwondũ wa ũu mũtikatwaa ũmbano ũũ mũlikye nthĩ ĩla namanengie.'),
('kam', 'NUM', 20, 13, 'Asu nĩ manzĩ ma Meliva; nũndũ ana ma Isilaeli matetanisye na Yeova, nake eeyonan’ya kwoo atĩ nĩ mũtheu.'),
('kam', 'NUM', 20, 14, 'Na Mose atũma atũmwa maume Katesi mathi kwa mũsumbĩ wa Etomu, mamwĩe, Ũũ nĩw’o mwana‐a‐au Isilaeli ũnũkwasya, Nĩwĩsĩ mathĩna onthe ala matũkwatie:'),
('kam', 'NUM', 20, 15, 'ũndũ aaĩthe maitũ matheeie Misili, na twatũa Misili ĩvinda ĩasa; na Amisili matwĩka naĩ, o na aaĩthe maitũ:'),
('kam', 'NUM', 20, 16, 'na yĩla twamwĩkaĩlile Yeova, nĩwewie wasya witũ, na atũma mũlaĩka, na atumya Misili: na, sisya, twĩ vaa Katesi, ndũa yĩ mũminũkĩlyonĩ wa mũvaka waku.'),
('kam', 'NUM', 20, 17, 'Nĩngũkwĩsũva, tũeke tũvĩtĩle nthĩ yaku: tũivĩtĩla mũũndanĩ kana mũũndanĩ wa mĩsavivũ, o na tũinyw’a manzĩ ma ithima; tũkavĩtĩla lelũnĩ wa mũsumbĩ; tũiathũka ũtee ngalĩ ya kw’oko kwa aũme kana kw’oko kwa aka, kũvika yĩla twakĩla mũvaka waku.'),
('kam', 'NUM', 20, 18, 'Na Etomu amwĩa, Ndwĩvĩtĩla nthĩ yakwa, ndikese ũkumĩlĩla na ũvyũ.'),
('kam', 'NUM', 20, 19, 'Na ana ma Isilaeli mamwĩa, Tũkambata na lelũ; na ethĩwa tũkanyw’a manzi kwaku, nyie na indo syakwa, nĩvo ĩndĩ nĩũnenga thooa wamo: ndeka no kũvĩtĩla na nyaĩĩ syakwa, vate ũndũ ũngĩ.'),
('kam', 'NUM', 20, 20, 'Nake asya, Ndwĩvĩtĩla. Na Etomu amumĩlĩla na andũ aingĩ, na kw’oko kwĩ vinya.'),
('kam', 'NUM', 20, 21, 'Ũu nĩw’o Etomu waleile kũnenga Isilaeli ũthei wa kũvĩtĩla mũvakanĩ wake: kwondũ wa ũu Isilaeli aalũka na aekana nake.'),
('kam', 'NUM', 20, 22, 'Na maenda kyalo kuma Katesi: na ana ma Isilaeli, o ũmbano w’onthe, mavika kĩĩma kya Olu.'),
('kam', 'NUM', 20, 23, 'Na Yeova aneena na Mose na Aluni kĩĩmanĩ kya Olu, vakuvĩ na mũvaka wa nthĩ ya Etomu, akĩmea,'),
('kam', 'NUM', 20, 24, 'Aluni akoombanw’a vamwe na andũ make; nũndũ ndakalika nthĩ ĩla nanengie ana ma Isilaeli, nĩkwĩthĩwa nĩmwang’endeie ndeto yakwa manzĩnĩ ma Meliva.'),
('kam', 'NUM', 20, 25, 'Osa Aluni na Eleasali mwana wake, na ũimaete kĩĩmanĩ kya Olu;'),
('kam', 'NUM', 20, 26, 'na mumye Aluni ngũa syake, na ũimwĩkĩa Eleasali mwana wake: na Aluni akakw’ĩa vo, na akoombanw’a vamwe na andũ make.'),
('kam', 'NUM', 20, 27, 'Na Mose eeka o tondũ Yeova weaie: na mambata kĩĩmanĩ kya Olu menekee nĩ ũmbano w’onthe.'),
('kam', 'NUM', 20, 28, 'Na Mose amumya Aluni ngũa syake, na amwĩkĩa Eleasali mwana wake; na Aluni akw’ĩa vo mũtumbĩnĩ wa kĩĩma: na Mose na Eleasali matheea kuma kĩĩmanĩ.'),
('kam', 'NUM', 20, 29, 'Na ũmbano w’onthe woona Aluni nũkwie, mamũĩĩa Aluni mĩthenya mĩongo ĩtatũ, o nyũmba yonthe ya Isilaeli.'),
('kam', 'NUM', 21, 1, 'Na Mũkanaani, mũsumbĩ wa Alati, ũla watwĩe ngalĩ ya Ĩtheo, eew’a atĩ Isilaeli nĩmokĩte na nzĩa ya Athalimu; nake okita na Isilaeli, na atava amwe moo.'),
('kam', 'NUM', 21, 2, 'Na Isilaeli eevĩtĩa Yeova wĩvĩto, na asya, Ethĩwa nĩ w’o wĩnengane andũ aa kw’okonĩ kwakwa, nĩvo ĩndĩ nĩananga ndũa syoo vyũ.'),
('kam', 'NUM', 21, 3, 'Na Yeova eethukĩĩsya wasya wa Isilaeli, na anengane Akanaani; na mamananga na ndũa syoo vyũ: na syĩtwa ya vandũ vau veetwa Olima.'),
('kam', 'NUM', 21, 4, 'Na maenda kyalo kuma kĩĩma kya Olu na nzĩa ĩla ĩelete Ũkanga Mũtune, mathyũlũlũke nthĩ ya Etomu: na andũ asu makw’a ngoo nũndũ wa ĩ nzĩa.'),
('kam', 'NUM', 21, 5, 'Na andũ mamũneenea Ngai naĩ, na Mose nake, makyasya, Mwatumisye Misili tũkw’ĩe weũnĩ nĩkĩ? Nũndũ vaiĩ kya ũya, na vaiĩ manzĩ; na ngoo sĩtũ niemetwe nĩ kya ũya kĩĩ kĩvũthũ.'),
('kam', 'NUM', 21, 6, 'Na Yeova amaetee andũ asu nzoka iilyĩ ta mwaki, na syamaũma andũ; na andũ aingĩ ma Isilaeli makw’a.'),
('kam', 'NUM', 21, 7, 'Na andũ mooka vala ve Mose, na mamwĩa, Nĩtũvĩtĩtye, nũndũ twamũneenea Yeova naĩ, naku we; mũvoye Yeova, aumye nzoka vala tũĩ. Na Mose amavoyea andũ asu.'),
('kam', 'NUM', 21, 8, 'Na Yeova amwĩa Mose, Seũvya nzoka ĩilyĩ ta mwaki, ũmĩkĩe mũtĩnĩ: na kũkeethĩwa, kĩla mũndũ ũla wĩũmwa, amĩsisya, akekala thayũ.'),
('kam', 'NUM', 21, 9, 'Na Mose aseũvya nzoka ya ũthuku, na amĩkĩa mũtĩnĩ: na kweethĩwa ethĩwa nzoka nĩyaũma mũndũ o na wĩva, asisya ĩla nzoka ya ũthuku, akavĩta.'),
('kam', 'NUM', 21, 10, 'Na ana ma Isilaeli maenda kyalo, na mamba maeema moo Ovothi.'),
('kam', 'NUM', 21, 11, 'Na maenda kyalo kuma Ovothi, na mamba maeema moo Iye‐avalimu, weũnĩ ũla welekele Moavi, kwelekela wumĩlonĩ wa syũa.'),
('kam', 'NUM', 21, 12, 'Kuma vo maenda kyalo, na mamba maeema moo kyandanĩ kya Nzeleti.'),
('kam', 'NUM', 21, 13, 'Na kuma vu maenda kyalo, na mamba maeema moo mũingo ũla ũngĩ wa Alinoni, ũla wĩ weũnĩ, ũla wumite mũvakanĩ wa Aamoli: nũndũ Alinoni nĩ mũvaka wa Moavi, katĩ wa Moavi na Aamoli.'),
('kam', 'NUM', 21, 14, 'Kwondũ wa ũu kũneenetw’e ĩvukunĩ ya Makaũ ma Yeova atĩĩ, Vaevu nthĩnĩ wa Suva, Na syanda sya Alinoni,'),
('kam', 'NUM', 21, 15, 'Na kĩvaũũko kya syanda Kĩla kĩelete wĩkalonĩ wa Ali, Na kĩtinene mũvakanĩ wa Moavi.'),
('kam', 'NUM', 21, 16, 'Na kuma vau maenda kyalo kũvika Mbeeli: na nĩ kĩthima kĩla Yeova wamũtavisye Mose ũndũ wakyo, Ũmban’ya andũ na ngamanenga manzĩ.'),
('kam', 'NUM', 21, 17, 'Nĩvo ĩndĩ Isilaeli mainie wathi ũũ: Vulutya, we kĩthima; kinĩei:'),
('kam', 'NUM', 21, 18, 'Kĩthima, kĩla anene me mbee ũsumbĩnĩ menzie, Kĩla anene ma andũ me ndaĩa mavukũie, Na ndata sya ũsumbĩ, na ndata syoo. Na kuma weũnĩ maenda kyalo kũvika Matana;'),
('kam', 'NUM', 21, 19, 'na kuma Matana mavika Naalieli; na kuma Naalieli mavika Mbamothi;'),
('kam', 'NUM', 21, 20, 'na kuma Mbamothi mavika kyanda kĩla kĩ weũnĩ wa Moavi, kũvika mũtumbĩnĩ wa kĩĩma kya Visika, kĩla kyelekele na ku ĩtheo weũnĩ.'),
('kam', 'NUM', 21, 21, 'Na Isilaeli atũma atũmwa kwa Sioni mũsumbĩ wa Aamoli, akĩmwĩa,'),
('kam', 'NUM', 21, 22, 'Ndeka nĩvĩtĩle nthĩ yaku: tũiathũka ũtee mũũndanĩ, kana kũlika mũũndanĩ wa mĩsavivũ; tũinyw’a manzĩ ma ithima: tũkavĩtĩla lelũnĩ wa mũsumbĩ, kũvika twakĩla mũvaka waku.'),
('kam', 'NUM', 21, 23, 'Na Sioni ndaaĩtĩkĩla kũmaeka Isilaeli mavĩtĩle mũvakanĩ wake: ĩndĩ Sioni oomban’ya andũ make onthe, na amaumaalĩla Isilaeli weũnĩ, na avika Yaasa; na okita na Isilaeli.'),
('kam', 'NUM', 21, 24, 'Na Isilaeli mamũkũna kwa kũmũtemanga na ũvyũ, na mamesya nthĩ yake kuma ũsĩ wa Alinoni kũvika ũla wa Yavoki, o kũvika ana ma Amimoni; nũndũ mũvaka wa ana ma Amimoni waĩ na vinya.'),
('kam', 'NUM', 21, 25, 'Na Isilaeli makwata ndũa isu syonthe: na Isilaeli matwĩe ndũanĩ syonthe sya Aamoli, ndũanĩ ya Esivoni, na tũtũla twayo tw’onthe.'),
('kam', 'NUM', 21, 26, 'Nũndũ Esivoni yaĩ ndũa ya Sioni mũsumbĩ wa Aamoli, ũla wokitie na mũsumbĩ wa Moavi ũla waĩ mbeange wa ĩvinda yĩu, na amũvena nthĩ yake kw’okonĩ kwake, o kũvika Alinoni.'),
('kam', 'NUM', 21, 27, 'Kwondũ wa ũu ala maneenaa na nthimo measya, Ũkai Esivoni; Ndũa ya Sioni nĩyakwe na kũlũlũmĩlw’a:'),
('kam', 'NUM', 21, 28, 'Nũndũ mwaki wumĩte Esivoni, Ũlĩlĩnzĩ wa mwaki wumĩte ndũanĩ ya Sioni: Nĩwanangĩte ndũa ya Ali ya Moavi, Eaĩi ma kũndũ kũtũlu kwa ũ Alinoni.'),
('kam', 'NUM', 21, 29, 'Woo nĩ waku, Moavi! Nĩmwathela, inyw’ĩ andũ ma Kemosi: Anenganĩte ana make methĩwe akĩi, Na eĩtu make mũtavonĩ, Kwa Sioni mũsumbĩ wa Aamoli.'),
('kam', 'NUM', 21, 30, 'Nĩtũmekĩtye mĩsyĩ; Esivoni nĩyaaie o kũvika Ndivoni, Na nĩtwanangie o kũvika Novia, O na kũvika Meteva.'),
('kam', 'NUM', 21, 31, 'Na ĩndĩ Isilaeli matwĩe nthĩ ya Aamoli.'),
('kam', 'NUM', 21, 32, 'Na Mose atũma andũ kũthiana Yaseli; na makwata tũtũla twa vo, na mamalũngya Aamoli ala maĩ vo.'),
('kam', 'NUM', 21, 33, 'Na meethyũũa na mambata na nzĩa ya Mbasani: na Oku mũsumbĩ wa Mbasani amaumaalĩla, we na andũ make onthe, kũkitĩa namo Etilei.'),
('kam', 'NUM', 21, 34, 'Na Yeova amwĩa Mose, Ndũkamũkĩe: nĩkwĩthĩwa nĩnĩmũnenganĩte kw’okonĩ kwaku, na andũ make onthe, na nthĩ yake; na ũkamwĩka o tondũ wamwĩkie Sioni mũsumbĩ wa Aamoli, ũla watwĩe Esivoni.'),
('kam', 'NUM', 21, 35, 'Kwondũ wa ũu mamũkũna we, na ana make na andũ make onthe, kũvika vatyaatiala mũndũ o na wĩva wake: namo mamĩmesya nthĩ yake.'),
('kam', 'NUM', 22, 1, 'Na ana ma Isilaeli maenda kyalo, na mamba maeema moo ndiĩnĩ sya Moavi mũingo wa Yolotani o vu Yeliko.'),
('kam', 'NUM', 22, 2, 'Na Mbalaki mwana wa Nzivoli oona ũu w’onthe ũla Isilaeli mekĩte Aamoli.'),
('kam', 'NUM', 22, 3, 'Na Moavi amakĩa andũ asu mũno, nũndũ maĩ aingĩ: na Moavi aũũya nũndũ wa ana ma Isilaeli.'),
('kam', 'NUM', 22, 4, 'Na Moavi amea atumĩa ma Mitiani, Yu nguthu ĩno ĩkanyenya kĩla kyonthe kĩtũthyũlũlũkĩte, o tondũ ng’ombe ĩnyenyaa nyeki ya weũ. Na Mbalaki mwana wa Nzivoli aĩ mũsumbĩ wa Moavi ĩvinda yĩu.'),
('kam', 'NUM', 22, 5, 'Na atũma atũmwa kwa Mbalaamu mwana wa Mbeoli, ku Vetholi, ĩla yĩ vakuvĩ na ũla Ũsĩ, nthĩ ya syana sya andũ make, mamwĩte, makĩmwĩa, Sisya, kwĩ andũ ala maumĩte Misili: sisya, mavw’ĩkĩte nthĩ, na mekalaa mambelekele nyie.'),
('kam', 'NUM', 22, 6, 'Ũka oyu ĩndĩ, nĩngũkwĩsũva, ũnumanĩĩe andũ aa: nũndũ nao me na vinya kũmbĩtũka nyie: nokwĩthĩwa nĩmakĩlya vinya, tũmakũne, nakwa nĩmalũngye maume nthĩ ĩno; nũndũ nĩnĩsĩ ũla ũmũathimaa we nĩ mũathime, na ũla ũumanĩaa nĩ mũumanĩe.'),
('kam', 'NUM', 22, 7, 'Na atumĩa ma Moavi na atumĩa ma Mitiani mathi makwete syĩndũ sya kũaũsya mokonĩ moo; nao mavika vala ve Mbalaamu, na mamũtavya ndeto sya Mbalaki.'),
('kam', 'NUM', 22, 8, 'Nake amea, Komai vaa ũtukũ ũũ, na ngamũetee ũvoo ĩngĩ, o tondũ Yeova wĩmbĩa: na ala anene me mbee ũsumbĩnĩ ma Moavi mekala kwa Mbalaamu.'),
('kam', 'NUM', 22, 9, 'Na Ngai ooka vala ve Mbalaamu, na amũkũlya, Andũ aa me kwaku naaũ?'),
('kam', 'NUM', 22, 10, 'Na Mbalaamu amwĩa Ngai, Mbalaki mwana wa Nzivoli, mũsumbĩ wa Moavi, nũtũmanĩte kwakwa, akĩmbĩa,'),
('kam', 'NUM', 22, 11, 'Sisya, andũ ala maumĩte Misili, nĩmavw’ĩkĩte nthĩ: oyu, ũka ũnumanĩĩe mo; nokwĩthĩwa ndonya kũkita namo, na kũmalũngya.'),
('kam', 'NUM', 22, 12, 'Na Ngai amwĩa Mbalaamu, Ndũkaende namo; ndũkaumanĩe andũ asu; nũndũ nĩ aathime.'),
('kam', 'NUM', 22, 13, 'Na Mbalaamu ookĩla kĩoko, na amea anene me mbee ũsumbĩnĩ ma Mbalaki, Alũkai nthĩ yenyu; nũndũ Yeova nũnũkũlea kũnenga ũthei wa kũthi nenyu.'),
('kam', 'NUM', 22, 14, 'Na anene me mbee ũsumbĩnĩ ma Moavi mookĩla na mamũsyokea Mbalaki, na mamwĩa, Mbalaamu nũleile kũkan’ya naitũ.'),
('kam', 'NUM', 22, 15, 'Na Mbalaki atũma ĩngĩ anene me mbee ũsumbĩnĩ aingangĩ, na me na ndaĩa kwĩ asu ma mbee.'),
('kam', 'NUM', 22, 16, 'Na mavika kwa Mbalaamu, na mamwĩa, Ũũ nĩw’o Mbalaki mwana wa Nzivoli ũnũkwasya, Nĩngũkwĩsũva, ndũkasiĩĩwe nĩ ũndũ o na wĩva kũka vala nĩĩ:'),
('kam', 'NUM', 22, 17, 'nũndũ ngakũnenevya wĩthĩwe na ndaĩa nene mũno, na o ũla wĩmbĩa ngawĩka: ũka ĩndĩ, nĩngũkwĩsũva, ũnumanĩĩe andũ aa.'),
('kam', 'NUM', 22, 18, 'Na Mbalaamu asũngĩa na amea athũkũmi ma Mbalaki, O na ethĩwa Mbalaki akanenga nyũmba yake yusũĩte vetha na thaavu, nditonya kũkĩla ndeto ya Yeova Ngai wakwa, kũmĩnyivya kana kũmyongelela.'),
('kam', 'NUM', 22, 19, 'Yu ĩndĩ, nĩngũmwĩsũva, ĩkalai vaa ũtukũ ũũ naw’o, nĩmanye ũndũ Yeova wĩongela kũmbĩa.'),
('kam', 'NUM', 22, 20, 'Na Ngai amũendea Mbalaamu ũtukũ, na amwĩa, Ethĩwa andũ nĩmooka ũkwĩta, ũkĩla, ũthi namo; ĩndĩ no ndeto ĩla nĩkũtavya, nĩyo wĩĩka.'),
('kam', 'NUM', 22, 21, 'Na Mbalaamu ookĩla kĩoko, na atandĩka ĩng’oi yake, na athi na anene me mbee ũsumbĩnĩ ma Moavi.'),
('kam', 'NUM', 22, 22, 'Na ũthatu wa Ngai wakana nũndũ nĩwathi; na mũlaĩka wa Yeova aũngama nzĩanĩ ethĩwe nthũ yake. Nake aenda akuĩtwe nĩ ĩng’oi yake na athũkũmi make elĩ maĩ vamwe nake.'),
('kam', 'NUM', 22, 23, 'Na ĩng’oi yoona mũlaĩka wa Yeova aũngeme nzĩanĩ, akũĩte ũvyũ wake wĩ kw’okonĩ kwake; na ĩng’oi yaathũka ũtee wa nzĩa, na yathi mũũndanĩ: na Mbalaamu akũna ĩng’oi, ayĩtũnge nzĩanĩ.'),
('kam', 'NUM', 22, 24, 'Nĩvo ĩndĩ mũlaĩka wa Yeova aũngama nzĩanĩ ntheke katĩ wa mĩũnda ya mĩsavivũ, ũvai wĩ ngalĩ ĩno, na ũvai ngalĩ ĩya.'),
('kam', 'NUM', 22, 25, 'Na ĩng’oi yoona mũlaĩka wa Yeova, na yeethũũan’ya na ũvai, na yavinyĩĩa kũũ kwa Mbalaamu ũvainĩ: nake ayĩkũna ĩngĩ.'),
('kam', 'NUM', 22, 26, 'Na mũlaĩka wa Yeova aenda mbee, na aũngama vandũ vatheke, vala vataĩ ũthei wa kwathũka ngalĩ ya kw’oko kwa aũme kana kw’oko kwa aka.'),
('kam', 'NUM', 22, 27, 'Na ĩng’oi yoona mũlaĩka wa Yeova, na yavalũka nthĩ yĩkuĩte Mbalaamu: na ũthatu wa Mbalaamu wakana, na akũna yĩla ĩng’oi na ndata yake.'),
('kam', 'NUM', 22, 28, 'Na Yeova aathamya kanyw’a wa ĩng’oi, nayo yamwĩa Mbalaamu, Nakwĩkie ata, ũndũ ũũngũna mavinda aa atatũ?'),
('kam', 'NUM', 22, 29, 'Na Mbalaamu ayĩa ĩng’oi, Nĩkwĩthĩwa nũũmbũĩa ngũĩ: nenda kethĩwa nĩĩ na ũvyũ kw’okonĩ kwakwa, nũndũ yu nĩthĩwa ngũaie.'),
('kam', 'NUM', 22, 30, 'Na ĩng’oi yakũlya Mbalaamu, Nyie ndi ĩng’oi yaku, yĩla yĩũkuaa matukũ maku onthe kũvika ũmũnthĩ? Nĩ ĩndĩĩ nakwĩkie ũu? Nake asũngĩa, Aiee.'),
('kam', 'NUM', 22, 31, 'Nĩvo ĩndĩ Yeova wasalukilye metho ma Mbalaamu, nake oona mũlaĩka wa Yeova aũngeme nzĩanĩ, e na ũvyũ wake akũĩte wĩ kw’okonĩ kwake; na akunamya mũtwe wake, na avalũka na ũthyũ wake.'),
('kam', 'NUM', 22, 32, 'Na mũlaĩka wa Yeova amwĩa, Wakũna ĩng’oi yaku mavinda aa atatũ nĩkĩ? Sisya, nĩnumie nĩthĩwe mũmaitha, nĩkwĩthĩwa nzĩa yaku nĩ ya ngũlũ vala nĩĩ:'),
('kam', 'NUM', 22, 33, 'na yĩ ĩng’oi yambona, na yaathũka ũtee mbee wakwa mavinda aa atatũ: kethĩwa yĩtyaathũka ũtee mbee wakwa, nĩthĩwa ngũaie vate ndĩi, na kũyĩeka yĩ thayu.'),
('kam', 'NUM', 22, 34, 'Na Mbalaamu amwĩa mũlaĩka wa Yeova, Nĩnĩvĩtĩtye; nũndũ ndyĩĩsĩ kana ũũngeme nzĩanĩ kũnziĩĩa: kwondũ wa ũu yu ethĩwa ũu ndũũkwendeesya, nĩngũalũka.'),
('kam', 'NUM', 22, 35, 'Na mũlaĩka wa Yeova amwĩa Mbalaamu, Enda na andũ aa; ĩndĩ no ndeto ĩla nĩũtavya, nĩyo wĩneena. Kwondũ wa ũu Mbalaamu athi na anene me mbee ũsumbĩnĩ ma Mbalaki.'),
('kam', 'NUM', 22, 36, 'Na yĩla Mbalaki wewie Mbalaamu nĩwooka, aumaala amũthaũe kũvika Ndũa ya Moavi, ĩla yĩ mũvakanĩ wa ũsĩ wa Alinoni, ũla wĩ mũminũkĩlyonĩ wa mũvaka.'),
('kam', 'NUM', 22, 37, 'Na Mbalaki akũlya Mbalaamu, Ndinatũmana na kĩthing’ĩĩsyo makwĩte? Ndũnoka vala nĩĩ nĩkĩ? Nditonya ũkũnenevya wĩthĩwe na ndaĩa?'),
('kam', 'NUM', 22, 38, 'Na Mbalaamu amwĩa Mbalaki, Sisya, nĩnooka vala ũĩ: nĩ na vinya o na wĩva o na yu ndonya ũneena ũndũ o na ũmwe? Ndeto ĩla Ngai wĩmbĩkĩa kanyw’anĩ wakwa, noyo nĩneena.'),
('kam', 'NUM', 22, 39, 'Na Mbalaamu athi na Mbalaki na mavika Kiliathiusothi.'),
('kam', 'NUM', 22, 40, 'Na Mbalaki athemba ng’ombe na malondu, na amwatũĩla Mbalaamu, na anene me mbee ũsumbĩnĩ ala maĩ nake.'),
('kam', 'NUM', 22, 41, 'Na kweethĩwa ũnĩ ũsu, Mbalaki amwosa Mbalaamu, na amwambatya kũndũ kũtũlu kwa Mbaali; na e kũu oona andũ onthe o vala mathelele.'),
('kam', 'NUM', 23, 1, 'Na Mbalaamu amwĩa Mbalaki, Mbakĩa vaa ithembeo mũonza, na ũthĩnzĩe vaa tũsalũ mũonza twa mũew’a na ndũũme mũonza.'),
('kam', 'NUM', 23, 2, 'Na Mbalaki eeka o tondũ Mbalaamu waisye; na Mbalaki na Mbalaamu mathemba kasalũ ka mũew’a na ndũũme kĩla kĩthembeonĩ.'),
('kam', 'NUM', 23, 3, 'Na Mbalaamu amwĩa Mbalaki, Ũngama vakuvĩ na nthembo yaku ya kũvĩvw’a, nakwa nĩngũthi: nokwĩthĩwa Yeova ekũka tũkomane; na o ũla wĩmbon’ya ngaũtavya. Na athi kĩĩmanĩ vandũ vathei.'),
('kam', 'NUM', 23, 4, 'Na Ngai akomana na Mbalaamu: nake amwĩa, Nĩnzeũvĩtye ithembeo mũonza, na nĩnthembete kasalũ ka mũew’a na ndũũme kĩla kĩthembeonĩ.'),
('kam', 'NUM', 23, 5, 'Na Yeova eekĩa ndeto kanyw’anĩ wa Mbalaamu, na amwĩa, Mũsyokee Mbalaki, na ũkaneene ũna na ũna.'),
('kam', 'NUM', 23, 6, 'Na amũsyokea, na, sisya, aũngeme vakuvĩ na nthembo yake ya kũvĩvw’a, we, na anene me mbee ũsumbĩnĩ onthe ma Moavi.'),
('kam', 'NUM', 23, 7, 'Nake aneena ngelekan’yo yake, na asya, Mbalaki andetete kuma Alamu, Mũsumbĩ wa Moavi anumĩtye iĩmanĩ sya Wumĩlonĩ wa syũa: Ũka, ũnumanĩĩe Yakovo, Na ũka ũmavũthĩĩsye Isilaeli.'),
('kam', 'NUM', 23, 8, 'Ngamũumanĩa ata, ũla Ngai ũtaamũumanĩa? Na ngamũvũthĩĩsya ata, ũla Yeova ũtaamũvũthĩĩsya?'),
('kam', 'NUM', 23, 9, 'Nũndũ kuma vaa ĩũlũ wa maũvai nĩngũmwona, Na nĩ iĩmanĩ no ngũmwona: Sisya, asu nĩ andũ ala matwĩe me oka, Na matikatalanĩlw’a na mbaĩ ingĩ.'),
('kam', 'NUM', 23, 10, 'Nũũ ũla ũtonya kũtala kĩtoo kya Yakovo, Kana kũtala kĩlungu kya kana kya Isilaeli? Ndeka nĩkw’e kĩkw’ũ kya mũndũ mũlũngalu, Na mũminũkĩlyo wakwa nĩwĩthĩwe ta wake!'),
('kam', 'NUM', 23, 11, 'Na Mbalaki amwĩa Mbalaamu, Ũmbĩkĩte ata? Nĩkũetete ũumanĩe amaitha makwa, na, sisya, nũmaathimĩte ki.'),
('kam', 'NUM', 23, 12, 'Nake asũngĩa na amwĩa, Ti mũvaka nĩsũvĩe kũneena ndeto ila Yeova ũnũũmbĩkĩa kanyw’anĩ wakwa?'),
('kam', 'NUM', 23, 13, 'Na Mbalaki amwĩa, Ũka, nĩngũkwĩsũva, tũendan’ye vandũ vangĩ vala ũtonya kũmona; ũkoona o vala mathelele, na ndũkamona onthe: na ũnumanĩĩe andũ asu wĩ vo.'),
('kam', 'NUM', 23, 14, 'Na amũtwaa mũũndanĩ wa Nzovimu, mũtumbĩnĩ wa kĩĩma kya Visika, na aaka ithembeo mũonza, na athemba kasalũ ka mũew’a na ndũũme kĩla kĩthembeonĩ.'),
('kam', 'NUM', 23, 15, 'Na amwĩa Mbalaki, Ũngama vaa vakuvĩ na nthembo yaku ya kũvĩvw’a, yĩla ngũthi kũkomana na Yeova kũya.'),
('kam', 'NUM', 23, 16, 'Na Yeova akomana na Mbalaamu, na eekĩa ndeto kanyw’anĩ wake, na amwĩa, Mũsyokee Mbalaki, na ũneene nake ũna na ũna.'),
('kam', 'NUM', 23, 17, 'Na avika vala ũĩ, na, sisya, aũngeme vakuvĩ na nthembo yake ya kũvĩvw’a, na anene me mbee ũsumbĩnĩ ma Moavi vamwe nake. Na Mbalaki amũkũlya, Yeova akwĩa ata?'),
('kam', 'NUM', 23, 18, 'Nake aneena ngelekan’yo yake, na asya, Ũkĩla, Mbalaki, wĩw’e; Mbĩthukĩĩsya, we mwana wa Nzivoli:'),
('kam', 'NUM', 23, 19, 'Ngai ti mũndũ, ũndũ ũneena ũvũngũ; O na ti mwana wa mũndũ, kana etũnge: Nũneenete, na ndakeka? Kana nĩwaĩtye, na ndakeanĩsya?'),
('kam', 'NUM', 23, 20, 'Sisya, nĩnosete mwĩao wa kũathima: Nake nũathimĩte, nakwa nditonya kũalyũla.'),
('kam', 'NUM', 23, 21, 'Ndaaona ũthũku nthĩnĩ wa Yakovo; O na ndaaona ngũlũ nthĩnĩ wa Isilaeli: Yeova Ngai wake e vamwe nake, Na wasya mũtũlu wa mũsumbĩ wĩ katĩ wamo.'),
('kam', 'NUM', 23, 22, 'Ngai nũmaetete kuma Misili; E na vinya ũilyĩ ta vinya wa mboo.'),
('kam', 'NUM', 23, 23, 'Nĩ w’o, vati ũoi ũtonya Yakovo; O na vati kũaũsya kũtonya Isilaeli: Nĩkũũneew’a yu ũndũ wa Yakovo na ũndũ wa Isilaeli, Ai, Ngai nĩwĩkĩte!'),
('kam', 'NUM', 23, 24, 'Sisya, andũ nĩmekũkĩla ta mũnyambũ mũka, Na nũkwĩyũkĩlya ta mũnyambũ mũũme: Ndakatindia atanaya nyama ila sya nzyĩma, Na kũnyw’a nthakame ya ila syoaiwe.'),
('kam', 'NUM', 23, 25, 'Na Mbalaki amwĩa Mbalaamu, Ndũkamaumanĩe nongi, o na ndũkamaathime nongi.'),
('kam', 'NUM', 23, 26, 'Ĩndĩ Mbalaamu asũngĩa na amwĩa Mbalaki, Ndinakũtavya, ngyasya, Maũndũ onthe ala Yeova ũneenaa, nditĩa kũmeka?'),
('kam', 'NUM', 23, 27, 'Na Mbalaki amwĩa Mbalaamu, Ũka yu, ngakũtwaa vandũ vangĩ; nokwĩthĩwa Ngai akendeew’a ũnumanĩĩe mo vau.'),
('kam', 'NUM', 23, 28, 'Na Mbalaki amũtwaa Mbalaamu mũtumbĩnĩ wa kĩĩma kya Veoli, kĩla kyelekele na ku ĩtheo weũnĩ.'),
('kam', 'NUM', 23, 29, 'Na Mbalaamu amwĩa Mbalaki, Mbakĩa vaa ithembeo mũonza, na ũimbiĩa vaa tũsalũ mũonza twa mũew’a na ndũũme mũonza.'),
('kam', 'NUM', 23, 30, 'Na Mbalaki eeka o tondũ Mbalaamu wamwĩie, na athemba kasalũ ka mũew’a na ndũũme kĩla kĩthembeonĩ.'),
('kam', 'NUM', 24, 1, 'Na Mbalaamu oona Yeova nũkwendeew’a nĩ kũathima Isilaeli, ndaathi, ta mavinda ala angi, kũmantha mowe, ĩndĩ eelekelya ũthyũ wake weũnĩ.'),
('kam', 'NUM', 24, 2, 'Na Mbalaamu ookĩlya metho make, na oona Isilaeli matũĩte kwĩanana na mbaĩ syoo; na Veva wa Ngai ooka ĩũlũ wake.'),
('kam', 'NUM', 24, 3, 'Na aneena ngelekan’yo yake, na asya, Mbalaamu mwana wa Mbeoli easya, Na mũndũ ũla ũnalalĩtye metho make easya;'),
('kam', 'NUM', 24, 4, 'Nake easya, ũla wĩw’aa ndeto sya Ngai, Ũla wonaa woni wa Mwene Vinya W’onthe, Akĩvalũka nthĩ, metho make masalukĩtye:'),
('kam', 'NUM', 24, 5, 'Ai! Maeema maku ko nĩ maseo, we Yakovo, Mawĩkalo maku, we Isilaeli!'),
('kam', 'NUM', 24, 6, 'Ta syanda nĩmalanĩtw’e, Ta mĩũnda ũtee wa ũsĩ, Ta mĩtĩ ya uuti ĩla Yeova ũvandĩte, Ta mĩtĩ ya mĩkũũ ũtee wa manzi.'),
('kam', 'NUM', 24, 7, 'Manzĩ makavulutasya kuma ndoonĩ syake, Na ũsyao wake ũkekala vala ve manzĩ maingĩ, Na mũsumbĩ wake akataĩwa kwĩ Akaki, Na ũsumbi wake ũkanenevw’a.'),
('kam', 'NUM', 24, 8, 'Ngai nũmũetete kuma Misili; E na vinya ũilyĩ ta vinya wa mboo: Akaimelya mbaĩ ila syĩ amaitha make, Na akatũlanga mavĩndĩ moo ilungu, Na akamaathanga mũkuthũ na mĩsyĩ yake.'),
('kam', 'NUM', 24, 9, 'Akunama, atindia ta mũnyambũ mũume, Na ta mũnyambũ mũka; ũla wĩmũtindiũkya nũũ? Naathimwe kĩla mũndũ ũla ũkũathimaa, Na naumanĩwe kĩla mũndũ ũla ũkũumanĩaa.'),
('kam', 'NUM', 24, 10, 'Na ũthatu wa Mbalaki wamwakanĩa Mbalaamu, na akũnangan’ya mbĩ; na Mbalaki amwĩa Mbalaamu, Nĩnĩnakwĩtie ũumanĩe amaitha makwa, na, sisya, nũmaathimĩte ki mavinda aa atatũ.'),
('kam', 'NUM', 24, 11, 'Kwondũ wa ũu yu kĩa ũende kwaku: nĩnasũanĩaa ũkũnenevya na ndaĩa nene; ĩndĩ, sisya, Yeova nĩwakũsiĩĩe ndũkethĩwe na ndaĩa.'),
('kam', 'NUM', 24, 12, 'Na Mbalaamu amwĩa Mbalaki, Ndyaaneena na atũmwa maku ala wamatũmie kwakwa, ngĩmea,'),
('kam', 'NUM', 24, 13, 'Ethĩwa Mbalaki akanenga nyũmba yake yusũĩte vetha na thaavu, nditonya kũvĩta ndeto ya Yeova, kwĩka ũseo kana ũthũku na kĩsũanĩo kyakwa mwene; ũla Yeova ũneenaa, nĩw’o nĩneena?'),
('kam', 'NUM', 24, 14, 'Na yu, sisya, nĩngũthi kwa andũ makwa: ũka, na ngakũmanyĩthya ũla andũ aa makameka andũ maku mĩthenya ya mũminũkĩlyo.'),
('kam', 'NUM', 24, 15, 'Na aneena ngelekan’yo yake, na asya, Mbalaamu mwana wa Mbeoli easya, Na mũndũ ũla ũnalalĩtye metho make easya;'),
('kam', 'NUM', 24, 16, 'Nake easya, we ũla wĩw’aa ndeto sya Ngai, Na wĩsĩ ũmanyi wa Ũla Wĩ Ĩũlũ wa Onthe, Ũla wonaa woni wa Mwene Vinya W’onthe, Akĩvalũka nthĩ, metho make masalukĩtye:'),
('kam', 'NUM', 24, 17, 'Nĩngũmwona, ĩndĩ ti yu; Nĩngũmũsisya, ĩndĩ ti vakuvĩ: Kũkauma ndata nthĩnĩ wa Yakovo, Na ndata ya ũsumbĩ ĩkookĩla kuma nthĩnĩ wa Isilaeli, Na ĩkakũnanga ikoto sya Moavi, Na kwavalũkya nthĩ ana onthe ma kĩtuu.'),
('kam', 'NUM', 24, 18, 'Na Etomu ĩkeethĩwa ng’ũndũ yake, O na Seili ĩkeethĩwa ng’ũndũ yake, asu ala maĩ amaitha make; Yĩla Isilaeli wĩkaa maũndũ na ũkũmbaũ.'),
('kam', 'NUM', 24, 19, 'Nthĩnĩ wa Yakovo vakauma ũla ũkasumbĩka, Nake akaananga ala matialile ndũanĩ.'),
('kam', 'NUM', 24, 20, 'Na amũsisya Amaleki, na aneena ngelekan’yo yake, na asya, Amaleki aĩ wa mbee wa ila mbaĩ; Ĩndĩ mũminũkĩlyo wake ũkeethĩwa wanangĩko.'),
('kam', 'NUM', 24, 21, 'Na asisya Mũkeni, na aneena ngelekan’yo yake, na asya, Ũtũo waku wĩ na vinya, Na ndala yaku yiĩtwe ĩvianĩ.'),
('kam', 'NUM', 24, 22, 'Ĩndĩ Keni akaanangwa, Kũvika yĩla Asuli ũkakũtwaa wĩ mũtave.'),
('kam', 'NUM', 24, 23, 'Na aneena ngelekan’yo yake, na asya, Ĩiaa! Nũũ ũla ũkavĩta yĩla Ngai wĩĩka ũu?'),
('kam', 'NUM', 24, 24, 'Ĩndĩ ngalawa ikooka kuma ndee sya Kitimu, Na ikathĩn’ya Asuli, na ikathĩn’ya Eveli; Nake akaanangwa vyũ.'),
('kam', 'NUM', 24, 25, 'Na Mbalaamu ookĩla, na athi enũka kwake; o nake Mbalaki eeyiendea.'),
('kam', 'NUM', 25, 1, 'Na Isilaeli mekala Sitimu; na andũ mambĩlĩlya kwĩka ũmalwaya na eĩtu ma Moavi:'),
('kam', 'NUM', 25, 2, 'nũndũ nĩmeetie andũ maende nthembonĩ sya ngai syoo; na andũ maya, na makunamĩa ngai syoo.'),
('kam', 'NUM', 25, 3, 'Na Isilaeli meekwatan’ya na Mbaali‐veoli: na ũthatu wa Yeova wakanĩa Isilaeli.'),
('kam', 'NUM', 25, 4, 'Na Yeova amwĩa Mose, Osa anene onthe ma andũ, na ũmasũĩsye Yeova syũanĩ, nĩ kana ũthatu mwai wa Yeova wĩthyũũe wume kwa Isilaeli.'),
('kam', 'NUM', 25, 5, 'Na Mose amea asili ma Isilaeli, Inyw’ĩ, mũaei o kĩla mũndũ andũ make ala mekwatanĩtye na Mbaali‐veoli.'),
('kam', 'NUM', 25, 6, 'Na, sisya, mũndũ ũmwe wa ana ma Isilaeli ooka na amaetee ana‐a‐ĩthe make mũndũ mũka Mũmitiani Mose ene, o na ũmbano w’onthe wa ana ma Isilaeli wene, o yĩla maĩĩaa mũomonĩ wa ĩeema ya kũmbanĩa.'),
('kam', 'NUM', 25, 7, 'Na yĩla Vineasi, mwana wa Eleasali, mwana wa mũthembi Aluni, wonie uũ, ookĩla kuma katĩ wa ũmbano, na oosa ĩtumo kw’okonĩ kwake;'),
('kam', 'NUM', 25, 8, 'na amũatĩĩa mũndũ ũsu wa Isilaeli alika ĩeemanĩ, na amatonya me elĩ mũkuthũ, ũ mũndũ wa Isilaeli, na ũla mũndũ mũka ĩvunĩ yake. Na ĩndĩ mũimũ wasiĩĩwa ananĩ ma Isilaeli.'),
('kam', 'NUM', 25, 9, 'Na ala makwie nĩ mũimũ ũsu maĩ ngili mĩongo ĩlĩ na inya.'),
('kam', 'NUM', 25, 10, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 25, 11, 'Vineasi, mwana wa Eleasali, mwana wa mũthembi Aluni, nũalyũlĩte ũthilĩku wakwa wume ĩũlũ wa ana ma Isilaeli, nũndũ nĩwewie kĩwĩu, o kĩwĩu kyakwa katĩ woo, ũndũ wa ũu ndyaananga ana ma Isilaeli kĩwĩunĩ kyakwa.'),
('kam', 'NUM', 25, 12, 'Kwondũ wa ũu neena atĩĩ, Sisya, nĩngũmũnenga ũtianĩo wakwa wa mũuo:'),
('kam', 'NUM', 25, 13, 'na ũkeethĩwa kwake, na kwa ũsyao wake ĩtina wake, ũtianĩo wa ũthembi wa tene na tene; nĩkwĩthĩwa aĩ na kĩwĩu kwondũ wa Ngai wake, na amew’anĩthya ana ma Isilaeli.'),
('kam', 'NUM', 25, 14, 'Na ĩndĩ syĩtwa ya mũndũ wa Isilaeli ũla woaiwe, ũla woaiwe vamwe na mũndũ mũka Mũmitiani, eetawa Nzimili, mwana wa Salu, mũnene wa nyũmba ya aaithe mũvĩanĩ wa Asimeoni.'),
('kam', 'NUM', 25, 15, 'Na syĩtwa ya mũndũ mũka Mũmitiani ũla woaiwe eetawa Kosivi, mwĩĩtu wa Nzuli; nake aĩ mũtongoi wa andũ ma nyũmba ya aaĩthe ku Mitiani.'),
('kam', 'NUM', 25, 16, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 25, 17, 'Mathĩn’ye Amitiani, na kũmakũna;'),
('kam', 'NUM', 25, 18, 'nũndũ nĩmeũmũthĩn’ya na moseleke moo, ala mamũkengie nao ũvoonĩ wa Veoli, na ũvoonĩ wa Kosivi, mwĩĩtu wa mũnene wa Mitiani, mwĩĩtua‐inyia woo, ũla woaiwe mũthenya wa mũimũ ũndũnĩ ũsu wa Veoli.'),
('kam', 'NUM', 26, 1, 'Na kweethĩwa ĩtina wa mũimũ ũsu, Yeova aneena na Mose na Eleasali mwana wa mũthembi Aluni, akĩmea,'),
('kam', 'NUM', 26, 2, 'Talai ũmbano w’onthe wa ana ma Isilaeli, ala mavikĩtye myaka mĩongo ĩlĩ na mbee, kũatĩĩa nyũmba sya aaĩthe moo, onthe ma Isilaeli ala matonya kũthi kaũnĩ.'),
('kam', 'NUM', 26, 3, 'Na Mose na mũthembi Eleasali maneenea nao ndiĩnĩ sya Moavi vakuvĩ na Yolotani ku Yeliko, makyasya,'),
('kam', 'NUM', 26, 4, 'Talai andũ onthe ala mavikĩtye myaka mĩongo ĩlĩ na mbee; o tondũ Yeova wamwĩaĩe Mose na ana ma Isilaeli, ala maumie nthĩ ya Misili.'),
('kam', 'NUM', 26, 5, 'Leuveni, ĩkithathi ya Isilaeli; ana ma Leuveni nĩ aa: ma Anoki, mũvĩa wa Aanoki; ma Valu, mũvĩa wa Avalu;'),
('kam', 'NUM', 26, 6, 'ma Esiloni, mũvĩa wa Aesiloni; ma Kalimi, mũvĩa wa Akalimi.'),
('kam', 'NUM', 26, 7, 'Ĩsu nĩyo mĩvĩa ya Aleuveni; na ala matalilwe moo maĩ ngili mĩongo ĩna na itatũ na maana mũonza na mĩongo ĩtatũ.'),
('kam', 'NUM', 26, 8, 'Na ana ma Valu: o Eliavu.'),
('kam', 'NUM', 26, 9, 'Na ana ma Eliavu: Nemueli, na Ndathani, na Avilamu. Ndathani na Avilamu nĩo asu, ala manyuviwe nĩ ũmbano, na ala makĩlanilye vinya na Mose na Aluni nguthunĩ ya Kola, yĩla makĩlanilye vinya na Yeova,'),
('kam', 'NUM', 26, 10, 'na nthĩ yaathamya kanyw’a wayo, na yamamelya vamwe na Kola, yila nguthu ĩsu yakwie; ĩvinda yĩla mwaki waminie andũ maana elĩ na mĩongo ĩtano, na matw’ĩkie wonan’yo.'),
('kam', 'NUM', 26, 11, 'Ĩndĩ ana ma Kola matyaakw’a.'),
('kam', 'NUM', 26, 12, 'Ana ma Simeoni kũatĩĩa mĩvĩa yoo nĩ aa: ma Nemueli, mũvĩa wa Anemueli; ma Yamini, mũvĩa wa Ayamini; ma Yakini, mũvĩa wa Ayakini;'),
('kam', 'NUM', 26, 13, 'ma Nzela, mũvĩa wa Anzela; ma Sauli, mũvĩa wa Asauli.'),
('kam', 'NUM', 26, 14, 'Ĩsu nĩyo mĩvĩa ya Asimeoni, ngili mĩongo ĩlĩ na ilĩ na maana elĩ.'),
('kam', 'NUM', 26, 15, 'Ana ma Ngati kũatĩĩa mĩvĩa yoo nĩ aa: ma Nzevoni, mũvĩa wa Anzevoni; ma Aki, mũvĩa wa Aaki, ma Suni, mũvĩa wa Asuni;'),
('kam', 'NUM', 26, 16, 'ma Osini, mũvĩa wa Aosini; ma Eeli, mũvĩa wa Aeeli;'),
('kam', 'NUM', 26, 17, 'ma Aloti, mũvĩa wa Aaloti; ma Aleli, mũvĩa wa Aaleli.'),
('kam', 'NUM', 26, 18, 'Ĩsu nĩyo mĩvĩa ya ana ma Ngati kwĩanana na ala matalilwe moo, ngili mĩongo ĩna na maana atano.'),
('kam', 'NUM', 26, 19, 'Ana ma Yuta nĩ aa: Eeli na Onani; na Eeli na Onani nĩmakw’ĩĩe nthĩ ya Kanaani.'),
('kam', 'NUM', 26, 20, 'Na ana ma Yuta kũatĩĩa mĩvĩa yoo nĩ aa: ma Siela, mũvĩa wa Asiela; ma Velesi, mũvĩa wa Avelesi; ma Nzela mũvĩa wa Anzela.'),
('kam', 'NUM', 26, 21, 'Na ana ma Velesi nĩ aa: ma Esiloni, mũvĩa wa Aesiloni; ma Amuli, mũvĩa wa Aamuli.'),
('kam', 'NUM', 26, 22, 'Ĩsu nĩyo mĩvĩa ya Yuta kwĩanana na ala matalilwe moo, ngili mĩongo mũonza na thanthatũ na maana atano.'),
('kam', 'NUM', 26, 23, 'Ana ma Isakali kũatĩĩa mĩvĩa yoo nĩ aa: ma Tola, mũvĩa wa Atola; ma Vuva, mũvĩa wa Avuni;'),
('kam', 'NUM', 26, 24, 'ma Yasuvu, mũvĩa wa Ayasuvu; ma Similoni, mũvĩa wa Asimiloni.'),
('kam', 'NUM', 26, 25, 'Ĩsu nĩyo mĩvĩa ya Isakali kwĩanana na ala matalilwe moo, ngili mĩongo thanthatũ na inya na maana atatũ.'),
('kam', 'NUM', 26, 26, 'Ana ma Nzevuluni kũatĩĩa mĩvĩa yoo ni aa: ma Seletu, mũvĩa wa Aseletu ma Eloni, mũvĩa wa Aeloni; ma Yaleeli, mũvĩa wa Ayaleeli.'),
('kam', 'NUM', 26, 27, 'Ĩsu nĩyo mĩvĩa ya Anzevuluni kwĩanana na ala matalilwe moo, ngili mĩongo thanthatũ na maana atano.'),
('kam', 'NUM', 26, 28, 'Ana ma Yosevu kũatĩĩa mĩvĩa yoo nĩ aa: Manase na Evalaimu.'),
('kam', 'NUM', 26, 29, 'Ana ma Manase nĩ aa: ma Makili, mũvĩa wa Amakili; na Makili asyaa Ngileati: ma Ngileati, mũvĩa wa Angileati.'),
('kam', 'NUM', 26, 30, 'Aa nĩo ana ma Ngileati: ma Ieseli, mũvĩa wa Aieseli; ma Eleki, mũvĩa wa Aeleki;'),
('kam', 'NUM', 26, 31, 'na ma Asilieli, mũvĩa wa Aasilieli; na ma Sekemu, mũvĩa wa Asekemu;'),
('kam', 'NUM', 26, 32, 'na ma Semita, mũvĩa wa Asemita; na ma Eevieli, mũvĩa wa Aeevieli.'),
('kam', 'NUM', 26, 33, 'Na Nzeloveati mwana wa Eevieli ndaĩ na ana aũme, ate o eĩtu: na masyĩtwa ma eĩtu ma Nzeloveati meetawa Maala, na Noa, na Okila, na Milika, na Tilisa.'),
('kam', 'NUM', 26, 34, 'Ĩsu nĩyo mĩvĩa ya Manase; na ala matalilwe moo maĩ ngili mĩongo ĩtano na ilĩ na maana mũonza.'),
('kam', 'NUM', 26, 35, 'Aa nĩo ana ma Evalaimu kũatĩĩa mĩvĩa yoo: ma Suthela, mũvĩa wa Asuthela; ma Mbekeli, mũvĩa wa Ambekeli; ma Taani, mũvĩa wa Ataani.'),
('kam', 'NUM', 26, 36, 'Na aa nĩo ana ma Suthela: ma Elani, mũvĩa wa Aelani.'),
('kam', 'NUM', 26, 37, 'Ĩsu nĩyo mĩvĩa ya ana ma Evalaimu kwĩanana na ala matalilwe moo, ngili mĩongo ĩtatũ na ilĩ na maana atano. Asu nĩo ana ma Yosevu kũatĩĩa mĩvĩa yoo.'),
('kam', 'NUM', 26, 38, 'Ana ma Mbenyamini kũatĩĩa mĩvĩa yoo nĩ aa: ma Mbela, mũvĩa wa Ambela; ma Asiveli, mũvĩa wa Aasiveli; ma Ailamu, mũvĩa wa Aailamu;'),
('kam', 'NUM', 26, 39, 'ma Suvamu, mũvĩa wa Asuvamu; ma Uvamu, mũvĩa wa Auvamu.'),
('kam', 'NUM', 26, 40, 'Na ana ma Mbela nĩ Aliti na Naamani: ma Aliti, mũvĩa wa Aaliti; ma Naamani, mũvĩa wa Anaamani.'),
('kam', 'NUM', 26, 41, 'Asu nĩ ana ma Mbenyamini kũatĩĩa mĩvĩa yoo; na ala matalilwe moo maĩ ngili mĩongo ĩna na itano na maana thanthatũ.'),
('kam', 'NUM', 26, 42, 'Aa nĩo ana ma Ndani kũatĩĩa mĩvĩa yoo: ma Suamu, mũvĩa wa Asuamu. Ĩsu nĩyo mĩvĩa ya Ndani kũatĩĩa mĩvĩa yoo.'),
('kam', 'NUM', 26, 43, 'Mĩvĩa yonthe ya Asuamu, kwĩanana na ala matalilwe moo maĩ ngili mĩongo thanthatũ na inya na maana ana.'),
('kam', 'NUM', 26, 44, 'Ana ma Aseli kũatĩĩa mĩvĩa yoo nĩ aa: ma Imina, mũvĩa wa Aimina; ma Isiva, mũvĩa wa Aisiva; ma Mbelia, mũvĩa wa Ambelia,'),
('kam', 'NUM', 26, 45, 'Ma ana ma Mbelia nĩ aa: ma Eeveli, mũvĩa wa Aeeveli; ma Malikieli, mũvĩa wa Amalikieli.'),
('kam', 'NUM', 26, 46, 'Na syĩtwa ya mwĩĩtu wa Aseli eetawa Selaa.'),
('kam', 'NUM', 26, 47, 'Ĩsu nĩyo mĩvĩa ya ana ma Aseli kwĩanana na ala matalilwe moo, ngili mĩongo ĩtano na itatũ na maana ana.'),
('kam', 'NUM', 26, 48, 'Ana ma Navitali kũatĩĩa mĩvĩa yoo nĩ aa: ma Yaseeli, mũvĩa wa Ayaseeli; ma Nguni, mũvĩa wa Anguni;'),
('kam', 'NUM', 26, 49, 'ma Yeseli, mũvĩa wa Ayeseli; ma Silemu, mũvĩa wa Asilemu.'),
('kam', 'NUM', 26, 50, 'Ĩsu nĩyo mĩvĩa ya Navitali kwĩanana na mĩvĩa yoo; na ala matalilwe moo maĩ ngili mĩongo ĩna na itano na maana ana.'),
('kam', 'NUM', 26, 51, 'Asu nĩo ala matalilwe ma ana ma Isilaeli, ngili maana thanthatũ na ĩmwe na maana mũonza na mĩongo ĩtatũ.'),
('kam', 'NUM', 26, 52, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 26, 53, 'Andũ asu makaaanw’a nthĩ ĩno yĩthĩwe ũtiĩwa woo kwĩanana na ũtalo wa masyĩtwa moo.'),
('kam', 'NUM', 26, 54, 'Ala aingĩ ũkamanenge ũtiĩwa mwingĩ, na ala anini ũkamanenge ũtiĩwa mũnini: kĩla ũmwe akanengwe ũtiĩwa wake kwĩanana na ũndũ ũtalo wa andũ make wĩana.'),
('kam', 'NUM', 26, 55, 'Ĩndĩ nthĩ ĩkaaanw’a kwa kũlimana: kwĩanana na masyĩtwa ma mbaĩ sya aaĩthe moo makoosa ũtiĩwa woo.'),
('kam', 'NUM', 26, 56, 'O ũndũ kũlimana kũilyĩ nĩw’o ũtiĩwa woo ũkaaanw’a katĩ wa ala aingĩ na ala anini.'),
('kam', 'NUM', 26, 57, 'Na aa nĩo ala matalilwe ma Alivai kũatĩĩa mĩvĩa yoo; ma Ngelisoni, mũvĩa wa Angelisoni; ma Koathi, mũvĩa wa Akoathi; ma Melali, mũvĩa wa Amelali.'),
('kam', 'NUM', 26, 58, 'Ĩno nĩyo mĩvĩa ya Livai: mũvĩa wa Alivini, na mũvĩa wa Aeviloni, na mũvĩa wa Amali, na mũvĩa wa Amusi, na mũvĩa wa Akola. Na Koathi asyaa Amilamu.'),
('kam', 'NUM', 26, 59, 'Na syĩtwa ya mũka wa Amilamu eetawa Yokeveti, mwĩĩtu wa Livai, ũla wasyaĩwe Livai ku Misili: nake amũsyaĩa Amilamu, Aluni na Mose, na Miliamu mwĩĩtu‐a‐ĩnyia woo.'),
('kam', 'NUM', 26, 60, 'Na Aluni asyaa Natavu na Aviu na Eleasali na Ithamali.'),
('kam', 'NUM', 26, 61, 'Na Natavu na Aviu makw’a, yĩla maumĩsye Yeova mwaki ũte wa vo.'),
('kam', 'NUM', 26, 62, 'Na ala matalilwe moo maĩ ngili mĩongo ĩlĩ na itatũ, kĩla mũndũ mũũme o na tũvĩsĩ tũla tũvikĩtye mwei ũmwe na mbee: nũndũ matyaatalanĩlw’a vamwe na ana ma Isilaeli, nũndũ matyaanengwa ũtiĩwa ananĩ ma Isilaeli.'),
('kam', 'NUM', 26, 63, 'Asu nĩo ala matalilwe nĩ Mose na mũthembi Eleasali, ala matalile ana ma Isilaeli ndiĩnĩ sya Moavi, vakuvi na Yolotani ku Yeliko.'),
('kam', 'NUM', 26, 64, 'Ĩndĩ andũnĩ asu kũtyaĩ mũndũ ũmwe woo ũla watalilwe nĩ Mose na mũthembi Aluni, ala matalile ana ma Isilaeli weũnĩ wa Sinai.'),
('kam', 'NUM', 26, 65, 'Nũndũ Yeova nĩwaĩtye ũndũ woo, Vate ndĩi makakw’ĩa weũnĩ. Na vaiaatiwa mũndũ o na ũmwe woo, keka Kalevu mwana wa Yevune, na Yosua mwana wa Nuni.'),
('kam', 'NUM', 27, 1, 'Nĩvo ĩndĩ eĩtu mookie ma Nzeloveati, mwana wa Eevieli, mwana wa Ngileati, mwana wa Makili, mwana wa Manase, ma mĩvĩa ya Manase mwana wa Yosevu; na aa nĩo masyĩtwa ma eĩtu make: Maala, na Noa, na Okila, na Milika, na Tilisa.'),
('kam', 'NUM', 27, 2, 'Na maũngama mbee wa Mose, na mbee wa mũthembi Eleasali, na mbee wa anene na ũmbano w’onthe, mũomonĩ wa ĩeema ya kũmbanĩa, makyasya,'),
('kam', 'NUM', 27, 3, 'Ĩthe waitũ nĩwakw’ĩĩe weũnĩ, na ndaĩ nguthunĩ ya ala mamũmbanĩe Yeova nguthunĩ ya Kola; ĩndĩ akw’ĩa naĩnĩ yake mwene; na ndaĩ na ana aũme.'),
('kam', 'NUM', 27, 4, 'Syĩtwa ya ĩthe waitũ yaĩlwe kũvetwa mũvĩanĩ wake nĩkĩ, nĩkwĩthĩwa ndaĩ na mwana? Tunengei ithyĩ ng’ũndũ katĩ wa ana‐a‐ĩthe ma ĩthe waitũ.'),
('kam', 'NUM', 27, 5, 'Na Mose amũtwaĩa Yeova ũvoo woo.'),
('kam', 'NUM', 27, 6, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 27, 7, 'Eĩtu ma Nzeloveati nĩmeũneena w’o: ndũtĩa ũmanenga kĩlungu kya ũtiĩwa katĩ wa ana‐a‐ĩthe ma ĩthe woo; na nue wĩtuma mosa ũtiĩwa wa ĩthe woo.'),
('kam', 'NUM', 27, 8, 'Na ũkaneene na ana ma Isilaeli, ũkĩmea, Mũndũ akw’a ate na mwana mũndũ mũũme, nĩvo ĩndĩ mũkanenga mwĩĩtu wake ũtiĩwa wake.'),
('kam', 'NUM', 27, 9, 'Na ethĩwa nde na mwĩĩtu, mũkanenge ana‐a‐ĩthe make ũtiĩwa wake.'),
('kam', 'NUM', 27, 10, 'Na ethĩwa nde na ana‐a‐ĩthe, mũkanenge endw’a‐ĩthe ũtiĩwa wake.'),
('kam', 'NUM', 27, 11, 'Na ethĩwa nde na endw’a‐ĩthe, nĩvo ĩndĩ mũkanenga mũndũ wa mbaĩ yake ũla wĩ vakuvĩ nake mũvĩanĩ wake ũtiĩwa wake, nake akawosa wĩthĩwe wake: na ũsu ũkeethĩwa mwamũlo na ũtw’ĩo kwa ana ma Isilaeli, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 27, 12, 'Na Yeova amwĩa Mose, Ũkĩla wambate kĩĩmanĩ kĩĩ kya Avalimu, ũsisye nthĩ ĩla nĩnengete ana ma Isilaeli.'),
('kam', 'NUM', 27, 13, 'Na wamyona, naku ũkoombanw’a vamwe na andũ maku, o tondũ Aluni mwana‐a‐mwenyu wombaniwe;'),
('kam', 'NUM', 27, 14, 'nũndũ nĩmwang’endeie ndeto yakwa weũnĩ wa Nzini, yĩla ũmbano waĩ na ngananĩo, mũtekwonan’ya atĩ nyie nĩ mũtheu mene vau manzini. (Manzĩ asu nĩmo manzĩ ma Meliva ku Katesi, weũnĩ wa Nzini.)'),
('kam', 'NUM', 27, 15, 'Na Mose aneena na Yeova, akĩmwĩa,'),
('kam', 'NUM', 27, 16, 'Yeova, Ngai wa maveva ma mĩĩ yonthe, naie mũndũ ethĩwe mũnene wa ũmbano ũũ,'),
('kam', 'NUM', 27, 17, 'ũla ũtonya kumaalaa mene, na ũla ũtonya kũsyokaa nthĩnĩ mene, na ũla ũtonya kũmatongoeasya maumaale, na ũla ũtonya kũmatũngaa nthĩnĩ; nĩ kana ũmbano wa Yeova ndũkethĩwe ta malondu mate mũĩthi.'),
('kam', 'NUM', 27, 18, 'Na Yeova amwĩa Mose, Osa Yosua mwana wa Nuni, mũndũ ũla wĩ na Veva, na mwilĩĩle kw’oko kwaku;'),
('kam', 'NUM', 27, 19, 'na mwie mbee wa mũthembi Eleasali, na mbee wa ũmbano w’onthe; na mwĩaĩe mene.'),
('kam', 'NUM', 27, 20, 'Na ũkamũolela ndaĩa yaku, nĩ kana andũ onthe ma ũmbano wa ana ma Isilaeli mamwĩw’ae.'),
('kam', 'NUM', 27, 21, 'Nake akaũngama mbee wa mũthembi Eleasali, ũla ũkamũkũlĩlasya vala ve Yeova na sila wa Ulimu: kwondũ wa ndeto yake makaumaalaa, na kwondũ wa ndeto yake makasyokaa nthĩnĩ, we, na ana onthe ma Isilaeli vamwe nake, o ũmbano w’onthe.'),
('kam', 'NUM', 27, 22, 'Na Mose eeka o tondũ Yeova wamwĩaĩe; na amwosa Yosua, na amwia mbee wa mũthembi Eleasali, na mbee wa ũmbano w’onthe:'),
('kam', 'NUM', 27, 23, 'na amwilĩĩla moko make, na amwĩaĩa, o tondũ Yeova waneenie na kanyw’a wa Mose.'),
('kam', 'NUM', 28, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 28, 2, 'Ĩaĩe ana ma Isilaeli, ũmatavye, Nthembo yakwa, lĩu wakwa wa nthembo syakwa ila ivĩvaw’a na mwaki, ila syĩ mũuke mũseo kwakwa, mũkasũvĩe kũnthembea ĩvinda yĩla yasyo.'),
('kam', 'NUM', 28, 3, 'Na ũkamea, Ĩno nĩyo nthembo ĩvĩvaw’a na mwaki ĩla mũkamũthembeaa Yeova: tutũlũme twa mwaka ũmwe tũte kĩema, twilĩ kĩla mũthenya, twĩthĩwe nthembo ya kũvĩvw’a ĩtatw’ĩkanaa.'),
('kam', 'NUM', 28, 4, 'Katũlũme kamwe ũkathembe kĩoko, na katũlũme kangĩ ũkathembe wĩoo;'),
('kam', 'NUM', 28, 5, 'vamwe na kĩlungu kya ĩkũmi kya eva ya mũtu mũvinyu wĩthĩwe nthembo ya mũtu, ũvulanĩtw’e na kĩlungu kya kana kya ini ya mauta makime.'),
('kam', 'NUM', 28, 6, 'Nĩ nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, ĩla yatw’ĩĩwe kĩĩmanĩ kya Sinai yĩthĩwe yĩ mũuke mũseo, nthembo ĩla ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'NUM', 28, 7, 'Na nthembo ya kũnyuwa ya kũthembanĩsya nayo ĩkeethĩwa kĩlungu kya kana kya ini kwondũ wa katũlũme kamwe: nthĩnĩ wa vala vandũ vatheu ũkamwĩtĩe Yeova nthembo ya kũnyuwa ya mbinyu mbĩu.'),
('kam', 'NUM', 28, 8, 'Na katũlũme kala kangĩ ũkathembe wĩoo: o tondũ nthembo ya mũtu ya kĩoko, na nthembo ya kũnyuwa ya kũthembanĩsya nayo syathembiwe, ũkakathembe o ta ũu, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova.'),
('kam', 'NUM', 28, 9, 'Na mũthenya wa savato ũkathembe tũtũlũme twĩlĩ twa mwaka ũmwe tũte kĩema, vamwe na ilungu ilĩ sya eva ya mũtu mũvinyu ũvulanĩtw’e na mauta, wĩthĩwe nthembo ya mũtu, na nthembo ya kũnyuwa ya kũthembanĩsya nayo:'),
('kam', 'NUM', 28, 10, 'ĩsu nĩyo nthembo ya kũvĩvw’a ya kĩla savato, o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 28, 11, 'Na myambĩlĩlyo ya myei yenyu mũkathembee Yeova nthembo ya kũvĩvw’a: tũsalũ twĩlĩ, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 28, 12, 'na ilungu itatũ sya ĩkũmi sya eva ya mũtu mũvinyu ũvulanĩtw’e na mauta, wĩthĩwe nthembo ya mũtu kwondũ wa kĩla kasalũ; na ilungu ilĩ sya mũtu mũvinyu ũvulanĩtw’e na mauta, wĩthĩwe nthembo ya mũtu kwondũ wa ĩla ndũũme;'),
('kam', 'NUM', 28, 13, 'na kĩlungu kya ĩkũmi kya mũtu mũvinyu ũvulanĩtw’e na mauta, wĩthĩwe nthembo ya mũtu kwondũ wa kĩla katũlũme; syĩthĩwe nthembo ya kũvĩvw’a yĩ mũuke mũseo, nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'NUM', 28, 14, 'Na nthembo sya kũnyuwa sya kũthembanĩsya nasyo ikeethĩwa nyunzu ya ini ya mbinyu kwondũ wa kĩla kasalũ, na kĩlungu kya katatũ kya ini kwondũ wa ĩla ndũũme, na kĩlungu kya kana kya ini kwondũ wa kĩla katũlũme: ĩsu nĩyo nthembo ya kũvĩvw’a ya kĩla mwei, myei yonthe ya mwaka.'),
('kam', 'NUM', 28, 15, 'Na nthenge ĩmwe ĩkathembewe. Yeova yĩthĩwe nthembo kwondũ wa naĩ; nayo ĩkathembwa vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 28, 16, 'Na mwei wa mbee, mũthenya wa ĩkũmi na ĩna wa mwei, nĩ vasaka wa Yeova.'),
('kam', 'NUM', 28, 17, 'Na mũthenya wa ĩkũmi na ĩtano wa mwei ũsu ũkeethĩwa wa mboka: kĩmũtũ kĩte ĩlawa kĩkaĩwe mĩthenya mũonza.'),
('kam', 'NUM', 28, 18, 'Mũthenya wa mbee kũkeethĩwa ũmbano mũtheu: mũikatethye wĩa o na wĩva w’onthe;'),
('kam', 'NUM', 28, 19, 'ĩndĩ mũkathembe nthembo ĩvĩvaw’a na mwaki, nthembo ya kũvĩvĩw’a Yeova: tũsalũ twĩlĩ, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe; ikethĩwe ite kĩema kwenyu;'),
('kam', 'NUM', 28, 20, 'na nthembo ya mũtu ya kũthembanĩsya nasyo, mũtu mũvinyu ũvulanĩtw’e na mauta: ilungu itatũ sya ĩkũmi mũkathembe kwondũ wa kĩla kasalũ, na ilungu ĩli sya ĩkũmi kwondũ wa ĩla ndũũme;'),
('kam', 'NUM', 28, 21, 'kĩlungu kya ĩkũmi ũkathembe kwondũ wa kĩla katũlũme ka tũla tũtũlũme mũonza;'),
('kam', 'NUM', 28, 22, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ, ya kwĩw’anĩthw’a kwenyu.'),
('kam', 'NUM', 28, 23, 'Mũkathembe isu o vamwe na nthembo ya kũvĩvw’a ya kĩoko, nayo nĩ nthembo ya kũvĩvw’a ĩtatw’ĩkanaa.'),
('kam', 'NUM', 28, 24, 'Ũu nĩw’o mwĩthemba kĩla mũthenya, ĩvinda ya mĩthenya mũonza, lĩu wa nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova: ĩkathembwa vamwe na nthembo ya kũvĩvw’a ĩtatw’ikanaa, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 28, 25, 'Na mũthenya wa mũonza mũkeethĩwa na ũmbano mũtheu; mũtikatethye wĩa o na wĩva w’onthe.'),
('kam', 'NUM', 28, 26, 'Na ĩngĩ mũthenya wa mosyao ma mbee, yĩla mwĩmũthembea Yeova nthembo ya mũtu mweũ mbokanĩ yenyu ya syumwa, mũkeethĩwa na ũmbano mũtheu; mũtikatethye wĩa o na wĩva w’onthe;'),
('kam', 'NUM', 28, 27, 'ĩndĩ mũkathembe nthembo ya kũvĩvw’a yĩthĩwe yĩ mũuke mũseo kwa Yeova: tũsalũ twĩlĩ, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe;'),
('kam', 'NUM', 28, 28, 'na nthembo ya mũtu ya kũthembanĩsya nasyo, mũtu mũvinyu ũvulanĩtw’e na mauta, ilungu itatũ sya ĩkũmi kwondũ wa kĩla kasalũ, na ilungu ilĩ sya ĩkũmi kwondũ wa ĩla ndũũme ĩmwe,'),
('kam', 'NUM', 28, 29, 'na kĩlungu kya ĩkũmi kwondũ wa kĩla katũlũme ka tũla tũtũlũme mũonza;'),
('kam', 'NUM', 28, 30, 'na nthenge ĩmwe yĩthĩwe nthembo ya kwĩw’anĩthw’a kwenyu.'),
('kam', 'NUM', 28, 31, 'O vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, mũkaithembe na nthembo sya kũnyuwa sya kũthembanĩsya nasyo (ikethĩwe ite kĩema kwenyu).'),
('kam', 'NUM', 29, 1, 'Na mwei wa mũonza, mũthenya wa mbee wa mwei, mũkeethĩwa na ũmbano mũtheu; mũtikatethye wĩa o na wĩva w’onthe: kwenyu nĩ mũthenya wa kũvuva masoo.'),
('kam', 'NUM', 29, 2, 'Na mũkathembe nthembo ya kũvĩvw’a yĩthĩwe yĩ mũuke mũseo kwa Yeova: kasalũ kamwe, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 3, 'na nthembo ya mũtu ya kũthembanĩsya nasyo, mũtu mũvinyu ũvulanĩtw’e na mauta, ilungu itatũ sya ĩkũmi kwondũ wa kala kasalũ, na ilungu ilĩ sya ĩkũmi kwondũ wa ĩla ndũũme,'),
('kam', 'NUM', 29, 4, 'na kĩlungu kĩmwe kya ĩkũmi kwondũ wa kĩla katũlũme ka tũla tũtũlũme mũonza;'),
('kam', 'NUM', 29, 5, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ, ya kwĩw’anĩthw’a kwenyu;'),
('kam', 'NUM', 29, 6, 'o vamwe na nthembo ya kũvĩvw’a ya mũtiso wa mwei, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo sya kũnyuwa sya kũthembanĩsya nasyo, kwĩanana na ũtw’ĩo wasyo syĩthĩwe mũuke mũseo, nthembo ĩvĩvĩaw’a Yeova na mwaki.'),
('kam', 'NUM', 29, 7, 'Na mũthenya wa ĩkũmi wa mwei ũsu wa mũonza mũkeethĩwa na ũmbano mũtheu; na mwĩĩthĩn’ye ngoo syenyu: mũtikatethye wĩa o na wĩva;'),
('kam', 'NUM', 29, 8, 'ĩndĩ mũkamũthembee Yeova nthembo ya kũvĩvw’a yĩthĩwe yĩ mũuke mũseo: kasalũ kamwe, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe; ikethĩwe kwenyu ite kĩema;'),
('kam', 'NUM', 29, 9, 'na nthembo ya mũtu ya kũthembanĩsya nasyo, mũtu mũvinyu ũvulanĩtw’e na mauta, ilungu itatũ sya ĩkũmi kwondũ wa kala kasalũ, na ilungu ilĩ sya ĩkũmi kwondũ wa ĩla ndũũme,'),
('kam', 'NUM', 29, 10, 'na kĩlungu kya ĩkũmi kwondũ wa kĩla katũlũme ka tũla tũtũlũme mũonza:'),
('kam', 'NUM', 29, 11, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo kwondũ wa naĩ ya kwĩw’anĩthya, na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo sya kũnyuwa sya kũthembanĩsya nasyo.'),
('kam', 'NUM', 29, 12, 'Na mũthenya wa ĩkũmi na ĩtano wa mwei wa mũonza mũkeethĩwa na ũmbano mũtheu; mũtikatethye wĩa o na wĩva w’onthe, na mũkeethĩwa na mboka mĩthenya mũonza kwondũ wa Yeova:'),
('kam', 'NUM', 29, 13, 'na mũkathembe nthembo ya kũvĩvw’a, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova; tũsalũ ĩkũmi na tũtatũ, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe; nasyo ikethĩwe ite kĩema;'),
('kam', 'NUM', 29, 14, 'na nthembo ya mũtu ya kũthembanĩsya nasyo, mũtu mũvinyu ũvulanĩtw’e na mauta, ilungu itatũ sya ĩkũmi kwondũ wa kĩla kasalũ ka tũla tũsalũ ĩkũmi na tũtatũ, na ilungu ilĩ sya ĩkũmi kwondũ wa kĩla ndũũme ya ila ndũũme ilĩ,'),
('kam', 'NUM', 29, 15, 'na kĩlungu kya ĩkũmi kwondũ wa kĩla katũlũme ka tũla tũtũlũme ĩkũmi na tũna;'),
('kam', 'NUM', 29, 16, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na ĩla nthembo ya kũvivw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 17, 'Na mũthenya wa kelĩ mũkathembe tũsalũ ĩkũmi na twĩlĩ, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema:'),
('kam', 'NUM', 29, 18, 'na nthembo ya mũtu ya kũthembanĩsya nasyo na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa tũsalũ tũu, na kwondũ wa ndũũme ĩsu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 19, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo sya kũnyuwa sya kũthembanĩsya nasyo.'),
('kam', 'NUM', 29, 20, 'Na mũthenya wa katatũ mũkathembe tũsalũ ĩkũmi na kamwe, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 21, 'na nthembo ya mũtu na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa tũsalũ tũu, na kwondũ wa ndũũme isu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 22, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 23, 'Na mũthenya wa kana mũkathembe tũsalũ ĩkũmi, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 24, 'na nthembo ya mũtu na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa tũsalũ tũu, na kwondũ wa ndũũme isu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 25, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 26, 'Na mũthenya wa katano mũkathembe tũsalũ kenda, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 27, 'na nthembo ya mũtu na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa tũsalũ tũũ, na kwondũ wa ndũũme isu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 28, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 29, 'Na mũthenya wa thanthatũ mũkathembe tũsalũ nyanya, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 30, 'na nthembo ya mũtu na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa tũsalũ tũu, na kwondũ wa ndũũme isu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 31, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo sya kũnyuwa sya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 32, 'Na mũthenya wa mũonza mũkathembe tũsalũ mũonza, na ndũũme ilĩ, na tũtũlũme ĩkũmi na tũna twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 33, 'na nthembo ya mũtu na nthembo sya kũnyuwa kwondũ wa tũsalũ tũu, na kwondũ wa ndũũme isu, na kwondũ wa tũtũlũme tũu, kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo;'),
('kam', 'NUM', 29, 34, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 35, 'Mũthenya wa nyanya mũkeethĩwa na ũmbano ũkilĩtye: mũtikatethye wĩa o na wĩva w’onthe;'),
('kam', 'NUM', 29, 36, 'ĩndĩ mũkathembe nthembo ya kũvĩvw’a, nthembo ĩvĩvaw’a na mwaki, yĩ mũuke mũseo kwa Yeova: kasalũ kamwe ka mũew’a, na ndũũme ĩmwe, na tũtũlũme mũonza twa mwaka ũmwe tũte kĩema;'),
('kam', 'NUM', 29, 37, 'na nthembo ya mũtu ya kũthembanĩsya nasyo na nthembo sya kũnyuwa sya kũthembanĩsya nasyo kwondũ wa kasalũ kau, na kwondũ wa ĩla ndũũme, na kwondũ wa tũtũlũme tũu, syĩthĩwe kwĩanana na ũtalo wasyo, kũatĩĩa ũla ũtw’ĩo:'),
('kam', 'NUM', 29, 38, 'na nthenge ĩmwe yĩthĩwe nthembo kwondũ wa naĩ; o vamwe na nthembo ya kũvĩvw’a ĩtatw’ĩkanaa, na nthembo ya mũtu ya kũthembanĩsya nayo, na nthembo ya kũnyuwa ya kũthembanĩsya nayo.'),
('kam', 'NUM', 29, 39, 'Isu mũkathembee Yeova ĩvinda ya mboka syenyu ila itw’ĩtwe, o vamwe na mawĩvĩto menyu, na nthembo syenyu ila mumasya na ngoo ya kwenda, syĩthĩwe nthembo syenyu sya kũvĩvw’a, na nthembo syenyu sya mũtu, na nthembo syenyu sya kũnyuwa, na nthembo syenyu sya mũuo.'),
('kam', 'NUM', 29, 40, 'Na Mose amatavya ana ma Isilaeli kwĩanana na w’onthe ũla Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 30, 1, 'Na Mose aneena na atongoi ma mbaĩ sya ana ma Isilaeli, akĩmea, Ũũ nĩw’o Yeova weaie.'),
('kam', 'NUM', 30, 2, 'Yĩla mũndũ mũũme ũkevĩtĩa Yeova wĩvĩto kana kwĩyĩava wĩavo wa kwova ngoo yake na wovo, ndakaeke ndeto yake; akeke kwĩanana na w’onthe ũla wumaa kanyw’anĩ wake.'),
('kam', 'NUM', 30, 3, 'Na ĩngĩ yĩla mũndũ mũka ũkevĩtĩa Yeova wĩvĩto, na kwĩyova na wovo, e nyũmbanĩ ya ĩthe wake, wĩĩtunĩ wake,'),
('kam', 'NUM', 30, 4, 'na ĩthe wake akĩw’a wĩvĩto wake, na kwĩyova kwake kũla wĩyovete ngoo yake nakw’o, na ĩthe wake akamũvindĩsya; nĩvo ĩndĩ mawĩvĩto make onthe makekala, na kĩla wovo ũla wĩyovethetye ngoo yake naw’o ũkekala.'),
('kam', 'NUM', 30, 5, 'Ĩndĩ ethĩwa ĩthe wake akamũvata mũthenya o ũla wĩĩw’a, mawĩvĩto make o na ũmwe, kana mawovo make o na ũmwe, ala wĩyovethetye ngoo yake namo, matikekala: na Yeova akamũekea, nũndũ ĩthe wake nĩwamũvatie.'),
('kam', 'NUM', 30, 6, 'Na ethĩwa nake nĩ mũtwae, yĩla wĩ na mawĩvĩto make, kana ndeto sya ilomo syake ila ũneenete ateũsũanĩa, ila wĩyovethetye ngoo yake nasyo,'),
('kam', 'NUM', 30, 7, 'na mũũme akawĩw’a, na kũmũvindĩsya mũthenya ũla wĩĩw’a; nĩvo ĩndĩ mawĩvĩto make makekala, na mawovo make ala wĩyovethetye ngoo yake namo makekala.'),
('kam', 'NUM', 30, 8, 'Ĩndĩ ethĩwa mũũme akamũvata mũthenya o ũla wĩĩw’a, nĩvo ĩndĩ ũkatw’ĩkĩthya wĩvĩto wake ũla wĩ naw’o wĩthĩwe wa mana, na ndeto syake ila ũneenete na ilomo syake ateũsũanĩa, ila wĩyovethetye ngoo yake nasyo: na Yeova akamũekea.'),
('kam', 'NUM', 30, 9, 'Ĩndĩ wĩvĩto wa mũndũ mũka ndiwa, kana wa ũla ũtaanĩsye na mũũme, o kĩla ũndũ ũla weyovethisye ngoo yake naw’o, ũkekala.'),
('kam', 'NUM', 30, 10, 'Na ethĩwa nĩmevĩtĩie e kwa mũũme, kana nĩweyovethisye ngoo yake na wovo wa wĩvĩto,'),
('kam', 'NUM', 30, 11, 'na mũũme awĩw’a, na amũvindĩsya, na ndaamũvata; nĩvo ĩndĩ mawĩvĩto make onthe makekala, na kĩla wovo ũla wĩyovethetye ngoo yake naw’o ũkekala.'),
('kam', 'NUM', 30, 12, 'Ĩndĩ ethĩwa mũũme wake nĩwamatw’ĩkĩthisye ma mana vyũ mũthenya o ũsu ũla wamewie, nĩvo ĩndĩ ũndũ o na wĩva w’onthe ũla wumĩte ilomonĩ syake ũndũ wa mawĩvĩto make, kana ũndũ wa wĩyovethyo wa ngoo yake, ũteĩkala; mũũme wake nũmatw’ĩkĩthĩtye ma mana; na Yeova akamũekea.'),
('kam', 'NUM', 30, 13, 'Kĩla wĩvĩto, na kĩla wĩavo wa kwĩyovethya wa kũthĩn’ya ngoo, mũũme wake nũtonya kũwũlũmya, kana mũũme wake nũtonya kũwũtw’ĩkĩthya wa mana.'),
('kam', 'NUM', 30, 14, 'Ĩndĩ ethĩwa mũũme wake akamũvindĩsya ki mĩthenya yonthe, nĩvo ĩndĩ ũnũũlũlũmĩlya mawĩvĩto make onthe, kana mawĩyovethyo make onthe ala wĩ namo: nũmalũlũmĩlye nũndũ nĩwamũvindĩsye mũthenya ũla wamewie.'),
('kam', 'NUM', 30, 15, 'Ĩndĩ ethĩwa akamatw’ĩkĩthya ma mana vyũ ĩtina wa kũmew’a, nĩvo ĩndĩ wĩkua ũthũku wa mũka.'),
('kam', 'NUM', 30, 16, 'Asu nĩmo myamũlo, ala Yeova wamwĩaĩe Mose, katĩ wa mũndũ na mũka, na katĩ wa ĩthe na mwĩĩtu wake, e wĩĩtunĩ wake, kwa ĩthe wake.'),
('kam', 'NUM', 31, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 31, 2, 'Ĩvanĩsya ana ma Isilaeli kwa Amitiani: ĩtina ũkoombanw’a vamwe na andũ maku.'),
('kam', 'NUM', 31, 3, 'Na Mose aneena na andũ, akĩmea, Mekĩei andũ ala mwĩumya katĩ wenyu mĩio ya kaũ, nĩ kana mathi kũkita na Amitiani, meanĩsye ũĩvanĩsyo wa Yeova ĩũlũ wa Mitiani.'),
('kam', 'NUM', 31, 4, 'Mũkatwae kaũnĩ andũ ngili ya kĩla mbaĩ, nthĩnĩ wa mbaĩ syonthe sya Isilaeli.'),
('kam', 'NUM', 31, 5, 'Kwondũ wa ũu nĩkwaumw’a nthĩnĩ wa ngili sya Isilaeli, ngili ĩmwe ya kĩla mbaĩ, andũ ngili ĩkũmi na ilĩ ila syĩkĩĩtwe mĩio ya kaũ.'),
('kam', 'NUM', 31, 6, 'Na Mose amatũma, ngili ĩmwe ya kĩla mbaĩ, mo na Vineasi mwana wa mũthembi Eleasali, maende kaũnĩ, e na mĩio ya vala vandũ vatheu na masoo me wasya wa kũtĩsya kw’okonĩ kwake.'),
('kam', 'NUM', 31, 7, 'Na mokita na Mitiani, o tondũ Yeova wamwĩaĩe Mose; na mooaa aũme onthe.'),
('kam', 'NUM', 31, 8, 'Na mooaa asumbi ma Mitiani vamwe na ala angĩ oae: nao nĩ Evi, na Lekemu, na Nzuli, na Uulu, na Leva, asumbĩ atano ma Mitiani: o na Mbalaamu mwana wa Mbeoli mamũaa na ũvyũ.'),
('kam', 'NUM', 31, 9, 'Na ana ma Isilaeli matava aka ma Mitiani na syana syoo nini; na ng’ombe syoo syonthe, na ndĩthya syoo syonthe sya mbũi na malondu, na syĩndũ syoo syonthe, matava mũtavo.'),
('kam', 'NUM', 31, 10, 'Na ndũa syoo syonthe kũndũ kũla matũaa, na myako yoo yonthe ya maeema, mavĩvya na mwaki.'),
('kam', 'NUM', 31, 11, 'Nao mamakũũta syĩndũ syonthe, na matava mũtavo, wa mũndũ na wa nyamũ.'),
('kam', 'NUM', 31, 12, 'Na maete andũ ala atave, na syĩndũ ila makũũtanĩte, na syĩndũ ila matavĩte, vala ve Mose, na vala ve mũthembi Eleasali, na vala ve ũmbano wa ana ma Isilaeli, mwakonĩ wa maeema ndiĩnĩ sya Moavi ila syĩ vakuvĩ na Yolotani ku Yeliko.'),
('kam', 'NUM', 31, 13, 'Na Mose, na mũthembi Eleasali, na anene onthe ma ũmbano, maumaala mamathaũe ũtee wa mwako wa maeema.'),
('kam', 'NUM', 31, 14, 'Na Mose amathilĩkĩa anene ma ĩla nguthu, o makavuteni ma ngili ngili na makavuteni ma maana, ala maumie wĩanĩ wa kaũ.'),
('kam', 'NUM', 31, 15, 'Na Mose amakũlya, Nĩmwavonokisye aka onthe, mũkĩmaeka me thayũ?'),
('kam', 'NUM', 31, 16, 'Sisyai, asu nĩo mavĩtĩthisye ana ma Isilaeli, nũndũ wa ũtao wa Mbalaamu, mamũvĩtanĩsye Yeova ũvoonĩ wa Veoli, na kwondũ wa ũu mũimũ waĩ ũmbanonĩ wa Yeova.'),
('kam', 'NUM', 31, 17, 'Yu ĩndĩno ũaai kĩla kana ka kavĩsĩ, na ũaai kĩla mũndũ mũka ũla wamanyie mũndũ mũũme ũndũ wa ũkoma nake.'),
('kam', 'NUM', 31, 18, 'Ĩndĩ twana tw’onthe twa twĩlĩtu, tũla tũtaamanya mũndũ mũũme ũndũ wa ũkoma nake, tũekei twĩ thayũ twĩthĩwe twenyu.'),
('kam', 'NUM', 31, 19, 'Na ĩkalai ũtee wa mwako wa maeema mĩthenya mũonza: o ũla ũaĩte mũndũ o na wĩva, na o ũla ũkiitĩte mũndũ o na wĩva ũla ũaĩtwe, ĩthesyei mũthenya wa katatũ na mũthenya wa mũonza, inyw’ĩ na ala mũtavĩte.'),
('kam', 'NUM', 31, 20, 'Na ũndũ wa kĩla ngũa, na kyonthe kĩla kĩtumĩtwe kya mbũa, na kyonthe kĩla kĩtumĩtwe kya w’ĩa wa mbũi, na syĩndũ syonthe iseũvĩtw’e sya mĩtĩ, mũkaithesye inyw’ĩ.'),
('kam', 'NUM', 31, 21, 'Na mũthembi Eleasali amea andũ ma kaũ ala maendie kũkita, Ũu nĩw’o mwamũlo wa mwĩao ũla Yeova wamwĩaĩte Mose:'),
('kam', 'NUM', 31, 22, 'ĩndĩ thaavu, na vetha, na ũthuku, na kĩaa, na kĩaa kya ivava, na ĩvulũ,'),
('kam', 'NUM', 31, 23, 'kĩla kĩndũ kĩtonya kũmĩĩsya mwaki, mũkakĩvĩtĩlye mwakinĩ, na kĩkeethĩwa kĩ kĩtheu; ĩndĩ kĩkathew’a nĩ manzĩ ala ma ũthesya ũvuku: na kyonthe kĩla kĩtatonya kũmĩĩsya mwaki mũkakĩvĩtĩlye manzĩnĩ.'),
('kam', 'NUM', 31, 24, 'Na mũkathambye ngũa syenyu mũthenya wa mũonza, na mũkeethĩwa mwĩ atheu; na ĩtina mũkasyoka mwakonĩ wa maeema.'),
('kam', 'NUM', 31, 25, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 31, 26, 'Tala ũtalo wa mũtavo ũla wataviwe, wa andũ na wa nyamũ, we, na mũthembi Eleasali, na atongoi ma nyũmba sya aaĩthe ma ũmbano;'),
('kam', 'NUM', 31, 27, 'na aan’ya mũtavo ilungu ilĩ: katĩ wa andũ ala oĩ kaũnĩ ala maendie kũkita, na ũmbano w’onthe.'),
('kam', 'NUM', 31, 28, 'Na mumĩsye Yeova mũvothi wa andũ ma kaũ ala maendie kũkita: thayũ ũmwe nthĩnĩ wa mathayũ maana atano, nthĩnĩ wa andũ, o na nthĩnĩ wa ng’ombe, na nthĩnĩ wa mang’oi, na nthĩnĩ wa ndĩthya sya mbũi na malondu:'),
('kam', 'NUM', 31, 29, 'osa nthĩnĩ wa nyunzu yoo na mũnenge mũthembi Eleasali, wĩthĩwe nthembo ya kũkĩlĩlw’a Yeova.'),
('kam', 'NUM', 31, 30, 'Na nthĩnĩ wa nyunzu ya ana ma Isilaeli, osa ũmwe nthĩnĩ wa kĩla mĩongo ĩtano, nthĩnĩ wa andũ, na nthĩnĩ wa ng’ombe, na nthĩnĩ wa mang’oi, na nthĩnĩ wa ndĩthya sya mbũi na malondu, o nthĩnĩ wa indo syonthe, na ũimanenga Alivai, ala masũvĩaa wĩaĩo wa wĩkalo wa Yeova.'),
('kam', 'NUM', 31, 31, 'Na Mose na mũthembi Eleasali meeka o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 31, 32, 'Na ĩndĩ matialyo ala matialile, mũtavo wavetwa ũla wosiwe nĩ andũ ma kaũ, maĩ malondu ngili maana thanthatũ na mĩongo mũonza na atano,'),
('kam', 'NUM', 31, 33, 'na ng’ombe ngili mĩongo mũonza na ilĩ,'),
('kam', 'NUM', 31, 34, 'na mang’oi ngili mĩongo thanthatũ na ĩmwe,'),
('kam', 'NUM', 31, 35, 'na aka ngili mĩongo ĩtatũ na ilĩ ala mataamanya mũndũ mũũme ũndũ wa ũkoma nake.'),
('kam', 'NUM', 31, 36, 'Na nyunzu, ĩla yaĩ ya ala maendie kaũnĩ, ĩkĩtalwa yaĩ malondu ngili maana atatũ na mĩongo ĩtatũ na mũonza na maana atano:'),
('kam', 'NUM', 31, 37, 'na mũvothi wa Yeova wa malondu waĩ maana thanthatũ na mĩongo mũonza na atano.'),
('kam', 'NUM', 31, 38, 'Na ng’ombe syaĩ ngili mĩongo ĩtatũ na thanthatũ; na mũvothi wa Yeova wa isu waĩ mĩongo mũonza na ilĩ.'),
('kam', 'NUM', 31, 39, 'Na mang’oi maĩ ngili mĩongo ĩtatũ na maana atano; na mũvothi wa Yeova wamo waĩ mĩongo thanthatũ na yĩmwe.'),
('kam', 'NUM', 31, 40, 'Na andũ maĩ ngili ĩkũmi na thanthatũ; na mũvothi wa Yeova wa asu waĩ andũ mĩongo ĩtatũ na elĩ.'),
('kam', 'NUM', 31, 41, 'Na Mose anenga mũthembi Eleasali ũla mũvothi, ũla waĩ nthembo ya kũkĩlĩlw’a Yeova, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 31, 42, 'Na nthĩnĩ wa nyunzu ĩla yaĩ ya ana ma Isilaeli, ĩla Mose wavathanisye kumya andũnĩ ala maĩ kaũnĩ'),
('kam', 'NUM', 31, 43, '(na ĩndĩ nyunzu ĩla yaĩ ya ũmbano yaĩ malondu ngili maana atatũ na mĩongo ĩtatũ na mũonza na maana atano,'),
('kam', 'NUM', 31, 44, 'na ng’ombe ngili mĩongo ĩtatũ na thanthatũ'),
('kam', 'NUM', 31, 45, 'na mang’oi ngili mĩongo ĩtatũ na maana atano,'),
('kam', 'NUM', 31, 46, 'na andũ ngili ĩkũmi na thanthatũ),'),
('kam', 'NUM', 31, 47, 'o nthĩnĩ wa nyunzu ĩsu ĩla yaĩ ya ana ma Isilaeli, Mose oosa ũmwe nthĩnĩ wa kĩla mĩongo ĩtano, wa andũ na wa nyamũ, na amanenga Alivai ala masũvĩaa wĩaĩo wa wĩkalo wa Yeova, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'NUM', 31, 48, 'Na anene ma ngili sya ĩ nguthu, o makavuteni ma ngili ngili, na makavuteni ma maana, mamũthengeea Mose;'),
('kam', 'NUM', 31, 49, 'na mamwĩa Mose, Ithyĩ athũkũmi maku, nĩtũtalĩte andũ ma kaũ ala me ĩtheo waitũ, na vati mũndũ o na ũmwe waitũ ũte vaa.'),
('kam', 'NUM', 31, 50, 'Na nĩtwaete ũelo wa kũmũthembea Yeova, o syĩndũ ila kĩla mũndũ wonete, mĩio ya wanake ya thaavu, mĩnyoo ya maũũ, na itang’a, na ngome sya ũvana ũsiĩlo na ngome sya matũ, na mĩnyoo ya ngingo, syĩthĩwe sya kũtwĩw’anĩthya mathayũ maitũ na Yeova.'),
('kam', 'NUM', 31, 51, 'Na Mose na mũthembi Eleasali moosa thaavu woo, o mĩio yonthe ya wanake ya thaavu ĩla ĩseũvĩtwe nesa'),
('kam', 'NUM', 31, 52, 'Na thaavu w’onthe wa nthembo ya kũkĩlw’a ũla mamũthembee Yeova, ũla wa makavuteni ma ngili ngili na wa makavuteni ma maana, waĩ sekeli ngili ĩkũmi na thanthatũ na maana mũonza na mĩongo ĩtano.'),
('kam', 'NUM', 31, 53, '(Nũndũ andũ ma kaũ maĩ manoosa mũtavo, kĩla mũndũ wake mwene.)'),
('kam', 'NUM', 31, 54, 'Na Mose na mũthembi Eleasali moosa thaavu wa makavuteni ma ngili ngili na ma maana, na mootwaa nthĩnĩ wa ĩeema ya kũmbanĩa, wĩthĩwe ũlilikan’yo kwondũ wa ana ma Isilaeli vu mbee wa Yeova.'),
('kam', 'NUM', 32, 1, 'Na ĩndĩ ana ma Leuveni na ana ma Ngati maĩ na indo nyingĩ mũno; na yĩla moonie nthĩ ya Yaseli, na nthĩ ya Ngileati, kana, sisya, nĩ vandũ va kũĩthĩsya indo;'),
('kam', 'NUM', 32, 2, 'ana ma Ngati na ana ma Leuveni mooka na maneena na Mose, na mũthembi Eleasali, na anene ma ũmbano, makĩmea,'),
('kam', 'NUM', 32, 3, 'Atalothi, na Ndivoni, na Yaseli na Nimila, na Esivoni, na Eleale, na Sevamu, na Nevo, na Mbeoni,'),
('kam', 'NUM', 32, 4, 'nthĩ ĩla Yeova wakũnie ũmbano wa Isilaeli wene, nĩ nthĩ ya ũĩthĩsya indo; na ithyĩ athũkũmi maku twĩ na indo.'),
('kam', 'NUM', 32, 5, 'Na masya, Ethĩwa nĩtwonete ũseo methonĩ maku, nthĩ ĩno ĩnengwe ithyĩ athũkũmi maku yĩthĩwe ng’ũndũ yaitũ; ndũkatũingye Yolotani.'),
('kam', 'NUM', 32, 6, 'Na Mose amakũlya ana ma Ngati na ana ma Leuveni, Ana‐a‐ĩthe menyu makathi kaũnĩ, na inyw’ĩ mũkekala vaa?'),
('kam', 'NUM', 32, 7, 'Na nũndũ wa kĩ mũũtuma ana ma Isilaeli makw’a ngoo matikainge malike nthĩ ĩla Yeova ũmanengete?'),
('kam', 'NUM', 32, 8, 'Ũu nĩw’o aaĩthe menyu meekie, yĩla namatũmie kuma Katesi‐mbalinea mathi mathiane nthĩ.'),
('kam', 'NUM', 32, 9, 'Nũndũ yĩla maendie na malika kyandanĩ kya Esikoli, na moona nthĩ, matuma ngoo sya ana ma Isilaeli ikw’a, matikalike nthĩ ĩla Yeova ũmanengete.'),
('kam', 'NUM', 32, 10, 'Na ũthatu wa Yeova wakana mũthenya ũsu, na eevĩta, akyasya,'),
('kam', 'NUM', 32, 11, 'Nĩ w’o, vati mũndũ o na ũmwe ũla waumie Misili, ũla ũvikĩtye myaka mĩongo ĩlĩ na mbee, ũkona nthĩ ĩla namathie Avalaamu, na Isaka, na Yakovo; nũndũ matyaambikĩla ki:'),
('kam', 'NUM', 32, 12, 'ate o Kalevu mwana wa Yevune Mũkenisi, na Yosua mwana wa Nuni; nĩkwĩthĩwa nĩmamũvikĩlaa Yeova ki.'),
('kam', 'NUM', 32, 13, 'Na ũthatu wa Yeova wakanĩa Isilaeli, na atuma manganga kũũ na kũũ weũnĩ myaka mĩongo ĩna, kũvika nzyawa ĩsu yonthe yathela ĩla yeekie naĩ Yeova ene.'),
('kam', 'NUM', 32, 14, 'Na, sisyai, inyw’ĩ nĩmũkĩlĩte vandũ va aaĩthe menyu, wingĩvo wa andũ athe, o kwongelela ũthatu mwai wa Yeova kwa Isilaeli.'),
('kam', 'NUM', 32, 15, 'Nũndũ ethĩwa mũkeethyũũa na kũeka kũmũatĩĩa, akamatia ĩngĩ weũnĩ; na inyw’ĩ mũkaananga andũ aa onthe.'),
('kam', 'NUM', 32, 16, 'Na mamũthengeea, na mamwĩa, Tũkaaka syengo vaa ũndũ wa indo sitũ, na ndũa ũndũ wa syana sitũ nini:'),
('kam', 'NUM', 32, 17, 'ĩndĩ ithyĩ ene tũkeeyũmban’ya twĩ na mĩio ya kaũ kũmatongoesya ana ma Isilaeli, kũvika yĩla twĩmavikya vandũ voo: na syana sitũ nini ikekala ndũanĩ isu mbiie nũndũ wa andũ ala matwĩe nthĩ ĩsu.'),
('kam', 'NUM', 32, 18, 'Tũtikasyoka nyũmbanĩ sitũ, kũvika ana ma Isilaeli o kĩla mũndũ akeethĩwa akwatĩte ũtiĩwa wake.'),
('kam', 'NUM', 32, 19, 'Nũndũ tũtikosa ũtiĩwa vamwe namo mũingo ũla ũngĩ wa Yolotani, na vau mbee; nũndũ kwatw’ĩkie ũtiĩwa witũ wĩ mũingo ũũ wa Yolotani kwelekela wumĩlonĩ wa syũa.'),
('kam', 'NUM', 32, 20, 'Na Mose amea, Ethĩwa mũkeeka ũu, ethĩwa mũkeekĩa mĩio ya kaũ mũthi kaũnĩ mwenekee nĩ Yeova,'),
('kam', 'NUM', 32, 21, 'na kĩla mũndũ wenyu ũla wĩ na mĩio ya kaũ akainga Yolotani enekee nĩ Yeova, kũvika amina kũlũngya amaitha make mbee wake,'),
('kam', 'NUM', 32, 22, 'na nthĩ ĩsu ĩkakĩlw’a vinya Yeova ene; ĩtina wa ũu ĩndĩ mũkasyoka, na mũkeethĩwa mũte na ĩvĩtyo vala ve Yeova, kana vala ve Isilaeli; na nthĩ ĩno ĩkeethĩwa ng’ũndũ yenyu Yeova ene.'),
('kam', 'NUM', 32, 23, 'Ĩndĩ ethĩwa mũtikeka ũu, sisyai, nĩmwamũvĩtanĩsya Yeova; na manyai vate ndĩi naĩ syenyu ikamũkwata.'),
('kam', 'NUM', 32, 24, 'Akĩai syana syenyu nini ndũa, na malondũ menyu syengo; na ĩkai o tondũ mwaisye na makanyw’a menyu.'),
('kam', 'NUM', 32, 25, 'Na ana ma Ngati na ana ma Leuveni maneena na Mose, makĩmwĩa, Ithyĩ athũkũmi maku tũkeeka o tondũ mwĩaĩi wakwa ũtwĩaĩĩte.'),
('kam', 'NUM', 32, 26, 'Syana sitũ nini, na iveti sitũ, na ndĩthya sitũ sya mbũi na malondu, na indo sitũ syonthe, ikekala vo ndũanĩ sya Ngileati;'),
('kam', 'NUM', 32, 27, 'ĩndĩ ithyĩ athũkũmi maku tũkainga, kĩla mũndũ ũla wĩkĩĩte mĩio ya kaũ, enekee nĩ Yeova, aendete kaũnĩ, o tondũ mwĩaĩi wakwa ũneenete.'),
('kam', 'NUM', 32, 28, 'Kwondũ wa ũu Mose eeaĩa mũthembi Eleasali, na Yosua mwana wa Nuni, na atongoi ma nyũmba sya aaĩthe ma mbaĩ sya ana ma Isilaeli, ũndũ woo.'),
('kam', 'NUM', 32, 29, 'Na Mose amea, Ethĩwa ana ma Ngati na ana ma Leuveni makainga Yolotani vamwe nenyu, kĩla mũndũ ũla wĩkĩĩte mĩio ya kaũ, enekee nĩ Yeova, na nthĩ ĩkakĩlw’a vinya nĩ inyw’ĩ; nĩvo ĩndĩ mũkamanenga nthĩ ya Ngileati ĩthĩwe ng’ũndũ yoo:'),
('kam', 'NUM', 32, 30, 'ĩndĩ ethĩwa matikainga nenyu mekĩe mĩio ya kaũ, makeethĩwa na ng’ũndũ syoo katĩ wenyu nthĩ ya Kanaani.'),
('kam', 'NUM', 32, 31, 'Na ana ma Ngati na ana ma Leuveni masũngĩa, makyasya, O ũndũ Yeova wameie athũkũmi maku, tũkeeka o ũu.'),
('kam', 'NUM', 32, 32, 'Tũkainga twĩkĩĩte mĩio ya kaũ twenekee nĩ Yeova tũlike nthĩ ya Kanaani, na ng’ũndũ ya ũtiĩwa witũ ĩkeethĩwa mũingo wa Yolotani.'),
('kam', 'NUM', 32, 33, 'Na Mose amanenga, o ana asu ma Ngati, na ana ma Leuveni, na nyunzu ya mbaĩ ya Manase mwana wa Yosevu, ũsumbĩ wa Sioni mũsumbĩ wa Aamoli, na ũsumbĩ wa Oku mũsumbĩ wa Mbasani, nthĩ ĩsu, kwĩanana na ndũa syayo vamwe na mĩvaka yasyo, o ndũa sya nthĩ ĩla ĩthyũlũlũkĩte ngalĩ syonthe.'),
('kam', 'NUM', 32, 34, 'Na ana ma Ngati maaka Ndivoni, na Atalothi, na Aloeli,'),
('kam', 'NUM', 32, 35, 'na Atilothi‐sovani, na Yaseli, na Yokivea,'),
('kam', 'NUM', 32, 36, 'na Mbethinimila, na Mbethi‐aalani: ndũa mbiie, na syengo sya malondu.'),
('kam', 'NUM', 32, 37, 'Na ana ma Leuveni maaka Esivoni, na Eleale, na Kiliathaimu,'),
('kam', 'NUM', 32, 38, 'na Nevo, na Mbaalimeoni, (masyĩtwa masyo makĩalyũlwa,) na Sivima: na ndũa ila maakie nĩmaitw’ĩĩe masyĩtwa angĩ,'),
('kam', 'NUM', 32, 39, 'Na ana ma Makili mwana wa Manase mathi Ngileati, na mamĩkwata, na malũngya Aamoli ala matwĩe vo.'),
('kam', 'NUM', 32, 40, 'Na Mose anenga Makili mwana wa Manase nthĩ ya Ngileati; nake atũa vo.'),
('kam', 'NUM', 32, 41, 'Na Yaili mwana wa Manase athi na akwata tũtũla twayo, na atwĩta Avothi‐yaili.'),
('kam', 'NUM', 32, 42, 'Na Nova athi na akwata Kenathi, na mĩsyĩ yayo, na amĩta Nova, aimĩtanĩsya na syĩtwa yake mwene.'),
('kam', 'NUM', 33, 1, 'Ii nĩsyo syalo sya ana ma Isilaeli, yĩla maumie nthĩ ya Misili o ũndũ nguthu syoo syailyĩ syatongoew’e nĩ Mose na Aluni.'),
('kam', 'NUM', 33, 2, 'Na Mose aandĩka ũndũ maumie kwĩanana na syalo syoo o tondũ Yeova weaie: na ii nĩsyo syalo syoo o ũndũ kumaala kwoo kwailyĩ.'),
('kam', 'NUM', 33, 3, 'Na mathi kyalo kuma Lamesesi mwei wa mbee, mũthenya wa ĩkũmi na ĩtano wa mwei wa mbee; ũnĩ ũsu ĩtina wa vasaka ana ma Isilaeli mauma na kw’oko kwĩ vinya menekee nĩ Amisili onthe,'),
('kam', 'NUM', 33, 4, 'yĩla Amisili mathikaa makithathi moo onthe, ala Yeova wakũnĩte katĩ woo: o na ngai syoo Yeova aisilĩla.'),
('kam', 'NUM', 33, 5, 'Na ana ma Isilaeli mathi kyalo kuma Lamesesi, na mamba maeema moo Sukothi.'),
('kam', 'NUM', 33, 6, 'Na mathi kyalo kuma Sukothi, na mamba maeema moo Ethamu, kũla kwĩ ũtee wa weũ.'),
('kam', 'NUM', 33, 7, 'Na mathi kyalo kuma Ethamu, na masyoka kũvika Viailothi, ndũa ĩla yĩ vakuvĩ na Mbaalinzevoni: na mamba maeema moo vakuvĩ na Militoli.'),
('kam', 'NUM', 33, 8, 'Na mathi kyalo kuma vakuvĩ na Ailothi, na mavĩta ũkanganĩ katĩ malika weũnĩ: na mathi weũnĩ wa Ethamu kyalo kya mĩthenya ĩtatũ, na mamba maeema moo Mala.'),
('kam', 'NUM', 33, 9, 'Na mathi kyalo kuma Mala, na mavika Elimu: na vu Elimu vaĩ mbuluti ĩkũmi na ilĩ sya manzĩ, na mĩtende mĩongo mũonza; na mamba maeema moo vo.'),
('kam', 'NUM', 33, 10, 'Na mathi kyalo kuma Elimu, na mamba maeema moo vakuvĩ na Ũkanga Mũtune.'),
('kam', 'NUM', 33, 11, 'Na mathi kyalo kuma Ũkanga Mũtune, na mamba maeema moo weũnĩ wa Sini.'),
('kam', 'NUM', 33, 12, 'Na mathi kyalo kuma weũnĩ wa Sini, na mamba maeema moo Ndovika.'),
('kam', 'NUM', 33, 13, 'Na mathi kyalo kuma Ndovika, na mamba maeema moo Alusi.'),
('kam', 'NUM', 33, 14, 'Na mathi kyalo kuma Alusi, na mamba maeema moo Levitimu, vala vatai manzĩ ma kũnyuwa nĩ andũ.'),
('kam', 'NUM', 33, 15, 'Na mathi kyalo kuma Levitimu, na mamba maeema moo weũnĩ wa Sinai.'),
('kam', 'NUM', 33, 16, 'Na mathi kyalo kuma weũnĩ wa Sinai, na mamba maeema moo Kivilothi‐ataava.'),
('kam', 'NUM', 33, 17, 'Na mathi kyalo kuma Kivilothi‐ataava, na mamba maeema moo Aaselothi.'),
('kam', 'NUM', 33, 18, 'Na mathi kyalo kuma Aaselothi, na mamba maeema moo Lithima.'),
('kam', 'NUM', 33, 19, 'Na mathi kyalo kuma Lithima, na mamba maeema moo Limonivelesi.'),
('kam', 'NUM', 33, 20, 'Na mathi kyalo kuma Limonivelesi, na mamba maeema moo Livina.'),
('kam', 'NUM', 33, 21, 'Na mathi kyalo kuma Livina, na mamba maeema moo Lisa.'),
('kam', 'NUM', 33, 22, 'Na mathi kyalo kuma Lisa, na mamba maeema moo Keelatha.'),
('kam', 'NUM', 33, 23, 'Na mathi kyalo kuma Keelatha, na mamba maeema moo kĩĩmanĩ kya Sieveli.'),
('kam', 'NUM', 33, 24, 'Na mathi kyalo kuma kĩĩmanĩ kya Sieveli, na mamba maeema moo Alata.'),
('kam', 'NUM', 33, 25, 'Na mathi kyalo kuma Alata, na mamba maeema moo Makelothi.'),
('kam', 'NUM', 33, 26, 'Na mathi kyalo kuma Makelothi, na mamba maeema moo Taathi.'),
('kam', 'NUM', 33, 27, 'Na mathi kyalo kuma Taathi, na mamba maeema moo Tela.'),
('kam', 'NUM', 33, 28, 'Na mathi kyalo kuma Tela, na mamba maeema moo Mithika.'),
('kam', 'NUM', 33, 29, 'Na mathi kyalo kuma Mithika, na mamba maeema moo Asimona.'),
('kam', 'NUM', 33, 30, 'Na mathi kyalo kuma Asimona, na mamba maeema moo Moselothi.'),
('kam', 'NUM', 33, 31, 'Na mathi kyalo kuma Moselothi, na mamba maeema moo Mbene‐yaakani.'),
('kam', 'NUM', 33, 32, 'Na mathi kyalo kuma Mbene‐yaakani, na mamba maeema moo Olu‐akitikati.'),
('kam', 'NUM', 33, 33, 'Na mathi kyalo kuma Olu‐akitikati, na mamba maeema moo Yotivatha.'),
('kam', 'NUM', 33, 34, 'Na mathi kyalo kuma Yotivatha, na mamba maeema moo Avilona.'),
('kam', 'NUM', 33, 35, 'Na mathi kyalo kuma Avilona, na mamba maeema moo Esioni‐ngeveli.'),
('kam', 'NUM', 33, 36, 'Na mathi kyalo kuma Esioni‐ngeveli, na mamba maeema moo weũnĩ wa Nzini (naw’o nĩ Katesi).'),
('kam', 'NUM', 33, 37, 'Na mathi kyalo kuma Katesi, na mamba maeema moo kĩĩmanĩ kya Olu, mũvakanĩ wa nthĩ ya Etomu.'),
('kam', 'NUM', 33, 38, 'Na mũthembi Aluni ambata kĩĩmanĩ kya Olu ũndũ wa mwĩao wa Yeova, na akw’ĩa vo, myaka mĩongo ĩna ĩtina wa ana ma Isilaeli mauma nthĩ ya Misili, mwei wa katano, mũthenya wa mbee wa mwei.'),
('kam', 'NUM', 33, 39, 'Na Aluni aĩ wa myaka ĩana yĩmwe na mĩongo ĩlĩ na ĩtatũ yĩla wakw’ĩĩe kĩĩmanĩ kya Olu.'),
('kam', 'NUM', 33, 40, 'Na Mũkanaani, mũsumbĩ wa Alati, ũla watwĩe ngalĩ ya ĩtheo nthĩ ya Kanaani, eew’a ũvoo wa kũka kwa ana ma Isilaeli.'),
('kam', 'NUM', 33, 41, 'Na mathi kyalo kuma kĩĩmanĩ kya Olu, na mamba maeema moo Nzalimona.'),
('kam', 'NUM', 33, 42, 'Na mathi kyalo kuma Nzalimona, na mamba maeema moo Vunoni.'),
('kam', 'NUM', 33, 43, 'Na mathi kvalo kuma Vunoni, na mamba maeema moo Ovothi.'),
('kam', 'NUM', 33, 44, 'Na mathi kyalo kuma Ovothi, na mamba maeema moo Iye‐avalimu, mũvakanĩ wa Moavi.'),
('kam', 'NUM', 33, 45, 'Na mathi kyalo kuma Iimu, na mamba maeema moo Ndivoni‐ngati.'),
('kam', 'NUM', 33, 46, 'Na mathi kyalo kuma Ndivoni‐ngati, na mamba maeema moo Alimoni‐ndivilathaimu.'),
('kam', 'NUM', 33, 47, 'Na mathi kyalo kuma Alimoni‐ndivilathaimu, na mamba maeema moo iĩmanĩ sya Avalimu, vakuvĩ na Nevo.'),
('kam', 'NUM', 33, 48, 'Na mathi kyalo kuma iĩmanĩ sya Avalimu, na mamba maeema moo ndiĩnĩ sya Moavi vakuvĩ na Yolotani ku Yeliko.'),
('kam', 'NUM', 33, 49, 'Na mamba maeema moo vakuvĩ na Yolotani, kuma Mbethiyesimothi o kũvika Aveli‐sitimu ndiĩnĩ sya Moavi.'),
('kam', 'NUM', 33, 50, 'Na Yeova aneenea na Mose ndiĩnĩ sya Moavi vakuvĩ na Yolotani ku Yeliko, akĩmwĩa,'),
('kam', 'NUM', 33, 51, 'Neena na ana ma Isilaeli, ũkĩmea, Yĩla mwĩinga Yolotani mũlike nthĩ ya Kanaani,'),
('kam', 'NUM', 33, 52, 'nĩvo ĩndĩ mwĩlũngya andũ onthe ala matwĩe nthĩ ĩsu maume mbee wenyu, na kwananga mavia moo onthe ala mavanĩtwe mĩvw’anano, na kwananga mĩvw’anano yoo yonthe mĩseũvye na syĩndũ matwekethetye, na kwananga kũndũ kwoo kw’onthe kũla kũtũlu:'),
('kam', 'NUM', 33, 53, 'nenyu mũkamesya nthĩ ĩsu, na kũmĩtĩnĩka; nũndũ nĩnĩmũnengete inyw’ĩ nthĩ ĩsu mũmĩmesye.'),
('kam', 'NUM', 33, 54, 'Na inyw’ĩ mũkaaan’ya nthĩ ĩsu kwondũ wa kũlimana kwĩanana na mĩvĩa yenyu; ala aingĩ mũkamanenga ũtiĩwa mwingĩ, na ala anini mũkamanenga ũtiĩwa mũnini: o vala vakatw’ĩka va mũndũ kwondũ wa kũlimana, vau vakeethĩwa vake; kwĩanana na mbaĩ sya aaĩthe menyu now’o mũkosa ũtiĩwa.'),
('kam', 'NUM', 33, 55, 'Ĩndĩ ethĩwa mũtikalũngya andũ ala matwĩe nthĩ ĩsu maume mbee wenyu, nĩvo ĩndĩ ala mũkamaeka vo makeethĩwa ta tũmĩkuva twa kũtonya metho menyu, na ta mĩw’a mbaunĩ syenyu, na makamũthĩnĩsya nthĩ ĩsu ĩla mũtũĩte.'),
('kam', 'NUM', 33, 56, 'Na kũkeethĩwa, kana, o ũndũ nasũanĩa kũmeka, now’o ngamwĩka inyw’ĩ.'),
('kam', 'NUM', 34, 1, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 34, 2, 'Ĩaĩe ana ma Isilaeli, noimea, Yĩla mũkalika nthĩ ya Kanaani (nĩyo nthĩ ĩla ĩkethĩwa yenyu ya ũtiĩwa, o nthĩ ya Kanaani kwĩanana na mĩvaka yayo),'),
('kam', 'NUM', 34, 3, 'nĩvo ĩndĩ kĩlungu kyenyu kya ngalĩ ya ĩtheo kĩkethĩwa kuma weũ wa Nzini kũvĩtĩla ũtee wa Etomu, na mũvaka wenyu wa ngalĩ ya ĩtheo ũkeethĩwa kuma mũminĩo wa Ũkanga wa Mũnyũ kwelekela ngalĩ ya wumĩlonĩ wa syũa;'),
('kam', 'NUM', 34, 4, 'na mũvaka wenyu ũkasyoka kwelekela ngalĩ ya ĩtheo kyambatonĩ kya Akilavimu, na kũvĩta kũvika Nzini; na umĩlĩlo waw’o ũkeethĩwa ngalĩ ya ĩtheo ya Katesi‐mbalinea; noivĩta kũvika Asali‐atali, na kũvĩta kũvika Asimoni;'),
('kam', 'NUM', 34, 5, 'na mũvaka ũkasyoka kuma Asimoni kũvika kalũsĩ ka Misili, na ũmĩlĩlo waw’o ũkeethĩwa ũkanganĩ.'),
('kam', 'NUM', 34, 6, 'Na mũvaka wenyu wa ngalĩ ya ũthũĩlonĩ wa syũa ũkeethĩwa nĩ ũkanga mũnene o ngũkanĩ yaw’o: ũsu ũkeethĩwa mũvaka wenyu wa ũthũĩlonĩ wa syũa.'),
('kam', 'NUM', 34, 7, 'Na mũvaka wenyu wa ngalĩ ya ĩũlũ nĩ ũũ: kuma ũkanga mũnene mũkeekĩa mũvaka kũvika kĩĩma kya Olu;'),
('kam', 'NUM', 34, 8, 'kuma kĩĩmanĩ kya Olu mũkeekĩa mũvaka kũvika ũlikĩlonĩ wa Amathi; na ũmĩlĩlo wa mũvaka ũkeethĩwa Nzetati;'),
('kam', 'NUM', 34, 9, 'na mũvaka ũkavĩta na kũthi Nzĩviloni, na ũmĩlĩlo waw’o ũkeethĩwa Asali‐enani: ũu nĩw’o ũkethĩwa mũvaka wenyu wa ngalĩ ya ĩũlũ.'),
('kam', 'NUM', 34, 10, 'Na mũkeekĩa mũvaka wenyu wa ngalĩ ya wũmĩlonĩ wa syũa kuma Asali‐enani kũvika Seviamu;'),
('kam', 'NUM', 34, 11, 'na mũvaka ũkatheea kuma Seviamu kũvika Livila, ngalĩ ya wumĩlonĩ wa syũa ya Aini; na mũvaka ũkatheea, na kũvika ũtee wa ũkanga wa Kinelethi kwelekela ngalĩ ya wũmĩlonĩ wa syũa;'),
('kam', 'NUM', 34, 12, 'na mũvaka ũkatheelela Yolotani, na umĩlĩlo waw’o ũkeethĩwa Ũkanganĩ wa Mũnyũ. Ĩsu ĩkeethĩwa nthĩ yenyu kwĩanana na mĩvaka yayo ngalĩ syonthe.'),
('kam', 'NUM', 34, 13, 'Na Mose ameaĩa ana ma Isilaeli, akĩmea, Ĩno nĩyo nthĩ ĩla mũkatiĩwa kwondũ wa kũlimana, ĩla Yeova weaie ĩnengwe ila mbaĩ kenda, na nyunzu ya mbaĩ:'),
('kam', 'NUM', 34, 14, 'nũndũ mbaĩ ya ana ma Leuveni kwĩanana na nyũmba sya aaĩthe moo, na mbaĩ ya ana ma Ngati kwĩanana na nyũmba sya aaĩthe moo, nĩsyosete, na ĩla nyunzu ya mbaĩ ya Manase nĩyosete, utiĩwa wasyo:'),
('kam', 'NUM', 34, 15, 'mbaĩ isu syelĩ na ĩ nyunzu ya mbaĩ nĩsyosete ũtiĩwa wasyo mũingo wa Yolotani ku Yeliko ngalĩ ya wumĩlonĩ wa syũa, kwelekela vala syũa yumĩlaa.'),
('kam', 'NUM', 34, 16, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 34, 17, 'Aa nĩo masyĩtwa ma andũ ala makamũaan’ya nthĩ yĩthĩwe ũtiĩwa wenyu: mũthembi Eleasali, na Yosua mwana wa Nuni.'),
('kam', 'NUM', 34, 18, 'Na mũkose mũnene ũmwe wa kĩla mbaĩ, maaan’ye nthĩ ĩsu yĩthĩwe ũtiĩwa.'),
('kam', 'NUM', 34, 19, 'Na aa nĩmo masyĩtwa ma andũ asu: Wa mbaĩ ya Yuta, Kalevu mwana wa Yevune.'),
('kam', 'NUM', 34, 20, 'Na wa mbaĩ ya ana ma Simeoni, Semueli mwana wa Amiuti.'),
('kam', 'NUM', 34, 21, 'Na wa mbaĩ ya Mbenyamini, Elitati mwana wa Kisiloni.'),
('kam', 'NUM', 34, 22, 'Na wa mbaĩ ya ana ma Ndani, mũnene Mbuki mwana wa Yokili.'),
('kam', 'NUM', 34, 23, 'Na wa ana ma Yosevu: wa mbaĩ ya ana ma Manase, mũnene Anieli mwana wa Evoti.'),
('kam', 'NUM', 34, 24, 'Na wa mbaĩ ya ana ma Evalaimu, mũnene Kemueli mwana wa Sivitani.'),
('kam', 'NUM', 34, 25, 'Na wa mbaĩ ya ana ma Nzevuloni, mũnene Elisavani mwana wa Valanaki.'),
('kam', 'NUM', 34, 26, 'Na wa mbaĩ ya ana ma Isakali, mũnene Valitieli mwana wa Asiani.'),
('kam', 'NUM', 34, 27, 'Na wa mbaĩ ya ana ma Aseli, mũnene Aiuti mwana wa Selomi.'),
('kam', 'NUM', 34, 28, 'Na wa mbaĩ ya ana ma Navitali, mũnene Vetaeli mwana wa Amiuti.'),
('kam', 'NUM', 34, 29, 'Asu nĩmo ala Yeova weaie mamaaan’ye ana ma Isilaeli ũtiĩwa nthĩ ya Kanaani.'),
('kam', 'NUM', 35, 1, 'Na Yeova aneenea na Mose ndiĩnĩ sya Moavi vakuvĩ na Yolotani ku Yeliko, akĩmwĩa,'),
('kam', 'NUM', 35, 2, 'Meaĩe ana ma Isilaeli mamanenge Alivai ndũa sya kũtũa nthĩnĩ wa ũtiĩwa wa ng’ũndũ syoo; na mũkanenge Alivai syengo ila ithyũlũlũkĩtye ndũa ngalĩ syonthe.'),
('kam', 'NUM', 35, 3, 'Na ndũa isu ikeethĩwa syoo sya kũtũa; na syengo isu ikeethĩwa sya indo syoo, na sya ũthwii woo, na sya nyamũ syoo syonthe.'),
('kam', 'NUM', 35, 4, 'Na syengo sya ndũa isu, ila mũkanenga Alivai, ikeethĩwa kuma ũvainĩ wa ndũa kũthyũlũlũka ngalĩ syonthe mĩkono ngili ĩmwe.'),
('kam', 'NUM', 35, 5, 'Na mũkathime ũtee wa ndũa mĩkono ngili ili ngalĩ ya wumĩlonĩ wa syũa, na ngalĩ ya ĩtheo mĩkono ngili ilĩ, na ngalĩ ya ũthũĩlonĩ wa syũa mĩkono ngili ilĩ, na ngalĩ ya ĩũlũ mĩkono ngili ilĩ, na ndũa ĩkeethĩwa yĩ katĩ. Ũu nĩw’o syengo sya ndũa ikethĩwa iilyĩ kwoo.'),
('kam', 'NUM', 35, 6, 'Na ndũa ila mũkanenga Alivai, ikeethĩwa ndũa thanthatũ sya kwĩvitha, ila mũkanengane kwondũ wa mũndũ ũla ũkoaa ũngĩ akĩĩae vo: na vamwe na isu mũkanengane ndũa ingĩ mĩongo ĩna na ilĩ.'),
('kam', 'NUM', 35, 7, 'Ndũa syonthe ila mũkanenga Alivai ikeethĩwa mĩongo ĩna na nyanya; nĩsyo mũkamanenga vamwe na syengo syasyo.'),
('kam', 'NUM', 35, 8, 'Na ũndũ wa ndũa ila mũkanengane kuma nthĩnĩ wa ng’ũndũ ya ana ma Isilaeli, kuma kwa andũ aingĩ mũkoosa ndũa nyingĩ; na kuma kwa andũ anini mũkoosa nini: kĩla mũndũ akanenga Alivai ndũa imwe syake, kwĩanana na ũtiĩwa wake ũla watiĩwe.'),
('kam', 'NUM', 35, 9, 'Na Yeova aneena na Mose, akĩmwĩa,'),
('kam', 'NUM', 35, 10, 'Neena na ana ma Isilaeli, noimea, Yĩla mwĩinga Yolotani mũlike nthĩ ya Kanaani,'),
('kam', 'NUM', 35, 11, 'nĩvo ĩndĩ mwĩia ndũa syĩthĩwe ndũa sya kwĩvitha kwondũ wenyu, nĩ kana mũndũ ũla ũkoaa mũndũ o na wĩva na mbanga akĩĩae vo.'),
('kam', 'NUM', 35, 12, 'Na ndũa isu ikeethĩwa kwenyu kwondũ wa kũmwĩvitha mũĩvanĩsya, nĩ kana mũndũ ũla ũkoaa ũngĩ ndakoawe, atanaũngama mbee wa ũmbano asilĩlwe.'),
('kam', 'NUM', 35, 13, 'Na ndũa ila mũkanengane ikeethĩwa kwenyu ndũa thanthatũ sya kwĩvitha.'),
('kam', 'NUM', 35, 14, 'Mũkanengane ndũa itatũ mũingo wa Yolotani; na mũkanengane ndũa itatũ nthĩ ya Kanaani; isu ikeethĩwa ndũa sya kwĩvitha.'),
('kam', 'NUM', 35, 15, 'Ndũa isu thanthatũ ikeethĩwa sya kwĩvitha kwondũ wa ana ma Isilaeli, na kwondũ wa mũeni, na kwondũ wa mwĩkali wa ũeninĩ wĩ kwoo; nĩ kana kĩla mũndũ ũla ũkoaa mũndũ o na wĩva na mbanga akĩĩae vo.'),
('kam', 'NUM', 35, 16, 'Ĩndĩ ethĩwa nĩwamũkũna na kĩndũ kya kĩaa, na akw’a, ũsu mũkũnani nĩ mũaani: mũaani nde ndĩi ya kũlea kũawa.'),
('kam', 'NUM', 35, 17, 'Na ethĩwa nĩwamũkima na ĩvia akwete na kw’oko kwake, yĩla yĩtonya kũaa mũndũ, na akw’a, ũsu mũkimani nĩ mũaani: mũaani nde ndĩi ya kũlea kũawa.'),
('kam', 'NUM', 35, 18, 'Kana ethĩwa nĩwamũkũna na kĩndũ kya mũtĩ akwete kw’okonĩ, kĩla kĩtonya kũaa mũndũ, na akw’a, ũsu mũkũnani nĩ mũaani: mũaani nde ndĩi ya kũlea kũawa.'),
('kam', 'NUM', 35, 19, 'Mũĩvanĩsya wa nthakame we mwene akooaa mũaani ũsu: akomana nake akamũaa.'),
('kam', 'NUM', 35, 20, 'Na ethĩwa nĩwamũluuta nũndũ wa kũmũmena, kana kũmwĩkya kĩndũ, amwoveesye, na kwondũ wa ũu aikw’a,'),
('kam', 'NUM', 35, 21, 'kana ethĩwa nĩwamũkũna na kw’oko kwondũ wa ũthũ, na kwondũ wa ũu aikw’a; ũla wamũkũna nde ndĩi ya kũlea kũawa; ũsu mũkũnani nĩ mũaani: mũĩvanĩsya wa nthakame akoaa mũaani ũsu, o yĩla wĩkomana nake.'),
('kam', 'NUM', 35, 22, 'Ĩndĩ ethĩwa nĩwamũluuta na kĩthũlũmũkĩlo vate ũthũ, kana kũmwĩkya kĩndũ vate kũmwoveesya,'),
('kam', 'NUM', 35, 23, 'kana ĩvia o na yĩva, yĩla yĩtonya kũaa mũndũ, na akamwĩkya, atamwene, na kwondũ wa ũu aikw’a, na ti nthũ yake, o na ndaamantha kũmwĩka ũndũ ũthũku;'),
('kam', 'NUM', 35, 24, 'nĩvo ĩndĩ ũmbano ũkamasilan’ya ũla mũkũnani na mũĩvanĩsya wa nthakame, kwĩanana na motw’ĩo aa;'),
('kam', 'NUM', 35, 25, 'na ũmbano ũkamũvonokya mũaani kũmumya kw’okonĩ kwa mũĩvanĩsya wa nthakame, na ũmbano ũkamũtũnga ndũanĩ yake ya kwĩvitha, vala wakĩĩe: na akekala nthĩnĩ wayo kũvika yĩla mũthembi mũnene ũkakw’a ũla wetĩkĩw’e mauta matheu.'),
('kam', 'NUM', 35, 26, 'Ĩndĩ ethĩwa mũaani o na ĩndĩĩ akakĩla mũvaka wa ndũa yake ya kwĩvitha, vala wakĩĩe,'),
('kam', 'NUM', 35, 27, 'na mũĩvanĩsya wa nthakame akamwona akĩlĩte mũvaka wa ndũa yake ya kwĩvitha, na mũĩvanĩsya wa nthakame akoaa ũla mũaani; ndakethĩwae na ĩvĩtyo kwondũ wa nthakame ĩsu,'),
('kam', 'NUM', 35, 28, 'nĩkwĩthĩwa ũsu nĩwaĩlwe nĩ kwĩkala ndũanĩ yake ya kwĩvitha kũvika yĩla mũthembi mũnene ũkakw’a: ĩndĩ mũthembi mũnene akw’a ũla mũaani akasyoka nthĩ ĩla ya ng’ũndũ yake.'),
('kam', 'NUM', 35, 29, 'Na maũndũ asu makeethĩwa kwenyu mwamũlo na ũtw’ĩo mosyaanĩonĩ menyu onthe motũonĩ menyu onthe.'),
('kam', 'NUM', 35, 30, 'O ũla ũkoaa mũndũ o na wĩva, mũaani ũsu akooawa nũndũ wa makanyw’a ma ngũsĩ: ĩndĩ ngũsĩ ĩmwe yĩ yoka ndĩkamũkũsĩĩe mũndũ o na wĩva oawe.'),
('kam', 'NUM', 35, 31, 'Na ĩngĩ mũtikose mbovosya kwondũ wa thayũ wa mũaani, ũla wonekete nĩwaĩlwe nĩ kũawa; ĩndĩ mũndũ ũsu nde ndĩi ya kũlea kũawa.'),
('kam', 'NUM', 35, 32, 'Na mũtikose mbovosya kwondũ wa ũla wakĩĩe ndũanĩ yake ya kwĩvitha, nĩ kana asyoke kwĩkala nthĩ yake, mũthembi atanakw’a.'),
('kam', 'NUM', 35, 33, 'Na ĩndĩ mũtikavukye nthĩ ĩla mũtwĩe: nũndũ nthakame, nĩyo ĩvukasya nthĩ; na vai nthembo yumaw’a kwondũ wa nthĩ ũndũ wa nthakame ĩla yetĩkiwe vo, keka o nthakame ya ũla wamĩtĩkisye.'),
('kam', 'NUM', 35, 34, 'Na mũtikavukye nthĩ ĩla mũtũĩte, ĩla nyie nĩtũaa nthĩnĩ wayo: nũndũ nyie, Yeova, nĩtũaa katĩ wa ana ma Isilaeli.'),
('kam', 'NUM', 36, 1, 'Na atongoi ma nyũmba sya aaithe ma mũvia wa ana ma Ngileati, mwana wa Makili, mwana wa Manase, ma mĩvĩa ya ana ma Yosevu, mathengeea, na maneena vala ve Mose, na vala ve anene, ala atongoi ma nyũmba sya aaĩthe ma ana ma Isilaeli:'),
('kam', 'NUM', 36, 2, 'na masya, Yeova amwĩaĩe mwĩaĩi wakwa amanenge ana ma Isilaeli nthĩ yĩthĩwe ũtiĩwa woo kwondũ wa kũlimana: na mwĩaĩi wakwa eeaĩwa nĩ Yeova atĩ ũtiĩwa wa Nzeloveati mwana‐a‐ĩthe waitũ ũnengwe eĩtu make.'),
('kam', 'NUM', 36, 3, 'Na ethĩwa makatwawa nĩ ana o na meva ma mbaĩ ila ingĩ sya ana ma Isilaeli, nĩvo ĩndĩ ũtiĩwa woo ũkoswa kumw’a nthĩnĩ wa ũtiĩwa wa aaĩthe maitũ, na ũkongelelwa ũtiĩwanĩ wa mbaĩ ĩla matwaĩtwe nĩyo: o ta ũu ũkoswa nthĩnĩ wa ũtiĩwa witũ, ũla twoosie kwondũ wa kũlimana.'),
('kam', 'NUM', 36, 4, 'Na yĩla yuvilii wa ana ma Isilaeli ũkavika, nĩvo ĩndĩ ũtiĩwa woo ũkongelelwa ũtiĩwanĩ wa mbaĩ ĩla matwaĩtwe nĩyo: kwondũ wa ũu ũtiĩwa woo ũkoswa kumw’a ũtiĩwanĩ wa mbaĩ ya aaĩthe maitũ.'),
('kam', 'NUM', 36, 5, 'Na Mose eeaĩa ana ma Isilaeli kwĩanana na ndeto ya Yeova, akĩmea, Mbaĩ ya ana ma Yosevu nĩnĩũneena w’o.'),
('kam', 'NUM', 36, 6, 'Ũũ nĩw’o ũla Yeova wĩaĩte ũndũ wa eĩtu ma Nzeloveati, akyasya, Nĩmatwawe nĩ aũme ala mekwenda: ĩndĩ no matwawe mũvĩani wa mbaĩ ya ĩthe woo.'),
('kam', 'NUM', 36, 7, 'Kwondũ wa ũu vai ũtiĩwa wa ana ma Isilaeli ũkaumw’a mbaĩnĩ ĩmwe kũthi mbaĩnĩ ĩngĩ; nũndũ ana ma Isilaeli makakwatana kĩla mũndũ na ũtiĩwa wa mbaĩ ya aaĩthe make.'),
('kam', 'NUM', 36, 8, 'Na kĩla mwĩĩtu ũla ũkethĩwa na ũtiĩwa mbaĩnĩ o na yĩva ya ana ma Isilaeli, akatwawa nĩ mũndũ wa mũvĩa wa mbaĩ ya ĩthe wake, nĩ kana ana ma Isilaeli kĩla mũndũ akwate ũtiĩwa wa aaĩthe make.'),
('kam', 'NUM', 36, 9, 'Kwondũ wa ũu kũikethĩwa ũtiĩwa o na wĩva ũkyumw’a mbaĩnĩ ĩmwe kũtwawa mbaĩnĩ ĩngĩ; nũndũ mbaĩ sya ana ma Isilaeli ikalũman’ya kĩla ĩmwe na ũtiĩwa wayo.'),
('kam', 'NUM', 36, 10, 'O ũndũ Yeova wamwĩaĩe Mose, now’o eĩtu ma Nzeloveati meekie:'),
('kam', 'NUM', 36, 11, 'nũndũ Maala, na Tilisa, na Okila, na Milika, na Noa, eĩtu ma Nzeloveati, nĩmatwaiwe nĩ ana ma endw’a‐ĩthe.'),
('kam', 'NUM', 36, 12, 'Nĩmatwaiwe mĩvĩanĩ ya ana ma Manase mwana wa Yosevu; na ũtiĩwa woo wekalile mbaĩnĩ ya mũvĩa wa ĩthe woo.'),
('kam', 'NUM', 36, 13, 'Ĩsu nĩyo mĩao na motw’ĩo ala Yeova weaĩe ana ma Isilaeli na kanyw’a wa Mose ndiĩnĩ sya Moavi vakuvĩ na Yolotani ku Yeliko.'),
('kam', 'DEU', 1, 1, 'Ii nĩsyo ndeto ila Mose waneenie na Isilaeli onthe mũingo wa Yolotani weũnĩ, mwandanĩ wa Alava ũla welekele Suvu, katĩ wa Valani, na Toveli, na Lavani, na Aaselothi, na Ndi‐saavu.'),
('kam', 'DEU', 1, 2, 'Nĩ mũendo wa mĩthenya ĩkũmi na ũmwe kuma Olevu kũthi na nzĩa ya kĩĩma kya Seili kũvika Katesi‐mbalinea.'),
('kam', 'DEU', 1, 3, 'Na kweethĩwa mwaka wa mĩongo ĩna, mwei wa ĩkũmi na ũmwe, mũthenya wa mbee wa mwei, Mose aneena na ana ma Isilaeli, kwĩanana na w’onthe ũla wataviw’e nĩ Yeova ameaĩe;'),
('kam', 'DEU', 1, 4, 'ĩtina wa kũmũkũna Sioni mũsumbĩ wa Aamoli, ũla watwĩe Esivoni, na Oku mũsumbĩ wa Mbasani, ũla watwĩe Asetalothi, vu Etilei.'),
('kam', 'DEU', 1, 5, 'Mũingo wa Yolotani, nthĩ ya Moavi, Mose ambĩlĩlya kũtavan’ya mĩao ĩno, akyasya,'),
('kam', 'DEU', 1, 6, 'Yeova Ngai waitũ nĩwaneenee naitũ Olevu, akyasya, Kũtũa kwenyu kwa kĩĩmanĩ kĩĩ nĩkweanĩa:'),
('kam', 'DEU', 1, 7, 'ĩthyũũei, mũkwate kyalo kyenyu, mũthi nthĩ ya Aamoli ĩla yĩ iĩma, na kũndũ kw’onthe kũla kwĩ vakuvĩ nayo, mwandanĩ wa Alava, nthĩ yĩ iĩma, na nthĩ ndindimalu, na ngalĩ ya Ĩtheo, na ũtee wa ũkanga, nthĩ ya Akanaani, na Levanoni, kũvika ũsĩ ũla mũnene, ũsĩ wa Euvalati.'),
('kam', 'DEU', 1, 8, 'Sisyai, nĩniĩte nthĩ mbee wenyu: likai na mũimĩmesya nthĩ ĩla Yeova wamevĩtĩe aaĩthe menyu, Avalaamu, na Isaka, na Yakovo, kũmanenga na ũsyao woo ĩtina woo.'),
('kam', 'DEU', 1, 9, 'Nakwa naneenie nenyu ĩvinda yĩu, ngyasya, Nditonya kũmũkua inyw’ĩ nĩ nyioka:'),
('kam', 'DEU', 1, 10, 'Yeova Ngai wenyu nũmwingĩvĩtye, na, sisyai, ũmũnthĩ mũilyĩ ta ndata sya ĩtunĩ ũndũ wa kwingĩva.'),
('kam', 'DEU', 1, 11, 'Yeova, Ngai wa aaĩthe menyu, namũtw’ĩkĩthye kũndũ ngili o ũndũ mwĩana yu, na kũmũathima, o ũndũ wamwathie!'),
('kam', 'DEU', 1, 12, 'Nyie nĩ nyioka ndonya ata kũkua kĩthokoo kwenyu, na mũio wenyu, na ĩteta yenyu?'),
('kam', 'DEU', 1, 13, 'Osai andũ oĩ, me na ũmanyi, na ala mesĩkĩwe, kwĩanana na mbaĩ syenyu, na ngamatw’ĩkĩthya atongoi menyu.'),
('kam', 'DEU', 1, 14, 'Na inyw’ĩ mwanzũngĩa na mwasya, Ũndũ ũla ũneenete nĩ ũseo twĩke.'),
('kam', 'DEU', 1, 15, 'Kwondũ wa ũu noosa atongoi ma mbaĩ syenyu, andũ oĩ, na ala mesĩkĩwe, na namaia methĩwe atongoi menyu, makavuteni ma ngili ngili, o makavuteni ma maana, na makavuteni ma mĩongo ĩtano mĩongo ĩtano, na makavuteni ma makũmi, na anene, kwĩanana na mbaĩ syenyu.'),
('kam', 'DEU', 1, 16, 'Na nameaĩa asili menyu ĩvinda yĩu, ngyasya, Ĩthukĩĩsyei maũndũ ma ana‐a‐ĩthe menyu, na silan’yai katĩ mũndũ na mwana‐a‐ĩthe, na mwĩkali wa ũeninĩ ũla wĩ kwake.'),
('kam', 'DEU', 1, 17, 'Mũikendeesye andũ mũkĩsila; methukĩĩsye ala anini na ala anene ũndũ ũmwe; mũtikakĩe ũthyũ wa mũndũ; nũndũ kũsilĩla nĩ kwa Ngai: na ũndũ ũla wĩmũema mwĩndetee, nakwa ngawĩthukĩĩsya.'),
('kam', 'DEU', 1, 18, 'Na ĩvinda yĩu namwĩaĩa maũndũ onthe ala mwaĩle kwĩka.'),
('kam', 'DEU', 1, 19, 'Na twakwata kyalo kuma Olevu, na twavĩtĩla weũnĩ ũsu w’onthe mũnene na wa ũtĩsya ũla mwoonie, tũkwete nzĩa ya nthĩ yĩ iĩma ya Aamoli, o tondũ Yeova Ngai waitũ watwĩaĩe; na twavika Katesi‐mbalinea.'),
('kam', 'DEU', 1, 20, 'Nakwa namwĩa, Nĩmũvikĩte nthĩ yĩ iĩma ya Aamoli, ĩla Yeova Ngai waitũ ũtũnengae.'),
('kam', 'DEU', 1, 21, 'Sisya, Yeova Ngai waku nĩwiĩte ĩ nthĩ mbee waku: ambata, noĩmĩmesya o tondũ Yeova, Ngai wa aaĩthe maku, ũneenete naku; ndũkakĩe, o na ndũkateve.'),
('kam', 'DEU', 1, 22, 'Ma mwanthengeea o kĩla mũndũ wenyu, na mwambĩa, Tũtũme andũ maende mbee waitũ, makatũthianĩe nthĩ, na maitũetee ũvoo wa nzĩa ĩla twĩambata nayo, na ndũa ila twĩvikĩa.'),
('kam', 'DEU', 1, 23, 'Na ũndũ ũsu wambendeesya mũno; na noosa andũ ĩkũmi na elĩ menyu, kĩla mbaĩ mũndũ ũmwe:'),
('kam', 'DEU', 1, 24, 'na methyũũa na mambata nthĩ yĩ iĩma, na mavika mwanda wa Esikoli, na moothiana.'),
('kam', 'DEU', 1, 25, 'Na moosa ũsyao wa nthĩ mokonĩ moo, na matũtheeesya, na matũetee ũvoo, na masya, Nĩ nthĩ nzeo ĩla Yeova Ngai waitũ ũtũnengae.'),
('kam', 'DEU', 1, 26, 'Ĩndĩ inyw’ĩ mwalea kwambata, na mwatũla mwĩao wa Yeova Ngai wenyu:'),
('kam', 'DEU', 1, 27, 'na mwanyungunyĩĩsya maeemanĩ menyu, na mwasya, Nũndũ Yeova nĩwatũmenie, nĩwatumisye nthĩ ya Misili, atũnengane mokonĩ ma Aamoli, matwanange.'),
('kam', 'DEU', 1, 28, 'Twĩambata va? Ana‐a‐ĩthe maitũ nĩmatũtũlĩte ngoo, maitwĩa, Andũ nĩ anene na aasa kwĩ ithyĩ; ndũa nĩ nene na mbiie kũvika ĩtunĩ; na ũndũ ũngĩ nĩtũnamonie ana ma Aanaki kw’o.'),
('kam', 'DEU', 1, 29, 'Nĩvo ĩndĩ namwĩa inyw’ĩ, Mũikethĩwe na kĩũũyũ, o na mũikamakĩe.'),
('kam', 'DEU', 1, 30, 'Yeova Ngai wenyu ũla ũendaa mbee wenyu, akamũkitĩa, kwĩanana na ũndũ w’onthe wamwĩkie Misili mwene na metho menyu,'),
('kam', 'DEU', 1, 31, 'na weũnĩ, vala wonete ũndũ Yeova Ngai waku wakũkuie, o tondũ mũndũ ũkuaa mwana wake, nzĩanĩ yonthe ĩla mwaendie nayo, kũvika yĩla mwavikie vaa.'),
('kam', 'DEU', 1, 32, 'Ĩndĩ ũndũnĩ ũũ mũtyaamwĩtĩkĩla Yeova Ngai wenyu,'),
('kam', 'DEU', 1, 33, 'ũla wamũtongoeasya nzĩanĩ, ũtukũ na mwaki wa kũmwon’ya nzĩa ĩla mũũendela, na mũthenya na mũumbĩ, nĩ kana amũmanthĩe vandũ va kwamba maeema menyu.'),
('kam', 'DEU', 1, 34, 'Na Yeova eew’a wasya wa ndeto syenyu, na athilĩka, na eevĩta, akyasya,'),
('kam', 'DEU', 1, 35, 'Vate ndĩi vati ũmwe wa andũ aa ma nzyawa ĩno nthũku ũkona nthĩ ĩla nzeo, ĩla neevĩtie kũnenga aaĩthe menyu,'),
('kam', 'DEU', 1, 36, 'ate o Kalevu mwana wa Yevune; nake akamyona; na ngamũnenga we na syana syake nthĩ ĩla wakinyĩle, nĩkwĩthĩwa nĩwamũatĩĩe Yeova ki.'),
('kam', 'DEU', 1, 37, 'Na Yeova anthatĩa kwondũ wenyu, akĩmbĩa, O naku ndũkalika kw’o:'),
('kam', 'DEU', 1, 38, 'Yosua mwana wa Nuni, ũla ũũngamaa mbee waku, akalika kw’o: mũkũmbaĩthye; nũndũ nĩwe ũkatuma Isilaeli mamĩtiĩwa.'),
('kam', 'DEU', 1, 39, 'Na ũndũ ũngĩ twana twenyu tũnini, tũla mwaisye tũkethĩwa twĩ tũtave, na syana syenyu, ila ũmũnthĩ ite na ũmanyi wa ũseo kana ũthũku, ikalika kw’o, nĩsyo nĩinenga, na ikamĩmesya.'),
('kam', 'DEU', 1, 40, 'Ĩndĩ inyw’ĩ, ĩthyũũei, na mũikwata kyalo kyenyu mũthi weũnĩ na nzĩa ĩla ĩelete Ũkanga Mũtune.'),
('kam', 'DEU', 1, 41, 'Nĩvo ĩndĩ mwanzũngĩie na mwambĩa, Nĩtũmũvĩtanĩsye Yeova, tũkambata na kũkita, kwĩanana na ũndũ w’onthe ũla Yeova Ngai waitũ watwĩaĩe. Na mweekĩa kĩla mũndũ mĩio yake ya kaũ, na mwoona ta ũndũ ũnini kwambata nthĩ yĩ iĩma.'),
('kam', 'DEU', 1, 42, 'Na Yeova ambĩa, Matavye, Mũtikambate, kana kũkita; nũndũ ndi vamwe nenyu: mũtikakũnwe nĩ amaitha menyu.'),
('kam', 'DEU', 1, 43, 'Kwondũ wa ũu naneena nenyu, na mũtyaambĩthukĩĩsya; ĩndĩ mwang’endea mwĩao wa Yeova, na mwaĩ na mĩtavyo, na mwambata nthĩ yĩ iĩma.'),
('kam', 'DEU', 1, 44, 'Na Aamoli, ala matwĩe nthĩ ĩsu yĩ iĩma, mamumĩlĩla inyw’ĩ, na mamũlũngya, o tondũ nzũkĩ ilũngasya, na mamũkũnĩa Seili, o na kũvika Olima.'),
('kam', 'DEU', 1, 45, 'Na mwasyoka na mwamũĩĩa Yeova; ĩndĩ Yeova ndaaĩthukĩĩsya wasya wenyu, o na ndaathyũũa kũtũ kwake amwĩw’e.'),
('kam', 'DEU', 1, 46, 'Kwondũ wa ũu mwekala Katesi mĩthenya mingĩ, kwĩanana na mĩthenya ĩla mwekalile vo.'),
('kam', 'DEU', 2, 1, 'Nĩvo ĩndĩ tweethyũũie, twakwata kyalo kitũ tũendete weũnĩ na nzĩa ĩla ĩelete Ũkanga Mũtune, o tondũ Yeova waneenie nakwa; na twathyũlũlũka kĩĩma kya Seili mĩthenya mingĩ.'),
('kam', 'DEU', 2, 2, 'Na Yeova aneena nakwa, akĩmbĩa,'),
('kam', 'DEU', 2, 3, 'Kũthyũlũlũka kwenyu kwa kĩĩma kĩĩ nĩkweanĩa: ĩthyũũei ngalĩ ya ĩũlũ.'),
('kam', 'DEU', 2, 4, 'Na meaĩe andũ, ũkyasya, Mũitĩa kũvĩtĩla mũvakanĩ wa ana‐a‐ĩthe menyu ana ma Esau, ala matũaa Seili; na makamũkĩa. Kwondũ wa ũu ĩsũvĩei mũno;'),
('kam', 'DEU', 2, 5, 'mũikamathee; nũndũ ndikamũnenga kĩlungu kya nthĩ yoo, aiee, o na vandũ va ũkinya veana ĩkinya ya ũnyaĩĩ; nikwĩthĩwa nĩmũnengete Esau kĩĩma kya Seili kĩthĩwe ng’ũndũ yake.'),
('kam', 'DEU', 2, 6, 'Mũkathooa liu kwoo na mbesa, nĩ kana mũye; na mũkathooa manzĩ kwoo na mbesa, nĩ kana mũnyw’e.'),
('kam', 'DEU', 2, 7, 'Nũndũ Yeova Ngai waku nũkũathimĩte wĩanĩ w’onthe wa moko maku; nũmanyĩte kwanganga kwaku weũnĩ ũũ mũnene: myaka ĩno mĩongo ma Yeova Ngai waku nĩwĩkalĩte naku; ndwaanyivĩwa nĩ kĩndũ.'),
('kam', 'DEU', 2, 8, 'Na ĩndĩ twavita kuma vala vaĩ ana‐a‐ĩthe maitũ ana ma Esau, ala matũaa Seili, twaeka nzĩa va Alava, na Elathi, na ya Esioni‐ngeveli. Na tweethyũũa na twakwata nzĩa ya kũthi weũnĩ wa Moavi.'),
('kam', 'DEU', 2, 9, 'Na Yeova ambĩa, Ndũkathĩn’ye Amoavi, o na ndũkokite nao; nũndũ ndikaũnenga kĩlungu kya nthĩ yake kĩthĩwe ng’ũndũ yaku; nũndũ nĩnengete syana sya Loto nthĩ ya Ali yĩthĩwe ng’ũndũ yoo.'),
('kam', 'DEU', 2, 10, '(Aemi matwie vo tene, andũ anene, na aingĩ, na aasa, o ta Aanaki:'),
('kam', 'DEU', 2, 11, 'o namo matalawa Alevai, o ta Aanaki; ĩndĩ Amoavi mametaa Aemi.'),
('kam', 'DEU', 2, 12, 'O na Aoli matwĩe Seili tene, ĩndĩ ana ma Esau mamalũngya; na mamamina vyũ mbee woo, na matũa vandũ voo; o tondũ Isilaeli wekie nthĩ ya ng’ũndũ yake, ĩla Yeova wamanengie.)'),
('kam', 'DEU', 2, 13, 'Yu ũkĩlai, mũinge kalũsĩ ka Nzeleti. Na twainga kalũsi ka Nzeleti.'),
('kam', 'DEU', 2, 14, 'Na mĩthenya ĩla twookie kuma Katesĩmbalinea, kũvika yĩla twaingie kalũsĩ ka Nzeleti, yaĩ myaka mĩongo ĩtatũ na nyanya; kũvika yĩla nzyawa yonthe ya andũ ma kaũ maminiwe kumw’a mwakonĩ wa maeema, o tondũ Yeova wamevĩtĩe.'),
('kam', 'DEU', 2, 15, 'Na ĩngĩ kw’oko kwa Yeova kwaĩ ĩũlũ woo, kũmananga kũmaumya mwakonĩ wa maeema, kũvika maminwa vyũ.'),
('kam', 'DEU', 2, 16, 'Kwondũ wa ũu kweethĩwa, yĩla andũ onthe ma kaũ maanangiwe na makw’a kuma andũnĩ,'),
('kam', 'DEU', 2, 17, 'nĩw’o Yeova waneenie nakwa, akĩmbĩa,'),
('kam', 'DEU', 2, 18, 'Ũmũnthĩ inga ũsĩ wa Ali mũvaka wa Moavi:'),
('kam', 'DEU', 2, 19, 'na yĩla wĩthengeea welekele ana ma Amimoni, ndũkamathĩn’ye, kana kũkita namo; nũndũ ndikaũnenga kĩlungu kya nthĩ ya ana ma Amimoni kĩthĩwe ng’ũndũ yaku; nĩkwĩthĩwa nĩmanengete ana ma Loto nthĩ ĩsu yĩthĩwe ng’ũndũ yoo.'),
('kam', 'DEU', 2, 20, '(O na ĩsu ĩtalawa nĩ nthĩ ya Alevai: Alevai matwĩe vo tene; ĩndĩ Aamimoni mametaa Anzamisumi,'),
('kam', 'DEU', 2, 21, 'andũ anene, na aingĩ, na aasa, o ta Aanaki; ĩndĩ Yeova amananga mbee woo; na mamalũngya, na matũa vandũ voo;'),
('kam', 'DEU', 2, 22, 'o tondũ wekie kwondũ wa ana ma Esau, ala matũaa Seili, yĩla wanangie Aoli mbee woo; na mamalũngya, na matũaa vandũ voo kũvika ũmũnthĩ.'),
('kam', 'DEU', 2, 23, 'Na Aavi, ala matwĩe mĩsyĩ kũvika Ngasa, maanangwa nĩ Akavitoli, ala maumie Kavitoli, na matũa vandũ voo.)'),
('kam', 'DEU', 2, 24, 'Ũkĩlai, mũkwate kyalo kyenyu, mũkĩle mwanda wa Alinoni: sisya, nĩnenganĩte Sioni ũla Mũamoli, mũsumbĩ wa Esivoni, na nthĩ yake, kw’okonĩ kwaku; ambĩlĩlyai kũmyosa, na kũkita nake.'),
('kam', 'DEU', 2, 25, 'Ũmũnthĩ kwondũ waku nĩngwambĩlĩlya kũtĩsya ngo sya andũ ila syĩ ĩtheo wa ĩtu yonthe, na kũsyĩkĩa w’ĩa, ila ikew’a ũvoo waku, na ikatetemaa, na kũkwatwa nĩ woo kwondũ waku.'),
('kam', 'DEU', 2, 26, 'Na natũma andũ nĩ weũnĩ wa Ketemothi mathi kwa Sioni mũsumbĩ wa Esivoni na ndeto sya mũuo, ngyasya,'),
('kam', 'DEU', 2, 27, 'Ndeka nĩvĩtĩle nthĩ yaku: ngaendela lelũnĩ, ndikathũka ngalĩ ya kw’oko kwa aũme kana kw’oko kwa aka.'),
('kam', 'DEU', 2, 28, 'Ũkanthooesya lĩu mbesa, nĩye; na ũkanenga manzĩ ma mbesa, nĩnyw’e: ndeka no kũvĩta ngũvĩta na maũũ makwa;'),
('kam', 'DEU', 2, 29, 'o tondũ ana ma Esau ala matũaa Seili, na Amoavi ala matũaa Ali, mambĩkie; mũvaka ngainga Yolotani na kũlika nthĩ ĩla Yeova Ngai waitũ ũtũnengae.'),
('kam', 'DEU', 2, 30, 'Ĩndĩ Sioni mũsumbĩ wa Esivoni ndaaĩtĩkĩla tũvĩtĩle kwake; nũndũ Yeova Ngai waku nĩwomisye veva wake, na amũng’endethya ngoo, amũnengane kw’okonĩ kwaku, o tondũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 2, 31, 'Na Yeova ambĩa, Sisya, nĩnambĩlĩlya kũnengane Sioni na nthĩ yake mbee waku: ambĩlĩlya kwosa, nĩ kana ũtiĩwe nthĩ yake.'),
('kam', 'DEU', 2, 32, 'Nĩvo ĩndĩ Sioni watumĩlĩle, we na andũ make onthe, kũkita naitũ kũu Yaasa.'),
('kam', 'DEU', 2, 33, 'Na Yeova Ngai waitũ amũnengane mbee waitũ; na twamũkũna we, na ana make, na andũ make onthe.'),
('kam', 'DEU', 2, 34, 'Na twoosa ndũa syake syonthe ĩvinda yĩu, na twaananga vyũ kĩla ndũa yaĩ na andũ, vamwe na aka na twana tũnini; tũtyaatia mũndũ o na ũmwe;'),
('kam', 'DEU', 2, 35, 'no indo twoosie syĩthĩwe mũtavo witũ ene, vamwe na mĩio ya ndũa ila twoosie.'),
('kam', 'DEU', 2, 36, 'Kuma Aloeli, ĩla yĩ ũtee wa mwanda wa Alinoni, na kuma ndũanĩ ĩla yĩ mwandanĩ, o kũvika Ngileati, vatyaĩ ndũa o na ĩmwe yaĩ na ũvai mũtũlu ũtonya kũtũsiĩĩa; Yeova Ngai waitũ anengane syonthe mbee waitũ:'),
('kam', 'DEU', 2, 37, 'no nthĩ ya ana ma Amimoni ũtaamĩthengeea; ngalĩko yonthe ya ũsĩ wa Yavoki, na ndũa sya nthĩ yĩ iĩma, na o vala Yeova Ngai waitũ watũvatie.'),
('kam', 'DEU', 3, 1, 'Na ĩndĩ tweethyũũa, na twakwata nzĩa ya Mbasani: na Oku mũsumbĩ wa Mbasani atumĩlĩla, we na andũ make onthe, okitĩe Etilei.'),
('kam', 'DEU', 3, 2, 'Na Yeova ambĩa, Ndũkamũkĩe; nũndũ nĩmũnenganĩte we, na andũ make onthe, na nthĩ yake, kw’okonĩ kwaku; na ũkamwĩka o ũndũ wamwĩkie Sioni mũsumbĩ wa Aamoli, ũla watwĩe Esivoni.'),
('kam', 'DEU', 3, 3, 'Kwondũ wa ũu Yeova Ngai waitũ atũnenga kw’okonĩ kwitũ o na Oku nake, mũsumbĩ wa Mbasani, na andũ make onthe: na twamũkũna mũvaka ndaatialĩlwa nĩ mũndũ o na ũmwe.'),
('kam', 'DEU', 3, 4, 'Na twakwata ndũa syake syonthe ĩvinda yĩu; vatyaĩ ndũa o na ĩmwe ĩla tũtaamavena; ndũa mĩongo thanthatũ, na nthĩ yonthe ya Alikovu, ũsumbĩ wa Oku nthĩ ga Mbasani.'),
('kam', 'DEU', 3, 5, 'Ndũa isu syonthe syaĩ mbiie na maũvai matũlu, na mbingĩlo, na ivingi; na vamwe na isu mĩsyĩ mingĩ ĩtaĩ miie.'),
('kam', 'DEU', 3, 6, 'Na twasyananga vyũ, o tondũ twamwĩkie Sioni mũsumbĩ wa Esivoni, tũkyananga vyũ kĩla ndũa yaĩ na andũ, vamwe na aka na twana tũnini.'),
('kam', 'DEU', 3, 7, 'Ĩndĩ indo syonthe, na mĩio yonthe ya ndũa isu, twoosa syĩthĩwe mũtavo witũ ene.'),
('kam', 'DEU', 3, 8, 'Na ĩvinda yĩu twoosa nthĩ kuma mokonĩ ma asumbĩ asu elĩ ma Aamoli ala maĩ mũingo wa Yolotani, kuma mwanda wa ũsĩ wa Alinoni, kũvika kĩĩma kya Elimoni'),
('kam', 'DEU', 3, 9, '(kĩĩma kyu kya Elimoni, Asitoni makĩtaa Silioni, na Aamoli makĩtaa Senili);'),
('kam', 'DEU', 3, 10, 'ndũa syonthe sya ũiĩnĩ, na Ngileati yonthe, na Mbasani yonthe, kũvika Saleka na Etilei, ndũa sya ũsumbĩ wa Oku nthĩ ya Mbasani.'),
('kam', 'DEU', 3, 11, '(Nũndũ no Oku weka mũsumbĩ wa Mbasani watialilw’e wa ũtialo wa Alevai; sisya, ũkomo wake waĩ ũkomo wa kĩaa; ndwĩ vo ndũanĩ ya Lava ya ana ma Amimoni? Ũasa waw’o waĩ mĩkono kenda, na ũthanthau waw’o waĩ mĩkono ĩna, o ũndũ mũkono wa mũndũ ũilyĩ.)'),
('kam', 'DEU', 3, 12, 'Na nthĩ ĩsu twamĩmesya ĩvinda yĩu: kuma ndũa ya Aloeli, ĩla yĩ vakuvĩ na mwanda wa ũsĩ wa Alinoni, na nyanzu ya nthĩ yĩ iĩma ya Ngileati, na ndũa syayo, nanenga Aleuveni na Angati:'),
('kam', 'DEU', 3, 13, 'na nthĩ ya Ngileati ĩla yatialile, na nthĩ yonthe ya Mbasani, ũsumbĩ wa Oku, nanenga nyunzu ya mbaĩ ya Manase; nthĩ yonthe ya Alikovu, nayo nĩ Mbasani yonthe. (Nthĩ ĩsu yĩtawa nthĩ ya Alevai.'),
('kam', 'DEU', 3, 14, 'Yaili mwana wa Manase oosa nthĩ yonthe ya Alikovu, kũvika mũvakanĩ wa Angesuli na Amaaka, na asyĩta, o Mbasanĩ, aisyĩtanĩsya na syĩtwa yake mwene, Avothi‐yaili, kũvika ũmũnthĩ.)'),
('kam', 'DEU', 3, 15, 'Na namũnenga Makili nthĩ ya Ngileati.'),
('kam', 'DEU', 3, 16, 'Na namanenga Aleuveni na Angati nthĩ kuma Ngileati kũvika mwanda wa ũsĩ wa Alinoni, mwandanĩ katĩ, wĩthĩwe mũvaka o kũvika ũsĩ wa Yavoki, naw’o nĩ mũvaka wa ana ma Amimoni;'),
('kam', 'DEU', 3, 17, 'o na Alava, na ũsĩ wa Yolotani wĩthĩwe mũvaka, kuma ndũa ya Kinelethi o kũvika ũkanga wĩ Alava, naw’o nĩ Ũkanga wa Mũnyũ, ĩtheo wa kĩvaũũko kya Visika kwelekela wumĩlonĩ wa syũa.'),
('kam', 'DEU', 3, 18, 'Na namwĩaĩa ĩvinda yĩu, ngyasya, Yeova Ngai wenyu nũmũnengete nthĩ ĩno mũmĩmesye: mũkainga mwĩkĩĩte mĩio ya kaũ mwĩ mbee wa ana‐a‐ĩthe menyu ana ma Isilaeli andũ onthe me na ũkũmbaũ.'),
('kam', 'DEU', 3, 19, 'Ĩndĩ iveti syenyu, na syana syenyu nini, na indo syenyu (nĩnĩsĩ mwĩ na indo nyingĩ), ikekala ndũanĩ syenyu ila nĩmũnengete,'),
('kam', 'DEU', 3, 20, 'kũvika yĩla Yeova wĩmathũmũsya ana‐a‐ĩthe menyu, o ũndũ wamũthũmũisye inyw’ĩ, na makamesya nthĩ ĩla Yeova Ngai wenyu ũmanengae mũingo wa Yolotani; nĩvo ĩndĩ mwĩsyoka kĩla mũndũ ng’ũndũnĩ yake, ĩla nĩmũnengete.'),
('kam', 'DEU', 3, 21, 'Na namwĩaĩa Yosua ĩvinda yĩu, ngyasya, Metho maku nĩmonete ũndũ w’onthe ũla Yeova Ngai waku ũmekĩte asumbĩ asu elĩ: now’o Yeova wĩmeka mosumbĩ onthe nthĩ ĩla wĩinga.'),
('kam', 'DEU', 3, 22, 'Mũtikamakĩe; nũndũ Yeova Ngai waku, nĩwe ũmũkitĩaa.'),
('kam', 'DEU', 3, 23, 'Na namwĩsũva Yeova ĩvinda yĩu, ngyasya,'),
('kam', 'DEU', 3, 24, 'Ame Mwĩaĩi Yeova, nĩwambĩlĩlye kwon’ya mũthũkũmi waku, ũnene waku na kw’oko kwaku kwĩ vinya: nũndũ nĩ ngai yĩva ĩtunĩ kana kũũ nthĩ, ĩtonya kwĩka kwĩanana na mawĩa maku, na kwĩanana na meko maku me vinya?'),
('kam', 'DEU', 3, 25, 'Ndeka nĩinge, nĩngũkwĩsũva, none nthĩ nzeo ĩla yĩ mũingo wa Yolotani, nthĩ ĩsu nzeo yĩ iĩma, na kĩĩma kya Levanoni.'),
('kam', 'DEU', 3, 26, 'Ĩndĩ Yeova anthatĩa kwondũ wenyu, na ndaambĩthukĩĩsya; na Yeova ambĩa, Ĩanĩwa nũu; ndũkaneene nakwa ĩngĩ ũvoo ũsu.'),
('kam', 'DEU', 3, 27, 'Ambata mũtumbĩnĩ wa kĩĩma Visika, na ũngalalya metho maku ũthũĩlonĩ wa syũa, na ngali ya ĩũlũ, na ngalĩ ya ĩtheo, na wumĩlonĩ wa syũa, ũiketeea na metho maku: nũndũ ndũkainga ũsĩ ũũ wa Yolotani.'),
('kam', 'DEU', 3, 28, 'Ĩndĩ mwĩaĩe Yosua, na ũimũkũmbaĩthya, na kũmwĩkĩa vinya; nũndũ nĩwe ũkamatongoesya andũ aa mainge, nake akatuma matiĩwa nthĩ ĩla wĩona.'),
('kam', 'DEU', 3, 29, 'Kwondũ wa ũu twekala mwandanĩ ũla welekele Mbethi‐veoli.'),
('kam', 'DEU', 4, 1, 'Na yu, Isilaeli, ĩthukĩĩsyei myamũlo na motw’ĩo, ala nĩmũmanyĩasya, mũmeke; nĩ kana mwĩkale thayũ, na kũlika na kũmesya ĩ nthĩ ĩla Yeova, Ngai wa aaĩthe menyu, ũmũnengae.'),
('kam', 'DEU', 4, 2, 'Mũikamyongeleele ndeto ĩla nĩmwĩaĩaa, o na mũikamĩole, nĩ kana mũkwate mĩao ya Yeova Ngai wenyu ĩla nĩmwĩaĩaa.'),
('kam', 'DEU', 4, 3, 'Metho menyu nĩmonete ũndũ Yeova wekie nũndũ wa Mbethi‐veoli; nũndũ andũ onthe ala maatĩĩe Mbethi‐veoli, Yeova Ngai waku nũmanangĩte kũmaumya nthĩnĩ wenyu.'),
('kam', 'DEU', 4, 4, 'Ĩndĩ inyw’ĩ ala mwalũmanilye na Yeova Ngai wenyu mwĩ thayũ kĩla mũndũ ũmũnthĩ.'),
('kam', 'DEU', 4, 5, 'Sisyai, nĩmũmanyĩĩtye myamũlo na motw’ĩo, o tondũ Yeova Ngai wakwa wambĩaĩe, nĩ kana inyw’ĩ mwĩkĩae ũu nthĩ ĩla mwĩlika mũmĩmesye.'),
('kam', 'DEU', 4, 6, 'Kwondũ wa ũu mĩkwatei na mũimĩka; nĩkwĩthĩwa ũu nĩw’o ũĩ wenyu na ũmanyi wenyu methonĩ ma ngo sya andũ, ala makew’a mĩao ĩno yonthe, na kwasya, Nĩ w’o mbaĩ ĩno nene nĩ andũ oĩ na me na ũmanyi.'),
('kam', 'DEU', 4, 7, 'Nũndũ kwĩ mbaĩ yĩva nene, ĩla yĩ na ngai yĩ vakuvĩ namo, tondũ Yeova Ngai waitũ ũilyĩ o yĩla tũmwĩkaĩlaa?'),
('kam', 'DEU', 4, 8, 'Na kwĩ mbaĩ yĩva nene, yĩ na myamũlo na motw’ĩo malũngalu ta mĩao ĩno yonthe, ĩla niĩte mbee wenyu ũmũnthĩ?'),
('kam', 'DEU', 4, 9, 'Ĩsũvĩe mwene, na kũsyaĩĩsya na kĩthing’ĩĩsyo ngoo yaku, ndũkese kũlwa nĩ maũndũ ala metho maku moonie, maikese kuma ngoonĩ yaku mĩthenya yonthe ya thayũ waku; ĩndĩ manyĩthya mo syana syaku na esũkũũu;'),
('kam', 'DEU', 4, 10, 'na mũno mũthenya ũla waũngamie mbee wa Yeova Ngai waku Olevu, yĩla Yeova wambĩie, Mbũmbanĩsya andũ, nakwa ngatuma mew’a ndeto syakwa, nĩ kana memanyĩsye kũngĩa mĩthenya yonthe ĩla me thayũ kũũ nthĩ, na nĩ kana mamanyĩsye syana syoo.'),
('kam', 'DEU', 4, 11, 'Nenyu mwathengeea na kũũngama ĩtina wa kĩĩma; na kĩĩma kyakana mwaki kũvika ĩtunĩ nthĩnĩ, kweethĩwa kĩvindu, na mũumbĩ, na kĩvindu kya ngokomi.'),
('kam', 'DEU', 4, 12, 'Na Yeova aneena nenyu e nthĩnĩ, wa mwaki: mweew’a wasya wa ndeto, ĩndĩ mũtyaona mũvw’ano; no kwĩw’a wasya.'),
('kam', 'DEU', 4, 13, 'Nake amũtavya ũtianĩo wake, ũla wamwĩaĩe mwĩke, naw’o nĩ ĩla mĩao ĩkũmi; na amĩandĩka masengeanĩ elĩ ma mavia.'),
('kam', 'DEU', 4, 14, 'Na Yeova ambĩaĩa ĩvinda yĩu nĩmũmanyĩsye myamũlo na motw’ĩo, mũtonye kũmekĩaa nthĩ ĩla mwĩinga mũmĩmesye.'),
('kam', 'DEU', 4, 15, 'Kwondũ wa ũu ĩsũvĩei ene; nũndũ mũtyaona mũvw’ano o na wĩva mũthenya ũla Yeova waneenie nenyu e nthĩnĩ wa mwaki Olevu;'),
('kam', 'DEU', 4, 16, 'mũikese kwĩthũkya, na kwĩseũvĩsya mũvw’anano mwasũvye wa mũvw’ano wa kĩndũ o na kĩva, mũvw’ano wa mũndũ mũũme kana mũndũ mũka,'),
('kam', 'DEU', 4, 17, 'mũvw’ano wa nyamũ o na yĩva yĩ kũũ nthĩ, mũvw’ano wa nyũnyi o na yĩva yĩ nthwau yĩũlũkaa yayayanĩ,'),
('kam', 'DEU', 4, 18, 'mũvw’ano wa kĩndũ o na kĩva kĩla kĩtambũkaa mũthanganĩ, mũvw’ano wa ĩkũyũ o na yĩva yĩla yĩ manzĩnĩ ĩtheo wa nthĩ;'),
('kam', 'DEU', 4, 19, 'na ndũkese kũũngalalya metho maku kũsisya ĩtunĩ, na woona syũa na mwei na ndata, o nguthu yonthe yĩ ĩtunĩ, ũkakusw’a na kwithaitha, na kwithũkũma, ila Yeova Ngai waku wiaanĩĩtye ngonĩ syonthe sya andũ ila syĩ ĩtheo wa ĩtu yonthe.'),
('kam', 'DEU', 4, 20, 'Ĩndĩ Yeova nũmwosete, na kũmumya ikonĩ ĩnene ya kĩaa, kũmumya Misili, mwĩthĩwe kwake andũ ma ũtiĩwa, o ũndũ mũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 4, 21, 'Na ũndũ ũngĩ Yeova anthatĩa kwondũ wenyu, na eevĩta ndikainga ũsĩ wa Yolotani, na ndikalika nthĩ ĩsu nzeo, ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtiĩwa waku:'),
('kam', 'DEU', 4, 22, 'ĩndĩ mũvaka nĩkw’ĩe nthĩ ĩno, nditonya kũinga ũsĩ wa Yolotani; ĩndĩ inyw’ĩ mũkainga, na mũithi kũmĩmesya nthĩ ĩsu nzeo.'),
('kam', 'DEU', 4, 23, 'Ĩsũvĩei, mũtikese kũlwa nĩ ũtianĩo wa Yeova Ngai wenyu, ũla watianĩe nenyu, na kwĩseũvĩsya mũvw’anano mwasũvye wa mũvw’ano wa kĩndũ o na kĩva kĩla Yeova Ngai waku wakũvatie.'),
('kam', 'DEU', 4, 24, 'Nũndũ Yeova Ngai waku nĩ mwaki ũla ũĩsaa, Ngai wĩ kĩwĩu.'),
('kam', 'DEU', 4, 25, 'Wasyaa syana, na esũkũũu, na kwĩthĩwa mwĩkalĩte nthĩ ĩvinda ĩasa, na mũkevukya, na kũseũvya mũvw’anano mwasũvye wa mũvw’ano wa kĩndũ o na kĩva, na mũkeka ũndũ ũla Yeova Ngai wenyu wonaa wĩ ũthũku, na kũmũthatya;'),
('kam', 'DEU', 4, 26, 'ũmũnthĩ nĩngwĩta ĩtu na nthĩ imũkũsĩĩe, atĩ mĩtũkĩ mũkaanangĩka vyũ kumw’a nthĩ ĩsu ĩla mwĩinga Yolotani mũkamĩmesye; mũtikaingĩvya mĩthenya yenyu nthĩnĩ wayo, ĩndĩ mũkanangwa vyũ.'),
('kam', 'DEU', 4, 27, 'Na Yeova akamũnyaĩĩkya katĩ wa ngo sya andũ, na mũkatiala andũ anini ũtalonĩ katĩ wa i mbaĩ, kũla Yeova ũkamũtwaa.'),
('kam', 'DEU', 4, 28, 'Na kũu mũkaithũkũma ngai, mawĩa ma moko ma andũ, mĩtĩ na mavia, ila itonaa, kana kwĩw’a, kana kũya, kana kũnyungĩa.'),
('kam', 'DEU', 4, 29, 'Ĩndĩ mwĩ kũu mũkamantha Yeova Ngai waku, na ũkamwona, yĩla wĩmũmantha na ngoo yaku yonthe na thayũ waku w’onthe.'),
('kam', 'DEU', 4, 30, 'Yĩla wĩ ũnyamaonĩ, na maũndũ asu onthe makũkĩa, mĩthenya ya mũminũkĩlyo ũkamũsyokea Yeova Ngai waku, na kwĩthukĩĩsya wasya wake:'),
('kam', 'DEU', 4, 31, 'nũndũ Yeova Ngai waku nĩ Ngai wa tei; ndakakũeka, kana ũkwananga, kana kũlwa nĩ ũtianĩo wa aaĩthe maku ũla wamevĩtĩe.'),
('kam', 'DEU', 4, 32, 'Ĩndĩ kũlya yu ũvoo wa mĩthenya mĩvĩtu, ĩla yavĩtie mbee waku, kuma mũthenya ũla Ngai wombie mũndũ kũũ nthĩ, na kuma ngalĩ ĩmwe ya ĩtu kũvika ngalĩ ĩngĩ, ethĩwa kwaethĩwa ũndũ o na wĩva wailyĩ ũndũ ũũ ũnene, kana kwaew’ĩka ũndũ ũilyĩ taw’o?'),
('kam', 'DEU', 4, 33, 'Ve andũ maew’a wasya wa Ngai ũineena wĩ mwakinĩ tondũ weewie, na kwĩkala thayu?'),
('kam', 'DEU', 4, 34, 'Kana Ngai aatata kũthi na kwĩyosea mwene mbaĩ kuma nthĩnĩ wa mbaĩ ĩngĩ, kwondũ wa matatwa, na syama, na moseng’yo, na kaũ, na kw’oko kwĩ vinya, na kw’oko kũtambũũku, na motĩsyo manene, o ũndũ Yeova Ngai wenyu wamwĩkĩe nthĩ ya Misili mwene na metho menyu?'),
('kam', 'DEU', 4, 35, 'We nĩwooniw’e ũu, nĩ kana ũmanye atĩ Yeova nĩwe Ngai; vai ũngĩ ate o we.'),
('kam', 'DEU', 4, 36, 'E ĩtunĩ akwĩw’ĩthya wasya wake, nĩ kana akũmanyĩsye; na kũũ nthĩ akwonethya mwaki wake mũnene; naku weew’a ndeto syake e mwakinĩ.'),
('kam', 'DEU', 4, 37, 'Na nĩkwĩthĩwa nĩwamendie aaĩthe maku, kwondũ wa ũu anyuva ũsyao woo ĩtina woo, na akumya Misili e vamwe naku, kwondũ wa vinya wake mũnene;'),
('kam', 'DEU', 4, 38, 'kana alũngye mbee waku mbaĩ ila nene na syĩ vinya kwĩ we, akũlikye nthĩnĩ, na ũkũnenga nthĩ yoo yĩthĩwe ũtiĩwa o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 4, 39, 'Manya ĩndĩ ũmũnthĩ, na wĩkĩe ngoonĩ yaku, kana Yeova nĩwe Ngai ĩũlũ ĩtunĩ na ĩtheo kũũ nthĩ; vai ũngĩ.'),
('kam', 'DEU', 4, 40, 'Naku kwata myamũlo yake, na mĩao yake, ĩla ngũkwĩaĩa ũmũnthĩ, nĩ kana kwĩthĩwe ũseo kwaku, na kwa syana syaku ĩtina waku, na nĩ kana wingĩvye mĩthenya yaku wĩ nthĩ ĩla Yeova Ngai waku ũkũnengae, tene na tene.'),
('kam', 'DEU', 4, 41, 'Nĩvo Mose wavathie ndũa itatũ mũingo wa Yolotani kwelekela vala syũa yumĩlaa;'),
('kam', 'DEU', 4, 42, 'nĩ kana mũaani akĩĩae vo, ũla ũmũaa mũtũi wake na mbanga, na ndatwĩe e ũthũ nake; na ĩndĩ akeethĩwa thayũ akĩĩa ndũa ĩmwe ya isu:'),
('kam', 'DEU', 4, 43, 'nasyo nĩ, Mbeseli ĩla yĩ weũnĩ, nthĩ yĩ ũiĩ, ũndũ wa Aleuveni; na Lamothi nthĩ ya Ngileati, ũndũ wa Angati; na Ngolani nthĩ ya Mbasani, ũndũ wa Amanase.'),
('kam', 'DEU', 4, 44, 'Na ĩno nĩyo mĩao ĩla Mose wamaiĩe ana ma Isilaeli:'),
('kam', 'DEU', 4, 45, 'aa nĩmo mokũsĩ, na myamũlo, na motw’ĩo, ala Mose wamatavisye ana ma Isilaeli, yĩla maumie nthĩ ya Misili,'),
('kam', 'DEU', 4, 46, 'mũingo wa Yolotani, mwandanĩ ũla welekele Mbethi‐veoli, nthĩ ya Sioni mũsumbĩ wa Aamoli, ũla watwĩe Esivoni, ũla Mose na ana ma Isilaeli mamũkũnie, yĩla maumie Misili.'),
('kam', 'DEU', 4, 47, 'Na mamĩmesya nthĩ yake, na nthĩ ya Oku mũsumbĩ wa Mbasani, nĩmo asumbĩ elĩ ma Aamoli, ala maĩ mũingo wa Yolotani kwelekela vala syũa yumĩlaa;'),
('kam', 'DEU', 4, 48, 'kuma Aloeli, ĩla yĩ ũtee wa mwanda wa ũsĩ wa Alinoni, o kũvika kĩĩma kya Saioni (nĩkyo kĩĩma kya Elimoni),'),
('kam', 'DEU', 4, 49, 'na Alava w’onthe mũingo wa Yolotani kwelekela wumĩlonĩ wa syũa, o kũvika ũkanga wa Alava, ĩtheo wa ivaũũko sya Visika.'),
('kam', 'DEU', 5, 1, 'Na Mose ameta Isilaeli onthe, na amea, Ĩthukĩĩsyei, we Isilaeli, myamũlo na motw’ĩo ala ngũneena matũnĩ menyu ũmũnthĩ, nĩ kana mwĩmanyĩsye, mũmasũvĩe na kũmekaa.'),
('kam', 'DEU', 5, 2, 'Yeova Ngai waitũ atianĩe ũtianĩo naitũ Olevu.'),
('kam', 'DEU', 5, 3, 'Ũtianĩo ũũ Yeova ndaatianĩa na aaĩthe maitũ, ĩndĩ nĩ ithyĩ, o ithyĩ ala twĩ thayũ vaa ithyonthe ũmũnthĩ.'),
('kam', 'DEU', 5, 4, 'Yeova aneena nenyu ũthyũ kwa ũthyũ kĩĩmanĩ e mwakinĩ'),
('kam', 'DEU', 5, 5, '(nakwa naũngama katĩ wa Yeova nenyu ĩvinda yĩu, nĩmwon’ye ndeto ya Yeova: nĩkwĩthĩwa nĩmwakĩaa nũndũ wa mwaki, na mũtyaambata kĩĩmanĩ), akĩmwĩa,'),
('kam', 'DEU', 5, 6, 'Ninyie Yeova Ngai waku, ũla wakumisye nthĩ ya Misili, ũkumya nyũmbanĩ ya ũkombo.'),
('kam', 'DEU', 5, 7, 'Ndũkethĩwe na ngaĩ ingĩ ate o nyie.'),
('kam', 'DEU', 5, 8, 'Ndũkeseũvĩsye mũvw’anano mwasũvye, mũvw’ano o na wĩva wa kĩndũ kĩ ĩũlũ ĩtunĩ, kana kĩla kĩ kũũ nthĩ, kana kĩla kĩ manzĩnĩ ĩtheo wa nthĩ:'),
('kam', 'DEU', 5, 9, 'ndũkamĩkunamĩe, o na ndũkamĩthũkũme; nũndũ nyie, Yeova Ngai waku, nĩ Ngai wĩ kĩwĩũ, ngĩivanĩsya kwa syana ũthũku wa aaĩthe, kũvika nzyawa ya katatũ na ya kana sya ala mamenaa;'),
('kam', 'DEU', 5, 10, 'na ngyonan’ya ũseo wĩ wendo kũvika ngili na ngili sya ala mambendaa na kũkwataa mĩao yakwa.'),
('kam', 'DEU', 5, 11, 'Ndũkawete syĩtwa ya Yeova Ngai waku mana: nũndũ Yeova ndakasya ũsu nde ĩvĩtyo ũla ũwetaa syĩtwa yake mana.'),
('kam', 'DEU', 5, 12, 'Lilikana mũthenya wa savato, ũwĩkalye wĩ mũtheu, o tondũ Yeova Ngai waku wakwĩaĩe.'),
('kam', 'DEU', 5, 13, 'Tethya wĩa mĩthenya thanthatũ, wĩke mawĩa maku onthe;'),
('kam', 'DEU', 5, 14, 'ĩndĩ mũthenya wa mũonza nĩ savato wa Yeova Ngai waku: mũthenya ũsu ndũkatethye wĩa o na wĩva, we, kana mwana waku, kana mwĩĩtu waku, kana mũthũkũmi waku mũndũ mũũme, kana mũthũkũmi waku mwĩĩtu, kana ng’ombe yaku, kana ĩng’oi yaku, kana indo syaku o na syĩva, kana mũeni waku ũla wĩ kwaku; nĩ kana mũthũkũmi waku mũndũ mũũme na mũthũkũmi waku mwĩĩtu mathũmũe o taku.'),
('kam', 'DEU', 5, 15, 'Na lilikana atĩ waĩ mũthũkũmi nthĩ ya Misili, na Yeova Ngai waku akumya vo na kw’oko kwĩ vinya na kw’oko kũtambũũku: kwondũ wa ũu Yeova Ngai waku nĩwakwĩaĩe ũlilikane mũthenya wa savato.'),
('kam', 'DEU', 5, 16, 'Taĩa au na mwenyu, o tondũ Yeova Ngai waku wakwĩaĩe; nĩ kana matukũ maku maingĩve, na nĩ kana kwĩthĩwe ũseo kwaku, nthĩ ĩla Yeova Ngai waku ũkũnengae.'),
('kam', 'DEU', 5, 17, 'Ndũkoae.'),
('kam', 'DEU', 5, 18, 'O na ndũkalaalae.'),
('kam', 'DEU', 5, 19, 'O na ndũkoye.'),
('kam', 'DEU', 5, 20, 'O na ndũkamũkũsĩĩe mũtũi waku ũvũngũ.'),
('kam', 'DEU', 5, 21, 'O na ndũkamwĩw’ĩe ĩtomo mũka wa mũtũi waku; o na ndũkew’ĩe ĩtomo nyũmba ya mũtũi waku, kana mũũnda wake, kana mũthũkũmi wake mũndũ mũũme, kana mũthũkũmi wake mwĩĩtu, kana ng’ombe yake, kana ĩng’oi yake, kana kĩndũ o na kĩva kya mũtũi waku.'),
('kam', 'DEU', 5, 22, 'Ndeto isu Yeova aneena na ũmbano wenyu w’onthe kĩĩmanĩ e katĩ wa mwaki, na mũumbĩnĩ, na kĩvindunĩ kya ngokomi, na wasya mũnene: o na ndaongela. Na aiandĩka masengeanĩ elĩ ma mavia, na anenga nyie.'),
('kam', 'DEU', 5, 23, 'Na kweethĩwa, mweew’a wasya wĩ kĩvindunĩ, yĩla kĩĩma kyakanĩte mwaki, mwanthengeea, o atongoi onthe ma mbaĩ syenyu, na atumĩa menyu;'),
('kam', 'DEU', 5, 24, 'na mwanbĩa, Sisya, Yeova Ngai waitũ nũtwonetye ũtheu mũtisu wake na ũnene wake, na ithyĩ nĩtwĩw’ĩte wasya wake wĩ nthĩnĩ wa mwaki: ũmũnthĩ nĩtwoona kana Ngai nũneenaa na mũndũ, nake akekala thayũ.'),
('kam', 'DEU', 5, 25, 'Na yu ĩndĩ twĩkw’ĩa kĩ? Nũndũ mwaki ũũ mũnene ũkatũmina: ethĩwa tũkeew’a ĩngĩ wasya wa Yeova Ngai waitũ, tũkakw’a.'),
('kam', 'DEU', 5, 26, 'Nũndũ nĩ wĩva wa onthe me mĩĩ, ũla wewie wasya wa Ngai ũla wĩ thayũ akĩneena e katĩ wa mwaki, o tondũ tweew’a, nake akekala thayũ?'),
('kam', 'DEU', 5, 27, 'Thi ũthengeee, wĩw’e w’onthe ũla Yeova Ngai waitũ wĩneena: naku ũtũtavye w’onthe ũla Yeova Ngai waitũ wĩneena naku; naitũ tũkawĩw’a, na kũwĩka.'),
('kam', 'DEU', 5, 28, 'Na Yeova eew’a wasya wa ndeto syenyu, yĩla mwaneenie nakwa; na Yeova ambĩa, Nĩneew’a wasya wa ndeto sya andũ aa, ila makũtavya: nĩmaneena nesa w’onthe ũla maneena.'),
('kam', 'DEU', 5, 29, 'A! Kethĩwa me na ngoo ta ĩsu mavinda onthe, mangĩe na kũkwata mĩao yakwa yonthe, nĩ kana kwĩthĩwe ũseo kwoo, na kwa syana syoo tene na tene!'),
('kam', 'DEU', 5, 30, 'Enda ũmatavye, Syokai maeemanĩ menyu.'),
('kam', 'DEU', 5, 31, 'Ĩndĩ we, ũngama vaa vakuvĩ nakwa, na nĩngũkũtavya mwĩao w’onthe, na myamũlo, na motw’ĩo, ala wĩmamanyĩsya, nĩ kana matonye kũmekĩaa nthĩ ĩla nĩmanengae mamĩmesye.'),
('kam', 'DEU', 5, 32, 'Sũvĩai ĩndĩ mwĩke o tondũ Yeova Ngai wenyu wamwĩaĩe: mũtikathũke ngalĩ ya kw’oko kwa aũme kana kw’oko kwa aka.'),
('kam', 'DEU', 5, 33, 'Endaai na nzĩa yonthe ĩla Yeova Ngai wenyu wamwĩaĩe, nĩ kana mwĩthĩwe thayũ, na nĩ kana kwĩthĩwe ũseo kwenyu, na mwingĩvye mĩthenya yenyu mwĩ nthĩ ĩla mwĩmĩmesya.'),
('kam', 'DEU', 6, 1, 'Ũũ nĩw’o mwĩao, na myamũlo, na motw’ĩo, ala Yeova Ngai wenyu weaĩe mũmanyĩwe, nĩ kana mũmekĩe nthĩ ĩla mwĩinga mũkamĩmesye;'),
('kam', 'DEU', 6, 2, 'nĩ kana ũmũkĩe Yeova Ngai waku, kũkwata myamũlo yake yonthe, na mĩao yake yonthe, ĩla nĩmwĩaĩaa, we, na mwana waku, na mwĩsũkũũu, mĩthenya yonthe ya thayũ waku; na nĩ kana mĩthenya yaku yingĩvw’e.'),
('kam', 'DEU', 6, 3, 'Kwondũ wa ũu ĩw’a, we Isilaeli, sũvĩa wĩke ũu; nĩ kana kwĩthĩwe ũseo kwaku, nĩ kana mũtonye kwingĩva mũno, o tondũ Yeova, Ngai wa aaĩthe maku, wakwathie, mwĩ nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'DEU', 6, 4, 'Ĩw’a, we Isilaeli: Yeova Ngai waitũ nĩ Yeova ũmwe:'),
('kam', 'DEU', 6, 5, 'naku mwende Yeova Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe, na vinya waku w’onthe.'),
('kam', 'DEU', 6, 6, 'Na ndeto ii, ila ngũkwĩaĩa ũmũnthĩ, ikeethĩwa ngoonĩ yaku;'),
('kam', 'DEU', 6, 7, 'naku imanyĩasye syana syaku na kĩthing’ĩĩsyo, na ineenae ndeto isu yĩla ũilyĩ nyũmbanĩ yaku, na yĩla ũendaa nzĩanĩ, na yĩla ũkomaa, na yĩla wũkĩlaa.'),
('kam', 'DEU', 6, 8, 'Na syoveee kw’okonĩ kwaku syĩthĩwe wonan’yo, na syĩthĩwe ũlilikan’yo katĩ wa metho maku.'),
('kam', 'DEU', 6, 9, 'Na iandĩke mĩtĩnĩ ĩla yĩ ndee sya mĩomo ya nyũmba yaku, na mbingĩlonĩ syaku.'),
('kam', 'DEU', 6, 10, 'Na kũkeethĩwa, yĩla Yeova Ngai waku wĩkũtwaa nthĩ ĩla wevĩtĩe aaĩthe maku, Avalaamu, na Isaka, na Yakovo, ũkũnenga, ndũa nene na nzeo, ila ũtaaka we,'),
('kam', 'DEU', 6, 11, 'na nyũmba syusĩe syĩndũ syonthe nzeo, ila ũtaausũsya, na ithima mbĩnze, ila ũtaaĩnza, na mĩũnda ya mĩsavivũ na mĩthata, ĩla ũtaavanda, naku ũkaya na kũvũna;'),
('kam', 'DEU', 6, 12, 'nĩvo ĩndĩ sũvĩa ndũkese kũlwa nĩ Yeova, ũla wakumisye nthĩ ya Misili, kũkumya nyũmbanĩ ya ũkombo.'),
('kam', 'DEU', 6, 13, 'Mũkĩe Yeova Ngai waku; na kũmũthũkũma, na kwĩvĩta na syĩtwa yake.'),
('kam', 'DEU', 6, 14, 'Mũtikaatĩĩe ngai ingĩ, ngai sya andũ ala mamũthyũlũlũkĩte;'),
('kam', 'DEU', 6, 15, 'nĩkwĩthĩwa Yeova Ngai waku ũla wĩ katĩ wenyu nĩ Ngai wĩ kĩwĩu; ũthatu wa Yeova Ngai waku ndũkese ũkwakanĩa, nake aikwananga wume ũthyũnĩ wa nthĩ.'),
('kam', 'DEU', 6, 16, 'Mũtikamũtate Yeova Ngai wenyu, o ũndũ mwamũtatie kũu Masa.'),
('kam', 'DEU', 6, 17, 'Kwatai na kĩthing’ĩĩsyo mĩao ya Yeova Ngai wenyu, na mokũsĩ make, na myamũlo yake, ĩla wakwĩaĩe.'),
('kam', 'DEU', 6, 18, 'Na ĩka ũla Yeova wonaa wĩ wa w’o na ũseo; nĩ kana kwĩthĩwe ũseo kwaku, na nĩ kana ũtonye kũlika na kũmesya nthĩ ĩsu nzeo ĩla Yeova wevĩtĩe aaĩthe maku,'),
('kam', 'DEU', 6, 19, 'kũlũngya amaitha maku onthe maume mbee waku, o tondũ Yeova ũneenete.'),
('kam', 'DEU', 6, 20, 'Yĩla mwana waku ũkakũkũlya ĩvinda yĩla yũkĩte, akyasya, Nĩ ma kĩ, mokũsĩ aa, na myamũlo ĩno, na motw’ĩo aa ala Yeova Ngai waitũ wamwĩaĩe?'),
('kam', 'DEU', 6, 21, 'Nĩvo ĩndĩ ũkamwĩa mwana waku, Twaĩ ngombo sya Valao nthĩ ya Misili: na Yeova atumya Misili na kw’oko kwĩ vinya;'),
('kam', 'DEU', 6, 22, 'na Yeova oonan’ya syama na moseng’yo manene na me woo, ĩũlũ wa Misili, na Valao, na nyũmba yake yonthe twene na metho maitũ;'),
('kam', 'DEU', 6, 23, 'na atumya kw’o, nĩ kana atũlikye kũũ, atũnenge nthĩ ĩla wamevĩtĩe aaĩthe maitũ.'),
('kam', 'DEU', 6, 24, 'Na Yeova atwĩaĩa twĩke myamũlo ĩsu yonthe, na kũkĩa Yeova Ngai waitũ, twĩthĩwe na ũseo mavinda onthe, nĩ kana atũsũvĩe twĩthĩwe thayũ, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 6, 25, 'Na kũkeethĩwa ũlũngalu kwitũ, twasũvĩa na kwĩka mwĩao ũũ w’onthe mbee wa Yeova Ngai waitũ, o tondũ watwĩaĩe.'),
('kam', 'DEU', 7, 1, 'Yĩla Yeova Ngai waku ũkakũlikya nthĩ ĩla wĩthi kũmĩmesya, na kũlũngya mbaĩ nyingĩ syume mbee waku, Mũititi, na Mũngilikasi, na Mũamoli, na Mũkanaani, na Mũvelisi, na Mũivi, na Mũyevusi, mbaĩ mũonza nene na syĩ vinya kwĩ we;'),
('kam', 'DEU', 7, 2, 'na yĩla Yeova Ngai waku ukainengane mbee waku, naku ũkaikũna; nĩvo ĩndĩ syanange vyũ: ndũkaethĩwe na wĩw’ano nao, kana kũmew’ĩa tei;'),
('kam', 'DEU', 7, 3, 'o na ndũkaatwaanĩe nao; mwĩĩtu waku ndũkaamũne mwana wake, kana mwĩĩtu wake ndũkaamũtwaĩe mwana waku.'),
('kam', 'DEU', 7, 4, 'Nũndũ akamwathũkya mwana waku aeke kũmbikĩla, nĩ kana mathũkũme ngai ingĩ: na kwondũ wa ũu ũthatu wa Yeova ũkakwakanĩa, na akakwananga mĩtũkĩ.'),
('kam', 'DEU', 7, 5, 'Ĩndĩ mekei ũũ: anangai ithembeo syoo, na tũlangai ituĩ syoo ilungu, na temangai Aselimu yoo, na vĩvyai na mwaki mĩvw’anano yoo myasũvye.'),
('kam', 'DEU', 7, 6, 'Nĩkwĩthĩwa we wĩ mbaĩ ntheu kwa Yeova Ngai waku: Yeova Ngai waku nũkũnyuvĩte wĩthĩwe mbaĩ yake mwene, kuma ngonĩ syonthe sya andũ syĩ ĩũlũ wa nthĩ.'),
('kam', 'DEU', 7, 7, 'Yeova ndaamwenda kana kũmũnyuva, nĩkwĩthĩwa mwaĩ aingĩ kũvĩtũka ũko wa andũ o na wĩva; nũndũ mwaĩ anini kũvĩtũka ngo syonthe sya andũ:'),
('kam', 'DEU', 7, 8, 'ĩndĩ nĩ kwĩthĩwa Yeova nũmwendaa, na nĩkwĩthĩwa nũkwenda kwĩanĩsya wĩvĩto ũla wamevĩtĩe aaĩthe menyu, nĩvo Yeova wamumisye na kw’oko kwĩ vinya, na kũmwovosya kũmumya nyũmbanĩ ya ũkombo, kuma kw’okonĩ kwa Valao mũsumbĩ wa Misili.'),
('kam', 'DEU', 7, 9, 'Manya ĩndĩ kana Yeova Ngai waku, nĩwe Ngai, Ngai wĩ kĩthito, ũla wĩanĩasya ũtianĩo na ũseo wĩ wendo kwa ala mamwendaa na kũkwata mĩao yake kũvika nzyawa ngili,'),
('kam', 'DEU', 7, 10, 'na kwĩĩvanĩsya ũthyũnĩ woo ala mamũmenaa, amanange: ndakethĩwa na kĩkono kwa ũla ũmũmenaa, akamũĩvanĩsya ũthyũnĩ wake.'),
('kam', 'DEU', 7, 11, 'Kwondũ wa ũu kwata mwĩao, na myamũlo, na motw’ĩo, ala ngũkwĩaĩa ũmũnthĩ, ũmeke.'),
('kam', 'DEU', 7, 12, 'Na kũkeethĩwa, nũndũ nĩmwĩthukĩĩasya motw’ĩo aa, na kũmakwata, na kũmeka, kana Yeova Ngai waku akeanĩsya naku ũtianĩo na ũseo wĩ wendo ũla wamevĩtĩe aaĩthe maku:'),
('kam', 'DEU', 7, 13, 'nake akakwenda, na ũkũathima, na ũkwingĩvya; na akaathima ũsyao wa mwĩĩ waku na ũsyao wa nthĩ yaku, lĩu waku wa mbaa ngetha na mbinyu yaku mbĩthĩ na mauta maku, wingĩvo wa ng’ombe syaku, na tũtena twa ndĩthya yaku ya mbũi na malondu, wĩ nthĩ ĩla wamevĩtĩe aaĩthe maku ũkũnenga.'),
('kam', 'DEU', 7, 14, 'Ũkaathimwa kũvĩtũka ngo syonthe sya andũ: vatikethĩwa mũndũ mũũme kana mũndũ mũka ũteũsyaa katĩ wenyu, kana ĩndonĩ syenyu.'),
('kam', 'DEU', 7, 15, 'Na Yeova akakũvetea ũwau w’onthe; na ndakakũetee ũwau o na ũmwe wa mowau mathũku ma Misili, ala wĩsĩ, ĩndĩ akamaetee onthe ala makũmenaa.'),
('kam', 'DEU', 7, 16, 'Naku mina ngo syonthe sya andũ ila Yeova Ngai waku ũkakũnenga; ĩtho yaku yĩtikaasyĩw’ĩe tei: o na ndũkaathũkũme ngai syoo; nũndũ ũu ũkethĩwa kĩtei kya ũkũkwatya.'),
('kam', 'DEU', 7, 17, 'Ethĩwa ũkaneena ngoonĩ yaku, Mbaĩ ii nĩ nyingĩ kwĩ nyie; ndonya ata kwilũngya?'),
('kam', 'DEU', 7, 18, 'Ndũkaikĩe: lilikana mũno ũndũ Yeova Ngai waku wamwĩkie Valao, na Misili yonthe;'),
('kam', 'DEU', 7, 19, 'matatwa manene ala metho maku moonie, na syama, na moseng’yo, na kw’oko kwĩ vinya, na kw’oko kũtambũũku, kũla Yeova Ngai waku wakumisye nakw’o: o ta ũu Yeova Ngai waku akasyĩka ngo syonthe sya andũ ila ũkĩaa.'),
('kam', 'DEU', 7, 20, 'Na ũndũ ũngĩ Yeova Ngai waku akatũma mauĩ katĩ woo, kũvika yĩla ala matialile mevithĩte, meanangwa maume mbee waku.'),
('kam', 'DEU', 7, 21, 'Ndũkatelemw’e nĩmo; nũndũ Yeova Ngai waku e vamwe naku, nake nĩ Ngai mũnene na wa ũtĩsya.'),
('kam', 'DEU', 7, 22, 'Na Yeova Ngai waku akalũngya mbaĩ isu syume mbee waku mbola na mbola: ndũkaimine o ĩmwe, nyamũ sya kĩtheka itikaingĩve kwaku.'),
('kam', 'DEU', 7, 23, 'Ĩndĩ Yeova Ngai waku akainengane mbee waku, na akaithokoan’ya na kĩthokoan’yo kĩnene, kũvika syaanangwa.'),
('kam', 'DEU', 7, 24, 'Na akanengane asumbĩ moo kw’okonĩ kwaku, na ũkatuma masyĩtwa moo manangwa kuma ĩtheo wa ĩtu: vatikethĩwa mũndũ o na wĩva ũkatonya kũũngama mbee waku, kũvika yĩla wĩmananga.'),
('kam', 'DEU', 7, 25, 'Mĩvw’anano myasũvye ya ngai syoo vĩvya na mwaki: ndũkawĩw’ĩe ĩtomo vetha kana thaavu ũla wĩ ĩũlũ wayo, kana kwĩyosea, ndũkese kũkwatw’a nĩw’o; nũndũ nĩ ũthatyo kwa Yeova Ngai waku.'),
('kam', 'DEU', 7, 26, 'Na ndũkaaete kĩndũ kya ũthatyo nyũmbanĩ yaku, na ũkĩtw’ĩka kĩndũ kĩumanĩe takyo: kĩmene vyũ, na kĩthĩthe vyũ; nũndũ nĩ kĩndũ kĩumanĩe.'),
('kam', 'DEU', 8, 1, 'Mwĩao w’onthe ũla ngũkwĩaĩa ũmũnthĩ ũsũvĩe na kũwĩka, nĩ kana wĩthĩwe thayũ, na kwingĩva, na kũlika na kũmesya ĩ nthĩ ĩla Yeova wamevĩtĩe aaĩthe maku.'),
('kam', 'DEU', 8, 2, 'Na mĩlilikane nzĩa yonthe ĩla Yeova Ngai waku wakũtongoesye myaka ĩno mĩongo ĩna weũnĩ, nĩ kana akũnyivye, akũtate, amanye ũla wĩ ngoonĩ yaku, ethĩwa wendaa ũkwata mĩao yake kana ti w’o.'),
('kam', 'DEU', 8, 3, 'Na akũnyivya, na akũeka wĩthĩwe na nzaa, na akũvũnĩthya na lĩu wĩtawa mana, ũla ũtaamanya, o na aaĩthe maku mataomanya; nĩ kana akũmanyĩthye atĩ mũndũ ndethĩawa thayũ kwondũ wa imũtũ syoka, ĩndĩ ethĩawa thayũ kwondũ wa kĩla ũndũ wumaa kanyw’anĩ wa Yeova.'),
('kam', 'DEU', 8, 4, 'Ngũa syaku ila weekĩe ityaakũa, o na kũũ kwaku kũtyaaimba, myaka ĩno mĩongo ĩna.'),
('kam', 'DEU', 8, 5, 'Naku ũkamanya ngoonĩ yaku, kana, o ũndũ mũndũ ũkũnaa mwana wake, now’o Yeova Ngai waku ũkũkũnaa.'),
('kam', 'DEU', 8, 6, 'Mĩkwate mĩao ya Yeova Ngai waku, ũendae nzĩanĩ syake, na kũmũkĩa.'),
('kam', 'DEU', 8, 7, 'Nũndũ Yeova Ngai waku nũkũũlikya nthĩ nzeo, nthĩ yĩ tũlũsĩ twĩ manzĩ, na nthongo na mbuluti, syumasya manzĩ myandanĩ na iĩmanĩ;'),
('kam', 'DEU', 8, 8, 'nthĩ yĩ nganũ na mbaale, na mĩsavivũ na mĩkũyũ na makũngũmanga; nthĩ yĩ mĩthata na ũkĩ wa nzũkĩ;'),
('kam', 'DEU', 8, 9, 'nthĩ ĩla ũkaĩsĩaa kĩmũtũ ũteũnyivĩwa, ndũkaĩwa nĩ kĩndũ kw’o; nthĩ ĩla mavia mayo nĩ iaa, na iĩmanĩ syayo ũkenza ũthuku.'),
('kam', 'DEU', 8, 10, 'Na ũkaya na kũvũna, na ũkamũtaĩa Yeova Ngai waku nũndũ wa nthĩ nzeo ĩla ũkũnengete.'),
('kam', 'DEU', 8, 11, 'Sũvĩa ndũkese kũlwa nĩ Yeova Ngai waku, kwondũ wa kũlea kũkwata mĩao yake, na motw’ĩo make, na myamũlo yake, ĩla ngũkwĩaĩa ũmũnthĩ:'),
('kam', 'DEU', 8, 12, 'kũikethĩwe, waya na kũvũna, na waaka nyũmba nzeo, na kwĩkala vo;'),
('kam', 'DEU', 8, 13, 'na ndĩthya syaku sya ng’ombe na sya mbũi na malondu syaingĩva, na vetha waku na thaavu waku waingĩva, na syonthe ila wĩ nasyo syaingĩva;'),
('kam', 'DEU', 8, 14, 'ngoo yaku ĩndĩ ĩketũlya, naku ũkyũlwa nĩ Yeova Ngai waku, ũla wakumisye nthĩ ya Misili, ũkumya nyũmbanĩ ya ũkombo;'),
('kam', 'DEU', 8, 15, 'ũla wakũtongoesye kũvĩtĩla weũnĩ mũnene na wa ũtĩsya, ũla waĩ na nzoka iilyĩ mwaki na ing’auũ, na nthĩ yĩ waũni ĩte manzĩ; ũla wakumisye manzĩ ĩvianĩ yũmũ mũno;'),
('kam', 'DEU', 8, 16, 'ũla wakũvũnĩthasya lĩu wĩtawa mana weũnĩ, ũla aaĩthe maku matawĩsĩ; nĩ kana akũnyivye, na nĩ kana akũtate, akwĩke nesa mũminũkĩlyo waku:'),
('kam', 'DEU', 8, 17, 'naku ũkyasya ngoonĩ yaku, Vinya wakwa na ũtonyi wakwa nũmboneete ũthwii ũũ.'),
('kam', 'DEU', 8, 18, 'Ĩndĩ mũlilikane Yeova Ngai waku, nũndũ nĩwe ũkũnengae vinya wa kwĩyonea ũthwii; nĩ kana alũlũmĩlye ũtianĩo wake ũla wamevĩtĩe aaĩthe maku, o tondũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 8, 19, 'Na kũkeethĩwa, ethĩwa ũkoolwa nĩ Yeova Ngai waku, na kũatĩĩa ngai ingĩ, na kwithũkũma, na kwithaitha, nĩngũũkũsĩĩa ũmũnthĩ kana ndũtĩa kwanangĩka.'),
('kam', 'DEU', 8, 20, 'O tondũ Yeova wanangaa mbaĩ mbee wenyu, o ta ũu, inyw’ĩ mũkaanangĩka; nĩkwĩthĩwa nĩmwaleile kwĩthukĩĩsya wasya wa Yeova Ngai wenyu.'),
('kam', 'DEU', 9, 1, 'Ĩw’a, we Isilaeli: ũmũnthĩ nũkũinga Yolotani, ũlike na kwosa nthĩ ya mbaĩ nene na syĩ vinya kwĩ we, ndũa nene na mbiie kũvika ĩtunĩ,'),
('kam', 'DEU', 9, 2, 'andũ anene na aasa, ana ma Aanaki, ala ũmesĩ, na ala weewie maiwetwa atĩĩ, Nũũ ũla ũtonya kũũngama mbee wa ana ma Anakĩ?'),
('kam', 'DEU', 9, 3, 'Manya ĩndĩ ũmũnthĩ, kana Yeova Ngai waku nĩwe ũla wĩinga mbee waku o ta mwaki ũla ũminaa; nake akamananga, na kũmanyivya mbee waku: kwondũ wa ũu ũkamalũngya, na kũmananga mĩtũkĩ, o tondũ Yeova ũneenete naku.'),
('kam', 'DEU', 9, 4, 'Yeova Ngai waku amina kũmalũngya mbee waku, ndũkaneene ngoonĩ yaku, ũkyasya, Nũndũ wa ũlũngalu wakwa Yeova nũndikĩtye nthĩ ĩno nĩmĩmesye; ĩndĩ nĩ kwondũ wa ũthũku wa mbaĩ isu Yeova ailũngya syume mbee waku.'),
('kam', 'DEU', 9, 5, 'Ti kwondũ wa ũlũngalu waku, kana kwondũ wa ũlũngalu wa ngoo yaku, wĩlika ũmesye nthĩ yoo; ĩndĩ kwondũ wa ũthũku wa mbaĩ isu Yeova Ngai waku ailũngya syume mbee waku, na nĩ kana alũlũmĩlye ndeto ĩla Yeova wamevĩtĩe aaĩthe maku, Avalaamu, na Isaka, na Yakovo.'),
('kam', 'DEU', 9, 6, 'Manya ĩndĩ, kana Yeova Ngai waku ndeũkũnenga nthĩ ĩno nzeo ũmĩmesye nũndũ wa ũlũngalu waku; nĩkwĩthĩwa wĩ mbaĩ yĩ ngingo nyũmũ.'),
('kam', 'DEU', 9, 7, 'Lilikana, ndũkolwe, ũndũ wamũthatisye Yeova Ngai waku weũnĩ: kuma mũthenya ũla waumie nthĩ ya Misili, mũvaka mwavika vandũ vaa, mwamũng’endeeaa Yeova.'),
('kam', 'DEU', 9, 8, 'O na vu Olevu mwamũthatĩsya Yeova, nake Yeova amũthatĩa enda kũmwananga.'),
('kam', 'DEU', 9, 9, 'Nambata kĩĩmanĩ kwosa masengea ma mavia, o masengea ma ũtianĩo ũla Yeova watianĩe nenyu, nĩvo nekalile kĩĩmanĩ mĩthenya mĩongo ĩna na matukũ mĩongo ĩna; ndyaaya lĩu kana kũnyw’a manzĩ.'),
('kam', 'DEU', 9, 10, 'Na Yeova anenga masengea elĩ ma mavia maandĩkĩtwe na kyaa kya Ngai; na kwaandĩkĩtwe ĩũlũ wamo kwĩanana na ndeto syonthe, ila Yeova waneenie nenyu kĩĩmanĩ e katĩ wa mwaki mũthenya wa ũmbano.'),
('kam', 'DEU', 9, 11, 'Na kweethĩwa mĩthenya mĩongo ĩna na matukũ mĩongo ĩna yathela, Yeova anenga ala masengea elĩ ma mavia, namo nĩ masengea ma ũtianĩo.'),
('kam', 'DEU', 9, 12, 'Na Yeova ambĩa, Ũkĩla, ũtheee mĩtũkĩ; nĩkwĩthĩwa andũ maku ala wamaumisye nthĩ ya Misili nĩmevukĩtye; mĩtũkĩ nĩmathũkĩte nzĩanĩ ĩla nameaĩe; nĩmeseũvĩsye mũvw’anano na syĩndũ matwekethetye.'),
('kam', 'DEU', 9, 13, 'Na ũndũ ũngĩ Yeova aneena nakwa, akĩmbĩa, Nĩnonete andũ aa, na, sisya, nĩ andũ me na ngingo nyũmũ:'),
('kam', 'DEU', 9, 14, 'ndeka, nĩmanange, na kwananga syĩtwa yoo yume ĩtheo wa ĩtu; na ngakũtw’ĩkĩthya mbaĩ yĩ vinya na nene kwĩ mo.'),
('kam', 'DEU', 9, 15, 'Kwondũ wa ũu neethyũũa na natheea kuma kĩĩmanĩ, na kĩĩma kyaĩ kyakanu mwaki: na masengea asu elĩ ma ũtianĩo maĩ mokonĩ makwa elĩ.'),
('kam', 'DEU', 9, 16, 'Na noona, na, sisya, mũmũvĩtanĩsye Yeova Ngai wenyu; mũseũvĩtye mũvw’anano wa kasaũ ka ng’ombe na syĩndũ ila mũtwekethetye: mwaathũka mĩtũkĩ nzĩanĩ ĩla Yeova wamwĩaĩe.'),
('kam', 'DEU', 9, 17, 'Na nakwete masengea asu elĩ, na namakiman’ya na nthĩ na moko makwa elĩ, namoaa mũsyaĩtye.'),
('kam', 'DEU', 9, 18, 'Na navalũka nthĩ mbee wa Yeova, o ta ĩvinda ya mbee, mĩthenya mĩongo ĩna na matukũ mĩongo ĩna; ndyaaya lĩu kana kũnyw’a manzĩ; nũndũ wa naĩ syenyu syonthe ila mwavĩtĩsye, ũndũ wa kwĩka ũndũ Yeova wonaa wĩ ũthũku, mũkĩmũthatya.'),
('kam', 'DEU', 9, 19, 'Nũndũ nakĩaa ũthatu na kũthilĩka, kũla Yeova wamũthilĩkĩle amwanange. Ĩndĩ Yeova ambĩthukĩĩsya ĩvinda yĩu nayo.'),
('kam', 'DEU', 9, 20, 'Na Yeova amũthatĩa Aluni mũno akyenda kũmũaa: nakwa ĩvinda yĩu namũvoyea Aluni nake.'),
('kam', 'DEU', 9, 21, 'Na noosa naĩ yenyu, nayo nĩ kasaũ kala mwaseũvĩtye, nakavĩvya na mwaki, nakatumbanga, nakathia kavinya, katw’ĩka ta kĩtoo: na neekĩa kĩtoo kyako kalũsĩnĩ kala katheeete kuma kĩĩmanĩ.'),
('kam', 'DEU', 9, 22, 'Na kũu Tavela, na Masa, na Kivilothi‐ataava, mwamũthatya Yeova.'),
('kam', 'DEU', 9, 23, 'Na yĩla Yeova wamũtũmie kuma Katesi‐mbalinea, akĩmwĩa, Ambatai mũmĩmesye nthĩ ĩla namũnengie; nĩvo mwaleile mwĩao wa Yeova Ngai wenyu, na mũtyaamwĩtĩkĩla, kana kwĩthukĩĩsya wasya wake.'),
('kam', 'DEU', 9, 24, 'Nĩmwamũng’endeie Yeova kuma mũthenya ũla namũmanyie inyw’ĩ.'),
('kam', 'DEU', 9, 25, 'Kwondũ wa ũu navalũka mbee wa Yeova mĩthenya mĩongo ĩna na matukũ mĩongo ĩna ala navalũkile, nũndũ Yeova nĩwaĩtye akamwananga.'),
('kam', 'DEU', 9, 26, 'Na namũvoya Yeova, ngyasya, Ame Mwĩaĩi Yeova, ndũkanange andũ maku na ũtiĩwa waku, ala wamovoisye kwondũ wa ũnene waku, ala wamaumisye Misili na kw’oko kwĩ vinya.'),
('kam', 'DEU', 9, 27, 'Lilikana athũkũmi maku, Avalaamu, na Isaka, na Yakovo; ndũkasisye ngũlũ sya andũ aa, kana ũthũku woo, kana naĩ yoo,'),
('kam', 'DEU', 9, 28, 'nthĩ ĩla watumisye ndĩkese kwasya, Nĩkwĩthĩwa Yeova ndaatonya kũmalikya nthĩ ĩla wamathie, na nĩkwĩthĩwa nĩwamamenaa, amaumisye akamoaĩe weũnĩ.'),
('kam', 'DEU', 9, 29, 'Ĩndĩ nĩ andũ maku na ũtiĩwa waku, ala wamaumisye na vinya waku mũnene na kw’oko kwaku kũtambũũku.'),
('kam', 'DEU', 10, 1, 'Ĩvinda yĩu Yeova ambĩa, Asũvya masengea elĩ ma mavia mailyĩ ta ala ma mbee, na ambata vala nĩĩ kĩĩmanĩ, na tuma ĩsandũkũ ya mĩtĩ.'),
('kam', 'DEU', 10, 2, 'Na ngaandĩka masengeanĩ asu ndeto ila syaĩ masengeanĩ ma mbee ala wooaie, na ũkamekĩa ĩsandũkũnĩ yĩu.'),
('kam', 'DEU', 10, 3, 'Na ĩndĩ natuma ĩsandũkũ ya mũtĩ wa mũea, na nasũvya masengea elĩ ma mavia mailyĩ ta ala ma mbee, na nambata kĩĩmanĩ, nĩ na masengea asu elĩ kw’okonĩ kwakwa.'),
('kam', 'DEU', 10, 4, 'Nake aandĩka masengeanĩ asu, o ũndũ ũandĩko wa mbee wailyĩ, ĩla mĩao ĩkũmi, ĩla Yeova wamũtavĩsye kĩĩmanĩ, e katĩ wa mwaki mũthenya wa ũmbano: na Yeova anenga nyie.'),
('kam', 'DEU', 10, 5, 'Na neethyũũa na natheea kuma kĩĩmanĩ, na neekĩa masengea asu ĩsandũkũnĩ yĩla natumĩte; na me vo o tondũ Yeova wambĩaĩe.'),
('kam', 'DEU', 10, 6, '(Na ana ma Isilaeli mauma Mbeelothi Mbene‐yaakani mathi kũvĩka Mosela. Aluni akw’ĩa kw’o, na athikwa kw’o; na Eleasali mwana wake athũkũma wĩanĩ wa ũthembi vandũ vake.'),
('kam', 'DEU', 10, 7, 'Kuma vau mathi kũvika Ngutokola; na kuma Ngutokola mathi kũvika Yotivatha, nthĩ ĩla yĩ tũlũsĩ twĩ manzĩ.'),
('kam', 'DEU', 10, 8, 'Ĩvinda yĩu Yeova avatha mbaĩ ya Livai, ĩkuae ĩsandũkũ ya ũtianĩo ya Yeova, na kũũngamaa mbee wa Yeova ĩmũthũkũme, na kũathimaa syĩtwanĩ yake, kũvika ũmũnthĩ.'),
('kam', 'DEU', 10, 9, 'Kwondũ wa ũu Livai nde na kĩanda kana ũtiĩwa vamwe na ana‐a‐ĩthe; Yeova nĩwe ũtĩĩwa wake, kwĩanana na ũndũ Yeova Ngai waku wamũtavisye.)'),
('kam', 'DEU', 10, 10, 'Na nekala kĩĩmanĩ, o ta ĩvinda ya mbee, mĩthenya mĩongo ĩna na matukũ mĩongo ĩna: na Yeova ambĩthukĩĩsya ĩvinda yĩu nayo; Yeova ndaenda ũkwananga.'),
('kam', 'DEU', 10, 11, 'Na Yeova ambĩa, Ũkĩla, kwata kyalo kyaku mbee wa andũ; nao makalika na kũmesya ĩ nthĩ, ĩla namevĩtĩe aaĩthe moo kũmanenga.'),
('kam', 'DEU', 10, 12, 'Na yu, Isilaeli, ũndũ ũla Yeova Ngai waku ũnũkũandũa kwaku nĩ mwaũ, ate o kũmũkĩaa Yeova Ngai waku, na kũendaa nzĩanĩ syake syonthe, na kũmwendaa, na kũthũkũmaa Yeova Ngai waku na ngoo yaku yonthe na thayũ waku w’onthe,'),
('kam', 'DEU', 10, 13, 'na kũkwataa mĩao ya Yeova, na myamũlo yake, ĩla ngũkwĩaĩa ũmũnthĩ nĩ kana wone ũseo?'),
('kam', 'DEU', 10, 14, 'Sisya, ĩtu nĩ ya Yeova Ngai waku, o na ĩtu yĩla yĩ ĩũlũ wa matu, na nthĩ, na syonthe syĩ kw’o.'),
('kam', 'DEU', 10, 15, 'Ĩndĩ Yeova nĩwatanĩe aaĩthe maku na kũmenda, na anyuva ũsyao woo ĩtina woo, naw’o nĩ inyw’ĩ kũmumya ngonĩ syonthe sya andũ, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 10, 16, 'Kwondũ wa ũu aĩkai makonde ma ngoo syenyu, na mũikethĩwe na ngingo nyũmũ ĩngĩ.'),
('kam', 'DEU', 10, 17, 'Nũndũ Yeova Ngai waku, nĩwe Ngai wa i ngai, na Mwĩaĩi wa eaĩi, Ngai mũnene, na wĩ vinya, na wa ũtĩsya, ũla ũtendeeasya andũ, kana kwosa ĩtuvi ya wendeesyo.'),
('kam', 'DEU', 10, 18, 'Asilaa katĩ kwondũ wa ũla wakw’ĩĩwe nĩ ĩthe na aka ndiwa, na nũmwendaa mwĩkali wa ũeninĩ, aimũnenga kya ũya na kya kwĩvw’ĩka.'),
('kam', 'DEU', 10, 19, 'Kwondũ wa ũu inyw’ĩ mwendei mwĩkali wa ũeninĩ; nĩkwĩthĩwa inyw’ĩ mwaĩ ekali ma ũeninĩ nthĩ ya Misili.'),
('kam', 'DEU', 10, 20, 'Mũkĩe Yeova Ngai waku; mũthũkũme we; lũman’ya nake, na ĩvĩte na syĩtwa yake.'),
('kam', 'DEU', 10, 21, 'Nake nĩ ndaĩa yaku, na nĩ Ngai waku, ũla wakwĩkie maũndũ aa manene na ma ũtĩsya, ala metho maku monete.'),
('kam', 'DEU', 10, 22, 'Aaĩthe maku matheeie Misili me andũ mĩongo mũonza; na yu Yeova Ngai waku nũkwingĩvĩtye ta ndata sya ĩtunĩ.'),
('kam', 'DEU', 11, 1, 'Kwondũ wa ũu mwende Yeova Ngai waku, na kwata wĩaĩo wake, na myamũlo yake, na motw’ĩo make, na mĩao yake, mavinda onthe.'),
('kam', 'DEU', 11, 2, 'Na manyai ũmũnthĩ: nũndũ ndiũneena na syana syenyu ila itesĩ, na itaona ũsilĩlo wa Yeova Ngai wenyu, na ũnene wake, na kw’oko kwake kwĩ vinya, na kw’oko kwake kũtambũũku,'),
('kam', 'DEU', 11, 3, 'na syama syake, na mawĩa make, ala wamwĩkie Valao mũsumbĩ wa Misili, na nthĩ yake yonthe, kũu Misili;'),
('kam', 'DEU', 11, 4, 'na ũndũ wasyĩkie ita sya Misili, mbalasi syoo, na makasya moo ma kaũ; ũndũ wamavw’ĩkie na manzĩ ma Ũkanga Mũtune makĩmũatĩĩa, na ũndũ Yeova wamanangie kũvika ũmũnthĩ;'),
('kam', 'DEU', 11, 5, 'na ũndũ wamwĩkie inyw’ĩ mwĩ weũnĩ, kũvika mwavika vaa;'),
('kam', 'DEU', 11, 6, 'na ũndũ wamekie Ndathani na Avilamu, ana ma Eliavu, mwana wa Leuveni; ũndũ nthĩ yathamisye kanyw’a wayo, na yamamelya, na andũ ma nyũmba syoo, na maeema moo, na kĩla kĩndũ kyaĩ thayũ maĩ nakyo, nthĩnĩ wa Isilaeli onthe:'),
('kam', 'DEU', 11, 7, 'ĩndĩ metho menyu nĩmonete wĩa w’onthe mũnene wa Yeova ũla wekie.'),
('kam', 'DEU', 11, 8, 'Kwondũ wa ũu kwatai mwĩao w’onthe ũla ngũmwĩaĩa ũmũnthĩ, nĩ kana mwĩthĩwe na vinya, na kũlika na kũmesya nthĩ, ĩla mwĩinga mũkamĩmesye;'),
('kam', 'DEU', 11, 9, 'na nĩ kana mwingĩvye mĩthenya yenyu nthĩ ĩsu, ĩla Yeova wamevĩtĩe aaĩthe menyu kũmanenga na ũsyao woo, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'DEU', 11, 10, 'Nũndũ nthĩ, ĩla wĩlika ũmĩmesye, ndĩilyĩ nthĩ ya Misili vala mwaumie, vala wavandie mbeũ yaku, na kũmĩnyithya na kũũ kwaku, o ta mũũnda wa mboka;'),
('kam', 'DEU', 11, 11, 'ĩndĩ nthĩ, ĩla mwĩinga mũkamĩmesye, nĩ nthĩ yĩ iĩma na myanda, na ĩnyusaa manzĩ ma mbua ya ĩtunĩ,'),
('kam', 'DEU', 11, 12, 'nthĩ ĩla Yeova Ngai waku ũsũvĩaa: metho ma Yeova Ngai waku mamĩsyaĩĩsyaa mavinda onthe, kuma mwambĩlĩlyo wa mwaka kũvika mũminũkĩlyo wa mwaka.'),
('kam', 'DEU', 11, 13, 'Na kũkeethĩwa, ethĩwa mũkethukĩĩasya mũno mĩao yakwa ĩla ngũmwĩaĩa ũmũnthĩ, mũmwende Yeova Ngai wenyu, na kũmũthũkũma na ngoo yaku yonthe na thayũ waku w’onthe,'),
('kam', 'DEU', 11, 14, 'nĩvo ĩndĩ uganengane mbua ya nthĩ yenyu kyathĩ kyayo, mbua ya nthwa na mbua ya uũa, nĩ kana ũtonye kũketha lĩu waku wa mbaa ngetha, na mbinyu yaku mbĩthĩ, na mauta maku.'),
('kam', 'DEU', 11, 15, 'Ngamesya nyeki isesinĩ syaku kwondũ wa indo syaku, naku ũkaya na kũvũna.'),
('kam', 'DEU', 11, 16, 'Ĩsũvĩei, ngoo syenyu itikakengwe, na inyw’ĩ mũkyathũka, na kũthũkũma ngai ingĩ, na kwithaitha;'),
('kam', 'DEU', 11, 17, 'na ũthatu wa Yeova ũkĩmwakanĩa, nake aivinga matu, kũikethĩwe mbua, na nthĩ ĩilea kũsyaa ũsyao wayo; nenyu mũkyanangĩka mĩtũkĩ mume nthĩ nzeo ĩla Yeova ũmũnengae.'),
('kam', 'DEU', 11, 18, 'Kwondũ wa ũu iai ndeto ii syakwa ngoonĩ yenyu na mathayũnĩ menyu; na syoveei kw’okonĩ kwenyu syĩthĩwe wonan’yo, na syĩthĩwe ũlilikan’yo katĩ wa metho menyu.'),
('kam', 'DEU', 11, 19, 'Na imanyĩasye syana syenyu, mũkĩneena ũvoo wasyo, yĩla ũilyĩ nyũmbanĩ yaku, na yĩla ũendaa nzĩanĩ, na yĩla ũkomaa, na yĩla wũkĩlaa.'),
('kam', 'DEU', 11, 20, 'Na iandĩke mĩtĩnĩ ĩla yĩ ndee sya mĩomo ya nyũmba yaku, na mbingĩlonĩ syaku;'),
('kam', 'DEU', 11, 21, 'nĩ kana mĩthenya yaku yingĩvw’e, na mĩthenya ya syana syaku, wĩ nthĩ ĩla Yeova wamevĩtĩe aaĩthe maku kũmanenga, o ta mĩthenya ya matu me ĩũlũ wa nthĩ.'),
('kam', 'DEU', 11, 22, 'Nũndũ ethĩwa mũkakwata na kĩthing’ĩĩsyo mwĩao ũũ w’onthe ũla ngũkwĩaĩa, na kũwĩka, na kũmwendaa Yeova Ngai wenyu, na kũendaa nzĩanĩ syake syonthe, na kũlũman’ya nake;'),
('kam', 'DEU', 11, 23, 'nĩvo ĩndĩ Yeova wĩlũngya mbaĩ isu syonthe syume mbee wenyu, na mũkosa nthĩ ya mbaĩ nene na syĩ vinya kwĩ inyw’ĩ.'),
('kam', 'DEU', 11, 24, 'Kĩla vandũ vala ũnyaĩĩ wenyu ũkakinya vakeethĩwa venyu: kuma weũnĩ, na Levanoni, kuma ũsĩnĩ, naw’o nĩ ũsĩ wa Euvalati, o na kũvika ũkanga wa ũthũĩlonĩ wa syũa kũkeethĩwa mũvaka wenyu.'),
('kam', 'DEU', 11, 25, 'Vai mũndũ ũkatonya kũũngama mbee wenyu: Yeova Ngai wenyu akeekĩa w’ĩa kwondũ wenyu na ũtĩsyo kwondũ wenyu nthĩ yonthe ĩla mũkakinyĩla, o tondũ wamũtavisye.'),
('kam', 'DEU', 11, 26, 'Sisya, ũmũnthĩ nĩngwia mbee wenyu ũathimo na kĩumo:'),
('kam', 'DEU', 11, 27, 'ũathimo, ethĩwa mũkeethukĩĩasya mĩao ya Yeova Ngai wenyu, ĩla ngũmwĩaĩa ũmũnthĩ;'),
('kam', 'DEU', 11, 28, 'na kĩumo, ethĩwa mũtikethukĩĩasya mĩao ya Yeova Ngai wenyu, ĩndĩ mũkyathũka kuma nzĩanĩ ĩla ngũmwĩaĩa ũmũnthĩ, mũatĩĩe ngai ingĩ, ila mũtaaimanya.'),
('kam', 'DEU', 11, 29, 'Na kũkeethĩwa, yĩla Yeova Ngai waku wĩkũlikya nthĩ ĩla mwĩthĩ kũmĩmesya, nĩvo ũkaia ũathimo kĩĩmanĩ kya Ngelisimu, na kĩumo kĩĩmanĩ kya Evali.'),
('kam', 'DEU', 11, 30, 'Isu iti mũingo wa Yolotani, ĩtina wa nzĩa ya ũthũĩlonĩ wa syũa, nthĩ ya Akanaani ala matwĩe Alava, kwelekela Ngilikali, vakuvĩ na myaloni ya Mole?'),
('kam', 'DEU', 11, 31, 'Nĩkwĩthĩwa nĩmũinga Yolotani mũlike mũmesye nthĩ ĩla Yeova Ngai wenyu ũmũnengae, na mũkamĩmesya, na kũmĩtĩnĩka.'),
('kam', 'DEU', 11, 32, 'Na inyw’ĩ sũvĩai na mũyĩka myamũlo yonthe na motw’ĩo ala ngwia mbee wenyu ũmũnthĩ.'),
('kam', 'DEU', 12, 1, 'Ĩno nĩyo myamũlo na aa nĩmo motw’ĩo ala mũkasũvĩaa na kũmekaa mwĩ nthĩ ĩla Yeova, Ngai wa aaĩthe maku, ũkũnengete ũmĩmesye, mĩthenya yonthe ĩla ũkethĩwa thayũ kũũ nthĩ.'),
('kam', 'DEU', 12, 2, 'Anangai vyũ kũndũ kw’onthe kũla mbaĩ ila mũkalũngya syathaithĩaa ngai syoo, na iĩmanĩ ndũlu, na tũlĩmanĩ, na ĩtina wa kĩla mũtĩ mwĩũ:'),
('kam', 'DEU', 12, 3, 'na anangai ithembeo syoo, na tũlangai ituĩ syoo ilungu, na vĩvyai na mwaki Aselimu yoo; na temangai mĩvw’anano myasũvye ya ngai syoo; na anangai syĩtwa yoo vandũ vau.'),
('kam', 'DEU', 12, 4, 'Mũtikamwĩke Yeova Ngai wenyu ũu.'),
('kam', 'DEU', 12, 5, 'Ĩndĩ vandũ vala Yeova Ngai wenyu wĩnyuva nthĩnĩ wa mbaĩ syenyu syonthe avaie syĩtwa yake, nĩvo ũtũo wake vala mwĩelekela, na vau nĩvo wĩendaa;'),
('kam', 'DEU', 12, 6, 'na vau mũkatwaaa nthembo syenyu sya kũvĩvw’a, na nthembo syenyu sya kũtonywa, na ilungu syenyu sya ĩkũmi, na nthembo ya kũkĩlw’a ya moko menyu, na mawĩvĩto menyu, na nthembo syenyu sya kumya na ngoo ya kwenda, na kĩla kĩsyawa mbee kya ndĩthya yenyu ya ng’ombe na ya mbũi na malondu:'),
('kam', 'DEU', 12, 7, 'na vau mũkaya mbee wa Yeova Ngai wenyu, na mũkatanĩa kĩla ũndũ ũla mwĩkaa na moko menyu, inyw’ĩ na andũ ma nyũmba syenyu, ũla Yeova Ngai waku ũkũathimĩe.'),
('kam', 'DEU', 12, 8, 'Mũtikeke mũkĩatĩĩa maũndũ onthe ala tũkwĩka vaa ũmũnthĩ, kĩla mũndũ o ũndũ wonaa wĩ ũseo methonĩ make;'),
('kam', 'DEU', 12, 9, 'nũndũ mũtyaamba kũlika ũthũmũonĩ na ũtiĩwanĩ, ũla Yeova Ngai waku ũkũnengae.'),
('kam', 'DEU', 12, 10, 'Ĩndĩ yĩla mwĩinga Yolotani, na kũtũa nthĩ ĩla Yeova Ngai wenyu wĩtuma ũmĩtiĩwa, nake aimũnenga kũthũmũa kuma amaithanĩ menyu ala mamũthyũlũlũkĩte, na ĩndĩ mũkikala mũte na mũisyo;'),
('kam', 'DEU', 12, 11, 'nĩvo ĩndĩ kũkeethĩwa kana vala Yeova Ngai wenyu wĩnyuva, ayĩkalye syĩtwa yake vo, o vau mũkatwaa syonthe ila ngũmwĩaĩa: nthembo syenyu sya kũvĩvw’a, na nthembo syenyu sya kũtonywa, na ilungu syenyu sya ĩkũmi, na nthembo ya kũkĩlw’a ya moko menyu, na mawĩvĩto menyu onthe maseo ala mũmwĩvĩtĩaa Yeova.'),
('kam', 'DEU', 12, 12, 'Tanai mbee wa Yeova Ngai wenyu, inyw’ĩ, na ana menyu, na eĩtu menyu, na athũkũmi menyu aũme, na athũkũmi menyu eĩtu, na Mũlivai ũla wĩ kwenyu, nũndũ nde na kĩanda kana ũtiĩwa vamwe nenyu.'),
('kam', 'DEU', 12, 13, 'Ĩsũvĩe ndũkathembe nthembo syaku sya kũvĩvw’a kĩla vandũ wonaa;'),
('kam', 'DEU', 12, 14, 'ĩndĩ vala Yeova wĩnyuva mbaĩnĩ ĩmwe yaku, vau nĩvo ũkathembea nthembo syaku sya kũvĩvw’a, na vau ũkeeka w’onthe ũla nĩkwĩaĩaa.'),
('kam', 'DEU', 12, 15, 'Ĩndĩ, weew’a mũmeo ngoonĩ yaku, nũtonya kũaa nyamũ na kũya wĩ kwaku, kwĩanana na ũathimo wa Yeova Ngai waku ũla wakũnengie: ala avuku na ala atheu matonya kũmĩya, ta nyama ya kĩlong’a, na ya ndaatai nzamba.'),
('kam', 'DEU', 12, 16, 'Ĩndĩ mũtikaye nthakame yasyo; mĩte nthĩ ta manzĩ.'),
('kam', 'DEU', 12, 17, 'Ndũkaĩe kwaku kĩlungu kya ĩkũmi kya lĩu waku wa mbaa ngetha, kana kya mbinyu waku mbĩthĩ, kana kya mauta maku, kana kya kĩla kĩsyawa mbee kya ndĩthya yaku ya ng’ombe kana ya mbũi na malondu, kana mawĩvĩto maku o na meva ala ũmevĩtaa, kana nthembo syaku sya kumya na ngoo ya kwenda, kana nthembo ya kũkĩlw’a ya kw’oko kwaku;'),
('kam', 'DEU', 12, 18, 'ĩndĩ ũkaiĩa mbee wa Yeova Ngai waku vala Yeova Ngai waku wĩnyuva, we, na mwana waku, na mwĩĩtu waku, na mũthũkũmi waku mũndũ mũũme, na mũthũkũmi waku mwĩĩtu, na Mũlivai ũla wĩ kwaku: na ũkatana mbee wa Yeova Ngai waku maũndũnĩ onthe ala mwĩkaa na moko maku.'),
('kam', 'DEU', 12, 19, 'Ĩsũvĩe ndũkaaũlwe nĩ Mũlivai mĩthenya yonthe ĩla wĩ thayũ wĩ nthĩ yaku.'),
('kam', 'DEU', 12, 20, 'Yĩla Yeova Ngai waku ũkongela mũvaka waku, o tondũ wakwathie, naku ũkasya, Ngaya nyama, nĩkwĩthĩwa ngoo yaku yĩ na mũmeo wa kũya nyama; nũtonya kũya nyama, o tondũ ngoo yaku ĩnĩkwenda.'),
('kam', 'DEU', 12, 21, 'Ethĩwa vandũ vala Yeova Ngai waku wĩnyuva, ekĩe syĩtwa yake vo, vethĩwa kũasa naku, nĩvo ĩndĩ wĩũaa kuma ndĩthyanĩ yaku ya ng’ombe na ya mbũi na malondu, ila Yeova ũkũnengete, o tondũ nakwĩaĩe; na nũtonya kũya wĩ kwaku, o tondũ ngoo yaku ĩnĩkwenda.'),
('kam', 'DEU', 12, 22, 'O tondũ kĩlong’a na ndaatai nzamba iĩsawa, o ta ũu ũkaiya: ala avuku na ala atheu matonya kwiya ũndũ ũmwe.'),
('kam', 'DEU', 12, 23, 'Kwata ũndũ ũũ vyũ ndũkaaye nthakame: nũndũ nthakame nĩyo thayũ; na ndũkaaĩsanĩsye thayũ na nyama.'),
('kam', 'DEU', 12, 24, 'Ndũkaamĩye; mĩte nthĩ ta manzĩ.'),
('kam', 'DEU', 12, 25, 'Ndũkaamĩye; nĩ kana kwĩthĩwe ũseo kwaku, na kwa syana syaku ĩtina waku, yĩla ũkeka ũla Yeova wonaa wĩ ũseo.'),
('kam', 'DEU', 12, 26, 'Ĩndĩ syĩndũ syaku ntheu ila wĩ nasyo, na mawĩvĩto maku, syose, na ũithi vala Yeova wĩnyuva;'),
('kam', 'DEU', 12, 27, 'na ũkathembe nthembo syaku sya kũvĩvw’a, nyama na nthakame, kĩthembeonĩ kya Yeova Ngai waku; na nthakame ya nthembo syaku sya kũtonywa ĩta kĩthembeonĩ kya Yeova Ngai waku; naku ũkaya i nyama.'),
('kam', 'DEU', 12, 28, 'Sũvĩa noyĩw’a ndeto ii syonthe ila nĩkwĩaĩaa, nĩ kana kwĩthĩwe ũseo kwaku, na kwa syana syaku ĩtina waku tene na tene, yĩla wĩĩkaa ũla Yeova Ngai waku wonaa wĩ ũseo na wa w’o.'),
('kam', 'DEU', 12, 29, 'Yĩla Yeova Ngai waku ũkaivetanga i mbaĩ syume mbee waku, vala wĩlika kwilũngya, naku ũkailũngya, na kwĩkalaa nthĩ yasyo;'),
('kam', 'DEU', 12, 30, 'ĩsũvĩe ndũkese kũkwatw’a wiatĩĩe, ĩtina wa kwanangwa kwasyo kumw’a mbee waku; na ndũkaakũlye ũvoo wa ngai syasyo, ũkyasya, Mbaĩ ii ithũkũmaa ngai syasyo ata? Nakwa nĩke o ta syo.'),
('kam', 'DEU', 12, 31, 'Ndũkamwĩke ũu Yeova Ngai waku: nĩkwĩthĩwa kĩla ũndũ wa ũmũthatya Yeova, ũla ũmenaa, nĩsyeekĩte ngai syasyo; nũndũ o na ana masyo na eĩtu masyo nivĩvĩasya na mwaki ngai syasyo.'),
('kam', 'DEU', 12, 32, 'Kĩla ndeto nĩmwĩaĩaa, mĩsũvĩe na kũmĩka: ndũkamyongele, kana kũmĩola.'),
('kam', 'DEU', 13, 1, 'Ethĩwa kũkookĩla mwathani kwaku, kana mũoti wa ndoto, nake akĩkũathĩa kyama kana ũseng’yo,'),
('kam', 'DEU', 13, 2, 'na kyama kyu kana ũseng’yo ũsu ũkĩkĩka, ũla wakũathĩe, aikwĩa, Tũvikĩle ngai ingĩ, ila ũtaamanya, na twithũkũme;'),
('kam', 'DEU', 13, 3, 'ndũkethukĩĩsye ndeto sya mwathani ũsu, kana mũoti ũsu wa ndoto: nũndũ Yeova Ngai wenyu nũmũtataa, amanye ethĩwa nĩmũmwendaa Yeova Ngai wenyu na ngoo yenyu yonthe na thayũ wenyu w’onthe.'),
('kam', 'DEU', 13, 4, 'Mũatĩĩei Yeova Ngai wenyu, na mũkĩei we, na kũkwata mĩao yake, na kwĩw’a wasya wake, na mũthũkũmei, na kũlũman’ya nake.'),
('kam', 'DEU', 13, 5, 'Na mwathani ũsu, kana mũoti ũsu wa ndoto akooawa, nĩkwĩthĩwa aĩtye ũeke Yeova Ngai waku, ũla wakumisye nthĩ ya Misili, na ũkwovosya kuma nyũmbanĩ ya ũkombo, akwathũkye wume nzĩanĩ ĩla Yeova Ngai waku wakwĩaĩe ũendae nayo Ũu nĩw’o wĩvetaa ũthũku ũũ wume kwaku.'),
('kam', 'DEU', 13, 6, 'Ethĩwa mwana‐a‐mwenyu, kana mwana waku, kana mwĩĩtu waku, kana kĩveti kya kĩthũinĩ kyaku, kana mũnyanyau, ũla ũilyĩ thayũ waku mwene, akakũsengasenga kĩmbithĩ, aikwĩa, Tũthi tũthũkũme ngai ingĩ, ila ũtaamanya, we, kana aaĩthe maku;'),
('kam', 'DEU', 13, 7, 'ngai sya mbaĩ ila ikũthyũlũlũkĩte, ila syĩ vakuvĩ naku, kana syĩ kũasa naku, kuma ngalĩ ĩmwe ya nthĩ o kũvika ngalĩ ĩla ĩngĩ ya nthĩ;'),
('kam', 'DEU', 13, 8, 'ndũkamwĩtĩkĩle, o na ndũkamwĩthukĩĩsye; itho vaku yĩikamwĩw’ĩe tei; o na ndũkamũeke, o na ndũkamũvithe:'),
('kam', 'DEU', 13, 9, 'ĩndĩ ndũkatĩe kũmũaa; kw’oko kwaku kũkeethĩwa kwa mbee ĩũlũ wake kũmũaa, na ĩtina moko ma andũ onthe.'),
('kam', 'DEU', 13, 10, 'Na mũkimange na mavia akw’e, nĩkwĩthĩwa nũtatĩte ũkũkusya ũtaanĩsye na Yeova Ngai waku, ũla wakumisye nthĩ ya Misili, ũkumya nyũmbanĩ ya ũkombo.'),
('kam', 'DEU', 13, 11, 'Na Isilaeli onthe makeew’a, na kũkĩa, na maikeka ĩngĩ ũthũku wĩana ũu kwaku.'),
('kam', 'DEU', 13, 12, 'Ethĩwa ũkeew’a ndũanĩ ĩmwe yaku, ĩla Yeova Ngai waku ũkũnengae ũtũe vo, ũmwe akyasya,'),
('kam', 'DEU', 13, 13, 'Andũ ang’endu nĩmaumĩte kwaku, na nĩmakusĩtye andũ ma ndũa yoo, makyasya Tũthi tũthũkũme ngai ingĩ, ila mũtaamanya;'),
('kam', 'DEU', 13, 14, 'nĩvo ĩndĩ wĩkũlya, na kũmantha, na kũlya na kĩthing’ĩĩsyo; na, sisya, ethĩwa nĩ wa w’o, na nĩ w’o ki, kana ũthũku ũilyĩ ũu nĩwĩkĩtwe kwaku,'),
('kam', 'DEU', 13, 15, 'no mũvaka ũkũne andũ ma ndũa ĩsu kwa kũmatemanga na ũvyũ, ũkĩmyananga vyũ, na syĩndũ syonthe ila syĩ nthĩnĩ wayo na indo ila syĩ vo, kũtemanga na ũvyũ.'),
('kam', 'DEU', 13, 16, 'Na ũmban’ya mũtavo w’onthe wayo nzĩanĩ nene yayo katĩ, na kũmũvĩvĩsya Yeova Ngai waku ndũa ĩsu na mwaki, na mũtavo w’onthe wayo vyũ: na ĩkeethĩwa mbumbu kũvika tene na tene; ndĩkakwe ĩngĩ.'),
('kam', 'DEU', 13, 17, 'Kĩndũ o na kĩva kya kĩla kĩumanĩe kĩikalũman’ye na kw’oko kwaku; nĩ kana Yeova aeke wai wa ũthatu wake, na ũkwon’ya tei, na ũkwĩw’ĩa ĩnee, na ũkwingĩvya, o tondũ wamevĩtĩe aaĩthe maku;'),
('kam', 'DEU', 13, 18, 'yĩla ũkethukĩĩsya wasya wa Yeova Ngai waku, ũkwate mĩao yake yonthe ĩla ngũkwĩaĩa ũmũnthĩ, wĩke ũla Yeova Ngai waku wonaa wĩ ũseo.'),
('kam', 'DEU', 14, 1, 'Inyw’ĩ mwĩ syana sya Yeova Ngai wenyu: mũikaetemange, kana kwenza mbaa katĩ wa metho menyu kwondũ wa akw’ũ.'),
('kam', 'DEU', 14, 2, 'Nũndũ wĩ mbaĩ ntheu kwa Yeova Ngai waku, na Yeova nũkũnyuvĩte wĩthĩwe mbaĩ yake mwene, kuma ngonĩ syonthe sya andũ ila syĩ ĩũlũ wa nthĩ.'),
('kam', 'DEU', 14, 3, 'Ndũkaaye kĩndũ o na kĩva kĩla kĩthatasya.'),
('kam', 'DEU', 14, 4, 'Ii nĩsyo nyamũ ila mũtonya kũya: ng’ombe, na ĩlondu, na mbũi,'),
('kam', 'DEU', 14, 5, 'ndaatai nzamba, na kĩlong’a, na nthwaĩa nzamba, na mbũi ya kĩthekanĩ, na nthia nzaũ, na ngondi, na ĩsũkũ.'),
('kam', 'DEU', 14, 6, 'Na kĩla nyamũ yĩ na ĩvũngũ yatũe, na yĩ mathaio matũku katĩ, na ĩthaumasya, nyamũnĩ syonthe, nĩyo mũtonya kũya.'),
('kam', 'DEU', 14, 7, 'Ĩndĩ ii mũikaaya sya ila ithaumasya, kana sya ila syĩ na ĩvũngũ yatũe: Ngamĩle, na mbũkũ, na kĩnyowe, nũndũ nithaumasya ĩndĩ iti na ĩvũngũ yatũe, isu nĩ mbuku kwenyu.'),
('kam', 'DEU', 14, 8, 'Na ngũlũe, nũndũ yĩ na ĩvũngũ yatũe ĩndĩ ndĩthaumasya, nayo nĩ mbuku kwenyu: mũikaaye nyama syasyo, na mũikaakiite syĩ ngw’ũ.'),
('kam', 'DEU', 14, 9, 'Ii nĩsyo mũtonya kũya ila syĩ manzĩnĩ: o ĩla yĩ na nthwau na makwaũ nĩmũtonya kũya:'),
('kam', 'DEU', 14, 10, 'na ĩla ĩte na nthwau na makwaũ mũikaaye; nĩ mbuku kwenyu.'),
('kam', 'DEU', 14, 11, 'Nyũnyi syonthe ntheu nĩmũtonya kũya.'),
('kam', 'DEU', 14, 12, 'Ĩndĩ ii nĩsyo ila mũtatonya kũya: ndiũ, na ndiũ ya ĩthingi, na ndei,'),
('kam', 'DEU', 14, 13, 'na kalũmalũmi, na kĩvaalala, na kĩmangaũ o mũthemba wakyo,'),
('kam', 'DEU', 14, 14, 'na ngũngũũ o mũthemba wayo'),
('kam', 'DEU', 14, 15, 'na nyaa, na ĩowe, na ĩng’aa, na mbolosya o mũthemba wayo,'),
('kam', 'DEU', 14, 16, 'na mũnyũũ, na ndundu nene, na ndundu yĩ mbya,'),
('kam', 'DEU', 14, 17, 'na ngunĩ, na ndei ya ĩthingi, na ĩvutavutĩlya,'),
('kam', 'DEU', 14, 18, 'na ĩsaũ, na ĩkũthakũthĩi o mũthemba wayo, na ĩlumi, na ũvuvu.'),
('kam', 'DEU', 14, 19, 'Na tũsamũ tw’onthe tũla twĩ na nthwau na tũtambũkaa nĩ tũvuku kwenyu: tũikaaĩwe.'),
('kam', 'DEU', 14, 20, 'Nyũnyi ntheu syonthe nĩmũtonya kũya.'),
('kam', 'DEU', 14, 21, 'Mũikaaye kĩndũ o na kĩva kya kũkw’a: nũtonya ũkĩnenga mwĩkali wa ũeninĩ wĩ kwaku, akaya; kana nũtonya ũkĩthooesya mũndũ wa nthĩ ĩngĩ: nũndũ wĩ mbaĩ ntheu kwa Yeova Ngai waku. Ndũkaaue katena ka mbũi na ĩia ya inyia wako.'),
('kam', 'DEU', 14, 22, 'Mũvaka wumye kĩlungu kya ĩkũmi kya wingĩvo wa mbeũ syaku, ila syumaa mũũndanĩ kĩla mwaka.'),
('kam', 'DEU', 14, 23, 'Naku ũkaĩa mbee wa Yeova Ngai waku, vala wĩnyuva, ekalye syĩtwa yake vo, kĩlungu kya ĩkũmi kya lĩu waku wa mbaa ngetha, na kya mbinyu yaku mbĩthĩ, na kya mauta maku, na ila isyaawa mbee sya ndĩthya yaku ya ng’ombe, na ya mbũi na malondu; nĩ kana wĩmanyĩsye kũmũkĩaa Yeova Ngai waku mavinda onthe.'),
('kam', 'DEU', 14, 24, 'Na ethĩwa nzĩa nĩ ndasa mũno kwaku, ũndũ ũtatonya kwikua, nĩkwĩthĩwa vandũ vau nĩ vaasa mũno na kwaku, vala Yeova Ngai waku wĩnyuva, ekĩe syĩtwa yake vo, yĩla Yeova Ngai waku ũkakũathima;'),
('kam', 'DEU', 14, 25, 'nĩvo ĩndĩ wĩikũan’ya itw’ĩke mbesa, noyoveea i mbesa kw’okonĩ kwaku, na enda vala Yeova Ngai waku wĩnyuva:'),
('kam', 'DEU', 14, 26, 'na mbesa isu ia kwondũ wa o kĩla ngoo yaku ĩnĩkwenda, kwondũ wa ng’ombe, kana malondu, kana mbinyu, kana kĩla kĩtoonasya, kana o kĩla ngoo yaku yĩkwĩtya; na ũkaĩa vau mbee wa Yeova Ngai waku, na ũkatana, we na ala ma nyũmba yaku.'),
('kam', 'DEU', 14, 27, 'Na Mũlivai ũla wĩ kwaku, ndakaakũle; nũndũ nde na kĩanda kana ũtiĩwa vamwe naku.'),
('kam', 'DEU', 14, 28, 'Kĩla myaka ĩtatũ yathela umasya kĩlungu kyonthe kya ĩkũmi kya wingĩvo wa syĩndũ syaku sya mwaka o ũsu, na ia kwaku:'),
('kam', 'DEU', 14, 29, 'na Mũlivai, nĩkwĩthĩwa nde na kĩanda kana ũtiĩwa vamwe naku, na mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, ala me kwaku, makooka, na makaya na kũvũna; nĩ kana Yeova Ngai waku akũathime wĩanĩ w’onthe wa moko maku ũla ũtethasya.'),
('kam', 'DEU', 15, 1, 'Kĩla myaka mũonza yathela ekanĩai.'),
('kam', 'DEU', 15, 2, 'Na ũekanĩo ũsu ũilyĩ ũũ: kĩla mũndũ ũmũkovethetye mũtũi wake namũekee kyu kĩla ũmũkovethetye; ndakamumĩthye mũtũi wake na mwana‐a‐ĩthe kyo na vinya; nĩkwĩthĩwa ũekanĩo wa Yeova nũtavanĩtw’e.'),
('kam', 'DEU', 15, 3, 'Nũtonya kũmumĩthya mũndũ wa nthĩ ĩngĩ: ĩndĩ kĩla kyaku mwana‐a‐au wĩ nakyo, kw’oko kwaku kũkakĩeke.'),
('kam', 'DEU', 15, 4, 'Ĩndĩ kũikethĩwa ngya kwaku (vate ndĩi Yeova akakũathima wĩ nthĩ ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtĩiwa ũmĩmesye),'),
('kam', 'DEU', 15, 5, 'ethĩwa ũkeethukĩĩsya ki wasya wa Yeova Ngai waku, ũkwate na kwĩka mwĩao ũũ w’onthe ũla ngũkwĩaĩa ũmũnthĩ.'),
('kam', 'DEU', 15, 6, 'Nũndũ Yeova Ngai waku akakũathima, o tondũ wakwathie: na ũkakovethya mbaĩ nyingĩ, ĩndĩ ndũkakova; na ũkaisumbĩka mbaĩ nyingĩ, ĩndĩ itikakũsumbĩka.'),
('kam', 'DEU', 15, 7, 'Ethĩwa kwaku kũkeethĩwa mũndũ ngya, ũmwe wa ana‐a‐au, kwaku nthĩ yaku ĩla Yeova Ngai waku ũkũnengae, ndũkomye ngoo yaku, o na ndũkamũkumbatĩlĩlye kw’oko kwaku mwana‐a‐au e ngya;'),
('kam', 'DEU', 15, 8, 'ĩndĩ ndũtĩa kũmũtambũũkĩsya kw’oko kwaku, na kũmũkovethya kĩla kĩanĩe vata wake, o kĩla ũnũkwenda.'),
('kam', 'DEU', 15, 9, 'Ĩsũvĩe ndũkethĩwe na ũsũanĩo mũthũku ngoonĩ yaku, ũkyasya, Mwaka wa mũonza, naw’o nĩ mwaka wa ũekanĩo, nũthengee; na itho yaku yĩkĩthĩwa yĩ ĩthuku ĩũlũ wa mwana‐a‐au ngya, naku ũilea kũmũnenga kĩndũ; nake akĩmwĩkaĩla Yeova kwondũ waku, na ũndũ ũsu ũkethĩwa naĩ kwaku.'),
('kam', 'DEU', 15, 10, 'Na mũvaka ũmũnenge, na ngoo yaku ndĩkew’a woo ũimũnenga; nĩkwĩthĩwa kwondũ wa ũndũ ũsu Yeova Ngai waku akakũathima wĩanĩ waku w’onthe, na kĩla ũndũnĩ ũla wĩkaa na moko maku.'),
('kam', 'DEU', 15, 11, 'Nũndũ ngya itikathela nthĩ o na ĩndĩĩ: kwondũ wa ũu nĩngũkwĩaĩa, ngyasya, Ndũtĩa kũmũtambũũkĩsya mwana‐a‐au kw’oko kwaku, na ala maku athĩnĩ, na ala maku ngya, nthĩ yaku.'),
('kam', 'DEU', 15, 12, 'Ethĩwa mwana‐a‐au, mũndũ mũũme Mũevelania, kana mũndũ mũka Mũevelania, akathoow’a kwaku, na ũkũthũkũma myaka thanthatũ; nĩvo mwaka wa mũonza ũkamũthasya aume kwaku.'),
('kam', 'DEU', 15, 13, 'Na wamũthasya aume kwaku, ndũkamũeke athi ate na kĩndũ:'),
('kam', 'DEU', 15, 14, 'mũnenge na ũlau kuma ndĩthyanĩ yaku ya mbũi na malondu, na kuma kĩvũĩonĩ kyaku, na kuma kĩangĩonĩ kyaku kya nzavivũ; o tondũ Yeova Ngai waku ũkũathimĩte o ta ũu ũkamũnenga.'),
('kam', 'DEU', 15, 15, 'Na lilikana atĩ waĩ ngombo nthĩ ya Misili, na Yeova Ngai waku akwovosya: kwondũ wa ũu nĩngũkwĩaĩa ũndũ ũsu ũmũnthĩ.'),
('kam', 'DEU', 15, 16, 'Na kũkeethĩwa, ethĩwa akakwĩa, Ndiuma kwaku; nĩkwĩthĩwa nũkwendete we na nyũmba yaku, nĩkwĩthĩwa nĩwoneaa ũseo kwaku;'),
('kam', 'DEU', 15, 17, 'nĩvo ĩndĩ wĩosa mũkuva, noitonya kũtũ kwake amamĩĩsye mũomonĩ, na akeethĩwa mũthũkũmi waku tene na tene. Na ngombo yaku mwĩĩtu ũkamwĩka ta ũu.'),
('kam', 'DEU', 15, 18, 'Ndũkone nĩ vinya ũimũthasya aume kwaku; nũndũ nũkũthũkũmĩte myaka thanthatũ, na nĩ ta ĩtuvi kundũ kwĩlĩ ya mũndũ ũtuvawa; na Yeova Ngai waku akakũathima ũndũnĩ w’onthe ũla wĩkaa.'),
('kam', 'DEU', 15, 19, 'Ila isyaawa mbee syonthe nũme ndĩthyanĩ yaku ya ng’ombe, na ya mbũi na malondu ivanthan’ye syĩthĩwe ntheu kwa Yeova Ngai waku: ndũkatethye wĩa na kĩla kĩsyawa mbee kya ndĩthya yaku ya ng’ombe, o na ndũkatile maw’ĩa ma kĩla kĩsyawa mbee kya ndĩthya yaku ya mbũi na malondu.'),
('kam', 'DEU', 15, 20, 'Kĩĩsĩae mbee wa Yeova Ngai waku kĩla mwaka vandũ vala Yeova wĩnyuva, we na andũ ma nyũmba yaku.'),
('kam', 'DEU', 15, 21, 'Na ethĩwa kĩ kĩema, ethĩwa nĩkĩthuaa kana kĩtyonaa nthĩ, kĩema o na kĩva, ndũkakĩthembee Yeova Ngai waku.'),
('kam', 'DEU', 15, 22, 'Kĩĩsĩae kwaku: ala avuku na ala atheu makaya ũndũ ũmwe, o tondũ maĩsaa kĩlong’a na ndaatai.'),
('kam', 'DEU', 15, 23, 'Ĩndĩ ndũkaaye nthakame yakyo; mĩte nthĩ ta manzĩ.'),
('kam', 'DEU', 16, 1, 'Sũvĩa mwei wa Avivu, na lilikana vasaka kwondũ wa Yeova Ngai waku; nũndũ Yeova Ngai waku nĩwakumisye nthĩ ya Misili ũtukũ mwei wa Avivu.'),
('kam', 'DEU', 16, 2, 'Na mũthembee Yeova Ngai waku vasaka wa ndĩthya ya mbũi na malondu na ya ng’ombe, vandũ vala Yeova wĩnyuva, ekalye syĩtwa yake vo.'),
('kam', 'DEU', 16, 3, 'Ndũkaaye kĩmũtũkĩ ĩlawa vamwe naw’o; mĩthenya mũonza wĩya kĩmũtũ kĩte ĩlawa vamwe naw’o, nĩ kĩmũtũ kya thĩna; nũndũ nĩwaumie nthĩ ya Misili ũindũkĩte: nĩ kana mĩthenya yonthe ya thayũ waku ũlilikane mũthenya ũla waumie nthĩ ya Misili.'),
('kam', 'DEU', 16, 4, 'Na kũikoneke kwaku ĩlawa nthĩnĩ wa mĩvaka yaku yonthe vandũ va mĩthenya mũonza; o na nyama o na yĩva ĩla ũthembaa mũthenya wa mbee wĩoo, ndĩkaaekwe ũtukũ ũsu kũvika kĩoko.'),
('kam', 'DEU', 16, 5, 'Ndũkaathembe vasaka kwaku o na va, ũla Yeova Ngai waku ũkũnengae;'),
('kam', 'DEU', 16, 6, 'ĩndĩ no vandũ vala Yeova Ngai waku wĩnyuva, ekalye syĩtwa yake vo, nĩvo wĩthembea vasaka wĩoo, syũa yĩkĩthũa, ĩvinda ta yĩu, yĩla waumie Misili.'),
('kam', 'DEU', 16, 7, 'Naku wĩua na kũĩa vala Yeova Ngai waku wĩnyuva: na kĩoko kyu ĩthyũũe, ũende maeemanĩ maku.'),
('kam', 'DEU', 16, 8, 'Ĩsaa kĩmũtũ kĩte ĩlawa mĩthenya thanthatũ; na mũthenya wa mũonza wĩthĩwe ũmbano ũkilĩtye wa Yeova Ngai waku; ndũkatethye wĩa mũthenya ũsu.'),
('kam', 'DEU', 16, 9, 'Ĩtalĩle syumwa mũonza: ambĩlĩlya kũtala syumwa mũonza kuma yĩla wĩambĩlĩlya kũketha lĩu ũtũĩtye na kavyũ ke ngoto.'),
('kam', 'DEU', 16, 10, 'Ũkeethĩwa na mboka ya syumwa kwondũ wa Yeova Ngai waku vamwe na ũelo wa nthembo ya kw’oko kwaku ya kumya na kwenda kwa ngoo, ĩla wĩnengane, o kwĩanana na ũndũ Yeova Ngai waku ũkũathimaa:'),
('kam', 'DEU', 16, 11, 'naku ũkatane mbee wa Yeova Ngai waku, we, na mwana waku, na mwĩĩtu waku, na mũthũkũmi waku mũndũ mũũme, na mũthũkũmi waku mwĩĩtu, na Mũlivai ũla wĩ kwaku, na mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, ala matwĩe kwaku, vandũ vala Yeova Ngai waku wĩnyuva, ekalye syĩtwa yake vo.'),
('kam', 'DEU', 16, 12, 'Naku lilikana waĩ ngombo nthĩ ya Misili: na sũvĩa noyĩka myamũlo ĩno yonthe.'),
('kam', 'DEU', 16, 13, 'Ũlilikanae mboka ya malwanda mĩthenya mũonza, wamina kumya kĩvũĩonĩ kyaku na kumya kĩangĩonĩ kyaku kya nzavivũ:'),
('kam', 'DEU', 16, 14, 'na tanĩa mbokanĩ yaku, we, na mwana waku, na mwĩĩtu waku, na mũthũkũmi waku mũndũ mũũme, na mũthũkũmi waku mwĩĩtu, na Mũlivai, na mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, ala me kwaku.'),
('kam', 'DEU', 16, 15, 'Ũkeethĩwa na mboka ya mĩthenya mũonza kwondũ wa Yeova Ngai waku vandũ vala Yeova wĩnyuva; nĩkwĩthĩwa Yeova Ngai waku akakũathima wingĩvyonĩ waku w’onthe, na wĩanĩ w’onthe wa moko maku, na ũkeethĩwa na ũtanu ki.'),
('kam', 'DEU', 16, 16, 'Mavinda atatũ kĩla mwaka aũme maku onthe makookaa mbee wa Yeova Ngai waku vala wĩnyuva: mbokanĩ ya kĩmũtũ kĩte ĩlawa, na mbokanĩ ya syumwa, na mbokanĩ ya malwanda; na matikokae mbee wa Yeova na moko mathei:'),
('kam', 'DEU', 16, 17, 'kĩla mũndũ akanengane o ũndũ ũtonya, kwĩanana na ũathimo wa Yeova Ngai waku ũla ũkũnengete.'),
('kam', 'DEU', 16, 18, 'Maie asili na anene mbingĩlonĩ syaku syonthe, ala Yeova Ngai waku ũkũnengae, kwĩanana na mbaĩ syaku; namo makatusĩaa andũ sila mũlũngalu.'),
('kam', 'DEU', 16, 19, 'Ndũkelelũkasye sila wa katĩ: ndũkamendeeasye andũ; ndũkaose ĩvaki; nũndũ ĩvaki nĩyĩlindaa metho ma ala oĩ, na kwelelũkasya ndeto sya ala alũngalu.'),
('kam', 'DEU', 16, 20, 'Atĩĩa ũla ũlũngalu ki, nĩ kana wĩthĩwe thayũ, na kũtiĩwa nthĩ ĩla Yeova Ngai waku ũkũnengae.'),
('kam', 'DEU', 16, 21, 'Ndũkenzĩle Asela wa mũtĩ wa mũthemba o na wĩva ũtee wa kĩthembeo kya Yeova Ngai waku, ũla ũkeseũvĩsya.'),
('kam', 'DEU', 16, 22, 'O na ndũkeũngamĩsye kĩtuĩ; kĩla Yeova Ngai waku ũmenaa.'),
('kam', 'DEU', 17, 1, 'Ndũkathembee Yeova Ngai waku ng’ombe, kana ĩlondu, yĩla yĩ kĩema, kana ũndũ o na wĩva ũthũku; nũndũ ũndũ ũsu nũmũthatasya Yeova Ngai waku.'),
('kam', 'DEU', 17, 2, 'Ethĩwa kũkooneka nthĩnĩ waku, nthĩnĩ wa mbingĩlo syaku o na syĩva ila Yeova Ngai waku ũkũnengae, mũndũ mũũme kana mũndũ mũka, ũla wĩkaa ũla Yeova Ngai waku wonaa wĩ ũthũku, aivĩtya ũtianĩo wake,'),
('kam', 'DEU', 17, 3, 'na nĩ mũendu kũthũkũma ngai ingĩ, na kwithaitha, kana syũa, kana mwei, kana imwe sya nguthu ya ĩtunĩ, ũndũ ndaeaa,'),
('kam', 'DEU', 17, 4, 'na watavw’a, na nũwĩw’ĩte; nĩvo ĩndĩ wĩkũlya na kĩthing’ĩĩsyo; na, sisya, ethĩwa nĩ wa w’o, vate ndĩi, kana ũthũku ũsu nĩwĩkĩtwe nthĩnĩ wa Isilaeli,'),
('kam', 'DEU', 17, 5, 'nĩvo ĩndĩ mumaalye mbingĩlonĩ syaku mũndũ mũũme ũsu kana mũndũ mũka ũsu, ũla wĩkĩte ũndũ ũsu ũthũku, o mũndũ mũũme kana mũndũ mũka; na makimange na mavia makw’e.'),
('kam', 'DEU', 17, 6, 'Kwa kanyw’a wa ngũsĩ ilĩ, kana ngũsĩ itatũ, ũla wa kũawa nĩoaawe; ndakoawe kwa kanyw’a wa ngũsĩ ĩmwe.'),
('kam', 'DEU', 17, 7, 'Moko ma ngũsĩ isu methĩwe ma mbee ĩũlũ wake kũmũaa, na ĩtina moko ma andũ onthe. Ũu nĩw’o wĩvetaa ũthũku ũsu wume kwaku.'),
('kam', 'DEU', 17, 8, 'Ethĩwa kũkookĩla ũndũ ũkũema silanĩ, katĩ wa nthakame na nthakame, katĩ wa mũandũi na mũandũwa, katĩ wa ĩkũna na ĩkũna, namo nĩ maũndũ ala meũkananĩwa nthĩnĩ wa mbingĩlo syaku; nĩvo ĩndĩ wĩũkĩla na kwambata vala Yeova Ngai waku wĩnyuva;'),
('kam', 'DEU', 17, 9, 'na ũmaendee athembi Alivai, na ũla ũkethĩwa mũsili mĩthenya ĩsu: na makũlye; na makakwon’ya ũtw’ĩo wa sila.'),
('kam', 'DEU', 17, 10, 'Naku wĩĩka kwĩanana na ũtw’ĩo ũla mekwonesya vandũ vu vala Yeova wĩnyuva; na sũvĩa na kwĩka w’onthe ũla mekũmanyĩsya:'),
('kam', 'DEU', 17, 11, 'kwĩanana na mĩao ĩla mekũmanyĩsya, na kwĩanana na ũtw’ĩo ũla mekũtavya, wĩĩka ũu; ndũkaaathũke kuma ũtw’ĩonĩ ũla mekwon’ya, ngalĩ ya kw’oko kwa aũme, kana kw’oko kwa aka.'),
('kam', 'DEU', 17, 12, 'Na mũndũ ũla wĩng’endaa, akĩlea kũmwĩthukĩĩsya mũthembi ũla ũũngamaa athũkũme mbee wa Yeova Ngai waku, kana mũsili, mũndũ ũsu akakw’e: naku ũkaveta ũthũku ũsu kwa Isilaeli.'),
('kam', 'DEU', 17, 13, 'Na andũ onthe makeew’a, na kũkĩa, na matikang’enda ĩngĩ.'),
('kam', 'DEU', 17, 14, 'Yĩla wĩvika nthĩ ĩla Yeova Ngai waku ũkũnengae, na wamĩmesya, na kũtũa vo, na kwasya, Ngaia mũsumbĩ anzumbĩke, ta mbaĩ syonthe ila inthyũlũlũkĩte;'),
('kam', 'DEU', 17, 15, 'mũvaka ũmwie ũla Yeova Ngai waku wĩnyuva ethĩwe mũsumbĩ waku; ia ũmwe wa ana‐a‐au akũsumbĩke; ndũkaamũsumbĩkye mũndũ wa nthĩ ĩngĩ, ũla ũte mwana‐a‐au.'),
('kam', 'DEU', 17, 16, 'Ĩndĩ ndakaingĩvye mbalasi kwake, kana kũtuma andũ masyoka Misili, nĩ kana aingĩvye mbalasi; nũndũ Yeova nũmũtavĩtye, Mũtikasyokee ĩngĩ nzĩa ĩsu.'),
('kam', 'DEU', 17, 17, 'O na ndakatwae aka aingĩ, ngoo yake ndĩkathyũũwe: o na ndakaeyingĩvĩsye vetha kana thaavu.'),
('kam', 'DEU', 17, 18, 'Na kũkeethĩwa, yĩla wĩĩkalĩla kĩvĩla kya ũsumbĩ wake, eĩyumĩĩĩsya ũandĩko wa mĩao ĩno ĩvukunĩ, kũatĩĩa ĩvuku yĩla yĩ na athembi Alivai:'),
('kam', 'DEU', 17, 19, 'na akĩthĩwa nayo, na akĩyĩsomaa mĩthenya yonthe ya thayũ wake; nĩ kana emanyĩsye kũkĩa Yeova Ngai wake, kũkwata ndeto syonthe sya mĩao ĩno na myamũlo ĩno, kũsyĩkaa;'),
('kam', 'DEU', 17, 20, 'nĩ kana ngoo yake ndĩkaaĩnenevye ĩũlũ wa ana‐a‐ĩthe make, na nĩ kana ndakaaathũke na kũtia ũla mwĩao, ngalĩ ya kw’oko kwa aũme, kana aka: nĩ kana aingĩvye matukũ make ũsumbĩnĩ wake, we na syana syake, nthĩnĩ wa Isilaeli.'),
('kam', 'DEU', 18, 1, 'Athembi Alivai, o mbaĩ yonthe ya Alivai, matikethĩwe na kĩanda kana ũtiĩwa vamwe na Isilaeli: makaye nthembo sya Yeova ila ivĩvaw’a na mwaki, nĩsyo ũtiĩwa wake.'),
('kam', 'DEU', 18, 2, 'Na matikethĩwe na ũtiĩwa katĩ wa ana‐a‐ĩthe moo: Yeova nĩwe ũtiĩwa woo, o tondũ ũneenete nao.'),
('kam', 'DEU', 18, 3, 'Na kĩĩ nĩkyo kyaĩle kwĩthĩwa kya mũthembi kuma andũnĩ, kuma kwa ala mathembaa nthembo ya kũtonywa, ethĩwa nĩ ng’ombe kana ĩlondu, manenge mũthembi kĩtuo, na ngambuu syelĩ, na ĩvu.'),
('kam', 'DEU', 18, 4, 'Mosyao ma mbee ma lĩu waku wa mbaa ngetha, na ma mbinyu yaku mbĩthĩ, na ma mauta maku, na w’ĩa wa mbee wa malondu maku, mũnenge isu.'),
('kam', 'DEU', 18, 5, 'Nũndũ Yeova Ngai waku nũmũnyuvĩte kuma mbaĩnĩ syaku syonthe, aũngamae kũthũkũma syĩtwanĩ ya Yeova, we na ana make tene na tene.'),
('kam', 'DEU', 18, 6, 'Na ethĩwa Mũlivai akooka kuma mbingĩlonĩ syaku o na syĩva nthĩnĩ wa Isilaeli onthe, vala wekalaa ũeni, akyũka na kwenda kw’onthe kwa ngoo yake vala Yeova wĩnyuva;'),
('kam', 'DEU', 18, 7, 'nĩvo ĩndĩ wĩthũkũma syĩtwanĩ ya Yeova Ngai wake, o tondũ ana‐a‐ĩthe make onthe Alivai mekaa, ala maũngamaa mbee wa Yeova.'),
('kam', 'DEU', 18, 8, 'Makeethĩwa na ilungu sya ũya syĩanene, vamwe na kĩla wosaa kwondũ wa ũthoosya ũtiĩwa wa ĩthe wake.'),
('kam', 'DEU', 18, 9, 'Walika nthĩ ĩla Yeova Ngai waku ũkũnengae, ndũkemanyĩsye kwĩka mothatyo ma mbaĩ isu.'),
('kam', 'DEU', 18, 10, 'Kũikaoneke kwaku mũndũ ũla ũkũmũvĩtĩlya mwana wake kana mwĩĩtu wake mwakinĩ, kana ũla ũaũasya, kana ũla ũingasya nyũnyi kana mũndũ mũe, kana mũoi,'),
('kam', 'DEU', 18, 11, 'kana mwĩki wa syama, kana ũla ũkũlasya ala mesene na maveva, kana ũla ũmbasya ithitũ, kana ũla ũkũlasya akw’ũ.'),
('kam', 'DEU', 18, 12, 'Nũndũ ũla wĩkaa maũndũ asu nũmũthatasya Yeova: na kwondũ wa mothatyo asu Yeova Ngai waku nũmalũngasya maume mbee wake.'),
('kam', 'DEU', 18, 13, 'Ĩthĩwa mwĩanĩu mbee wa Yeova Ngai waku.'),
('kam', 'DEU', 18, 14, 'Nũndũ mbaĩ isu, ila wĩlũngya syume kwoo, syĩthukĩĩasya ala maingasya nyũnyi, na ala maaũasya; ĩndĩ we, Yeova Ngai waku ndakũnengete ũthei wa kwĩka ũu.'),
('kam', 'DEU', 18, 15, 'Yeova Ngai waku akakũkĩlĩlya mwathani kuma katĩ waku, kuma katĩ wa ana‐a‐au, ũilyĩ takwa; mwĩthukĩĩsyei;'),
('kam', 'DEU', 18, 16, 'kwĩanana na w’onthe ũla wamwĩtĩsye Yeova Ngai waku Olevu mũthenya wa ũla ũmbano, ũkyasya, Ndikew’e ĩngĩ wasya wa Yeova Ngai wakwa, o na ndikasisye mwaki ũũ mũnene ĩngĩ, ndikakw’e.'),
('kam', 'DEU', 18, 17, 'Na Yeova ambĩa, Nĩmaneena nesa ũndũ maneena.'),
('kam', 'DEU', 18, 18, 'Ngamokĩlĩlya mwathani kuma katĩ wa ana‐a‐ĩthe moo, ũilyĩ taku; na ngeekĩa ndeto syakwa kanyw’anĩ wake, nake akamatavya w’onthe ũla ngamwĩaĩa.'),
('kam', 'DEU', 18, 19, 'Na kũkeethĩwa, kana o ũla ũtakethukĩĩsya ndeto syakwa ila ũkaneena syĩtwanĩ yakwa, ngaandũa ũndũ ũsu kwake.'),
('kam', 'DEU', 18, 20, 'Ĩndĩ mwathani, ũla ũkaneena ndeto sya mĩtavyo syĩtwanĩ yakwa, ĩla ndaamwĩaĩa aneene, kana ũla ũkaneena syĩtwanĩ ya ngai ingĩ, mwathani ũsu nakw’e.'),
('kam', 'DEU', 18, 21, 'Na ethĩwa wĩasya ngoonĩ yaku, Tũkamanya ata ndeto ĩla Yeova ũtaneenete?'),
('kam', 'DEU', 18, 22, 'Yĩla mwathani ũneenaa syĩtwanĩ ya Yeova, ethĩwa ũndũ ũsu ndwĩĩthĩwa, o na ndwĩĩkĩka, ũu nĩw’o ũla Yeova ũtaaneena: mwathani ũsu aneenete na mĩtavyo, ndũkamũkĩe.'),
('kam', 'DEU', 19, 1, 'Yĩla Yeova Ngai waku ũkaveta mbaĩ, ila Yeova Ngai waku ũkũnengae nthĩ yasyo, naku woosa nthĩ yasyo, na kũtũa ndũanĩ syasyo, na nyũmba syasyo;'),
('kam', 'DEU', 19, 2, 'ĩvathĩe ndũa itatũ nthĩnĩ wa nthĩ yaku, ĩla Yeova Ngai waku ũkũnengae ũmĩmesye.'),
('kam', 'DEU', 19, 3, 'Ĩseũvĩsye nzĩa, na atũan’ya mĩvaka ya nthĩ yaku, ĩla Yeova Ngai waku wĩtuma ũmĩtiĩwa, yĩthĩwe ilungu itatũ, nĩ kana kĩla mũndũ ũkoaa ũngĩ akĩĩe vo.'),
('kam', 'DEU', 19, 4, 'Na ũũ nĩw’o ũvoo wa ũla ũkoaa ũngĩ, ũla ũkakĩĩa vo na kwĩkala thayũ: o ũla ũkoaa mũtũi wake na mbanga, na ndatwĩe e ũthũ nake;'),
('kam', 'DEU', 19, 5, 'ta yĩla mũndũ ũendaa mũtitũnĩ e na mũtũi wake kũtema mĩtĩ, na kw’oko kwake kũkyũkĩlya ĩthoka ateme mũtĩ, na ĩthoka yĩisingĩla, na kũkũna mũtũi wake, na aikw’a; nake akakĩĩa ndũa ĩmwe ya isu na kwĩkala thayũ:'),
('kam', 'DEU', 19, 6, 'mũĩvanĩsya wa nthakame ndakese kũmũatĩĩa mũaani, yĩla wĩ na ũthatu ngoonĩ, na kũmũkwata, nũndũ nzĩa nĩ ndasa, na kũmũkũna akw’e; nake ndaĩlwe nĩ kũkw’a, nũndũ ndatwĩe e ũthũ nake.'),
('kam', 'DEU', 19, 7, 'Kwondũ wa ũu nĩngũkwĩaĩa, ngyasya, Ĩvathĩe ndũa itatũ.'),
('kam', 'DEU', 19, 8, 'Na ethĩwa Yeova Ngai waku akongela mũvaka waku, o tondũ wameavĩe aaĩthe maku, na ũkũnenga nthĩ yonthe ĩla wathie akamanenga aaĩthe maku;'),
('kam', 'DEU', 19, 9, 'ethĩwa ũkakwata mwĩao ũũ w’onthe ũwĩke, ũla ngũkwĩaĩa ũmũnthĩ, ũmwende Yeova Ngai waku, na kũendaa nzĩanĩ syake mavinda onthe; nĩvo ĩndĩ wĩyongela ndũa ingĩ itatũ, vamwe na isu itatũ:'),
('kam', 'DEU', 19, 10, 'nĩ kana nthakame ĩte ĩvĩtyo ndĩketĩkw’e nthĩ yaku, ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtiĩwa, na kwondũ wa ũu nthakame ĩkĩthĩwa ĩũlũ waku.'),
('kam', 'DEU', 19, 11, 'Ĩndĩ ethĩwa mũndũ o na wĩva nũmenete mũtũi wake, na kũmwoveesya, na kũmũkĩlĩla, na kũmũkũna akw’e, nake aikĩĩa ndũanĩ ĩmwe ya isu;'),
('kam', 'DEU', 19, 12, 'nĩvo ĩndĩ atumĩa ma ndũa yake matũmane na kũmumya vo, na kũmũnengane mokonĩ ma mũĩvanĩsya wa nthakame, nĩ kana akw’e.'),
('kam', 'DEU', 19, 13, 'Metho maku matikamwĩw’ĩe tei, ĩndĩ veta kũasa na Isilaeli nthakame ĩte ĩvĩtyo, nĩ kana kwĩthĩwe ũseo kwaku.'),
('kam', 'DEU', 19, 14, 'Ndũkaakũĩĩsya kyambo kya mũvaka wa mũtũi waku, kĩla ala ma tene meekĩie, ũtiĩwanĩ waku ũla ũkatiĩwa, nthĩ ĩla Yeova Ngai waku ũkũnengae ũmĩmesye.'),
('kam', 'DEU', 19, 15, 'Ngũsĩ ĩmwe ndĩkakũsĩĩe mũndũ kwondũ wa ũthũku o na wĩva, kana naĩ o na yĩva, naĩnĩ o na yĩva ĩla wĩkaa: kwa kanyw’a wa ngũsĩ ilĩ, kana kwa kanyw’a wa ngũsĩ itatũ, ũndũ ũkalũma.'),
('kam', 'DEU', 19, 16, 'Ethĩwa ngũsĩ ĩte ya w’o ĩkamũkĩlĩla mũndũ o na wĩva ĩmũkũsĩĩe kana nĩwĩkĩte naĩ,'),
('kam', 'DEU', 19, 17, 'nĩvo ĩndĩ andũ asu elĩ ala me na ngananĩo katĩ wamo, meũngama mbee wa Yeova, mbee wa athembi na asili ala makethĩwa mĩthenya ĩsu;'),
('kam', 'DEU', 19, 18, 'na asili mamanthe na kĩthing’ĩĩsyo: na, sisya, ethĩwa ngũsĩ nĩ ngũsĩ ya ũvũngũ, na ĩmũkũsĩĩe mwana‐a‐ĩthe ũvũngũ;'),
('kam', 'DEU', 19, 19, 'nĩvo ĩndĩ yĩkwe, o ũndũ ĩsũanĩĩte kũmwĩka mwana‐a‐ĩthe: ũu nĩw’o wĩvetaa ũthũku ũsu wume kwaku.'),
('kam', 'DEU', 19, 20, 'Na ala metiala makeew’a, na kũkĩa, na maikeka ĩngĩ ũthũku ta ũsu kwaku.'),
('kam', 'DEU', 19, 21, 'Na itho yaku yĩtikew’ĩe tei; thayũ vandũ va thayũ, itho vandũ va itho, ĩeo vandũ va ĩeo, kw’oko vandũ va kw’oko, kũũ vandũ va kũũ.'),
('kam', 'DEU', 20, 1, 'Yĩla wĩendaa kũkita na amaitha maku, na woona mbalasi, na makasya ma kaũ, na andũ aingĩ kwĩ we, ndũkamakĩe; nũndũ Yeova Ngai waku e vamwe naku, ũla wakumisye nthĩ ya Misili.'),
('kam', 'DEU', 20, 2, 'Na kũkeethĩwa, yĩla mwĩthengeea kaũnĩ, mũthembi akathengeea na kũneena na andũ,'),
('kam', 'DEU', 20, 3, 'na akamea, Ĩw’ai, Isilaeli, ũmũnthĩ nĩmũthengeea kũkita na amaitha menyu: ngoo syenyu itikaleele; mũikakĩe, kana kũtetema, o na mũikatĩsw’e nĩo;'),
('kam', 'DEU', 20, 4, 'nũndũ Yeova Ngai wenyu nĩwe ũendaa nenyu, ũmũkitĩaa amitha menyu, amũtangĩĩe.'),
('kam', 'DEU', 20, 5, 'Na anene makaneena na andũ, makyasya, Nĩ mũndũ wĩva ũla wakĩte nyũmba nzaũ, na ndanamba ũmĩvingũa? Naende asyoke nyũmbanĩ kwake, ndakese kũkw’ĩa kaũnĩ, na mũndũ ũngĩ aimĩvingũa.'),
('kam', 'DEU', 20, 6, 'Na nĩ mũndũ wĩva ũla ũvandĩte mũũnda wa mĩsavivũ, na ndanamba kũya ũsyao waw’o? Naende asyoke nyũmbanĩ kwake, ndakese kũkw’ĩa kaũnĩ, na mũndũ ũngĩ aiya ũsyao waw’o.'),
('kam', 'DEU', 20, 7, 'Na nĩ mũndũ wĩva ũla ũasĩtye mwĩĩtu, na ndanamba ũmũtwaa? Naende asyoke nyũmbanĩ kwake, ndakese kũkw’ĩa kaũnĩ, na mũndũ ũngĩ aimũtwaa.'),
('kam', 'DEU', 20, 8, 'Na anene asu makaendeea na kũneena na andũ, na makasya, Nũũ ũla wĩ na w’ĩa na mũleelu ngoonĩ? Naende asyoke nyũmbanĩ kwake, ngoo sya ana‐a‐ithe make itikese kũtweka o ta ngoo yake.'),
('kam', 'DEU', 20, 9, 'Na kũkeethĩwa, anene mamina kũneena na andũ, makaia makavuteni ma nguthu methĩwe atongoi ma andũ.'),
('kam', 'DEU', 20, 10, 'Yĩla ũkathengeea ndũa ũkite nayo, nĩvo ĩndĩ mĩkũlye wĩw’ano.'),
('kam', 'DEU', 20, 11, 'Na kũkeethĩwa, ethĩwa ĩkakũsũngĩa ũsũngĩo wa mũuo, na ũkũvingũĩa, nĩvo kũkethĩwa, kana andũ onthe ala makethĩwa nthĩnĩ wayo makatw’ĩka maku, na makakũthũkũma.'),
('kam', 'DEU', 20, 12, 'Na ethĩwa ĩkalea kwĩw’ana naku, ĩndĩ ĩkenda kũkita naku, nĩvo ũkamĩthyũlũlũka ũmĩtw’ĩkanĩsye:'),
('kam', 'DEU', 20, 13, 'na yĩla Yeova Ngai waku ũkamĩnengane kw’okonĩ kwaku, ũaa kĩla mũndũ mũũme wayo kwa kũmũtemanga na ũvyũ:'),
('kam', 'DEU', 20, 14, 'ĩndĩ aka, na twana tũnini, na indo, na kyonthe kĩla kĩ ndũanĩ, o mũtavo wayo w’onthe, osa wĩthĩwe waku mwene; na wĩya mũtavo wa amaitha maku, ũla Yeova Ngai waku ũkũnengete.'),
('kam', 'DEU', 20, 15, 'Ĩka ũu ndũa syonthe ila syĩ kũasa naku, ila ite sya ndũa sya mbaĩ ii.'),
('kam', 'DEU', 20, 16, 'Ĩndĩ nthĩnĩ wa ndũa sya mbaĩ ii, ila Yeova Ngai waku ũkũnengae syĩthĩwe ũtiĩwa waku, ndũkakĩtie kĩ thayũ kĩndũ kĩla kĩvevaa;'),
('kam', 'DEU', 20, 17, 'ĩndĩ maminei vyũ: Mũititi, na Mũamoli, na Mũkanaani, na Mũvelisi, na Mũivi, na Mũyevusi; o tondũ Yeova Ngai waku wakwĩaĩe;'),
('kam', 'DEU', 20, 18, 'maikese kũmũmanyĩsya kwĩka maũndũ moo onthe ala mathatasya, ala mekaa kwondũ wa ngai syoo; na mweeka ũu mũkamwĩka Yeova Ngai wenyu naĩ.'),
('kam', 'DEU', 20, 19, 'Yĩla ũkathyũlũlũka ndũa ũmĩtw’ĩkanĩsye ĩvinda ĩasa, ũkyũkita nayo ũmĩkwate, ndũkanange mĩtĩ yayo ũitemanga na ĩthoka; nũndũ nũtonya kũya ũsyao wayo, na ndũkamĩteme; nũndũ mũtĩ wa mũũnda nĩ mũndũ, ũndũ ũkita naw’o?'),
('kam', 'DEU', 20, 20, 'Ĩndĩ mĩtĩ ĩla wĩsĩ ti mĩtĩ ya kũĩwa, myanange na kũmĩtema; na akĩĩa ngome ndũa ĩsu ĩla ĩnĩũkita naku, mũvaka yĩla ĩvalũka.'),
('kam', 'DEU', 21, 1, 'Ethĩwa kũkooneka mũndũ wũaĩwe nthĩ ĩla Yeova Ngai waku ũkũnengae ũmĩmesye, e mũũndanĩ, na ndesĩkĩwe ũla wamũaie;'),
('kam', 'DEU', 21, 2, 'nĩvo ĩndĩ atumĩa maku na asili maku meumaalaa, na maithima ndũa ila imũthyũlũlũkĩte ũsu ũla wũaĩtwe;'),
('kam', 'DEU', 21, 3, 'na kũkeethĩwa ndũa ĩla yĩ vakuvĩ na mũndũ ũla wũaĩtwe, o atumĩa ma ndũa ĩsu makose moi ya ndĩthya, ĩla ĩtaatethya wĩa, na ĩla ĩtaakusya na ĩsoki;'),
('kam', 'DEU', 21, 4, 'na atumĩa ma ndũa ĩsu makatwaa moi ĩsu mwandanĩ ũla wĩ manzĩ mavĩtĩte, ũla ũtenzĩtwe kana kũvandwa, na makatũlĩla ngingo ya moi vu mwandanĩ.'),
('kam', 'DEU', 21, 5, 'Na athembi ana ma Livai mathengee, nĩkwĩthĩwa nĩmo Yeova Ngai waku wamanyuvie mamũthũkũme, na kũathima syĩtwanĩ ya Yeova; na kĩla ngananĩo na kĩla ĩkũnwa yĩkeethĩwa kwĩanana na ndeto yoo.'),
('kam', 'DEU', 21, 6, 'Na atumĩa onthe ma ndũa ĩsu, ala me vakuvĩ na mũndũ ũla woaiwe, mathambĩsye moko moo ĩũlũ wa moi ĩla ngingo yayo yatũlĩlwa mwandanĩ;'),
('kam', 'DEU', 21, 7, 'na makasũngĩa na kwasya, Moko maitũ matyaaĩtĩkya nthakame ĩno, o na metho maitũ matyaamyona.'),
('kam', 'DEU', 21, 8, 'Ame Yeova, ekea andũ maku Isilaeli, ala wamovoisye, na ndũkaeke nthakame ĩte na ĩvĩtyo kwĩkalaa katĩ wa andũ maku Isilaeli. Na makaekewa ĩla nthakame.'),
('kam', 'DEU', 21, 9, 'Ũu nĩw’o wĩvetaa nthakame ĩte na ĩvĩtyo yume katĩ waku, yĩla wĩĩkaa ũla Yeova wonaa wĩ ũseo.'),
('kam', 'DEU', 21, 10, 'Yĩla wĩthĩ kũkita na amaitha maku, na Yeova Ngai waku aimanengane mokonĩ maku, naku ũimatwaa me atave,'),
('kam', 'DEU', 21, 11, 'na kwona katĩ wa ala matavĩtwe mũndũ mũka mwanake, naku ũimwĩw’ĩa ĩtomo, na ũyenda kũmũtwaa ethĩwe mũka waku;'),
('kam', 'DEU', 21, 12, 'nĩvo ĩndĩ mũtwae kwaku nyũmbanĩ yaku; nake nĩenze mũtwe wake, na kwela mbwaa syake;'),
('kam', 'DEU', 21, 13, 'na akaumye ngũa ya kũtavwa kwake, na kwĩkala nyũmbanĩ yaku, na kũmaĩĩa ĩthe na nyinyia mwei mũima: na ĩtina wa ũu lika kwake, wĩthĩwe mũũme wake, nake ethĩwe mũka waku.'),
('kam', 'DEU', 21, 14, 'Na kũkeethĩwa, ethĩwa ndũkwendeew’a nĩwe, mũnenge ũthei aende o vala ũnũkwenda; ĩndĩ ndũkamũthoosye mbesa, ndũkamwĩke ta ngombo, nũndũ nĩwamũthũkisye.'),
('kam', 'DEU', 21, 15, 'Ethĩwa mũndũ e na aka elĩ, ũmwe mwende, na ũla ũngĩ mũmene, na makĩmũsyaĩa syana, ũla wendetwe na ũla ũmenetwe me elĩ; na ethĩwa ĩkithathi nĩ ya ũla ũmenetwe;'),
('kam', 'DEU', 21, 16, 'nĩvo kũkeethĩwa, mũthenya ũla ũkatuma ana make matĩĩwa kĩla wĩ nakyo, ndatonya kũmũtw’a mwana wa mũndũ mũka ũla wendetwe ĩkithathi yĩla mwana wa ũla ũmenetwe wĩ thayũ, nake nĩwe ĩkithathi:'),
('kam', 'DEU', 21, 17, 'ĩndĩ nĩetĩkĩle yĩla ĩkithathi, mwana wa ũla ũmenetwe, aiyĩnenga kũndũ kwĩlĩ syĩndũnĩ syonthe ila wĩ nasyo; nũndũ nĩwe wambĩlĩlyo wa vinya wake; ũtiĩwa wa ũkithathi nĩ wake.'),
('kam', 'DEU', 21, 18, 'Ethĩwa mũndũ e na mwana mbaa matũ na mũng’endu, ũla ũtew’aa wasya wa ĩthe, kana wasya wa nyinyia, o na mamũkũna, ndamew’aa;'),
('kam', 'DEU', 21, 19, 'nĩvo ĩthe wake na nyinyia mamũkwate, na kũmumĩlya kwa atumĩa ma ndũa yake, na mbingĩlonĩ ya vandũ vake;'),
('kam', 'DEU', 21, 20, 'na mamatavye atumĩa ma ndũa yake, Mwana ũũ waitũ nĩ mbaa matũ na mũng’endu, ndethukĩĩasya wasya witũ; nĩ mũyi na mũnywi.'),
('kam', 'DEU', 21, 21, 'Na aũme onthe ma ndũa yake makamũkimange na mavia akw’e: ũu nĩw’o wĩvetaa ũthũku wume kwaku; na Isilaeli onthe makeew’a, na kũkĩa.'),
('kam', 'DEU', 21, 22, 'Na ethĩwa mũndũ ekĩte naĩ yaĩle kĩkw’ũ, na ooawa, na ũimũsũsya mũtĩnĩ;'),
('kam', 'DEU', 21, 23, 'kimba kyake kĩtikekale ũtukũ w’onthe mũtĩnĩ, ĩndĩ no mũvaka ũkĩthike mũthenya o ũsu; nũndũ ũla ũsũĩtwe mũtĩnĩ nũumanĩwe nĩ Ngai; nĩ kana ndũkavukye nthĩ yaku ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtiĩwa.'),
('kam', 'DEU', 22, 1, 'Woona ng’ombe ya mwana‐a‐au kana ĩlondu yake yaĩte, ndũkeke ta ũtanasyona: no mũvaka witũnge kwa mwana‐a‐au.'),
('kam', 'DEU', 22, 2, 'Na ethĩwa mwana‐a‐au nde vakuvĩ naku, kana ethĩwa ndũmwĩsĩ, nĩvo ĩndĩ mĩtwae kwaku nyũmbanĩ yaku, na ĩkekala kwaku kũvika yĩla mwana‐a‐au wĩmĩmantha, na ĩndĩ ũimũtũngĩa.'),
('kam', 'DEU', 22, 3, 'Na ĩka ta ũu na ĩng’oi yake; na ĩka ta ũu na ngũa yake; na ĩka ta ũu na kĩla kĩndũ kyaĩte kya mwana‐a‐au, kĩla waĩtye, naku wakyona: ndũkeke ta ũtanakyona.'),
('kam', 'DEU', 22, 4, 'Woona ĩng’oi ya mwana‐a‐au kana ng’ombe yake ĩvalũkĩte ũtee wa nzĩa, naku ndũkeke ta ũtanasyona: no mũvaka ũmũtethye kũsyũkĩlya.'),
('kam', 'DEU', 22, 5, 'Mũndũ mũka ndakekĩe ngũa ila syĩkĩawa nĩ mũndũ mũũme, o na mũndũ mũũme ndakekĩe ngũa ila syĩkĩawa nĩ mũndũ mũka; nũndũ o ũla wĩkaa maũndũ asu nũthatasya Yeova Ngai waku.'),
('kam', 'DEU', 22, 6, 'Ethĩwa ndala ya nyũnyi ĩkeethĩwa mbee waku nzĩanĩ, mũtĩnĩ o na wĩva kana nthĩ, yĩ na tũswii kana matumbĩ, ndũkakwate inyia vamwe na tũswii:'),
('kam', 'DEU', 22, 7, 'na mũvaka ũlekye inyia, ĩndĩ tũswii nũtonya kwĩyosea; nĩ kana wĩthĩwe ũseo kwaku, na nĩ kana wingĩvye mĩthenya yaku.'),
('kam', 'DEU', 22, 8, 'Waaka nyũmba nzaũ, nĩvo ĩndĩ akĩĩa wiio ũengonĩ wa kĩala kyayo, nĩ kana ndũkaete nthakame ĩũlũ wa nyũmba yaku, ethĩwa mũndũ akavalũka kuma vo.'),
('kam', 'DEU', 22, 9, 'Ndũkaavande mũũnda waku wa mĩsavivũ mbeũ sya mĩthemba ĩlĩ, ũsyao w’onthe ndũkese kwanangana, mbeũ ila wavandie, na ũsyao wa mũũnda wa mĩsavivũ.'),
('kam', 'DEU', 22, 10, 'Ndũkaaĩme na ng’ombe na ĩng’oi vamwe.'),
('kam', 'DEU', 22, 11, 'Ndũkaekĩe ngũa ĩvulanĩtye ndii sya mĩthemba ĩlĩ, ya w’ĩa wa ĩlondu na ya katane vamwe.'),
('kam', 'DEU', 22, 12, 'Ĩsyũlĩlye manyenze motiivonĩ ana ma ngũa yaku ya kwĩvw’ĩka.'),
('kam', 'DEU', 22, 13, 'Ethĩwa mũndũ o na wĩva etwaa mũka, na kũlika kwake, na kũmũmena,'),
('kam', 'DEU', 22, 14, 'na kũmwilĩĩla maũndũ me nthoni, na kũmũetee syĩtwa ĩthũku, na kwasya, Natwaie mũndũ mũka ũũ, na yĩla namũthengeeie, ndyaona kwake mawonan’yo ma wĩĩtu;'),
('kam', 'DEU', 22, 15, 'nĩvo ĩndĩ ĩthe wa mwĩĩtu, na inyia wake, makose mawonan’yo ma wĩĩtu wake na maetee atumĩa ma ndũa mbingĩlonĩ;'),
('kam', 'DEU', 22, 16, 'na ĩthe wa mwĩĩtu akamatavye atumĩa, Namũnengie mũndũ ũũ mwĩĩtu wakwa ethĩwe mũka wake, nake nũnũũmũmena;'),
('kam', 'DEU', 22, 17, 'na, sisya, nũmwilĩĩle maũndũ me nthoni; akyasya, Ndyaona mwĩĩtunĩ waku mawonan’yo ma wĩĩtu; ĩndĩ aa nĩmo mawonan’yo ma wĩĩtu wa mwĩĩtu wakwa. Na makalan’ye ngũa mbee wa atumĩa ma ndũa.'),
('kam', 'DEU', 22, 18, 'Na atumĩa ma ndũa ĩsu makakwate mũndũ mũũme ũsu na kũmũkũna;'),
('kam', 'DEU', 22, 19, 'na makamumye nthĩnzwa ya sekeli ĩana sya vetha, na kũmũnenga ĩthe wa mwĩĩtu, nĩkwĩthĩwa aeteeete mwĩĩtu wa Isilaeli syĩtwa ĩthũku: nake akeethĩwa mũka wake; ndakaamũeke mĩthenya yake yonthe.'),
('kam', 'DEU', 22, 20, 'Ĩndĩ ethĩwa ũndũ ũsu nĩ wa w’o, atĩ mawonan’yo ma wĩĩtu matyaoneka mwĩĩtunĩ;'),
('kam', 'DEU', 22, 21, 'nĩvo ĩndĩ makaete mwĩĩtu mũomonĩ wa nyũmba ya ĩthe wake, na aũme ma ndũa yake makamũkimange na mavia akw’e, nĩkwĩthĩwa nĩwĩkĩte ũtumanu nthĩnĩ wa Isilaeli, kwĩka ũmalwaya e nyũmbanĩ ya ĩthe wake; ũu nĩw’o wĩvetaa ũthũku kwaku.'),
('kam', 'DEU', 22, 22, 'Ethĩwa mũndũ mũũme akooneka akomete na mũndũ mũka mũtwae, nĩvo ĩndĩ me elĩ moaawe, mũndũ mũũme ũla wakomie na mũka ũsu, na ũ mũndũ mũka: ũu nĩw’o wĩvetaa ũthũku wume nthĩnĩ wa Isilaeli.'),
('kam', 'DEU', 22, 23, 'Ethĩwa ve mwĩĩtu ũla mũtheu na nĩwĩvaĩtwe, na mũndũ mũũme aimwĩthĩa ndũanĩ, na kũkoma nake;'),
('kam', 'DEU', 22, 24, 'nĩvo ĩndĩ maumaalyei me elĩ mbingĩlonĩ ya ndũa ĩsu, na makimangei na mavia makw’e; mwĩĩtu, nũndũ ndaakaya, e ndũanĩ; na ũla mũndũ mũũme, nũndũ nĩwamũthũkisye mũka wa mũtũi wake: ũu nĩw’o wĩveta ũthũku wume kwaku.'),
('kam', 'DEU', 22, 25, 'Ĩndĩ ethĩwa mũndũ mũũme akamwĩthĩa mwĩĩtu wĩvaĩtwe e mũũndanĩ, na mũndũ ũsu aimũkinda; mũndũ ũsu wakindana nakw’e e weka:'),
('kam', 'DEU', 22, 26, 'ĩndĩ ndũkamwĩke mwĩĩtu ũndũ; mwĩĩtu ũsu nde na naĩ ya ũtuma oawa: nũndũ nĩ ta mũndũ ũmũkĩlĩle mũtũi na kũmũaa, nĩw’o ũilyĩ ũndũ ũsu;'),
('kam', 'DEU', 22, 27, 'nĩkwĩthĩwa amwĩthĩie mũũndanĩ, na mwĩĩtu ũsu ũla wĩvaĩtwe akaya, na vatyĩĩ mũndũ wa ũmũtaan’ya.'),
('kam', 'DEU', 22, 28, 'Ethĩwa mũndũ mũũme amwona mwĩĩtu mũtheu, ũte mwĩvasye, na aimũkwata, na kũkoma nake, na makyoneka;'),
('kam', 'DEU', 22, 29, 'nĩvo mũndũ ũla wakomie nake amũnenge ĩthe wa mwĩĩtu sekeli mĩongo ĩtano sya vetha, nake natw’ĩke mũka wake, nĩkwĩthĩwa nĩwamũthũkisye; ndakaamũeke mĩthenya yake yonthe.'),
('kam', 'DEU', 22, 30, 'Mũndũ ndakose mũka wa ĩthe, o na ndakamũvue ĩthe ngũa syake.'),
('kam', 'DEU', 23, 1, 'Ũla wĩ na mee mavevenze, kana kũtilĩka kĩa kyake, ndakaalike ũmbanonĩ wa Yeova.'),
('kam', 'DEU', 23, 2, 'Mũndũ ũsyaĩwe ũlaalainĩ ndakaalike ũmbanonĩ wa Yeova; o na kũvika nzyawa ya ĩkũmi kũikaalike ũmwe wake ũmbanonĩ wa Yeova.'),
('kam', 'DEU', 23, 3, 'Mũamimoni kana Mũmoavi ndakaalike ũmbanonĩ wa Yeova; o na kũvika nzyawa ya ĩkũmi kũikaethĩwe ũmwe wamo ũlika ũmbanonĩ wa Yeova tene na tene:'),
('kam', 'DEU', 23, 4, 'nĩkwĩthĩwa matyaamũthaũsya kĩmũtũ na manzĩ, yĩla mwaumĩte Misili, na nĩkwĩthĩwa matuvie Mbalaamu mwana wa Mbeoli wa ndũa ya Vetholi ya Mesovotamia akũumanĩe.'),
('kam', 'DEU', 23, 5, 'Ĩndĩ Yeova Ngai waku ndaamwĩthukĩĩsya Mbalaamu; ĩndĩ Yeova Ngai waku nĩwakũalyũlĩle kĩumo kĩthĩwe ũathimo, nĩkwĩthĩwa Yeova Ngai waku nĩwakwendie.'),
('kam', 'DEU', 23, 6, 'Ndũkaamamanthĩe mũuo kana ũunĩko mĩthenya yaku yonthe tene na tene.'),
('kam', 'DEU', 23, 7, 'Ndũkaamũthĩthe Mũetomu; nũndũ nĩ mwana‐a‐au: ndũkaamũthĩthe Mũmisili; nũndũ waĩ mwĩkali wa ũeninĩ nthĩ yake.'),
('kam', 'DEU', 23, 8, 'Syana syoo ila ikasyawa nzyawanĩ ya katatũ ikalika ũmbanonĩ wa Yeova.'),
('kam', 'DEU', 23, 9, 'Yĩla wĩuma mwakonĩ waku wa maeema ũendee amaitha maku, ĩsũvĩe kwa kĩla ũndũ ũthũku.'),
('kam', 'DEU', 23, 10, 'Ethĩwa ve mũndũ o na wĩva katĩ wenyu, ũla ũte mũtheu kwondũ wa ũla ũmũkitĩkĩe ũtukũ, nĩvo ĩndĩ wĩuma mwakonĩ wa maeema, ndakalike mwakonĩ wa maeema:'),
('kam', 'DEU', 23, 11, 'ĩndĩ kũkeethĩwa, yĩla syũa yĩthengeea kũthũa, ethamba na manzĩ; na syũa yathũa, elika mwakonĩ wa maeema.'),
('kam', 'DEU', 23, 12, 'Ĩthĩwa na vandũ ũtee wa mwako ma maeema, vala wĩathũkaa:'),
('kam', 'DEU', 23, 13, 'na ũyĩthĩwa na mũo mĩionĩ yaku; na kũkeethĩwa, wekala nthĩ wĩ ũtee wa mwako wa maeema, ĩnza naw’o, na ĩthyũũa na kũvw’ĩka kĩla kyauma nthĩnĩ waku:'),
('kam', 'DEU', 23, 14, 'nũndũ Yeova Ngai waku nũtambũkaa mwakonĩ waku wa maeema, akũvonokye, na kũnengane amaitha maku mbee waku; kwondũ wa ũu mwako waku wa maeema wĩthĩwe mũtheu, nĩ kana ndakone kĩndũ kĩvuku nthĩnĩ waku, na ũkwĩthyũũĩa akũtie.'),
('kam', 'DEU', 23, 15, 'Ndũkamũtũnge kwa vwana wake mũthũkũmi ũla ũvonokete kuma kwa vwana wake na akoka kwaku;'),
('kam', 'DEU', 23, 16, 'nĩekale naku, o katĩ waku, vandũ vala nake wĩnyuva nthĩnĩ wa mbingĩlo ĩmwe yaku, o vala wĩendeew’a nĩvo: ndũkamũthĩn’ye.'),
('kam', 'DEU', 23, 17, 'Kũikethĩwe ĩlwaya eĩtunĩ ma Isilaeli, o na kũikethĩwe mũndũ mũũme ũla wĩĩkaa naĩ na mũndũ mũũme ũngĩ katĩ wa ana ma Isilaeli.'),
('kam', 'DEU', 23, 18, 'Ndũkaete ĩtuvi ya ĩlwaya, kana ĩtuvi ya ngitĩ, nyũmbanĩ ya Yeova Ngai waku kwondũ wa wĩvĩto o na wĩva: nũndũ asu elĩ nĩmathatasya Yeova Ngai waku.'),
('kam', 'DEU', 23, 19, 'Ndũkaamũkovethye mwana‐a‐au eũtũngĩa ũtandĩthyo; ũtandĩthyo wa mbesa, kana wa lĩu, kana wa kĩndũ o na kĩva kĩla kĩkovawa kya ũtandĩthyo.'),
('kam', 'DEU', 23, 20, 'Nũtonya kũmũkovethya mũndũ wa nthĩ ĩngĩ wone ũtandĩthyo; ĩndĩ ndũkamũkovethye mwana‐a‐au wone ũtandĩthyo, nĩ kana Yeova Ngai waku akũathime ũndũnĩ w’onthe ũla wĩkaa na kw’oko kwaku, wĩ nthĩ ĩla wĩlika ũmĩmesye.'),
('kam', 'DEU', 23, 21, 'Yĩla wĩmwĩvĩtĩa Yeova Ngai waku wĩvĩto, ndũkethĩwe na kĩkono kya kũwĩanĩsya: nũndũ Yeova Ngai waku ndetĩa ũkũandũa; na ũkethĩwa nĩ naĩ kwaku.'),
('kam', 'DEU', 23, 22, 'Ĩndĩ ethĩwa ndũkevĩta, kũikethĩwa kwĩ naĩ kwaku.'),
('kam', 'DEU', 23, 23, 'O ũla wumĩte ilomonĩ syaku ũsũvĩe noiwĩka; kwĩanana na ũndũ wamwĩvĩtĩe Yeova Ngai waku, nthembo ya kumya na ngoo ya kwenda, ĩla wetw’ĩĩe na kanyw’a waku.'),
('kam', 'DEU', 23, 24, 'Walika mũũndanĩ wa mĩsavivũ wa mũtũi waku, nũtonya kũya nzavivũ o ũndũ ũkwenda ũvũne; ĩndĩ ndũkekĩe imwe mĩionĩ yaku.'),
('kam', 'DEU', 23, 25, 'Walika mũũndanĩ wa lĩu ũtũĩtye wa mũtũi waku, nũtonya kũtũla iia na kw’oko kwaku; ĩndĩ ndũkaakethe na kavyũ ke ngoto lĩu ũtũĩtye mũũndanĩ wa mũtũi waku.'),
('kam', 'DEU', 24, 1, 'Mũndũ oosa mũndũ mũka, na aimũtwaa, kũkeethĩwa, ethĩwa mũndũ mũka ndeona ũseo methonĩ make, nĩkwĩthĩwa mũũme nĩwonete ũndũ ũtaĩle kwake, akamũandĩkĩe valũa wa kũtaanĩsya, na kũmũnenga kw’okonĩ kwake, na aimũlũngya nyũmbanĩ yake.'),
('kam', 'DEU', 24, 2, 'Na auma nyũmbanĩ yake, nũtonya kũenda na kũtw’ĩka mũka wa mũndũ ũngĩ.'),
('kam', 'DEU', 24, 3, 'Na ethĩwa mũũme wa ĩtina nũnũũmũmena, na kũmũandĩkĩa valũa wa kũtaanĩsya, na kũmũnenga kw’okonĩ kwake, na aimũlũngya nyũmbanĩ yake; kana ethĩwa mũũme wa ĩtina, ũla wamũtwaie ethĩwe mũka wake nĩwakw’a;'),
('kam', 'DEU', 24, 4, 'mũũme wake wa mbee, ũla wamũlũngilye, ndatonya kũmũtwaa ĩngĩ ethĩwe mũka wake, ĩtina wa kũvukwa kwake; nũndũ ũu nĩ ũthatyo mbee wa Yeova: na ndũkavĩtĩthye nthĩ, ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtiĩwa.'),
('kam', 'DEU', 24, 5, 'Mũndũ atwaa mũka, ndakaende na nguthu ya kaũ, o na ndakovwe na wĩa o na wĩva: akekale mũsyĩ wake mwaka ũmwe, na kũmũtanĩthasya mũka wake ũla ũtwaĩte.'),
('kam', 'DEU', 24, 6, 'Mũndũ ndakaose ĩvia ya ũthia kana nthio yayo yĩthĩwe ngwatĩlĩlyo; nũndũ ũu nĩ ta kwosa thayũ wa mũndũ wĩthĩwe ngwatĩlĩlyo.'),
('kam', 'DEU', 24, 7, 'Ethĩwa mũndũ akooneka akyũya mwana‐a‐ĩthe o na wĩva wa ana ma Isilaeli, na aimwĩka ta ngombo, kana kũmũthoosya; mũvaka kĩng’ei kyu kyũawe: ũu nĩw’o wĩvetaa ũthũku ũsu wume katĩ waku.'),
('kam', 'DEU', 24, 8, 'Sisya ĩvinda ya ũthĩn’yo wa mangũ, ũsũvĩe mũno, noyĩka kwĩanana na w’onthe ũla athembi Alivai makamũmanyĩsya: o tondũ nameaĩe, now’o mwĩsũvĩa mwĩke.'),
('kam', 'DEU', 24, 9, 'Lilikana ũndũ Yeova Ngai waku wamwĩkie Miliamu, mwĩ nzĩanĩ mumĩte Misili.'),
('kam', 'DEU', 24, 10, 'Wamũkovethya mũtũi waku kĩndũ o na kĩva, ndũkalike nyũmbanĩ yake wose kĩndũ kĩthĩwe ngwatĩlĩlyo.'),
('kam', 'DEU', 24, 11, 'Ũngama nza, na mũndũ ũla ũmũkovethetye nakũetee kĩndũ kyu kya ngwatĩlĩlyo wĩ nza.'),
('kam', 'DEU', 24, 12, 'Na ethĩwa nĩ mũndũ ngya, ndũkaakome na kĩndũ kyake kya ngwatĩlĩlyo;'),
('kam', 'DEU', 24, 13, 'no mũvaka ũmũtũngĩe kyu kyake kya ngwatĩlĩlyo syũa yathũa, nĩ kana akome evw’ĩkĩte ngũa ĩsu yake, na akũathime: na ũkeethĩwa ũlũngalu kwaku mbee wa Yeova Ngai waku.'),
('kam', 'DEU', 24, 14, 'Ndũkaathĩn’ye mũthũkũmi ũtuvawa ũla ngya na mũthĩni, ethĩwa nĩ ũmwe wa ana‐a‐au, kana wa ekali ma ũeninĩ ala me kwaku nthĩ yaku:'),
('kam', 'DEU', 24, 15, 'mũnenge ĩtuvi yake kĩla mũthenya, o na syũa yĩtikathũe wĩ nayo (nũndũ nĩ ngya, na ngoo yake yĩ na vata mũno nayo); ndakese ũmwĩkaĩla Yeova ũndũ waku, na ũu ũkethĩwa naĩ kwaku.'),
('kam', 'DEU', 24, 16, 'Aaĩthe matikoaawe kwondũ wa syana, o na syana itikoaawe kwondũ wa aaĩthe: kĩla mũndũ nĩoaawe kwondũ wa naĩ yake mwene.'),
('kam', 'DEU', 24, 17, 'Ndũkelelũkasye sila wa katĩ wa mwĩkali wa ũeninĩ, kana wa ũla wakw’ĩĩwe nĩ ĩthe, o na ndũkaose ngũa ya mũndũ mũka ndiwa yĩthĩwe ngwatĩlĩlyo;'),
('kam', 'DEU', 24, 18, 'ĩndĩ lilikana waĩ ngombo Misili, na Yeova Ngai waku nĩwakwovoisye kuma vo: kwondũ wa ũu nĩkwĩaĩa wĩkae ũndũ ũũ.'),
('kam', 'DEU', 24, 19, 'Waketha ngetha yaku mũũndanĩ waku, na woolwa nĩ kyove mũũndanĩ, ndũkakĩsyokee: kĩthĩwe kya mwĩkali wa ũeninĩ, na kya ũla wakw’ĩĩwe nĩ ĩthe, na kya mũndũ mũka ndiwa; nĩ kana Yeova Ngai waku akũathime wĩanĩ w’onthe wa moko maku.'),
('kam', 'DEU', 24, 20, 'Wakũnanga mũthata waku, ndũkasyoke kũkũnanga ĩngĩ mbonge syaw’o: wĩthĩwe wa mwĩkali wa ũeninĩ, na wa ũla wakw’ĩĩwe nĩ ĩthe, na wa mũndũ mũka ndiwa.'),
('kam', 'DEU', 24, 21, 'Waketha nzavivũ sya mũũnda waku wa mĩsavivũ, ndũkethĩan’ye ũtialyo: syĩthĩwe sya mwĩkali wa ũeninĩ, na sya ũla wakw’ĩĩwe nĩ ĩthe, na sya mũndũ mũka ndiwa.'),
('kam', 'DEU', 24, 22, 'Lilikana waĩ ngombo nthĩ ya Misili: kwondũ wa ũu nĩkwĩaĩa wĩkae ũndũ ũũ.'),
('kam', 'DEU', 25, 1, 'Ethĩwa ve ngananĩo katĩ wa andũ, na maenda silanĩ, na asili mamasilan’ya; nĩvo mamũtw’e mũlũngalu ũla mũlũngalu, na kũmũtw’a mũvĩtan’ya ũla mũthũku.'),
('kam', 'DEU', 25, 2, 'Na kũkeethĩwa, ethĩwa mũndũ ũsu mũthũku nĩwaĩlwe nĩ kũkũnwa, mũsili amũkomye nthĩ, na kũmũkũnĩthya mbee wa ũthyũ wake, kwĩanana na ũthũku wake, makũna makĩtalwa.'),
('kam', 'DEU', 25, 3, 'Nũtonya kũmũkũna makũna mĩongo ĩna, na ndakavĩtũkye; mwana‐a‐au ndakese kwoneka kwaku e kĩvooi, ethĩwa akavĩtũkya, na kũmũkũna makũna maingĩ kwĩ asu.'),
('kam', 'DEU', 25, 4, 'Ndũkamyove ng’ombe kanyw’a, ĩkĩvũa lĩu wa mbaa ngetha.'),
('kam', 'DEU', 25, 5, 'Ethĩwa mũndũ na mwana‐a‐inyia mekalaa vamwe, na ũmwe aikw’a, na nde na mwana wa kavĩsĩ, kĩveti kya ũla wakwie kĩikatwawe nĩ mũeni: mwana‐a‐inyia wa mũũme akalike kwake, na kũmũtw’ĩkĩthya mũka wake, na kũmwĩka ũndũ waĩlĩte mwana‐a‐inyia wa mũũme.'),
('kam', 'DEU', 25, 6, 'Na kũkeethĩwa, kana mwana wa mbee ũla ũkasyaa akaũngame vandũ va syĩtwa ya mwana‐a‐inyia ũla wakwie, syĩtwa yake yĩtikanangwe nthĩnĩ wa Isilaeli.'),
('kam', 'DEU', 25, 7, 'Na ethĩwa ũ mũndũ ndekwenda kwosa mũka wa mwana‐a‐inyia, nĩvo mũka wa mwana‐a‐inyia akaende mbingĩlonĩ kwa atumĩa, na kũmea, Mwana‐a‐inyia wa mũemewa nũnũũlea kũmũũngamĩsya mwana‐a‐inyia syĩtwa nthĩnĩ wa Isilaeli; nũkũlea kũmbĩka ũndũ waĩlĩte mwana‐a‐inyia wa mũũme.'),
('kam', 'DEU', 25, 8, 'Nĩvo atumĩa ma ndũa yake makamwĩte, na kũneena nake: na ethĩwa akaũngama, na kwasya, Ndikwenda ũmwosa;'),
('kam', 'DEU', 25, 9, 'nĩvo mũka wa mwana‐a‐inyia wĩũka vala ũĩ atumĩa mamwene, na aimũthasya kĩatũ kyake kũkyumya kũũnĩ kwake, na aimũtw’ĩla mata ũthyũ; na akasũngĩa na kwasya, Ũu nĩw’o kwĩkawa mũndũ ũla ũtakaa nyũmba ya mwana‐a‐inyia.'),
('kam', 'DEU', 25, 10, 'Na syĩtwa yake yĩkeetawa kwa Isilaeli, Nyũmba ya mumw’a kĩatũ.'),
('kam', 'DEU', 25, 11, 'Yĩla aũme meũkita, na kĩveti kya ũmwe kĩkathengeea kũmũtaan’ya mũũme kw’okonĩ kwa ũla ũnũũmũkũna, na kũtambũũkya kw’oko kwakyo, na ũkwata ũũme wake;'),
('kam', 'DEU', 25, 12, 'kĩtile kw’oko kwakyo, itho yaku yĩtikew’ĩe tei.'),
('kam', 'DEU', 25, 13, 'Ngusunĩ yaku ndũkethĩwe na mavia mavathũkene ma ũthima namo, manene na manini.'),
('kam', 'DEU', 25, 14, 'Nyũmbanĩ yaku ndũkethĩwe na ithimi ivathũkene, nene na nini.'),
('kam', 'DEU', 25, 15, 'Ĩthĩwa na ĩvia yĩanĩe na ya w’o; ĩthĩwa na kĩthimi kĩanĩe na kya w’o: nĩ kana mĩthenya yaku yĩthĩwe mingĩ wĩ nthĩ ĩla Yeova Ngai waku ũkũnengae.'),
('kam', 'DEU', 25, 16, 'Nũndũ onthe ala mekaa maũndũ ta asu, onthe ala mekaa ũla ũte ũlũngalu, nĩ ũthatyo kwa Yeova Ngai waku.'),
('kam', 'DEU', 25, 17, 'Lilikana ũndũ Amaleki wakwĩkĩe nzĩanĩ wumĩte Misili;'),
('kam', 'DEU', 25, 18, 'ũndũ wakomanie naku nzĩanĩ, na amakũna ala maĩ ĩtina, onthe ala mataĩ na vinya ĩtina waku, yĩla waĩ mũnyalu na waĩ na mĩnoo; na ndaamũkĩa Ngai.'),
('kam', 'DEU', 25, 19, 'Kwondũ wa ũu kũkeethĩwa, yĩla Yeova Ngai waku wĩkũthũmũsya kuma amaithanĩ maku onthe ala me ndee, wĩ nthĩ ĩla Yeova Ngai waku ũkũnengae ũmĩmesye yĩthĩwe ũtiĩwa, no mũvaka wanange ũlilikan’yo wa Amaleki ĩtheo wa ĩtu; ndũkolwe.'),
('kam', 'DEU', 26, 1, 'Na kũkeethĩwa, walika nthĩ ĩla Yeova Ngai waku ũkũnengae yĩthĩwe ũtiĩwa, na wamĩmesya na kũmĩtũa,'),
('kam', 'DEU', 26, 2, 'wĩosa ũsyao wa mbee wa nthĩ, ũla wĩketha nthĩ ĩla Yeova Ngai waku ũkũnengae; wĩkĩe kĩkavũnĩ, na ũienda vala Yeova Ngai waku wĩnyuva, ekalye syĩtwa yake vo.'),
('kam', 'DEU', 26, 3, 'Na wĩthi kwa mũthembi ũla ũkethĩwa mĩthenya ĩsu, noimwĩa, Nĩngũneena ũmũnthĩ mbee wa Yeova Ngai waku, atĩ nĩnĩvikĩte nthĩ ĩla Yeova wamevĩtĩe aaĩthe maitũ kũtũnenga.'),
('kam', 'DEU', 26, 4, 'Na mũthembi nĩose kĩkavũ kw’okonĩ kwaku, na kwia mbee wa kĩthembeo kya Yeova Ngai waku.'),
('kam', 'DEU', 26, 5, 'Naku wĩsũngĩa na ũkyasya mbee wa Yeova Ngai waku, Nau aĩ Mũsilia aianganga; na atheea Misili, na ekala ũeni kw’o, andũ anini ũtalonĩ; na e ku atw’ĩka mbaĩ, nene, na yĩ ũtonyi, na yĩ andũ aingĩ.'),
('kam', 'DEU', 26, 6, 'Na Amisili matwĩka naĩ, na matũthĩn’ya, na matũthũkũmĩthya na ũkombo wĩ vinya:'),
('kam', 'DEU', 26, 7, 'na twamwĩkaĩla Yeova, Ngai wa aaĩthe maitũ, na Yeova eethukĩĩsya wasya witũ, na oona thĩna witũ, na wĩa witũ wĩ vinya, na ũnyamao witũ;'),
('kam', 'DEU', 26, 8, 'na Yeova atumya Misili na kw’oko kwĩ vinya, na kw’oko kũtambũũku, na ũtĩsyo mũnene, na syama, na moseng’yo;'),
('kam', 'DEU', 26, 9, 'na nũtũetete vaa, na nũtũnengete nthĩ ĩno, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'DEU', 26, 10, 'Na yu, sisya, nĩnaete ũsyao wa mbee wa nthĩ, ũla we, Yeova, ũnengete. Naku ia mbee wa Yeova Ngai waku, na mũthaithe Yeova Ngai waku:'),
('kam', 'DEU', 26, 11, 'na ũitana kwondũ wa ũseo w’onthe ũla Yeova Ngai waku ũkũnengete we, na nyũmba yaku, we, na Mũlivai, na mwĩkali wa ũeninĩ ũla wĩ kwenyu.'),
('kam', 'DEU', 26, 12, 'Wamina kumya kĩlungu kyonthe kya kĩlungu kya ĩkũmi kya wingĩvo wa syĩndũ syaku mwaka wa katatũ, naw’o nĩ mwaka wa kumya kĩlungu kya ĩkũmi, nĩvo ĩndĩ inenge Mũlivai, na mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, nĩ kana maye mavũnĩe mbingĩlonĩ syaku.'),
('kam', 'DEU', 26, 13, 'Naku neena mbee wa Yeova Ngai waku, Syĩndũ ila ivathĩtwe syĩthĩwe ntheu nĩnĩvetete kuma nyũmbanĩ yakwa, o na nĩnĩmũnengete Mũlivai, na mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa, o kwĩanana na mwĩao waku w’onthe ũla wambĩaĩe: ndyaavĩtya ũmwe wa mĩao yaku, o na ndyaolwa nĩyo:'),
('kam', 'DEU', 26, 14, 'ndyaaya kĩmwe kya isu ntheu kĩmetonĩ kyakwa, o na ndyaaia kĩmwe kyasyo yĩla naĩ mũvuku, o na ndyaanengane kĩmwe kya isu kwondũ wa ala akw’ũ: nĩneethukĩĩsye wasya wa Yeova Ngai wakwa; nĩneekie kwĩanana na w’onthe ũla wambĩaĩe.'),
('kam', 'DEU', 26, 15, 'Sisya kuma ũtũonĩ waku mũtheu, kuma ĩtunĩ, na ũiathima andũ maku Isilaeli, na nthĩ ĩla ũtũnengete, o ũndũ wamevĩtĩe aaĩthe maitũ, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'DEU', 26, 16, 'Ũmũnthĩ Yeova Ngai waku nũnũũkwĩaĩa ũkwate myamũlo ĩno na motw’ĩo: kwondũ wa ũu makwate na kũmeka na ngoo yaku yonthe, na thayũ waku w’onthe.'),
('kam', 'DEU', 26, 17, 'Nũmũtavanĩtye Yeova ũmũnthĩ atĩ nĩwe Ngai waku, na kana ũkaendaa nzĩanĩ syake, na kũkwataa myamũlo yake, na mĩao yake, na motw’ĩo make, na kwĩthukĩĩasya wasya wake:'),
('kam', 'DEU', 26, 18, 'nake Yeova nũkũtavanĩtye ũmũnthĩ atĩ wĩ ũko wake mwene wa andũ, o tondũ wakwathie, na kana nĩwaĩle kũkwataa mĩao yake yonthe;'),
('kam', 'DEU', 26, 19, 'nake akakũnenevya kwĩ mbaĩ syonthe ila wombie, nĩ kana wĩthĩwe ndaĩa, na syĩtwa, na ngatho; nĩ kana wĩthĩwe ũko mũtheu wa andũ kwa Yeova Ngai waku, o tondũ waisye.'),
('kam', 'DEU', 27, 1, 'Na Mose na atumĩa ma Isilaeli mameaĩa andũ, makyasya, Kwatai mwĩao w’onthe ũla ngũkwĩaĩa ũmũnthĩ.'),
('kam', 'DEU', 27, 2, 'Na kũkeethĩwa mũthenya ũla mwĩinga Yolotani na kũvika nthĩ ĩla Yeova Ngai waku ũkũnengae, wĩĩũngamĩsya mavia manene, na kũmavakaa ĩa:'),
('kam', 'DEU', 27, 3, 'na kũandĩka ĩũlũ wamo ndeto syonthe sya mĩao ĩno, wamina kũinga; ni kana ũlike nthĩ ĩla Yeova Ngai waku ũkũnengae, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, o tondũ Yeova, Ngai wa aaĩthe maku, wakwathie.'),
('kam', 'DEU', 27, 4, 'Na kũkeethĩwa, mwamina kũinga Yolotani, mwĩũngamya mavia aa, ala ngũkwĩaĩa ũmũnthĩ, kĩĩmanĩ kya Evali, na kũmavaka ĩa.'),
('kam', 'DEU', 27, 5, 'Na kũu mwakĩe Yeova Ngai waku kĩthembeo, kĩthembeo kya mavia: ndũkatethye wĩa ĩũlũ wamo na mũio wa kĩaa.'),
('kam', 'DEU', 27, 6, 'Aka kĩthembeo kya Yeova Ngai waku kya mavia mate masũvye; na mũthembee Yeova Ngai waku nthembo sya kũvĩvw’a ĩũlũ wakyo:'),
('kam', 'DEU', 27, 7, 'na themba nthembo sya mũuo, na ũiya wĩ ku; na ũitana mbee wa Yeova Ngai waku.'),
('kam', 'DEU', 27, 8, 'Na andĩka mavianĩ asu ndeto syonthe sya mĩao ĩno syoneke nesa vyũ.'),
('kam', 'DEU', 27, 9, 'Na Mose na athembi Alivai maneena na Isilaeli onthe, makyasya, Vindya ki, na ĩthukĩĩsye, we Isilaeli: Ũmũnthĩ nũtw’ĩkĩte ũko wa Yeova Ngai waku.'),
('kam', 'DEU', 27, 10, 'Kwondũ wa ũu ĩw’a wasya wa Yeova Ngai waku, na kwata mĩao yake na myamũlo yake, ĩla ngũkwĩaĩa ũmũnthĩ.'),
('kam', 'DEU', 27, 11, 'Na Mose eeaĩa andũ mũthenya o ũsu, akyasya,'),
('kam', 'DEU', 27, 12, 'Aa meũngama kĩĩmanĩ kya Ngelisimu kũathima andũ mwainga Yolotani: Simeoni, na Livai, na Yuta, na Isakali, na Yosevu, na Mbenyamini.'),
('kam', 'DEU', 27, 13, 'Na aa meũngama kĩĩmanĩ kya Evali kwondũ wa kũumanĩa: Leuveni, na Ngati, na Aseli, na Nzevuluni, na Ndani, na Navitali.'),
('kam', 'DEU', 27, 14, 'Na Alivai masũngĩe, na matavye andũ onthe ma Isilaeli na wasya mũnene,'),
('kam', 'DEU', 27, 15, 'Naumanĩwe mũndũ ũla ũseũvasya mũvw’anano wa kwasũvya kana mũvw’anano wa syĩndũ ila ũtwekethetye, naw’o nĩ ũthatyo kwa Yeova, wĩa wa moko ma ndũĩka, na kũũngamya na kĩmbithĩ. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 16, 'Naumanĩwe ũla ũvũthasya ĩthe kana nyinyia. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 17, 'Naumanĩwe ũla ũkũĩĩasya kyambo kya mũvaka kya mũtũi wake. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 18, 'Naumanĩwe ũla ũtumaa ililinda ivĩtya nzĩa. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 19, 'Naumanĩwe ũla welelũkasya sila wa katĩ kwondũ wa mwĩkali wa ũeninĩ, na ũla wakw’ĩĩwe nĩ ĩthe, na mũndũ mũka ndiwa. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 20, 'Naumanĩwe ũla ũkomaa na kĩveti kya ĩthe, nũndũ nĩũkĩlĩtye ngũa ya ĩthe wake. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 21, 'Naumanĩwe ũla ũkomaa na mũthemba o na wĩva wa nyamũ. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 22, 'Naumanĩwe ũla ũkomaa na mwĩĩtu wa ĩthe, kana mwĩĩtu wa inyia. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 23, 'Naumanĩwe ũla ũkomaa na mũthoni. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 24, 'Naumanĩwe ũla ũkũnaa mũtũi wake na kĩmbithĩ. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 25, 'Naumanĩwe ũla wosaa ĩvaki oae mũndũ ũte mũvĩtan’ya. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 27, 26, 'Naumanĩwe ũla ũtalũmasya ndeto sya mĩao ĩno, asyĩke. Na andũ onthe meĩtĩkĩĩsya, Ameni.'),
('kam', 'DEU', 28, 1, 'Na kũkeethĩwa, ethĩwa, ũkethukĩĩasya ki wasya wa Yeova Ngai waku, kũkwataa na kwĩkaa mĩao yake yonthe ĩla ngũkwĩaĩa ũmũnthĩ, nĩvo ĩndĩ Yeova Ngai waku ũkakũnenevya kwĩ mbaĩ syonthe sya nthĩ:'),
('kam', 'DEU', 28, 2, 'na moathimo aa onthe makooka kwaku, na ũkũkwata, ethĩwa ũkethukĩĩasya wasya wa Yeova Ngai waku.'),
('kam', 'DEU', 28, 3, 'Ũkeethĩwa wĩ mũathime ndũanĩ, na ũkeethĩwa wĩ mũathime mũũndanĩ.'),
('kam', 'DEU', 28, 4, 'Ũsyao wa mwĩĩ waku ũkeethĩwa mũathime, na ũsyao wa nthĩ yaku, na ũsyao wa nyamũ syaku, na wingĩvo wa indo syaku, na tũtena twa ndĩthya yaku ya mbũi na malondu.'),
('kam', 'DEU', 28, 5, 'Kĩkeethĩwa kĩ kĩathime kyondo kyaku na kĩndũ kyaku kĩla kĩluĩlawa mũtu.'),
('kam', 'DEU', 28, 6, 'Ũkeethĩwa wĩ mũathime yĩla wĩlikaa na ũkeethĩwa wĩ mũathime yĩla wĩumaalaa.'),
('kam', 'DEU', 28, 7, 'Yeova akamakũnĩthya mbee waku amaitha maku ala mekũkĩlĩla: makakumaalĩla na nzĩa ĩmwe, na makakĩĩla mbee waku na nzĩa mũonza.'),
('kam', 'DEU', 28, 8, 'Yeova akeaĩa ũathimo ĩũlũ waku makũmbĩnĩ maku, na ũndũnĩ w’onthe ũla wĩkaa na kw’oko kwaku; nake akakũathima wĩ nthĩ ĩla Yeova Ngai waku ũkũnengae.'),
('kam', 'DEU', 28, 9, 'Yeova akakũlũlũmĩlya withĩwe ũko mũtheu kwake, o tondũ wakwĩavĩe; ethĩwa ũkakwataa mĩao ya Yeova Ngai waku, na kũendaa nzĩanĩ syake.'),
('kam', 'DEU', 28, 10, 'Na ngo syonthe sya nthĩ ikoona atĩ nĩwĩtanĩaw’a na syĩtwa ya Yeova; na ikakũkĩa.'),
('kam', 'DEU', 28, 11, 'Na Yeova akakwingĩvĩsya ũseo, ũsyaonĩ wa mwĩĩ waku, na ũsyaonĩ wa indo syaku, na ũsyaonĩ wa nthĩ yaku, wĩ nthĩ ĩla Yeova wamevĩtĩe aaĩthe maku ũkũnengae.'),
('kam', 'DEU', 28, 12, 'Yeova akakũvingũĩa kyũmbanĩsyo kyake kĩseo, nakyo nĩ matu, akuĩsye mbua ya nthĩ yaku ĩvinda yayo, na kũathima wĩa w’onthe wa moko maku: na ũkakovethya mbaĩ nyingĩ, na ndũkakova.'),
('kam', 'DEU', 28, 13, 'Na Yeova akakũtw’ĩkĩthya mũtwe, na ti kĩsithe; na ũkeethĩwa wĩ ĩũlũ ki, na ndũkethĩwa wĩ ĩtheo; ethĩwa ũkethukĩĩasya mĩao ya Yeova Ngai waku, ĩla ngũkwĩaĩa ũmũnthĩ, kũmĩkwataa na kũmĩka,'),
('kam', 'DEU', 28, 14, 'na ethĩwa ndũkathũka kuma ndetonĩ syonthe ila ngũkwĩaĩa ũmũnthĩ, kũthi ngalĩ ya kw’oko kwa aũme, kana kwa aka, kũatĩĩa ngai ingĩ na kwithũkũma.'),
('kam', 'DEU', 28, 15, 'Ĩndĩ kũkeethĩwa, ethĩwa ndwĩĩthukĩĩsya wasya wa Yeova Ngai waku, ũkwate na kwĩka mĩao yake yonthe na myamũlo yake yonthe ĩla ngũkwĩaĩa ũmũnthĩ, kana iumo ii syonthe ikakũkĩa, na ũkũkwata.'),
('kam', 'DEU', 28, 16, 'Ũkeethĩwa wĩ mũumanĩe ndũanĩ, na ũkeethĩwa wĩ mũumanĩe mũũndanĩ.'),
('kam', 'DEU', 28, 17, 'Kĩkeethĩwa kĩumanĩwe kĩkavũ kyaku, na kĩndũ kyaku kĩla kĩluĩlawa mũtu.'),
('kam', 'DEU', 28, 18, 'Ũkeethĩwa ũumanĩwe ũsyao wa mwĩĩ waku, na ũsyao wa nthĩ yaku, na wingĩvo wa indo syaku, na tũtena twa ndĩthya yaku ya mbũi na malondu.'),
('kam', 'DEU', 28, 19, 'Ũkeethĩwa wĩ mũumanĩe yĩla wĩlikaa, na ũkeethĩwa wĩ mũumanĩe yĩle wĩumaalaa.'),
('kam', 'DEU', 28, 20, 'Yeova akakũetee kĩumo, na mathĩna, na ũkan’yo, ũndũnĩ w’onthe ũla wĩtethasya na moko maku, kũvika yĩla wĩanangwa, na kwaa mĩtũkĩ; nũndũ wa ũthũku wa meko maku, ala ũndiĩte kwondũ wamo.'),
('kam', 'DEU', 28, 21, 'Yeova akakũkwatĩthya mũimũ, kũvika akũmina wume nthĩ, ĩla wĩlika ũmĩmesye.'),
('kam', 'DEU', 28, 22, 'Yeova akakũkũna na ũwau wa ũkooa, na ndetema, na ĩtũatũ yai, na ũvyũvu ta wa mwaki, na ũvyũ, na wũmanĩlu, na mbuka; na makakũatĩĩa kũvika yĩla wĩanangwa.'),
('kam', 'DEU', 28, 23, 'Na ĩtu yaku yĩla yĩ ĩũlũ wa mũtwe waku yĩkeethĩwa ta ũthuku, na nthĩ ĩla yĩ ĩtheo waku ĩkeethĩwa ta kĩaa.'),
('kam', 'DEU', 28, 24, 'Yeova akatw’ĩkĩthya mbua ya nthĩ yaku ta mũtu na kĩtoo: ĩkakũtheeea kuma ĩtunĩ, kũvika yĩla wĩanangwa.'),
('kam', 'DEU', 28, 25, 'Yeova akaũkũnĩthya mbee wa amaitha maku; ũkamaumaalĩla na nzĩa ĩmwe, na ũkakĩĩla mbee woo na nzĩa mũonza: na ũkanyaĩĩkw’a kũũ na kũũ mosumbĩnĩ onthe ma nthĩ.'),
('kam', 'DEU', 28, 26, 'Na kimba kyaku kĩkeethĩwa lĩu wa nyũnyi syonthe sya yayaya, na wa nyamũ sya nthĩ; na kũikethĩwa mũndũ wa kwilũngya.'),
('kam', 'DEU', 28, 27, 'Yeova akaũkũna na ũla mũimũ wa Misili, o na mĩimũ ĩngĩ, na mũvolekango, na ũng’ũũ, ala ũtatonya kũvow’a.'),
('kam', 'DEU', 28, 28, 'Yeova akaũkũna na ndũũka, na ũlilinda, na kũsaanĩw’a kwa ngoo;'),
('kam', 'DEU', 28, 29, 'na ũkavavata mũthenya katĩ, o tondũ kĩlilinda kĩvavataa kĩvindunĩ, na ndũkaathimĩka nzĩanĩ syaku: na mavinda onthe ũkanyamaaw’a na kũvutwa, na vatikethĩwa mũndũ wa ũkũtangĩĩa.'),
('kam', 'DEU', 28, 30, 'Ũkeevasya mwĩĩtu, na mũndũ ũngĩ akakoma nake: ũkaaka nyũmba, na ndũkekala nthĩnĩ wayo: ũkavanda mũũnda wa mĩsavivũ, na ndũkaya ũsyao waw’o.'),
('kam', 'DEU', 28, 31, 'Ng’ombe yaku ĩkooawa wene na metho maku, na ndũkaya nyama syayo: ũkavenwa ĩng’oi yaku na vinya, mbee wa ũthyũ waku, na ndũkayĩtũngĩwa: malondu maku makanengwa amaitha maku, na ndũkethĩwa na mũndũ wa ũkũtangĩĩa.'),
('kam', 'DEU', 28, 32, 'Ana maku na eĩtu maku makanenganwe mbaĩnĩ ĩngĩ; na metho maku makasyaĩĩsya, na makaya mbindu kwondũ wa mea moo mũthenya w’onthe: na kw’oko kwaku kũikethĩwa kũtonya ũndũ na vinya wakw’o.'),
('kam', 'DEU', 28, 33, 'Ũsyao wa nthĩ yaku, na mawĩa maku onthe, makaĩwa nĩ mbaĩ ĩla ũtesi; na ũkathĩnw’a ki na kũkanyangwa ĩndĩ yonthe;'),
('kam', 'DEU', 28, 34, 'ũndũ ũkaũũka nũndũ wa maũndũ ala metho maku makona.'),
('kam', 'DEU', 28, 35, 'Yeova akaũkũna mau na maũũ, na mũimũ mũthũku, ũtavoeka, kuma ũnyaĩĩ waku kũvika lolotya.'),
('kam', 'DEU', 28, 36, 'Yeova akaũtwaa we, na mũsumbĩ waku ũla wĩsumbĩkĩsye, kwa mbaĩ ĩla ũtaamanya, we kana aaĩthe maku; na kũu ũkaithũkũma ngai ingĩ, o mĩtĩ na mavia.'),
('kam', 'DEU', 28, 37, 'Na ũkatw’ĩka ũseng’yo, na nthimo, na kũvũthĩĩw’a, ngonĩ syonthe sya andũ vala Yeova ũkakũtwaa.'),
('kam', 'DEU', 28, 38, 'Ũkaumya mbeũ nyingĩ kũvanda mũũndanĩ, na ũkaketha nini, nũndũ ikalĩka nĩ ngie.'),
('kam', 'DEU', 28, 39, 'Ũkavanda mĩũnda ya mĩsavivũ, na kũmĩsea, ĩndĩ ndũkanyw’a mbinyu yayo, kana kũketha nzavivũ, nũndũ ikalĩka nĩ iinyũ.'),
('kam', 'DEU', 28, 40, 'Ũkeethĩwa na mĩthata mĩvakanĩ yaku yonthe, ĩndĩ ndũkevaka mauta mayo; nũndũ mũthata waku ũketĩkya ũsyao waw’o.'),
('kam', 'DEU', 28, 41, 'Ũkasyaa ana na eĩtu, ĩndĩ matikethĩwa maku; nũndũ makaenda me atave.'),
('kam', 'DEU', 28, 42, 'Mĩtĩ yaku yonthe na ũsyao wa nthĩ yaku ũkeethĩwa wa ngie.'),
('kam', 'DEU', 28, 43, 'Mwĩkali wa ũeninĩ ũla wĩ kwaku akanenevw’a kwĩ we mbee na mbee; naku ũkatheea kũtheea.'),
('kam', 'DEU', 28, 44, 'Akakũkovethya, naku ndũkamũkovethya: nake akeethĩwa mũtwe, naku ũkeethĩwa kĩsithe.'),
('kam', 'DEU', 28, 45, 'Na iumo ii syonthe ikakũkĩa, na ikakũatĩĩa, na ũkũkwata, kũvika yĩla wĩanangwa; nũndũ ndwaaĩthukĩĩsya wasya wa Yeova Ngai waku, kũkwata mĩao yake na myamũlo yake ĩla wakwĩaĩe:'),
('kam', 'DEU', 28, 46, 'na ikeethĩwa wonan’yo na ũseng’yo kwaku, na kwa ũsyao waku tene na tene.'),
('kam', 'DEU', 28, 47, 'Nĩkwĩthĩwa ndwaathũkũma Yeova Ngai waku na mũyo, na ũtanu wa ngoo, kwondũ wa wingĩ wa syĩndũ syonthe;'),
('kam', 'DEU', 28, 48, 'kwondũ wa ũu ũkathũkũma amaitha maku ala Yeova ũkakũetee, wĩ na nzaa, na waũni, na wĩ mũthei, na wĩ na vata wa syĩndũ syonthe: na akeekĩa ĩsoki ya kĩaa ngingonĩ yaku, kũvika akwananga.'),
('kam', 'DEU', 28, 49, 'Yeova akakũetee mbaĩ kuma kũasa, kuma ngalĩ ĩmwe ya nthĩ, ĩũlũkaa ta ndiũ; mbaĩ ĩla ũtakamanya kĩthyomo kyayo;'),
('kam', 'DEU', 28, 50, 'mbaĩ yĩ na ũthyũ mwaĩ, ĩla ĩtona mũndũ mũkũũ ta kĩndũ, kana kwon’ya ala anini ũseo,'),
('kam', 'DEU', 28, 51, 'na ĩkaya ũsyao wa indo syaku, na ũsyao wa nthĩ yaku, kũvika yĩla wĩanangwa; o na ĩtikakũtialĩlya lĩu wa mbaa ngetha, kana mbinyu mbĩthĩ, kana mauta, kana wingĩvo wa ng’ombe syaku, kana tũtena twa ndĩthya yaku ya mbũi na malondu, kũvika yĩla yĩkwananga vyũ.'),
('kam', 'DEU', 28, 52, 'Na makakũtw’ĩkanĩsya mbingĩlonĩ syaku syonthe, kũvika maũvai maku matũlu na maiie mavalũka, ala wĩkwatĩtye, nthĩ yaku yonthe; na makakũtw’ĩkanĩsya mbingĩlonĩ syaku syonthe nthĩ yaku yonthe, ĩla Yeova Ngai waku ũkũnengete.'),
('kam', 'DEU', 28, 53, 'Kũtw’ĩkanĩw’anĩ na ũnyamaonĩ ũla amaitha maku makakũnyamasya naw’o, ũkaya ũsyao wa mwĩĩ waku mwene, nyama sya ana maku na eĩtu maku, ala Yeova Ngai waku ũkũnengete.'),
('kam', 'DEU', 28, 54, 'Mũndũ mũũme katĩ wenyu ũla mwololo na mwanake mũno, itho yake yĩkeethĩwa yĩ ĩthũku kwa mwana‐a‐ĩthe, na kwa kĩveti kya kĩthũinĩ kyake, na kwa ũtialo wa syana syake ila watialĩlw’e;'),
('kam', 'DEU', 28, 55, 'ũndũ ũtakamaaĩa o na ũmwe woo nyama sya syana syake ila ũkaya, nũndũ ndaatialĩlwa nĩ kĩndũ, kũtw’ĩkanĩw’anĩ na ũnyamaonĩ ũla mũmaitha waku ũkakũnyamasya naw’o mbingĩlonĩ syaku syonthe.'),
('kam', 'DEU', 28, 56, 'Mũndũ mũka mwololo na mwanake mũno katĩ wenyu, ũla ũtaatata kũkinya nthĩ na ũnyaĩĩ wake nũndũ wa wanake na wololou, itho yake yĩkeethĩwa yĩ ĩthũku kwa mũũme wa kĩthũinĩ kyake, na kwa mwana wake, na kwa mwĩĩtu wake,'),
('kam', 'DEU', 28, 57, 'na kwa kaũkenge kake kala keuma katĩ wa maũũ make, na kwa syana syake ila ũkasyaa; nũndũ akaiya na kĩmbithĩ kwondũ wa vata wa syĩndũ syonthe, kũtw’ĩkanĩw’anĩ na ũnyamaonĩ ũla mũmaitha waku ũkakũnyamasya naw’o mbingĩlonĩ syaku.'),
('kam', 'DEU', 28, 58, 'Ethĩwa ndũkakwata na kwĩka ndeto syonthe sya mĩao ĩno ila iandĩkĩtwe ĩvukunĩ yĩĩ, nĩ kana ũyĩkĩe syĩtwa yĩĩ ĩnene na ya ũtĩsya, YEOVA NGAI WAKU;'),
('kam', 'DEU', 28, 59, 'nĩvo ĩndĩ Yeova wĩtw’ĩkĩthya mothĩn’yo maku na mothĩn’yo ma ũsyao waku methĩwe ma ũseng’yo, o mothĩn’yo manene, na ala mekalaa, na mowau mathũku, na ala mekalaa.'),
('kam', 'DEU', 28, 60, 'Nake akakũtũngĩa mowau onthe ma Misili, ala wamakĩaa; na makalũman’ya naku.'),
('kam', 'DEU', 28, 61, 'O na kĩla ũwau, na kĩla ũthĩn’yo, ũla ũtaandĩkĩtwe ĩvukunĩ ya mĩao ĩno, nĩmo Yeova ũkakũetee, kũvika yĩla ũkanangwa.'),
('kam', 'DEU', 28, 62, 'Na mũkatiala mwĩ andũ anini ũtalonĩ, o na kau mweanaa ta ndata sya ĩtunĩ ũndũ wa kwingĩva; nĩkwĩthĩwa ndwaaĩthukĩĩsya wasya wa Yeova Ngai waku.'),
('kam', 'DEU', 28, 63, 'Na kũkeethĩwa, kana, o tondũ Yeova wamũtanĩaa aimwĩka nesa, na kũmwingĩvya, o ta ũu Yeova akamũtanĩa akĩmwasya, na akĩmwananga; na mũkaumw’a nthĩ ĩla mwĩlika mũmĩmesye.'),
('kam', 'DEU', 28, 64, 'Na Yeova akakũnyaĩĩkya ngonĩ syonthe sya andũ, kuma ngalĩ ĩmwe ya nthĩ kũvika ngalĩ ĩla ĩngĩ ya nthĩ; na kũu ũkathũkũma ngai ingĩ, ila ũtaamanya, we kana aaĩthe maku, o ila sya mĩtĩ na mavia.'),
('kam', 'DEU', 28, 65, 'Na mbaĩnĩ isu ndũkona ũthũmũo, na kũikethĩwa vandũ va kũthũmũsya ũnyaĩĩ waku: ĩndĩ kũu Yeova akakũnenga ngoo ya kũtetema, na metho me mbindu, na kũsonzoma kwa thayũ;'),
('kam', 'DEU', 28, 66, 'na thayũ waku ũkekala ta ũniinĩtwe nĩ nzika mbee waku; na ũkakĩaa ũtukũ na mũthenya, na ndũkethĩwa na wĩkwatyo kwondũ wa thayũ waku.'),
('kam', 'DEU', 28, 67, 'Kĩoko ũkaasya, Kethĩwa yu nĩ wĩoo! Na wĩoo ũkaasya, Kethĩwa yu nĩ kĩoko! Nũndũ wa kũkĩa kwa ngoo yaku kũla ũkakĩa, na nũndũ wa maũndũ ala metho maku makona.'),
('kam', 'DEU', 28, 68, 'Na Yeova akakũtũnga Misili na ngalawa, na nzĩa ĩla nakwĩie, Ndũkaamyona ĩngĩ nongi: na kũu mũkeethoosya kwa amaitha menyu mwĩthĩwe ngombo aũme na aka, na mũikona mũndũ wa ũmũthooa.'),
('kam', 'DEU', 29, 1, 'Ii nĩsyo ndeto sya ũtianĩo ũla Yeova wamwĩaĩe Mose atianĩe na ana ma Isilaeli nthĩ ya Moavi, vamwe na ũtianĩo ũla watianĩe nao Olevu.'),
('kam', 'DEU', 29, 2, 'Na Mose ameta Isilaeli onthe, na amea, Nĩmwonete na metho menyu w’onthe ũla Yeova wamwĩkĩe Valao ku Misili, na athũkũmi make onthe, na nthĩ yake yonthe;'),
('kam', 'DEU', 29, 3, 'mathĩna manene ala metho maku moonie, na syama, na moseng’yo asu manene:'),
('kam', 'DEU', 29, 4, 'ĩndĩ Yeova ndaamũnenga inyw’ĩ ngoo ya kũmanya, na metho ma kwona, na matũ ma kwĩw’a, kũvika ũmũnthĩ.'),
('kam', 'DEU', 29, 5, 'Nakwa nĩnamũtongoesye myaka mĩongo ĩna weũnĩ: ngũa syenyu ila mweekĩe ityaakũa, na iatũ syenyu ila mweekĩe maũũ ityaakũa.'),
('kam', 'DEU', 29, 6, 'Mũtyaĩsaa kĩmũtũ, o na mũtyanyusaa mbinyu kana kĩla kĩtoonasya; nĩ kana mũmanye atĩ ninyie Yeova Ngaĩ wenyu.'),
('kam', 'DEU', 29, 7, 'Na mwavika vaa, Sioni mũsumbĩ wa Esivoni, na Oku mũsumbĩ wa Mbasani, matumĩlĩla mokite naitũ, na twamakũna:'),
('kam', 'DEU', 29, 8, 'na twoosa nthĩ yoo, na twamanenga Aleuveni, na Angati, na nyunzu ya mbaĩ ya Amanase yĩthĩwe ũtiĩwa.'),
('kam', 'DEU', 29, 9, 'Kwatai ĩndĩ ndeto sya ũtianĩo ũũ, na mũisyĩka, nĩ kana ũndũnĩ w’onthe ũla mwĩkaa, mũathimĩke.'),
('kam', 'DEU', 29, 10, 'Ũmũnthĩ inyw’onthe nĩmũũngeme mbee wa Yeova Ngai wenyu; atongoi menyu, mbaĩ syenyu, atumĩa menyu, na anene menyu, o andũ onthe ma Isilaeli,'),
('kam', 'DEU', 29, 11, 'twana twenyu tũnini, iveti syenyu, na mwĩkali waku wa ũeninĩ ũla wĩ myakonĩ yaku ya maeema, kuma ũla unaa ngũ syaku kũvika ũla ũtavaa manzĩ maku;'),
('kam', 'DEU', 29, 12, 'nĩ kana ũlike ũtianĩonĩ wa Yeova Ngai waku, na wĩvĩtonĩ wake, ũla Yeova Ngai waku ũnũũtianĩa naku ũmũnthĩ;'),
('kam', 'DEU', 29, 13, 'nĩ kana akũlũmye ũmũnthĩ wĩthĩwe ũko wa andũ make, na nĩ kana ethĩwe Ngai waku, o tondũ waneenie naku, na tondũ wamevĩtĩe aaĩthe maku Avalaamu, na Isaka, na Yakovo.'),
('kam', 'DEU', 29, 14, 'Na ti inyw’ĩ mwĩ inyw’oka ala ngũtianĩa ũtianĩo ũũ nenyu na wĩvĩto ũũ,'),
('kam', 'DEU', 29, 15, 'ĩndĩ o nake ũla ũũngeme vaa vamwe naitũ ũmũnthĩ mbee wa Yeova Ngai waitũ, o na ũla ũte vaa vamwe naitũ ũmũnthĩ'),
('kam', 'DEU', 29, 16, '(nũndũ nĩmwĩsĩ ũndũ twatwĩe nthĩ ya Misili, na ũndũ twavĩtĩla katĩ wa mbaĩ ila mwavĩtĩle katĩ wasyo;'),
('kam', 'DEU', 29, 17, 'na inyw’ĩ nĩmwonete mothatyo moo, na mĩvw’anano yoo, ya mĩtĩ na mavia, vetha na thaavu, ĩla yaĩ kwoo);'),
('kam', 'DEU', 29, 18, 'kũikese kwĩthĩwa katĩ wenyu mũndũ mũũme, kana mũndũ mũka, kana mũvĩa, kana mbaĩ, ĩla ũmũnthĩ ĩnĩkwĩthyũũa ngoonĩ na kũtia Yeova Ngai waitũ, ĩthũkũme ngai sya mbaĩ isu; kũikese kwĩthĩwa kwenyu kĩtina kĩla kĩsyaa nyongo na kĩndũ kĩ ũũ;'),
('kam', 'DEU', 29, 19, 'na kũkethĩwa, yĩla ũkew’a ndeto sya kĩumo kĩĩ, akeathima ngoonĩ yake, akyasya, Ngeethĩwa na mũuo, o na naendeea kũatĩĩa ũng’endu wa ngoo yakwa, kwongeleela ũthengi waũni.'),
('kam', 'DEU', 29, 20, 'Yeova ndakamũekea, ĩndĩ ũthatu wa Yeova na kĩwĩu kyake ikamũtoesya mũndũ ũsu syũki, na kĩumo kyonthe kĩla kĩandĩkĩtwe ĩvukunĩ yĩĩ kĩkeethĩwa ĩũlũ wake, na Yeova akaananga syĩtwa yaku ĩtheo wa ĩtu.'),
('kam', 'DEU', 29, 21, 'Na Yeova akamũvatha aume mbaĩnĩ syonthe sya Isilaeli akwatwe nĩ ũthũku, kwĩanana na iumo syonthe sya ũtianĩo ũla ũandĩkĩtwe ĩvukunĩ yĩĩ ya mĩao.'),
('kam', 'DEU', 29, 22, 'Na nzyawa ĩla yũkĩte, nayo nĩ syana syenyu ila ikokĩla ĩtina wenyu, na mũeni ũla ũkoka kuma nthĩ yĩ kũasa, makasya, moona mothĩn’yo ma nthĩ ĩsu, na mowau ala Yeova wamĩwaisye;'),
('kam', 'DEU', 29, 23, 'na kana nthĩ yayo yonthe nĩ mũvĩlĩtĩ na mũnyũ, na maũvĩvye, ũndũ ĩtavandĩka, o na kũsyaa, o na ndĩmesya nyeki, o tondũ kwailyĩ kũng’uthũlangwa kwa Sotomo na Ngomola, Atima na Nzevoiimu, ila Yeova wang’uthũlangile ũthatunĩ wake, na kũthilĩkanĩ kwake:'),
('kam', 'DEU', 29, 24, 'o mbaĩ syonthe ikasya, Nĩkĩ Yeova wĩkĩte nthĩ ĩno ũu? Kĩtumi nĩ kyaũ kya ũthatu ũvyũvĩte ũu?'),
('kam', 'DEU', 29, 25, 'Nĩvo andũ measya, Nĩkwĩ thĩwa matiie ũtianĩo wa Yeova, Ngai wa aaĩthe moo, ũla watianĩe namo yĩla wamaumisye nthĩ ya Misili,'),
('kam', 'DEU', 29, 26, 'na maenda na kũthũkũma ngai ingĩ, na maithaitha, ngai ila mataamanya, na ila ũtaamanenga:'),
('kam', 'DEU', 29, 27, 'kwondũ wa ũu ũthatu wa Yeova wakanĩe nthĩ ĩno, amĩetee kĩumo kyonthe kĩla kĩandĩkĩtwe ĩvukunĩ yĩĩ;'),
('kam', 'DEU', 29, 28, 'na Yeova amakũa nthĩ yoo e na ũthatu, na ũthilĩku, na woo mwingĩ, na amekya nthĩ ĩngĩ, o ũndũ kũilyĩ ũmũnthĩ.'),
('kam', 'DEU', 29, 29, 'Maũndũ mavithe nĩ ma Yeova Ngai waitũ; ĩndĩ maũndũ mavuan’ye nĩ maitũ na ma syana sitũ tene na tene, nĩ kana twĩkae ndeto syonthe sya mĩao ĩno.'),
('kam', 'DEU', 30, 1, 'Na kũkeethĩwa, yĩla maũndũ aa onthe mekũkĩa, ũathimo na kĩumo, ala niĩte mbee waku, na wamalilikana wĩ mbaĩnĩ syonthe, vala Yeova Ngai waku wakũlũngĩlĩĩlye,'),
('kam', 'DEU', 30, 2, 'na wamũsyokea Yeova Ngai waku, na kwĩw’a wasya wake kwĩanana na w’onthe ũla ngũkwĩaĩa ũmũnthĩ, we na syana syaku, na ngoo yaku yonthe, na thayũ waku w’onthe;'),
('kam', 'DEU', 30, 3, 'nĩvo ĩndĩ Yeova Ngai waku ũkakũtũnga wume kũtavwanĩ kwaku, na ũkwĩw’ĩa tei, na akasyoka na ũkũmban’ya kuma ngonĩ syonthe sya andũ, kũla Yeova Ngai waku wakũnyaĩĩkĩsye.'),
('kam', 'DEU', 30, 4, 'Ethĩwa amwe maku ala malũngilw’e makethĩwa me ngalĩko ya mũminũkĩlyo ya ĩtu, kuma ku Yeova Ngai waku akakũmban’ya, na akawĩsĩa kw’o:'),
('kam', 'DEU', 30, 5, 'na Yeova Ngai waku akakũlikya nthĩ ĩla aaĩthe maku mamyosie, naku ũkamĩmesya; nake akakwĩka nesa, na ũkwingĩvya kwĩ aaĩthe maku.'),
('kam', 'DEU', 30, 6, 'Na Yeova Ngai waku akaĩka ngoo yaku, na ngoo ya ũsyao waku, ũmwende Yeova Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe, nĩ kana wĩthĩwe thayũ.'),
('kam', 'DEU', 30, 7, 'Na Yeova Ngai waku akeekĩa iumo ii syonthe ĩũlũ wa amaitha maku, na ĩũlũ wa ala meũkũmena, ala makũthĩnisye.'),
('kam', 'DEU', 30, 8, 'Naku ũkasyoka na kwĩw’a wasya wa Yeova, na kwĩka mĩao yake yonthe ĩla ngũkwĩaĩa ũmũnthĩ.'),
('kam', 'DEU', 30, 9, 'Na Yeova Ngai waku akakwongeleela wĩanĩ w’onthe wa moko maku, na ũsyaonĩ wa mwĩĩ waku, na ũsyaonĩ wa indo syaku, na ũsyaonĩ wa nthĩ yaku, kwondũ wa ũseo: nũndũ Yeova akakũtanĩa ĩngĩ kwondũ wa ũseo, o tondũ wamatanĩaa aaĩthe maku;'),
('kam', 'DEU', 30, 10, 'ethĩwa ũkethukĩĩasya wasya wa Yeova Ngai waku, kũkwataa mĩao yake na myamũlo yake ĩla ĩandĩkĩtwe ĩvukunĩ yĩĩ ya mĩao; ethĩwa wĩmũsyokea Yeova Ngai waku na ngoo yaku yonthe, na thayũ waku w’onthe.'),
('kam', 'DEU', 30, 11, 'Nũndũ mwĩao ũũ ũla ngũkwĩaĩa ũmũnthĩ, ti mũito mũno kwaku, o na ndwĩ kũasa.'),
('kam', 'DEU', 30, 12, 'Ndwĩ ĩtunĩ, ũndũ ũneena, Nũũ ũla ũkambata ĩtunĩ kwondũ witũ, na kũwosa na kũtũetee, na kũtwĩw’ĩthya, nĩ kana twĩke?'),
('kam', 'DEU', 30, 13, 'O na ndwĩ mũingo wa ũkanga, ũndũ ũneena, Nũũ ũla ũkainga ũkanga kwondũ witũ, na kũwosa na kũtũetee, na kũtwĩw’ĩthya, nĩ kana twĩke?'),
('kam', 'DEU', 30, 14, 'Ĩndĩ ĩ ndeto yĩ vakuvĩ mũno naku, kanyw’anĩ waku, na ngoonĩ yaku, nĩ kana ũmĩke.'),
('kam', 'DEU', 30, 15, 'Sisya, nĩnĩĩte mbee waku ũmũnthĩ thayũ na ũseo, na kĩkw’ũ na ũthũku;'),
('kam', 'DEU', 30, 16, 'kwa ũu ngũkwĩaĩa ũmũnthĩ ũmwende Yeova Ngai waku, na kũenda nzĩanĩ syake, na kũkwata mĩao yake na myamũlo yake na motw’ĩo make, nĩ kana wĩthĩwe thayũ na kwingĩva, na nĩ kana Yeova Ngai waku akũathime wĩ nthĩ ĩla wĩlika ũmĩmesye.'),
('kam', 'DEU', 30, 17, 'Ĩndĩ ethĩwa ngoo yaku ĩkeethyũũa, naku ndũkwenda kwĩw’a, ĩndĩ ũkakusw’a ũtee, na kũthaitha ngai ingĩ, na kwithũkũma;'),
('kam', 'DEU', 30, 18, 'nĩngũmũtavya ũmũnthĩ, mũitĩa kwaa; mũtikaingĩvya mĩthenya yenyu mwĩ nthĩ ĩla mwĩĩnga Yolotani mũlike kũmĩmesya.'),
('kam', 'DEU', 30, 19, 'Nĩngwĩta ĩtu na nthĩ imũkũsĩĩe ũmũnthĩ, kana nĩniĩte mbee waku thayũ na kĩkw’ũ, ũathimo na kĩumo: kwondũ wa ũu nyuva thayũ, nĩ kana wĩkale thayũ, we na ũsyao waku;'),
('kam', 'DEU', 30, 20, 'na kũmwenda Yeova Ngai waku, na kwĩthukĩĩsya wasya wake, na kũlũman’ya nake; nũndũ nĩwe thayũ waku, na wingĩ wa mĩthenya yaku; nĩ kana wĩkalae nthĩ ĩla Yeova wamevĩtĩe aaĩthe maku, Avalaamu, na Isaka, na Yakovo, kũmanenga.'),
('kam', 'DEU', 31, 1, 'Na Mose athi na amatavya Isilaeli onthe ndeto ii.'),
('kam', 'DEU', 31, 2, 'Na amea, Ũmũnthĩ nĩ wa myaka ĩana na mĩongo ĩlĩ; nditonya kumaala na kũlika ĩngĩ: na Yeova nũndavĩtye, Ndũkainga ũsĩ ũũ wa Yolotani.'),
('kam', 'DEU', 31, 3, 'Yeova Ngai waku, akatongosya mbee waku; akaananga mbaĩ isu syume mbee waku, naku ũkailũngya nthĩ yasyo: na Yosua akatongosya mbee waku, o tondũ Yeova ũneenete.'),
('kam', 'DEU', 31, 4, 'Na Yeova akameka o tondũ wamekie Sioni na Oku, asumbĩ ma Aamoli, na nthĩ yoo; ala wamanangie.'),
('kam', 'DEU', 31, 5, 'Na Yeova akamanengane mbee wenyu, na mũkameka kwĩanana na mwĩao w’onthe ũla namwĩaĩe.'),
('kam', 'DEU', 31, 6, 'Ĩthĩwa na vinya na ũkũmbaũ mũnene, ndũkakĩe, o na ndũkatelemw’e nĩmo: nũndũ Yeova Ngai waku, nĩwe ũendaa naku; ndakakũnyivĩa, o na ndakakũtia.'),
('kam', 'DEU', 31, 7, 'Na Mose amwĩta Yosua, na amwĩa Isilaeli onthe mene na metho moo, Ĩthĩwa na vinya na ũkũmbaũ mũnene: nĩkwĩthĩwa ũkalika wĩ na andũ aa nthĩ ĩla Yeova wamevĩtĩe aaĩthe moo kũmanenga; na ũkatuma matiĩwa yo.'),
('kam', 'DEU', 31, 8, 'Na Yeova, nĩwe ũla ũendaa mbee waku; akeethĩwa vamwe naku, ndakakũnyivĩa, o na ndakakũtia: ndũkakĩe, o na ndũkateve.'),
('kam', 'DEU', 31, 9, 'Na Mose aandĩka mĩao ĩno, na amanenga athembi ana ma Livai, ala makuaa ĩsandũkũ ya ũtianĩo ya Yeova, vamwe na atumĩa onthe ma Isilaeli.'),
('kam', 'DEU', 31, 10, 'Na Mose ameaĩa, akyasya, Kĩla myaka mũooza yathela, ĩvinda yĩla yĩtw’ĩtwe ya kũekanĩa mathiĩ, mbokanĩ ya malwanda,'),
('kam', 'DEU', 31, 11, 'ĩvinda ya kũka kwa Isilaeli onthe kumĩla mbee wa Yeova Ngai waku vala wĩnyuva, wĩsomaa mĩao ĩno matũnĩ ma Isilaeli onthe.'),
('kam', 'DEU', 31, 12, 'Ũmbanasya andũ, aũme na aka na twana tũnini, na mwĩkali wa ũeninĩ ũla wĩkalaa kwaku, nĩ kana mew’e, na nĩ kana memanyĩsye, na kũmũkĩa Yeova Ngai wenyu, na kũkwata na kwĩka ndeto syonthe sya mĩao ĩno;'),
('kam', 'DEU', 31, 13, 'na nĩ kana syana syoo, ila itaamanya, syĩw’e, na kwĩmanyĩsya kũkĩa Yeova Ngai wenyu, mĩthenya yonthe ĩla mwĩĩkala nthĩ ĩla mwĩinga Yolotani mũthi mũmĩmesye.'),
('kam', 'DEU', 31, 14, 'Na Yeova amwĩa Mose, Sisya, mĩthenya ya kũkw’a kwaku nĩthengee: mwĩte Yosua, mũkaũngame ĩeemanĩ ya kũmbanĩa, nĩ kana nĩmwĩaĩe Yosua. Na Mose na Yosua maenda, na maũngama ĩeemanĩ ya kũmbanĩa.'),
('kam', 'DEU', 31, 15, 'Na Yeova aumĩla Ĩeemanĩ e kĩtuĩnĩ kya mũumbĩ: na kĩtuĩ kyu kya mũumbĩ kyaũngama ĩũlũ wa mũomo wa Ĩeema.'),
('kam', 'DEU', 31, 16, 'Na Yeova amwĩa Mose, Sisya, ũkakoma na aaĩthe maku; na andũ aa makookĩla, na kwĩka ũmalwaya wa kũatĩĩa ngai ngeni sya nthĩ, vala meenda na kwĩkalaa katĩ wasyo, na makandia, na kwananga ũtianĩo wakwa ũla natianĩe nao.'),
('kam', 'DEU', 31, 17, 'Nĩvo ũthatu wakwa ũkamakanĩa mũthenya ũsu, na ngamatia, na ngamavitha ũthyũ wakwa, na makaminwa vyũ, na mothũku maingĩ na mathĩna makamokĩa; kwondũ wa ũu makaneena mũthenya ũsu, Mothũku aa matyaatũkĩa nũndũ Ngai waitũ nde vamwe naitũ?'),
('kam', 'DEU', 31, 18, 'Na kũvitha nĩngavitha ũthyũ wakwa mũthenya ũsu nũndũ wa ũthuku w’onthe ũla makethĩwa mekĩte, ũndũ wa kwĩthyũũĩa ngai ingĩ.'),
('kam', 'DEU', 31, 19, 'Kwondũ wa ũu andĩkai wathi ũũ kwondũ wenyu, na ũmanyĩsye ana ma Isilaeli: ũwĩkĩe makanyw’anĩ moo, nĩ kana wathi ũũ wĩthĩwe ngũsĩ yakwa kwa ana ma Isilaeli.'),
('kam', 'DEU', 31, 20, 'Nũndũ yĩla nĩmalikya nthĩ ĩla namevĩtĩe aaĩthe moo, nthĩ yusũĩte ĩia na ũkĩ wa nzũkĩ, na maya na mavũna, na manoa; nĩvo ĩndĩ makethyũũĩa ngai ingĩ, na kwithũkũma, na kũmbũthya, na kwananga ũtianĩo wakwa.'),
('kam', 'DEU', 31, 21, 'Na kũkeethĩwa, yĩla mothũku maingĩ na mathĩna memokĩa, wathi ũũ ũkeethĩwa ngũsĩ mbee woo; nũndũ ndũkola kuma makanyw’anĩ ma ũsyao woo: nũndũ nĩnĩsĩ motalĩthyo moo ala meũtalĩthya ũmũnthĩ, ndanamba kũmalikya nthĩ ĩla namevĩtĩe.'),
('kam', 'DEU', 31, 22, 'Na ĩndĩ Mose aandĩka wathi ũũ mũthenya o ũsu, na amamanyĩsya ana ma Isilaeli.'),
('kam', 'DEU', 31, 23, 'Na amwĩaĩa Yosua mwana wa Nuni, na amwĩa, Ĩthĩwa na vinya na ũkũmbaũ mũnene; nũndũ ũkamalikya ana ma Isilaeli nthĩ ĩla namevĩtĩe: nakwa ngeethĩwa vamwe naku.'),
('kam', 'DEU', 31, 24, 'Na kweethĩwa, Mose amina kũandĩka ndeto sya mĩao ĩno ĩvukunĩ, na kũmina syonthe,'),
('kam', 'DEU', 31, 25, 'Mose ameaĩa Alivai, ala makuaa ĩsandũkũ ya ũtianĩo ya Yeova, akĩmea,'),
('kam', 'DEU', 31, 26, 'Osai ĩvuku yĩĩ ya mĩao, na mũyie ũtee wa ĩsandũkũ ya ũtianĩo ya Yeova Ngai wenyu, nĩ kana yĩkalae vo yĩthĩwe ngũsĩ kwaku.'),
('kam', 'DEU', 31, 27, 'Nũndũ nĩnĩsĩ ũng’endu waku, na ngingo yaku nyũmũ: sisya, o yĩla nyie nĩ thayũ vamwe nenyu ũmũnthĩ, nĩmũng’endeaa Yeova; na nĩ mbee veanata ĩtina wa kũkw’a kwakwa?'),
('kam', 'DEU', 31, 28, 'Mbũmbanĩsyai atumĩa onthe ma mbaĩ syenyu, na anene menyu, nĩ kana nĩneene ndeto ii matũnĩ moo, na kwĩta ĩtu na nthĩ imakũsĩĩe.'),
('kam', 'DEU', 31, 29, 'Nũndũ nĩnĩsĩ atĩ ĩtina wa kũkw’a kwakwa mũkeethũkya vyũ, na kwĩthyũũa na kũtia nzĩa ĩla namwĩaĩe; na ũthũku ũkamũkĩa mĩthenya ya mũminũkĩlyo; nĩkwĩthĩwa mũkekaa ũla Yeova wonaa wĩ ũthũku, kũmũthatya ũndũ wa wĩa wa moko menyu.'),
('kam', 'DEU', 31, 30, 'Na Mose aneena matũnĩ ma ũmbano w’onthe wa Isilaeli ndeto sya wathi ũũ, kũvika syathela vyũ.'),
('kam', 'DEU', 32, 1, 'Ĩthukĩĩsyei, inyw’ĩ matu, na nĩngũneena; Na nthĩ nĩĩthukĩĩsye ndeto sya kanyw’a wakwa.'),
('kam', 'DEU', 32, 2, 'Ũmanyĩsyo wakwa ũketĩkaa ta mbua; Kũneena kwakwa kũkavolotangaa ta ĩmwe, Ta ũnyenyeũ nyekinĩ ya vuvĩ, Na ta mĩono ya mbua tũmĩtĩnĩ.'),
('kam', 'DEU', 32, 3, 'Nũndũ ngatavan’ya syĩtwa ya Yeova: Mũwetei Ngai waitũ ũnene.'),
('kam', 'DEU', 32, 4, 'Ĩvia, wĩa wake nĩ mwĩanĩu; Nũndũ nzĩa syake syonthe nĩ ndũngalu: Ngai wa kĩthito na ũte na naĩ, Nake nĩ wa w’o na mũlũngalu.'),
('kam', 'DEU', 32, 5, 'Nĩmamwĩkĩte ũthũku, ti ana make, nĩyo ĩlanga yoo; Nĩ ũsyao wĩ ngũlũ na mũthyoeku!'),
('kam', 'DEU', 32, 6, 'Nĩw’o mũũmũĩva Yeova, Inyw’ĩ andũ atumanu na mũte na ũĩ? Tiwe ĩthe waku ũla wakũthooie? Nĩwe wakũmbie, na akũlũlũmĩlya.'),
('kam', 'DEU', 32, 7, 'Lilikana mĩthenya ya tene, Sũanĩa myaka ya nzyawa nyingĩ: Kũlya ĩthe waku, nake akakwon’ya; Kũlya atumĩa maku, na makakũtavya.'),
('kam', 'DEU', 32, 8, 'Yĩla Ũla Wĩ Ĩũlũ wa Onthe wanengie mbaĩ ũtiĩwa wasyo, Yĩla wamataanisye ana ma andũ, Nĩwamavakanisye andũ mĩvaka Kwĩanana na ũndũ ana ma Isilaeli meanaa.'),
('kam', 'DEU', 32, 9, 'Nũndũ kĩlungu kya Yeova nĩ andũ make; Yakovo nĩwe kĩanda kya ũtiĩwa wake.'),
('kam', 'DEU', 32, 10, 'Amwĩthĩa nthĩ yĩ yalata, Na weũnĩ mwanangĩku walumaa nyamũ; Amũthyũlũlũka, amũtethya, Amũsũvĩa ta kyũma kya itho yake.'),
('kam', 'DEU', 32, 11, 'O ũndũ ndiũ yũkĩlangasya ndala yayo, Ĩkĩũlũkanga ĩũlũ wa tũswii twayo, Ĩkĩtambũũkya nthwau syayo, ĩitwosa, Ĩkĩtũkua ĩũlũ wa nthwau syayo:'),
('kam', 'DEU', 32, 12, 'Yeova e weka amũtongoesya, Na vatyaĩ ngai ngenĩ yaĩ nake.'),
('kam', 'DEU', 32, 13, 'Amwambatya kũndũ kũtũlu kwa nthĩ, Nake aya ũsyao wa mĩũnda; Na amwongethya ũkĩ wa nzũkĩ ĩvianĩ, Na mauta ĩvianĩ yũmũ mũno;'),
('kam', 'DEU', 32, 14, 'Mauta ma ndĩthya ya ng’ombe, na ĩia ya ndĩthya ya mbũi na malondu, Vamwe na mathunya ma tũtena twa malondu, Na ndũũme sya kĩ‐Mbasani, na mbũi, Vamwe na nganũ ila nzeo mbee; Na wanyw’a mbinyu ya nthakame ya nzavivũ.'),
('kam', 'DEU', 32, 15, 'Ĩndĩ Yesuluni anoa mũno, na ekangya nthele: Nũnoete, na ũkaimba, na ũkatendea; Nĩvo ĩndĩ wamũtiie Ngai ũla wamũmbie, Na avũthya Ĩvia ya ũtangĩĩo wake.'),
('kam', 'DEU', 32, 16, 'Mamwĩkĩa kĩwĩu ũndũ wa ngai ngeni; Mamũthatya ũndũ wa mothũku moo.'),
('kam', 'DEU', 32, 17, 'Mathembea ndaimoni, nasyo ti Ngai, Ngai ila mataamanya, Ngai ngeni ila syaumbũkie mĩtũkĩ, Ila aaĩthe menyu mataikĩaa.'),
('kam', 'DEU', 32, 18, 'Ĩvia yĩla yakũsyaie ndũyĩlilikana, Na nĩwũlĩtwe nĩ Ngai ũla wakũsyaie.'),
('kam', 'DEU', 32, 19, 'Na Yeova oona, na amathĩtha, Nũndũ eew’ĩthiw’e woo nĩ ana make aũme na eĩtu.'),
('kam', 'DEU', 32, 20, 'Nake asya, Ngamavitha ũthyũ wakwa, Ngasisya ũndũ mũminũkĩlyo woo ũkethĩwa ũilyĩ: Nũndũ nĩ ũsyao mũng’endu mũno, Syana ite na kĩthito nongi.'),
('kam', 'DEU', 32, 21, 'Nĩmambĩkĩĩte kĩwĩu nũndũ wa isu ite Ngai; Nĩmanthatisye kwondũ wa maũndũ moo ma mana: Nakwa ngamekĩa kĩwĩu kwondũ wa asu mate andũ; Ngamathatya kwondũ wa mbaĩ ndumanu.'),
('kam', 'DEU', 32, 22, 'Nũndũ mwaki nĩwakanĩte kwondũ wa ũthatu wakwa, Naw’o nũvĩvasya o na kũvika Seoli kũu nthĩnĩ wa nthĩ, Na nũminaa nthĩ vamwe na wingĩvo wayo, Na nũkwatasya mwaki myambĩlĩlyo ya iĩma.'),
('kam', 'DEU', 32, 23, 'Ngombĩĩa mothũku ĩũlũ woo; Ngamaathanga na mĩsyĩ yakwa ĩthele vyũ:'),
('kam', 'DEU', 32, 24, 'Makang’ong’wa nĩ nzaa, na kũvĩvw’a nĩ muutĩa ũilyĩ mwakĩ Na wanangĩko mũthũku; Ngaete maeo ma nyamũ mbai ĩũlũ woo, Vamwe na ũoi wa tũsamũ tũla tũtambũkaa kĩtoonĩ.'),
('kam', 'DEU', 32, 25, 'Na kũu nza ũvyũ ũkooaana, Na w’ĩa mũnene tũsũmbanĩ nthĩnĩ; Ũkaananga mwanake na mwĩĩtu mũtheu me elĩ, Kaũkenge vamwe na mũndũ mũũme wĩ mbuĩ.'),
('kam', 'DEU', 32, 26, 'Naisye, Nĩthĩwa nĩmanyaĩĩkya kũasa, Nĩthĩwa nĩtuma ũlilikan’yo woo ũthela andũnĩ;'),
('kam', 'DEU', 32, 27, 'Kethĩwa ndiũkĩa ũthatu wa amaitha, Nthũ syoo itikese kũsũanĩa ũndũ ũte wa w’o, Itikese kwasya, Kw’oko kwitũ nĩkũtũlĩtw’e, Na Yeova ndaaĩka ũu w’onthe.'),
('kam', 'DEU', 32, 28, 'Nũndũ nĩ mbaĩ ĩtataĩkaa, Na ndĩ ũmanyi nthĩnĩ wayo.'),
('kam', 'DEU', 32, 29, 'A! Kethĩwa nĩ oĩ, na makamanya ũũ, Na makasũanĩa mũminũkĩlyo woo!'),
('kam', 'DEU', 32, 30, 'Ũmwe atonya ata kũlũngya ngili, Na elĩ kũlũngya ngili ĩkũmi, Ate o Ĩvia yoo yĩmathooetye, Na Yeova amanenganĩte?'),
('kam', 'DEU', 32, 31, 'Nũndũ ĩvia yoo yĩtiilyĩ ta Ĩvia yitũ, O na amaitha moo ene nĩmeũtw’a ũu.'),
('kam', 'DEU', 32, 32, 'Nũndũ mũsavivũ woo nĩ wa mũsavivũ wa Sotomo, Na wa mĩũnda ya Ngomola: Nzavivũ syoo nĩ nzavivũ sya nyongo, Itũngo syasyo syĩ ũũ:'),
('kam', 'DEU', 32, 33, 'Mbinyu yoo nĩ ũoi wa nzoka, Na ũoi mũthũku wa syĩko.'),
('kam', 'DEU', 32, 34, 'Ũu ndwiĩtwe kwakwa, Ũkasiĩlanĩlw’a na ũthwii wakwa mwie?'),
('kam', 'DEU', 32, 35, 'Ũĩvanĩsyo nĩ wakwa, na kũĩva, Ĩvinda yĩla kũũ kwoo kũkatendelũka: Nũndũ mũthenya wa wanangĩko woo nũthengeee, Na maũndũ ala makamokĩa makekalaataa.'),
('kam', 'DEU', 32, 36, 'Nũndũ Yeova akasilĩla andũ make, Na akeetũnga kwondũ wa athũkũmi make; Yĩla wĩona vinya woo wathela, Na vati mũndũ mwove kana ũla ũte mwove.'),
('kam', 'DEU', 32, 37, 'Nake akasya, Iĩva ngai syoo, Ĩvia yĩla meekwatĩtye;'),
('kam', 'DEU', 32, 38, 'Ila syaĩe mathunya ma nthembo syoo, Na syanyw’a mbinyu ya nthembo yoo ya kũnyuwa? Syũkĩle na kũmũtethya inyw’ĩ, Syĩthĩwe mawĩvitho menyu.'),
('kam', 'DEU', 32, 39, 'Sisya yu kana nyie, o nyie, ninyie we, Na vati ngai ĩngĩ vamwe nakwa: Ninyie nũaa, na ninyie nĩthayũũkasya; Ninyie nũkitaa, na ninyie nĩvoasya; Na vati mũndũ ũtonya kũvenana kw’okonĩ kwakwa.'),
('kam', 'DEU', 32, 40, 'Nũndũ nĩngũkĩlya kw’oko kwakwa ĩtunĩ, Na kwasya, O ũndũ nyie nĩ thayũ tene na tene,'),
('kam', 'DEU', 32, 41, 'Ethĩwa nĩngũnoa ũvyũ wakwa ũla ũtisatisaa, Na kw’oko kwakwa kũĩkwata ũsili; Ngeeĩvanĩsya amaitha makwa, Ngaĩva ala mamenaa.'),
('kam', 'DEU', 32, 42, 'Ngatoonethya mĩsyĩ yakwa nthakame, Na ũvyũ wakwa ũkamina mĩĩ; Nthakame ya ala mooaiwe na ala mataviwe, Kuma mĩtwenĩ ya atongoi ma amaitha.'),
('kam', 'DEU', 32, 43, 'Tanai, inyw’ĩ mbaĩ, vamwe na andũ make: Nũndũ akaĩvanĩsya nthakame ya athũkũmi make, Na akaĩva nthũ syake, Na akaumya nthembo kwondũ wa nthĩ yake, kwondũ wa andũ make.'),
('kam', 'DEU', 32, 44, 'Na Mose ooka na aneena ndeto syonthe sya wathi ũũ matũnĩ ma andũ, we, na Osea mwana wa Nuni.'),
('kam', 'DEU', 32, 45, 'Na Mose amina kũmatavya Isilaeli onthe ndeto ii syonthe;'),
('kam', 'DEU', 32, 46, 'na amea, Ĩkĩai ngoonĩ syenyu ndeto syonthe ila ngũmũkũsĩĩa ũmũnthĩ, ila mũkeaĩa syana syenyu isũvĩe na kwĩka, o ndeto syonthe sya mĩao ĩno.'),
('kam', 'DEU', 32, 47, 'Nũndũ ti ũndũ wa mana kwenyu; nũndũ nĩ thayũ wenyu, na kwondũ wa ũndũ ũsu mũkaingĩvĩsya mĩthenya yenyu nthĩ, ĩla mwĩinga Yolotani mũmĩmesye.'),
('kam', 'DEU', 32, 48, 'Na Yeova aneena na Mose mũthenya o ũsu, akĩmwĩa,'),
('kam', 'DEU', 32, 49, 'Ambata kĩĩmanĩ kĩĩ kya Avalimu, kũvika kĩĩma kya Nevo, kĩla kĩ nthĩ ya Moavi, kĩla kyelekele Yeliko; na ĩloele nthĩ ya Kanaani, ĩla nĩmanengae ana ma Isilaeli yĩthĩwe ng’ũndũ yoo;'),
('kam', 'DEU', 32, 50, 'ũkakw’ĩe kĩĩmanĩ kĩla ũkwambata, na ũkyũmbanw’a vamwe na andũ maku, o tondũ Aluni mwana‐a‐mwenyu wakw’ĩĩe kĩĩmanĩ kya Olu, na oombanw’a vamwe na andũ make:'),
('kam', 'DEU', 32, 51, 'nĩkwĩthĩwa nĩmwambĩtanĩsye katĩ wa ana ma Isilaeli manzĩnĩ ma Meliva nthĩ ya Katesi, weũnĩ wa Nzini; nĩkwĩthĩwa mũtyaonan’ya kana nyie nĩ mũtheu katĩ wa ana ma Isilaeli.'),
('kam', 'DEU', 32, 52, 'Nũndũ ũkoona ĩ nthĩ mbee waku; ĩndĩ ndũkalika nthĩ ĩsu ĩla nĩmanengae ana ma Isilaeli.'),
('kam', 'DEU', 33, 1, 'Na ũũ nĩw’o ũathimo, ũla Mose mũndũ wa Ngai wamaathimie ana ma Isilaeli naw’o atanakw’a.'),
('kam', 'DEU', 33, 2, 'Nake asya, Yeova auma Sinai, Na amaumĩlĩla kuma Seili; Akena kuma kĩĩmanĩ kya Valani, Na ooka kuma vala ve ngili makũmi sya ala atheu: Ngalĩ ya kw’oko kwake kwa aũme kwaĩ mĩao yĩ mwaki kwondũ woo.'),
('kam', 'DEU', 33, 3, 'Ĩĩ, nũmendete andũ; Atheu make onthe me kw’okonĩ kwaku: Na mekala nthĩ maũũnĩ maku; Kĩla ũmwe akoosa sya ndeto syaku.'),
('kam', 'DEU', 33, 4, 'Mose atwĩaĩa mĩao, Ũtiĩwa wa ũmbano wa Yakovo.'),
('kam', 'DEU', 33, 5, 'Nake aĩ mũsumbĩ nthĩnĩ wa Yesuluni, Yĩla atongoi ma andũ moombanaa, Mbaĩ syonthe sya Isilaeli vamwe.'),
('kam', 'DEU', 33, 6, 'Leuveni nĩekale thayũ, na ndakakw’e; Ĩndĩ andũ make methĩwe anini ũtalonĩ.'),
('kam', 'DEU', 33, 7, 'Na ũathimo wa Yuta nĩ ũũ; na asya, Ĩw’a, Yeova, wasya wa Yuta, Na kũmũete kwa andũ make. Nĩweyũkitĩe mwene na moko make; Naku ũkamũtethya ũndũ wa nthũ syake.'),
('kam', 'DEU', 33, 8, 'Na ũndũ wa Livai asya, Syĩndũ syaku syĩtawa Thumimu na Ulimu syĩ na ũla waku ũla ũmũkĩaa Ngai, Ũla wamũtatĩe kũu Masa, Ũla watetanĩsye nake kũu manzĩnĩ ma Meliva;'),
('kam', 'DEU', 33, 9, 'Ũla waneenie ũndũ wa ĩthe wake, na ũndũ wa nyinyia, Ndyaamwona; O na ndaametĩkĩla ana‐a‐ĩthe, O na ndeesĩ syana syake: Nũndũ nĩmasũvĩe ndeto yaku, Na malũmya ũtianĩo waku.'),
('kam', 'DEU', 33, 10, 'Makamanyĩsya Yakovo motw’ĩo maku, Na Isilaeli mĩao yaku, Makeekĩa ũvani mbee waku, Na nthembo nima ya kũvĩvw’a kĩthembeonĩ kyaku.'),
('kam', 'DEU', 33, 11, 'Yeova, aathima syĩndũ syake, Na ĩtĩkĩla wĩa wa moko make: Makũne ala mamũkĩlĩĩlaa inyunyu itũlĩke, Na ala mamũmenaa, matikaokĩle ĩngĩ.'),
('kam', 'DEU', 33, 12, 'Na ũndũ wa Mbenyamini asya, Mwendwa wa Yeova akekala vate mũisyo vakuvĩ nake; Nũmũvw’ĩkaa mũthenya w’onthe, Nake ekalaa katĩ wa ituo syake.'),
('kam', 'DEU', 33, 13, 'Na ũndũ wa Yosevu asya, Nthĩ yake nĩathimwe nĩ Yeova, Ũndũ wa syĩndũ syĩ vata mũno sya ĩtunĩ, ũndũ wa ĩmwe, Na ũndũ wa syũngũ syĩkalaa ĩtheo,'),
('kam', 'DEU', 33, 14, 'Na ũndũ wa syĩndũ syĩ vata mũno sya mosyao ma syũa, Na ũndũ wa syĩndũ syĩ vata mũno sya mosyao ma myei,'),
('kam', 'DEU', 33, 15, 'Na ũndũ wa syĩndũ syĩ vata mũno sya iĩma sya tene, Na ũndũ wa syĩndũ syĩ vata mũno sya tũlĩma tũla twĩkalaa tene na tene,'),
('kam', 'DEU', 33, 16, 'Na ũndũ wa syĩndũ syĩ vata mũno sya nthĩ na wusũu wayo, Na kwenda kũseo kwa ũla wekalile kakuthunĩ, Ũathimo nĩwũke mũtwenĩ wa Yosevu, Na mũtwe lolotyanĩ kwa ũla wataanĩtw’e na ana‐a‐ĩthe.'),
('kam', 'DEU', 33, 17, 'Kĩla kĩsyaĩtwe mbee kya ndĩthya yake ya ng’ombe ũnene nĩ wakyo; Na mbya syakyo nĩ mbya sya mboo: Nasyo akailuta ngo syonthe sya andũ, o itulu sya nthĩ: Namo nĩ ngili makũmi sya Evalaimu, Namo nĩ ngili sya Manase.'),
('kam', 'DEU', 33, 18, 'Na ũndũ wa Nzevuluni asya, Tana, Nzevuluni, kumaalanĩ kwaku; Na, Isakali, maeemanĩ maku.'),
('kam', 'DEU', 33, 19, 'Makasyĩta ngo sya andũ syũke kĩĩmanĩ; Vau makathembaa nthembo sya ũlũngalu: Nũndũ makoonga wingĩ wa maũkanga, Na ũthwii mũvithe kĩthangathĩnĩ.'),
('kam', 'DEU', 33, 20, 'Na ũndũ wa Ngati asya, Naathimwe ũla ũmũnenevasya Ngati: Oveeasya ta mũnyambũ mũka, Na kũtembũanga kw’oko, ĩĩ, o na mũtwe lolotyanĩ.'),
('kam', 'DEU', 33, 21, 'Nake enyuvĩaa kĩlungũ kya mbee, Nũndũ nĩkyo kĩlungu kĩla kiĩawa mũnengani wa mĩao; Na ookan’ya na atongoi ma andũ; Na eeka ũlũngalu wa Yeova, Na motw’ĩo make kwa Isilaeli.'),
('kam', 'DEU', 33, 22, 'Na ũndũ wa Ndani asya, Ndani nĩ ĩswii ya mũnyambũ, Yĩla yĩtũlĩlaa kuma Mbasani.'),
('kam', 'DEU', 33, 23, 'Na ũndũ wa Navitali asya, We Navitali, ũvũnĩtw’e na ũseo, Na kusũw’a na ũathimo wa Yeova, Mesya ng’ũndũ ngalĩ ya ũthũĩlonĩ wa syũa na ngalĩ ya ĩtheo.'),
('kam', 'DEU', 33, 24, 'Na ũndũ wa Aseli asya, Naathimwe Aseli ethĩwe na syana; Etĩkĩlwe nĩ ana‐a‐ĩthe, Na navotye kũũ kwake mautanĩ.'),
('kam', 'DEU', 33, 25, 'Ivingi syaku ikeethĩwa sya iaa na ũthuku; O tondũ mĩthenya yaku yĩana, now’o vinya waku ũkethĩwa wĩana.'),
('kam', 'DEU', 33, 26, 'Vai ũilyĩ ta Ngai, we Yesuluni, Ũla ũkuawa nĩ matu ũndũ wa ũkũtethya, Na ĩũlũ wa mathweo ũnenenĩ wake.'),
('kam', 'DEU', 33, 27, 'Ngai wa tene na tene nĩ wĩkalo waku, Na ĩtheo ve moko ma tene na tene. Na alũngya mũmaitha mbee waku Na asya, Ananga.'),
('kam', 'DEU', 33, 28, 'Na Isilaeli nĩwĩkalaa vate mũisyo, Nthongo ya Yakovo yĩ yoka, Nthĩ yĩ lĩu wa mbaa ngetha na mbinyu mbĩthĩ; Ĩĩ, matu make mavolotangasya ĩmwe.'),
('kam', 'DEU', 33, 29, 'Wĩ mũtanu, Isilaeli: Ũla ũilyĩ taku nũũ, andũ matangĩĩĩtwe nĩ Yeova, Ngao ya ũkũtethya, Na ũvyũ wa ũnene waku! Na amaitha maku makakwĩnyivĩsya; Naku ũkakinyanga kũndũ kwoo kũtũlu.'),
('kam', 'DEU', 34, 1, 'Na Mose ambata kuma ndiĩnĩ sya Moavi kũvika kĩĩma kya Nevo, mũtumbĩnĩ wa kĩĩma kya Visika, kĩla kyelekele Yeliko. Na Yeova amwon’ya nthĩ yonthe ya Ngileati, kũvika Ndani,'),
('kam', 'DEU', 34, 2, 'na Navitali yonthe, na nthĩ ya Evalaimu na Manase, na nthĩ yonthe ya Yuta, kũvika ũkanga ũla wĩ ũthũĩlonĩ wa syũa,'),
('kam', 'DEU', 34, 3, 'na ngalĩ ya Ĩtheo, na Ũiĩ wĩ mwandanĩ wa Yeliko ndũa ya mĩtende, kũvika Nzoali.'),
('kam', 'DEU', 34, 4, 'Na Yeova amwĩa, Ĩno nĩyo nthĩ ĩla namevĩtĩe Avalaamu, na Isaka, na Yakovo, ngyasya, Ngamĩnenga ũsyao waku: nĩnakwon’ya ũmyone na metho maku, ĩndĩ ndũkainga kw’o.'),
('kam', 'DEU', 34, 5, 'Na ĩndĩ Mose mũthũkũmi wa Yeova akw’ĩa kũu nthĩ ya Moavi, kwĩanana na ndeto ya Yeova.'),
('kam', 'DEU', 34, 6, 'Na amũthika mwandanĩ nthĩ ya Moavi kwelekela Mbethi‐veoli: ĩndĩ vai mũndũ waamanya mbũa yake kũvika ũmũnthĩ.'),
('kam', 'DEU', 34, 7, 'Na Mose aĩ wa myaka ĩana na mĩongo ĩlĩ yĩla wakwie: metho make matyaĩ mbindu, o na vinya wake ndwaanyiva.'),
('kam', 'DEU', 34, 8, 'Na ana ma Isilaeli mamũĩĩa Mose ndiĩnĩ sya Moavi mĩthenya mĩongo ĩtatũ; na ĩndĩ mĩthenya ya kũĩa na kũmũmetea Mose yathela.'),
('kam', 'DEU', 34, 9, 'Na Yosua mwana wa Nuni ausũĩte veva wa ũi; nũndũ Mose nĩwamwilĩĩle moko make: na ana ma Isilaeli mamwĩthukĩĩsya, na meeka ũndũ Yeova wamwĩaĩe Mose.'),
('kam', 'DEU', 34, 10, 'Na kuma ĩvinda yĩu kũtyaokĩla nthĩnĩ wa Isilaeli mwathani ũilyĩ Mose, ũla Yeova wesene nake ũthyũ kwa ũthyũ,'),
('kam', 'DEU', 34, 11, 'ũndũ wa syama syonthe na moseng’yo onthe, ala Yeova wamũtũmie akameke nthĩ ya Misili, kwa Valao, na kwa athũkũmi make onthe, na nthĩ yake yonthe,'),
('kam', 'DEU', 34, 12, 'na ũndũ wa kw’oko kw’onthe kwĩ ũtonyi, na kũtĩsya kw’onthe kũnene, kũla Mose wekie Isilaeli onthe mene na metho moo.'),
('kam', 'JOS', 1, 1, 'Na kweethĩwa ĩtina wa Mose mũthũkũmi wa Yeova akw’a, Yeova aneena na Yosua mwana wa Nuni, mũthũkũmi wa Mose, akĩmwĩa,'),
('kam', 'JOS', 1, 2, 'Mose, mũthũkũmi wakwa, nĩ mũkw’ũ; ũkĩla ĩndĩ yu, ũinge Yolotani ũyũ, we, na andũ aa onthe, kũlika nthĩ ĩla nĩmanengae, o ana ma Isilaeli.'),
('kam', 'JOS', 1, 3, 'Kĩla vandũ ũnyaĩĩ wenyu ũkakinya, kũu nĩmũnengete, o tondũ namwĩie Mose.'),
('kam', 'JOS', 1, 4, 'Kuma weũnĩ, na vaa Levanoni, o kũvika ũla ũsĩ mũnene, o ũsĩ wa Euvalati, nthĩ yonthe ya Aititi, na kũvika ũla ũkanga mũnene welekele ũthũĩlonĩ wa syũa, ũkeethĩwa mũvaka wenyu.'),
('kam', 'JOS', 1, 5, 'Kũtikethĩwa mũndũ o na wĩva ũla ũkatonya kũũngama mbee waku mĩthenya yonthe ya thayũ waku: o tondũ neethĩawa na Mose, o ta ũu ngeethĩawa vamwe naku; ndikakũnyivĩa, o na ndikakũtia.'),
('kam', 'JOS', 1, 6, 'Ĩthĩwa na vinya na ũkũmbaũ mũnene; nũndũ ũkatuma andũ aa mosa nthĩ ĩla neevĩtĩe aaĩthe moo nĩmanenga yithĩwe ũtiĩwa.'),
('kam', 'JOS', 1, 7, 'Ĩndĩ ĩthĩwa na vinya na ũkũmbaũ mũnene, ũsũvĩe wĩke kwĩanana na mĩao yonthe, ĩla Mose mũthũkũmi wakwa wakwĩaĩe: ndũkaamyelelũkĩle kwelekela kw’oko kwa aũme kana kw’oko kwa aka, nĩ kana ũathimĩke o vala wĩthi.'),
('kam', 'JOS', 1, 8, 'Ĩvuku yĩĩ ya mĩao yĩtikaaume kanyw’anĩ waku, ĩndĩ wĩmĩsũanĩaa mũthenya na ũtukũ, nĩ kana ũsũvĩe wĩke kwĩanana na w’onthe ũla ũandĩkĩtwe nthĩnĩ wayo: nũndũ nĩvo ĩndĩ wĩaĩlya nzĩa yaku, na nĩvo wĩĩka na kĩlĩko.'),
('kam', 'JOS', 1, 9, 'Ndikwĩaĩte? Ĩthĩwa na vinya na ũkũmbaũ mũnene; ndũkaakĩe, o na ndũkaateve: nũndũ Yeova Ngai waku e vamwe naku o kũla wĩthi.'),
('kam', 'JOS', 1, 10, 'Nĩvo ĩndĩ Yosua weaĩe anene ma andũ, akĩmea,'),
('kam', 'JOS', 1, 11, 'Vĩtĩlai katĩ wa mwako wa maeema, na mũkĩaĩa andũ, mũkĩmea, Seũvyai lĩu; nũndũ katĩ wa mĩthenya ĩtatũ mũkainga Yolotani ũyũ, mũlike mũmĩmesye nthĩ, ĩla Yeova Ngai wenyu ũmũnengae mũmĩmesye.'),
('kam', 'JOS', 1, 12, 'Na Yosua aneena na Aleuveni na Angati na ĩla nyunzu ya mbaĩ ya Manase, akĩmea,'),
('kam', 'JOS', 1, 13, 'Lilikanai ndeto ĩla Mose mũthũkũmi wa Yeova wamwĩaĩe, akĩmwĩa, Yeova Ngai wenyu nũmũnengaa kũthũmũa, na akamũnenga nthĩ ĩno.'),
('kam', 'JOS', 1, 14, 'Iveti syenyu, na syana nini syenyu, na indo syenyu, ikekala nthĩ ĩla Mose wamũnengie mũingo wa Yolotani; ĩndĩ inyw’ĩ, ngũmbaũ nene syonthe, mũkavĩte mbee wa ana‐a‐ĩthe menyu mwĩkĩĩte mĩio ya kaũ, na mũkamatethye;'),
('kam', 'JOS', 1, 15, 'kũvika Yeova amanenga ana‐a‐ĩthe menyu kũthũmũa, o tondũ ũmũnengete, namo meethĩwa mamĩmeetye nthĩ ĩla Yeova Ngai wenyu ũmanengae: nĩvo ĩndĩ mwĩsyoka nthĩ ĩla ng’ũndũ yenyu, na mũimĩmesya, ĩla Mose mũthũkũmi wa Yeova wamũnengie mũingo wa Yolotani kwelekela wumĩlonĩ wa syũa.'),
('kam', 'JOS', 1, 16, 'Na masũngĩa Yosua, makĩmwĩa, Ũu w’onthe ũla ũtwĩaĩte ũkeeka, na o vala wĩtũtũma tũkathi.'),
('kam', 'JOS', 1, 17, 'O tondũ twamwĩthukĩĩasya Mose maũndũnĩ onthe, o ta ũu tũkakwĩthukĩĩasya: ĩndĩ Yeova Ngai waku nĩethĩwe naku, o tondũ wethĩawa na Mose.'),
('kam', 'JOS', 1, 18, 'O ũla wĩng’endea mĩao yaku na ailea kwĩthukĩĩsya ndeto syaku nthĩnĩ wa onthe ala wĩmwĩaĩa, nake akooawa: ĩndĩ ĩthĩwa na vinya na ũkũmbaũ mũnene.'),
('kam', 'JOS', 2, 1, 'Na Yosua mwana wa Nuni atũma andũ elĩ kuma Sitimu na kĩmbithĩ makathiane, akĩmea, Endai, mũsisye nthĩ, na Yeliko. Na mathi, na malika nyũmba ya ĩlwaya yĩla syĩtwa yayo yeetawa Laavi, na makoma vo.'),
('kam', 'JOS', 2, 2, 'Na mũsumbĩ wa Yeliko atavw’a, akĩw’a, Sisya, nĩkwalika kũũ andũ ma ana ma Isilaeli ũtukũ ũũ mathiane nthĩ.'),
('kam', 'JOS', 2, 3, 'Na mũsumbĩ wa Yeliko atũmana kwa Laavi, akĩmwĩa, Umaalya andũ ala mokie kwaku, ala malikile nyũmba kwaku; nũndũ nĩmokie mathiane nthĩ yonthe.'),
('kam', 'JOS', 2, 4, 'Na ũla mũndũ mũka oosa andũ asu elĩ, na amavitha; na asya, Ĩĩ, andũ asu nĩmokie kwakwa, ĩndĩ ndinamanya kũla maumĩte:'),
('kam', 'JOS', 2, 5, 'na kweethĩwa o ta ĩvinda ya kũvinga mbingĩlo, kwatuka, ala andũ maumaala; kũla andũ asu mathi ndyĩsĩ: maatĩĩei mĩtũkĩ; nũndũ nĩmũũmakwata.'),
('kam', 'JOS', 2, 6, 'Ĩndĩ aĩ anamatwaa kĩalanĩ ĩũlũ, na ũmavitha na ũa wa katane ũla walanĩtye kĩalanĩ.'),
('kam', 'JOS', 2, 7, 'Na andũ asu mamaatĩĩa nzĩanĩ ĩelete Yolotani kũvika masyũkonĩ: na o yĩla asu mamaatĩĩe maumaalile, mavinga mbingĩlo.'),
('kam', 'JOS', 2, 8, 'Na matanakoma, ambata vala maĩ kĩalanĩ ĩũlũ;'),
('kam', 'JOS', 2, 9, 'na eea ala andũ, Nĩnĩsĩ atĩ Yeova nũmũnengete nthĩ ĩno, na kana kũmũkĩa nĩkwatũvalũkĩĩle, na kana onthe ala mamĩtwĩe ĩ nthĩ nĩmeũnyaĩĩka mbee wenyu.'),
('kam', 'JOS', 2, 10, 'Nũndũ nĩtwĩw’ĩte ũndũ Yeova wang’alĩthisye manzĩ ma Ũkanga Mũtune mbee wenyu, yĩla mwaumie Misili; na ũla mweekie asumbĩ elĩ ma Aamoli, Sioni na Oku, ala maĩ mũingo wa Yolotani, ala mwooaie vyũ.'),
('kam', 'JOS', 2, 11, 'Na o yĩla tweewie, ngoo sitũ syatweka, o na vatyaatiwa ũnyiau mũndũnĩ o na wĩva, nũndũ wenyu: nũndũ Yeova Ngai wenyu, nĩwe Ngai ĩũlũ ĩtunĩ, na ĩtheo nthĩ.'),
('kam', 'JOS', 2, 12, 'Yu ĩndĩ, nĩngũmwĩsũva mbĩavĩei na Yeova, nĩkwĩthĩwa nĩmwĩkie nesa, inyw’ĩ nenyu mwĩmĩka nesa nyũmba ya nau, na mũkĩnenga ũvano ũla wa w’o;'),
('kam', 'JOS', 2, 13, 'na ĩngĩ kana mwĩmaeka me thayũ nau, na mwaitũ, na ana‐a‐asa, na eĩtu‐a‐asa, na onthe ala me namo, na kũtũtangĩĩa mathayũ maitũ tũtikakw’e.'),
('kam', 'JOS', 2, 14, 'Na ala andũ mamwĩa, Mathayũ maitũ vandũ va menyu, ethĩwa mũtiũweta ũndũ ũũ witũ; na kũkeethĩwa, yĩla Yeova wĩtũnenga ĩ nthĩ, tũkakwĩka nesa na w’o.'),
('kam', 'JOS', 2, 15, 'Nĩvo ĩndĩ wamatheelelye mbũthinĩ na ĩkanda: nũndũ nyũmba yake yaĩ wakonĩ wa ũvai wa ndũa, na atũĩte ũvainĩ.'),
('kam', 'JOS', 2, 16, 'Na amea, Endai kĩĩmanĩ, ala mamũatĩĩe matikamũwĩle; na ĩvithei vo matukũ atatũ, mũvaka ala mamũatĩĩe masyoka: na ĩtina wa ũu nĩmũtonya kwĩendea.'),
('kam', 'JOS', 2, 17, 'Na ala andũ mamwĩa, Ithyĩ tũkeethĩwa tũte na ĩvĩtyo wĩvĩtonĩ ũũ waku ũla watuma twĩvĩta.'),
('kam', 'JOS', 2, 18, 'Sisya, yĩla twĩlika ĩ nthĩ, nĩwĩovelela ĩkanda yĩĩ ya ũlii mũtune mbũthinĩ ĩla watũtheelelya: na wĩmombanĩsya nyũmbanĩ yaku au, na mwenyu, na ana‐a‐au, na andũ onthe ma nyũmba ya au.'),
('kam', 'JOS', 2, 19, 'Na kũkeethĩwa, o ũla wĩumaala mĩomonĩ ya nyũmba yaku athi nzĩanĩ nene, nthakame yake ĩkeethĩwa ĩũlũ wa mũtwe wake, naitũ tũkeethĩwa tũte na ĩvĩtyo: na o ũla ũkethĩwa vamwe naku nyũmbanĩ, nthakame yake ĩkeethĩwa ĩũlũ wa mĩtwe yaitũ, ethĩwa kw’oko o na kwĩva kũkeethĩwa ĩũlũ wake.'),
('kam', 'JOS', 2, 20, 'Ĩndĩ ethĩwa nũũweta ũndũ ũũ witũ, nĩvo ĩndĩ tũkethĩwa tũte na ĩvĩtyo wĩvĩtonĩ waku ũla watuma twĩvĩta.'),
('kam', 'JOS', 2, 21, 'Na amea, Nĩkwĩthĩwe kwĩanana na ndeto syenyu. Na amea mathi, namo maenda: nake ovelela ũlii mũtune mbũthinĩ.'),
('kam', 'JOS', 2, 22, 'Namo mathi, na mavika kĩĩmanĩ, na mekala vo matukũ atatũ, mũvaka ala mamaatĩĩe masyoka: na ala mamaatĩĩe mamamantha nzĩanĩ yonthe, ĩndĩ matyaamona.'),
('kam', 'JOS', 2, 23, 'Nĩvo ĩndĩ andũ asu elĩ masyokie, na matheea kuma kĩĩmanĩ, na mainga, na mavika vala Yosua mwana wa Nuni ũĩ; na mamũtavya onthe ala mamakĩtĩkĩe.'),
('kam', 'JOS', 2, 24, 'Na mamwĩa Yosua, Nĩ w’o, Yeova nĩwanenganie mokonĩ maitũ nthĩ ĩno yonthe; na mbee wa ũu onthe ala matwĩe nthĩ ĩsu nĩmeũnyaĩĩka mbee waitũ.'),
('kam', 'JOS', 3, 1, 'Na Yosua ookĩla kĩoko tene; na mauma Sitimu, na mavika Yolotani, we na ana onthe ma Isilaeli; na makoma vo matanainga.'),
('kam', 'JOS', 3, 2, 'Na kweethĩwa matukũ atatũ mathela, anene mavĩtĩla katĩ wa mwako wa maeema;'),
('kam', 'JOS', 3, 3, 'na mameaĩa andũ, makĩmea, Yĩla mwĩona ĩsandũkũ ya ũtianĩo ya Yeova Ngai wenyu, na athembi Alivai mayĩkuĩte, nĩvo ĩndĩ mwĩuma vala mũĩ, na mũkĩyĩvikĩla.'),
('kam', 'JOS', 3, 4, 'Ĩndĩ nĩveĩthĩwa ũthei katĩ wenyu nayo, o ta mĩkono ngili ilĩ kwa kũthima: mũtikayĩthengeee, nĩ kana mũtonye kũmanya nzĩa ĩla mwĩendela nayo; nũndũ mũtyaavĩtĩla nzĩanĩ ĩno ĩngĩ.'),
('kam', 'JOS', 3, 5, 'Na Yosua amea andũ, Ĩvathan’yei mwĩthĩwe atheu; nũndũ ũnĩ Yeova akeeka moseng’yo katĩ wenyu.'),
('kam', 'JOS', 3, 6, 'Na Yosua aneena na athembi, akĩmea, Ũkĩlyai ĩsandũkũ ya ũtianĩo, na mũkĩinga mbee wa andũ. Na mookĩlya ĩsandũkũ ya ũtianĩo, na maenda mbee wa andũ.'),
('kam', 'JOS', 3, 7, 'Na Yeova amwĩa Yosua, Mũnthĩ ũũ nĩngwambĩlĩlya ũkũnenevya Isilaeli onthe mene, nĩ kana mamanye, o tondũ naĩ vamwe na Mose, o ta ũu ngeethĩawa vamwe naku.'),
('kam', 'JOS', 3, 8, 'Naku ũkameaĩe athembi ala makuaa ĩsandũkũ ya ũtianĩo, ũkĩmea, Yĩla mwĩvika ũtee wa manzĩ ma Yolotani, nĩmwĩũngama ki Yolotani.'),
('kam', 'JOS', 3, 9, 'Na Yosua amea ana ma Isilaeli, Thengeeai, mwĩw’e ndeto sya Yeova Ngai wenyu.'),
('kam', 'JOS', 3, 10, 'Na Yosua amea, Kwondũ wa ũu mũkamanya atĩ Ngai ũla wĩ thayũ e katĩ wenyu, na kana nde ndĩi ya ũlea ũlũngya mbee wenyu Mũkanaani, na Mũititi, na Mũivi, na Mũvelisi, na Mũngilikasi, na Mũamoli, na Mũyevusi.'),
('kam', 'JOS', 3, 11, 'Sisyai, ĩsandũkũ ya ũtianĩo ya Mwĩaĩi wa nthĩ yonthe nĩyĩũvĩtĩla mbee wenyu kũlika Yolotani.'),
('kam', 'JOS', 3, 12, 'Kwondũ wa ũu ĩndĩ osai andũ ĩkũmi na elĩ kuma mbaĩnĩ sya Isilaeli, kĩla mbaĩ mũndũ ũmwe.'),
('kam', 'JOS', 3, 13, 'Na kũkeethĩwa, yĩla nyaĩĩ sya athembi ala makuaa yĩla ĩsandũkũ ya Yeova, Mwĩaĩi wa nthĩ yonthe, syĩkinya nthĩ manzĩnĩ ma Yolotani, manzĩ ma Yolotani makavingĩwa, o manzĩ ala matheeaa kuma ĩũlũ; na makaũngama kĩvumbu kĩmwe.'),
('kam', 'JOS', 3, 14, 'Na kweethĩwa, yĩla andũ maumie maeemanĩ moo mainge Yolotani, athembi ala makuaa ĩsandũkũ ya ũtianĩo meethĩawa makĩtongoesya andũ;'),
('kam', 'JOS', 3, 15, 'na yĩla asu makuaa yĩla ĩsandũkũ maĩ manavika Yolotani, na maũũ na athembi ala makuaa yĩla ĩsandũkũ malika manzĩnĩ ũtee (nũndũ Yolotani nũvingaa ũkakĩla ngũka syonthe ĩvinda yonthe ya ngetha),'),
('kam', 'JOS', 3, 16, 'nĩw’o manzĩ ala matheeaa kuma ĩũlũ maũngamie, na mookĩla kĩvumbu kĩmwe, me kũasa, ku Atamu, ndũa ĩla yĩ vakuvĩ na Nzalethani; na asu ala matheeaa kwelekela ũkanga wĩ ku Alava, ũla Ũkanga wa Mũnyũ, mathi vyũ; na andũ asu mainga melekele Yeliko.'),
('kam', 'JOS', 3, 17, 'Na athembi ala makuaa ĩsandũkũ ya ũtianĩo ya Yeova maũngama ki nthĩ nyũmũ Yolotani katĩ; na Isilaeli onthe mainga makinyĩle nthĩ nyũmũ, mũvaka mbaĩ ĩsu yonthe yainga Yolotani vyũ.'),
('kam', 'JOS', 4, 1, 'Na kweethĩwa, yĩla mbaĩ yonthe yaminie kũinga Yolotani vyũ, Yeova aneena na Yosua, akĩmwĩa,'),
('kam', 'JOS', 4, 2, 'Osa andũ ĩkũmi na elĩ kuma andũnĩ, kuma kĩla mbaĩ mũndũ ũmwe,'),
('kam', 'JOS', 4, 3, 'na ũimeaĩa, ũkĩmea, Osai mavia ĩkũmi na elĩ Yolotani katĩ, kuma vandũ vala maũũ ma athembi maũngamĩte ki, nenyu mũimakua, na mũkamaie vandũ vala mwĩkoma, o vala mwĩkoma ũtukũ ũũ.'),
('kam', 'JOS', 4, 4, 'Nĩvo ĩndĩ Yosua wametie andũ asu ĩkũmi na elĩ, ala waiie ma ana ma Isilaeli, kuma kĩla mbaĩ mũndũ ũmwe:'),
('kam', 'JOS', 4, 5, 'na Yosua amea, Vĩtĩlai mbee wa yĩla ĩsandũkũ ya Yeova mũlike Yolotani katĩ, na kĩla mũndũ wenyu ose ĩvia mwilĩĩle kĩtuo, o kwĩanana na ũtalo wa mbaĩ sya ana ma Isilaeli;'),
('kam', 'JOS', 4, 6, 'nĩ kana ũu wĩthĩwe wonan’yo katĩ wenyu, kana, yĩla syana syenyu ikakũlya ĩvinda yĩla yĩkoka, ikyasya, Mwĩonan’ya ata na mavia aa?'),
('kam', 'JOS', 4, 7, 'Nĩvo mwĩsyĩa, Nũndũ manzĩ ma Yolotani nĩmavingĩiwe mbee wa ĩsandũkũ ya ũtianĩo ya Yeova; yĩla yaingie Yolotani, manzĩ ma Yolotani nĩmavĩngĩiwe: na mavia aa makeethĩwa ũlilikan’yo kwa ana ma Isilaeli tene na tene.'),
('kam', 'JOS', 4, 8, 'Na ana ma Isilaeli meeka o tondũ Yosua weaie, na moosa mavia ĩkũmi na elĩ kuma Yolotani katĩ, o kwĩanana na ũtalo wa mbaĩ sya ana ma Isilaeli, o tondũ Yeova wamũtavisye Yosua; na mamakua kũvika vandũ vala makomie, na mamaia nthĩ vo.'),
('kam', 'JOS', 4, 9, 'Na Yosua aũngamya mavia ĩkũmi na elĩ Yolotani katĩ, vandũ vala maũũ ma athembi ala makuaa ĩsandũkũ ya ũtianĩo maũngamĩte: na nĩvo maĩ kũvika mũnthĩ ũũ.'),
('kam', 'JOS', 4, 10, 'Nũndũ athembi ala makuaa yĩla ĩsandũkũ maũngamĩte Yolotani katĩ, kũvika maũndũ onthe mathela ala Yeova weaĩe Yosua amatavye andũ, o kwĩanana na onthe ala Mose weaie Yosua: na andũ meekalaata na mainga.'),
('kam', 'JOS', 4, 11, 'Na kweethĩwa, yĩla andũ onthe maingie vyũ, nayo ĩsandũkũ ya Yeova yainga, na athembi, andũ mene.'),
('kam', 'JOS', 4, 12, 'Na ana ma Leuveni, na ana ma Ngati, na nyunzu ya mbaĩ ya Manase, mainga mbee wa ana ma Isilaeli mekĩĩte mĩio ya kaũ, o tondũ Mose wamatavisye:'),
('kam', 'JOS', 4, 13, 'mainga o ta ngili mĩongo ĩna Yeova asyaĩtye mekĩĩte mĩio ya kaũ, kũvika ndiĩnĩ sya Yeliko, nĩ kana mokite.'),
('kam', 'JOS', 4, 14, 'Mũthenya ũsu Yeova anenevya Yosua methonĩ ma Isilaeli onthe: na mamũkĩa mĩthenya yonthe ya thayũ wake, o tondũ makĩĩte Mose.'),
('kam', 'JOS', 4, 15, 'Na Yeova aneena na Yosua, akĩmwĩa,'),
('kam', 'JOS', 4, 16, 'Ĩaĩe athembi ala makuaa ĩsandũkũ ya ũkũsĩ maume Yolotani.'),
('kam', 'JOS', 4, 17, 'Kwondũ wa ũu Yosua ameaĩa athembi, akĩmea, Umai Yolotani.'),
('kam', 'JOS', 4, 18, 'Na kweethĩwa, yĩla athembi ala makuaa ĩsandũkũ ya ũtianĩo ya Yeova mauma Yolotani katĩ, na nyaĩĩ sya athembi syookĩlw’a syakinya nthĩ nyũmũ, manzĩ ma Yolotani masyoka vandũ vamo, na makĩla ngũka syonthe syamo, o ta tene.'),
('kam', 'JOS', 4, 19, 'Na andũ asu mauma Yolotani mũthenya wa ĩkũmi mwei wa mbee, na mamba maeema Ngilikali, mũvakanĩ wa Yeliko ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JOS', 4, 20, 'Na mavia asu ĩkũmi na elĩ, ala maumisye Yolotani, Yosua amaũngamya Ngilikali.'),
('kam', 'JOS', 4, 21, 'Na aneena na ana ma Isilaeli, akĩmea, Yĩla syana syenyu ikamakũlya aaĩthe masyo ĩvinda yĩla yĩkoka, ikĩmea, Mavia aa nĩ ma kĩ?'),
('kam', 'JOS', 4, 22, 'Nĩvo mwĩmanyĩthya syana syenyu, mũkĩsyĩa, Isilaeli nĩmaingie Yolotani ũyũ makinyĩle nthĩ nyũmũ.'),
('kam', 'JOS', 4, 23, 'Nũndũ Yeova Ngai wenyu nĩwang’alĩthisye manzĩ ma Yolotani mbee wenyu, kũvika mwainga, o tondũ Yeova Ngai wenyu wekie Ũkanga Mũtune, ũla wang’alĩthisye mbee waitũ, kũvika twainga;'),
('kam', 'JOS', 4, 24, 'nĩ kana andũ onthe ma nthĩ mamanye kw’oko kwa Yeova, atĩ kwĩ na vinya mũno; nĩ kana mũkĩe Yeova Ngai wenyu tene na tene.'),
('kam', 'JOS', 5, 1, 'Na kweethĩwa, yĩla asumbĩ onthe ma Aamoli, ala maĩ mũingo wa Yolotani kwelekela ũthũĩlonĩ wa syũa, na asumbĩ onthe ma Akanaani, ala maĩ ũtee wa ũkanga, meewie ũndũ Yeova wang’alĩthisye manzĩ ma Yolotani mbee wa ana ma Isilaeli, kũvika twainga, ngoo syoo syatweka, o na kũtyaĩ ũnyiau nthĩnĩ wamo ĩngĩ, kwondũ wa ana ma Isilaeli.'),
('kam', 'JOS', 5, 2, 'Ĩvinda yĩu Yeova amwĩa Yosua, Ĩseũvĩsye tũvyũ twa ĩvia yũmũ, waĩke ana ma Isilaeli ĩngĩ ĩvinda ya kelĩ.'),
('kam', 'JOS', 5, 3, 'Na Yosua eeseũvĩsya tũvyũ twa ĩvia yũmũ, na amaĩkĩa ana ma Isilaeli Kĩĩmanĩ kya Nzaĩko.'),
('kam', 'JOS', 5, 4, 'Na kĩtumi nĩ kĩĩ kya Yosua kũmaĩka: andũ onthe ala maumie Misili, ala andũ, o andũ onthe ma kaũ, nĩmakw’ĩĩe weũnĩ me nzĩanĩ, ĩtina wa mauma Misili.'),
('kam', 'JOS', 5, 5, 'Nũndũ andũ onthe ala maumie Misili maĩ aĩke; ĩndĩ andũ onthe ala masyaĩwe weũnĩ me nzĩanĩ makyuma Misili, matyamaĩkĩte.'),
('kam', 'JOS', 5, 6, 'Nũndũ ana ma Isilaeli mangangaa myaka mĩongo ĩna weũnĩ, kũvika mbaĩ yonthe, o asu andũ ma kaũ ala maumie Misili, mathela, nĩkwĩthĩwa matyaaĩthukĩĩsya wasya wa Yeova: o ala Yeova wamevĩtĩe atĩ ndakamanenga ũthei wa kwona nthĩ ĩla Yeova wamevĩtĩe aaĩthe moo ũmanenga, nthĩ yũsũĩte ĩia na ũkĩ wa nzũkĩ.'),
('kam', 'JOS', 5, 7, 'Na syana syoo, ila wokĩlilye vandũ voo, nĩsyo Yosua waĩkie: nũndũ ityaĩ mbaĩke, nĩkwĩthĩwa matyaasyaĩka me nzĩanĩ.'),
('kam', 'JOS', 5, 8, 'Na kweethĩwa, yĩla maminie kwaĩka mbaĩ yonthe, mekalile vandũ voo mwakonĩ wa maeema, kũvika mavoa.'),
('kam', 'JOS', 5, 9, 'Na Yeova amwĩa Yosua, Mũthenya ũũ nĩnaveta nthoni sya Misili syume kwenyu. Kwondũ wa ũu syĩtwa ya vandũ vau veetwa Ngilikali, kũvika ũmũnthĩ.'),
('kam', 'JOS', 5, 10, 'Na ana ma Isilaeli mamba maeema Ngilikali; na malilikana vasaka mũthenya wa ĩkũmi na ĩna wa mwei wĩoo me ndiĩnĩ sya Yeliko.'),
('kam', 'JOS', 5, 11, 'Na ũnĩ ũsu wa vasaka maya ũsyao wa nthĩ ĩsu, tũmũtũ tũte ĩlawa na lĩu wa mbaa ngetha mũkaange, o mũthenya ũsu.'),
('kam', 'JOS', 5, 12, 'Na ũla lĩu wĩtawa mana waeka kwoneka ũnĩ ũsu, o yĩla maĩe ũsyao wa nthĩ ĩsu; o na ana ma Isilaeli matyaaĩthĩwa na ũla lĩu wĩtawa mana ĩngĩ; ĩndĩ maĩsaa ũsyao wa nthĩ ya Kanaani mwaka ũsu.'),
('kam', 'JOS', 5, 13, 'Na kweethĩwa, yĩla Yosua waĩ vakuvĩ na Yeliko, ookĩlya metho make na oona, na, sisya, kwaũngamĩte mũndũ amwelekele akũĩte ũvyũ wake wĩ kw’okonĩ kwake: na Yosua amũendea na amũkũlya, Wĩ ngalĩ yaitũ, kana ngalĩ ya nthũ sitũ?'),
('kam', 'JOS', 5, 14, 'Na asya, Aiee: ĩndĩ nyie yu nĩnooka ũla mũnene wa nguthu ya Yeova. Na Yosua avalũka nthĩ na ũthyũ wake, na athaitha, na amũkũlya, Mwĩaĩi wakwa emwĩa mũthũkũmi wake ata?'),
('kam', 'JOS', 5, 15, 'Na mũnene wa nguthu ya Yeova amwĩa Yosua, Umya iatũ syaku maũũnĩ maku; nũndũ vandũ vala ũngamĩte nĩ vatheu. Na Yosua eeka ũu.'),
('kam', 'JOS', 6, 1, 'Na ĩndĩ Yeliko yaĩ mbinge ki kwondũ wa ana ma Isilaeli: vatyaĩ waaumaala, na vatyaĩ waalika.'),
('kam', 'JOS', 6, 2, 'Na Yeova amwĩa Yosua, Sisya, nĩnĩnenganĩte Yeliko, na mũsumbĩ wayo, na ngũmbaũ nene, kw’okonĩ kwaku.'),
('kam', 'JOS', 6, 3, 'Nenyu mũkathyũlũlũke ndũa, o andũ onthe ma kaũ, mũkĩthyũlũlũka ndũa ĩmwe. Wĩke ũu mĩthenya thanthatũ.'),
('kam', 'JOS', 6, 4, 'Na athembi mũonza makakue masoo mũonza ma mbya sya ndũũme me mbee wa yĩla ĩsandũkũ: na mũthenya wa mũonza mũkathyũlũlũke ĩla ndũa mathyũlũlũka mũonza, na athembi makavuve masoo.'),
('kam', 'JOS', 6, 5, 'Na kũkeethĩwa, yĩla mevuva mbya sya ndũũme ĩvuva yĩasa, na yĩla mwĩw’a wasya wa soo, andũ onthe nĩmakokĩlye mawasya mũno mũnene; na ũvai wa ndũa ũkavalũka mbu, na andũ makambata kĩla mũndũ aeleele kuma vala eĩĩ.'),
('kam', 'JOS', 6, 6, 'Na Yosua mwana wa Nuni eeta athembi, na amea, Ukĩlyai ĩsandũkũ ya ũtianĩo, na athembi mũonza nĩmakue masoo mũonza ma mbya sya ndũũme me mbee wa yĩla ĩsandũkũ ya Yeova.'),
('kam', 'JOS', 6, 7, 'Na mamea andũ, Vĩtai, mũthyũlũlũke ĩla ndũa, na ala andũ mekĩĩte mĩio ya kaũ nĩmavĩte mbee wa yĩla ĩsandũkũ ya Yeova.'),
('kam', 'JOS', 6, 8, 'Na kweethĩwa, yĩla Yosua waĩ ananeena na andũ, ala athembi mũonza makuĩte masoo mũonza ma mbya sya ndũũme me mbee wa Yeova maenda mbee, na mavuva masoo: na ĩsandũkũ ya ũtianĩo ya Yeova yamaatĩĩa.'),
('kam', 'JOS', 6, 9, 'Na ala andũ mekĩĩte mĩio ya kaũ maenda mbee wa athembi ala mavuvaa masoo, na ala ma ĩtina maatĩĩa yĩla ĩsandũkũ, athembi makĩvuva masoo maendete.'),
('kam', 'JOS', 6, 10, 'Na Yosua ameaĩa andũ, akĩmea, Mũtikokĩlye mawasya, o na mawasya menyu matikew’ĩke, o na ndeto o na yĩva ndĩkaume makanyw’anĩ menyu, kũvika mũthenya ũla nĩmwĩaĩa mũkĩlye mawasya: nĩvo ĩndĩ mwĩũkĩlya mawasya.'),
('kam', 'JOS', 6, 11, 'Na ĩndĩ atuma ĩsandũkũ ya Yeova yĩthyũlũlũkw’a ndũa, ĩthyũlũlũka yĩmwe: na masyoka mwakonĩ wa maeema, na makoma mwakonĩ wa maeema.'),
('kam', 'JOS', 6, 12, 'Na Yosua ookĩla kĩoko tene na ala athembi mookĩlya yĩla ĩsandũkũ ya Yeova.'),
('kam', 'JOS', 6, 13, 'Na athembi mũonza ala makuĩte masoo mũonza ma mbya sya ndũũme me mbee wa ĩsandũkũ ya Yeova maendeeaa matekũũngama, na makĩvuva masoo: na ala andũ mekĩĩte mĩio ya kaũ mamatongoesya; na ala ma ĩtina maatĩĩa yĩla ĩsandũkũ ya Yeova, athembi makĩvuva masoo maendete.'),
('kam', 'JOS', 6, 14, 'Na mũthenya wa kelĩ mathyũlũlũka ndũa ĩmwe, na masyoka mwakonĩ wa maeema: meekie o ta ũu mĩthenya thanthatũ.'),
('kam', 'JOS', 6, 15, 'Na kweethĩwa mũthenya wa mũonza, mookĩla tene w’oa ũitema, na mathyũlũlũka ndũa o ta ũu mathyũlũlũka mũonza: ate o mũthenya ũsu mathyũlũlũkile ndũa mathyũlũlũka mũonza.'),
('kam', 'JOS', 6, 16, 'Na kweethĩwa ĩthyũlũlũka ya mũonza, yĩla athembi mavuvaa masoo, Yosua amea andũ, Usyai ngemi; nũndũ Yeova nũmũnengete ndũa ĩno.'),
('kam', 'JOS', 6, 17, 'Na ndũa ĩkeethĩwa ĩvathĩtwe kwa Yeova, o yo na syonthe ĩla syĩ nthĩnĩ: ate o Laavi yĩla ĩlwaya wĩekwa e thayũ, we na onthe ala me nake nyũmbanĩ, nĩkwĩthĩwa nĩwavithie atũmwa ala twatũmie.'),
('kam', 'JOS', 6, 18, 'Ĩndĩ inyw’ĩ ngalĩ ĩ yenyu, ĩsũvĩĩei na kĩndũ kĩla kĩvathĩtwe, nĩ kana, mwamina kũkĩvatha, mũtikese kwosa kĩla kĩvathe; na kwondũ wa ũu mũkĩtw’ĩkĩthya mwako wa maeema wa Isilaeli mũumanĩe, na mũkyũthĩn’ya.'),
('kam', 'JOS', 6, 19, 'Ĩndĩ vetha w’onthe, na thaavu, na mĩio ya ũthuku na ya kĩaa, nĩ ntheu kwa Yeova: ikaetwe vala vaiawa ũthwii va Yeova.'),
('kam', 'JOS', 6, 20, 'Na ĩndĩ andũ mookĩlya mawasya, na athembi mavuva masoo: na kweethĩwa, yĩla andũ meewie wasya wa soo, andũ mookĩlya mawasya mũno mũnene, na ũvai wavalũka mbu, ũndũ andũ malika ndũanĩ, kĩla mũndũ aelele kuma vala eĩĩ, na makwata ndũa.'),
('kam', 'JOS', 6, 21, 'Na maananga vyũ syonthe ila syaĩ ndũanĩ, mũndũ mũũme o na mũndũ mũka, me ma mũika o na ala akũũ, na ng’ombe, na ĩlondu, na ĩng’oi, kwa kũtemanga na ũvyũ.'),
('kam', 'JOS', 6, 22, 'Na Yosua atavya andũ elĩ ala mathianie nthĩ, Likai nyũmbanĩ ya yĩla ĩlwaya, na mũimumya vu mũndũ mũka ũsu, na syonthe ila wĩ nasyo, o tondũ mwamwĩvĩtĩe.'),
('kam', 'JOS', 6, 23, 'Na ala anake athiani malika, na mamumaalya Laavi, na ĩthe wake, na inyia wake, na ana‐a‐ĩthe, na syonthe ila waĩ nasyo; o na andũ onthe ma mũvĩa wake mamaumaalya; na mamaia ũtee wa mwako wa maeema wa Isilaeli.'),
('kam', 'JOS', 6, 24, 'Na mamĩvĩvya ndũa na mwaki, na syonthe ila syaĩ nthĩnĩ; ate o vetha, na thaavu, na mĩio ya ũthuku na ya kĩaa, meekĩie vala vaiawa ũthwii va nyũmba ya Yeova.'),
('kam', 'JOS', 6, 25, 'Ĩndĩ Yosua amaeka me thayũ Laavi yĩla ĩlwaya, na andũ ma nyũmba ya ĩthe wake, na syonthe ila waĩ nasyo; nake atũaa katĩ wa Isilaeli kũvika ũmũnthĩ, nĩkwĩthĩwa avithie atũmwa, ala Yosua watũmie mathiane Yeliko.'),
('kam', 'JOS', 6, 26, 'Na Yosua ameaĩa na wĩvĩto ĩvinda yĩu, akĩmea, Naumanĩwe kũla kwĩ Yeova mũndũ ũla wĩũkĩla na kwaka ndũa ĩno Yeliko: akĩkwatya wambĩlĩlyo wayo akakw’ĩĩwa nĩ ĩkithathi yake, na akĩũngamya mbingĩlo syayo akakw’ĩĩwa nĩ ĩlumaita yake ya mũndũ mũũme.'),
('kam', 'JOS', 6, 27, 'Na ĩndĩ Yeova aĩ vamwe na Yosua; na nguma yake yaĩ nthĩ ĩsu yonthe.'),
('kam', 'JOS', 7, 1, 'Ĩndĩ ana ma Isilaeli mavĩtya kĩndũnĩ kĩvathĩtwe; nũndũ Akani, mwana wa Kalimi, mwana wa Nzaveti, mwana wa Nzela, wa mbaĩ ya Yuta, oosa kĩndũ kĩla kĩvathe: na ũthatu wa Yeova wamakanĩa ana ma Isilaeli.'),
('kam', 'JOS', 7, 2, 'Na Yosua atũma andũ kuma Yeliko mathi Ai, ĩla yĩ ũtee wa Mbethi‐aveni, ngalĩ ya wumĩlonĩ wa syũa ya Mbethi‐eli, na aneena namo, akĩmea, Ambatai mũthiane nthĩ. Na ala andũ mambata na mathiana Ai.'),
('kam', 'JOS', 7, 3, 'Na mamũsyokea Yosua, na mamwĩa, Andũ onthe matikambate; ĩndĩ andũ ta ngili ilĩ kana itatũ nĩmambate makũne Ai; ndũkatũme andũ onthe mathĩnĩe wĩa wa kũthi vo; nũndũ asu no avũthũ.'),
('kam', 'JOS', 7, 4, 'Na ĩndĩ mambata vo andũ ta ngili itatũ; namo makũkie makĩĩte andũ ma Ai.'),
('kam', 'JOS', 7, 5, 'Na andũ ma Ai mooaa ta andũ mĩongo ĩtatũ na thanthatũ katĩ woo; na mamalũngya kuma mbingĩlonĩ o na kũvika Sevalimu, na mamoaĩa kĩtheeonĩ: na ngoo sya andũ syatweka, na syeethĩwa ta manzĩ.'),
('kam', 'JOS', 7, 6, 'Na Yosua atembũa ngũa syake, na avalũka nthĩ na ũthyũ wake mbee wa yĩla ĩsandũkũ ya Yeova kũvika wĩoo, we na atumĩa ma Isilaeli; na meekĩa kĩtoo mĩtwenĩ yoo.'),
('kam', 'JOS', 7, 7, 'Na Yosua asya, Ĩiaa! Ame Mwĩaĩi Yeova, waingisye andũ aa Yolotani ũndũ wa kĩ we, ũtũnengane kw’okonĩ kwa Aamoli, ũtwanange? Nenda kethĩwa tweanĩwe nĩ kwĩkala mũingo wa Yolotani!'),
('kam', 'JOS', 7, 8, 'Ame Mwĩaĩi, nĩasya ata, Isilaeli mamina kwon’ya amaitha moo mĩongo!'),
('kam', 'JOS', 7, 9, 'Nũndũ Akanaani na onthe ala matwĩe nthĩ ĩno makawĩw’a, na makatũthyũlũlũka, na kũveta syĩtwa yitũ yume nthĩ: na ũkeeka ata kwondũ wa syĩtwa yaku ĩnene?'),
('kam', 'JOS', 7, 10, 'Na Yeova amwĩa Yosua, Ũkĩla we; ũvalũkĩte ũu na ũthyũ waku nĩkĩ?'),
('kam', 'JOS', 7, 11, 'Isilaeli nĩmavĩtĩtye; ĩĩ, o na nĩmavĩtĩtye ũtianĩo wakwa ũla nameaĩie: ĩĩ, o na nĩmosete kĩndũ kĩvathĩtwe, na ĩngĩ nĩmoyĩte, o na kũkengana; o na nĩmakiĩte mĩionĩ yoo ene.'),
('kam', 'JOS', 7, 12, 'Kwondũ wa ũu ana ma Isilaeli matitonya kũũngama mbee wa amaitha moo; nĩmonetye amaitha moo mĩongo, nĩkwĩthĩwa nĩmaumanĩwa: ndikethĩwa vamwe nenyu ĩngĩ, ate o mwaananga kĩla kĩndũ kĩvathĩtwe kyume katĩ wenyu.'),
('kam', 'JOS', 7, 13, 'Ũkĩla, ũvathan’ye andũ methĩwe atheu, na ũimea, Ĩvathan’yei kwondũ wa ũnĩ: nũndũ ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Ve kĩndũ kĩvathĩtwe katĩ waku, we Isilaeli; ndũtonya kũũngama mbee wa amaitha maku, kũvika yĩla mwĩveta kĩla kĩndũ kĩvathĩtwe kyume katĩ wenyu.'),
('kam', 'JOS', 7, 14, 'Kwondũ wa ũu kĩoko mũkathengeew’a mbaĩ na mbaĩ: na kũkeethĩwa, mbaĩ ĩla Yeova wĩosa ĩkathengeea mũvĩa na mũvĩa; na mũvĩa ũla Yeova wĩosa ũkathengeea nyũmba na nyũmba; na nyũmba ĩla Yeova wĩosa ĩkathengeea mũndũ na mũndũ.'),
('kam', 'JOS', 7, 15, 'Na kũkeethĩwa, ũsu ũla wĩkwatwa e na kĩla kĩndũ kĩvathĩtwe akavĩvw’a na mwaki, we na syonthe ila wĩ nasyo; nĩkwĩthĩwa nũvĩtĩtye ũtianĩo wa Yeova, na nĩkwĩthĩwa nĩwĩkĩte ũtumanu nthĩnĩ wa Isilaeli.'),
('kam', 'JOS', 7, 16, 'Kwondũ wa ũu Yosua ookĩla kĩoko tene, na athengeesya Isilaeli mbaĩ na mbaĩ; na mbaĩ ya Yuta yooswa:'),
('kam', 'JOS', 7, 17, 'na athengeesya mũvĩa wa Yuta; na oosa mũvĩa wa Anzela: na athengeesya mũvĩa wa Anzela mũndũ na mũndũ; na Nzaveti ooswa:'),
('kam', 'JOS', 7, 18, 'na athengeesya nyũmba yake mũndũ na mũndũ; na Akani, mwana wa Kalimi, mwana wa Nzaveti, mwana wa Nzela, wa mbaĩ ya Yuta, ooswa.'),
('kam', 'JOS', 7, 19, 'Na Yosua amwĩa Akani, Mwana wakwa, nĩngũkwĩsũva, ũnenge Yeova, Ngai wa Isilaeli, ndaĩa, na ũimumbũlĩla; na ndavya yu ũla wĩkĩte; ndũkambithe.'),
('kam', 'JOS', 7, 20, 'Na Akani asũngĩa Yosua, na amwĩa, Nĩ w’o nĩnĩmũvĩtanĩsye Yeova, Ngai wa Isilaeli, na nĩkĩte ũũ na ũũ:'),
('kam', 'JOS', 7, 21, 'yĩla nĩnoonie mũtavonĩ suka mũseo wa Mbaviloni, na sekeli maana elĩ ma vetha, na kĩlungu kya thaavu kya sekeli mĩongo ĩtano, nĩvo ĩndĩ nĩnasyĩw’ĩe ĩtomo, na nĩnasyosa; na, sisya, nivithĩtwe nthĩ ĩeemanĩ yakwa katĩ, na ũla vetha ungu wasyo.'),
('kam', 'JOS', 7, 22, 'Na ĩndĩ Yosua atũma atũmwa, na masemba ĩeemanĩ; na, sisya, syaĩ mbithe ĩeemanĩ yake, na ũla vetha ungu wasyo.'),
('kam', 'JOS', 7, 23, 'Na masyosa kuma ĩeemanĩ katĩ, na maitwaĩa Yosua, na ana onthe ma Isilaeli; namo masia mbee wa Yeova.'),
('kam', 'JOS', 7, 24, 'Na Yosua, na Isilaeli onthe vamwe nake, moosa Akani mwana wa Nzela, na ũla vetha, na ũla suka, na kĩla kĩlungu kya thaavu, na ana make, na eĩtu make, na ng’ombe syake, na mang’oi make, na malondu make, na ĩeema yake, na syonthe ila waĩ nasyo: na mamaete vu mwandanĩ wa Akoli.'),
('kam', 'JOS', 7, 25, 'Na Yosua akũlya, Ũtũthĩnĩtye nĩkĩ? Yeova nũnũũkũthĩn’ya mũthenya ũũ. Na Isilaeli onthe mamũkimanga na mavia; na mamavĩvya na mwaki, na kũmakimanga na mavia.'),
('kam', 'JOS', 7, 26, 'Na moomba ĩũlũ wake mbumbu nene ya mavia, kũvika ũmũnthĩ; na Yeova aeka wai wa ũthatu wake. Kwondũ wa ũu syĩtwa ya vandũ vau yeetwa, Mwanda wa Akoli, kũvika ũmũnthĩ.'),
('kam', 'JOS', 8, 1, 'Na Yeova amwĩa Yosua, Ndũkakĩe, o na ndũkateve: osa andũ onthe ma kaũ, na ũiũkĩla, wambate Ai; sisya, nĩnĩnenganĩte kw’okonĩ kwaku mũsumbĩ wa Ai, na andũ make, na ndũa yake, na nthĩ yake;'),
('kam', 'JOS', 8, 2, 'na ũkeke Ai na mũsumbĩ wayo o tondũ weekie Yeliko na mũsumbĩ wayo: ate o mũtavo wayo, o na indo syayo, mũkose syĩthĩwe mũtavo kwenyu: ĩyiĩe ala ma kwoveesya ndũa mbĩlĩlo wayo.'),
('kam', 'JOS', 8, 3, 'Na ĩndĩ Yosua ookĩla, na andũ onthe ma kaũ, mambate Ai: na Yosua anyuva andũ ngili mĩongo ĩtatũ, ila ngũmbaũ nene, na amatũma mathi ũtukũ.'),
('kam', 'JOS', 8, 4, 'Na ameaĩa, akĩmea, Sisyai, mũkoveesye ndũa, mwĩ mbĩlĩlo wa ĩ ndũa; mũtikathi kũasa mũno na ndũa, ĩndĩ ĩthĩwai mwĩyũmbanĩtye inyw’onthe:'),
('kam', 'JOS', 8, 5, 'nakwa, na andũ onthe ala me vamwe nakwa, tũkathengeea ĩla ndũa. Na kũkeethĩwa, yĩla meũtumaalĩla, o ta yĩ ya mbee, tũkakũka mbee woo;'),
('kam', 'JOS', 8, 6, 'namo makaumaala matũatĩĩe, mũvaka twamakusya kuma ndũanĩ; nũndũ makasya, Nĩmeũtũkĩa, o ta yĩla ya mbee: na ĩndĩ tũkakĩa mbee woo;'),
('kam', 'JOS', 8, 7, 'nenyu mũkokĩle kuma kũla mwoveesye, na mũikwata ndũa yĩthĩwe yenyu: nũndũ Yeova Ngai wenyu akamĩnengane mokonĩ menyu.'),
('kam', 'JOS', 8, 8, 'Na kũkeethĩwa, yĩla mwĩmĩkwata ndũa, mwĩmĩkwatya ndũa mwaki; mũkeke kwĩanana na ndeto ya Yeova: sisyai, nĩnamwĩaĩa.'),
('kam', 'JOS', 8, 9, 'Na Yosua amatũma mathi; na maenda kũla kwa kwoveesya, na mekala katĩ wa Mbethi‐eli na Ai, ngalĩ ya Ai ya ũthũĩlonĩ wa syũa: ĩndĩ Yosua akoma ũtukũ ũsu andũnĩ.'),
('kam', 'JOS', 8, 10, 'Na Yosua ookĩla kĩoko kwĩ masangya, na atala andũ, na ambata Ai, we na atumĩa ma Isilaeli, mbee wa andũ.'),
('kam', 'JOS', 8, 11, 'Na andũ onthe, o andũ ma kaũ ala maĩ nake, mambata, na mathengeea, na mavika mbee wa ĩla ndũa ya Ai, na mamba maeema ngali ya ĩũlũ: na ĩndĩ kwaĩ kyanda katĩ wake na Ai.'),
('kam', 'JOS', 8, 12, 'Na oosa andũ ta ngili itano, na amaia moveesye katĩ wa Mbethi‐eli na Ai, ngalĩ ya ndũa ya ũthũĩlonĩ wa syũa.'),
('kam', 'JOS', 8, 13, 'Na ĩndĩ maia andũ, o nguthu yonthe ĩla yaĩ ngalĩ ya ĩũlũ ya ndũa, na oveesya moo ala maĩ ngalĩ ya ndũa ya ũthũĩlonĩ wa syũa; na Yosua aenda ũtukũ ũsu kyandanĩ katĩ.'),
('kam', 'JOS', 8, 14, 'Na kweethĩwa, yĩla mũsumbĩ wa Ai wonie ũu, mookĩla na mĩtũkĩ kĩoko tene, na andũ ma ĩla ndũa maumaalĩla Isilaeli mokite namo, we na andũ make onthe, kwelekela Alava, vandũ vatw’ĩĩtwe; ĩndĩ ndaamanya kana kwaĩ ala mamwoveesye mbĩlĩlo wa ndũa.'),
('kam', 'JOS', 8, 15, 'Na Yosua na Isilaeli onthe meeka mbee woo ta makĩlw’a vinya, na makũka na nzĩa ya weũnĩ.'),
('kam', 'JOS', 8, 16, 'Na andũ onthe ala maĩ ndũanĩ meetwa mombane nĩ kana mamaatĩĩe: na mamũatĩĩa Yosua, na makusw’a matia ndũa.'),
('kam', 'JOS', 8, 17, 'Na kũtyaĩ mũndũ mũũme watialile Ai kana Mbethi‐eli, ũla ũtaaumaala aatĩĩe Isilaeli: na matia ndũa yĩ mbingũe, na maatĩĩa Isilaeli.'),
('kam', 'JOS', 8, 18, 'Na Yeova amwĩa Yosua, Tambũũkya katumo kala ke kw’okonĩ kwaku kelekele Ai; nũndũ nĩngũmĩnengane kw’okonĩ kwaku. Na Yosua atambũũkya katumo kala kaĩ kw’okonĩ kwake kelekele ĩla ndũa.'),
('kam', 'JOS', 8, 19, 'Na ala oveesya mookĩla mĩtũkĩ kuma vala maĩ, na o yĩla watambũũkisye kw’oko kwake masemba, na malika ndũanĩ, na mamĩkwata; na meekalaata na makwatya ndũa mwaki.'),
('kam', 'JOS', 8, 20, 'Na yĩla andũ ma Ai masyaisye ĩtina woo, moona, na, sisya, syũki ya ĩla ndũa yambata ĩtunĩ, na matyaĩ na vinya wa kũkũka kũũ o na kũũ: na andũ ala maĩ manakũka weũnĩ mamaalũkĩla ala mamaatĩĩe.'),
('kam', 'JOS', 8, 21, 'Na yĩla Yosua na Isilaeli onthe moonie kana ala oveesya nĩmakwata ndũa, na kana syũki ya ndũa nĩyambatĩte, meetulũla ĩngĩ; na mooaa andũ ma Ai.'),
('kam', 'JOS', 8, 22, 'Na ala angĩ mamaumaalĩla kuma ndũanĩ; na kwondũ wa ũu maĩ katĩ wa Isilaeli, amwe ngalĩ ĩno, na amwe ngalĩ ĩya: namo mamakũna, mateũmatialya o na ũmwe e thayũ o na wa kũvonoka.'),
('kam', 'JOS', 8, 23, 'Na mũsumbĩ wa Ai mamũkwata e thayũ, na mamũetee Yosua.'),
('kam', 'JOS', 8, 24, 'Na kweethĩwa, yĩla Isilaeli maĩ manamina kũmoaĩa kĩthekanĩ onthe ala matwĩe Ai, o vu weũnĩ vala mamaatĩĩe, na onthe mavalũkĩtw’e kwa kũtemangwa na ũvyũ mũvaka maminwa, Isilaeli onthe masyoka Ai, na mamĩkũna kwa kũtemanga na ũvyũ.'),
('kam', 'JOS', 8, 25, 'Na onthe ala mavalũkilw’e mũthenya ũsu, ma aũme o na aka, maĩ ngili ĩkũmi na ilĩ, o andũ onthe ma Ai.'),
('kam', 'JOS', 8, 26, 'Nũndũ Yosua ndaatũnga kw’oko kwake, kũla watambũũkĩtye katumo, mũvaka amamina vyũ ala matwĩe Ai.'),
('kam', 'JOS', 8, 27, 'Ĩndĩ mũtavo wa indo na mũtavo wa syĩndũ sya ndũa ĩsu Isilaeli moosa syĩthĩwe mũtavo woo ene, kwĩanana na ndeto ya Yeova ĩla wamwĩaĩe Yosua.'),
('kam', 'JOS', 8, 28, 'Na ĩndĩ Yosua avĩvya Ai, na amĩtw’ĩkĩthya kĩvumbu tene na tene, no ĩaanzo, kũvika mũnthĩ ũũ.'),
('kam', 'JOS', 8, 29, 'Na amũsũsya mũsumbĩ wa Ai mũtĩnĩ kũvika wĩoo: na syũa yĩkĩthũa Yosua aumya mwĩao, na maumya kimba kyake mũtĩnĩ, na makĩkya ũlikĩlonĩ mbingĩlonĩ ya ndũa, na makyũmbĩĩa mbumbu nene ya mavia, kũvika mũnthĩ ũũ.'),
('kam', 'JOS', 8, 30, 'Nĩvo ĩndĩ Yosua wakĩie Yeova, Ngai wa Isilaeli, kĩthembeo, kĩĩmanĩ kya Evali,'),
('kam', 'JOS', 8, 31, 'o tondũ Mose, mũthũkũmi wa Yeova, wameaĩe ana ma Isilaeli, o tondũ kũandĩkĩtwe ĩvukunĩ ya mĩao ya Mose, kĩthembeo kya mavia mate masũvye, ala mũndũ o na wĩva ũtaamasũvya na mũio o na wĩva wa kĩaa: na mathembea Yeova nthembo sya kũvĩvw’a ĩũlũ wakyo, na mathemba nthembo sya mũuo.'),
('kam', 'JOS', 8, 32, 'Na andĩka vo mavianĩ wumĩĩsyo wa mĩao ya Mose, ĩla waandĩkie, ana ma Isilaeli mene.'),
('kam', 'JOS', 8, 33, 'Na Isilaeli onthe, na atumĩa moo na anene, na asili moo, aeni o na ala masyaĩwe nthĩ ĩsu, maũngama ngalĩ ĩno ya yĩla ĩsandũkũ na ngalĩ ĩya mbee wa athembi Alivai, ala makuaa ĩsandũkũ ya ũtianĩo ya Yeova; nyunzu yamo yelekele kĩĩma kya Ngelisimu, na nyũnzu yamo yelekele kĩĩma kya Evali; o tondũ Mose, mũthũkũmi wa Yeova, wambie ũmeaĩa, nĩ kana maathime andũ ma Isilaeli.'),
('kam', 'JOS', 8, 34, 'Na ĩtina asoma ndeto syonthe sya ĩla mĩao, ũathimo o na kĩumo, kwĩanana na syonthe ila iandĩkĩtwe ĩvukunĩ ya mĩao.'),
('kam', 'JOS', 8, 35, 'Kũtyaĩ ndeto ya isu syonthe ila Mose weaie, Yosua ũtaasoma kũla kwĩ ĩkomano yonthe ya Isilaeli, o na aka, na syana nini, na ekali ma ũeninĩ ala maĩ katĩ woo.'),
('kam', 'JOS', 9, 1, 'Na kweethĩwa, yĩla asumbĩ onthe ala maĩ mũingo wa Yolotani, nthĩ yĩ iĩma, na nthĩ ndindimalu, na ndeenĩ syonthe sya ũkanga mũnene ũla welekele Levanoni, Mũititi, na Mũamoli, na Mũkanaani, na Mũvelisi, na Mũivi, na Mũyevusi, meewie ũndũ ũsu;'),
('kam', 'JOS', 9, 2, 'nĩmoombanie vamwe, mokite na Yosua na Isilaeli, me na ngoo ĩmwe.'),
('kam', 'JOS', 9, 3, 'Ĩndĩ yĩla ala matwĩe Ngiveoni meewie ũndũ Yosua wĩkĩte Yeliko na Ai,'),
('kam', 'JOS', 9, 4, 'namo meekie na ũseleke, na mathi meeyĩelekan’ya ta atũmwa, na mailĩĩla makunia makũũ mang’oinĩ, na tũthatwa twa mbinyu, tũla tũkũũ, na tũtembũkangu, na tũliĩtwe,'),
('kam', 'JOS', 9, 5, 'na mekĩĩte maũũnĩ moo iatũ ngũũ na syĩ ilio, na mekĩĩte ngũa ngũũ; na kĩmũtũ kyonthe kya lĩu woo kyaĩ kyũmũ na kĩkaya mbuuka.'),
('kam', 'JOS', 9, 6, 'Na mamũendea Yosua mwakonĩ wa maeema Ngilikali, na mamwĩa we, o na andũ ma Isilaeli, Nĩtumĩte nthĩ yĩ kũasa: na yu kwondũ wa ũu tianĩai ũtianĩo naitũ.'),
('kam', 'JOS', 9, 7, 'Na andũ ma Isilaeli mamea Aivi, Nokwĩthĩwa mũtwĩe katĩ waitũ; na twĩtianĩa ũtianĩo nenyu ata?'),
('kam', 'JOS', 9, 8, 'Na mamwĩa Yosua, Twĩ athũkũmi maku. Na Yosua amakũlya, Mwĩ aaũ? Na mumĩte va?'),
('kam', 'JOS', 9, 9, 'Na mamwĩa, Athũkũmi maku nĩmaumĩte nthĩ yĩ kũasa mũno kwondũ wa syĩtwa ya Yeova Ngai waku: nũndũ nĩtwĩw’ĩte nguma yake, na w’onthe ũla wekie Misili,'),
('kam', 'JOS', 9, 10, 'na w’onthe ũla wekie asumbĩ elĩ ma Aamoli, ala maĩ mũingo wa Yolotani, Sioni mũsumbĩ wa Esivoni, na Oku mũsumbĩ wa Mbasani, ũla waĩ Asetalothi.'),
('kam', 'JOS', 9, 11, 'Na atumĩa maitũ na onthe ala matwie nthĩ yaitũ maneena naitũ, makĩtwĩa, Osai lĩu wa nzĩanĩ na moko menyu, na mũithi mũmathaũe, na mũimea, Twĩ athũkũmi menyu: na yu tianĩai ũtianĩo naitũ.'),
('kam', 'JOS', 9, 12, 'Kĩmũtũ kĩĩ kitũ twaumie nakyo nyũmbanĩ sitũ kĩ kĩvyũ kĩthĩwe lĩu witũ mũthenya ũla twaumaalile tũkomane nenyu; ĩndĩ yu, sisyai, nĩ kyũmũ, na nĩkĩĩte mbuuka:'),
('kam', 'JOS', 9, 13, 'na tũthatwa tũũ twa mbinyu, tũla twausũisye, twaĩ tweũ; na, sisyai, nĩ tũtembũkangu: na ngũa ii sitũ na iatũ sitũ nikũĩte nũndũ wa kyalo kũasava mũno.'),
('kam', 'JOS', 9, 14, 'Na ala andũ moosa kya ũya kyoo, na matyaakũlya ũtao kanyw’anĩ wa Yeova.'),
('kam', 'JOS', 9, 15, 'Na Yosua aseũvya mũuo namo, na atianĩa ũtianĩo namo, nĩ kana mekale thayũ: na anene ma ĩkomano mameavĩa.'),
('kam', 'JOS', 9, 16, 'Na kweethĩwa mĩthenya ĩtatũ yathela ĩtina wa matianĩa ũtianĩo namo, nĩmeewie kana maĩ atũi moo, na kana matwĩe katĩ woo.'),
('kam', 'JOS', 9, 17, 'Na ana ma Isilaeli maenda kyalo, na mavika ndũa syoo mũthenya wa katatũ. Na ĩndĩ ndũa syoo syeetawa Ngiveoni na Kevila, na Mbeelothi, na Kiliathi‐yealimu.'),
('kam', 'JOS', 9, 18, 'Na ana ma Isilaeli matyaamakũna, nĩkwĩthĩwa anene ma yĩla ĩkomano maĩ manameavĩa na Yeova, Ngai wa Isilaeli. Na ĩkomano yonthe yanyũngũnyĩĩsya ala anene.'),
('kam', 'JOS', 9, 19, 'Ĩndĩ anene asu onthe matavya ĩkomano yonthe, Nĩtũmeavĩe na Yeova, Ngai wa Isilaeli: kwondũ wa ũu yu tũtitonya kũmakiita.'),
('kam', 'JOS', 9, 20, 'Twĩmeka ũũ, na kũmaeka mekale thayũ; ũthatu ndũkese kwĩthĩwa ĩũlũ waitũ, nũndũ wa wĩvĩto ũla twamevĩtĩe.'),
('kam', 'JOS', 9, 21, 'Na anene mamea, Nĩmaekwe mekale thayũ: na ĩndĩ matw’ĩka auni ma ngũ na atavi ma manzĩ kwa ĩkomano yonthe, o tondũ anene mamatavĩtye.'),
('kam', 'JOS', 9, 22, 'Na Yosua amatũmana, na aneena namo, akĩmea, Mũtũkengete nĩkĩ, mũkĩtwĩa, Twĩ kũasa nenyu mũno; na kaĩ mũtwĩe katĩ waitũ?'),
('kam', 'JOS', 9, 23, 'Kwondũ wa ũu yu mwĩ aumanĩe, na kũikatĩa o na ĩndĩĩ kwĩthĩwa amwe menyu ngombo, auni ma ngũ o na atavi ma manzĩ kwondũ wa nyũmba ya Ngai wakwa.'),
('kam', 'JOS', 9, 24, 'Na masũngĩa Yosua, na mamwĩa, Nĩkwĩthĩwa athũkũmi maku nĩmataviw’e ki, ũndũ Yeova Ngai waku wamwĩaĩe mũthũkũmi wake Mose amũnenge inyw’ĩ nthĩ ĩno yonthe, na kwananga kuma mbee wenyu onthe ala matwĩe ĩ nthĩ; kwondũ wa ũu twakĩsya mũno mathayũ maitũ kwondũ wenyu, na ĩndĩ tũneekie ũndũ ũũ.'),
('kam', 'JOS', 9, 25, 'Na yu, sisya, twĩ kw’okonĩ kwaku: o ũndũ wĩona wĩ ũseo na ũlũngalu kũtwĩka, ũtwĩke.'),
('kam', 'JOS', 9, 26, 'Na ameka o ta ũu, na amavonokya mokonĩ ma Isilaeli, matikamoae.'),
('kam', 'JOS', 9, 27, 'Na mũthenya ũsu Yosua amatw’ĩkĩthya auni ma ngũ na atavi ma manzĩ kwondũ wa ĩkomano, na kwondũ wa kĩthembeo, kya Yeova, kũvika ũmũnthĩ, o vandũnĩ vala wĩnyuva.'),
('kam', 'JOS', 10, 1, 'Na ĩndĩ kweethĩwa, yĩla Atoninzeteki mũsumbĩ wa Yelusaleme wewie ũndũ Yosua wakwatie Ai, na ũndũ wamyanangie vyũ (o tondũ wekĩte Yeliko na mũsumbĩ wayo, o ta ũu nĩwekĩte Ai na mũsumbĩ wayo), na ũndũ ala matwĩe Ngiveoni maseũvĩtye mũuo na Isilaeli, na meethĩwa katĩ woo;'),
('kam', 'JOS', 10, 2, 'makĩa mũno, nũndũ Ngiveoni yaĩ ndũa nene, o ta ndũa ĩmwe ya kĩũsumbĩ, na nĩkwĩthĩwa yaĩ nene kwĩ Ai, na andũ onthe mayo maĩ ngũmbaũ.'),
('kam', 'JOS', 10, 3, 'Kwondũ wa ũu Atoninzeteki mũsumbĩ wa Yelusaleme atũmana Oamu mũsumbĩ wa Eviloni, na Vikamu mũsumbĩ wa Yalimuthi, na Yavia mũsumbĩ wa Lakisi, na Ndevili mũsumbĩ wa Ekeloni, akĩmea,'),
('kam', 'JOS', 10, 4, 'Ambatai kwakwa, mũndethye, na tũkũnei Ngiveoni; nũndũ nĩseũvĩtye mũuo na Yosua na ana ma Isilaeli.'),
('kam', 'JOS', 10, 5, 'Kwondũ wa ũu asumbĩ asu atano ma Aamoli, mũsumbĩ wa Yelusaleme, na mũsumbĩ wa Eviloni, na mũsumbĩ wa Yalimuthi, na mũsumbĩ wa Lakisi, na mũsumbĩ wa Ekeloni, meeyũmban’ya vamwe, na mambata, mo na nguthu syoo syonthe, na mamba maeema mataũĩĩe Ngiveoni, na makwatya kaũ nayo.'),
('kam', 'JOS', 10, 6, 'Na andũ ma Ngiveoni matũmana Yosua mwakonĩ wa maeema Ngilikali, makĩmwĩa, Kw’oko kwaku kũtikethĩwe na kĩkono kũla kwĩ athũkũmi maku; ambata mĩtũkĩ kwitũ, ũtũtangĩĩe, na kũtũtethya: nũndũ asumbĩ onthe ma Aamoli ala matwĩe nthĩ yĩ iĩma nĩmatũmbanĩe.'),
('kam', 'JOS', 10, 7, 'Kwondũ wa ũu Yosua ambata kuma Ngilikali, we, na andũ onthe ma kaũ vamwe nake, na ngũmbaũ nene syonthe.'),
('kam', 'JOS', 10, 8, 'Na Yeova amwĩa Yosua, Ndũkamakĩe: nũndũ nĩnĩmanenganĩte mokonĩ maku; kũtikaũngama mũndũ wamo mbee waku.'),
('kam', 'JOS', 10, 9, 'Na kwondũ wa ũu Yosua amakuthũkĩa na kĩthũlũmũko; nũndũ ambatie kuma Ngilikali ũtukũ w’onthe.'),
('kam', 'JOS', 10, 10, 'Na Yeova amathokoan’ya mbee wa Isilaeli, na amoaĩa na ũai mũnene ku Ngiveoni, na amalũngya na nzĩa ya kyambato kya Mbethi‐oloni, na amakũnĩa kũvika Aseka, na kũvika Maketa.'),
('kam', 'JOS', 10, 11, 'Na kweethĩwa, makĩkũka mbee wa Isilaeli, me kĩtheeonĩ kya Mbethi‐oloni, Yeova amekya mavia manene kuma ĩtunĩ kũvika Aseka, na makw’a: ala makwie na mbua ya mavia maĩ aingĩ kwĩ ala ana ma Isilaeli mooaie na ũvyũ.'),
('kam', 'JOS', 10, 12, 'Nĩvo ĩndĩ Yosua waneenie na Yeova mũthenya ũla Yeova wanenganie Aamoli kũla kwĩ ana ma Isilaeli; na asya Isilaeli mene, Syũa, ũngama ki ĩũlũ wa Ngiveoni; Naku, Mwei, mwandanĩ wa Aiyaloni.'),
('kam', 'JOS', 10, 13, 'Nayo syũa yaũngama ki, na mwei weeteela Mũvaka ĩla mbaĩ yeeĩvanĩsya amaithanĩ mayo. Ũu ti mũandĩke ĩvukunĩ ya Yasali? Na syũa yaũngama ĩtunĩ katĩ, na yĩtyaaĩkalaata kũthũa ta ĩvinda ya mũthenya mũima.'),
('kam', 'JOS', 10, 14, 'Na kũtyaĩ mũthenya ta ũsu mbee waw’o kana ĩtina waw’o, ũndũ Yeova wethukĩĩsye wasya wa mũndũ: nĩkwĩthĩwa Yeova nĩwamokitĩie Isilaeli.'),
('kam', 'JOS', 10, 15, 'Na Yosua asyoka, we na Isilaeli onthe vamwe nake, mwakonĩ wa maeema Ngilikali.'),
('kam', 'JOS', 10, 16, 'Na asumbĩ asu atano makũka, na meevitha ngunganĩ ku Maketa.'),
('kam', 'JOS', 10, 17, 'Na Yosua atavw’a, kũkyaw’a, Asumbĩ asu atano nĩ oneku, mevithĩte ĩla ngunganĩ ku Maketa.'),
('kam', 'JOS', 10, 18, 'Na Yosua asya, Vingilitĩĩlyai mavia manene mũomonĩ wa ngunga, na mũkia andũ vakuvĩ nayo mamasũvĩe:'),
('kam', 'JOS', 10, 19, 'ĩndĩ inyw’ĩ mũtikaũngame; atĩĩai amaitha menyu, na mũimakũna ala me ĩtina; mũtikamaeke malike ndũanĩ syoo: nũndũ Yeova Ngai wenyu nũmanenganĩte mokonĩ menyu.'),
('kam', 'JOS', 10, 20, 'Na kweethĩwa, yĩla Yosua na ana ma Isilaeli maĩ manamina kũmoaa na ũai mũnene mũno, mũvaka mamamina, na ũtialo ũla watialile wamo waĩ ũnalika ila ndũanĩ mbiie,'),
('kam', 'JOS', 10, 21, 'andũ onthe masyoka mwakonĩ wa maeema kwa Yosua ku Maketa me na mũuo: kũtyaĩ ũmwe waaũkĩlya ũĩmĩ ĩũlũ wa ana ma Isilaeli o na ũmwe.'),
('kam', 'JOS', 10, 22, 'Nĩvo ĩndĩ Yosua waisye, Vingũai mũomo wa ngunga, na mũinũmaalĩĩlya asumbĩ asu atano ngunganĩ.'),
('kam', 'JOS', 10, 23, 'Na meeka ũu, na mamumaalĩĩlya asumbĩ asu atano ngunganĩ, ũla mũsumbĩ wa Yelusaleme, na mũsumbĩ wa Eviloni, na mũsumbĩ wa Yalimuthi, na mũsumbĩ wa Lakisi, na mũsumbĩ wa Ekeloni.'),
('kam', 'JOS', 10, 24, 'Na kweethĩwa, yĩla mamumaalĩĩlye Yosua asumbĩ asu, Yosua atũmana andũ onthe ma Isilaeli, na amea anene ma andũ ma kaũ ala maendie nake, Thengeeai, mũkinyĩthye maũũ menyu ngingonĩ sya asumbĩ aa. Na mathengeea, na makinyĩthya maũũ moo ngingonĩ syoo.'),
('kam', 'JOS', 10, 25, 'Na Yosua amea, Mũikakĩe, o na kũteva; ĩthĩwai na vinya na ũkũmbaũ mũnene: nũndũ ũũ nĩw’o Yeova wĩmeka amaitha menyu onthe ala mũũkita namo.'),
('kam', 'JOS', 10, 26, 'Na ĩtina Yosua amakũna, na amoaa, na kũmasũsya mĩtĩnĩ ĩtano: na masũa ĩla mĩtĩnĩ kũvika wĩoo.'),
('kam', 'JOS', 10, 27, 'Na kweethĩwa ĩvinda ya syũa yĩkĩthũa, Yosua aumya mwĩao, na mamaumya mĩtĩnĩ, na mamekya ngunganĩ ĩla meevithĩte, na maia mavia manene mũomonĩ wa ngunga, kũvika mũthenya ũũ wa ũmũnthĩ.'),
('kam', 'JOS', 10, 28, 'Na Yosua akwata Maketa mũthenya ũsu, na amĩkũna kwa kũmĩtemanga na ũvyũ, na mũsumbĩ wayo: amananga vyũ na andũ onthe ala maĩ nthĩnĩ wayo; ndaatialya o na ũmwe; na amwĩka mũsumbĩ wa Maketa o tondũ waĩ anamwĩka mũsumbĩ wa Yeliko.'),
('kam', 'JOS', 10, 29, 'Na Yosua avĩta kuma Maketa, e na Isilaeli onthe, kũvika Livina, na mokita na Livina:'),
('kam', 'JOS', 10, 30, 'nayo Yeova amĩnengane, na mũsumbĩ wayo, kw’okonĩ kwa Isilaeli; na amĩkũna kwa kũmĩtemanga na ũvyũ, na andũ onthe ala maĩ nthĩnĩ wayo; ndaatialya o na ũmwe vo; na amwĩka mũsumbĩ wayo o tondũ waĩ anamwĩka mũsumbĩ wa Yeliko.'),
('kam', 'JOS', 10, 31, 'Na Yosua avĩta kuma Livina, e na Isilaeli onthe, kũvika Lakisi, na mamba maeema mamĩtaũĩĩe, na mokita nayo:'),
('kam', 'JOS', 10, 32, 'na Yeova amĩnengane Lakisi kw’okonĩ kwa Isilaeli; na amĩkwata ũnĩ ũsu, na amĩkũna kwa kũmĩtemanga na ũvyũ, na andũ onthe ala maĩ nthĩnĩ wayo, kwĩanana na w’onthe ũla waĩ aneeka Livina.'),
('kam', 'JOS', 10, 33, 'Nĩvo ĩndĩ Olamu mũsumbĩ wa Ngeseli wambatie amĩtethye Lakisi; na Yosua amũkũna na andũ make, mũvaka ndaamũtialya o na ũmwe.'),
('kam', 'JOS', 10, 34, 'Na Yosua avĩta kuma Lakisi, e na Isilaeli onthe, kũvika Ekeloni; na mamba maeema maĩtaũĩĩe, na mokita nayo;'),
('kam', 'JOS', 10, 35, 'na mamĩkwata mũthenya ũsu, na mamĩkũna kwa kũmĩtemanga na ũvyũ; na andũ onthe ala maĩ nthĩnĩ wayo aananga vyũ mũthenya ũsu, kwĩanana na w’onthe ũla waĩ aneeka Lakisi.'),
('kam', 'JOS', 10, 36, 'Na Yosua ambata kuma Ekeloni, e na Isilaeli onthe, kũvika Eviloni; na mokita nayo:'),
('kam', 'JOS', 10, 37, 'na mamĩkwata, na mamĩkũna kwa kũmĩtemanga na ũvyũ, na mũsumbĩ wayo, na ndũa syonthe syayo, na andũ onthe ala maĩ nthĩnĩ wayo; ndaatĩalya o na ũmwe, kwĩanana na w’onthe ũla waĩ aneeka Ekeloni; ĩndĩ amyananga vyũ, na andũ onthe ala maĩ nthĩnĩ wayo.'),
('kam', 'JOS', 10, 38, 'Na Yosua asyoka, e na Isilaeli onthe, kũvika Ndevili, na mokita nayo;'),
('kam', 'JOS', 10, 39, 'na amĩkwata, na mũsumbĩ wayo na ndũa syonthe syayo; na mamakũna kwa kũmatemanga na ũvyũ, na mooaa vyũ andũ onthe ala maĩ nthĩnĩ wayo; ndaatĩalya o na ũmwe: o tondũ waĩ aneeka Eviloni, o ta ũu eekie Ndevili, na mũsumbĩ wayo; o na tondũ waĩ aneeka Livina nayo, na mũsumbĩ wayo.'),
('kam', 'JOS', 10, 40, 'O ta ũu Yosua akũna nthĩ yonthe, nthĩ yĩ iĩma, na nthĩ yĩ Ĩtheo, na nthĩ ndindimalu, na ivaũũko, na asumbĩ onthe masyo: ndaatialya o na ũmwe, ĩndĩ aananga vyũ onthe ala mavevaa, o tondũ Yeova, Ngai wa Isilaeli, weaie.'),
('kam', 'JOS', 10, 41, 'Na Yosua amakũna kuma Katesi‐mbalinea o kũvika Ngasa, na nthĩ yonthe ya Ngoseni, o kũvika Ngiveoni.'),
('kam', 'JOS', 10, 42, 'Na asumbĩ asu onthe na nthĩ syoo Yosua akwata ĩvinda yĩmwe, nĩkwĩthĩwa Yeova, Ngai wa Isilaeli, okitĩaa Isilaeli.'),
('kam', 'JOS', 10, 43, 'Na Yosua asyoka mwakonĩ wa maeema Ngilikali, e na Isilaeli onthe.'),
('kam', 'JOS', 11, 1, 'Na kweethĩwa, yĩla Yavini mũsumbĩ wa Asoli wewie ũndũ ũsu, atũmana Yovavu mũsumbĩ wa Matoni, na mũsumbĩ wa Similoni, na mũsumbĩ wa Akisavu,'),
('kam', 'JOS', 11, 2, 'na asumbĩ ala maĩ ngalĩ ya ĩũlũ, nthĩ yĩ iĩma, na Alava ngalĩ ya ĩtheo wa Kinelethi, na nthĩ ndindimalu, na motũlunĩ ma Ndoli ngalĩ ya ũthũĩlonĩ wa syũa,'),
('kam', 'JOS', 11, 3, 'kwa Mũkanaani ngalĩ ya wumĩlonĩ wa syũa na ngalĩ ya ũthũĩlonĩ wa syũa, na kwa Mũamoli, na kwa Mũititi, na kwa Mũvelisi, na kwa Mũyevusi nthĩ yĩ iĩma, na kwa Mũivi ũla wĩ ĩtheo wa Elimoni nthĩ ya Misiva.'),
('kam', 'JOS', 11, 4, 'Na maumaala, mo na nguthu, syoo syonthe vamwe nao, andũ aingĩ, o ta kĩthangathĩ kĩla kĩ ũtee wa ũkanga ũndũ wa kwingĩva, me na mbalasi na ngalĩ nyingĩ nũno sya kaũ.'),
('kam', 'JOS', 11, 5, 'Na asumbĩ asu onthe makomana; na mavika na mamba maeema vamwe ũtee wa manzĩ ma Melomu, mokite na Isilaeli.'),
('kam', 'JOS', 11, 6, 'Na Yeova amwĩa Yosua, Ndũkakĩe nũndũ woo; nũndũ ũnĩ ta ĩvinda yĩĩ ngamanengane onthe me oae kũla kwĩ Isilaeli: nĩwĩtilanga mbalasi syoo mĩlangũ, na kũvĩvya makasya moo na mwaki.'),
('kam', 'JOS', 11, 7, 'Na ĩndĩ Yosua, e na andũ onthe ma kaũ, mamakitya ũtee wa manzĩ ma Melomu na kĩthũlũmũko, na mamavithũkĩa.'),
('kam', 'JOS', 11, 8, 'Na Yeova amanengane kw’okonĩ kwa Isilaeli, na mamakũna na mamalũngya kũvika Sitoni ĩla nene, na kũvika Misilevothi‐maimu, na kũvika mwandanĩ wa Misiva kwelekela ngalĩ ya wumĩlonĩ wa syũa; na mamakũna, mũvaka matyaatialya o na ũmwe.'),
('kam', 'JOS', 11, 9, 'Na Yosua ameka o tondũ Yeova wamwĩie: atilanga mbalasi syoo mĩlangũ, na avĩvya makasya moo na mwaki.'),
('kam', 'JOS', 11, 10, 'Na Yosua ĩvinda yĩu asyoka, na akwata Asoli, na amũtema mũsumbĩ wayo na ũvyũ: nũndũ tene Asoli yaĩ ndũa nene ya mosumbĩ asu onthe.'),
('kam', 'JOS', 11, 11, 'Na makũna andũ onthe ala maĩ nthĩnĩ wayo kwa kũmatemanga na ũvyũ, na kũmina vyũ; kũtyaĩ ũmwe waatiwa aiveva: na avĩvya Asoli na mwaki.'),
('kam', 'JOS', 11, 12, 'Na ndũa syonthe sya asumbĩ asu, na asumbĩ onthe masyo, Yosua akwata, na amakũna kwa kũmatemanga na ũvyũ, na amananga vyũ; o tondũ Mose mũthũkũmi wa Yeova weaie.'),
('kam', 'JOS', 11, 13, 'Ĩndĩ ũndũ wa ndũa ila syatiĩtwe syĩ nũmũ ũtũlunĩ wasyo, Isilaeli matyaaivĩvya o na ĩmwe, ate o Asoli yoka; nĩyo Yosua wavĩvisye.'),
('kam', 'JOS', 11, 14, 'Na mũtavo w’onthe wa ndũa isu, o na ĩndo, ana ma Isilaeli meeyosea itw’ĩke mũtavo; ĩndĩ kĩla mũndũ nĩmamũkũnie kwa kũmũtemanga na ũvyũ, mũvaka mamamina, o na matyaatialya o na ũmwe aiveva.'),
('kam', 'JOS', 11, 15, 'O tondũ Yeova wamwĩaĩe Mose mũthũkũmi wake, now’o Mose weaĩe Yosua; na now’o Yosua wekie; ndaatialya ũndũ ũtekĩtwe wa w’onthe ũla Yeova weaĩe Mose.'),
('kam', 'JOS', 11, 16, 'O ta ũu Yosua akwata nthĩ ĩsu yonthe, nthĩ yĩ iĩma, na nthĩ yonthe ya ngalĩ ya Ĩtheo, na nthĩ yonthe ya Ngoseni, na nthĩ ndindimalu, na Alava, na nthĩ ya Isilaeli yĩ iĩma, na nthĩ ndindimalu yayo;'),
('kam', 'JOS', 11, 17, 'kuma kĩĩma kya Alaki, kĩla kĩtambũũkĩte kũvika Seili, o kũvika Mbaali‐ngati mwandanĩ wa Levanoni itheo wa kĩĩma kya Elimoni: na akwata asumbĩ masyo onthe, na amakũna, na amoaa.'),
('kam', 'JOS', 11, 18, 'Yosua okita ĩvinda ĩasa na asumbĩ asu onthe.'),
('kam', 'JOS', 11, 19, 'Kũtyaĩ ndũa ĩla yaseũvisye mũuo na ana ma Isilaeli, ate o Aivi ala matwĩe Ngiveoni: ila ingĩ syonthe makwatie na kaũ.'),
('kam', 'JOS', 11, 20, 'Nũndũ kwaĩ ũndũ wa Yeova kũmya ngoo syoo, mokite na Isilaeli, nĩ kana amamine vyũ, matikew’ĩwe ĩnee, ĩndĩ nĩ kana amamine, o tondũ Yeova wamwĩaĩe Mose.'),
('kam', 'JOS', 11, 21, 'Na Yosua athi ĩvinda yĩu, na amaveta Aanaki nthĩ yĩ iĩma, kuma ku Eviloni, na Ndevili, na Anavu, na nthĩ yonthe ya Yuta yĩ iĩma, na nthĩ yonthe ya Isilaeli yĩ iĩma: Yosua amamina vyũ vamwe na ndũa syoo.'),
('kam', 'JOS', 11, 22, 'Kũtyaĩ ũmwe wa Aanaki waatiala nthĩ ya ana ma Isilaeli: ate o amwe matialile Ngasa, na Ngathi, na Asitoti.'),
('kam', 'JOS', 11, 23, 'O ta ũu Yosua akwata nthĩ yonthe, kwĩanana na w’onthe ũla Yeova watavisye Mose; na Yosua amĩnengane kwa Isilaeli yĩthĩwe ũtiĩwa kwĩanana na ũaan’yo woo wa mbaĩ. Na nthĩ yathũmũĩa kaũ.'),
('kam', 'JOS', 12, 1, 'Na ĩndĩ aa nĩo asumbĩ ma nthĩ ĩsu, ala ana ma Isilaeli makũnie, na mamĩmesya nthĩ yoo mũingo wa Yolotani kwelekela vala syũa yumĩlaa, kuma mwanda wa Alinoni kũvika kĩĩma kya Elimoni, na Alava w’onthe kwelekela ngalĩ ya wumĩlonĩ wa syũa:'),
('kam', 'JOS', 12, 2, 'Sioni mũsumbĩ wa Aamoli, ũla watwĩe Esivoni, na aisumbĩka kuma Aloeli, ĩla yĩ ũtee wa mwanda wa Alinoni, na ndũanĩ ĩla yĩ mwandanĩ katĩ, na nyunzu ya Ngileati, o kũvika ũsĩ wa Yavoki, mũvaka wa ana ma Amimoni;'),
('kam', 'JOS', 12, 3, 'na ũla Alava, kũvika ũkanga wa Kinelethi, kwelekela ngalĩ ya wumĩlonĩ wa syũa, na kũvika ũkanga wa Alava, o ũsu Ũkanga wa Mũnyũ, kwelekela ngalĩ ya wumĩlonĩ wa syũa, nzĩanĩ ya kũthi Mbethi‐yesimothi; na ngalĩ ya ĩtheo, ĩtheo wa ivaũũko sya Visika:'),
('kam', 'JOS', 12, 4, 'o na mũvaka wa Oku mũsumbĩ wa Mbasanĩ, wa ala matialĩte ma Alevai, ala matwĩe Asetalothi na Etilei,'),
('kam', 'JOS', 12, 5, 'na asumbĩka kĩĩmanĩ kya Elimoni, na Saleka, na Mbasani yonthe, kũvika mũvakanĩ wa Angesuli na Amaaka na nyunzu ya Ngileati, mũvaka wa Sioni mũsumbĩ wa Esivoni.'),
('kam', 'JOS', 12, 6, 'Mose mũthũkũmi wa Yeova na ana ma Isilaeli mamakũna; na Mose mũthũkũmi wa Yeova amĩnengane kwa Aleuveni, na Angati, na nyunzu ya mbaĩ ya Manase yĩthĩwe ng’ũndũ yoo.'),
('kam', 'JOS', 12, 7, 'Na aa nĩo asumbĩ ma nthĩ ĩla Yosua na ana ma Isilaeli makũnie mũingo wa Yolotani kwelekela ngalĩ ya ũthũĩlonĩ wa syũa, kuma Mbaali‐ngati mwandanĩ wa Levanoni o na kũvika kĩĩma kya Alaki, kĩla kĩtambũũkĩte kũvika Seili (na Yosua amĩnengane kwa mbaĩ sya Isilaeli, yĩthĩwe ng’ũndũ yoo kwĩanana na ũaan’yo woo;'),
('kam', 'JOS', 12, 8, 'nthĩ yĩ iĩma, na nthĩ ndindimalu, na ũla Alava, na ivaũũkonĩ, na weũnĩ na nthĩ ya yĩ Ĩtheo; Mũititi, na Mũamoli, na Mũkanaani, na Mũvelisi, na Mũivi, na Mũyevusi):'),
('kam', 'JOS', 12, 9, 'mũsumbĩ wa Yeliko, ũmwe; na mũsumbĩ wa Ai, yĩ vakuvĩ na Mbethi‐eli, ũmwe;'),
('kam', 'JOS', 12, 10, 'na mũsumbĩ wa Yelusaleme, ũmwe; na mũsumbĩ wa Eviloni, ũmwe;'),
('kam', 'JOS', 12, 11, 'na mũsumbĩ wa Yalimuthi, ũmwe; na mũsumbĩ wa Lakisi, ũmwe;'),
('kam', 'JOS', 12, 12, 'na mũsumbĩ wa Ekeloni, ũmwe; na mũsumbĩ wa Ngeselĩ, ũmwe;'),
('kam', 'JOS', 12, 13, 'na mũsumbĩ wa Ndevili ũmwe; na mũsumbĩ wa Ngeteli, ũmwe;'),
('kam', 'JOS', 12, 14, 'na mũsumbĩ wa Olima, ũmwe; na mũsumbĩ wa Alati, ũmwe;'),
('kam', 'JOS', 12, 15, 'na mũsumbĩ wa Livina, ũmwe; na mũsumbĩ wa Atulamu, ũmwe;'),
('kam', 'JOS', 12, 16, 'na mũsumbĩ wa Maketa, ũmwe; na mũsumbĩ wa Mbethi‐eli, ũmwe;'),
('kam', 'JOS', 12, 17, 'na mũsumbĩ wa Tavua, ũmwe; na mũsumbĩ wa Eevieli, ũmwe;'),
('kam', 'JOS', 12, 18, 'na mũsumbĩ wa Aveki, ũmwe; na mũsumbĩ wa Lasaloni, ũmwe;'),
('kam', 'JOS', 12, 19, 'na mũsumbĩ wa Matoni, ũmwe; na mũsumbĩ wa Asoli, ũmwe;'),
('kam', 'JOS', 12, 20, 'na mũsumbĩ wa Similonimeloni, ũmwe; na mũsumbĩ wa Akisavu, ũmwe;'),
('kam', 'JOS', 12, 21, 'na mũsumbĩ wa Taanaki, ũmwe; na mũsumbĩ wa Mekito, ũmwe;'),
('kam', 'JOS', 12, 22, 'na mũsumbĩ wa Ketesi, ũmwe; na mũsumbĩ wa Yokineamu ku Kalimeli, ũmwe;'),
('kam', 'JOS', 12, 23, 'na mũsumbĩ wa Ndoli ũtũlunĩ wa Ndoli, ũmwe; na mũsumbĩ wa Ngoiimu ku Ngilikali, ũmwe;'),
('kam', 'JOS', 12, 24, 'na mũsumbĩ wa Tilisa, ũmwe: asumbĩ onthe maĩ mĩongo ĩtatũ na ũmwe.'),
('kam', 'JOS', 13, 1, 'Na ĩndĩ Yosua aĩ mũkũu na wa myaka mingĩ; na Yeova amwĩa, Wĩ mũkũu na wa myaka mingĩ, na kũtiele o na yu nthĩ nene mũno ya kwoswa yĩthĩwe ng’ũndũ yenyu.'),
('kam', 'JOS', 13, 2, 'Nthĩ ĩla itiele o na yu nĩ ĩno: nthĩ syonthe sya Avilisiti, na Angesuli onthe;'),
('kam', 'JOS', 13, 3, 'kuma ũsĩ wa Sioli, ũla ũthengeee Misili, o na kũvika mũvakanĩ wa Ekiloni welekele ngalĩ ya ĩũlũ, nthĩ ĩla ĩtalawa ya Akanaani: na eaĩi atano ma Avilisiti; na Angasa, na Aasitoti, na Aasikeloni, na Angiti, na Aekiloni; o na Aavi,'),
('kam', 'JOS', 13, 4, 'ngalĩ ya ĩtheo; nthĩ yonthe ya Akanaani, na Meala ĩla ya Asitoni, kũvika Aveki, kũvika mũvakanĩ wa Aamoli;'),
('kam', 'JOS', 13, 5, 'na nthĩ ya Angevali, na Levanoni w’onthe, kwelekela wumĩlonĩ wa syũa, kuma Mbaali‐ngati ĩtheo wa kĩĩma kya Elimoni kũvika ũlikĩlonĩ wa ku Amathi;'),
('kam', 'JOS', 13, 6, 'onthe ala matwĩe nthĩ yĩ iĩma kuma Levanoni kũvika Misilevothi‐maimu, o Asitoni onthe; asu ngamalũngya kuma mbee wa ana ma Isilaeli: ĩndĩ wĩaan’ya kwa kũlimana yĩthĩwe ya Isilaeli ũtiĩwa woo, o tondũ nĩkwĩaĩte.'),
('kam', 'JOS', 13, 7, 'Na ĩndĩ kwondũ wa ũu wĩaan’ya nthĩ ĩsu yĩthĩwe ũtiĩwa wa ila mbaĩ kenda, na nyunzu ya mbaĩ ya Manase.'),
('kam', 'JOS', 13, 8, 'Vamwe nayo Aleuveni na Angati nĩmoosie ũtiĩwa woo, ũla Mose wamanengie, mũingo wa Yolotani kwelekela ngalĩ ya wumĩlonĩ wa syũa, o tondũ Mose mũthũkũmi wa Yeova wamanengie:'),
('kam', 'JOS', 13, 9, 'kuma Aloeli, ĩla yĩ ũtee wa mwanda wa Alinoni, na ndũa ĩla yĩ mwandanĩ katĩ, na ũiĩ w’onthe wa Meteva kũvika Ndivoni;'),
('kam', 'JOS', 13, 10, 'na ndũa syonthe sya Sioni mũsumbĩ wa Aamoli, ũla wasumbĩkie Esivoni, kũvika mũvakanĩ wa ana ma Amimoni;'),
('kam', 'JOS', 13, 11, 'na Ngileati, na mũvaka wa Angesuli na Amaaka, na kĩĩma kyonthe kya Elimoni, na Mbasani yonthe kũvika Saleka;'),
('kam', 'JOS', 13, 12, 'ũsumbĩko w’onthe wa Oku ku Mbasani, ũla wasumbĩkie Asetalothi na Atilei (o asu nĩmatialĩte ma ũtialo wa Alevai); nũndũ Mose amakũnie asu, na amalũngya.'),
('kam', 'JOS', 13, 13, 'Ĩndĩ ana ma Isilaeli matyaalũngya Angesuli, o na Amaaka, ĩndĩ Angesuli na Amaaka matũaa katĩ wa Isilaeli kũvika mũnthĩ ũũ.'),
('kam', 'JOS', 13, 14, 'Ĩndĩ mbaĩ ya Livai ndaamĩnenga ũtiĩwa; nthembo sya Yeova, Ngai wa Isilaeli, ivĩvaw’a na mwaki nĩsyo ũtiĩwa woo, o tondũ wamatavisye.'),
('kam', 'JOS', 13, 15, 'Na Mose anenga mbaĩ ya ana ma Leuveni nthĩ kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 13, 16, 'Na mũvaka woo waĩ kuma Aloeli, ĩla yĩ ũtee wa mwanda wa Alinoni, na ndũa ĩla yĩ mwandanĩ katĩ, na ũiĩ w’onthe wa vakuvĩ na Meteva;'),
('kam', 'JOS', 13, 17, 'na Esivoni, na ndũa syonthe syayo ila syĩ ũiĩnĩ; na Ndivoni, na Mbamothi‐mbaali, na Mbethi‐mbaali‐meoni,'),
('kam', 'JOS', 13, 18, 'na Yaasa, na Ketemothi, na Mevaathi,'),
('kam', 'JOS', 13, 19, 'na Kiliathaimu, na Sivima, na Nzelethi‐saali kalĩmanĩ ke mwandanĩ,'),
('kam', 'JOS', 13, 20, 'na Mbethiveoli, na ĩvaũũko sya Visika, na Mbethi‐yesimothi,'),
('kam', 'JOS', 13, 21, 'na ndũa syonthe sya ũiĩ, na ũsumbĩko w’onthe wa Sioni mũsumbĩ wa Aamoli, ũla wasumbĩkie ku Esivoni, ũla Mose wakũnie vamwe na anene ma Mitiani, Evi, na Lekemu, na Nzuli, na Uulu, na Leva, ala anene me mbee ũsumbĩnĩ wa Sioni, ala matwĩe nthĩ ĩsu.'),
('kam', 'JOS', 13, 22, 'Mbalaamu nake mwana wa Mbeoli, ũla wathanaa maũndũ, ana ma Isilaeli mamũaa na ũvyũ vamwe na ala angĩ mooaie.'),
('kam', 'JOS', 13, 23, 'Na mũvaka wa ana ma Leuveni waĩ Yolotani, o ngũkanĩ yaw’o. Ũsu waĩ ũtiĩwa wa ana ma Leuveni kwĩanana na mĩvĩa yoo, o ndũa syoo, na mĩsyĩ yoo.'),
('kam', 'JOS', 13, 24, 'Na Mose anenga mbaĩ ya Ngati, o ana ma Ngati, nthĩ kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 13, 25, 'Na mũvaka woo waĩ Yaseli, na ndũa syonthe sya Ngileati, na nyunzu ya nthĩ ya ana ma Amimoni, kũvika Aloeli ĩla yelekele Lava;'),
('kam', 'JOS', 13, 26, 'na kuma Esivoni kũvika Lamathi‐misive, na Mbetonimu; na kuma Maanaimu kũvika mũvaka wa Ndevili;'),
('kam', 'JOS', 13, 27, 'na mwandanĩ, Mbethi‐alamu, na Mbethinimila, na Sũkothi, na Nzavoni, ũtialo wa ũsumbĩko wa Sioni mũsumbĩ wa Esivoni, ku Yolotani ngũkanĩ yaw’o, kũvika mũthelelo wa ũkanga wa Kinelethi mũingo wa Yolotani kwelekela ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JOS', 13, 28, 'Ũsu nĩw’o ũtiĩwa wa ana ma Ngati, ndũa syoo na mĩsyĩ yoo, kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 13, 29, 'Na Mose anenga ĩla nyunzu ya mbaĩ ya Manase ũtiĩwa: na waĩ kwondũ wa ĩla nyunzu ya mbaĩ ya Manase kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 13, 30, 'Na mũvaka woo waĩ kuma Maanaimu, Mbasani yonthe, ũsumbĩko w’onthe wa Oku mũsumbĩ wa Mbasani, na tũtũla tw’onthe twa Yaili tũla twĩ Mbasani, o ndũa mĩongo thanthatũ:'),
('kam', 'JOS', 13, 31, 'na nyunzu ya Ngileati, na Asetalothi, na Atilei, ndũa sya ũsumbĩko wa Oku ku Mbasani, syaĩ sya ana ma Makili mwana wa Manase, o asu nyunzũ ya ana ma Makili kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 13, 32, 'Asu nĩmo motiĩwa ala Mose waaanisye ndiĩnĩ sya Moavi, mũingo wa Yolotani ku Yelĩko, kwelekela ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JOS', 13, 33, 'Ĩndĩ mbaĩ ya Livai Mose ndaamanenga ũtiĩwa: Yeova, Ngai wa Isilaeli, nĩ ũtiĩwa woo, o tondũ wamatavisye.'),
('kam', 'JOS', 14, 1, 'Na asu nĩmo motiĩwa ala ana ma Isilaeli moosie nthĩ ya Kanaani, ala mũthembĩ Eleasali, na Yosua mwana wa Nuni, na atongoi ma nyũmba sya aaĩthe ma mbaĩ sya ana ma Isilaeli, mamaaanisye,'),
('kam', 'JOS', 14, 2, 'kwondũ wa kũlimana kwa ũtiĩwa woo, o tondũ Yeova weaie na kanyw’a wa Mose, kwondũ wa ila mbaĩ kenda, na ĩla nyunzu ya mbaĩ.'),
('kam', 'JOS', 14, 3, 'Nũndũ Mose aĩ anainenga ũtiĩwa mbaĩ ilĩ na nyunzu ya mbaĩ mũingo wa Yolotani: ĩndĩ ndaanenga Alivai ũtiĩwa katĩ woo.'),
('kam', 'JOS', 14, 4, 'Nũndũ ana ma Yosevu maĩ mbaĩ ilĩ, Manase na Evalaimu: na matyaanenga Alivai kĩanda nthĩ ĩsu, ate o ndũa sya kũtũaa, vamwe na syengo syasyo kwondũ wa indo syoo na kwondũ wa kwia syĩndũ syoo.'),
('kam', 'JOS', 14, 5, 'O tondũ Yeova weaĩa Mose, now’o ana ma Isilaeli meekie; na maaan’ya nthĩ.'),
('kam', 'JOS', 14, 6, 'Nivo ĩndĩ ana ma Yuta mathengeeie Yosua ku Ngilikali: na Kalevu mwana wa Yevune Mũkenisi amwĩa, Nĩwĩsĩ ũndũ ũla Yeova wamũtavisye Mose mũndũ wa Ngai ũndũ wakwa na ũndũ waku ku Katesi‐mbalinea.'),
('kam', 'JOS', 14, 7, 'Naĩ wa myaka mĩongo ĩna yĩla Mose mũthũkũmi wa Yeova wandũmie kuma Katesi‐mbalinea nĩthiane ĩ nthĩ; na namũtũngĩa ũvoo o tondũ wailyĩ ngoonĩ yakwa.'),
('kam', 'JOS', 14, 8, 'Ĩndĩ ana‐a‐asa makwa ala mambatie vamwe nakwa matuma ngoo sya andũ itweka: ĩndĩ nyie nĩnamũatĩĩe Yeova Ngai wakwa ki.'),
('kam', 'JOS', 14, 9, 'Na Mose eevĩta mũthenya ũsu, akĩmbĩa, Vate ndĩi, nthĩ ĩla kũũ kwaku kũkinyangĩle ĩkeethĩwa ũtiĩwa waku na wa syana syaku tene na tene, nũndũ nũmũvikĩlĩte Yeova Ngai waku ki.'),
('kam', 'JOS', 14, 10, 'Na yu, sisya, Yeova nũmbĩkalĩtye nĩ thayũ, o tondũ waneenie, myaka ĩno mĩongo ĩna na ĩtano, kuma ĩvinda yĩla Yeova watavisye Mose ndeto ĩno, o yĩla Isilaeli mangangaa weũnĩ: na yu, sisya, ũmũnthĩ nĩ wa myaka mĩongo nyanya na ĩtano.'),
('kam', 'JOS', 14, 11, 'O na yu nĩ na vinya ũmũnthĩ o tondũ naĩ naw’o mũthenya ũla Mose wandũmie: o tondũ vinya wakwa wailyĩ ĩvinda yĩu, now’o vinya wakwa ũilyĩ yu, kwondũ wa kaũ, na kwondũ wa kumaala na kũsyoka.'),
('kam', 'JOS', 14, 12, 'Na ĩndĩ kwondũ wa ũu nenga nthĩ ĩno yĩ iĩma, ĩla Yeova waneenie ũndũ wayo mũthenya ũsu; nũndũ we nĩweewie mũthenya ũsu kana Aanaki maĩ kw’o, na ndũa nene na mbiie: nokwĩthĩwa Yeova akeethĩwa vamwe nakwa, na ngamalũngya, o tondũ Yeova waneenie.'),
('kam', 'JOS', 14, 13, 'Na Yosua amũathima, na amũnenga Kalevu mwana wa Yevune ku Eviloni yĩthĩwe ũtiĩwa.'),
('kam', 'JOS', 14, 14, 'Kwondũ wa ũu Eviloni yatw’ĩka ũtiĩwa wa Kalevu mwana wa Yevune Mũkenisi kũvika ũmũnthĩ; nũndũ nĩwamũatĩĩe ki Yeova, Ngai wa Isilaeli.'),
('kam', 'JOS', 14, 15, 'Na ĩndĩ syĩtwa ya Eviloni tene yeetawa Kiliathi‐aliva; ũsu Aliva aĩ mũndũ mũnene kwĩ onthe katĩ wa Aanaki. Na ĩ nthĩ yathũmũĩa kaũ.'),
('kam', 'JOS', 15, 1, 'Na mũlimano kwondũ wa mbaĩ ya ana ma Yuta kũatĩĩa mĩvĩa yoo waĩ wa kũvika mũvaka wa Etomu, o kũvika weũ wa Nzini kwelekela ngalĩ ya ĩtheo, mũthelelo wa ngalĩ ya ĩtheo.'),
('kam', 'JOS', 15, 2, 'Na mũvaka woo wa ngalĩ ya ĩtheo waĩ kuma mũthelelo wa Ũkanga wa Mũnyũ, kuma kyokonĩ kĩla kyelekele ngalĩ ya ĩtheo;'),
('kam', 'JOS', 15, 3, 'na waumĩla ngalĩ ya ĩtheo ya kyambato kya Akilavimu na, waendeea kũvika Nzini, na wambata ngalĩ ya ĩtheo ya Katesi‐mbalinea, na waendeea vakuvĩ na Esiloni, na wambata kũvika Atali, na weelingĩla kwelekela Kalika;'),
('kam', 'JOS', 15, 4, 'na waendeea kũvika Asimoni na waumĩlĩla kalũsĩnĩ ka Misili; na ũmalĩlo waw’o waĩ ũkanganĩ: ũsu nĩw’o ũkethĩwa mũvaka wenyu wa ngalĩ ya ĩtheo.'),
('kam', 'JOS', 15, 5, 'Na mũvaka wa ngalĩ ya wumĩlonĩ wa syũa waĩ Ũkanga wa Mũnyũ o kũvika mũthelelo wa Yolotani. Na mũvaka wa ngalĩ ya ĩũlũ waĩ kuma kyokonĩ kya ũkanga mũthelelonĩ wa Yolotani;'),
('kam', 'JOS', 15, 6, 'na mũvaka wambata kũvika Mbethi‐okila, na waendeea ngalĩ ya ĩũlũ ya Mbethi‐alava; na mũvaka wambata wavika ĩvia ya Mboanĩ mwana wa Leuvenĩ;'),
('kam', 'JOS', 15, 7, 'na mũvaka wambata kũvika Ndevili kuma mwandanĩ wa Akoli, na ta ũu waendeea kwelekela ngalĩ ya ĩũlũ, kwelekela Ngilikali, ĩla yelekele kyambato kya Atumimu, ĩla yĩ ngalĩ ya ĩtheo ya ũsĩ: na mũvaka waendeea wavika manzĩnĩ ma Eni‐semesi, na umalĩlo waw’o waĩ Eni‐lokeli;'),
('kam', 'JOS', 15, 8, 'na mũvaka wambata waendeea kyandanĩ kya mwana wa Inomu kũvika ngalĩ ya Mũyevusi kwelekela ngalĩ ya ĩtheo (nayo nĩ Yelusaleme); na mũvaka wambata waendeea kũvika mũtumbĩnĩ wa kĩĩma kĩla kĩthengeee kyanda kya Inomu ngalĩ ya ũthũĩlonĩ wa syũa, kĩla kĩ mũthelelo wa mwanda wa Alevai kwelekela ngalĩ ya ĩũlũ;'),
('kam', 'JOS', 15, 9, 'na mũvaka waendeea kuma mũtumbĩnĩ wa kĩĩma kũvika nthongo ya manzĩ ma Nevitoa oa waendeea kũvika ndũa sya kĩĩma kya Eveloni; na mũvaka wavika ku Mbaala (nayo nĩ Kiliathi‐yealimu);'),
('kam', 'JOS', 15, 10, 'na mũvaka weelingĩla kuma Mbaala kwelekela ngalĩ ya ũthũĩlonĩ wa syũa kũvika kĩĩma kya Seili, na waendeea kũvika mũkyamanonĩ wa kĩĩma kya Yealimu kĩla kĩ ngalĩ ya ĩũlũ (nakyo nĩ Kesaloni), na watheea kũvika Mbethi‐semesi, na waendeea vakuvĩ na Timina;'),
('kam', 'JOS', 15, 11, 'na mũvaka waumĩla ũtee wa Ekiloni, kwelekela ngalĩ ya ĩũlũ; na mũvaka wavika Sikeloni, na waendeea wavika kĩĩma kya Mbaala, na waumĩla ku Yavineeli; na umalĩlo waw’o waĩ ũkanganĩ.'),
('kam', 'JOS', 15, 12, 'Na mũvaka wa ngalĩ ya ũthũĩlonĩ wa syũa wavika ũkanga mũnene, na mũvaka waw’o. Ũsu nĩw’o mũvaka wa ana ma Yuta ũthyũlũlũkĩte ngalĩ syonthe kwĩanana na mĩvĩa yoo.'),
('kam', 'JOS', 15, 13, 'Na anenga Kalevu mwana wa Yevune kĩanda katĩ wa ana ma Yuta, o tondũ Yeova wamwĩaĩe Yosua, o Kiliathi‐aliva, Aliva ũsu aĩ ĩthe wa Anaki (nĩyo Eviloni).'),
('kam', 'JOS', 15, 14, 'Na Kalevu alũngya vo ana atatũ ma Anaki: Sesai, na Aimani, na Talimai, ana ma Anaki.'),
('kam', 'JOS', 15, 15, 'Na ambata kw’o okite na andũ ala matwĩe Ndevili: na ĩndĩ syĩtwa ya Ndevili tene yeetawa Kiliathi‐seveli.'),
('kam', 'JOS', 15, 16, 'Na Kalevu asya, Ũla wĩkũna Kiliathi‐seveli, na kũmĩkwata, we ngamũnenga Akisa mwĩĩtu wakwa ethĩwe mũka.'),
('kam', 'JOS', 15, 17, 'Na Othinieli mwana wa Kenasi, mwana‐a‐inyia wa Kalevu, amĩkwata: na amũnenga Akisa mwĩĩtu wake ethĩwe mũka.'),
('kam', 'JOS', 15, 18, 'Na kweethĩwa, yĩla wokie vala ũĩ, amũingĩĩsya avoye ĩthe mũũnda: na auma ĩng’oinĩ yake; na Kalevu amũkũlya, Wĩenda kĩ?'),
('kam', 'JOS', 15, 19, 'Nake amũsũngĩa, Nenga ũathimo; nũndũ nũnenganĩte nthĩ ya ngalĩ ya Ĩtheo, nenga mbuluti sya manzĩ o nasyo. Na amũnenga mbuluti sya ĩũlũ na mbuluti sya ĩtheo.'),
('kam', 'JOS', 15, 20, 'Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Yuta kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 15, 21, 'Na ndũa syĩ ngalĩ ya mũminũkĩlyo sya mbaĩ ya ana ma Yuta kwelekela mũvaka wa Etomu ngalĩ ya Ĩtheo syaĩ Kaviseeli, na Eteli, na Yakuli,'),
('kam', 'JOS', 15, 22, 'na Kina, na Ndimona, na Atata,'),
('kam', 'JOS', 15, 23, 'na Ketesi, na Asoli, na Ithinani,'),
('kam', 'JOS', 15, 24, 'na Nzivu, na Telemu, na Mbealothi,'),
('kam', 'JOS', 15, 25, 'na Asoliaatata, na Keliothi‐esiloni (nayo nĩ Asoli),'),
('kam', 'JOS', 15, 26, 'na Amamu, na Sema, na Molata,'),
('kam', 'JOS', 15, 27, 'na Asali‐ngata, na Esimoni, na Mbethi‐veleti,'),
('kam', 'JOS', 15, 28, 'na Asali‐suali, na Mbeeli‐sieva, na Mbisiothia,'),
('kam', 'JOS', 15, 29, 'na Mbaala, na Iimu, na Esemu,'),
('kam', 'JOS', 15, 30, 'na Elitolati, na Kesili, na Olima,'),
('kam', 'JOS', 15, 31, 'na Nzikilaki, na Matimana, na Sanisana,'),
('kam', 'JOS', 15, 32, 'na Levaothi, na Siliimu, na Aini, na Limoni: ndũa syonthe mĩongo ĩlĩ na kenda, vamwe na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 33, 'Nthĩ ndindimalu kwaĩ Esitaoli, na Nzola, na Asina,'),
('kam', 'JOS', 15, 34, 'na Nzanoa, na Eni‐nganimu, na Tavua, na Enamu,'),
('kam', 'JOS', 15, 35, 'na Yalimuthi, na Atulamu, na Soko, na Aseka,'),
('kam', 'JOS', 15, 36, 'na Saalaimu, na Atithaimu, na Ngetela, na Ngetelothaimu; ndũa ĩkũmi na inya na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 37, 'Nzenani, na Atasa, na Mikitalingati,'),
('kam', 'JOS', 15, 38, 'na Ndileani, na Misiva, na Yokitheeli,'),
('kam', 'JOS', 15, 39, 'na Lakisi na Mbosikathi, na Ekeloni,'),
('kam', 'JOS', 15, 40, 'na Kavoni, na Lamasi, na Kithilisi,'),
('kam', 'JOS', 15, 41, 'na Ngetelothi, na Mbethi‐ndakoni, na Naama, na Maketa; ndũa ĩkũmi na thanthatũ na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 42, 'Livina, na Etheli, na Asani,'),
('kam', 'JOS', 15, 43, 'na Ivita, na Asina, na Nesivu,'),
('kam', 'JOS', 15, 44, 'na Keila, na Akisivu, na Malesa; ndũa kenda na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 45, 'Ekiloni, vamwe na tũtũla twayo na mĩsyĩ yayo;'),
('kam', 'JOS', 15, 46, 'kuma Ekiloni kũvika ũkanga, tw’onthe tũla twaĩ ũtee wa Asitoti vamwe na mĩsyĩ yatw’o.'),
('kam', 'JOS', 15, 47, 'Asitoti, tũtũla twayo na mĩsyĩ yayo; Ngasa, tũtũla twayo na mĩsyĩ yayo; kũvika kalũsĩ ka Misili, na ũkanga mũnene, na mũvaka waw’o.'),
('kam', 'JOS', 15, 48, 'Na nthĩ yĩ iĩma kwaĩ Samili, na Yatili, na Soko,'),
('kam', 'JOS', 15, 49, 'na Ndana, na Kiliathi‐sana (nayo nĩ Ndevili),'),
('kam', 'JOS', 15, 50, 'na Anavu, na Esitemo, na Animu,'),
('kam', 'JOS', 15, 51, 'na Ngoseni, na Oloni, na Ngilo; ndũa ĩkũmi na ĩmwe na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 52, 'Alavu, na Nduma, na Esani,'),
('kam', 'JOS', 15, 53, 'na Yanumu, na Mbethi‐tavua, na Aveka,'),
('kam', 'JOS', 15, 54, 'na Umuta, na Kiliathi‐aliva (nayo nĩ Eviloni), na Nzioli; ndũa kenda na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 55, 'Maoni, na Kalimeli, na Nzivu, na Yute,'),
('kam', 'JOS', 15, 56, 'na Yesileeli, na Yokiteamu, na Nzanoa,'),
('kam', 'JOS', 15, 57, 'na Kaini, na Ngivea, na Timina; ndũa ĩkũmi na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 58, 'Aliuli, na Mbethi‐suli, na Ngetoli,'),
('kam', 'JOS', 15, 59, 'na Maalathi, na Mbethi‐anothi, na Elitekoni; ndũa thanthatũ na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 60, 'Kiliathi‐mbaali (nayo nĩ Kiliathi‐yealimu), na Lava; ndũa ilĩ na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 61, 'Weũnĩ kwaĩ Mbethi‐alava, na Mitini na Sakeka,'),
('kam', 'JOS', 15, 62, 'na Nivisani, na Ndũa ya Mũnyũ, na Eni‐ngeti; ndũa thanthatũ na mĩsyĩ yasyo.'),
('kam', 'JOS', 15, 63, 'Na ũvoo wa Ayevusi, ala matwĩe Yelusaleme, ana ma Yuta matyaatonya kũmalũngya: ĩndĩ Ayevusi matũaa vamwe na ana ma Yuta ku Yelusaleme kũvika ũmũnthĩ.'),
('kam', 'JOS', 16, 1, 'Na mũlimano wambĩlĩla wa ana ma Yosevu kuma Yolotani ku Yeliko, manzĩnĩ ma Yeliko ngalĩ ya wumĩlonĩ wa syũa, o weũnĩ, ũkyambata kuma Yeliko kũvĩtĩla nthĩ yĩ iĩma kũvika Mbethi‐eli:'),
('kam', 'JOS', 16, 2, 'na wauma Mbethi‐eli wavika Lusu, na waendeea kũvika mũvaka wa Aaliiki ku Atalothi;'),
('kam', 'JOS', 16, 3, 'na watheea kwelekela ngalĩ ya ũthũĩlonĩ wa syũa kũvika mũvaka wa Ayavileti, kũvika mũvaka wa Mbethi‐oloni ĩla yĩ ĩtheo, o kũvika Ngeseli, na umalĩlo waw’o waĩ ũkanganĩ.'),
('kam', 'JOS', 16, 4, 'Na ana ma Yosevu, Manase na Evalaimu, moosa ũtiĩwa woo.'),
('kam', 'JOS', 16, 5, 'Na mũvaka wa ana ma Evalaimu kwĩanana na mĩvĩa yoo wailyĩ ũũ: mũvaka wa ũtiĩwa woo kwelekela ngalĩ ya wumĩlonĩ wa syũa waĩ Atalothi‐atali kũvika Mbethi‐oloni ĩla yĩ ĩũlũ;'),
('kam', 'JOS', 16, 6, 'na mũvaka waumĩla kwelekela ngalĩ ya ũthũĩlonĩ wa syũa ku Mikimetha ngalĩ ya ĩũlũ; na mũvaka weelingĩla kwelekela ngalĩ ya wumĩlonĩ wa syũa kũvika Taanathi‐silo, na wavĩtĩla ũtee wayo ngalĩ ya wumĩlonĩ wa syũa ya Yanoa;'),
('kam', 'JOS', 16, 7, 'na watheea kũma Yanoa kũvika Atalothi, na kũvika Naala, na wavika Yeliko, na waumĩlĩla Yolotani.'),
('kam', 'JOS', 16, 8, 'Kuma Tavua mũvaka waendeea kwelekela ngalĩ ya ũthũĩlonĩ wa syũa kũvika kalũsĩ ka Kana; na umalĩlo waw’o waĩ ũkanganĩ. Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Evalaimu kũatĩĩa mĩvĩa yoo;'),
('kam', 'JOS', 16, 9, 'vamwe na ndũa ila ivathĩtwe kwondũ wa ana ma Evalaimu katĩ wa ũtiĩwa wa ana ma Manase, ndũa syonthe na mĩsyĩ yasyo.'),
('kam', 'JOS', 16, 10, 'Na matyaalũngya Akanaani ala matwĩe Ngelesi: ĩndĩ Akanaani matũaa katĩ wa Evalaimu kũvika ũmũnthĩ, na matw’ĩkĩte athũkũmi ma ũtethethaw’a wĩa wa vinya.'),
('kam', 'JOS', 17, 1, 'Na ũu nĩw’o mũlimano kwondũ wa mbaĩ ya Manase; nũndũ aĩ ĩkithathi ya Yosevu. Na ũvoo wa Makili ĩkithathi ya Manase, ĩthe wa Ngileati, nĩkwĩthĩwa aĩ mũndũ wa kaũ, kwondũ wa ũu aĩ na nthĩ sya Ngileati na Mbasani.'),
('kam', 'JOS', 17, 2, 'Kwondũ wa ũu mũlimano waĩ kwondũ wa ana ala angĩ ma Manase kũatĩĩa mĩvĩa yoo: kwondũ wa ana ma Avieseli, na kwondũ wa ana ma Eleki, na kwondũ wa ana ma Asilieli, na kwondũ wa ana ma Sekemu, na kwondũ wa ana ma Eevieli, na kwondũ wa ana ma Semita: asu maĩ ana aũme ma Manase mwana wa Yosevu kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 17, 3, 'Ĩndĩ Nzeloveati, mwana wa Eevieli, mwana wa Ngileati, mwana wa Makili, mwana wa Manase, ndaĩ na ana ma aũme, ate o eĩtu: na aa nĩo masyĩtwa ma eĩtu make: Maala, na Noa, na Okila, na Milika, na Tilisa.'),
('kam', 'JOS', 17, 4, 'Na mamũthengeea mũthembi Eleasali, na Yosua mwana wa Nuni, na anene, makyasya, Yeova amwĩaĩa Mose atũnenge ũtiĩwa katĩ wa ana‐a‐asa maitũ: kwondũ wa ũu kwĩanana na mwĩao wa Yeova amanenga ũtiĩwa katĩ wa ana ma ĩthe woo.'),
('kam', 'JOS', 17, 5, 'Na ianda ĩkũmi syamũvalũkĩla Manase, eka nthĩ ya Ngileati na Mbasani, ĩla yĩ mũingo wa Yolotani;'),
('kam', 'JOS', 17, 6, 'nũndũ eĩtu ma Manase maĩ na ũtiĩwa katĩ wa ana aũme make. Na nthĩ ya Ngileati yaĩ ya ana ala angĩ ma Manase.'),
('kam', 'JOS', 17, 7, 'Na mũvaka wa Manase waĩ kuma Aseli kũvika Mikemetha, ĩla yelekele Sekemu, na mũvaka waendeea kwelekela ngalĩ ya kw’oko kwa aũme, kũvika ala matwĩe Eni‐tavua.'),
('kam', 'JOS', 17, 8, 'Nthĩ ya Tavua yaĩ ya Manase; ĩndĩ Tavua mũvakanĩ wa Manase yaĩ ya ana ma Evalaimu.'),
('kam', 'JOS', 17, 9, 'Na mũvaka watheea kũvika kalũsĩ ka Kana, kwelekela ngalĩ ya ĩtheo ya kalũsĩ: ndũa isu syaĩ sya Evalaimu katĩ wa ndũa sya Manase: na mũvaka wa Manase waĩ ngalĩ ya ĩũlũ ya kalũsĩ, na umalĩlo waw’o waĩ ũkanganĩ:'),
('kam', 'JOS', 17, 10, 'kwelekela ngalĩ ya ĩtheo yaĩ ya Evalaimu, na kwelekela ngalĩ ya ĩũlũ yaĩ ya Manase, na ũkanga waĩ mũvaka wake; na mavika Aseli ngalĩ ya ĩũlũ, na Isakali ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JOS', 17, 11, 'Na nthĩnĩ wa Isakali na Aseli, Manase aĩ na Mbethi‐seani na tũtũla twayo, na Ivileamu na tũtũla twayo, na ala matwĩe Ndoli na tũtũla twayo, na ala matwĩe Eni‐ndoli na tũtũla twayo, na ala matwĩe Taanaki na tũtũla twayo, na ala matwĩe Mekito na tũtũla twayo, o kũndũ kũtatũ kũtũlu.'),
('kam', 'JOS', 17, 12, 'Ĩndĩ ana ma Manase matyaatonya kũlũngya ala matwĩe ndũanĩ isu; ĩndĩ Akanaani meevinyĩlĩlya nthĩ ĩsu.'),
('kam', 'JOS', 17, 13, 'Na kweethĩwa, yĩla ana ma Isilaeli mongelekile vinya, mamatethethya Akanaani wĩa wa vinya, na matyaamalũngya vyũ.'),
('kam', 'JOS', 17, 14, 'Na ana ma Yosevu maneena na Yosua, makĩmũkũlya, Nũndũ wa kĩ ũnengete mũlimano ũmwe na kĩanda kĩmwe syĩthĩwe ũtiĩwa, nũndũ nyie nĩ mbaĩ nene, nũndũ kũvika yu Yeova nũngathimĩte?'),
('kam', 'JOS', 17, 15, 'Na Yosua amea, Ethĩwa wĩ mbaĩ nene, ambata mũtitũnĩ, ũkeyengee kw’o nthĩ ya Mũvelisi na Mũlevai; nũndũ nthĩ yĩ iĩma ya Evalaimu nĩ ntheke kwaku.'),
('kam', 'JOS', 17, 16, 'Na ana ma Yosevu masya, Nthĩ yĩ iĩma ndĩtwĩanĩa: na Akanaani onthe ala matwĩe nthĩ ya mwanda me na makasya ma iaa, o ala me Mbethi‐seani na tũtũla twayo, na ala me mwandanĩ wa Yesileeli.'),
('kam', 'JOS', 17, 17, 'Na Yosua aneena na nyũmba ya Yosevu, o Evalaimu na Manase, akĩmĩtavya, We wĩ mbaĩ nene, na wĩ na vinya mwingĩ; ndũkethĩwa na mũlimano ũmwe w’oka:'),
('kam', 'JOS', 17, 18, 'ĩndĩ nthĩ yĩ iĩma ĩkeethĩwa yaku; nũndũ o na kau nĩ mũtitũ, ũkootemanga, na umalĩlo waw’o ũkeethĩwa waku; nũndũ ũkalũngya Akanaani, o na kau me na makasya ma iaa, o na ethĩwa me na vinya.'),
('kam', 'JOS', 18, 1, 'Na ũmbano w’onthe wa Isilaeli woombana ku Silo, na mamba ĩeema ya kũmbanĩa kw’o: na nthĩ yakĩlw’a vinya mbee woo.'),
('kam', 'JOS', 18, 2, 'Na kwatiala katĩ wa ana ma Isilaeli mbaĩ mũonza, ila itambĩte kũaan’ya ũtiĩwa wasyo.'),
('kam', 'JOS', 18, 3, 'Na Yosua akũlya ana ma Isilaeli, Mũkeethĩwa mwĩ aleelu ĩvinda yĩana ata ũndũ wa kũlika mũmĩmesye nthĩ, ĩla Yeova, Ngai wa aaĩthe menyu, ũmũnengete?'),
('kam', 'JOS', 18, 4, 'Ĩyiĩei andũ atatũ ma kĩla mbaĩ: na ngamatũma, na makyũkĩla, na kũtambũka katĩ wa nthĩ, na kũandĩka ũndũ ũilyĩ ũtiĩwa woo; na makanzyokee.'),
('kam', 'JOS', 18, 5, 'Na makamĩaan’ye ianda mũonza: Yuta ĩkekala mũvakanĩ wayo ngalĩ ya ĩtheo, na nyũmba ya Yosevu ĩkekala mũvakanĩ wayo ngalĩ ya ĩũlũ.'),
('kam', 'JOS', 18, 6, 'Na mũkaandĩke nthĩ ĩaanĩtw’e ianda mũonza, na kũndetee maandĩko mayo; na ngalimana kwondũ wenyu vaa kũla kwĩ Yeova Ngai waitũ.'),
('kam', 'JOS', 18, 7, 'Nũndũ Alivai mati na kĩanda katĩ wenyu; nũndũ ũthembi wa Yeova nĩw’o ũtiĩwa woo: na Ngati na Leuveni na nyunzu ya mbaĩ ya Manase nĩmosete ũtiĩwa woo mũingo wa Yolotani kweleleka ngalĩ ya wumĩlonĩ wa syũa, ũla Mose mũthũkũmi wa Yeova wamanengie.'),
('kam', 'JOS', 18, 8, 'Na andũ asu mookĩla na mathi: na Yosua ameaĩa ala maendie kũandĩka nthĩ, akĩmea, Endai mũvĩtĩle katĩ wa nthĩ, na mũmĩandĩke, na mũinzyokea; na ngalimana kwondũ wenyu vaa Silo kũla kwĩ Yeova.'),
('kam', 'JOS', 18, 9, 'Na andũ mathi na mavĩtĩla katĩ wa nthĩ, na mamĩandĩka ndũa syayo ianda mũonza ĩvukunĩ; na mamũsyokea Yosua mwakonĩ wa maeema ku Silo.'),
('kam', 'JOS', 18, 10, 'Na Yosua alimana kwondũ woo ku Silo kũla kwĩ Yeova; na kw’o Yosua amaaan’ya ana ma Isilaeli nthĩ kwĩanana na ũndũ maaanĩtye.'),
('kam', 'JOS', 18, 11, 'Na mũlimano wa mbaĩ ya ana ma Mbenyamini waumĩla kũatĩĩa mĩvĩa yoo: na mũvaka wa mũlimano woo waumĩla katĩ wa ana ma Yuta na ana ma Yosevu.'),
('kam', 'JOS', 18, 12, 'Na mũvaka woo wa ngalĩ ya ĩũlũ waĩ kuma Yolotani; na mũvaka wambata ũtee wa Yeliko ngalĩ ya ĩũlũ, na wambata wavĩta katĩ wa nthĩ yĩ iĩma kwelekela ũthũĩloni wa syũa; na umalĩlo waw’o waĩ weũnĩ wa Mbethi‐aveni.'),
('kam', 'JOS', 18, 13, 'Na mũvaka waendeea kuma vau kũvika Lusu, ũtee wa Lusu (nayo nĩ Mbethi‐eli), kwelekela ngalĩ ya ĩtheo; na mũvaka watheea kũvika Atalothi‐atali, vakuvĩ na kĩĩma kĩla kĩ ngalĩ ya ĩtheo ya Mbethi‐oloni ĩla yĩ ĩtheo.'),
('kam', 'JOS', 18, 14, 'Na mũvaka waendeea kuma vau, na weelingĩla kĩlungunĩ kya ngalĩ ya wumĩlonĩ wa syũa kwelekela ngalĩ ya ĩtheo, kuma kĩĩma kĩla kĩthengeee Mbethi‐oloni kwelekela ngalĩ ya ĩtheo, umalĩlo waw’o waĩ Kiliathi‐mbaali (nayo nĩ Kiliathi‐yealimu), ndũa ya ana ma Yuta: nĩyo kĩlungu kya ngalĩ ya ũthũĩlonĩ wa syũa.'),
('kam', 'JOS', 18, 15, 'Na kĩlungu kya ngalĩ ya ĩtheo kyaĩ kuma mũthelelo wa Kiliathi‐yealimu; na mũvaka waumĩla kwelekela ngalĩ ya ũthũĩlonĩ wa syũa, na waumĩla wavika nthongonĩ ya manzĩ ma Nevitoa;'),
('kam', 'JOS', 18, 16, 'na mũvaka watheea kũvika mũthelelo wa kĩĩma kĩla kyelekele kyanda kya mwana wa Inomu, kĩla kĩ mwandanĩ wa Alevai kwelekela ngalĩ ya ĩũlũ; na watheea kũvika kyanda kya Inomu, ũtee wa Mũyevusi kwelekela ngalĩ ya ĩtheo, na watheea wavika Eni‐lokeli;'),
('kam', 'JOS', 18, 17, 'na waendeea kwelekela ngalĩ ya ĩũlũ, na waumĩla ku Eni‐semesi, na waendeea kũvika Ngelilothi, ĩla yelekele kyambato kya Atumimu; na watheea wavika ĩvia ya Mboani mwana wa Leuveni;'),
('kam', 'JOS', 18, 18, 'na wavĩtĩla ũtee kwelekela Alava kwelekela ngalĩ ya ĩũlũ, na watheea kũvika Alava;'),
('kam', 'JOS', 18, 19, 'na mũvaka waendeea kũvika ũtee wa Mbethi‐okila kwelekela ngalĩ ya ĩũlũ; na umalĩlo wa mũvaka waĩ kyokonĩ kya ngalĩ ya ĩũlũ kya Ũkanga wa Mũnyũ, mũthelelo wa ĩtheo wa Yolotani: ũsu nĩw’o mũvaka wa ngalĩ ya ĩtheo.'),
('kam', 'JOS', 18, 20, 'Na Yolotani waĩ mũvaka wayo kĩlungunĩ kya ngalĩ ya wumĩlonĩ wa syũa. Ũsu waĩ ũtiĩwa wa ana ma Mbenyamini, kwĩanana na mĩvaka yaw’o ĩla ĩthyũlũlũkĩte, kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 18, 21, 'Na ĩndĩ ndũa sya mbaĩ ya ana ma Mbenyamini kũatĩĩa mĩvĩa yoo syaĩ Yeliko, na Mbethi‐okila, na Emeki‐kesisi,'),
('kam', 'JOS', 18, 22, 'na Mbethi‐alava, na Nzemalaimu, na Mbethi‐eli,'),
('kam', 'JOS', 18, 23, 'na Aavi, na Vala, na Ovala,'),
('kam', 'JOS', 18, 24, 'na Kevali‐amimoni, na Oveni, na Ngeva; ndũa ĩkũmi na ilĩ na mĩsyĩ yasyo:'),
('kam', 'JOS', 18, 25, 'na Ngiveoni, na Lama, na Mbeelothi,'),
('kam', 'JOS', 18, 26, 'na Misiva, na Kevila, na Moosa,'),
('kam', 'JOS', 18, 27, 'na Lekemu, na Iliveeli, na Talala,'),
('kam', 'JOS', 18, 28, 'na Nzeela, na Elevu, na Mũyevusi (nayo nĩ Yelusaleme), na Ngiveathi, na Kiliathi; ndũa ĩkũmi na ĩnya na mĩsyĩ yasyo. Ũsu nĩw’o ũtiĩwa wa ana ma Mbenyamini kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 1, 'Na mũlimano wa kelĩ waumĩla wa Simeoni, o kwondũ wa mbaĩ ya ana ma Simeoni kũatĩĩa mĩvĩa yoo: na ũtiĩwa woo waĩ katĩ wa ũtiĩwa wa ana ma Yuta.'),
('kam', 'JOS', 19, 2, 'Na ũtiĩwa woo waĩ Mbeeli‐sieva, kana Sieva, na Molata,'),
('kam', 'JOS', 19, 3, 'na Asali‐suali, na Mbala, na Esemu,'),
('kam', 'JOS', 19, 4, 'na Elitolati, na Mbethuli, na Olima,'),
('kam', 'JOS', 19, 5, 'na Nzikilaki, na Mbethi‐malikavothi, na Asali‐susa,'),
('kam', 'JOS', 19, 6, 'na Mbethi‐levaothi, na Salueni; ndũa ĩkũmi na itatũ na mĩsyĩ yasyo:'),
('kam', 'JOS', 19, 7, 'na Aini, na Limoni, na Etheli, na Asani; ndũa inya na mĩsyĩ yasyo:'),
('kam', 'JOS', 19, 8, 'na mĩsyĩ yonthe ĩla ĩthyũlũlũkĩte ndũa isu kũvika Mbaalathi‐mbeeli, Lama ya ngalĩ ya ĩtheo. Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Simeoni kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 9, 'Ũtiĩwa wa ana ma Simeoni waĩ kuma kĩlungunĩ kya ana ma Yuta; nũndũ kĩanda kya ana ma Yuta kyaĩ kĩnene kwoo: kwondũ wa ũu ana ma Simeoni maĩ na ũtiĩwa katĩ wa ũtiĩwa woo.'),
('kam', 'JOS', 19, 10, 'Na mũlimano wa katatũ waumila wa ana ma Nzevuluni kũatĩĩa mĩvĩa yoo. Na mũvaka wa ũtiĩwa woo wavika Saliti;'),
('kam', 'JOS', 19, 11, 'na mũvaka woo wambata kwelekela ngalĩ ya ũthũĩlonĩ wa syũa, o kũvika Malala, na wavika Ndavesethi; na wavika kalũsĩ kala kathengeee Yokineamu:'),
('kam', 'JOS', 19, 12, 'na weelingĩla kuma Saliti kwelekela ngalĩ ya wumĩlonĩ wa syũa kwelekela vala syũa yumĩlaa kũvika mũvaka wa Kisilothi‐tavoli; na waumĩla wavika Ndavelathi, na wambata kũvika Yavia;'),
('kam', 'JOS', 19, 13, 'na kuma vau waendeea kwelekela wumĩlonĩ wa syũa kũvika Ngathi‐eevieli, kũvika Ethi‐kasini; na waumĩlĩla ku Limoni ũla ũvikĩte Nea;'),
('kam', 'JOS', 19, 14, 'na mũvaka wamĩthyũlũlũka ngalĩ ya ĩũlũ yayo kũvika Anathoni; na umalĩlo waw’o waĩ mwandanĩ wa Ivita‐eli;'),
('kam', 'JOS', 19, 15, 'na Katathi, na Naalali, na Similoni, na Itala, na Mbethi‐leemu: ndũa ĩkũmi na ilĩ na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 16, 'Ũsu nĩw’o ũtiĩwa wa ana ma Nzevuluni kũatĩĩa mĩvĩa yoo, ndũa ĩsu na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 17, 'Mũlimano wa kana waumĩla wa Isakali, o kwondũ wa ana ma Isakali, kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 18, 'Na mũvaka woo wavika Yesileeli, na Kesulothi, na Sunemu,'),
('kam', 'JOS', 19, 19, 'na Avalaimu, na Siioni, na Anaalathi,'),
('kam', 'JOS', 19, 20, 'na Lavithi, na Kisioni, na Evesu,'),
('kam', 'JOS', 19, 21, 'na Lemethi, na Eni‐nganimu, na Eni‐aata, na Mbethi‐vasesi,'),
('kam', 'JOS', 19, 22, 'na mũvaka wavika Tavoli, na Saasima, na Mbethi‐semesi; na umalĩlo wa mũvaka woo waĩ Yolotani; ndũa ĩkũmi na thanthatũ na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 23, 'Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Isakali kũatĩĩa mĩvĩa yoo, ndũa na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 24, 'Na mũlimano wa katano waumĩla wa mbaĩ ya ana ma Aseli kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 25, 'Na mũvaka woo waĩ Elikathi, na Aali, na Mbeteni, na Akisavu,'),
('kam', 'JOS', 19, 26, 'na Alamelekĩ, na Amati, na Misaali; na wavika Kalimeli kwelekela ngalĩ ya ũthũĩlonĩ wa syũa, na kũvika Siolilivinathi;'),
('kam', 'JOS', 19, 27, 'na weelelũka welekela wumĩlonĩ wa syũa kũvika Mbethi‐ndakoni, na wavika Nzevuluni, na wavika mwanda wa Ivita‐eli kwelekela ngalĩ ya ĩũlũ kũvika Mbethi‐emeki na Neieli; na waumĩla ku Kavuli ngalĩ ya kw’oko kwa aka,'),
('kam', 'JOS', 19, 28, 'na Eviloni, na Leovu, na Amumoni, na Kana, o kũvika Sitoni ĩla nene;'),
('kam', 'JOS', 19, 29, 'na mũvaka weelelũka kũvika Lama, na kũvika ndũa mbiie ya Tile; na mũvaka weelelũka kũvika Osa; na umalĩlo waw’o waĩ ũkanganĩ vakuvĩ na nthĩ ya Akisivu;'),
('kam', 'JOS', 19, 30, 'o na Uma, na Aveki, na Leovu: ndũa mĩongo ĩlĩ na ilĩ na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 31, 'Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Aseli kũatĩĩa mĩvĩa yoo, ndũa isu na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 32, 'Mũlimano wa thanthatũ waumĩla wa ana ma Navitali, o kwondũ wa ana ma Navitali kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 33, 'Na mũvaka woo waĩ kuma Elevi, kuma mũtĩ wa mwaloni wĩ Nzananimu, na Atami‐nekevu, na Yavineeli, kũvika Lakumu; na umalĩlo waw’o waĩ Yolotani;'),
('kam', 'JOS', 19, 34, 'na mũvaka weelelũka kwelekela ngalĩ ya ũthũĩlonĩ wa syũa kũvika Asinothitavoli, na waumĩla vau kũvika Ukoki; na wavika Nzevuluni ngalĩ ya ĩtheo, na wavika Aseli ngalĩ ya ũthũĩlonĩ wa syũa, na kũvika Yuta ku Yolotani kwelekela wumĩlonĩ wa syũa.'),
('kam', 'JOS', 19, 35, 'Na ndũa mbiie sya Nzitimu, na Seli, na Amimathi, na Lakathi, na Kinelethi,'),
('kam', 'JOS', 19, 36, 'na Atama, na Lama, na Asoli,'),
('kam', 'JOS', 19, 37, 'na Ketesi, na Etilei, na Eni‐asoli,'),
('kam', 'JOS', 19, 38, 'na Iloni, na Mikitali‐eli, na Olemu, na Mbethi‐anathi, na Mbethi‐semesi; ndũa ĩkũmi na kenda na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 39, 'Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Navitali kũatĩĩa mĩvĩa yoo, ndũa isu na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 40, 'Mũlimano wa mũonza waumĩla wa mbaĩ ya ana ma Ndani kũatĩĩa mĩvĩa yoo.'),
('kam', 'JOS', 19, 41, 'Na mũvaka wa ũtiĩwa woo waĩ Nzola, na Esitaoli, na Ilisemesi,'),
('kam', 'JOS', 19, 42, 'na Saalavini, na Aiyaloni, na Ithila,'),
('kam', 'JOS', 19, 43, 'na Eloni, na Timina, na Ekiloni,'),
('kam', 'JOS', 19, 44, 'na Eliteke, na Ngivethoni, na Mbaalathi,'),
('kam', 'JOS', 19, 45, 'na Yeuti, na Mbene‐mbelaki, na Ngathi‐limoni,'),
('kam', 'JOS', 19, 46, 'na Me‐yalikoni, na Lakoni, vamwe na mũvaka ũla wĩ vakuvĩ Yova.'),
('kam', 'JOS', 19, 47, 'Na mũvaka wa ana ma Ndani waumĩla mbee woo: nũndũ ana ma Ndani mambata na mokita na Lesemu, na mamĩkwata, na mamĩkũna kwa kũtemanga na ũvyũ, na mamĩmesya, na mekala kw’o, na mamĩta Lesemu, Ndani, o ta syĩtwa ya ĩthe woo Ndani.'),
('kam', 'JOS', 19, 48, 'Ũsu nĩw’o ũtiĩwa wa mbaĩ ya ana ma Ndani kũatĩĩa mĩvĩa yoo, ndũa isu na mĩsyĩ yasyo.'),
('kam', 'JOS', 19, 49, 'O ta ũu mamina kũaan’ya nthĩ kwondũ wa ũtiĩwa kũatĩĩa mĩvaka yayo; na ana ma Isilaeli manenga Yosua wa Nunĩ ũtiĩwa katĩ woo:'),
('kam', 'JOS', 19, 50, 'kwĩanana na mwĩao wa Yeova mamũnenga ndũa ĩla wetisye, o Timinathi‐selaa yĩ nthĩ yĩ iĩma ya Evalaimu; na aaka ndũa ĩsu, na atũa nthĩnĩ wayo.'),
('kam', 'JOS', 19, 51, 'Asu nĩmo motiĩwa ala mũthembi Eleasali na Yosua mwana wa Nuni, na atongoi ma nyũmba sya aaĩthe ma mbaĩ sya ana ma Isilaeli, maaanisye kwa kũlimana ku Silo kũla kwĩ Yeova, mũomonĩ wa ĩeema ya kũmbanĩa, methĩwe motiĩwa. O ta ũu mamina kũaan’ya nthĩ.'),
('kam', 'JOS', 20, 1, 'Na Yeova aneena na Yosua, akĩmwĩa,'),
('kam', 'JOS', 20, 2, 'Neena na ana ma Isilaeli, ũkĩmea, Ĩyiĩei ndũa sya kwĩvitha ila naneenie nenyu ũndũ wasyo na kanyw’a wa Mose,'),
('kam', 'JOS', 20, 3, 'nĩ kana mũndũ ũla ũkoaa mũndũ o na wĩva na mbanga na atesĩ akĩĩe vo: na ikeethĩawa kwenyu kwondũ wa kũmwĩvitha mũĩvanĩsya wa nthakame.'),
('kam', 'JOS', 20, 4, 'Nake akakĩĩa ndũa ĩmwe ya isu, na akaũngama ũlikĩlonĩ mbingĩlonĩ ya ndũa, na kũtavan’ya ũvoo wake matũnĩ ma atumĩa ma ndũa ĩsu; nao makamwosa nthĩnĩ wa ndũa vala maĩ, na kũmũnenga vandũ, nĩ kana ekalae katĩ woo.'),
('kam', 'JOS', 20, 5, 'Na ethĩwa mũĩvanĩsya wa nthakame akamũatĩĩa, matikamũnengane ũla wũaĩte mũndũ kw’okonĩ kwake; nĩkwĩthĩwa nĩwoaie mũtũi wake atesĩ, na ndatwĩe e ũthũ nake.'),
('kam', 'JOS', 20, 6, 'Nake akekalaa ndũanĩ ĩsu, kũvika o yĩla ũkaũngama mbee wa ũmbano asilĩlwe, kũvika yĩla ũla ũkethĩwa mũthembi mũnene mĩthenya ĩsu ũkakw’a: nĩvo ĩndĩ ũla woaie mũndũ akasyoka na kũvika ndũa yake mwene, na nyũmba yake mwene, kũvika ndũa ĩla waumie yĩla wakĩie.'),
('kam', 'JOS', 20, 7, 'Na mavatha Ketesi ĩla yĩ Ngalilii yĩ nthĩ yĩ iĩma ya Navitali, na Sekemu yĩ nthĩ yĩ iĩma ya Evalaimu, na Kiliathi‐aliva (nayo nĩ Eviloni) yĩ nthĩ yĩ iĩma ya Yuta.'),
('kam', 'JOS', 20, 8, 'Na mũingo wa Yolotani ku Yeliko kwelekela ngalĩ ya wumĩlonĩ wa syũa, mavatha Mbeseli ĩla yĩ weũnĩ ũiĩnĩ kuma mbaĩnĩ ya Leuveni, na Lamothi yĩ Ngileati kuma mbaĩnĩ ya Ngati, na Ngolani yĩ Mbasani kuma mbaĩnĩ ya Manase.'),
('kam', 'JOS', 20, 9, 'Isu syaĩ ndũa ivathĩtwe kwondũ wa ana onthe ma Isilaeli, na kwondũ wa mũeni ũla wĩkalaa ũeni katĩ woo, nĩ kana o ũla ũkoaa mũndũ o na wĩva na mbanga nũtonya kũkĩĩa vo, ndakoawe nĩ kw’oko kwa mũĩvanĩsya wa nthakame, atanamba kũũngama mbee wa ũmbano.'),
('kam', 'JOS', 21, 1, 'Na ĩndĩ atongoi ma nyũmba sya aaĩthe ma Alivai mamũkĩa mũthembi Eleasali, na Yosua mwana wa Nuni, na atongoi ma nyũmba sya aaĩthe ma mbaĩ sya ana ma Isilaeli;'),
('kam', 'JOS', 21, 2, 'na maneenea nao ku Silo nthĩ ya Kanaani, makĩmea, Yeova eaie na kanyw’a wa Mose tũnengwe ndũa sya kũtũaa, vamwe na syengo syasyo kwondũ wa indo sitũ.'),
('kam', 'JOS', 21, 3, 'Na ana ma Isilaeli manenga Alivai kuma ũtiĩwanĩ woo ndũa ii vamwe na syengo syasyo, o tondũ Yeova weaie.'),
('kam', 'JOS', 21, 4, 'Na mũlimano waumĩla wa mĩvĩa ya Akoathi: na ana ma mũthembi Aluni, ala maĩ ma Alivai, moosa kwa kũlimana kuma mbaĩnĩ ya Yuta, na kuma mbaĩnĩ ya Asimeoni, na kuma mbaĩnĩ ya Mbenyamini, ndũa ĩkũmi na itatũ.'),
('kam', 'JOS', 21, 5, 'Na ana ala angĩ ma Koathi moosa kwa kũlimana kuma mĩvĩanĩ ya mbaĩ ya Evalaimu, na kuma mbaĩnĩ ya Ndani, na kuma nyunzunĩ ya mbaĩ ya Manase, ndũa ĩkũmi.'),
('kam', 'JOS', 21, 6, 'Na ana ma Ngelisoni moosa kwa kũlimana kuma mĩvĩanĩ ya mbaĩ ya Isakali, na kuma mbaĩnĩ ya Aseli, na kuma mbaĩnĩ ya Navitali, na kuma myunzunĩ ya mbaĩ ya Manase yĩ Mbasani, ndũa ĩkũmi na itatũ.'),
('kam', 'JOS', 21, 7, 'Ana ma Melali kũatĩĩa mĩvĩa yoo moosa kuma mbaĩnĩ ya Leuveni, na kuma mbaĩnĩ ya Ngati, na kuma mbaĩnĩ ya Nzevuluni, ndũa ĩkũmi na ilĩ.'),
('kam', 'JOS', 21, 8, 'Na ana ma Isilaeli kwa kũlimana manenga Alivai ndũa isu vamwe na syengo syasyo, o tondũ Yeova weaie na kanyw’a wa Mose.'),
('kam', 'JOS', 21, 9, 'Na manengane kuma mbaĩnĩ ya ana ma Yuta, na kuma mbaĩnĩ ya ana ma Simeoni, ndũa ii ila ikũwetwa vaa na masyĩtwa masyo:'),
('kam', 'JOS', 21, 10, 'na syaĩ kwondũ wa ana ma Aluni, ma mĩvĩa ya Akoathi, ala maĩ ma ana ma Livai; nũndũ mũlimano wa mbee waĩ woo.'),
('kam', 'JOS', 21, 11, 'Na mamanenga Kiliathi‐aliva, Aliva ũsu aĩ ĩthe wa Anaki (nĩyo Eviloni), yĩ nthĩ yĩ iĩma ya Yuta, vamwe na syengo syayo ila imĩthyũlũlũkĩte.'),
('kam', 'JOS', 21, 12, 'Ĩndĩ isesi sya ndũa, na mĩsyĩ yayo, mamũnenga Kalevu mwana wa Yevune syĩthĩwe ng’ũndũ yake.'),
('kam', 'JOS', 21, 13, 'Na manenga ana ma mũthembi Alinu Eviloni na syengo syayo, ndũa ya kwĩvitha kwondũ wa ũla ũkoaa mũndũ, na Livina na syengo syayo,'),
('kam', 'JOS', 21, 14, 'na Yatili na syengo syayo, na Esitemoa na syengo syayo,'),
('kam', 'JOS', 21, 15, 'na Oloni na syengo syayo, na Ndevili na syengo syayo,'),
('kam', 'JOS', 21, 16, 'na Aini na syengo syayo, na Yute na syengo syayo, na Mbethi‐semesi na syengo syayo; ndũa kenda kuma mbaĩnĩ isu ilĩ.'),
('kam', 'JOS', 21, 17, 'Na kuma mbaĩnĩ ya Mbenyamini, Ngiveoni na syengo syayo, na Ngeva na syengo syayo,'),
('kam', 'JOS', 21, 18, 'na Anathothi na syengo syayo, na Alimoni na syengo syayo, ndũa inya.'),
('kam', 'JOS', 21, 19, 'Ndũa syonthe sya ana ma Alini, ala athembi, syaĩ ndũa ĩkũmi na itatũ na syengo syasyo.'),
('kam', 'JOS', 21, 20, 'Na mĩvĩa ya ana ma Koathi, Alivai, o ana ala angĩ ma Koathi, nĩmoosie ndũa sya mũlimano woo mbaĩnĩ ya Evalaimu.'),
('kam', 'JOS', 21, 21, 'Nao mamanenga Sekemu na syengo syayo yĩ nthĩ yĩ iĩma ya Evalaimu, ndũa ya kwĩvitha kwondũ wa ũla ũkoaa mũndũ, na Ngeseli na syengo syayo,'),
('kam', 'JOS', 21, 22, 'na Kivisaimu na syengo syayo, na Mbethi‐oloni na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 23, 'Na kuma mbaĩnĩ ya Ndani, Eliteke na syengo syayo, na Ngivethoni na syengo syayo,'),
('kam', 'JOS', 21, 24, 'na Aĩyaloni na syengo syayo, na Ngathi‐limoni na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 25, 'Na kuma nyunzunĩ ya mbaĩ ya Manase, Taanaki na syengo syayo, na Ngathi‐limoni na syengo syayo; ndũa ilĩ.'),
('kam', 'JOS', 21, 26, 'Ndũa syonthe sya mĩvĩa ya ana ala angĩ ma Koathi syaĩ ĩkũmi vamwe na syengo syasyo.'),
('kam', 'JOS', 21, 27, 'Na manenga ana ma Ngelisoni, ma mĩvĩa ya Alivai, kuma nyunzunĩ ya mbaĩ ya Manase, Ngolani yĩ Mbasani na syengo syayo, ndũa ya kwĩvitha kwondũ wa ũla ũkoaa mũndũ, na Mbeesitela na syengo syayo; ndũa ilĩ.'),
('kam', 'JOS', 21, 28, 'Na kuma mbaĩnĩ ya Isakali, Kisioni na syengo syayo, na Ndavelathi na syengo syayo,'),
('kam', 'JOS', 21, 29, 'na Yalimuthi na syengo syayo, na Eni‐nganimu na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 30, 'Na kuma mbaĩnĩ ya Aseli, Misaali na syengo syayo, na Avitoni na syengo syayo,'),
('kam', 'JOS', 21, 31, 'na Elikathi na syengo syayo, na Leovu na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 32, 'Na kuma mbaĩnĩ ya Navitali, Ketesi yĩ Ngalilii na syengo syayo, ndũa ya kwĩvitha kwondũ wa ũla ũkoaa mũndũ, na Amothi‐ndoli na syengo syayo, na Kalitani na syengo syayo; ndũa itatũ.'),
('kam', 'JOS', 21, 33, 'Ndũa syonthe sya Angelisoni kũatĩĩa mĩvĩa yoo syaĩ ndũa ĩkũmi na itatũ na syengo syasyo.'),
('kam', 'JOS', 21, 34, 'Na mĩvĩa ya ana ma Milali, ala angĩ ma Alivai, manengwa kuma mbaĩnĩ ya Nzevuluni, Yokineamu na syengo syayo, na Kalita na syengo syayo,'),
('kam', 'JOS', 21, 35, 'na Ndimina na syengo syayo, na Naalali na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 36, 'Na kuma mbaĩnĩ ya Leuveni, Mbeseli na syengo syayo, na Yaasa na syengo syayo,'),
('kam', 'JOS', 21, 37, 'na Ketemothi na syengo syayo, na Mevaathi na syengo syayo; ndũa inya.'),
('kam', 'JOS', 21, 38, 'Na kuma mbaĩnĩ ya Ngati, Lamothi yĩ Ngileati na syengo syayo, ndũa ya kwĩvitha kwondũ wa ũla ũkoaa mũndũ, na Maanaimu na syengo syayo,'),
('kam', 'JOS', 21, 39, 'na Esivoni na syengo syayo, na Yaseli na syengo syayo; syonthe ndũa inya.'),
('kam', 'JOS', 21, 40, 'Isu syonthe syaĩ ndũa sya ana ma Melali kũatĩĩa mĩvĩa yoo, o mĩvĩa ĩla ĩngĩ ya Alivai; na mũlimano woo waĩ ndũa ĩkũmi na ilĩ.'),
('kam', 'JOS', 21, 41, 'Ndũa syonthe sya Alivai katĩ wa ng’ũndũ sya ana ma Isilaeli syaĩ mĩongo ĩna na nyanya na syengo syasyo.'),
('kam', 'JOS', 21, 42, 'Ndũa isu kĩla ĩmwe yaĩ na syengo syayo ithyũlũlũkĩte: ũu nĩw’o kwailyĩ ndũanĩ isu syonthe.'),
('kam', 'JOS', 21, 43, 'O ta ũu Yeova amanenga Isilaeli nthĩ yonthe ĩla wevĩtie kũnenga aaĩthe moo; na mamĩmesya, na matũaa nthĩnĩ wayo.'),
('kam', 'JOS', 21, 44, 'Na Yeova amanenga ũthũmũo ngalĩ syonthe, kwĩanana na w’onthe ũla wamevĩtĩe aaĩthe moo: na kũtyaaũngama mũndũ o na ũmwe wa amaitha moo onthe mbee woo; Yeova nĩwanenganie amaitha moo onthe kw’okonĩ kwoo.'),
('kam', 'JOS', 21, 45, 'Kũtyaalea kwĩanĩw’a o na ũmwe wa moseo onthe ala Yeova wathie nyũmba ya Isilaeli; onthe nĩmeanĩw’e.'),
('kam', 'JOS', 22, 1, 'Na ĩndĩ Yosua ameta Aleuveni na Angati, na nyunzu ya mbaĩ ya Manase,'),
('kam', 'JOS', 22, 2, 'na amea, Nĩmũsũvĩĩte w’onthe ũla Mose mũthũkũmi wa Yeova wamwĩaĩe, na mweethukĩĩsya wasya wakwa ũndũnĩ w’onthe ũla namwĩaĩe:'),
('kam', 'JOS', 22, 3, 'mũtyaamatia ana‐a‐ĩthe menyu mĩthenya ĩsu mingĩ kũvika ũmũnthĩ, ĩndĩ nĩmũsũvĩĩte wĩaĩo wa mwĩao wa Yeova Ngai wenyu.'),
('kam', 'JOS', 22, 4, 'Na yu Yeova Ngai wenyu nũnengete ana‐a‐ĩthe menyu ũthũmũo, o tondũ waneenie nao; kwondũ wa ũu yu ĩthyũũei, na mũienda maeemanĩ menyu, kũvika nthĩ ĩla ya ng’ũndũ yenyu, ĩla Mose mũthũkũmi wa Yeova wamũnengie mũingo wa Yolotani.'),
('kam', 'JOS', 22, 5, 'Ĩsũvĩei mũno mwĩkae ũtw’ĩo na mĩao ĩla Mose mũthũkũmi wa Yeova wamwĩaĩe, mwende Yeova Ngai wenyu, na kũenda nzĩanĩ syake syonthe, na kũkwata mĩao yake, na kũlũman’ya nake, na kũmũthũkũma na ngoo syenyu syonthe na thayũ wenyu w’onthe.'),
('kam', 'JOS', 22, 6, 'Na ĩndĩ Yosua amaathima, na amaeka maende; na mathi maeemanĩ moo.'),
('kam', 'JOS', 22, 7, 'Na ĩndĩ Mose aĩ ananenga nyunzu ya mbaĩ ya Manase ũtiĩwa ku Mbasani; ĩndĩ nyunzu ĩla ĩngĩ Yosua amanenga katĩ wa ana‐a‐ĩthe moo mũingo wa Yolotani kwelekela ũthũĩlonĩ wa syũa. O na ĩngĩ yĩla Yosua wamaekie mathi maeemanĩ moo, amaathima,'),
('kam', 'JOS', 22, 8, 'na aneena nao, akĩmea, Syokai mwĩ na ũthwii mwingĩ maeemanĩ menyu, na mwĩ na indo nyingĩ, na vetha, na thaavu, na ũthuku, na kĩaa, na ngũa nyingĩ mũno: aan’yai mũtavo wa amaitha menyu na ana‐a‐ĩthe menyu.'),
('kam', 'JOS', 22, 9, 'Na ana ma Leuveni na ana ma Ngati na nyunzu ya mbaĩ ya Manase masyoka, na mauma vala vaĩ ana ma Isilaeli kuma Silo, ĩla yĩ nthĩ ya Kanaani, maende nthĩ ya Ngileati, kũvika nthĩ ya ng’ũndũ yoo, ĩla manengiwe yĩthĩwe ng’ũndũ yoo, kwĩanana na mwĩao wa Yeova na kanyw’a wa Mose.'),
('kam', 'JOS', 22, 10, 'Na yĩla mavikie nthĩ ĩla yĩ ũtee wa Yolotani, ũla wĩ nthĩ ya Kanaani, ana ma Leuveni na ana ma Ngati na nyunzu ya mbaĩ ya Manase maaka kĩthembeo kw’o ũtee wa Yolotani, kĩthembeo kĩnene kya kũsiw’a.'),
('kam', 'JOS', 22, 11, 'Na ana ma Isilaeli meew’a kũkyaw’a, Sisyai, ana ma Leuveni na ana ma Ngati na nyunzu ya mbaĩ ya Manase nĩmakĩte kĩthembeo kwelekela nthĩ ya Kanaani, nthĩ ĩla yĩ vakuvi na Yolotani, ngalĩ ĩla ya ana ma Isilaeli.'),
('kam', 'JOS', 22, 12, 'Na yĩla ana ma Isilaeli meewie ũu, ũmbano w’onthe wa ana ma Isilaeli moombana vamwe ku Silo, mambate mokite nao.'),
('kam', 'JOS', 22, 13, 'Na ana ma Isilaeli matũma kwa ana ma Leuveni, na ana ma Ngati, na nyunzu ya mbaĩ ya Manase, ku nthĩ ya Ngileati, Vineasi mwana wa mũthembi Eleasali,'),
('kam', 'JOS', 22, 14, 'na vamwe nake anene ĩkũmi, mũnene ũmwe wa nyũmba ya aaĩthe kwondũ wa kĩla mbaĩ ya Isilaeli; na kĩla ũmwe woo aĩ mũtongoi wa nyũmba sya aaĩthe katĩ wa ngili sya Isilaeli.'),
('kam', 'JOS', 22, 15, 'Na mamokĩa ana ma Leuveni, na ana ma Ngati, na nyunzu ya mbaĩ ya Manase, kũvika nthĩ ya Ngileati, na maneena nao, makĩmea,'),
('kam', 'JOS', 22, 16, 'Ũũ nĩw’o ũmbano w’onthe wa Yeova ũkwasya, Yĩĩ nĩ ĩvĩtyo yaũ yĩla mũmũvĩtanĩsye Ngai wa Isilaeli, mweethyũũa ũmũnthĩ mũeke kũmũvikĩla Yeova, ũndũ mwakĩte kĩthembeo, mũmũng’endee Yeova ũmũnthĩ?'),
('kam', 'JOS', 22, 17, 'Naĩ ya Veoli no nini kwĩtũ, ĩla tũtaaĩthesya kwayo kũvika ũmũnthĩ, o na kau nĩkwookie ũthĩn’yo ũmbanonĩ wa Yeova,'),
('kam', 'JOS', 22, 18, 'no mũvaka mwĩthyũũe ũmũnthĩ mũeke kũmũvikĩla Yeova? Na kũkeethĩwa atĩĩ, nũndũ ũmũnthĩ nĩmũũmũng’endea Yeova, ũnĩ akathatĩa ũmbano w’onthe wa Isilaeli,'),
('kam', 'JOS', 22, 19, 'Ĩndĩ, ethĩwa nthĩ ĩla ya ng’ũndũ yenyu ti ntheu, ingai ĩndĩ kũvika nthĩ ĩla ya ng’ũndũ ya Yeova, vala wĩkalo wa Yeova wĩkalaa, na mũimĩmesya mwĩkale katĩ waitũ: ĩndĩ mũtikamũng’endee Yeova, o na mũtikatũng’endee ithyĩ, nũndũ wa kwaka kĩthembeo eka kĩthembeo kya kĩthembeo kya Yeova Ngai waitũ.'),
('kam', 'JOS', 22, 20, 'Akani mwana wa Nzela ndaavĩtya kwondũ wa kwosa kĩndũ kĩla kĩvathĩtwe, na ũthatu wa Yeova wavalũkĩla ũmbano w’onthe wa Isilaeli? Na mũndũ ũsu ndaaa e weka naĩnĩ yake.'),
('kam', 'JOS', 22, 21, 'Nĩvo ĩndĩ ana ma Leuveni na ana ma Ngati na nyunzu ya mbaĩ ya Manase masũngĩie, na maneena na atongoi ma ngili sya Isilaeli,'),
('kam', 'JOS', 22, 22, 'Ũla Mwene Vinya, Ngai, Yeova, Ũla Mwene Vinya, Ngai, Yeova, nĩwĩsĩ; na Isilaeli nake akamanya: ethĩwa kweekiwe na ũng’endu, kana ũndũ wa kũmũvĩtanĩsya Yeova (ndũkatũtangĩĩe ũmũnthĩ),'),
('kam', 'JOS', 22, 23, 'atĩ nĩtwakĩte kĩthembeo twĩthyũũe tũeke kũmũvikĩla Yeova; kana ethĩwa nĩ kya kũthemba nthembo ya kũvĩvw’a kana nthembo ya mũtu ĩũlũ wakyo, kana ethĩwa nĩ kya kũthemba nthembo sya mũuo ĩũlũ wakyo, Yeova e mwene aandũe;'),
('kam', 'JOS', 22, 24, 'na ethĩwa tũtyaaika ũndũ ũũ ũndũ wa kũsũvĩa, na ũndũ wa kĩtumĩ, tũkyasya, Ĩvinda yĩla yũkĩte syana syenyu itonya kũneena na syana sitũ, ikĩsyĩa, Inyw’ĩ mwĩ na ũndũ mwaũ na Yeova, Ngai wa Isilaeli?'),
('kam', 'JOS', 22, 25, 'Nũndũ Yeova nũtw’ĩĩte Yolotani mũvaka katĩ waitũ nenyu, inyw’ĩ ana ma Leuveni na ana ma Ngati; inyw’ĩ mũti na kĩanda nthĩnĩ wa Yeova: o ta ũu syana syenyu nitonya kũtuma syana sitũ ieka kũkĩa Yeova.'),
('kam', 'JOS', 22, 26, 'Kwondũ wa ũu twasya, Twĩyũmban’yei yu twĩyakĩe kĩthembeo, ti kwondũ wa nthembo ya kũvĩvw’a, o na nthembo ya kũtonywa:'),
('kam', 'JOS', 22, 27, 'ĩndĩ kĩkeethĩwa ũkũsĩ katĩ waitũ nenyu, na katĩ wa nzyawa sitũ ĩtina waitũ, nĩ kana twĩke ũthũkũmi wa Yeova mbee wake na nthembo sitũ sya kũvĩvw’a, na nthembo sitũ sya kũtonywa, na nthembo sitũ sya mũuo; nĩ kana syana syenyu itikaatonye kũtavya syana sitũ ĩvinda yĩla yũkĩte, Mũti na kĩanda nthĩnĩ wa Yeova.'),
('kam', 'JOS', 22, 28, 'Kwondũ wa ũu twasya, Kũkeethĩwa, yĩla metũtavya ta ũu ithyĩ kana nzyawa sitũ ĩvinda yĩla yũkĩte, ithyĩ tũkasya, Sisyai, ngelekan’yo ya kĩthembeo kya Yeova, kĩla aaĩthe maitũ maseũvisye, ti kwondũ wa nthembo sya kũvĩvw’a, kana nthembo sya kũtonywa; ĩndĩ nĩ ũkũsĩ katĩ waitũ nenyu.'),
('kam', 'JOS', 22, 29, 'Nĩkwĩthĩwe kũasa naitũ kũmũng’endea Yeova, na kwĩthyũũa ũmũnthĩ tũeke kũmũvikĩla Yeova, twake kĩthembeo kĩthĩwe kya kũthemba nthembo ya kũvĩvw’a, kana nthembo ya mũtu, kana nthembo sya kũtonywa; ate o kĩthembeo kya Yeova Ngai waitũ kĩla kĩ mbee wa wĩkalo wake.'),
('kam', 'JOS', 22, 30, 'Na yĩla mũthembi Vineasi, na anene ma ũmbano, o atongoi ma ngili sya Isilaeli ala maĩ nake, meewie ndeto ila ana ma Leuveni na ana ma Ngati na ana ma Manase maneenie, mendeew’a mũno.'),
('kam', 'JOS', 22, 31, 'Na Vineasi mwana wa mũthembi Eleasali amea ana ma Leuveni, na ana ma Ngati, na ana ma Manase, Ũmũnthĩ nĩtũũmanya Yeova e katĩ waitũ, nũndũ mũtyaamũvĩtanĩsya Yeova.'),
('kam', 'JOS', 22, 32, 'Na Vineasi mwana wa mũthembi Eleasali, na ala anene, masyoka kuma vala vaĩ ana ma Leuveni, na ana ma Ngati, kuma nthĩ ya Ngileati, kũvika nthĩ ya Kanaani, vala ve ana ma Isilaeli, na mamatũngĩa ũvoo.'),
('kam', 'JOS', 22, 33, 'Na ũndũ ũsu wendeesya ana ma Isilaeli; na ana ma Isilaeli mamũtaĩa Ngai, na matyaaneena ĩngĩ ũvoo wa kwambata mokite nao, manange nthĩ vala ana ma Leuveni na ana ma Ngati matũaa.'),
('kam', 'JOS', 22, 34, 'Na ana ma Leuveni na ana ma Ngati makĩta kĩthembeo kyu Eti: masya, Nũndũ nĩ ũkũsĩ katĩ waitũ atĩ Yeova nĩwe Ngai.'),
('kam', 'JOS', 23, 1, 'Na kweethĩwa ĩtina wa mĩthenya mingĩ, yĩla Yeova waĩ ananenga Isilaeli kũthũmũa kuma amaithanĩ moo onthe ma ngalĩ syonthe, na Yosua aĩ mũkũu na wa myaka mingĩ;'),
('kam', 'JOS', 23, 2, 'Yosua ameta Isilaeli onthe, atumĩa moo na atongoi moo, na asili moo na anene ma kwoo, na amea, Nyie nĩ mũkũu na wa myaka mingĩ:'),
('kam', 'JOS', 23, 3, 'na nĩmwonete ũndũ w’onthe ũla Yeova Ngai wenyu wĩkĩte mbaĩ ii syonthe nũndũ wenyu; nũndũ Yeova Ngai wenyu, nĩwe wamũkitĩe inyw’ĩ.'),
('kam', 'JOS', 23, 4, 'Sisyai, nĩnamũaanĩsye kwa kũlimana mbaĩ ii ila syatialile, syĩthĩwe ũtiĩwa kwondũ wa mbaĩ syenyu, kuma Yolotani, vamwe na mbaĩ syonthe ila nĩvetete, o kũvika ũkanga mũnene kwelekela ũthũĩlonĩ wa syũa.'),
('kam', 'JOS', 23, 5, 'Na Yeova Ngai wenyu, akaikuthũa mbee wenyu, na kwilũngya iende vala mũtatonya kũsyona, na mũkamĩmesya nthĩ yasyo, o tondũ Yeova Ngai wenyu waneenie nenyu.'),
('kam', 'JOS', 23, 6, 'Kwondũ wa ũu ĩthĩwai na ũkũmbaũ mũnene mũsũvĩe na kwĩka w’onthe ũla ũandĩkĩtwe ĩvukunĩ ya mĩao ya Mose, nĩ kana mũtikethyũũe ngalĩ ya kw’oko kwa aũme kana kwa aka mũmĩtie;'),
('kam', 'JOS', 23, 7, 'nĩ kana mũtikalike katĩ wa mbaĩ ii, ii ila itialĩte katĩ wenyu; o na mũtikawete syĩtwa ya ngai syasyo, kana kwĩavĩthya nasyo, kana kwithũkũma, kana kũsyĩkunamĩsya;'),
('kam', 'JOS', 23, 8, 'ĩndĩ lũman’yai na Yeova Ngai wenyu, o tondũ mweekie kũvika ũmũnthĩ.'),
('kam', 'JOS', 23, 9, 'Nũndũ Yeova nũlũngĩtye mbee wenyu mbaĩ nene syĩ vinya: ĩndĩ ũndũ wenyu, vati mũndũ waaũngama mbee wenyu kũvika ũmũnthĩ.'),
('kam', 'JOS', 23, 10, 'Mũndũ ũmwe wenyu akalũngya ngili; nũndũ Yeova Ngai nĩwe ũla ũmũkitĩaa, o tondũ waneenie nenyu.'),
('kam', 'JOS', 23, 11, 'Ĩsũvĩei nesa ĩndĩ, mũmwende Yeova Ngai wenyu.'),
('kam', 'JOS', 23, 12, 'Na ethĩwa nĩmũũsyoka o vanini, na kũlũman’ya na ũtialo wa mbaĩ ii, o ii ila syatiiwe katĩ wenyu, na kũtwaanĩa nasyo, na kũlika kwasyo, nao kũlika kwenyu;'),
('kam', 'JOS', 23, 13, 'manyai ki Yeova Ngai wenyu ndakalũngya ĩngĩ mbaĩ ii iende vala mũtatonya kũsyona; ĩndĩ ikeethĩwa mũkwa na kĩtei kwenyu, na mũsalisa mbaunĩ syenyu, na mĩw’a methonĩ menyu, kũvika yĩla mũkaa kuma nthĩ nzeo ĩla Yeova Ngai wenyu ũmũnengete.'),
('kam', 'JOS', 23, 14, 'Na, sisyai, ũmũnthĩ nĩngũthi na nzĩa ya nthĩ yonthe: na inyw’ĩ nĩmwĩsĩ ngoonĩ syenyu syonthe na mathayũnĩ menyu onthe, kũtyaalea kwĩanĩw’a ũndũ ũmwe katĩ wa maũndũ onthe maseo ala Yeova Ngai wenyu waneenie ũndũ wenyu; onthe nĩmeanĩw’e kwenyu, kũtyaalea kwĩanĩw’a ũndũ ũmwe katĩ wamo.'),
('kam', 'JOS', 23, 15, 'Na kũkeethĩwa, o tondũ maũndũ onthe maseo nĩmokĩte ĩũlũ wenyu ala Yeova Ngai wenyu waneenie nenyu, o ta ũu Yeova akamũetee maũndũ onthe mathuku, kũvika yĩla ũkamwananga kũmumya nthĩ ĩno nzeo ĩla Yeova Ngai wenyu ũmũnengete.'),
('kam', 'JOS', 23, 16, 'Yĩla mũkavĩtya ũtianĩo wa Yeova Ngai wenyu, ũla wamwĩaĩe, na mũkaenda na kũthũkũma ngai ingĩ, na kũsyĩkunamĩsya; nĩvo ĩndĩ ũthatu wa Yeova ũkakanw’a ĩũlũ wenyu, na mũkaaa mĩtũkĩ kuma nthĩ nzeo ĩla ũmũnengete.'),
('kam', 'JOS', 24, 1, 'Na Yosua oomban’ya mbaĩ syonthe sya Isilaeli ku Sekemu, na ameta atumĩa ma Isilaeli, na atongoi moo, na asili moo, na anene ma kwoo; nao meeyonan’ya mbee wa Yeova.'),
('kam', 'JOS', 24, 2, 'Na Yosua amea andũ onthe, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Aaĩthe menyu nĩmatũaa tene mũingo wa ũla Ũsĩ, o Tela, ĩthe wa Avalaamu, na ĩthe wa Neoli: na nĩmathũkũmaa ngai ingĩ.'),
('kam', 'JOS', 24, 3, 'Na noosa ĩthe wenyu Avalaamu kũmumya mũingo wa ũla Ũsĩ, na namũtongoeasya katĩ wa nthĩ yonthe ya Kanaani, na naingĩvya ũsyao wake, na namũnenga Isaka.'),
('kam', 'JOS', 24, 4, 'Na namũnenga Isaka, Yakovo na Esau: na namũnenga Esau kĩĩma kya Seili, kĩthĩwe ng’ũndũ yake; na Yakovo na ana make matheea Misili.'),
('kam', 'JOS', 24, 5, 'Na natũma Mose na Aluni, na nathĩn’ya Misili, kwĩanana na ũndũ neekie katĩ wayo: na ĩtina namumya.'),
('kam', 'JOS', 24, 6, 'Na naumya aaĩthe menyu Misili: na mavika ũkanganĩ; na Amisili mamaatĩĩa aaĩthe menyu na makasya ma kaũ na andũ matũlĩte mbalasi kũvika Ũkanga Mũtune.'),
('kam', 'JOS', 24, 7, 'Na yĩla mamwĩkaĩlile Yeova, eekĩa kĩvindu katĩ wenyu na Amisili, na aete ũkanga ĩũlũ woo, na amavw’ĩka; na metho menyu moona ũndũ neekie Misili: na nĩmwekalaa weũnĩ mĩthenya mingĩ.'),
('kam', 'JOS', 24, 8, 'Na namũete nthĩ ya Aamoli, ala matwĩe mũingo ũya wa Yolotani: na mokita nenyu; na namanengane kw’okonĩ kwenyu, na mwamesya nthĩ yoo; na namananga mbee wenyu.'),
('kam', 'JOS', 24, 9, 'Nĩvo ĩndĩ Mbalaki mwana wa Nzivoli, mũsumbĩ wa Moavi, wokĩlile na okita na Isilaeli: na atũmana na amwĩta Mbalaamu mwana wa Mbeoli amũumanĩe;'),
('kam', 'JOS', 24, 10, 'ĩndĩ ndyaaĩtĩkĩla kũmwĩthukĩĩsya Mbalaamu; kwondũ wa ũu aendeea na ũmũathima: na ĩndĩ namũvonokya kuma kw’okonĩ kwake.'),
('kam', 'JOS', 24, 11, 'Na mwainga Yolotani, na mwavika Yeliko: na andũ ma Yeliko mokita nenyu, Mũamoli, na Mũvelisi, na Mũkanaani, na Mũititi, na Mũngilikasi, na Mũivi, na Mũyevusi; na namanengane kw’okonĩ kwenyu.'),
('kam', 'JOS', 24, 12, 'Na natũma yĩla ĩuĩ mbee wenyu, yĩla yamalũngilye, o asumbĩ asu elĩ ma Aamoli, maume mbee wenyu; na ti na ũvyũ waku, kana ũta waku.'),
('kam', 'JOS', 24, 13, 'Na namũnenga nthĩ vala mũtaatethya wĩa, na ndũa ĩla mũtaaka, na nĩmũtwĩe nthĩnĩ wasyo; nĩmũĩsaa kya ũya kya mĩũnda ya mĩsavivũ na mĩũnda ya mĩthata ĩla mũtaavanda.'),
('kam', 'JOS', 24, 14, 'Kwondũ wa ũu ĩndĩ kĩai Yeova, na mũimũthũkũma na w’o, na vate wangangan’yo; na vetai ngai ila aaĩthe menyu mathũkũmie mũĩngo wa ũla Ũsĩ, na ku Misili; na mũithũkũma Yeova.'),
('kam', 'JOS', 24, 15, 'Na ethĩwa nimũkwona nĩ ũthũku kũthũkũma Yeova, nyuvai ũmũnthĩ ũla mwĩthũkũmaa; ethĩwa nĩ ngai ila aaĩthe menyu mathũkũmaa ila syaĩ mũingo wa ũla Ũsĩ, kana ngai sya Aamoli, ala mũtũaa nthĩ yoo: ĩndĩ ũndũ wakwa na nyũmba yakwa, tũkathũkũmaa Yeova.'),
('kam', 'JOS', 24, 16, 'Na andũ masũngĩa na masya, Nĩkwĩthĩwe kũasa naitũ kũmũtia Yeova, tũthũkũmae ngai ingĩ:'),
('kam', 'JOS', 24, 17, 'nũndũ Yeova Ngai waitũ, nĩwe watumisye ithyĩ na aaĩthe maitũ nthĩ ya Misili, kuma nyũmbanĩ ya ũkombo, na ũla wekie syama isu nene twene, na watũsũvĩaa nzĩanĩ yonthe ĩla twaendaa nayo, na katĩ wa ngo syonthe sya andũ ila twavĩtĩle katĩ wasyo;'),
('kam', 'JOS', 24, 18, 'na Yeova alũngya mbee waitũ ngo syonthe sya andũ, o Aamoli ala matwĩe nthĩ ĩno: kwondũ wa ũu ithyĩ naitũ tũkathũkũmaa Yeova; nũndũ nĩwe Ngai waitũ.'),
('kam', 'JOS', 24, 19, 'Na Yosua amea andũ, Mũtitonya kũthũkũma Yeova; nũndũ nĩ Ngai mũtheu; na nĩ Ngai wĩ kĩwĩu; ndakamũekea mavĩtyo menyu kana naĩ syenyu.'),
('kam', 'JOS', 24, 20, 'Ethĩwa mũkatia Yeova, na kũthũkũma ngai ngeni, nĩvo ĩndĩ ũkethyũũa na kũmwĩka naĩ, na kũmũmina, ĩtina wa kũmwĩka nesa.'),
('kam', 'JOS', 24, 21, 'Na andũ mamwĩa Yosua, Aiee; ĩndĩ tũkathũkũmaa Yeova.'),
('kam', 'JOS', 24, 22, 'Na Yosua amea andũ, Inyw’ĩ mwĩ ngũsĩ ĩũlũ wenyu ene kana mĩmũnyuvĩte Yeova mũmũthũkũmae. Na masya, Twĩ ngũsĩ.'),
('kam', 'JOS', 24, 23, 'Yũ ĩndĩ vetai ngai ngeni ila syĩ katĩ wenyu, na elekelyai ngoo syenyu kwa Yeova, Ngai wa Isilaeli.'),
('kam', 'JOS', 24, 24, 'Na andũ mamwĩa Yosua, Tũkathũkũmaa Yeova Ngai waitũ, na tũkeethukĩĩasya wasya wake.'),
('kam', 'JOS', 24, 25, 'Kwondũ wa ũu Yosua atianĩa ũtianĩo na andũ mũthenya ũsu, na amaiĩa mwamũlo na ũtw’ĩo ku Sekemu.'),
('kam', 'JOS', 24, 26, 'Na Yosua aandĩka ndeto isu ĩvukunĩ ya mĩao ya Ngai; na oosa ĩvia ĩnene, na ayĩũngamya o vau ĩtina wa mũtĩ wa mwaloni ũla waĩ vakuvĩ na vandũ vala vatheu va Yeova.'),
('kam', 'JOS', 24, 27, 'Na Yosua amea andũ onthe, Sisyai, ĩvia yĩĩ yĩkatũkũsĩĩa; nũndũ nĩyĩw’ĩte ndeto syonthe sya Yeova ila waneenie naitũ: kwondũ wa ũu yĩkamũkũsĩĩa, mũtikaakaĩe Ngai wenyu.'),
('kam', 'JOS', 24, 28, 'Kwondũ wa ũu Yosua amombũũkya andũ mathi, kĩla mũndũ ũtiĩwanĩ wake.'),
('kam', 'JOS', 24, 29, 'Na kweethĩwa ĩtina wa maũndũ asu, Yosua mwana wa Nuni, mũthũkũmi wa Yeova, akw’a, e wa myaka ĩana na ĩkũmi.'),
('kam', 'JOS', 24, 30, 'Na mamũthika mũvakanĩ wa ũtiĩwa wake ku Timinathi‐selaa, ĩla yĩ nthĩ yĩ iĩma ya Evalaimu, ngalĩ ya ĩũlũ ya kĩĩma kya Ngaasi.'),
('kam', 'JOS', 24, 31, 'Na Isilaeli mathũkũmaa Yeova mĩthenya yonthe ya Yosua, na mĩthenya yonthe ya atumĩa ala mekalile thayũ kũvĩtũka Yosua, na meesĩ wĩa w’onthe wa Yeova, ũla watethisye kwondũ wa Isilaeli.'),
('kam', 'JOS', 24, 32, 'Na mavĩndĩ ma Yosevu, ala ana ma Isilaeli mambatisye kuma Misili, mathika ku Sekemu, kĩlungunĩ kya nthĩ kĩla Yakovo wamathooee ana ma Amolu, ĩthe wa Sekemu na ilungu ĩana sya mbesa: na matw’ĩka ũtiĩwa wa ana ma Yosevu.'),
('kam', 'JOS', 24, 33, 'Na Eleasali, mwana wa Aluni, akw’a; na mamũthika kĩĩmanĩ kya Vineasi mwana wake, kĩla wanengiwe nthĩ yĩ iĩma ya Evalaimu.'),
('kam', 'JDG', 1, 1, 'Na kweethĩwa ĩtina wa kĩkw’ũ kya Yosua, ana ma Isilaeli makũlya Yeova, makyasya, Nũũ ũla wĩamba kwambata kwa Akanaani kwondũ witũ, kũkita nao?'),
('kam', 'JDG', 1, 2, 'Na Yeova amea, Yuta akambata: sisyai, nyie nĩnĩnenganĩte ĩ nthĩ kw’okonĩ kwake.'),
('kam', 'JDG', 1, 3, 'Na Yuta amwĩa Simeoni mwana‐a‐inyia, Ũka twambatan’ye kĩandanĩ kyakwa, nĩ kana tũkite na Akanaani; nakwa ngaendan’ya naku kĩandanĩ kyaku. Na ĩndĩ Simeoni aendan’ya nake.'),
('kam', 'JDG', 1, 4, 'Na Yuta ambata; na Yeova amanengane Akanaani na Avelisi mokonĩ moo: nao mamoaa ma asu andũ ngili ĩkũmi ku Mbeseki.'),
('kam', 'JDG', 1, 5, 'Na mamwĩthĩa Atoni‐mbeseki ku Mbeseki; na mokita nake, na makũna Akanaani na Avelisi.'),
('kam', 'JDG', 1, 6, 'Ĩndĩ Atoni‐mbeseki akũka; na mamũatĩĩa, na mamũkwata, na mamũtila syaa ila nene sya moko na sya maũũ.'),
('kam', 'JDG', 1, 7, 'Na Atoni‐mbeseki asya, Asumbĩ mĩongo mũonza, ala maĩ atile syaa syoo ila nene sya moko na sya maũũ, moosanasya lĩu woo ungu wa mesa yakwa: o ũndũ neekie, now’o Ngai wandĩva. Na mamũete Yelusaleme, na akw’ĩa kw’o.'),
('kam', 'JDG', 1, 8, 'Na ana ma Yuta mokita na Yelusaleme, na mamĩkwata, na mamĩkũna kwa kũtemanga na ũvyũ, na mamĩvĩvya ĩ ndũa na mwaki.'),
('kam', 'JDG', 1, 9, 'Na ĩtina ana ma Yuta matheea kũkita na Akanaani ala matwĩe nthĩ yĩ iĩma, na nthĩ ya ngalĩ ya Ĩtheo, na nthĩ ndindimalu.'),
('kam', 'JDG', 1, 10, 'Na Yuta mathi kũkita na Akanaani ala matwĩe Eviloni (na ĩndĩ syĩtwa ya Eviloni mbee yeetawa Kiliathi‐aliva); na makũna Sesai, na Aimani, na Talimai.'),
('kam', 'JDG', 1, 11, 'Na kuma vo aenda kũkita na ala matwĩe Ndevili. (Na syĩtwa ya Ndevili mbee yeetawa Kiliathi‐seveli.)'),
('kam', 'JDG', 1, 12, 'Na Kalevu asya, Ũla wĩkũna Kiliathi‐seveli, na kũmĩkwata, we ngamũnenga Akisa mwĩĩtu wakwa ethĩwe mũka.'),
('kam', 'JDG', 1, 13, 'Na Othinieli mwana wa Kenasi, mũinae wa Kalevu, amĩkwata: nake amũnenga Akisa mwĩĩtu wake ethĩwe mũka.'),
('kam', 'JDG', 1, 14, 'Na kweethĩwa, yĩla wokie vala ũĩ, amũingĩĩsya avoye ĩthe mũũnda: na auma ĩng’oinĩ yake; na Kalevu amũkũlya, Wĩenda kĩ?'),
('kam', 'JDG', 1, 15, 'Nake amũsũngĩa, Nenga ũathimo; nũndũ nũnenganĩte nthĩ ya ngalĩ ya Ĩtheo, nenga mbuluti sya manzĩ o nasyo. Na Kalevu amũnenga mbuluti sya ĩũlũ na mbuluti sya ĩtheo.'),
('kam', 'JDG', 1, 16, 'Na ana ma Mũkeni, mũthoni wa Mose, mambata kuma ndũa ĩsu ya mĩtende vamwe na ana ma Yuta kũvika weũnĩ wa Yuta, ũla wĩ ngalĩ ya ĩtheo ya Alati; na mathi na matũa na andũ asu.'),
('kam', 'JDG', 1, 17, 'Na Yuta athi na mwana‐a‐inyia Simeoni, nao makũna Akanaani ala matwĩe Nzevathi, na mamyananga vyũ. Na syĩtwa ya ndũa ĩsu yeetawa Olima.'),
('kam', 'JDG', 1, 18, 'Vamwe na ũu Yuta akwata Ngasa vamwe na mĩvaka yayo, na Asikeloni na mĩvaka yayo, na Ekiloni na mĩvaka yayo.'),
('kam', 'JDG', 1, 19, 'Na Yeova aĩ vamwe na Yuta; nake amalũngya ala matwĩe nthĩ yĩ iĩma; nũndũ ndaatonya kũlũngya ala matwĩe mwandanĩ, nũndũ maĩ na makasya ma kaũ ma iaa.'),
('kam', 'JDG', 1, 20, 'Na mamũnenga Kalevu Eviloni, o tondũ Mose waneenie: nake amalũngya vo ana asu atatũ ma Anaki.'),
('kam', 'JDG', 1, 21, 'Na ana ma Mbenyamini matyaalũngya Ayevusi ala matwĩe Yelusaleme; ĩndĩ Ayevusi matũaa na ana ma Mbenyamini ku Yelusaleme kũvika ũmũnthĩ.'),
('kam', 'JDG', 1, 22, 'Na nyũmba ya Yosevu, nao mambata kũkita na Mbethi‐eli; na Yeova aĩ vamwe namo.'),
('kam', 'JDG', 1, 23, 'Na nyũmba ya Yosevu matũmana makathiane Mbethi‐eli. (Na syĩtwa ya ndũa ĩsu mbee yeetawa Lusu.)'),
('kam', 'JDG', 1, 24, 'Na athiani moona mũndũ okĩte kuma ĩ ndũanĩ, na mamwĩa, Nĩtũũkwĩsũva, twon’ye ũlikĩlo wa ĩ ndũa, naitũ tũkakwĩka nesa.'),
('kam', 'JDG', 1, 25, 'Nake amon’ya ũlikĩlo wa ndũa ĩsu; namo makũna ĩ ndũa kwa kũtemanga na ũvyũ; ĩndĩ ũla mũndũ mamũeka vamwe na mũvĩa wake w’onthe.'),
('kam', 'JDG', 1, 26, 'Na ũla mũndũ athi nthĩ ya Aititi, na aaka ndũa, na amĩta Lusu, na nĩyo syĩtwa yayo kũvika ũmũnthĩ.'),
('kam', 'JDG', 1, 27, 'Na Manase ndaalũngya ala matwĩe Mbethi‐seani na tũtũla twayo, o na ala matwĩe Taanaki, na tũtũla twayo, o na ala matwĩe Ndoli na tũtũla twayo, o na ala matwĩe Ivileamu na tũtũla twayo, o na ala matwĩe Mekito na tũtũla twayo; ĩndĩ Akanaani meevinyĩlĩlya nthĩ ĩsu.'),
('kam', 'JDG', 1, 28, 'Na kweethĩwa, yĩla Isilaeli mongelekile vinya, mamatethethya Akanaani wĩa wa vinya, na matyaamalũngya vyũ.'),
('kam', 'JDG', 1, 29, 'Na Evalaimu ndaamalũngya Akanaani ala matwĩe Ngeseli; ĩndĩ Akanaani matũaa Ngeseli katĩ woo.'),
('kam', 'JDG', 1, 30, 'Na Nzevuluni ndaamalũngya ala matwĩe Kiteloni, o na ala matwĩe Naalali; ĩndĩ Akanaani matũaa katĩ woo, namo matw’ĩka ala matethethaw’a wĩa wa vinya.'),
('kam', 'JDG', 1, 31, 'Na Aseli ndaamalũngya ala matwie Ako, o na ala matwĩe Sitoni, o na ala ma Alavi, o na ala ma Akisivu, o na ala ma Eliva, o na ala ma Aveki, o na ala ma Leovu;'),
('kam', 'JDG', 1, 32, 'ĩndĩ Aaseli matũaa vamwe na Akanaani, ala matwĩe ĩ nthĩ; nũndũ matyaamalũngya.'),
('kam', 'JDG', 1, 33, 'Na Navitali ndaamalũngya ala matwĩe Mbethi‐semesi, o na ala matwĩe Mbethi‐anathi; ĩndĩ atũaa vamwe na Akanaani, ala matwĩe ĩ nthĩ: ĩndĩ ala matwĩe Mbethi‐semesi na Mbethi‐anathi matethethaw’a wĩa wa vinya.'),
('kam', 'JDG', 1, 34, 'Na Aamol malũngĩlĩĩlya ana ma Ndani nthĩ yĩ iĩma; na matyaametĩkĩla matheee mwandanĩ;'),
('kam', 'JDG', 1, 35, 'ĩndĩ Aamoli meevinyĩlĩlya kĩĩmanĩ kya Eelesi, na Aiyaloni, na Saalivimu: ĩndĩ kw’oko kwa nyũmba ya Yosevu nĩkwakĩlilye vinya, mũvaka matethethaw’a wĩa wa vinya.'),
('kam', 'JDG', 1, 36, 'Na mũvaka wa Aamoli waumĩte kyambatonĩ kya Akilavimu, kuma yĩla ĩvianĩ, na kũendeea na ĩũlũ.'),
('kam', 'JDG', 2, 1, 'Na mũlaĩka wa Yeova ambata kuma Ngilikali kũthi Mbokimu. Na asya, Nyie nĩnatumie mwambata kuma Misili, na nĩnamũetie nthĩ ĩla nameavĩe aaĩthe menyu; na nĩnaisye, Ndikananga o na ĩndĩĩ ũtianĩo wakwa nenyu:'),
('kam', 'JDG', 2, 2, 'nenyu mũtikaatianĩe ũtianĩo o na wĩva na ala matwĩe nthĩ ĩno; mwĩomboa ithembeo syoo. Ĩndĩ mũtyaaĩthukĩĩsya wasya wakwa: mwĩkaa ũu kĩ?'),
('kam', 'JDG', 2, 3, 'Kwondũ wa ũu o nakwa nĩnaisye, Ndikamalũngya maume vala mũĩ; ĩndĩ makeethĩwa ta mĩw’a mbaunĩ syenyu, na ngai syoo ikeethĩwa kĩtei kwenyu.'),
('kam', 'JDG', 2, 4, 'Na kweethĩwa, yĩla ũla mũlaĩka wa Yeova waneenie ndeto isu na ana ma Isilaeli onthe, andũ mookĩlya mawasya moo na maĩa.'),
('kam', 'JDG', 2, 5, 'Na meeta syĩtwa ya vandũ vau Mbokimu: na mamũthembea Yeova vo.'),
('kam', 'JDG', 2, 6, 'Na ĩndĩ yĩla Yosua wamombũũkisye andũ, ana ma Isilaeli mathi kĩla mũndũ ũtiĩwanĩ wake amĩmesye nthĩ.'),
('kam', 'JDG', 2, 7, 'Na andũ mamũthũkũmaa Yeova mĩthenya yonthe ya Yosua, na mĩthenya yonthe ya atumĩa ala mekalangile thayũ kwĩ Yosua, ala monete wĩa mũnene w’onthe wa Yeova ũla wekĩte kwondũ wa Isilaeli.'),
('kam', 'JDG', 2, 8, 'Na Yosua mwana wa Nuni, mũthũkũmi wa Yeova, akw’a, e wa myaka ĩana na ĩkũmi.'),
('kam', 'JDG', 2, 9, 'Na mamũthika mũvakanĩ wa ũtiĩwa wake ku Timinathi‐eelesi, nthĩ yĩ iĩma ya Evalaimu, ngalĩ ya ĩũlũ ya kĩĩma kya Ngaasi.'),
('kam', 'JDG', 2, 10, 'O na andũ onthe ma nzyawa ĩsu yonthe moombanw’a vamwe na aaĩthe moo, na kwookĩla nzyawa ĩngĩ ĩtina woo, ĩla ĩtamwĩsĩ Yeova, o na ĩteesĩ wĩa ũla wekĩte kwondũ wa Isilaeli.'),
('kam', 'JDG', 2, 11, 'Na ana ma Isilaeli meekaa ũla Yeova wonaa wĩ ũthũku, na mathũkũmaa Mbaalimu;'),
('kam', 'JDG', 2, 12, 'na mamũtia Yeova, Ngai wa aaĩthe moo, ũla wamaumisye nthĩ ya Misili, na maatĩĩa ngai ingĩ, ngainĩ sya ngo sya andũ ila syamathyũlũlũkĩte, na masyĩkunamĩsya: na mamũthatya Yeova.'),
('kam', 'JDG', 2, 13, 'Na mamũtia Yeova, na mathũkũmaa Mbaali na Asetalothi.'),
('kam', 'JDG', 2, 14, 'Na ũthatu wa Yeova wakanĩa Isilaeli, nake amanengane mokonĩ ma anangi ala mamanangaa; na amathoosya mokonĩ ma amaitha moo ala mamathyũlũlũkĩte, mũvaka matyaatonya kũũngama ĩngĩ mbee wa amaitha moo.'),
('kam', 'JDG', 2, 15, 'O kw’onthe kũla maendĩe kw’oko kwa Yeova kwaĩ ĩũlũ woo kwondũ wa ũthũku, o tondũ Yeova waĩtye, na o tondũ Yeova wameavĩe: na maĩ athĩn’ye mũno.'),
('kam', 'JDG', 2, 16, 'Na Yeova aũngamasya asili, ala mamavonokasya mokonĩ ma ala mamanangaa.'),
('kam', 'JDG', 2, 17, 'Na vamwe na ũu matyaamethukĩĩasya asili moo; nĩkwĩthĩwa nĩmeekaa ũmalwaya makĩatĩĩa ngai ingĩ, na kũsyĩkunamĩsya: nĩmelelũkaa na mĩtũkĩ kuma nzĩanĩ ĩla aaĩthe moo maendelaa, makĩw’aa mĩao ya Yeova; ĩndĩ mo matyaaĩka ũu.'),
('kam', 'JDG', 2, 18, 'Na yĩla Yeova wamaũngamĩsya asili, nĩvo ĩndĩ Yeova waĩ vamwe na mũsili ũsu, na aimavonokya kuma mokonĩ ma amaitha moo mĩthenya yonthe ya mũsili ũsu: nũndũ Yeova nĩwetũngaa nũndũ wa kũluma kwoo kwondũ wa ala mamathĩnasya na kũmew’ĩthasya woo.'),
('kam', 'JDG', 2, 19, 'Ĩndĩ kweethĩawa, o yĩla mũsili wakw’a, nĩmasyokaa na ĩtina, na kwĩvukasya kwĩ aaĩthe moo, kwondũ wa kũatĩĩa ngaĩ ingĩ na kwithũkũmaa, na kũsyĩkunamĩasya; matyaaekana na meko moo kana mũendele woo wa kwaa matũ.'),
('kam', 'JDG', 2, 20, 'Na ũthatu wa Yeova wakanĩa Isilaeli; an asya, Nũndũ mbaĩ ĩno nĩvĩtĩtye ũtianĩo wakwa ũla nameaĩe aaĩthe moo, na matyaaĩthukĩĩsya wasya wakwa;'),
('kam', 'JDG', 2, 21, 'nakwa nyie kuma yu ndikailũngya mbaĩ ila Yosua watialilye aikw’a syume vala maĩ;'),
('kam', 'JDG', 2, 22, 'nĩ kana nĩmatatae Isilaeli nasyo ethĩwa makakwataa nzĩa ya Yeova mamĩendelae, o tondũ aaĩthe moo mamĩkwataa, kana ti w’o.'),
('kam', 'JDG', 2, 23, 'Kwondũ wa ũu Yeova aeka mbaĩ isũ, ate kwilũngya na mĩtũkĩ; o na ndaainengane kw’okonĩ kwa Yosua.'),
('kam', 'JDG', 3, 1, 'Na ĩndĩ ii nĩsyo mbaĩ ila Yeova watialilye atatae Isilaeli nasyo, o ala ma Isilaeli ala mataamanya makaũ onthe ma ku Kanaani;'),
('kam', 'JDG', 3, 2, 'no kana mosyaanĩo ma ana ma Isilaeli mamanyae, nĩ kana mamanyĩaw’e kũkita, na mũno mũno o asu ala mataamanya mbee ũndũ o na ũmwe wakw’o:'),
('kam', 'JDG', 3, 3, 'na nĩsyo ii, eaĩi atano ma Avilisiti, na Akanaani onthe, na Asitoni, na Aivi ala matũaa kĩĩmanĩ kya Levanoni, kuma kĩĩma kya Mbaalielimoni kũvika ũlikĩlonĩ wa Amathi.'),
('kam', 'JDG', 3, 4, 'Nasyo saytiiwe sya kũtataa Isilaeli nasyo, ũndũ wa kũmanyaa ethĩwa makeethukĩĩasya mĩao ya Yeova, ĩla weaĩe aaĩthe moo na kanyw’a wa Mose.'),
('kam', 'JDG', 3, 5, 'Na ana ma Isilaeli namo matũa katĩ wa Akanaani, na Aititi, na Aamoli, na Avelisi, na Aivi, na Ayevusi:'),
('kam', 'JDG', 3, 6, 'namo matwaa eĩtu ma asu methĩwe aka moo, namo manenga ana ma asu eĩtu moo, na kũthũkũmaa ngai sya asu.'),
('kam', 'JDG', 3, 7, 'Na ana ma Isilaeli meekaa ũla Yeova wonaa wĩ ũthũku, na kũlwa nĩ Yeova Ngai woo, na mathũkũmaa Mbaalimu na Asetalothi.'),
('kam', 'JDG', 3, 8, 'Kwondũ wa ũu ũthatu wa Yeova wakanĩa Isilaeli, nake amathoosya kw’okonĩ kwa Kusani‐lisathaimu mũsumbĩ wa Mesovotamia: na ana ma Isilaeli mamũthũkũma Kusani‐lisathaimu myaka nyanya.'),
('kam', 'JDG', 3, 9, 'Na yĩla ana ma Isilaeli mamwĩkaĩlile Yeova, Yeova amaũngamĩsya ana ma Isilaeli mũtangĩĩi, ũla wamatangĩĩe, nake nĩ Othinieli mwana wa Kenasi, mũinae we Kalevu.'),
('kam', 'JDG', 3, 10, 'Na veva wa Yeova ooka ĩũlũ wake, nake asilanasya Isilaeli; na auma akokite, na Yeova amũnengane Kusani‐lisathaimu mũsumbĩ wa Mesovotamia kw’okonĩ kwake: na kw’oko kwake kwamũkĩlya Kusani‐lisathaimu vinya.'),
('kam', 'JDG', 3, 11, 'Na ĩ nthĩ yathũmũa myaka mĩongo ĩna. Na Othinieli mwana wa Kenasi akw’a.'),
('kam', 'JDG', 3, 12, 'Na ana ma Isilaeli meeka ĩngĩ ũla Yeova wonaa wĩ ũthũku: na Yeova amwĩkĩa Ekeloni mũsumbĩ wa Moavi vinya okite na Isilaeli, nũndũ nĩmekĩte ũla Yeova wonaa wĩ ũthũku.'),
('kam', 'JDG', 3, 13, 'Na Ekeloni amomban’ya kwake ana ma Amimoni na Amaleki; na athi na akũna Isilaeli, na moosa ĩla ndũa ya mĩtende yĩthĩwe ng’ũndũ yoo.'),
('kam', 'JDG', 3, 14, 'Na ana ma Isilaeli mamũthũkũma Ekeloni mũsumbĩ wa Moavi myaka ĩkũmi na nyanya.'),
('kam', 'JDG', 3, 15, 'Ĩndĩ yĩla ana ma Isilaeli mamwĩkaĩlile Yeova, we Yeova amaũngamĩsya mũtangĩĩi, o Euti mwana wa Ngela, ũla Mũmbenyamini, mũndũ waĩ kĩmotho. Na ana ma Isilaeli mamũtwaĩa Ekeloni mũsumbĩ wa Moavi mũvothi na kw’oko kwa ũsu.'),
('kam', 'JDG', 3, 16, 'Na Euti eetuĩa ũvyũ waĩ mũĩ ngalĩ syelĩ, ũasa waw’o mũkono ũmwe; na awĩyovela nthĩnĩ wa ngũa yake nthũnũnĩ yake ya kw’oko kwa aũme.'),
('kam', 'JDG', 3, 17, 'Na amũnenga Ekeloni mũsumbĩ wa Moavi ũla mũvothi: na ĩndĩ Ekeloni aĩ mũndũ mũnou mũno.'),
('kam', 'JDG', 3, 18, 'Na amina kũmũnenga mũvothi ũsu, amea andũ ala maetie mũvothi mathi.'),
('kam', 'JDG', 3, 19, 'Ĩndĩ we mwene eetulũlĩle vala vasũvaw’a mĩvw’anano vakuvĩ na Ngilikali, na asya, Nyie nĩ na ũtũmane wa kĩmbithĩ kwaku, we mũsumbĩ. Nake asya, Vindyai. Na onthe ala maũngamĩte vakuvĩ nake mauma vala ũĩ.'),
('kam', 'JDG', 3, 20, 'Na Euti ooka vala ũĩ; nake ekalĩte e weka nyũmbanĩ ya ĩũlũ ya mbevo. Na Euti asya, Nĩ na ũtũme kwaku kuma kwa Ngai. Na ookĩla kĩvĩlanĩ kyake.'),
('kam', 'JDG', 3, 21, 'Na Euti atambũũkya kw’oko kwake kwa aka, na akũa ũvyũ nthũnũnĩ ya kw’oko kwake kwa aũme, na amũvũthũa ĩvu naw’o:'),
('kam', 'JDG', 3, 22, 'na mbusya o nayo yalikanĩlya na ũvyũ; na mathunya malindĩla ũvyũ, nũndũ ndaamũkũa ũvyũ ĩvunĩ yake; na wakuthũkana mũongo.'),
('kam', 'JDG', 3, 23, 'Nĩvo ĩndĩ Euti waumaalile valasyanĩ, na amũvingĩa mĩomo ya nyũmba ĩsu ya ĩũlũ, na avinga ki.'),
('kam', 'JDG', 3, 24, 'Na ĩndĩ yĩla waendie athũkũmi make mooka; namo moona, na, sisya, mĩomo ya nyũmba ĩsu ya ĩũlũ nĩ mĩvinge ki, na masya, Vate ndĩi evw’ĩkĩte maũũ make e nyũmbanĩ ya ĩũlũ.'),
('kam', 'JDG', 3, 25, 'Na meteelanga mũvaka meew’a nthoni; na, sisya, ndaavingũa mĩomo ya nyũmba ya ĩũlũ: kwondũ wa ũu moosa ũvungũo, na mamĩvingũa; na, sisya, mwĩaĩi woo avalũkĩte nthĩ e mũkw’ũ.'),
('kam', 'JDG', 3, 26, 'Na Euti eevonokya yĩla meeteelete, na avĩtũka vala vasũvĩaw’a mĩvw’anano, na eevonokĩsya Seila.'),
('kam', 'JDG', 3, 27, 'Na kweethĩwa, yĩla wavikie, avuvĩa soo nthĩ yĩ iĩma ya Evalaimu; na ana ma Isilaeli matheea vamwe nake kuma nthĩ yĩ iĩma, e mbee woo.'),
('kam', 'JDG', 3, 28, 'Na amea, Ngatĩĩai; nũndũ Yeova nũnenganĩte amaitha menyu Amoavi mokonĩ menyu. Na matheea mamũatĩĩe, na makwata masyũko ma Yolotani masiĩĩe Amoavĩ, na matyaamũnenga mũndũ ũthei wa kũinga.'),
('kam', 'JDG', 3, 29, 'Na ĩvinda yĩu makũna ma Moavi andũ ta ngili ĩkũmi, kĩla mũndũ mũnou, na kĩla mũndũ ngũmbaũ; na vati mũndũ waavĩta.'),
('kam', 'JDG', 3, 30, 'Ũu nĩw’o Moavi wakĩlĩlw’e vinya mũthenya ũsu na kw’oko kwa Isilaeli. Na nthĩ yathũmũa myaka mĩongo nyanya.'),
('kam', 'JDG', 3, 31, 'Na ĩtina wake kwaĩ Samukalĩ mwana wa Anathi, ũla wakũnie Avilisiti maana thanthatũ na mũsenge wa kũinga ng’ombe: o nake amatangĩĩa Isilaeli.'),
('kam', 'JDG', 4, 1, 'Na ana ma Isilaeli meeka ĩngĩ ũla Yeova wonaa wĩ ũthũku, yĩla Euti wakwie.'),
('kam', 'JDG', 4, 2, 'Na Yeova amathoosya kw’okonĩ kwa Yavini mũsumbĩ wa Kanaani, ũla wasumbĩkĩte ku Asoli; na kavuteni wa nguthu ya ũsu aĩ Sisela, ũla watwie Alosethi wa Andũ‐ma‐mbaĩ‐ingĩ.'),
('kam', 'JDG', 4, 3, 'Na ana ma Isilaeli mamwĩkaĩla Yeova: nũndũ Sisela aĩ na makasya ma kaũ maana kenda ma iaa; na nĩwathĩnasya ana ma Isilaeli na vinya myaka mĩongo ĩlĩ.'),
('kam', 'JDG', 4, 4, 'Na ĩvinda yĩu Ndevola, mwathani mũndũ mũka, kĩveti kya Lavitothi, nĩkyasilanasya Isilaeli.'),
('kam', 'JDG', 4, 5, 'Nake ekalaa ĩtina wa mũtende wa Ndevola, katĩ wa Lama na Mbethi‐eli, nthĩ yĩ iĩma ya Evalaimu: na ana ma Isilaeli mambataa vala ũĩ nĩ kana makasilanw’e.'),
('kam', 'JDG', 4, 6, 'Na atũmana Mbalaka aketwe, mwana wa Avinoamu, kuma Ketesi‐navitali, na amwĩa, Yeova, Ngai wa Isilaeli, ndakwĩaĩĩte, aikwĩa, Enda ũthengeee kĩĩmanĩ kya Tavoli, na ũkĩthi na andũ ngili ĩkũmi ma ana ma Navitali na ma ana ma Nzevuluni?'),
('kam', 'JDG', 4, 7, 'Nakwa ngakũthengeesya Sisela ũsĩnĩ wa Kisoni, kavuteni wa ita sya Yavini, vamwe na makasya make ma kaũ na nguthu yake; na ngamũnengane kw’okonĩ kwaku.'),
('kam', 'JDG', 4, 8, 'Na Mbalaka amwĩa, Ethĩwa nũkũendan’ya nakwa, nĩngũthi; ĩndĩ ethĩwa ndwĩendan’ya nakwa, ndithi.'),
('kam', 'JDG', 4, 9, 'Nake amwĩa, Nditĩa kũthi naku: ĩndĩ kyalo kyu ũkũthi kĩtyĩthĩwa kya ndaĩa yaku; nũndũ Yeova akanengane Sisela kw’okonĩ kwa mũndũ mũka. Na Ndevola ookĩla, na athi Ketesi, e na Mbalaka.'),
('kam', 'JDG', 4, 10, 'Na Mbalaka eeta a Nzevuluni na a Navitali mombane Ketesi; na mambata andũ ngili ĩkũmi mamũatĩĩe: na Ndevola ambata vamwe nake.'),
('kam', 'JDG', 4, 11, 'Na ĩndĩ Eeveli Mũkeni nĩwevathanĩte na Akeni, o ana ma Ovavu mũthoni wa Mose, na akamba ĩeema yake o vaasa ta vala vaĩ mũtĩ wa mwaloni ku Nzaananĩmu, ĩla yĩ ũtee wa Ketesi.'),
('kam', 'JDG', 4, 12, 'Na matavya Sisela kana Mbalaka mwana wa Avinoamu nĩwambatĩte kĩĩmanĩ kya Tavoli.'),
('kam', 'JDG', 4, 13, 'Na Sisela oomban’ya kuma Alosethi ya Andũ‐ma‐mbaĩ‐ingĩ, kũvika ũsĩnĩ wa Kisoni, makasya make onthe ma kaũ, o makasya maana kenda ma iaa, na andũ onthe ala maĩ vamwe nake.'),
('kam', 'JDG', 4, 14, 'Na Ndevola amwĩa Mbalaka, Ũkĩla; nũndũ ũũ nĩ mũthenya ũla Yeova ũnenganĩte Sisela kw’okonĩ kwaku; Yeova ndaumaalĩte akũtongoesye? Kwondũ wa ũu Mbalaka atheea kũma kĩĩmanĩ kya Tavoli, e na andũ ngili ĩkũmi mamũatĩĩe.'),
('kam', 'JDG', 4, 15, 'Na Yeova amũthokoan’ya Sisela, na makasya make onthe ma kaũ, na nguthu yake yonthe, kwa kũtemanga na ũvyũ Mbalaka e vo; na Sisela auma ĩkasyanĩ yake ya kaũ, na akũka na maũũ.'),
('kam', 'JDG', 4, 16, 'Ĩndĩ Mbalaka aatĩĩa makasya ma kaũ na nguthu, kũvika Alosethi ya Andũ‐ma‐mbaĩ‐ingĩ: na nguthu yonthe ya Sisela yavalũkw’a ĩtemangĩtwe na ũvyũ; vatyaatiala mũndũ o na ũmwe.'),
('kam', 'JDG', 4, 17, 'Ĩndĩ Sisela akũka na maũũ avika ĩeemanĩ ya Yaeli mũka wa Eeveli ũla Mũkeni; nũndũ kwaĩ mũuo katĩ wa Yavini mũsumbĩ wa Asoli na nyũmba ya Eeveli ũla Mũkeni.'),
('kam', 'JDG', 4, 18, 'Na Yaeli athi amũthaũe Sisela, na amwĩa, Athũka, mwĩaĩi wakwa, athũkĩla vaa nĩĩ; ndũkakĩe. Na athũka alika ĩeemanĩ kwake, na amũvw’ĩkĩĩa ĩvula.'),
('kam', 'JDG', 4, 19, 'Na amwĩa, Nĩngũkwĩsũva, nenga tũmanzĩ nĩnyw’e; nũndũ nĩ na waũni. Na akunũa kathatwa ke ĩia, na amũnenga anyw’e, na amũvw’ĩka.'),
('kam', 'JDG', 4, 20, 'Na amwĩa, Ũngama mũomonĩ wa ĩeema, na kwĩthĩwe ethĩwa mũndũ o na wĩva nũnũkũka na ũkũkũlya, akyasya, Ve mũndũ ũngĩ vaa? Mwĩe, Aiee.'),
('kam', 'JDG', 4, 21, 'Nĩvo ĩndĩ Yaeli mũka wa Eeveli wosie kyambo kya ĩeema, na oosa kĩiva na kw’oko, na amũtonea, na amũkũnĩĩla ũthĩanĩ na kyambo, na kyakũthũkana kyatonya nthĩ; nũndũ aĩ na too mũnene; nake anyooka na akw’a.'),
('kam', 'JDG', 4, 22, 'Na, sisya, Mbalaka aatĩĩe Sisela, Yaeli aumaala amũthaũe, na amwĩa, Ũka, na nĩngũkwon’ya mũndũ ũla ũũmantha. Na ooka vala ũĩ; na, sisya, Sisela akomete e mũkw’ũ, na kĩla kyambo kĩ ũthĩanĩ kĩkuthũkene.'),
('kam', 'JDG', 4, 23, 'Ũu nĩw’o Ngai wakĩlilye Yavini mũsumbĩ wa Kanaani vinya kwondũ wa ana ma Isilaeli mũthenya ũsu.'),
('kam', 'JDG', 4, 24, 'Na kw’oko kwa ana ma Isilaeli kwakĩlya Yavini mũsumbĩ wa Kanaani vinya mbee na mbee, mũvaka mamwananga Yavini mũsumbĩ wa Kanaani.'),
('kam', 'JDG', 5, 1, 'Nĩvo ĩndĩ Ndevola na Mbalaka mwana wa Avinoamu mainie mũthenya ũsu, makyasya,'),
('kam', 'JDG', 5, 2, 'Nũndũ atongoi nĩmatongoetye nthĩnĩ wa Isilaeli, Nũndũ andũ nĩmeenenganie na ngoo ya kwenda, Mũtaĩei Yeova.'),
('kam', 'JDG', 5, 3, 'Ĩw’ai, inyw’ĩ asumbĩ; teai matũ, inyw’ĩ anene; Nyie, o nyie, ngamwinĩa Yeova; Ngaina ngĩkumya Yeova, Ngai wa Isilaeli.'),
('kam', 'JDG', 5, 4, 'Yeova, yĩla waumaalile kuma Seili, Yĩla waendie wauma nthĩ ya Etomu, Nthĩ nĩyatetemie, matu namo mavalũka, Ĩĩ, mathweo metĩkya kĩw’ũ.'),
('kam', 'JDG', 5, 5, 'Iĩma syatetema Yeova e vo, O Sinai kĩya nakyo Yeova, Ngai wa Isilaeli, e vo.'),
('kam', 'JDG', 5, 6, 'Mĩthenyanĩ ya Samukali mwana wa Anathi, Mĩthenyanĩ ya Yaeli, malelũ matyaĩ andũ, Na aendi ma kyalo maendelaa tũsĩlanĩ twa myathũko.'),
('kam', 'JDG', 5, 7, 'Asumbĩki mathela nthĩnĩ wa Isilaeli, nĩmathelile, Mũvaka yĩla nyie Ndevola nookĩlile, Nookĩla nĩ inyia nthĩnĩ wa Isilaeli.'),
('kam', 'JDG', 5, 8, 'Nĩmanyuvie ngai ingĩ; Na ĩndĩ kwaĩ kaũ i mbingĩlonĩ: Nĩkwoonekie ngao kana ĩtumo Katĩ wa andũ ngili mĩongo ĩna ma Isilaeli?'),
('kam', 'JDG', 5, 9, 'Ngoo yakwa nĩyelekele makavana ma Isilaeli, Ala meenenganie na ngoo ya kwenda katĩ wa andũ: Mũtaĩei Yeova.'),
('kam', 'JDG', 5, 10, 'Ũtavan’yei, inyw’ĩ ala mũkuawa nĩ mang’oi meũ, Inyw’ĩ ala mwĩkalĩlaa mĩkeka yĩ thooa mũnene, Na inyw’ĩ ala mũendaa na nzĩa.'),
('kam', 'JDG', 5, 11, 'O kũasa na kĩlonzo kya ala ma mata, kũla kũtavawa manzĩ, Kũu makawetangĩa meko malũngalu ma Yeova, O meko malũngalu ma ũsumbĩki wake nthĩnĩ wa Isilaeli. Nĩvo ĩndĩ andũ ma Yeova matheeie i mbingĩlonĩ.'),
('kam', 'JDG', 5, 12, 'Amũka, amũka, Ndevola; Amũka, amũka, ina wathi: Ũkĩla, Mbalaka, twaa ala ũtavĩte, we, mwana wa Avinoamu.'),
('kam', 'JDG', 5, 13, 'Nĩvo ĩndĩ kwatheeie ũtialo wa anene me ndaĩa o na andũ; Yeova atheea kwondũ wakwa okite na ala me vinya mũnene.'),
('kam', 'JDG', 5, 14, 'Kuma Evalaimu matheea ala kĩtina kyoo kĩ ku Amaleki; Ĩtina waku, Mbenyamini, katĩ wa ngo sya andũ maku; Kuma Makili matheea makavana, Na kuma Nzevuluni ala makuaa ndata ya mũandikĩ.'),
('kam', 'JDG', 5, 15, 'Na anene ma Isakali maĩ vamwe na Ndevola; O tondũ Isakali wailyĩ, now’o Mbalaka wailyĩ; Masemba malika mwandanĩ mamũkinyĩlĩte itiinyo. Ũtee wa mĩmeo ya tũlũsĩ twa Leuveni Vaĩ kũsũanĩĩwa kũnene kwa ngoo.'),
('kam', 'JDG', 5, 16, 'Wekalĩte syengonĩ sya malondu nĩkĩ, Wĩw’ae mĩtũlilũ ĩla ĩnĩũvuvĩwa ndĩthya sya mbũi na malondu? Ũtee wa mĩmeo ya tũlũsĩ twa Leuveni Vaĩ mothianĩo manene ma ngoo.'),
('kam', 'JDG', 5, 17, 'Ngileati atwĩe mũingo wa Yolotani: Na Ndani, ekalaa ngalawanĩ nĩkĩ? Aseli ekalaa auĩtye kĩthũmũonĩ ũtee wa ũkanga, Na ekalaa ũtee wa syoko syĩ kwake.'),
('kam', 'JDG', 5, 18, 'Nzevuluni maĩ ũko wa andũ ũla walekilye mathayũ moo mũisyonĩ kũvika kĩkw’ũ, O na Navitali, ĩũlũ wa kũla kũndũ kũtũlu kwa nthĩ.'),
('kam', 'JDG', 5, 19, 'Asumbĩ mooka na mokita; Nĩvo ĩndĩ asumbĩ ma Kanaani mokitĩe, Ku Taanaki ũtee wa manzĩ ma Mekito: Matyaaosa ũtandĩthyo wa mbesa.'),
('kam', 'JDG', 5, 20, 'Ndata nĩsyokitie syĩ ĩtunĩ, Syĩ nzĩanĩ syasyo syamũkita Sisela.'),
('kam', 'JDG', 5, 21, 'Ũsĩ wa Kisoni wamatwaa vyũ, Ũsĩ ũsu wa tene, ũsĩ wa Kisoni. We ngoo yakwa, endeea na vinya.'),
('kam', 'JDG', 5, 22, 'Nĩvo ĩndĩ mavũngũ ma mbalasi malumangya matuu Kwondũ wa kũtũlĩlanga, kũtũlĩlanga kwa ila syoo syĩ vinya.'),
('kam', 'JDG', 5, 23, 'Umanĩai Melosi, asya ũu mũlaĩka wa Yeova, Maumanĩei na wai ala matwĩe vo, Nũndũ matyaaũka kũmũtetheesya Yeova, Kũmũtetheesya Yeova kwa ala me vinya mũno.'),
('kam', 'JDG', 5, 24, 'Yaeli akaathimwa kũvĩtũka aka, Kĩveti kya Eeveli ũla Mũkeni; Akaathimwa kũvĩtũka aka ma ĩeemanĩ.'),
('kam', 'JDG', 5, 25, 'Eetya kĩw’ũ, nake amũnenga ĩia; Amũetee mauta ma meo me ĩsaaninĩ ĩseo mũno.'),
('kam', 'JDG', 5, 26, 'Atambĩĩa na kw’oko kyambo kya ĩeema, Na kw’oko kwake kwa aũme kĩiva kya mũndũ wa wĩa; Na amũkũnĩĩa Sisela na kĩla kĩiva, amũkũnĩĩa kyakuthũkana mũtwe wake; Ĩĩ, atonya na akĩkũna mũkuthũ nthĩanĩ syake.'),
('kam', 'JDG', 5, 27, 'Maũũnĩ make akunama, avalũka, akoma; Maũũnĩ make akunama, avalũka: O vala wakunamĩe, nĩvo wavalũkile e mũkw’ũ.'),
('kam', 'JDG', 5, 28, 'Asyaĩlya mbũthinĩ, na aĩa, O inyia wa Sisela aĩĩa mbũthinĩ yĩ mĩtĩ mĩkelangan’ye, Ĩkasya yake yĩkalile ĩvinda yĩana ũu nĩkĩ? Ndĩa sya makasya make syĩkalile ũu nĩkĩ?'),
('kam', 'JDG', 5, 29, 'Aka oĩ me ndaĩa ma kwake mamũsũngĩa, Ĩĩ, o nake mwene eesũngĩa,'),
('kam', 'JDG', 5, 30, 'Matyonete, na kũaan’ya mũtavo? Mwĩĩtu, eĩtu elĩ kĩla mũndũ; Kwa Sisela mũtavo wa ngũa syĩ malangi, Mũtavo wa ngũa syĩ malangi syanakavĩtw’e na ndii, Wa ngũa syĩ malangi syanakavĩtw’e na ndii ngalĩ syelĩ, syĩ ngingonĩ sya atavwa?'),
('kam', 'JDG', 5, 31, 'Amaitha maku onthe nĩmathele ũu, ame Yeova; Ĩndĩ ala mamwendaa nĩmethĩwe ta syũa yĩkyuma na vinya wayo mũnene. Na ĩ nthĩ yathũmũa myaka mĩongo ĩna.'),
('kam', 'JDG', 6, 1, 'Na ana ma Isilaeli meeka ũla Yeova wonaa wĩ ũthũku: na Yeova amanengane kw’okonĩ kwa Mitiani myaka mũonza.'),
('kam', 'JDG', 6, 2, 'Na kw’oko kwa Mitiani kwakĩlya Isilaeli vinya; na nũndũ wa Mitiani ana ma Isilaeli nĩmeeseũvĩsye maima ala me iĩmanĩ, na ngunga, na ngome syĩ vinya.'),
('kam', 'JDG', 6, 3, 'Na kweethĩwa, yĩla Isilaeli mavuĩie, Amitiani mambata, na Aamaleki, na ana ma ngalĩ ya wumĩlonĩ wa syũa; mambate mokite namo;'),
('kam', 'JDG', 6, 4, 'na mamba maeema mamataũĩĩe, na maananga ũsyao wa nthĩ, kũvika wavika Ngasa, na matyaatialya kwa Isilaeli kĩndũ kya kũmatethya, ĩlondu, kana ng’ombe, kana ĩng’oi.'),
('kam', 'JDG', 6, 5, 'Nũndũ mo me na indo syoo na maeema moo nĩmambatie; malikile aingĩ ta ngie; mo na ngamĩle syoo ityaĩ italĩka: namo malika nthĩ ĩsu mamyanange.'),
('kam', 'JDG', 6, 6, 'Na Isilaeli matheew’a mũno nũndũ wa Mitiani; na ana ma Isilaeli mamwĩkaĩla Yeova.'),
('kam', 'JDG', 6, 7, 'Na kweethĩwa, yĩla ana ma Isilaeli mamwĩkaĩlile Yeova nũndũ wa Mitiani,'),
('kam', 'JDG', 6, 8, 'Yeova atũmĩa ana ma Isilaeli mwathanĩ: nake amea, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Nyie nĩnamwambatisye inyw’ĩ kuma Misili, na kũmumya nyũmbanĩ ya ũkombo;'),
('kam', 'JDG', 6, 9, 'na nĩnamũvonokisye kuma mokonĩ ma Amisili, na kuma mokonĩ ma onthe ala mamũthĩnasya, na namalũngya maume mbee wenyu, na namũnenga nthĩ yoo;'),
('kam', 'JDG', 6, 10, 'na namwĩa, Ninyie Yeova Ngai wenyu; mũtikakĩe ngai sya Aamoli, ala mũtũaa nthĩ yoo. Ĩndĩ mũtyaaĩw’a wasya wakwa.'),
('kam', 'JDG', 6, 11, 'Na mũlaĩka wa Yeova ooka na ekala ĩtina wa mũtĩ wa mwaloni ũla waĩ Ovala, ĩla yaĩ ya Yoasi Mũavieseli: na mwana wake Ngiteoni avũĩaa nganũ kĩangĩonĩ kya nzavivũ, nĩ kana amĩvithe Amitiani.'),
('kam', 'JDG', 6, 12, 'Na mũlaĩka wa Yeova amumĩlĩla, na amwĩa, Yeova e vamwe naku, we ngũmbaũ nene.'),
('kam', 'JDG', 6, 13, 'Na Ngiteoni amwĩa, Ame, mwĩaĩi wakwa, ethĩwa Yeova e vamwe naitũ, nĩkĩ ĩndĩ maũndũ aa onthe matũkwatĩte? Na maĩva ala mawĩa make onthe ma ũseng’ya, ala aaĩthe maĩtũ matũtavisye ũndũ wamo, makyasya, Yeova ndatwambatisye kuma Misili? Ĩndĩ yu Yeova nũtũekete, na nũtũnenganĩte kw’okonĩ kwa Mitiani.'),
('kam', 'JDG', 6, 14, 'Na Yeova amũsisya, na amwĩa, Enda na vinya ũũ waku, ũkamatangĩĩe Isilaeli kuma kw’okonĩ kwa Mitiani: ndikũtũmĩte?'),
('kam', 'JDG', 6, 15, 'Nake amwĩa, Ame Mwĩaĩi, ngamatangĩĩe Isilaeli na kayũ? Sisya, mũvĩa witũ nĩw’o ngya nthĩnĩ wa Manase, nakwa ninyie mũnini mbee nyũmbanĩ ya nau.'),
('kam', 'JDG', 6, 16, 'Na Yeova amwĩa, Nditĩa kwĩthĩwa vamwe naku, naku ũkakũna Amitiani o ta mũndũ ũmwe.'),
('kam', 'JDG', 6, 17, 'Nake amwĩa, Ethĩwa nĩnendeesye kwaku yu, mbon’ya ĩndĩ wonan’wo nĩmanye kana nue ũũneena nakwa.'),
('kam', 'JDG', 6, 18, 'Nĩngũkwĩsũva, ndũkaume vaa kũvika nasyoka vala ũĩ, na kũete mũthĩnzĩo wakwa, na kwia mbee waku. Nake amwĩa, Nĩngweteela mũvaka wooka ĩngĩ.'),
('kam', 'JDG', 6, 19, 'Na Ngiteoni alika nthĩnĩ, na ooaa katena ka mbũi, na aseũvya tũmũtũ tũte ĩlawa twa eva ya mũtu: eekĩa nyama kĩkavũnĩ, na eekĩa mũthoi mbisũnĩ, na amũetee vau nza ĩtina wa mwaloni, na amũnenga.'),
('kam', 'JDG', 6, 20, 'Na ũla mũlaĩka wa Ngai amwĩa, Osa nyama na tũmũtũ tũte ĩlawa, na ũkia ĩũlũ wa ĩvia yĩĩ, na ũkĩtulũla mũthoi. Nake eeka ũu.'),
('kam', 'JDG', 6, 21, 'Na ĩndĩ mũlaĩka wa Yeova atwaa mũthya wa ndata ĩla yaĩ kw’okonĩ kwake, na akiita ila nyama na tũmũtũ tũte ĩlawa; na kwauma mwaki yĩla ĩvianĩ, na wamina ila nyama na tũmũtũ tũte ĩlawa; na ũla mũlaĩka wa Yeova auma vala ũĩ.'),
('kam', 'JDG', 6, 22, 'Na Ngiteoni amanya atĩ ũsu eĩ mũlaĩka wa Yeova; na Ngiteoni asya, Ĩiaa, ame Mwĩaĩi Yeova! Nũndũ nĩnoonana na mũlaĩka wa Yeova ũthyũ kwa ũthyũ.'),
('kam', 'JDG', 6, 23, 'Na Yeova amwĩa, Mũuo wĩthĩwe kwaku; ndũkakĩe: ndwĩkw’a.'),
('kam', 'JDG', 6, 24, 'Nĩvo ĩndĩ Ngiteoni wamwakĩe Yeova kĩthembeo vu, na akĩta Yeova‐salomu: kũvika ũmũnthĩ kĩ o ku Ovala wa Aavieseli.'),
('kam', 'JDG', 6, 25, 'Na kweethĩwa ũtukũ o ũsu, Yeova amwĩa, Osa kasalũ ka au ka mũew’a, o kasalũ kala ka kelĩ ka myaka mũonza, na omboanga kĩthembeo kya Mbaali kĩla au wĩ nakyo, na ũitema mũvw’anano wĩtawa Asela ũla wĩ vakuvĩ nakyo;'),
('kam', 'JDG', 6, 26, 'na mwakĩe Yeova Ngai waku kĩthembeo ĩũlũ wa ngome ĩno yĩ vinya, kwĩanana na ũndũ waĩle, na osa kala kasalũ ka kelĩ, na ũkĩthemba nthembo ya kũvĩvw’a na ngũ sya ũla Asela ũla ũũtema.'),
('kam', 'JDG', 6, 27, 'Nĩvo ĩndĩ Ngiteoni wosie ĩkũmi ma athũkũmi make, na eeka o tondũ Yeova ũmũtavĩtye na kweethĩwa, nũndũ nĩwakĩaa andũ ma nyũmba ya ĩthe na andũ ma ĩ ndũa, ũndũ ũtatonya kwĩka ũu mũthenya, awĩkie ũtukũ.'),
('kam', 'JDG', 6, 28, 'Na yĩla andũ ma ĩ ndũa mookĩlile kĩoko tene, sisya, kĩla kĩthembeo kya Mbaali kyaĩ kĩomboe, na Asela waĩ mũteme ũkavalũka ũla waĩ vakuvĩ nakyo, na kala kasalũ ka kelĩ nĩkathembetwe ĩũlũ wa kĩthembeo kĩla kyaakiwe.'),
('kam', 'JDG', 6, 29, 'Na makũlan’ya ene kwa ene, Ũla wĩkie ũndũ ũũ nũũ? Na yĩla mamanthanie na kũkũlan’ya, masũngĩana, Ngiteoni mwana wa Yoasi nĩwe wĩkie ũndũ ũũ.'),
('kam', 'JDG', 6, 30, 'Nĩvo ĩndĩ andũ ma ndũa mamwĩie Yoasi, Umaalya mwana waku, nĩ kana akw’e, nũndũ nũomboangie kĩthembeo kya Mbaali, na nũndũ nũtemie Asela ũla wĩ vakuvĩ nakyo.'),
('kam', 'JDG', 6, 31, 'Na Yoasi amakũlya onthe ala maũngamie matetan’ye nake, Nĩmũũmũtetea Mbaali? Kana nĩmũũmũtangĩĩa? Ũla ũkũmũtetea, nĩoawe kũtanakya: ethĩwa nĩ ngai, nĩetetee mwene, nũndũ ũmwe nũomboie kĩthembeo kyake.'),
('kam', 'JDG', 6, 32, 'Kwondũ wa ũu mũthenya ũsu amwĩta Ngiteoni Yelumbaali, akyasya, Mbaali nĩetetee, nũndũ nũomboie kĩthembeo kyake.'),
('kam', 'JDG', 6, 33, 'Nĩvo ĩndĩ Amitiani na Aamaleki onthe na ana ma ngalĩ ya wumĩlonĩ wa syũa moombanie vamwe; na mainga na mamba maeema mwandanĩ wa Yesileeli.'),
('kam', 'JDG', 6, 34, 'Ĩndĩ Veva wa Yeova ooka ĩũlũ wa Ngiteoni; na avuva soo; na Avieseli moombana mamũatĩĩe.'),
('kam', 'JDG', 6, 35, 'Nake atũma atũmwa kwa Manase kw’onthe; o namo moombana mamũatĩĩe: na atũma atũmwa kwa Aseli, na kwa Nzevuluni, na kwa Navitali; namo mambata makomane namo.'),
('kam', 'JDG', 6, 36, 'Na Ngiteoni amwĩa Ngai, Ethĩwa ũkatangĩĩa Isilaeli na kw’oko kwakwa, o tondũ waĩtye,'),
('kam', 'JDG', 6, 37, 'sisya, nĩngwia w’ĩa wa ĩlondu kĩvũĩonĩ; ethĩwa kũkeethĩwa ĩmwe ĩũlũ wa w’ĩa wĩ w’oka, na nthĩ yonthe vu ĩkĩthĩwa yĩ nyũmũ, nĩvo ĩndĩ nĩmanya kana ũkatangĩĩa Isilaeli na kw’oko kwakwa, o tondũ waĩtye.'),
('kam', 'JDG', 6, 38, 'Na kweethĩwa o ta ũu; nũndũ ookĩla kĩoko tene ũnĩ ũsu, na ooviva, na aviva ĩmwe kuma ũ w’ĩanĩ, mbakũli mwĩta ya manzĩ.'),
('kam', 'JDG', 6, 39, 'Na Ngiteoni amwĩa Ngai, Ũthatu waku ndũkambakanĩe, na nĩngũneena o ĩvinda yĩĩ yoka: eka nĩtate, nĩngũkwĩsũva, o ĩvinda yĩĩ yoka na ũla w’ĩa; ũ w’ĩa e w’o wĩthĩwe wĩ mũmũ, na nthĩ yonthe vu yĩthĩwe na ĩmwe.'),
('kam', 'JDG', 6, 40, 'Na Ngai eeka ũu ũtukũ ũsu: nũndũ ũ w’ĩa now’o waĩ mũmũ, na kwaĩ ĩmwe nthĩ yonthe.'),
('kam', 'JDG', 7, 1, 'Nĩvo ĩndĩ Yelumbaali, ũla Ngiteoni, na andũ onthe ala maĩ nake, mookĩlile kĩoko tene, na mamba maeema vakuvĩ na mbuluti ya Alote: na mwako wa maeema wa Mitiani waĩ ngalĩ ya ĩũlũ woo mwandanĩ, vakuvĩ na kĩĩma kya Mole.'),
('kam', 'JDG', 7, 2, 'Na Yeova amwĩa Ngiteoni, Andũ ala wĩ namo nĩ aingĩ mũno ũndũ ndatonya kũmanengane Amitiani mokonĩ moo, Isilaeli matikese kwĩkathĩĩa ĩũlũ wakwa, makyasya, Kw’oko kwakwa mwene nĩkũndangĩĩĩte.'),
('kam', 'JDG', 7, 3, 'Yu ĩndĩ tavan’ya matũnĩ ma andũ, ũkĩmea, O ũla wĩ na w’ĩa na kũtetema, nasyoke aume kĩĩmanĩ kya Ngileati. Na kwasyoka ma andũ ngili mĩongo ĩlĩ na ilĩ; na kwatiala ngili ĩkũmi.'),
('kam', 'JDG', 7, 4, 'Na Yeova amwĩa Ngiteoni, Andũ no aingĩ o na yu; matheesye vala ve kĩw’ũ, na nĩngũũtatĩa mo vo: na kũkeethĩwa, ũla nĩkũtavya ũndũ wake atĩĩ, Ũũ nũkũthi naku, o ũsu nathi naku; na o ũla nĩkũtavya ũndũ wake atĩĩ, Ũũ ndethi naku, o ũsu ndakathi.'),
('kam', 'JDG', 7, 5, 'Na ĩndĩ atheesya andũ vala ve kĩw’ũ: na Yeova amwĩa Ngiteoni, Kĩla ũmwe ũla wĩlambalambya kĩw’ũ na ũĩmĩ, o tondũ ngitĩ ĩlambalambasya, ũsu wĩmũveta ũtee e weka; no ta ũu, kĩla ũmwe wĩtulya ndu anyw’e.'),
('kam', 'JDG', 7, 6, 'Na ũtalo wa ala malambalambilye, makĩtwaa kanyw’anĩ na kw’oko, maĩ andũ maana atatũ: ĩndĩ andũ ala angĩ onthe matulya ndu manyw’e kĩw’ũ.'),
('kam', 'JDG', 7, 7, 'Na Yeova amwĩa Ngiteoni, Ngamũtangĩĩa na andũ maana atatũ ala malambalambya, na kũmanengane Amitiani kw’okonĩ kwaku; na andũ ala angĩ onthe kĩla mũndũ nĩenũke kwake.'),
('kam', 'JDG', 7, 8, 'Na ĩndĩ andũ asu makua lĩu na masoo moo na moko moo; na amea andũ onthe ma Isilaeli kĩla mũndũ enũke ĩeemanĩ yake, ĩndĩ ekala na ala andũ maana atatũ: na mwako wa maeema wa Mitiani waĩ mwandanĩ ĩtheo wake.'),
('kam', 'JDG', 7, 9, 'Na kweethĩwa ũtukũ o ũsu Yeova amwĩa, Ũkĩla, ũtheee mwakonĩ wa maeema; nũndũ nĩnĩũnenganĩte kw’okonĩ kwaku.'),
('kam', 'JDG', 7, 10, 'Ĩndĩ ethĩwa nũũkĩa kũtheea, theea wĩ na Vula mũthũkũmi waku mwakonĩ wa maeema:'),
('kam', 'JDG', 7, 11, 'na ũkeew’a ũndũ meũneena; na ĩtina wa ũu moko maku nĩmeũya vinya nĩ kana ũtheee mwakonĩ wa maeema. Na ĩndĩ atheea e na Vula mũthũkũmi wake, mavikĩa ala meekĩe mĩĩo ya kaũ me ũtee wa mwako wa maeema.'),
('kam', 'JDG', 7, 12, 'Na Amitiani na Aamaleki na ana ma ngalĩ ya wumĩlonĩ wa syũa menyaĩtye mwandanĩ me aingĩ ta ngie; na ngamĩle syoo ityaĩ italĩka, o ta kĩthangathĩ kĩla kĩ ũtee wa ũkanga ũndũ wa kwingĩva.'),
('kam', 'JDG', 7, 13, 'Na yĩla Ngiteoni wavikie vo, sisya, kwaĩ mũndũ watavasya mũtindan’ya wake ndoto; na asya; Sisya, nĩnĩotie ndoto; na, sisya, kamũtũ ka mbaale kavingilitĩla mwako wa maeema wa Mitiani na kavika ĩeemanĩ, na kayĩkũna mũvaka yavalũka, na kayĩkũluman’ya, mũvaka ĩeema yeenyasya nthĩ.'),
('kam', 'JDG', 7, 14, 'Na mũtindan’ya wake amũsũngĩa amwĩa, Ũu ti ũndũ ũngĩ ate o ũvyũ wa Ngiteoni mwana wa Yoasi, mũndũ wa Isilaeli: Ngai nũnenganĩte Mitiani, na nguthu yonthe, kw’okonĩ kwake.'),
('kam', 'JDG', 7, 15, 'Na kweethĩwa, yĩla Ngiteoni wewie ndoto ĩkĩtavanw’a, na ũalyũlo wayo, athaitha; na asyoka mwakonĩ wa maeema wa Isilaeli, na asya, Ũkĩlai; nũndũ Yeova nũnenganĩte nguthu ya Mitiani mokonĩ menyu.'),
('kam', 'JDG', 7, 16, 'Na aaan’ya ala andũ maana atatũ nguthu itatũ, na amanenga onthe masoo mokonĩ moo, na itete nthei, syĩ na mũĩ nthĩnĩ wasyo.'),
('kam', 'JDG', 7, 17, 'Na amea, Nzisyai, na mũkĩka o ũndũ ngwĩka: na, sisyai, navika ũtee wa mwako wa maeema, nĩkwĩthĩwe o ũndũ nĩĩka, mwĩĩka o w’o.'),
('kam', 'JDG', 7, 18, 'Yĩla nĩvuva soo, nyie na onthe ala nĩ namo, nĩvo ĩndĩ nenyu mwĩvuva masoo ngalĩ syonthe sya mwako wa maeema, na mũkyasya, Nĩ kwondũ wa Yeova na Ngiteoni.'),
('kam', 'JDG', 7, 19, 'Na ĩndĩ Ngiteoni, na ala andũ ĩana maĩ nake, mavika ũtee wa mwako wa maeema ũsyaĩĩsyo wa katĩ ũkyambĩlĩla, o asyaĩĩsya makyuman’ya: na mavuva masoo, na mooaa ĩtete ila syaĩ mokonĩ moo.'),
('kam', 'JDG', 7, 20, 'Na nguthu isu itatũ syavuva masoo, na syooaa itete, na syakwata mũĩ na moko moo ma aka, na masoo na moko moo ma aũme nĩ kana mavuve: na maneena na wasya mũnene, Ũvyũ wa Yeova na wa Ngiteoni.'),
('kam', 'JDG', 7, 21, 'Na maũngama kĩla mũndũ vandũ vake melingĩle mwako wa maeema; na nguthu yonthe yasemba; na mausya ngemi, na mamalũngya.'),
('kam', 'JDG', 7, 22, 'Na mavuva ala masoo maana atatũ, na Yeova atuma ũvyũ wa kĩla ũmwe welekela mũtindan’ya wake, na nguthu yonthe; na nguthu yakũka kũvika Mbethi‐sita yelekele Nzelela, o kũvika mũvakanĩ wa Aveli‐meola, vakuvĩ na Tavathu.'),
('kam', 'JDG', 7, 23, 'Na andũ ma Isilaeli moombanĩte vamwe kuma Navitali, na kuma Aseli, na kuma Manase yonthe, na maatĩĩa Mitiani.'),
('kam', 'JDG', 7, 24, 'Na Ngiteoni atũma atũmwa nthĩ yonthe yĩ iĩma ya Evalaimu, akyasya, Theeai mũkite na Mitiani, na mũkyamba kũkwata iw’ũ kwĩ mo, o kũvika Mbethi‐mbala, o Yolotani. Na ĩndĩ andũ onthe ma Evalaimu moombanite vamwe, na makwata iw’ũ kũvika Mbethi‐mbala, o Yolotani.'),
('kam', 'JDG', 7, 25, 'Na makwata ala anene elĩ me mbee ũsumbĩnĩ ma Mitiani, Olevi na Nzeevu; na mamũaĩa Olevi ĩvianĩ ya Olevi, na Nzeevu mamũaĩa kĩangĩonĩ kya nzavivũ kya Nzeevu, na maatĩĩa Mitiani: na mamũetee Ngiteoni mĩtwe ya Olevi na Nzeevu mũingo wa Yolotani.'),
('kam', 'JDG', 8, 1, 'Na andũ ma Evalaimu mamũkũlya, Ũnatwĩkie ũu nĩkĩ, ũilea ũtwĩta yĩla ũnaendie kũkita na Mitiani? Nao mamũtetya mũno.'),
('kam', 'JDG', 8, 2, 'Nake amea, Nĩkĩte ata yũ kũmũvĩtũka inyw’ĩ? Kwĩthĩan’ya nzavivũ sya Evalaimu kũti kavaa kwĩ ngetha ya nzavivũ ya Avieseli?'),
('kam', 'JDG', 8, 3, 'Ngai nũnenganĩte anene me mbee ũsumbĩnĩ ma Mitiani, Olevi na Nzeevu, mokonĩ menyu: nakwa ndonyete kwĩka ata kũmũvĩtũka? Nĩvo ĩndĩ, yĩla waneenie ũu, ũthatu woo ũla wamwelekele walikile.'),
('kam', 'JDG', 8, 4, 'Na Ngiteoni avika Yolotani, na ainga, we, na ala andũ maana atatũ ala maĩ make, me anyalu, ĩndĩ no maatĩĩe.'),
('kam', 'JDG', 8, 5, 'Na amea andũ ma Sukothi, Nĩngũmwĩsũva, nengai andũ ala mangatĩĩe imũtũ; nũndũ nĩ anyalu, nakwa nĩatĩĩe Nzeva na Nzalimuna, ala asumbĩ ma Mitiani.'),
('kam', 'JDG', 8, 6, 'Na anene ma Sukothi mamũkũlya, Yu moko ma Nzeva na Nzalimuna me kw’okonĩ kwaku, nĩ kana ithyĩ tũnenge ita syaku imũtũ?'),
('kam', 'JDG', 8, 7, 'Na Ngiteoni amea, Kwondũ wa ũu yĩla Yeova wĩnengane Nzeva na Nzalimuna kw’okonĩ kwakwa, nĩvo nĩkalangĩthya mĩĩ yenyu mĩw’a ya weũnĩ na mĩtae ya kĩthekanĩ.'),
('kam', 'JDG', 8, 8, 'Na kuma vu ambata Venueli, na aneena na andũ ma vo o ta ũu; na andũ ma Venueli nao mamũsũngĩa o tondũ andũ ma Sukothi mamũsũngĩie.'),
('kam', 'JDG', 8, 9, 'Nake aneena na andũ ma Venueli o namo, akĩmea, Yĩla nĩsyoka na nũuo, ngaomboanga mwako ũũ mũtũlu wa mũnyoolo.'),
('kam', 'JDG', 8, 10, 'Na ĩndĩ Nzeva na Nzalimuna maĩ Kalikolĩ, vamwe na nguthu syoo, andũ ta ngili ĩkũmi na itano, onthe ala matialĩte ma nguthu yonthe ya ana ma ngalĩ ya wumĩlonĩ wa syũa; nũndũ kwavalũkilw’e andũ ngili ĩana na mĩongo ĩlĩ ala makũaa ũvyũ.'),
('kam', 'JDG', 8, 11, 'Na Ngiteoni ambata na nzĩa ya ala matũaa maeemanĩ ngalĩ ya wumĩlonĩ wa syũa ya Nova na Yokivea, na akũna nguthu ĩsu; nũndũ ĩ nguthu nĩyeyelele.'),
('kam', 'JDG', 8, 12, 'Na Nzeva na Nzalimuna makũka; na amaatĩĩa; na amakwata asumbĩ asu elĩ ma Mitiani, Nzeva na Nzalimuna, na amĩthokoan’ya ĩ nguthu yonthe.'),
('kam', 'JDG', 8, 13, 'Na Ngiteoni mwana wa Yoasi asyoka kuma kaũnĩ kuma kyambatonĩ kya Eelesi.'),
('kam', 'JDG', 8, 14, 'Na akwata mwanake wa andũ ma Sukothi, na amũkũlya: nake amũtavya ũndũ anene ma Sukothi matilyĩ, o na atumĩa ma vo, andũ mĩongo mũonza na mũonza.'),
('kam', 'JDG', 8, 15, 'Na avika kwa andũ ma Sukothi, na amea, Sisyai Nzeva na Nzalimuna, ala kwondũ wamo mwanthekeee, mũkĩmbĩa, Yu moko ma Nzeva na Nzalimuna me kw’okonĩ kwaku, nĩ kana tũnenge andũ maku ala anou lĩu?'),
('kam', 'JDG', 8, 16, 'Na oosa ala atumĩa ma ĩ ndũa, na mĩw’a ya weũnĩ na mĩtae ya kĩthekanĩ, na amamanyĩsya andũ ma Sukothi nayo.'),
('kam', 'JDG', 8, 17, 'Na aomboanga mwako mũtũlu wa mũnyoolo wa Venueli, na ooaa andũ ma ĩ ndũa.'),
('kam', 'JDG', 8, 18, 'Nĩvo ĩndĩ wakũlilye Nzeva na Nzalimuna, Nĩ andũ mailyĩ ata ala mwooaĩe Tavoli? Na mamũsũngĩa, O ũndũ ũilyĩ, now’o mailyĩ; kĩla ũmwe ailyĩ ta ana ma mũsumbĩ.'),
('kam', 'JDG', 8, 19, 'Na amea, Maĩ ana‐a‐ia, ana ma mwaitũ: o tondũ Yeova wĩ thayũ, kethĩwa nĩmwamaekie thayũ, ndimũaa.'),
('kam', 'JDG', 8, 20, 'Na amwĩa Yetheli ĩkithathi yake, Ũkĩla ũmoae. Ĩndĩ kĩmwana kĩtyaakũa ũvyũ wakyo; nũndũ nĩkyakĩaa, nĩkwĩthĩwa kyaĩ o kĩmwana.'),
('kam', 'JDG', 8, 21, 'Nĩvo ĩndĩ Nzeva na Nzalĩmuna maisye, Ũkĩla eue, ũtũkĩlĩĩle; nũndũ o ũndũ mũndũ ũilyĩ, now’o vinya wake ũilyĩ. Na Ngĩteoni ookĩla, na ooaa Nzeva na Nzalimuna, na oosa mavuo ala maĩ ngingonĩ sya ngamĩle syoo.'),
('kam', 'JDG', 8, 22, 'Nĩvo ĩndĩ andũ ma Isilaeli mamwĩie Ngiteoni, Tũsumbĩke, we na mwana waku, o na mwĩsũkũũu; nũndũ nũtũtangĩĩe kuma kw’okonĩ kwa Mitiani.'),
('kam', 'JDG', 8, 23, 'Na Ngiteoni amea, Ndimũsumbĩka, o na mwana wakwa ndemũsumbĩka: Yeova akamũsumbĩka.'),
('kam', 'JDG', 8, 24, 'Na Ngiteoni amea, Nĩnenda kũmwĩtya kĩndũ, nakyo nĩ kĩla mũndũ anenge ngome sya matũ sya mũtavo wake. (Nũndũ maĩ na ngome sya matũ sya thaavu, nũndũ maĩ Aisumaeli.)'),
('kam', 'JDG', 8, 25, 'Na masũngĩa, Nĩtũkwinengane na ngoo ya kwenda. Nao malan’ya ngũa nthĩ, na kĩla mũndũ alekya vo ngome sya matũ ila sya mũtavo wake.'),
('kam', 'JDG', 8, 26, 'Na ũito wa ngome sya matũ sya thaavu ila wetisye waĩ sekeli ngili na maana mũonza sya thaavu; eka mavuo na imanza, na ngũa iilyĩ ta ndune ila syeekĩĩtwe nĩ asumbĩ ma Mitiani, na eka mĩnyoo ĩla yaĩ ngingonĩ sya ngamĩle syoo.'),
('kam', 'JDG', 8, 27, 'Na Ngiteoni aseũvya evoti nasyo, na ayia ndũanĩ yake, o ku Olava: na Isilaeli onthe nĩmekaa ũmalwaya kw’o makĩyĩatĩĩa; na yatw’ĩka kĩtei kwa Ngiteonĩ, na nyũmba yake.'),
('kam', 'JDG', 8, 28, 'Na ĩndĩ Mitiani makĩlw’a vinya nĩ ana ma Isilaeli, na matyaaũkĩlya mĩtwe yoo ĩngĩ. Na nthĩ yathũmũa myaka mĩongo ĩna mĩthenyanĩ ya Ngiteoni.'),
('kam', 'JDG', 8, 29, 'Na Yelumbaalĩ mwana wa Yoasi athi ekala mũsyĩ kwake.'),
('kam', 'JDG', 8, 30, 'Na Ngiteoni aĩ na ana mĩongo mũonza ala wasyaĩte we mwene; nũndũ aĩ na iveti mbingĩ.'),
('kam', 'JDG', 8, 31, 'Na mũka wake ngombo ũla waĩ Sekemu, nake amũsyaĩa mwana, na amwĩta syĩtwa yake Avimeleki.'),
('kam', 'JDG', 8, 32, 'Na Ngiteoni mwana wa Yoasi akw’a e na ũkũu mũseo, na athikwa ngunganĩ ya Yoasi ĩthe wake vala vathikawa akw’ũ, ku Ovala ya Aavieseli.'),
('kam', 'JDG', 8, 33, 'Na kweethĩwa, o Ngiteoni akw’a, ana ma Isilaeli maalyũka ĩngĩ, na meekaa ũmalwaya makĩatĩĩa Mbaalimu, na matw’ĩkĩthya Mbaali‐mbelithi ngai yoo.'),
('kam', 'JDG', 8, 34, 'Na ana ma Isilaeli matyaamũlilikana Yeova Ngai woo, ũla wamavonokisye kuma mokonĩ ma amaitha moo onthe kĩla ngalĩko;'),
('kam', 'JDG', 8, 35, 'o na matyaamĩka nyũmba ya Yelumbaali nesa, ũla Ngiteoni, kwĩanana na ũseo w’onthe ũla wamekaa Isilaeli.'),
('kam', 'JDG', 9, 1, 'Na Avimeleki mwana wa Yelumbaali athi Sekemu kwa aaĩnaũme, na aneena namo, o na mũvĩa w’onthe wa nyũmba ya ĩthe wa inyia, akĩmea,'),
('kam', 'JDG', 9, 2, 'Nĩngũmwĩsũva, neenai matũnĩ ma andũ onthe ma Sekemu atĩĩ, Ũla ũseo kwenyu nĩ wĩva, nĩ ana onthe ma Yelumbaali, me mĩongo mũonza mamũsumbĩke, kana ũmwe amũsumbĩke? O na lilikanai kana nĩ ĩvĩndĩ yenyu na mwĩĩ wenyu.'),
('kam', 'JDG', 9, 3, 'Na mbaa ĩnaũme maneena ndeto ĩsu syonthe ũndũ wake matũnĩ ma andũ onthe ma Sekemu: na ngoo syoo syenda kũatĩĩa Avimeleki; nũndũ maisye, We nĩ mwana‐a‐inyia waitũ.'),
('kam', 'JDG', 9, 4, 'Na mamũnenga ilungu sya vetha mĩongo mũonza kuma nyũmbanĩ ya Mbaali‐mbelithi, ila Avimeleki watuvie andũ mate kĩĩĩ na ma mana, namo mamũatĩĩa.'),
('kam', 'JDG', 9, 5, 'Na athi nyũmbanĩ ya ĩthe ku Ovala, na ooaĩa ana‐a‐ĩthe make ana ma Yelumbaali ĩvianĩ yĩmwe, me andũ mĩongo mũonza: ĩndĩ Yothamu ĩlumaita ya Yelumbaali nĩyatiiwe; nũndũ nĩyeevithie.'),
('kam', 'JDG', 9, 6, 'Na andũ onthe ma Sekemu moombana vamwe, na nyũmba yonthe ya Milo, na mathi na mamũtw’ĩkĩthĩsya Avimeleki mũsumbĩ, ũtee wa mũtĩ wa mwaloni wa kĩtuĩ kĩla kyaĩ Sekemu.'),
('kam', 'JDG', 9, 7, 'Na yĩla mamũtavisye Yothamu, athi na aũngama mũtumbĩnĩ wa kĩĩma kya Ngelisimu, na ookĩlya wasya wake, na anĩĩsya, na amea, Mbĩthukĩĩsyaĩ, inyw’ĩ andũ ma Sekemu, nĩ kana Ngai amwĩthukĩĩsye.'),
('kam', 'JDG', 9, 8, 'Ĩvinda yĩmwe mĩtĩ nĩyaendie kwĩtĩkĩsya ũmwe mauta wĩthĩwe mũsumbĩ wayo; na yeea mũthata, Tũsumbĩke.'),
('kam', 'JDG', 9, 9, 'Ĩndĩ mũthata wamĩtavya, Nĩnaĩle kũtia mauta makwa, ala mataĩĩthasya Ngai o na andũ namo kwondũ wakwa, na ngĩthi kwĩyeeekangasya kũũ na kũũ ĩũlũ wa mĩtĩ?'),
('kam', 'JDG', 9, 10, 'Na mĩtĩ yeea mũkũyũ, Ũka we, ũtũsumbĩke.'),
('kam', 'JDG', 9, 11, 'Ĩndĩ mũkũyũ wamĩtavya, Nĩnaĩle kũtia mũyo wakwa, na ũsyao wakwa mũseo, na ngĩthi kwĩyeeekangasya kũũ na kũũ ĩũlũ wa mĩtĩ?'),
('kam', 'JDG', 9, 12, 'Na mĩtĩ yeea mũsavivũ, Ũka we, ũtũsumbĩke.'),
('kam', 'JDG', 9, 13, 'Na mũsavivũ wamĩtavya, Nĩnaĩle kũtia mbinyu yakwa mbĩthĩ, ĩla ĩtanĩthasya Ngai na mũndũ, na ngĩthĩ kwĩyeeekangasya kũũ na kũũ ĩũlũ wa mĩtĩ?'),
('kam', 'JDG', 9, 14, 'Nĩvo ĩndĩ mĩtĩ yonthe yatavisye mũtae, Ũka we, ũtũsumbĩke.'),
('kam', 'JDG', 9, 15, 'Na mũtae watavya mĩtĩ, Ethĩwa nĩv’o nĩmũũmbĩtĩkisya mauta nĩthĩwe mũsumbĩ wenyũ, yu ĩndĩ ũkai mwĩvithe muunyĩnĩ wakwa; na ethĩwa ti ũu, mwaki nĩwume mũtaenĩ ũvĩvye mĩkũũ ya Levanoni.'),
('kam', 'JDG', 9, 16, 'Na yu ĩndĩ, ethĩwa nĩmwĩkĩte w’o na ũlũngalu, kũmũtw’ĩkĩthya Avimeleki mũsumbĩ, na ethĩwa nĩmwĩkĩte Yelumbaali na nyũmba yake nesa, na nĩmũmwĩkĩte kwĩanana na ũndũ moko make maĩlĩtwe'),
('kam', 'JDG', 9, 17, '(nũndũ nau nĩwamũkitĩe, na alikya thayũ wake mũisyonĩ, na amũvonokya kuma kw’okonĩ kwa Mitiani:'),
('kam', 'JDG', 9, 18, 'nenyu nĩmũmyũkĩlĩĩle nyũmba ya nau mũnthĩ ũũ, na mwooaĩa ana make, andũ mĩongo mũonza, ĩvianĩ yĩmwe, na mwatw’ĩkĩthya Avimeleki, mwana wa mũthũkũmi wake mwĩĩtu, mũsumbĩ wa andũ ma Sekemu, nũndũ nĩ mwĩvae wenyu);'),
('kam', 'JDG', 9, 19, 'ethĩwa ĩndĩ nĩmwĩkĩte Yelumbaali na nyũmba yake w’o na ũlũngalu mũnthĩ ũũ, tanĩaĩ ĩndĩ Avimeleki, o nake namũtanĩe:'),
('kam', 'JDG', 9, 20, 'ĩndĩ ethĩwa ti ũu, mwaki nĩwume kwa Avimeleki, na ũivivya andũ ma Sekemu, na nyũmba ya Milo; na mwaki nĩwume kwa andũ ma Sekemu, na kuma nyũmbanĩ ya Milo, na ũivĩvya Avimeleki.'),
('kam', 'JDG', 9, 21, 'Na Yothamu asemba, na akĩa, na athi Mbeeli, na atũa kw’o, nũndũ wa kũkĩa Avimeleki, mwana‐a‐ĩthe.'),
('kam', 'JDG', 9, 22, 'Na Avimeleki aĩ mũnene wa Isilaeli myaka ĩtatũ.'),
('kam', 'JDG', 9, 23, 'Na Ngai atũma veva mũthũku katĩ wa Avimeleki na andũ ma Sekemu; na andũ ma Sekemu mamwĩka Avimeleki naĩ na ũkengani:'),
('kam', 'JDG', 9, 24, 'nĩ kana ũla ũng’endu weekiwe andũ mĩongo mũonza ma Yelumbaali wũke, na nĩ kana nthakame syoo syilĩĩlwe ĩũlũ wa Avimeleki mwana‐a‐ĩthe woo, ũla wamoaie, na ĩũlũ wa andũ ma Sekemu, ala meekĩie moko make vinya oae ana‐a‐ĩthe.'),
('kam', 'JDG', 9, 25, 'Na andũ ma Sekemu maia oveesya mĩtumbĩnĩ ya iĩma, namo mamavutaa onthe ala mavĩtĩlaa nzĩanĩ ĩsu vakuvĩ namo; na Avimeleki atavw’a.'),
('kam', 'JDG', 9, 26, 'Na Ngaali mwana wa Eveti ooka na ana‐a‐ĩthe, na athi Sekemu; na andũ ma Sekemu maia wĩkwatyo woo kwake.'),
('kam', 'JDG', 9, 27, 'Na mauma mathi mĩũndanĩ, na maketha mĩũndanĩ yoo ya mĩsavivũ, na maanga nzavivũ, na mavoka mboka, na mathi nyũmbanĩ ya ngai yoo, na maya na manyw’a, na mamũumanĩa Avimeleki.'),
('kam', 'JDG', 9, 28, 'Na Ngaali mwana wa Eveti asya, Avimeleki nũũ, na Sekemu nũũ, kana tũmũthũkũme? Ti mwana wa Yelumbaali? Na Nzevuli mũnene wa kwake? Thũkũmai andũ ma Amolu ĩthe wa Sekemu: ĩndĩ twĩmũthũkũma nĩkĩ?'),
('kam', 'JDG', 9, 29, 'Nenda kethĩwa andũ aa me kw’okonĩ kwakwa! Nĩvo ĩndĩ nĩthĩwa nĩmũveta Avimeleki. Na amwĩa Avimeleki, Ongela ita syaku, nokyumaala.'),
('kam', 'JDG', 9, 30, 'Na yĩla Nzevuli mũsumbĩki wa ndũa wewie ndeto sya Ngaali mwana wa Eveti, ũthatu wake wakana.'),
('kam', 'JDG', 9, 31, 'Na atũma atũmwa na ũseleke kwa Avimeleki, makamwie, Sisya, Ngaali mwana wa Eveti na ana‐a‐ĩthe nĩmokĩte Sekemu; na sisya, nĩmekũingĩanĩsya ndũa nĩ kana ĩkũalyũkĩle.'),
('kam', 'JDG', 9, 32, 'Na yu kwondũ wa ũu, ũkĩla ũtukũ, we na andũ ala me naku, na mũkoveesye kĩthekanĩ:'),
('kam', 'JDG', 9, 33, 'na kũkeethĩwa kĩoko, o syũa yauma, wĩũkĩla tene, na kũvithũkĩa ĩ ndũa; na, sisya, yĩla we na andũ ala me nake meumaala kũkita naku, ũkatonya kũmeka o kwĩanana na ũndũ wĩona mwanya.'),
('kam', 'JDG', 9, 34, 'Na Avimeleki ookĩla ũtukũ, na andũ onthe ala maĩ nake, na me nguthu inya mooveesya andũ ma Sekemu.'),
('kam', 'JDG', 9, 35, 'Na Ngaali mwana wa Eveti aumaala, na aũngama ũlikĩlonĩ mbingĩlonĩ ya ndũa: na Avimeleki na andũ ala maĩ nake mookĩla kuma vala moveesye.'),
('kam', 'JDG', 9, 36, 'Na yĩla Ngaali wonie andũ, amwĩa Nzevulĩ, Sisya, nĩkũtheeete andũ kuma mĩtumbĩnĩ ya iĩma. Na Nzevuli amwĩa, Wĩona muunyĩ ya iĩma ũkasya nĩ andũ.'),
('kam', 'JDG', 9, 37, 'Na Ngaali aneena ĩngĩ na asya, Sisya, nũkũtheeete andũ mavĩtĩle ĩ nthĩ katĩ, na nguthu ĩmwe yĩsĩle nzĩanĩ ya mũtĩ wa mwaloni wa Meonenimu.'),
('kam', 'JDG', 9, 38, 'Nĩvo ĩndĩ Nzevuli wamwĩie, Ũĩva yu ĩndĩ kanyw’a waku, ũndũ waisye, Avimeleki nũũ, kana tũmũthũkũme? Aa ti ũko wa andũ ala ũvũthĩtye? Nĩngũkwĩsũva, umaala yu wũkite namo.'),
('kam', 'JDG', 9, 39, 'Na Ngaali aumaala e mbee wa andũ ma Sekemu, na okita na Avimeleki.'),
('kam', 'JDG', 9, 40, 'Na Avimeleki amũkũa, na Ngaali akũkĩa mbee wake, na kwavalũkw’a aingĩ okite, o kũvika ũlikĩlonĩ mbingĩlonĩ.'),
('kam', 'JDG', 9, 41, 'Na Avimeleki atũa Aluma: na Nzevuli alũngya Ngaali na ana‐a‐ĩthe matikatũe Sekemu.'),
('kam', 'JDG', 9, 42, 'Na kweethĩwa ũnĩ ũsu, andũ maumaala mathi kĩthekanĩ; na matavya Avimeleki.'),
('kam', 'JDG', 9, 43, 'Na oosa andũ na amaaan’ya nguthu itatũ, na ooveesya kĩthekanĩ; na asisya, na, sisya, andũ maumaala kuma ndũanĩ; na amokĩlĩĩla, na amakũna.'),
('kam', 'JDG', 9, 44, 'Na Avimeleki, na nguthu ila syaĩ nake, makuthũka na vĩnya, na maũngama ũlikĩlonĩ mbingĩlonĩ ya ndũa: na ila nguthu ilĩ syakuthũkĩa ala maĩ kĩthekanĩ, na syamakũna.'),
('kam', 'JDG', 9, 45, 'Na Avimeleki okita na andũ ma ndũa ĩsu mũthenya ũsu w’onthe; na akwata ĩ ndũa, na ooaa andũ ala maĩ nthĩnĩ: na aomboanga ĩ ndũa, na amĩvũĩa mũnyũ.'),
('kam', 'JDG', 9, 46, 'Na yĩla andũ onthe ma mwako mũtũlu wa mũnyoolo wa Sekemu meewĩe ũvoo ũsu, malĩka ngomenĩ yĩ vinya ya nyũmba ya Elimbelithi.'),
('kam', 'JDG', 9, 47, 'Na Avimeleki atavw’a kana andũ onthe ma mwako mũtũlu wa mũnyoolo wa Sekemu nĩmombanĩte vamwe.'),
('kam', 'JDG', 9, 48, 'Na Avimeleki ambata kĩĩmanĩ kya Nzalĩmoni, we na andũ onthe ala maĩ nake; na Avimeleki oosa ĩthoka na kw’oko kwake, na atema ũvonge mĩtĩnĩ, na oosa awilĩĩla, kĩtuo: na eea andũ ala maĩ nake, Ũndũ mwoona neeka, ĩkalaatei, mwĩke o ũndũ neeka.'),
('kam', 'JDG', 9, 49, 'Na andũ asu onthe matema o take kĩla mũndũ ũvonge wake, na maatĩĩa Avimeleki, na masyĩkĩa ngomenĩ yĩ vinya, na makwatya ngome ĩsu yĩ vinya mwaki vala ve asu; kwondũ wa ũu andũ onthe ma mwako mũtũlu wa mũnyoolo wa Sekemu namo makw’a, aũme na aka ta ngili ĩmwe.'),
('kam', 'JDG', 9, 50, 'Nĩvo ĩndĩ Avimeleki waendie Thevesi, na amba maeema ataũĩĩe Thevesi, na amĩkwata.'),
('kam', 'JDG', 9, 51, 'Ĩndĩ kwaĩ mwako mũtũlu wa mũnyoolo wĩ winya nthĩnĩ wa ĩ ndũa, na aũme na aka onthe, na onthe ma ĩ ndũa, makĩĩĩa vo, na meevingĩa nthĩnĩ, na matũla kĩalanĩ kya ũla mwako mũtũlu wa mũnyoolo.'),
('kam', 'JDG', 9, 52, 'Na Avimeleki avika vala ve ũ mwako mũtũlu wa mũnyoolo, na awũkita, na athengeea mũomo wa ũ mwako mũtũlu wa mũnyoolo nĩ kana ovĩvye na mwaki.'),
('kam', 'JDG', 9, 53, 'Na mũndũ mũka ũmwe alekya nthio ya ĩvia mũtwenĩ wa Avimeleki, na amũvevenza kĩng’ala kyake.'),
('kam', 'JDG', 9, 54, 'Nĩvo ĩndĩ wetie na mĩtũkĩ mwanake ũla wamũkuĩaa mĩio yake ya kaũ, na amwĩa, Kũa ũvyũ waku, ũmbũae, nĩ kana andũ matikaaneene ũndũ wakwa, Mũndũ mũka nĩwamũaie. Na mwanake wake amũtonya mũkuthũ, na akw’a.'),
('kam', 'JDG', 9, 55, 'Na yila andũ ma Isilaeli moonie kana Avimeleki nĩwakw’a, mathi kĩla mũndũ kwake.'),
('kam', 'JDG', 9, 56, 'Ũu nĩw’o Ngai wamũĩvie Avimeleki ũthũku wake, ũla wekie ĩthe, ũndũ wa kũaa ana‐a‐ĩthe mĩongo mũonza;'),
('kam', 'JDG', 9, 57, 'na Ngai nĩwaĩvanĩĩsye ũthũku w’onthe wa andũ ma Sekemu mĩtwenĩ yoo: na kĩumo kya Yothamu mwana wa Yelumbaali nĩkyamakwatie.'),
('kam', 'JDG', 10, 1, 'Na ĩtina wa Avimeleki kwookĩla Tola mwana wa Vua, mwana wa Ndoto, mũndũ wa Isakali, amatangĩĩe Isilaeli; nake atũa Samili ku nthĩ yĩ iĩma ya Evalaimu.'),
('kam', 'JDG', 10, 2, 'Nake asilan’ya Isilaeli myaka mĩongo ĩlĩ na ĩtatũ, na akw’a, na athikwa ku Samili.'),
('kam', 'JDG', 10, 3, 'Na ĩtina wake kwookĩla Yaili, Mũngileati; nake asilan’ya Isilaeli myaka mĩongo ĩlĩ na ĩlĩ.'),
('kam', 'JDG', 10, 4, 'Na aĩ na ana mĩongo ĩtatũ ala makuawa nĩ ndena sya mang’oi mĩongo ĩtatũ, na maĩ na ndũa mĩongo ĩtatũ ila syĩtawa Avothi‐yaili kũvika ũmũnthĩ, ila syĩ nthĩ ya Ngileati.'),
('kam', 'JDG', 10, 5, 'Na Yaili akw’a, na athikwa ku Kamoni.'),
('kam', 'JDG', 10, 6, 'Na ana ma Isilaeli meeka ũla Yeova wonaa wĩ ũthũku ĩngĩ, na mathũkũma Mbaalimu, na Asetalothi, na ngai sya Silia, na ngai sya Sitoni, na ngai sya Moavi, na ngai sya ana ma Amimoni, na ngai sya Avilisiti; na matia Yeova, na matyaamũthũkũma.'),
('kam', 'JDG', 10, 7, 'Na ũthatu wa Yeova wamakanĩa Isilaeli, na amathoosya mokonĩ ma Avilisiti, na mokonĩ ma ana ma Amimoni.'),
('kam', 'JDG', 10, 8, 'Na mwaka ũsu mamanyamaasya na kũmathĩnasya ana ma Isilaeli: o na myaka ĩkũmi na nyanya nĩmathĩnasya ana onthe ma Isilaeli ala maĩ mũingo wa Yolotani nthĩ ya Aamoli, ĩla yĩ Ngileati.'),
('kam', 'JDG', 10, 9, 'Na ana ma Amimoni mainga Yolotani makokite na Yuta o nake, na Mbenyamini, na nyũmba ya Evalaimu; kwondũ wa ũu Isilaeli maĩ athĩn’ye mũno.'),
('kam', 'JDG', 10, 10, 'Na ana ma Isilaeli mamwĩkaĩla Yeova, makyasya, Nĩtũkũvĩtanĩsye, nũndũ nĩtũtiĩte Ngai waitũ, o na kwithũkũma Mbaalimu.'),
('kam', 'JDG', 10, 11, 'Na Yeova amea ana ma Isilaeli, Ndyaamũtangĩĩa kuma kwa Amisili, na kuma kwa Aamoli, na kuma kwa ana ma Amimoni, na kuma kwa Avilisiti?'),
('kam', 'JDG', 10, 12, 'Asitoni namo, na Aamaleki na Amaoni, nĩmamũthĩnasya; nenyu mweengaĩla, nakwa namũtangĩĩa kuma mokonĩ moo.'),
('kam', 'JDG', 10, 13, 'Ĩndĩ nĩmwandiie, na mwathũkũma ngai ingĩ: kwondũ wa ũu ndimũtangĩĩa ĩngĩ.'),
('kam', 'JDG', 10, 14, 'Endai mũkekaĩle ngai ila mwanyuvie; nimũtangĩĩe ĩnvinda ya thĩna wenyu.'),
('kam', 'JDG', 10, 15, 'Na ana ma Isilaeli meea Yeova, Nĩtũvĩtanĩtye: ĩka naitũ o ũndũ wĩona wĩ ũseo; ĩndĩ, nĩtũũkũvoya, ũtũvonokye o ũmũnthĩ.'),
('kam', 'JDG', 10, 16, 'Na maveta ngai ngeni kuma katĩ woo, na mathũkũma Yeova; na ngoo yake yeew’ĩthw’a woo nĩ ũnyamao wa Isilaeli.'),
('kam', 'JDG', 10, 17, 'Nĩvo ĩndĩ ana ma Amimoni moombanie, na mamba maeema Ngileati. Na ana ma Isilaeli moombana vamwe, na mamba maeema ku Misiva.'),
('kam', 'JDG', 10, 18, 'Na andũ, o anene ma Ngileati, maneenan’ya ene kwa ene, Nũũ mũndũ ũla wĩambĩlĩlya kũkita na ana ma Amimoni? Akeethĩwa e mũtongoi wa onthe ala matwĩe Ngileati.'),
('kam', 'JDG', 11, 1, 'Na ĩndĩ Yevitha Mũngileati aĩ ngũmbaũ nene, nake aĩ mwana wa ĩlwaya: na Ngileati amũsyaa Yevitha.'),
('kam', 'JDG', 11, 2, 'Na kĩveti kya Ngileati kyamũsyaĩa ana; na yĩla ana asu ma kĩveti kyu meanie, malũngya Yevitha, na mamwĩa, We ndũkethĩwa na ũtiĩwa nyũmbanĩ ya ĩthe waitũ; nũndũ we wĩ mwana wa mũndũ mũka ũngĩ.'),
('kam', 'JDG', 11, 3, 'Nĩvo ĩndĩ Yevitha wamakĩie ana‐a‐ĩthe, na atũa nthĩ ya Tovu: na andũ mate kĩĩĩ malũman’ya na Yevitha, na mangangaa vamwe nake.'),
('kam', 'JDG', 11, 4, 'Na kweethĩwa ĩvinda yathela, ana ma Amimoni mavithũkĩa Isilaeli.'),
('kam', 'JDG', 11, 5, 'Na kweethĩwa, o yĩla ana asu ma Amimoni mavithũkĩaa Isilaeli, atumĩa ma Ngileati mathi kũmũlatya Yevitha kuma nthĩ ya Tovu;'),
('kam', 'JDG', 11, 6, 'na mamwĩa Yevitha, Ũka ũtw’ĩke mũnene waitũ, nĩ kana tũkite na ana ma Amimoni.'),
('kam', 'JDG', 11, 7, 'Na Yevitha amea atumĩa ma Ngileati, Inyw’ĩ mũtyamenie, na mwandũngya nyũmbanĩ ya nau? Na mwĩmbũkĩĩa yu kĩ yĩla mwĩ thĩnanĩ?'),
('kam', 'JDG', 11, 8, 'Na ala atumĩa ma Ngileati mamwĩa Yevitha, Kwondũ wa ũu ithyĩ yu nĩtũkwĩthyũũĩe ĩngĩ, nĩ kana ũthi naitũ, na kũkita na ana ma Amimoni; naku ũkeethĩwa mũtongoi waitũ ĩũlũ wa onthe ala matwĩe Ngileati.'),
('kam', 'JDG', 11, 9, 'Na Yevitha amea ala atumĩa ma Ngileati, Ethĩwa nĩmũũndũnga kwitũ ĩngĩ kũkita na ana ma Amimoni, na Yeova aimanengane kwakwa, ngeethĩwa mũtongoi wenyu?'),
('kam', 'JDG', 11, 10, 'Na atumĩa ma Ngileati mamwĩa Yevitha, Yeova akeethĩwa ngũsĩ katĩ waitũ; o kwĩanana na ndeto yaku now’o tũkeeka.'),
('kam', 'JDG', 11, 11, 'Na ĩndĩ Yevitha aendan’ya na atumĩa ma Ngileati, na andũ mamũtw’a mũtongoi na mũnene woo: na Yevitha aneenea ndeto syake syonthe mbee wa Yeova kũu Misiva.'),
('kam', 'JDG', 11, 12, 'Na Yevitha atũma atũmwa kwa mũsumbĩ wa ana ma Amimoni, akĩkũlya, Wĩ na ũndũ mwaũ nakwa, nĩ kana wũke kwakwa wũkite na nthĩ yakwa?'),
('kam', 'JDG', 11, 13, 'Na mũsumbĩ wa ana ma Amimoni asũngĩa ala atũmwa ma Yevitha, Nĩkwĩthĩwa Isilaeli nĩwosie nthĩ yakwa, yĩla wambatie kuma Misili, kuma Alinoni o kũvika Yavoki, na kũvika Yolotani: kwondũ wa ũu tũnga yu nthĩ isu na mũuo.'),
('kam', 'JDG', 11, 14, 'Na Yevitha atũma atũmwa ĩngĩ kwa mũsumbĩ wa ana ma Amimoni:'),
('kam', 'JDG', 11, 15, 'na amwĩa, Yevitha asya atĩĩ: Isilaeli ndaaosa nthĩ ya Moavi, kana nthĩ ya ana ma Amimoni;'),
('kam', 'JDG', 11, 16, 'ĩndĩ yĩla wambatie kuma Misili, na Isilaeli aendela weũnĩ kũvika Ũkanga Mũtune, na avika Katesi;'),
('kam', 'JDG', 11, 17, 'nĩvo ĩndĩ Isilaeli watũmie atũmwa kwa mũsumbĩ wa Etomu, akĩmwĩa, Nĩngũkwĩsũva, eka nĩvĩtĩle nthĩ yaku; ĩndĩ mũsumbĩ wa Etomu ndaaĩthukĩĩsya. Na o ta ũu atũmana kwa mũsumbĩ wa Moavi; nake ndaaĩtĩkĩla: na Isilaeli ekalanga Katesi.'),
('kam', 'JDG', 11, 18, 'Na ĩndĩ maendela weũnĩ, na mathyũlũlũka nthĩ ya Etomu, na nthĩ ya Moavi, na mavĩtĩla ngalĩ ya wumĩlonĩ wa syũa ya nthĩ ya Moavi, na mamba maeema mũingo ũla ũngĩ wa Alinoni: ĩndĩ matyaakĩla mũvaka wa Moavi, nũndũ Alinoni waĩ mũvaka wa Moavi.'),
('kam', 'JDG', 11, 19, 'Na Isilaeli atũma atũmwa kwa Sioni mũsumbĩ wa Aamoli, mũsumbĩ wa Esivoni; na Isilaeli amwĩa, Nĩtũũkwĩsũva, eka tũvĩtĩle nthĩ yaku tũvike kwakwa.'),
('kam', 'JDG', 11, 20, 'Ĩndĩ Sioni ndaaĩtĩkĩla Isilaeli akĩle mũvaka wake; ĩndĩ Sioni oomban’ya andũ make onthe, na mamba maeema ku Yaasa, na mokita na Isilaeli.'),
('kam', 'JDG', 11, 21, 'Na Yeova, Ngai wa Isilaeli, anengane Sioni na andũ make onthe kw’okonĩ kwa Isilaeli, namo mamakũna: kwondũ wa ũu Isilaeli mamesya nthĩ yonthe ya Aamoli, ala matwĩe nthĩ ĩsu.'),
('kam', 'JDG', 11, 22, 'Na moosa mũvaka w’onthe wa Aamoli, kuma Alinoni kũvika Yavoki, na kuma weũnĩ kũvika Yolotani, watw’ka woo.'),
('kam', 'JDG', 11, 23, 'Na yu ĩndĩ Yeova, Ngai wa Isilaeli, nĩwalũngilye Aamoli mbee wa andũ make Isilaeli, naku wĩmosa methĩwe maku?'),
('kam', 'JDG', 11, 24, 'Kĩla ngai yaku Kemosi yĩkũnenga kĩthĩwe kyaku we ndwĩosa? O ta ũu o ala Yeova Ngai waitũ ũlũngĩtye mbee waitũ, asu tũkamosa methĩwe maitũ.'),
('kam', 'JDG', 11, 25, 'Na yu wĩ mũseango kwĩ Mbalaki mwana wa Nzivoli, mũsumbĩ wa Moavi? Aatata kũkĩlan’ya vinya na Isilaeli, kana aokita namo?'),
('kam', 'JDG', 11, 26, 'Yĩla Isilaeli matwĩe Esivoni na tũtũla twayo, na Aloeli na tũtũla twayo, na ndũa syonthe ila syĩ ũtee wa Alinoni, myaka maana atatũ; nĩkĩ mũtyaaitũnga ĩvindanĩ yĩu?'),
('kam', 'JDG', 11, 27, 'Nyie ĩndĩ ndikũvĩtanĩsye, ĩndĩ we nũũmbĩka naĩ ũkyũkita nakwa: Yeova, ũla Mũsili, nĩethĩwe mũsili ũmũnthĩ katĩ wa ana ma Isilaeli na ana ma Amimoni.'),
('kam', 'JDG', 11, 28, 'Ĩndĩ mũsumbĩ wa ana ma Amimoni ndaaĩthukĩĩsya ndeto sya Yevitha ila wamũtwaĩe.'),
('kam', 'JDG', 11, 29, 'Nĩvo ĩndĩ Veva wa Yeova wookie ĩũlũ wa Yevitha, na avĩtĩla Ngileati na Manase, na avĩtĩla Misiva ya Ngileati, na kuma Misiva ya Ngileati avĩta avika kwa ana ma Amimoni.'),
('kam', 'JDG', 11, 30, 'Na Yevitha eevĩta wĩvĩto kwa Yeova, na amwĩa, Ethĩwa ũkamanengane ana ma Amimoni w’o kw’okonĩ kwakwa,'),
('kam', 'JDG', 11, 31, 'kũkeethĩwa o kĩla kĩumaala kuma mĩomonĩ ya nyũmba yakwa kĩnthaũe, yĩla nĩsyoka na mũuo kuma kwa ana ma Amimoni, kĩkeethĩwa kĩ kya Yeova, na ngakĩthemba kĩthĩwe nthembo ya kũvĩvw’a.'),
('kam', 'JDG', 11, 32, 'Na ĩndĩ Yevitha ainga kwa ana ma Amimoni akokite namo; na Yeova amanengane kw’okonĩ kwake.'),
('kam', 'JDG', 11, 33, 'Na amakũna kuma Aloeli kũvika Minithi, o ndũa mĩongo ĩlĩ, na kũvika Avelikelamimu, na ũai mũnene mũno. Kwondũ wa ũu ana ma Amimoni makĩlw’a vinya nĩ ana ma Isilaeli.'),
('kam', 'JDG', 11, 34, 'Na Yevitha ooka Misiva mũsyĩ kwake; na, sisya, mwĩĩtu wake aumaala amũthaũe e na tũthembe na akĩsũnga: nake asyaĩtwe e ũmwe; ate o we ndaĩ na mwana kana mwĩĩtu.'),
('kam', 'JDG', 11, 35, 'Na kweethĩwa, yĩla wamwonie, atembũanga ngũa syake, na asya, Ĩiaa, mwĩĩtu wakwa! Nĩwantheesya mũno, na wĩ ũmwe wa ala manthĩnasya; nũndũ nĩnamwathamĩsye Yeova kanyw’a wakwa, na nditonya kũalyũka.'),
('kam', 'JDG', 11, 36, 'Nake amwĩa, Nau, nĩwamwathamĩsye Yeova kanyw’a waku; mbĩka kwĩanana na ũndũ ũnaumie kanyw’anĩ waku, nũndũ Yeova nũnakũĩvanĩsye kwa amaitha maku, o ana ma Amimoni.'),
('kam', 'JDG', 11, 37, 'Na amwĩa ĩthe, Nĩkwe ũũ: ndeka vandũ va myei ĩlĩ, nĩ kana nĩthi na kwanganga iĩmanĩ, na ngĩĩĩa wĩĩtu wakwa, nyie na atindan’ya makwa.'),
('kam', 'JDG', 11, 38, 'Na amwĩa, Thi. Na amũeka athi vandũ va myei ĩlĩ: na athi, we na atindan’ya make, na aĩĩa wĩĩtu wake iĩmanĩ.'),
('kam', 'JDG', 11, 39, 'Na kweethĩwa myei ĩlĩ yathela, asyoka kwa ĩthe, ũla wamwĩkie kwĩanana na wĩvĩto wake ũla wevĩtĩte: na ndaamanya mũndũ mũũme. Na kyatw’ika kĩthĩo nthĩnĩ wa Isilaeli,'),
('kam', 'JDG', 11, 40, 'atĩ eĩtu ma Isilaeli makĩendaa o kĩla mwaka kũmũlilikana mwĩĩtu wa Yevitha ũla Mũngileati mĩthenya ĩna kila mwaka.'),
('kam', 'JDG', 12, 1, 'Na andũ ma Evalaimu moombanaa vamwe, na mavĩta melekele ngalĩ ya ĩũlũ; na mamũkũlya Yevitha, Ũnainganĩsye nĩkĩ ũkokite na ana ma Amimoni, na ndũneetwĩta tũendan’ye naku? Nĩtũũkũvĩvĩsya nyũmbanĩ yaku na mwaki.'),
('kam', 'JDG', 12, 2, 'Na Yevitha amea, Nyie na andũ makwa twaĩ na ĩteta ĩnene na ana ma Amimoni; na yĩla namwĩtie, mũtyaandangĩĩa kuma mokonĩ moo.'),
('kam', 'JDG', 12, 3, 'Na yĩla noonie mũtekũndangĩĩa, nĩnaiie thayũ wakwa kw’okonĩ kwakwa, na nainganĩsya nũkite na ana ma Amimoni, na Yeova amanengane kw’okonĩ kwakwa; nũndũ wa kĩ ĩndĩ mwambata kwakwa ũmũnthĩ mũkite nakwa?'),
('kam', 'JDG', 12, 4, 'Nĩvo ĩndĩ Yevitha wombanisye andũ onthe ma Ngileati, na okita na Evalaimu; na andũ ma Ngileati makũna Evalaimu, nũndũ nĩmaisye, Inyw’ĩ Angileati, mwĩ akĩi ma Evalaimu, katĩ wa Evalaimu, na katĩ wa Manase.'),
('kam', 'JDG', 12, 5, 'Na Angileati makwata masyũko ma Yolotani masiĩĩe Aevelaimu. Na kweethĩwa, yĩla ũmwe wa akĩi ma Evalaimu waasya, Ndekai nĩinge, andũ ma Ngileati mamũkũlasya, Wĩ Mũevalaimu? Ethĩwa asya, Aiee;'),
('kam', 'JDG', 12, 6, 'nĩvo ĩndĩ mamwĩaa, Asya Syivolethi ĩndĩ, nake aĩasya Sivolethi; nũndũ ndaatonya kũmĩta nesa: na ĩndĩ maimũkwata, na kũmũaĩa masyũkonĩ ma Yolotani. Na ĩvinda yĩu kwavalũkw’a ma Evalaimu andũ ngili mĩongo ĩna na ilĩ.'),
('kam', 'JDG', 12, 7, 'Na Yevitha asilan’ya Isilaeli myaka thanthatũ. Na ĩndĩ Yevitha Mũngileati akw’a, na athikwa ndũani ĩmwe ya ku Ngileati.'),
('kam', 'JDG', 12, 8, 'Na ĩtina wake Ivisani wa Mbethi‐leemu atw’ĩka mũsilan’ya wa Isilaeli.'),
('kam', 'JDG', 12, 9, 'Na aĩ na ana mĩongo ĩtatũ; nake anengane eĩtu make mĩongo ĩtatũ kũngĩ, na atwaĩa ana make eĩtu mĩongo ĩtatũ kuma kũngĩ. Na asilan’ya Isilaeli myaka mũonza.'),
('kam', 'JDG', 12, 10, 'Na Ivisani akw’a, na athikwa Mbethi‐leemu.'),
('kam', 'JDG', 12, 11, 'Na ĩtina wake Eloni Mũnzevuluni atw’ĩka mũsilan’ya wa Isilaeli; na asilan’ya Isilaeli myaka ĩkũmi.'),
('kam', 'JDG', 12, 12, 'Na Eloni Mũnzevuluni akw’a, na athikwa Aiyaloni nthĩ ya Nzevuluni.'),
('kam', 'JDG', 12, 13, 'Na ĩtina wake Avitoni mwana wa Ileli Mũvilathoni atw’ĩka mũsilan’ya wa Isilaeli.'),
('kam', 'JDG', 12, 14, 'Na aĩ na ana mĩongo ĩna, na ana ma ana make mĩongo ĩtatũ, ala makuawa nĩ ndena mĩongo mũonza sya mang’oi: na asilan’ya Isilaeli myaka nyanya.'),
('kam', 'JDG', 12, 15, 'Na Avitoni mwana wa Ileli Mũvilathoni akw’a, na athikwa Vilathoni nthĩ ya Evalaimu, nthĩ yĩ iĩma ya Aamaleki.'),
('kam', 'JDG', 13, 1, 'Na ana ma Isilaeli meeka ũla Yeova wonaa wĩ ũthũku ĩngĩ; na Yeova amanengane mokonĩ ma Avilisiti myaka mĩongo ĩna.'),
('kam', 'JDG', 13, 2, 'Na kwaĩ mũndũ ũmwe wa ku Nzola, wa mũvĩa wa Andani, ũla wetawa syĩtwa yake Manoa; na mũka wake aĩ ngũngũ, na ndasyaaa.'),
('kam', 'JDG', 13, 3, 'Na mũlaĩka wa Yeova amumĩlĩla ũ mũndũ mũka, na amwĩa, Sisya yu, wĩ ngũngũ, na ndũsyaaa; ĩndĩ ũkaitava, na ũkĩsyaa mwana.'),
('kam', 'JDG', 13, 4, 'Kwondũ wa ũu ĩndĩ ĩsũvĩe, nĩngũkwĩsũva, na ndũkaanyw’e mbinyu o na kĩla kĩtoonasya, na ndũkaaye kĩndũ kĩvuku o na kĩva;'),
('kam', 'JDG', 13, 5, 'nũndũ, sisya, ũkaitava, na ũkĩsyaa mwana; na wenzi ndũkaavike mũtwe wake; nũndũ kana kau kakeethĩwa Mũnasili kwa Ngai kuma ke ĩvunĩ: nake akambĩlĩlya kũtangĩĩa Isilaeli kuma mokonĩ ma Avilisiti.'),
('kam', 'JDG', 13, 6, 'Na ĩndĩ ũ mũndũ mũka ooka na atavya mũũme, akĩmwĩa, Mũndũ wa Ngai ooka vala nĩĩĩ, na ũthyũ wake wĩĩilyĩ ta ũthyũ wa mũlaĩka wa Ngai, wa kũtĩsya mũno; na ndinamũkũlya kũla wauma, o nake ndanandavya syĩtwa yake:'),
('kam', 'JDG', 13, 7, 'ĩndĩ ambĩa, Sisya, ũkaitava, na ũkasyaa mwana; na yu ĩndĩ ndũkaanyw’e mbinyu o na kĩla kĩtoonasya, na ndũkaaye kĩndũ kĩvuku o na kĩva; nũndũ kana kakeethĩwa Mũnasili kwa Ngai kuma ke ĩvunĩ kũvika mũthenya wa kĩkw’ũ kyake.'),
('kam', 'JDG', 13, 8, 'Nĩvo ĩndĩ Manoa wamũvoyie Yeova, na amwĩa, Ame Yeova, nĩngũũvoya, eka mũndũ wa Ngai ũla ũnatũmĩte oke ĩngĩ kwitũ, na aitũmanyĩsya ũndũ twĩĩkana na kana kala kesyawa.'),
('kam', 'JDG', 13, 9, 'Na Ngai eethukĩĩsya wasya wa Manoa; na ũla mũlaĩka wa Ngai amũkĩa ũla mũndũ mũka ĩngĩ ailyĩ mũũndanĩ: ĩndĩ Manoa mũũme wake ndaĩ nake.'),
('kam', 'JDG', 13, 10, 'Na ũ mũndũ mũka eekalaata, na asemba, na atavya mũũme, na amwĩa, Sisya, ũla mũndũ nĩwanumĩlĩla, o ũla ũnambũkĩe mũthenya ũla ũngĩ.'),
('kam', 'JDG', 13, 11, 'Na Manoa ookĩla, na amũatĩĩa mũka, na avika vala ve ũla mũndũ, na amũkũlya, Nue ũnaneenie na mũndũ mũka ũũ? Nake asũngĩa, Ninyie.'),
('kam', 'JDG', 13, 12, 'Na Manoa asya, Ndeto syaku yu nĩsyĩthĩwe: mwĩkalĩle wa kana ũkeethĩwa ũilyĩ ata, na tũkeekana nako ata?'),
('kam', 'JDG', 13, 13, 'Na mũlaĩka wa Yeova amwĩa Manoa, Maũndũ onthe ala nĩnatavisye mũndũ mũka, nĩesũvĩe.'),
('kam', 'JDG', 13, 14, 'Ndakaaye kĩndũ o na kĩva kyumĩte mũsavivũnĩ, o na ndakaanyw’e mbinyu kana kĩla kĩtoonasya, o na ndakaaye kĩndũ kĩvuku o na kĩva; onthe ala nĩnamwĩaĩe nasũvĩe.'),
('kam', 'JDG', 13, 15, 'Na Manoa eea ũla mũlaĩka wa Yeova, Nĩngũkwĩsũva, eka tũkwĩkalangye, tũkũaĩe katena ka mbũi.'),
('kam', 'JDG', 13, 16, 'Na mũlaĩka wa Yeova eea Manoa, O na mwambĩkalangya, ndiya lĩu waku; na ethĩwa nũkũmban’ya nthembo ya ũvĩvw’a, no mũvaka ũthembee Yeova. Nũndũ Manoa ndeesĩ kana nĩ mũlaĩka wa Yeova.'),
('kam', 'JDG', 13, 17, 'Na Manoa akũlya mũlaĩka wa Yeova, Wĩtawa ata, nĩ kana, ndeto syaku syeanĩa, tũtonye kũkũtaĩa?'),
('kam', 'JDG', 13, 18, 'Na mũlaĩka wa Yeova amwĩa, Wĩngũlya syĩtwa yakwa nĩkĩ, nayo nĩ ya ũseng’ya?'),
('kam', 'JDG', 13, 19, 'Na ĩndĩ Manoa oosanĩsya katena ka mbũi na nthembo ya mũtu, na amũthembea Yeova ĩvianĩ ĩũlũ: na mũlaĩka eeka wa ũseng’ya; na Manoa na mũka masyaĩĩsya.'),
('kam', 'JDG', 13, 20, 'Nũndũ kweethĩiwe, yĩla ũlĩlĩnzĩ wa mwaki wambataa ĩtunĩ kuma kĩthembeonĩ, mũlaĩka wa Yeova nĩwambatie ũlĩlĩnzĩnĩ wa kĩthembeo: na Manoa na mũka masyaĩĩsya; na mavalũka nthĩ na mothyũ moo.'),
('kam', 'JDG', 13, 21, 'Ĩndĩ ũla mũlaĩka wa Yeova ndanaumĩlĩla Manoa kana mũka ĩngĩ. Nĩvo ĩndĩ Manoa wamanyie kana eĩ mũlaĩka wa Yeova.'),
('kam', 'JDG', 13, 22, 'Na Manoa eea mũka, Nĩtũũkw’a, vate ndĩi, nũndũ nĩtwamwona Ngai.'),
('kam', 'JDG', 13, 23, 'Ĩndĩ mũka amwĩa, Kethĩwa Yeova nũkwendaa kũtũaa, ndeĩ osa nthembo ya kũvĩvw’a na nthembo ya mũtu mokonĩ maitũ, o na ndeĩ atwon’ya maũndũ asu onthe, o na ndeĩ atavan’ya maũndũ ta asu ĩvinda yĩĩ.'),
('kam', 'JDG', 13, 24, 'Na ũ mũndũ mũka asyaa mwana, na amwĩta syĩtwa yake Samusoni: na kana keana, na Yeova akaathima.'),
('kam', 'JDG', 13, 25, 'Na Veva wa Yeova ambĩlĩlya kũmwĩkĩthya maũndũ ku Maane‐ndani, katĩ wa Nzola na Esitaoli.'),
('kam', 'JDG', 14, 1, 'Na Samusoni atheea Timina, na oona mũndũ mũka ku Timina wa eĩtu ma Avilisiti.'),
('kam', 'JDG', 14, 2, 'Na ambata, na atavya ĩthe na nyinyia, na amea, Nĩnonete mũndũ mũka ku Timina wa eĩtu ma Avilisiti: yu ĩndĩ ndwaĩai we ethĩwe kĩveti kyakwa.'),
('kam', 'JDG', 14, 3, 'Nĩvo ĩndĩ ĩthe na nyinyia mamũkũlilye, Kũti mũndũ mũka nongi katĩ wa eĩtu ma ana‐a‐au, kana andũnĩ makwa onthe, ũndũ ũkũthi kwa Avilisiti ala mate aĩke kũtwaa kĩveti? Na Samusoni amwĩa ĩthe, Ndwaĩa ũsu; nũndũ nũkũmbendeesya mũno.'),
('kam', 'JDG', 14, 4, 'Ĩndĩ ĩthe na nyinyia matyaamanya kana ũndũ ũsu waĩ wa Yeova; nũndũ nĩwamanthaa ũndũ kwa Avilisiti. Na ĩvinda yĩu Avilisiti nĩmasumbĩkĩte Isilaeli.'),
('kam', 'JDG', 14, 5, 'Na ĩndĩ Samusoni atheea Timina, e na ĩthe na nyinyia, na mavika mĩũndanĩ ya mĩsavivũ ya Timina: na, sisya, mũnyambũ wa mũika wamũtundumĩa.'),
('kam', 'JDG', 14, 6, 'Na Veva wa Yeova ooka ĩũlũ wake na vinya, na awatũan’ya o tondũ waĩ atũan’ya katena ka mbũi; na ndaĩ na kĩndũ kw’okonĩ kwake: ĩndĩ ndaatavya ĩthe kana nyinyia ũndũ weka.'),
('kam', 'JDG', 14, 7, 'Na atheea, na aneenan’ya na ũla mũndũ mũka; nake amwendeesya Samusoni mũno.'),
('kam', 'JDG', 14, 8, 'Na itinanga asyoka amũtwae; na aathũka asisye kĩla kimba kya mũnyambũ: na, sisya, vaĩ kĩthuĩ kya nzũkĩ nthĩnĩ wa kimba kya ũla mũnyambũ, na ũkĩ wa nzũkĩ.'),
('kam', 'JDG', 14, 9, 'Na atwa na moko make, na athi, akĩya o aendete; na avika vala ve ĩthe na nyinyia, na amanenga, na maya; ĩndĩ ndaamatavya kana aumya ũkĩ ũsu wa nzũkĩ kimbanĩ kya mũnyambũ.'),
('kam', 'JDG', 14, 10, 'Na ĩthe atheea kwa ũ mũndũ mũka: na Samusoni avoka mboka e kw’o; nũndũ nĩw’o anake meekaa.'),
('kam', 'JDG', 14, 11, 'Na kweethĩwa, yĩla mamwonie, mamũetee amũtindya mĩongo ĩtatũ methĩwe nake.'),
('kam', 'JDG', 14, 12, 'Na Samusoni amea, Ekai yu, nĩmũkwatye ndaĩ: ethĩwa nĩmũtonya kũmĩndavya katĩ wa mĩthenya ĩsu mũonza ya mboka, na mũkĩmĩmanya, nĩvo nĩmũnenga ngũa mĩongo ĩtatũ sya katane na ngũa ingĩ mĩongo ĩtatũ sya ũkũan’ya;'),
('kam', 'JDG', 14, 13, 'ĩndĩ ethĩwa mũtitonya kũndavya yo, nĩvo mwĩnenga ngũa mĩongo ĩtatũ sya katane na ngũa ingĩ mĩongo ĩtatũ sya ũkũan’ya. Na mamwĩa, Kwatan’ya ndaĩ yaku, nĩ kana tũmĩw’e.'),
('kam', 'JDG', 14, 14, 'Na amea, Kuma kwa ũla ũĩsaa kwaumie kya ũya, Na kuma kwa ũla wĩ vinya kwaumie mũyo. Na matyaatonya kũmĩtavan’ya ĩ ndaĩ katĩ wa mĩthenya ĩsu ĩtatũ.'),
('kam', 'JDG', 14, 15, 'Na kweethĩwa mũthenya wa mũonza, meea mũka wa Samusoni, Sengasenga mũemeu, nĩ kana atũtavye ĩla ndaĩ, tũtikese ũkũvĩvya na mwaki we na nyũmba ya au: kau mũinatwĩtaa mũtũvute? Ũu ti w’o?'),
('kam', 'JDG', 14, 16, 'Na mũka wa Samusoni aĩa e mbee wake, na amwĩa, Noũmenete, na ndũmbendete: nũkwatĩtye ana ma andũ makwa ndaĩ na ndũneemĩndavya. Na amwĩa, Sisya, ndineemĩtavya nau kana mwaitũ, na nĩkũtavya we?'),
('kam', 'JDG', 14, 17, 'Na aĩa e mbee wake mĩthenya mũonza, ĩla yaĩ ya mboka yoo: na kweethĩwa mũthenya wa mũonza amũtavya, nũndũ amũthing’ĩĩsye mũno; nake amatavya ana ma andũ make ĩ ndaĩ.'),
('kam', 'JDG', 14, 18, 'Na andũ ma ĩ ndũa mũthenya ũsu wa mũonza syũa yĩtanathũa mamũkũlya, Nĩ kyaũ kĩ mũyo kwĩ ũkĩ wa nzũkĩ? Na nĩ kyaũ kĩ vinya kwĩ mũnyambũ? Nake amea, Kethĩwa mũinenza na moi yakwa, Mũiĩthĩwa mũmanyie ndaĩ yakwa.'),
('kam', 'JDG', 14, 19, 'Na Veva wa Yeova ooka na vinya ĩũlũ wake, nake atheea Asikeloni, na akũna andũ mĩongo ĩtatũ ma vo, na oosa mũtavo woo, na amanenga ala mamũtavisye ĩla ndaĩ ngũa sya ũkũan’ya. Na ũthatu wake wakana, na ambata mũsyĩ kwa ĩthe.'),
('kam', 'JDG', 14, 20, 'Ĩndĩ mũka wa Samusoni anenganwe kwa mũtindan’ya wake, ũla watw’ĩte mũnyanyae.'),
('kam', 'JDG', 15, 1, 'Na kweethĩwa ĩtinanga, ĩvinda ya ngetha ya nganũ, Samusoni athi kũsisya mũka e na katena ka mbũi; na asya, Ngalika kwa kĩveti kyakwa kasũmbanĩ nthĩnĩ. Ĩndĩ mũthoni ndaaĩtĩkĩla alike.'),
('kam', 'JDG', 15, 2, 'Na mũthoni asya, Nĩ w’o, nasũanĩie nĩwamũmenie vyũ; kwondũ wa ũu nĩnamũnengie mũtindan’ya waku: mũinae ti mwanake kwĩ we? Nĩngũkwĩsũva, mũtwae vandũ vake.'),
('kam', 'JDG', 15, 3, 'Na Samusoni amea, Ĩvinda yĩĩ ngeethĩwa nde na ĩvĩtyo ngalĩ ĩ ya Avilisiti, nameka naĩ.'),
('kam', 'JDG', 15, 4, 'Na Samusoni athi na akwata mbĩwa maana atatũ, na oosa isinga, na eelekanĩlya kĩsithe kĩĩ na kĩĩ, na oovelela kĩsinga katĩ wa kĩla isithe ilĩ.'),
('kam', 'JDG', 15, 5, 'Na yĩla wakwatisye isinga, ailekya syathi syalika lĩunĩ ũtũĩtye wa Avilisiti, na avĩvya syove o na lĩu ũtũĩtye, o na mĩũnda ya mĩthata.'),
('kam', 'JDG', 15, 6, 'Nĩvo ĩndĩ Avilisiti makũlanilye, Ũla wĩkie ũu nũũ? Na masũngĩana, Samusoni, mũthoni wa ũla Mũtimina, nĩkwĩthĩwa nĩwosete kĩveti kyake, na akakĩnenga mũtindan’ya wake. Na Avilisiti mambata, na mavĩvya ũ mũndũ mũka na ĩthe na mwaki.'),
('kam', 'JDG', 15, 7, 'Na Samusoni amea, Ethĩwa mwĩkaa ũu, vate ndĩi ngeeĩvanĩsya kwenyu, na ĩtina wa ũu ngĩeka.'),
('kam', 'JDG', 15, 8, 'Na amavĩlĩa maũũ na mawaswa na ũai mũnene: na atheea na atũa mũvatĩnĩ wa ĩvĩa ya Etamu.'),
('kam', 'JDG', 15, 9, 'Na ĩndĩ Avilisiti mambata, na mamba maeema kwa Yuta, na meenyasya ku Lei.'),
('kam', 'JDG', 15, 10, 'Na andũ ma Yuta mamakũlya, Mwambatĩte kũkita naitũ nĩkĩ? Na masũngĩa, Nĩtwambatĩte tũmwove Samusoni, tũmwĩke o tondũ ũtwĩkĩte.'),
('kam', 'JDG', 15, 11, 'Nĩvo ĩndĩ andũ ngili itatũ ma Yuta matheeie mũvatĩnĩ wa ĩvia ya Etamu, na mamwĩa Samusoni, Ndwĩsĩ kana Avilisiti nĩmo matũsumbĩkĩte? Ĩndĩ ũndũ ũũ ũtwĩkĩte nĩ mwaũ? Nake amea, O tondũ mambĩkie, now’o nĩmekĩte.'),
('kam', 'JDG', 15, 12, 'Na mamwĩa, Twatheea tũkwove, nĩ kana tũkũnengane mokonĩ ma Avilisiti. Na Samusoni amea, Mbĩavĩei, kana mũtinthũũmũkĩa inyw’ĩ ene.'),
('kam', 'JDG', 15, 13, 'Na maneena nake, makĩmwĩa, Aiee; ĩndĩ nĩtũũkwova ũlũme, na tũkĩkũnengane mokonĩ moo: ĩndĩ, nĩ w’o ki, tũtikũaa. Na mamwova na makanda elĩ meũ, na mamwambatya kuma yĩla ĩvianĩ.'),
('kam', 'JDG', 15, 14, 'Na avika Lei, Avilisiti mausya ngemi makĩkomana nake: na Veva wa Yeova ooka ĩũlũ wake na vinya, na makanda ala maĩ mokonĩ make matw’ĩka o ta ndii sya katane syavĩvw’a na mwaki, na makanda mavalũka kuma mokonĩ make.'),
('kam', 'JDG', 15, 15, 'Na oona ũkambuu wa ĩng’oi ũte ũkũũ, na atambũũkya kw’oko kwake, na awosa, na akũna andũ ngili naw’o.'),
('kam', 'JDG', 15, 16, 'Na Samusoni asya, Na ũkambuu wa ĩng’oi, mbumbu ĩũlũ wa mbumbu, Na ũkambuu wa ĩng’oi nĩnakũna andũ ngili.'),
('kam', 'JDG', 15, 17, 'Na kweethĩwa, amina kũneena, ekya ũkambuu kuma kw’okonĩ kwake; na vandũ vau veetwa Lamathĩ‐leĩ.'),
('kam', 'JDG', 15, 18, 'Na akwatwa nĩ waũni mũnene, na amwĩkaĩla Yeova, na asya, Nũnenganĩte ũvonokyo ũũ mũnene na kw’oko kwa mũthũkũmi waku; na yu nĩngũkw’a nũndũ wa waũni, na ngĩvalũka mokonĩ ma ala mate aĩke.'),
('kam', 'JDG', 15, 19, 'Ĩndĩ Ngai aatũa kasongolimanĩ kala ke ku Lei, na vauma kĩw’ũ; na yĩla wanywie, veva wake wamũsyokea ĩngĩ, na avuũka: kwondũ wa ũu syĩtwa yavo veetwa Eni‐akole, ĩla yĩ Lei, kũvika ũmũnthĩ.'),
('kam', 'JDG', 15, 20, 'Na asilan’ya Isilaeli myaka mĩongo ĩlĩ mĩthenyanĩ ya Avilisiti.'),
('kam', 'JDG', 16, 1, 'Na Samusoni athi Ngasa, na oona ĩlwaya vo, na alika kwayo.'),
('kam', 'JDG', 16, 2, 'Na Angasa matavw’a, kũkyaw’a, Samusoni nĩ mũku kũũ. Na mamũthyũlũlũka mamũvinganĩsya nthĩnĩ, na mamwoveesya mbingĩlonĩ ya ndũa ũtukũ w’onthe, na nĩmakilĩtye ũtukũ w’onthe, makyasya, Tweteele kũvika masũilũnĩ, na ĩndĩ tũkĩmũaa.'),
('kam', 'JDG', 16, 3, 'Na Samusoni akoma mũvaka ũtukũ katĩ, na ookĩla ũtukũ katĩ, na akwata mĩomo ya mbingĩlo ya ĩ ndũa, na ila itũi ilĩ, na aikũanĩsya vamwe na kĩvingi, na asilĩĩla ituonĩ syake, na aikua asyambatya mũtumbĩnĩ wa kĩĩma kĩla kyelekele Eviloni.'),
('kam', 'JDG', 16, 4, 'Na kweethĩwa ĩtina, amwenda mũndũ mũka wĩ mwandanĩ wa Soleki, ũla wetawa syĩtwa yake Ndelila,'),
('kam', 'JDG', 16, 5, 'Na eaĩi ma Avilisiti mambata kwake, na mamwĩa, Mũsengasenge, ũmanye vala vinya wake mũnene ũĩ, na ũndũ tũtonya kũmũkĩlya vinya, nĩ kana tũmwove tũmũthĩn’ye: na tũkakũnenga kĩla ũmwe waitũ ilungu sya vetha ngili ĩmwe na ĩana yĩmwe.'),
('kam', 'JDG', 16, 6, 'Na Ndelila eea Samusoni, Nĩngũkwĩsũva, ndavya vala vinya waku mũnene ũĩ, na ũtonya kwovwa na kyaũ ũkathĩnw’e.'),
('kam', 'JDG', 16, 7, 'Na Samusoni amwĩa, Ethĩwa nĩmeũmbova na ndii mũonza nzĩũ ila ite mbovu, nĩvo nĩaa vinya, na ngeethĩwa o ta mũndũ ũngĩ.'),
('kam', 'JDG', 16, 8, 'Nĩvo ĩndĩ eaĩi ma Avilisiti mamũetee ndii mũonza nziũ ite mbovu, na amwova nasyo.'),
('kam', 'JDG', 16, 9, 'Na ĩndĩ aĩ na oveesya mekalĩte kasũmbanĩ ka nthĩnĩ. Na amwĩa, Avilisiti nĩmeũkũkwata, Samusoni. Nake atw’a ndii isu, o ta ũlii wa katane ũndũ ũtw’ĩ kaa wakiita mwaki. Kwondũ wa ũu vinya wake ndwaamanyĩka.'),
('kam', 'JDG', 16, 10, 'Na Ndelila eea Samusoni, Sisya, nũnambũĩa ngũĩ, na ũnandavya movũngũ: na nĩngũkwĩsũva, ndavya yu ũtonya kwovwa na kyaũ.'),
('kam', 'JDG', 16, 11, 'Nake amwĩa, Ethĩwa nomambova na makanda meũ ki ala mataaova kĩndũ, nĩvo nĩaa vinya na ngeethĩwa o ta mũndũ ũngĩ.'),
('kam', 'JDG', 16, 12, 'Na ĩndĩ Ndelila oosa makanda meũ, na amwova namo, na amwĩa, Avilisiti nĩmeũkũkwata, Samusoni. Na ala oveesya mekalĩte kasũmbanĩ ka nthĩnĩ. Nake amatw’a mauma mokonĩ make o ta kaũlii.'),
('kam', 'JDG', 16, 13, 'Na Ndelila amwĩa Samusoni, Kũvika o na yu ũmbũĩaa ngũĩ, na kũndavya movũngũ: ndavya ũtonya kwovwa na kyaũ. Nake amwĩa, Ethĩwa ũkatumanĩsya ithũkũ ii mũonza sya nzw’ĩĩ sya mũtwe wakwa na ndii sya kĩtumi.'),
('kam', 'JDG', 16, 14, 'Na ailũman’ya mũno na kyambo, na amwĩa, Avilisiti nĩmeũkũkwata, Samusoni. Na aamũka kuma toonĩ, na akũa kyambo kya mũamba, na ndii sya kĩtumi.'),
('kam', 'JDG', 16, 15, 'Nake amwĩa, Ũtonya ũneena ata, Nyie nĩngwendete, yĩla ngoo yaku ĩte vamwe nakwa? Nũmbũĩĩte ngũĩ mavinda asu atatũ, na ndũneendavya vala vinya waku mũnene ũĩ.'),
('kam', 'JDG', 16, 16, 'Na kweethĩwa, yĩla wamũthingĩĩsye na ndeto syake kĩla mũthenya na kũmũthetheesya, ngoo yake yanyamaa yesa ũkw’a.'),
('kam', 'JDG', 16, 17, 'Nake amũtavya ũndũ wĩ ngoonĩ yake w’onthe, na amwĩa, Wenzĩ ndwaavika mũtwe kwakwa; nũndũ nekalile nĩ Mũnasili kwa Ngai kuma nĩ ĩvunĩ ya mwaitũ: ethĩwa ngeenzwa, nĩvo vinya wakwa wĩuma kwakwa, nakwa ngatw’ĩka mwonzu, na ngeethĩwa o ta mũndũ ũngĩ.'),
('kam', 'JDG', 16, 18, 'Na yĩla Ndelila wonie kana nĩwamũtavya w’onthe ũla wĩ ngoonĩ yake, atũmana ete eaĩi ma Avilisiti, akĩmea, Ambatai o ĩvinda yĩĩ yĩmwe, nũndũ nĩwandavya w’onthe ũla wĩ ngoonĩ yake. Nĩvo ĩndĩ eaĩi ma Avilisiti mambatie vala ũĩ, na maete ila mbesa na moko moo.'),
('kam', 'JDG', 16, 19, 'Nake amũkomya too maũũnĩ make; na eeta mũndũ, nake asyenza ila ithũkũ mũonza sya mũtwe wake; na ambĩlĩlya kũmũthĩn’ya, na vinya wake wamuma.'),
('kam', 'JDG', 16, 20, 'Na asya, Avilisiti nĩmeũkũkwata, Samusoni. Nake aamũka kuma toonĩ, na asya, Nyie nĩngumaala o ta mavinda ala angĩ, na kwĩvuunza. Ĩndĩ ndaamanya kana Yeova nĩwamũtia.'),
('kam', 'JDG', 16, 21, 'Na Avilisiti mamũkwata, na mamũvũthũanga metho; na mamũtheesya Ngasa, na mamwĩkĩa mbĩngũ sya ũthuku; nake athiĩaa nyũmbanĩ ya kolokolo.'),
('kam', 'JDG', 16, 22, 'Indĩ nzw’ĩĩ sya mũtwe wake syambĩlĩlya kwĩana ĩngĩ ĩtina wa eenzwa.'),
('kam', 'JDG', 16, 23, 'Na ala eaĩi ma Avilisiti moombana vamwe nĩ kana mamũthembee Ndakoni ngai yoo nthembo nene, na kũtana; nũndũ maasya, Ngai yaitũ nĩnenganĩte Samusoni mũmaitha waitũ mokonĩ maitũ.'),
('kam', 'JDG', 16, 24, 'Na yĩla andũ mamwonie, mataĩa ngai yoo; nũndũ maisye, Ngai yaitũ nĩnenganĩte mũmaitha waitũ mokonĩ maitũ na mwanangi wa nthĩ yaitũ, ũla woaie aingĩ maitũ.'),
('kam', 'JDG', 16, 25, 'Na kweethĩwa, yĩla ngoo syoo syatana, masya, Mwĩtei Samusoni, nĩ kana atũthaũkĩe. Nao mamwĩta Samusoni kuma nyũmbanĩ ya kolokolo; nake amathaũkĩa. Na mamũũngamya katĩ wa ituĩ:'),
('kam', 'JDG', 16, 26, 'na Samusoni eea kĩla kĩmwana kyamũkwete kw’oko, Ndekya nĩkwatange ituĩ ila iũngamĩtye nyũmba ĩno, nĩ kana nĩsyaĩĩe.'),
('kam', 'JDG', 16, 27, 'Na ĩndĩ nyũmba ĩsu yausũĩte aũme na aka; na eaĩi onthe ma Avilisiti maĩ vo; na kwaĩ aũme na aka ta ngili itatũ kĩalanĩ ĩũlũ, ala meloelaa Samusoni aithaũka.'),
('kam', 'JDG', 16, 28, 'Nake Samusoni amwĩkaĩla Yeova, na asya, Ame Mwĩaĩi Yeova, ndilikana, nĩngũũvoya, na mbĩkĩa vinya, nĩngũũvoya, o ĩvinda yĩĩ yoka, ame Ngai, nĩ kana nĩyĩĩvanĩsye o ĩmwe kwa Avilisiti nũndũ wa metho makwa elĩ.'),
('kam', 'JDG', 16, 29, 'Na Samusoni akwata ila ituĩ ilĩ sya katĩ ila syaũngamĩtye nyũmba ĩsu, na ailuuta, kĩmwe na kw’oko kwake kwa aũme, na kĩla kĩngĩ na kw’oko kwake kwa aka.'),
('kam', 'JDG', 16, 30, 'Na Samusoni asya, Eka nĩkw’e vamwe na Avilisiti. Nake eenyitĩĩa na vinya wake w’onthe; na nyũmba yavalũkĩla ala eaĩi, na andũ onthe ala maĩ nthĩnĩ wayo. Kwondũ wa ũu akw’ũ ala woaie aikw’a nĩ aingĩ kwĩ ala woaĩte e thayũ.'),
('kam', 'JDG', 16, 31, 'Nĩvo ĩndĩ ana‐a‐inyia make na nyũmba yonthe ya ĩthe matheea, na mamwosa, na mamwambatya, na mamũthika katĩ wa Nzola na Esitaoli, vandũnĩ va mbũa va andũ ma Manoa, ĩthe wake. Nake asilanilye Isilaeli myaka mĩongo ĩlĩ.'),
('kam', 'JDG', 17, 1, 'Na kwaĩ mũndũ wa nthĩ yĩ iĩma ya Evalaimu, ũla wetawa syĩtwa yake Mika.'),
('kam', 'JDG', 17, 2, 'Na amwĩa inyia wake, Ilungu sya vetha ngili ĩmwe na ĩana yĩmwe ila wooyĩwe, ĩla waumanĩe ũndũ wasyo, o na ĩngĩ waneena matũnĩ makwa, sisya, ũla vetha wĩ nakwa; nĩnawosie. Na inyia wake asya, Mwana wakwa naathimwe nĩ Yeova.'),
('kam', 'JDG', 17, 3, 'Na amũtũngĩa inyia wake ila ilungu sya vetha ngili ĩmwe na ĩana yĩmwe; na inyia wake asya, Nĩ w’o, vetha ũũ nĩngũvathĩa Yeova wĩthĩwe mũtheu wume kw’okonĩ kwakwa kwondũ wa mwana wakwa, ũndũ wa kũseũvya mũvw’anano mwasũvye na mũvw’anano ũseũvĩtw’e na syĩndũ itwekethetw’e: na yu kwondũ wa ũu nĩngũũtũngĩa.'),
('kam', 'JDG', 17, 4, 'Na yĩla wamũtũngĩie inyia wake ũla vetha, inyia wake oosa ilungu sya vetha maana elĩ, na amũnenga mũtwii, ũla waiseũvisye mũvw’anano mwasũvye na mũvw’anano ũseũvĩtw’e na syĩndũ matwekethetye: na waĩ nyũmbanĩ ya Mika.'),
('kam', 'JDG', 17, 5, 'Na mũndũ ũsu Mika aĩ na nyũmba ya i ngai, na aseũvya evoti, o na telavimu, na avatha ũmwe wa ana make, ũla watw’ĩkie mũthembi wake.'),
('kam', 'JDG', 17, 6, 'Mĩthenya ĩsu kũtyaĩ mũsumbĩ nthĩnĩ wa Isilaeli: kĩla mũndũ eekaa o ũndũ wonaa wĩ ũseo.'),
('kam', 'JDG', 17, 7, 'Na kwaĩ mwanake wa Mbethi‐leemu‐yuta, wa mũvĩa wa Yuta, ũla waĩ Mũlivai; nake ekala ũeni kw’o.'),
('kam', 'JDG', 17, 8, 'Na mũndũ ũsu auma ĩ ndũanĩ, o Mbethi‐leemu‐yuta, akekale ũeni vala ũtonya kwona vandũ; nake avika nthĩ yĩ iĩma ya Evalaimu nyũmbanĩ ya Mika, e kyalonĩ kyake.'),
('kam', 'JDG', 17, 9, 'Na Mika amũkũlya, Wauma va? Nake amũsũngĩa, Nyie nĩ Mũlivai wa Mbethi‐leemu‐yuta, na nĩendete ngekale ũeni vala ndonya kwona vandũ.'),
('kam', 'JDG', 17, 10, 'Na Mika amwĩa, Tũa nakwa, naku ũitw’ĩka nau na mũthembi kwakwa, na ngaũnenga ilungu ĩkũmi sya vetha kĩla mwaka, na ngũa sya kwĩkĩa, na lĩu waku. Na ĩndĩ ũla Mũlivai alika nthĩnĩ.'),
('kam', 'JDG', 17, 11, 'Na ũla Mũlivai eanĩwa nĩ kũtũa na mũndũ ũsu; na ũla mwanake atw’ĩka kwake ta ũmwe wa ana make.'),
('kam', 'JDG', 17, 12, 'Na Mika avatha ũla Mũlivai, na mwanake ũsu atw’ĩka mũthembi wake, na eethĩawa nyũmbanĩ ya Mika.'),
('kam', 'JDG', 17, 13, 'Na ĩndĩ Mika asya, Yu nĩnĩsĩ kana Yeova akambĩka nesa, nũndũ nĩ na Mũlivai ethĩwe mũthembi wakwa.'),
('kam', 'JDG', 18, 1, 'Mĩthenya ĩsu kũtyaĩ mũsumbĩ nthĩnĩ wa Isilaeli: na mĩthenya ĩsu mbaĩ ya Andani meemanthĩa ũtiĩwa matũae; nũndũ kũvika mũthenya ũsu ũtiĩwa woo ndwaĩ ũnamba ũmavalũkĩla mbaĩnĩ sya Isilaeli.'),
('kam', 'JDG', 18, 2, 'Na ana ma Ndani matũma andũ atano ma mũvĩa woo kuma ũtalonĩ woo w’onthe, andũ ngũmbaũ, kuma ku Nzola, na kuma Esitaoli, nĩ kana mathĩane nthĩ ĩsu, na kũmĩkuũa; na mamea, Endai, mũkakuũe nthĩ ĩsu. Nao mavika nthĩ yĩ ĩĩma ya Evalaimu, nyũmbanĩ ya Mika, na makoma vo.'),
('kam', 'JDG', 18, 3, 'Me vakuvĩ na nyũmba ya Mika, mamanya wasya wa ũla mwanake Mũlivai; nao meelelũkĩla vo, na mamũkũlya, Nũũ wakũetie kũũ? Na wĩĩka ata vaa? Na wĩ na kyaũ vaa?'),
('kam', 'JDG', 18, 4, 'Nake amea, Ũũ na ũũ nĩw’o Mika ũmbĩkĩte, na nũnandĩkĩte, nakwa nĩndw’ĩkĩte mũthembi wake.'),
('kam', 'JDG', 18, 5, 'Na mamwĩa, Nĩtũũkwĩsũva, mũkũlye Ngai, nĩ kana tũmanye kana nzĩa ĩla tũkwete kana ĩkaathimĩka.'),
('kam', 'JDG', 18, 6, 'Na mũthembi amea, Endai na mũuo: nzĩa ĩla mũkwete Yeova nũmyene.'),
('kam', 'JDG', 18, 7, 'Nĩvo ĩndĩ ala andũ atano maendie, na mavika Laisa, na moona andũ ala maĩ nthĩnĩ wayo, ũndũ matũaa meyelele, o tondũ Asitoni matwĩe, mauĩtye na meyelele; nũndũ kũtyaĩ mũndũ nthĩnĩ wa nthĩ ĩsu waĩ na ũtonyi ũla waĩ amasonokya ũndũnĩ o na wĩva, namo maĩ kũasa na Asitoni, na matyaĩ na ũndũ na mũndũ o na wĩva.'),
('kam', 'JDG', 18, 8, 'Na mavika kwa ana‐a‐inyia moo ku Nzola na Esitaoli: na ana‐a‐inyia mamakũlya, Mwĩasya ata?'),
('kam', 'JDG', 18, 9, 'Na mamea, Ũkĩlai, twambatei tũkokite nao; nũndũ nĩtũmyonete nthĩ ĩsu, na lĩlĩĩ, nĩ nzeo mũno: nenyu nĩmũkilĩtye? Mũtikethĩwe atulu wa kũthi na kũlika nĩ kana mũmĩmesye.'),
('kam', 'JDG', 18, 10, 'Yĩla mwĩthi, mũkavika kwa andũ meyelele, na nthĩ ĩsu nĩ nene; nũndũ Ngai nũmĩnenganĩte mokonĩ menyũ, vandũ vataaa kĩndũ o na kĩva kĩ kũũ nthĩ.'),
('kam', 'JDG', 18, 11, 'Na kw’o kwauma andũ maana thanthatũ mekĩe mĩio ya kaũ ma mũvĩa wa Andani, kuma ku Nzola, na kuma Esitaoli.'),
('kam', 'JDG', 18, 12, 'Na mambata, na mamba maeema ku Kiliathi‐yealimu, nthĩnĩ wa Yuta: kwondũ wa ũu maveta vandũ vau Maane‐ndani kũvika ũmũnthĩ; sisya, yĩ ĩtina wa Kiliathi‐yealimu.'),
('kam', 'JDG', 18, 13, 'Na mavĩta kuma ku mavika nthĩ yĩ iĩma ya Evalaimu, na mavika nyũmbanĩ ya Mika.'),
('kam', 'JDG', 18, 14, 'Nĩvo ĩndĩ ala andũ atano ala maendie kũthiana nthĩ ya Laisa masũngĩie na mamea ana‐a‐ĩthe moo, Nĩmwĩsĩ kana nyũmbanĩ ii ve evoti, na telavimu, na mũvw’anano mwasũvye, na mũvw’anano ũseũvĩtw’e na syĩndũ matwekethetye? Yu ĩndĩ sũanĩai ũndũ mũkwĩka.'),
('kam', 'JDG', 18, 15, 'Nao meelelũkĩĩla vo, na mavika nyũmbanĩ ya ũla mwanake Mũlivai, o nyũmbanĩ ya Mika, na mamũkũlya ũvoo wake.'),
('kam', 'JDG', 18, 16, 'Na ala andũ maana thanthatũ mekĩe mĩio ya kaũ, ala maĩ ma ana ma Ndani, maũngama ũlikĩlonĩ mbingĩlonĩ.'),
('kam', 'JDG', 18, 17, 'Na ala andũ atano ala maendie kũthiana ĩla nthĩ mambata, na malika vo nthĩnĩ, na moosa ũla mũvw’anano mwasũvye, na yĩla evoti, na ila telavimu, na ũla mũvw’anano ũseũvĩtw’e na syĩndũ matwekethetye: na ũla mũthembi aũngama ũlikĩlonĩ mbingĩlonĩ vamwe na ala andũ maana thanthatũ mekĩe mĩio ya kaũ.'),
('kam', 'JDG', 18, 18, 'Na yĩla asu malikile nyũmbanĩ ya Mika, na kũete mũvw’anano mwasũvye, na yĩla evoti, na ila telavimu, na ũla mũvw’anano ũseũvĩtw’e na syĩndũ matwekethetye, ũla mũthembi amakũlya, Mwĩĩka ata inyw’ĩ?'),
('kam', 'JDG', 18, 19, 'Nao mamwĩa, Vindya, kunĩka kanyw’a waku na kw’oko, na ũithi naitũ, wĩthĩwe ĩthe na mũthembi kwitũ: ũu nĩw’o kavaa kwaku kwĩthĩwa mũthembi wa nyũmba ya mũndũ ũmwe, kana kwĩthĩwa mũthembi wa mbaĩ na mũvĩa nthĩnĩ wa Isilaeli?'),
('kam', 'JDG', 18, 20, 'Na ngoo ya mũthembi yatana, nake oosa yĩla evoti, na ĩla telavimu, na ũla mũvw’anano mwasũvye, na alika andũnĩ asu.'),
('kam', 'JDG', 18, 21, 'Na ĩndĩ meethyũũa na maenda, na matongosya syana ila nini o na indo na mĩio.'),
('kam', 'JDG', 18, 22, 'Na yĩla maĩ kũasa na nyũmba ya Mika, andũ ala matwĩe nyũmbanĩ ila syaĩ vakuvĩ na nyũmba ya Mika moombana vamwe, na maatĩĩa ana ma Ndani mamakwata.'),
('kam', 'JDG', 18, 23, 'Na mamanĩĩsya ana ma Ndani. Nao mathyũũa mothyũ moo, na mamũkũlya Mika, Wĩ na ũndũ mwaũ, ũndũ wooka na nguthu yĩana ũu?'),
('kam', 'JDG', 18, 24, 'Nake asya, Inyw’ĩ nĩmwosie ngai ila naseũvisye, na mũthembi, nenyu nĩmũendete, nakwa nĩ na kĩngĩ kyaũ? Na nĩkĩ ĩndĩ mũũngũlya, Wĩ na ũndũ mwaũ?'),
('kam', 'JDG', 18, 25, 'Na andũ ma Ndani mamwĩa, Wasya ũsu waku ndũkew’ĩke katĩ waitũ, ala me na ũthatu maikese ũkũthũũmũkĩa, naku ũkyasya thayũ waku, vamwe na mathayũ ma andũ ma nyũmba yaku.'),
('kam', 'JDG', 18, 26, 'Na ana ma Ndani meendea: na yĩla Mika wonie kana me na vinya kwĩ we, eethyũũa na asyoka nyũmbanĩ yake.'),
('kam', 'JDG', 18, 27, 'Namo matwaa kĩla Mika waseũvĩtye, na ũla mũthembi waĩ nake, na mavika Laisa, kwa andũ mauĩtye na meyelele, na mamakũna kwa kũmatemanga na ũvyũ; na mavĩvya ĩ ndũa na mwaki'),
('kam', 'JDG', 18, 28, 'Na kũtyaĩ mũvonokya, nũndũ yaĩ kũasa na Sitoni, nao matyaĩ na ũndũ na mũndũ o na wĩva; nayo yaĩ mwandanĩ ũla wĩ vakuvĩ na Mbethi‐leovu. Na maaka ndũa, na mamĩtũa.'),
('kam', 'JDG', 18, 29, 'Na meeta syĩtwa ya ndũa ĩsu Ndani, kũatĩĩa syĩtwa ya ĩthe woo Nadni, ũla wasyaiwe nĩ Isilaeli: ĩndĩ syĩtwa ya ĩla ndũa mbee yeetawa Laisa.'),
('kam', 'JDG', 18, 30, 'Na ana ma Ndani meeũngamĩsya ũla mũvw’anano mwasũvye; na Yonathani, mwana wa Ngelisoni, mwana wa Mose, we na ana make maĩ athembi kwa mbaĩ ya Ndani kũvika mũthenya wa kũtavwa kwa nthĩ ĩsu.'),
('kam', 'JDG', 18, 31, 'Na ĩndĩ meeũngamĩsya mũvw’anano mwasũvye wa Mika ũla waseũvĩtye, ĩvinda yonthe yĩla nyũmba ya Ngai yaĩ Silo.'),
('kam', 'JDG', 19, 1, 'Na kweethĩwa mĩthenya ĩsu, yĩla kũtaĩ mũsumbĩ nthĩnĩ wa Isilaeli, kwaĩ Mũlivai ũmwe wekalaa ũeni ngalĩ ĩla ĩngĩ ya nthĩ yĩ iĩma ya Evalaimu, ũla wetwaĩe mũndũ mũka ngombo wa Mbethi‐leemu‐yuta.'),
('kam', 'JDG', 19, 2, 'Na mũndũ mũka ũsu ngombo amũthĩn’ya kwa kwĩka ũmalwaya, na amũtia athi nyũmbanĩ kwa ĩthe ku Mbethi‐leemu‐yuta, na ekalile kw’o vandũ va myei ĩna.'),
('kam', 'JDG', 19, 3, 'Na mũũme ookĩla, na amũatĩĩa, e na mũthũkũmi wake, na mang’oi elĩ, akaneene nake nesa, amũtũnge ĩngĩ: na ũla mũndũ mũka amũthokya nyũmbanĩ ya ĩthe; na yĩla ĩthe wa mwĩĩtu ũsu wamwonie, atana ũndũ wa kũmwona.'),
('kam', 'JDG', 19, 4, 'Na mũthoni, ĩthe wa mwĩĩtu ũsu, amwĩkalya; nake ekala nake mĩthenya ĩtatũ: na ĩndĩ maya na manyw’a, na kũkoma kw’o.'),
('kam', 'JDG', 19, 5, 'Na kweethĩwa mũthenya wa kana, mookĩla kĩoko tene, nake ookĩla nĩ kana aende: na ĩthe wa ũla mwĩĩtu amwĩa mũthoni, Ĩkĩa ngoo yaku vinya na kalungu ka kĩmũtũ, na ĩtina mũkĩyĩendea.'),
('kam', 'JDG', 19, 6, 'Na ĩndĩ mekala nthĩ, na maya na manyw’a, elĩ vamwe: na ĩthe wa ũla mwĩĩtu atavya mũthoni, Nĩngũkwĩsũva, endeew’a nĩ kwĩkala ũtukũ w’onthe, na ngoo yaku nĩtane.'),
('kam', 'JDG', 19, 7, 'Na ũla mũndũ ookĩla nĩ kana aende; ĩndĩ mũthoni amũthetheesya mũno, nake akoma ĩngĩ kw’o.'),
('kam', 'JDG', 19, 8, 'Na ookĩla kĩoko tene mũthenya wa katano nĩ kana athi; na ĩthe wa ũla mwĩĩtu amwĩa, Ĩkĩa ngoo yaku vinya nĩngũkwĩsũva, na ĩkalanga syũa yeeeke; na maya, me elĩ.'),
('kam', 'JDG', 19, 9, 'Na yĩla ũla mũndũ wokĩlile nĩ kana aende, we, na ũla mũndũ mũka wake ngombo, na mũthũkũmi wake, mũthoni, ĩthe wa ũla mwĩĩtu, amwĩa, Sisya, yu mũthenya nĩ mũendu, nĩngũkwĩsũva, ĩkala ũtukũ w’onthe: sisya, syũa yĩkilĩlye ũthũa, koma kũũ, nĩ kana ngoo yaku ĩtane; na ũnĩ tene wĩkwata nzĩa, nĩ kana wĩnũke.'),
('kam', 'JDG', 19, 10, 'Ĩndĩ ũla mũndũ ndaaĩtĩkĩla kwĩkala ũtukũ ũsu, ĩndĩ ookĩla na athi, na avika kwelekela Yevusi (nayo nĩ Yelusaleme): nake aĩ na mang’oi elĩ me matandĩke; o na ũla mũndũ mũka wake ngombo aĩ nake.'),
('kam', 'JDG', 19, 11, 'Yĩla maĩ vakuvĩ na Yevusi, mũthenya waĩ mũendu mũno; na ũla mũthũkũmi amwĩa vwana wake, Nĩngũkwĩsũva, ũka, twelelũkĩĩle ndũa ĩno ya Ayevusi, tũkome vo.'),
('kam', 'JDG', 19, 12, 'Na vwana wake amwĩa, Tũtiathũka ndũa ya mũndũ wa nthĩ ĩngĩ, ĩte ya ana ma Isilaeli; ĩndĩ nĩtũũvĩta tũvike Ngivea.'),
('kam', 'JDG', 19, 13, 'Na amwĩa mũthũkũmi wake, Ũka tũthengeee vandũ vamwe va kũndũ kũũ; na nĩtũũkoma Ngivea, kana Lama.'),
('kam', 'JDG', 19, 14, 'Na ĩndĩ mavĩta na meeendea; na syũa yamathũĩĩa me vakuvĩ na Ngivea, ĩla ya Mbenyamini.'),
('kam', 'JDG', 19, 15, 'Nao meelelũkĩĩla vo, malike makome Ngivea: nake alika nthĩnĩ, na ekala nthĩ nzĩanĩ nene ya ĩ ndũa; nũndũ kũtyaĩ mũndũ o na ũmwe waamathokya nyũmbanĩ yake makome.'),
('kam', 'JDG', 19, 16, 'Na, sisya, kwooka mũtumĩa mũkũũ aumĩte wĩanĩ wake mũũndanĩ wĩoo: na mũndũ ũsu aĩ wa nthĩ yĩ iĩma ya Evalaimũ, nake ekalaa ũeni ku Ngivea; ĩndĩ andũ ma vandũ vau maĩ Ambenyamini.'),
('kam', 'JDG', 19, 17, 'Nake ookĩlya metho make, na oona mũndũ ũendete kyalo nzĩanĩ nene ya ndũa; na ĩndĩ ũla mũtumĩa amũkũlya, Wĩthi na kũ? Na wauma va?'),
('kam', 'JDG', 19, 18, 'Nake amwĩa, Nĩtũvĩtĩte tumĩte Mbethi‐leemũyuta tũthi ngalĩ ĩla ĩngĩ ya nthĩ yĩ iĩma ya Evalaimu; nĩ kw’o nĩnaumie, na naendie Mbethi‐leemu‐yuta; na yu nĩendete nyũmbanĩ ya Yeova; na vati mũndũ ũnanthokya nyũmbanĩ yake.'),
('kam', 'JDG', 19, 19, 'Ĩndĩ ve ũa na lĩu wa mang’oi maitũ; na ve lĩu na mbinyu nayo kwondũ wakwa, na mũthũkũmi waku mwĩĩtu, na mwanake ũla wĩ vamwe na athũkũmi maku: vati vata wa kĩndũ o na kĩmwe.'),
('kam', 'JDG', 19, 20, 'Na ũla mũtumĩa asya, Mũuo wĩthĩwe kwaku; ĩndĩ mavata maku onthe methĩwe ĩũlũ wakwa; ĩndĩ ndũkakome nzĩanĩ nene.'),
('kam', 'JDG', 19, 21, 'Na ĩndĩ amũtwaa nyũmbanĩ yake, na anenga mang’oi lĩu; na mathambya maũũ moo, maya, na manyw’a.'),
('kam', 'JDG', 19, 22, 'Na makĩtan’ya ngoo syoo, sisya, andũ ma ndũa ĩsu, andũ athe, mathyũlũlũka ĩ nyũmba, na kũkũnanga mũomo; na maneena na vwana wa nyũmba, ũla mũtumĩa maimwĩa, Mumaalye nza mũndũ ũla woka nyũmbanĩ yaku, nĩ kana tũmũmanye.'),
('kam', 'JDG', 19, 23, 'Na ũla mũndũ, vwana wa nyũmba, aumaala nza vau maĩ, na amea, Aiee, ana‐a‐ia makwa, nĩngũmwĩsũva, mũikeke ũthũku wĩana ũu; nũndũ mũndũ ũũ nũlikile nyũmbanĩ yakwa, mũikeke ũtumanu ũũ.'),
('kam', 'JDG', 19, 24, 'Sisya, vaa ve mwĩĩtu wakwa mũtheu, na mũndũ mũka wake ngombo; nĩngũmaumaalya nza oyu, na mathũkyei, na kũmeka ũndũ mũkwona wĩ ũseo: ĩndĩ mũndũ ũũ mũikamwĩke ũtumanu ta ũsu.'),
('kam', 'JDG', 19, 25, 'Ĩndĩ andũ asu matyaaĩtĩkĩla kũmwĩthukĩĩsya: na ĩndĩ mũndũ ũsu amũkwata mũndũ mũka wake ngombo, na amumaalya nza vala maĩ; nao mamũmanya, na mamũthĩn’ya ũtukũ w’onthe kũvika kĩoko: na masũilũnĩ, mamũeka athi.'),
('kam', 'JDG', 19, 26, 'Nĩvo ĩndĩ mũndũ mũka ũsu wokie kĩoko kũitheana, na avalũka mũomonĩ wa nyũmba ya ũla mũndũ vala vwana wake ũĩ, mũvaka kwakya.'),
('kam', 'JDG', 19, 27, 'Na mwĩaĩi wake ookĩla kĩoko, na avingũa mĩomo ya nyũmba, na aumaala nĩ kana eeendee; na, sisya, ũla mũndũ mũka wake ngombo avalũkĩte vau mũomonĩ wa nyũmba, na moko make me mwalyonĩ.'),
('kam', 'JDG', 19, 28, 'Na amwĩa, Ũkĩla, tũthĩ; ĩndĩ vatyaĩ ũsũngĩo; na ĩndĩ amũtũlya ĩng’oinĩ; na mũndũ ũsu akũsya, na athi kwake.'),
('kam', 'JDG', 19, 29, 'Na yĩla walikile nyũmba kwake, oosa kavyũ, na akwata ũla mũndũ mũka wake ngombo, na amũaan’ya, mutha na mutha, ilungu ĩkũmi na ilĩ, na amũtwaa mĩvakanĩ yonthe ya Isilaeli.'),
('kam', 'JDG', 19, 30, 'Na kweethĩwa, atĩ onthe ala moonie ũndũ ũsu masya, Ũndũ ta ũu ndwaaĩkĩka o na ndwaaoneka kuma mũthenya ũla ana ma Isilaeli mambatie kuma nthĩ ya Misili kũvika ũmũnthĩ; sũanĩai, na oan’yai, na neenai.'),
('kam', 'JDG', 20, 1, 'Nĩvo ĩndĩ ana onthe ma Isilaeli maumaalile, na ĩkomano yoombanĩa Yeova ku Misiva ta mũndũ ũmwe, kuma Ndani kũvika Mbeeli‐sieva, vamwe na nthĩ ya Ngileati.'),
('kam', 'JDG', 20, 2, 'Na anene ma andũ onthe, o ma mbaĩ syonthe sya Isilaeli, meeyumĩlya ũmbanonĩ wa andũ ma Ngai, andũ ngili maana ana ala maendete na maũũ ala makũaa ũvyũ.'),
('kam', 'JDG', 20, 3, '(Na ĩndĩ ana ma Mbenyamini meew’a kana ana ma Isilaeli nĩmambatie Misiva.) Na ana ma Isilaeli masya, Tũtavyei, ũthũku ũũ weekĩkie ata?'),
('kam', 'JDG', 20, 4, 'Na ũla Mũlivai, mũũme wa mũndũ mũka ũsu ũnooaiwe, asũngĩa na asya, Navikie Ngivea ĩla ya Mbenyamini, nyie na mũka wakwa ngombo, nĩ kana tũkome kw’o.'),
('kam', 'JDG', 20, 5, 'Na andũ ma Ngivea mambũkĩlĩla, na manthyũlũlũkĩla nyũmba ngalĩ syonthe ũtukũ; mendaa kũmbũaa nyie, na mũka wakwa ngombo mamũkinda, nake akw’a.'),
('kam', 'JDG', 20, 6, 'Nakwa noosa mũka wakwa ngombo na kũmũtilanga ilungu, na kũmũtwaa kw’onthe nthĩ yonthe ya ũtiĩwa wa Isilaeli; nũndũ mekĩte wathe na ũtumanu nthĩnĩ wa Isilaeli.'),
('kam', 'JDG', 20, 7, 'Sisyai, inyw’ĩ ana ma Isilaeli, inyw’onthe, tũnengei ũtao wenyu na kĩosyo kyenyu.'),
('kam', 'JDG', 20, 8, 'Na andũ onthe mookĩla ta mũndũ ũmwe, makyasya, Ithyĩ vati ũmwe katĩ waitũ wĩsyoka ĩeemanĩ yake, o na vati ũmwe katĩ waitũ wĩsyoka mũsyĩ kwake.'),
('kam', 'JDG', 20, 9, 'Ĩndĩ yu ũndũ ũla tũkwĩka Ngivea nĩ ũũ: nĩtũkwambata tũkokite nayo kwa nzĩa ya kũlimana;'),
('kam', 'JDG', 20, 10, 'na tũkoosa andũ ĩkũmi kwa kĩla ĩana mbaĩnĩ syonthe sya Isilaeli, na ĩana kwa ngili, na ngili kwa ngili ĩkũmi, nĩ kana mamalatĩlye andũ lĩu, nĩ kana, mavika Ngivea ya Mbenyamini, matonye kwĩka kwĩanana na ũtumanu w’onthe ũla meekie nthĩnĩ wa Isilaeli.'),
('kam', 'JDG', 20, 11, 'Na ĩndĩ andũ onthe ma Isilaeli moombanĩĩa ndũa ĩsu, makwatene vamwe o ta mũndũ ũmwe.'),
('kam', 'JDG', 20, 12, 'Na mbaĩ sya Isilaeli syatũma andũ maende mbaĩnĩ yonthe ya Mbenyamini, makĩkũlya, Ũthũku ũũ nĩ mwaũ wĩkĩkĩte katĩ wenyu?'),
('kam', 'JDG', 20, 13, 'Yu, ĩndĩ nenganai andũ asu athe, ala me Ngivea, nĩ kana tũmoae, na kũveta ũthũku kwa Isilaeli. Ĩndĩ a Mbenyamini matyaaĩtĩkĩla kwĩw’a wasya wa ana‐a‐ĩthe moo ana ma Isilaeli.'),
('kam', 'JDG', 20, 14, 'Na ana ma Mbenyamini moombana kuma ndũanĩ sya Ngivea, nĩ kana maume makokite na ana ma Isilaeli.'),
('kam', 'JDG', 20, 15, 'Na ana ma Mbenyamini matalilwe mũthenya ũsu kuma ĩ ndũanĩ andũ ngili mĩongo ĩlĩ na thanthatũ ala makũaa ũvyũ, eka andũ ma Ngivea, ala matalĩtwe andũ anyuve maana mũonza.'),
('kam', 'JDG', 20, 16, 'Katĩ wa andũ asu onthe kwaĩ andũ anyuve maana mũonza ma imotho; kĩla ũmwe aĩ atonya kwĩkya mavia na kĩkũtha kamwanyanĩ keanĩa ũsw’ĩĩ, na ndavĩtya.'),
('kam', 'JDG', 20, 17, 'Na andũ ma Isilaeli, eka a Mbenyamini, matalilwe andũ ngili maana ana ala makũaa ũvyũ: asu onthe maĩ andũ ma kaũ.'),
('kam', 'JDG', 20, 18, 'Na ana ma Isilaeli mookĩla, na mambata Mbethi‐eli, na makũlya Ngai ũtao; na makũlya, Naaũ ala mekwamba kwambata kwondũ witũ mokite na Mbenyamini? Na Yeova asya, Yuta nĩwe wĩamba kwambata.'),
('kam', 'JDG', 20, 19, 'Na ana ma Isilaeli mookĩla kĩoko, na mamba maeema mataũĩĩe Ngivea.'),
('kam', 'JDG', 20, 20, 'Na andũ ma Isilaeli maumaala mokite na Mbenyamini; na andũ ma Isilaeli mataũsya ita mokitĩe namo ku Ngivea.'),
('kam', 'JDG', 20, 21, 'Na ana ma Mbenyamini mauma Ngivea, na maanangĩa nthĩ ma Aisilaeli mũthenya ũsu andũ ngili mĩongo ĩlĩ na ilĩ.'),
('kam', 'JDG', 20, 22, 'Na andũ, aũme ma Isilaeli, meeyĩkĩa vinya, na mataũsya ita ĩngĩ o vala manataũĩtye mũthenya wa mbee.'),
('kam', 'JDG', 20, 23, 'Na ana ma Isilaeli mambata na maĩa mbee wa Yeova kũvika wĩoo; na mamũkũlya Yeova, makyasya, Ngathengeea ĩngĩ nũkite na ana ma Mbenyamini mwana‐a‐asa wakwa? Na Yeova amwĩa, Ambata wũkite nake.'),
('kam', 'JDG', 20, 24, 'Na ana ma Isilaeli mathengeea mokite na ana ma Mbenyamini mũthenya wa kelĩ.'),
('kam', 'JDG', 20, 25, 'Na Ambenyamini maumaala kuma Ngivea mokite namo mũthenya wa kelĩ, na ĩngĩ maanangĩa nthĩ ma ana ma Isilaeli andũ ngili ĩkũmi na nyanya; asu onthe maĩ ala makũaa ũvyũ.'),
('kam', 'JDG', 20, 26, 'Nĩvo ĩndĩ ana ma Isilaeli onthe, o andũ onthe, mambatie, na mavika Mbethi‐eli, na maĩa, na mekala nthĩ vu mbee wa Yeova, na matĩĩa kũya mũthenya ũsu kũvika wĩoo; na mamũthembea Yeova nthembo sya kũvĩvw’a na nthembo sya mũuo.'),
('kam', 'JDG', 20, 27, 'Na ana ma Isilaeli mamũkũlya Yeova (nũndũ ĩsandũkũ ya ũtianĩo ya Ngai yaĩ kw’o mĩthenya ĩsu,'),
('kam', 'JDG', 20, 28, 'na Vineasi, mwana wa Eleasali, mwana wa Aluni, nĩwaũngamaa mbee wayo mĩthenya ĩsu), makyasya, Ngaumaala o ĩngĩ kũkita na ana ma Mbenyamini, mwana‐a‐asa wakwa, kana nĩeke? Na Yeova amwĩa, Ambata; nũndũ ũnĩ ngamũnengane kw’okonĩ kwaku.'),
('kam', 'JDG', 20, 29, 'Na Isilaeli maia oveesya mathyũlũlũkĩte Ngivea.'),
('kam', 'JDG', 20, 30, 'Na ana ma Isilaeli mambata mokite na ana ma Mbenyamini mũthenya wa katatũ, na meetaũsya mokite na Ngivea, o ta mavinda ala angĩ.'),
('kam', 'JDG', 20, 31, 'Na ana ma Mbenyamini maumaala mokite na andũ asu, nao makusw’a mathi vaasa na ĩ ndũa; na mambĩlĩlya kũkũna na kũaĩa andũ, ta andũ mĩongo ĩtatũ ma Isilaeli, o ta mavinda ala angĩ, malelũnĩ, ala ũmwe wamo ũelete Mbethi‐eli, na ũla ũngĩ Ngivea, mũũndanĩ.'),
('kam', 'JDG', 20, 32, 'Na ana ma Mbenyamini masya, Nĩmeũkũnwa mavalũkw’e nthĩ nĩ ithyĩ, o ta mbee. Ĩndĩ ana ma Isilaeli masya, Nĩtũkũke, na tũkĩmakusya maume ndũanĩ kũvika malelũnĩ.'),
('kam', 'JDG', 20, 33, 'Na andũ onthe ma Isilaeli mookĩla kuma vala maĩ, na meetaũsya ku Mbaali‐tamali: na ala oveesya ma Isilaeli makuthũka kuma kũla maĩ, o kuma Maale‐ngeva.'),
('kam', 'JDG', 20, 34, 'Na kwooka andũ anyuve ngili ĩkũmi kuma kwa Isilaeli onthe mokite na Ngivea, na kaũ ũsu waĩ mwai mũno; ĩndĩ matyaamanya kana ũthũku nũmathengeee.'),
('kam', 'JDG', 20, 35, 'Na Yeova akũnĩa Mbenyamini vu mbee wa Isilaeli; na ana ma Isilaeli mũthenya ũsu maananga ma Mbenyamini andũ ngili mĩongo ĩlĩ na itano na ĩana yĩmwe: asu onthe nĩmakũaa ũvyũ.'),
('kam', 'JDG', 20, 36, 'Na ĩndĩ ana ma Mbenyamini moona kana nĩmakũnwa; nũndũ andũ ma Isilaeli nĩmathũkĩaa Mbenyamini, nĩkwĩthĩwa nĩmamaĩkĩĩaa oveesya ala mamaiĩte mokite na Ngivea.'),
('kam', 'JDG', 20, 37, 'Na ala oveesya meekalaata, na mavithũkĩa Ngivea; na ala oveesya meekusya maendeee mbee, na makũna ndũa yonthe kwa kũtemanga na ũvyũ.'),
('kam', 'JDG', 20, 38, 'Na ĩndĩ wonan’yo watw’ĩtwe katĩ wa andũ ma Isilaeli na ala oveesya waĩ atĩ mokĩlye mũumbĩ mũnene wa syũki kuma ĩ ndũanĩ.'),
('kam', 'JDG', 20, 39, 'Na andũ ma Isilaeli meethyũũĩa kaũ, na a Mbenyamini mambĩlĩlya kũkũna na kũaa andũ ma Isilaeli ta andũ mĩongo ĩtatũ; nũndũ maasya, Nĩ w’o, nĩmeũkũnwa mavalũkw’e nthĩ nĩ ithyĩ, o ta kaũnĩ wa mbee.'),
('kam', 'JDG', 20, 40, 'Ĩndĩ yĩla mũumbĩ wa kĩtuĩ kya syũki wambĩlĩlye kũkĩla kuma ndũanĩ, Ambenyamini masisya ĩtina woo; na, sisya, ndũa yonthe yausũĩte syũki yambatĩte ĩtunĩ.'),
('kam', 'JDG', 20, 41, 'Na andũ ma Isilaeli meethyũũa, na andũ ma Mbenyamini mateva; nũndũ nĩmoonie kana ũthũku nĩwamakwata.'),
('kam', 'JDG', 20, 42, 'Kwondũ wa ũu moon’ya andũ ma Isilaeli mĩongo yoo melekele nzĩa ya weũnĩ; ĩndĩ kaũ wamaatĩĩa na vinya; na ala maumĩte ndũanĩ mamanangĩa vau katĩ.'),
('kam', 'JDG', 20, 43, 'Mamathyũlũlũka Ambenyamini ngalĩ syonthe, na mamalũngya, na mamaanganĩsya vo vandũ voo va ũthũmũa, o kũvika kwelekela Ngivea ngalĩ ya wumĩlonĩ wa syũa.'),
('kam', 'JDG', 20, 44, 'Na kwavalũkw’a ma Mbenyamini andũ ngili ĩkũmi na nyanya; asu onthe maĩ andũ ngũmbaũ.'),
('kam', 'JDG', 20, 45, 'Na meethyũũa na makũka melekele weũnĩ kũvika ĩvianĩ ya Limoni: na meethĩan’ya mamo malelũnĩ andũ ngili itano, na mamaatĩĩa na vinya kũvika Ngitomu, na makũna mamo andũ ngili ilĩ.'),
('kam', 'JDG', 20, 46, 'Kwondũ wa ũu onthe ma Mbenyamini ala mavalũkile mũthenya ũsu maĩ ngili mĩongo ĩlĩ na itano ala makũaa ũvyũ; asu onthe maĩ andũ ngũmbaũ.'),
('kam', 'JDG', 20, 47, 'Ĩndĩ andũ maana thanthatũ meethyũũa na makũka melekele weũnĩ kũvika ĩvianĩ ya Limoni, na mekala ĩvianĩ ya Limoni myei ĩna.'),
('kam', 'JDG', 20, 48, 'Na andũ ma Isilaeli meethyũũĩa ana ma Mbenyamini ĩngĩ, na mamakũna kwa kũmatemanga na ũvyũ, ndũa nima, o na indo, na kyonthe kĩla moonie: vamwe na ũu ndũa syonthe ila moonie nĩmaivĩvisye na mwaki.'),
('kam', 'JDG', 21, 1, 'Na ĩndĩ andũ ma Isilaeli nĩmeeavĩĩte ku Misiva, makasya, Vati mũndũ katĩ waitũ ũkanengane mwĩĩtu wake kwa Mbenyamini.'),
('kam', 'JDG', 21, 2, 'Na andũ mavika Mbethi‐eli, na mekala kw’o mbee wa Ngai kũvika wĩoo, na mookĩlya mawasya moo, na kũĩa mũno.'),
('kam', 'JDG', 21, 3, 'Na masya, Ame Yeova, Ngai wa Isilaeli, ũndũ ũũ wĩkĩkie nĩkĩ nthĩnĩ wa Isilaeli, ũndũ vethĩiwe ũmũnthĩ mbaĩ ĩmwe ĩolekete nthĩnĩ wa Isilaeli?'),
('kam', 'JDG', 21, 4, 'Na kweethĩwa ũnĩ ũsu, andũ mookĩla tene, na maaka kĩthembeo vo, na mathemba nthembo sya kũvĩvw’a na nthembo sya mũuo.'),
('kam', 'JDG', 21, 5, 'Na ana ma Isilaeli masya, Katĩ wa mbaĩ syonthe sya Isilaeli nĩ yĩva ĩtaneambatĩa Yeova ĩkomanonĩ? Nũndũ nĩmeeavĩte kĩavo kĩnene ũndũ wa ũla ũteũmwambatĩa Yeova ku Misiva, makasya, Ũsu akooawa vate ndĩi.'),
('kam', 'JDG', 21, 6, 'Na ana ma Isilaeli meelila nũndũ wa Mbenyamini, mwana‐a‐ĩthe woo, na masya, Kwĩ mbaĩ ĩmwe ĩvetiwe kwa Isilaeli ũmũnthĩ.'),
('kam', 'JDG', 21, 7, 'Twĩĩka ata nĩ kana tũmonee ala matiele aka, nũndũ nĩtwĩavĩte kwa Yeova atĩ tũtikamanenga ma eĩtu maitũ methĩwe aka?'),
('kam', 'JDG', 21, 8, 'Na masya, Nĩ yĩva ya mbaĩ sya Isilaeli ĩtaneambatĩa Yeova ku Misiva? Na, sisya, kũtineũka o na ũmwe kuma Yavesi‐ngileati ĩkomanonĩ mwakonĩ wa maeema.'),
('kam', 'JDG', 21, 9, 'Nũndũ yĩla andũ matalawa, sisya, vo vayaĩ o na ũmwe wa ala matwĩe Yavesi‐ngileati.'),
('kam', 'JDG', 21, 10, 'Na ĩkomano yatũma kw’o andũ ngili ĩkũmi na ilĩ ala ngũmbaũ nene mbee, yameaĩa, ĩkyasya, Endai mũkũne andũ ala matwĩe Yavesi‐ngileati kwa kũmatemanga na ũvyũ, vamwe na aka na syana nini.'),
('kam', 'JDG', 21, 11, 'Na ũndũ ũla mwĩĩka nĩw’o ũũ: mũkanange vyũ kĩla mũndũ mũũme, na kĩla mũndũ mũka ũla waakoma na mũndũ mũũme.'),
('kam', 'JDG', 21, 12, 'Na katĩ wa andũ ala matwĩe Yavesi‐ngileati meethĩa eĩtu atheu maana ana ala mataamanya mũndũ mũũme ũndũ wa kũkoma nake; na mamaete mwakonĩ wa maeema ku Silo, ĩla yĩ nthĩ ya Kanaani.'),
('kam', 'JDG', 21, 13, 'Na ĩkomano yonthe yatũmana na yaneena na ana ma Mbenyamini ala maĩ ĩvianĩ ya Limoni, na matavan’ya mũuo kwoo.'),
('kam', 'JDG', 21, 14, 'Na a Mbenyamini masyoka ĩvinda yĩu; na mamanenga ala eĩtu ala mamaekie me thayũ katĩ wa aka ma Yavesi‐ngileati: na vamwe na ũu matyaameanĩa.'),
('kam', 'JDG', 21, 15, 'Na andũ meelila ũndũ wa Mbenyamini, nũndũ Yeova nĩwĩkĩĩte ĩthenya katĩ wa mbaĩ sya Isilaeli.'),
('kam', 'JDG', 21, 16, 'Nĩvo ĩndĩ atumĩa ma ĩkomano maisye, Twĩĩka ata nĩ kana tũmonee ala matiele aka, nũndũ aka ma Mbenyamini nĩ oae?'),
('kam', 'JDG', 21, 17, 'Na masũngĩana, No mũvaka vethĩwe ũtiĩwa ũndũ wa ala mathonokie ma Mbenyamini, nĩ kana mbaĩ ndĩkathele vyũ kwa Isilaeli.'),
('kam', 'JDG', 21, 18, 'Ĩndĩ ithyĩ tũtitonya kũmanenga aka kuma eĩtunĩ maitũ; nũndũ ana ma Isilaeli nĩmeeavĩte, makasya, Naumanĩwe ũla ũkanenga a Mbenyamini mũka.'),
('kam', 'JDG', 21, 19, 'Na masya, Sisyai, kwĩ mboka ya Yeova kĩla mwaka ku Silo, ĩla yĩ ngalĩ ya ĩũlũ ya Mbethi‐eli, ngalĩ ya wumĩlonĩ wa syũa ya lelũ ũla wambatĩte kuma Mbethi‐eli kũvika Sekemu, na ngalĩ ya ĩtheo ya Levona.'),
('kam', 'JDG', 21, 20, 'Na mameaĩa ana ma Mbenyamini, makĩmea, Endai mwoveesye mĩũndanĩ ya mĩsavivũ;'),
('kam', 'JDG', 21, 21, 'na, sisyai, ethĩwa eĩtu ma Silo nĩmekumaala makasũnge mbathinĩ, nĩvo ĩndĩ mwĩuma mĩũndanĩ ya mĩsavivũ, na ĩyoseei kĩla mũndũ mũka kuma eĩtunĩ ma Silo, na mũkĩthi nthĩ ya Mbenyamini.'),
('kam', 'JDG', 21, 22, 'Na kũkeethĩwa, yĩla aaĩthe kana ana‐a‐inyia moo meũka kũteta kwitũ, tũkamea, Tũnengei mo kwa mwaĩa; nũndũ tũkyũkita tũtyaatialĩlya kĩla mũndũ woo mũka, o na ti inyw’ĩ mũmanenganĩte kwoo; kethĩwa nĩ ũu, yu mwĩthĩwa mwĩ avĩtan’ya.'),
('kam', 'JDG', 21, 23, 'Na ana ma Mbenyamini meeka ũu, na meeyosea aka, kwĩanana na ũtalo woo, kuma kwa asu masũngaa, namo mamatwaa: na mathi masyoka ũtiĩwanĩ woo, na matũngĩĩa i ndũa, na maitũa.'),
('kam', 'JDG', 21, 24, 'Na ana ma Isilaeli mauma vau ĩvindanĩ yĩu, kĩla mũndũ akĩthi mbaĩnĩ yake na mũvĩanĩ wake, nao mauma vo kĩla mũndũ akĩthi ũtiĩwanĩ wake.'),
('kam', 'JDG', 21, 25, 'Mĩthenyanĩ ĩsu kũtyaĩ mũsumbĩ nthĩnĩ wa Isilaeli: kĩla mũndũ eekaa ũndũ wonaa wĩ ũseo.'),
('kam', 'RUT', 1, 1, 'Na kweethĩwa mĩthenya ĩla asili masilanasya, kwaĩ yũa nthĩ ĩsu. Na mũndũ ũmwe wa Mbethi‐leemu‐yuta athi akekale ũeni nthĩ ya Moavi, we, na mũka, na ana make elĩ.'),
('kam', 'RUT', 1, 2, 'Na syĩtwa ya mũndũ ũsu eetawa Elimeleki, na syĩtwa ya mũka eetawa Naomi, na masyĩtwa ma ana make elĩ maĩ Maloni na Kilioni, namo maĩ Aevilathi ma Mbethi‐leemu‐yuta. Namo mavika nthĩ ya Moavi, na mekala kw’o.'),
('kam', 'RUT', 1, 3, 'Na Elimeleki, mũũme wa Naomi, akw’a; na atiwa, o na ana make elĩ.'),
('kam', 'RUT', 1, 4, 'Namo matwaa aka ma ku Moavi; syĩtwa ya ũmwe eetawa Oliva, na syĩtwa ya ũla ũngĩ eetawa Luthi: namo mekala kw’o ta myaka ĩkũmi.'),
('kam', 'RUT', 1, 5, 'Namo elĩ, Maloni na Kilioni, makw’a: na mũndũ mũka ũsu akw’ĩĩwa nĩ ana make elĩ na mũũme.'),
('kam', 'RUT', 1, 6, 'Nĩvo ĩndĩ wokĩlile vamwe na aka ma ana make, asyoke kuma nthĩ ĩsu ya Moavi: nũndũ nĩwew’ĩte e ku nthĩ ya Moavi ũndũ Yeova ũmokĩe andũ make ũndũnĩ wa kũmanenga lĩu.'),
('kam', 'RUT', 1, 7, 'Nake auma vandũ vau waĩ, vamwe na aka ma ana make elĩ; namo makwata nzĩa nĩ kana masyoke nthĩ ya Yuta.'),
('kam', 'RUT', 1, 8, 'Na Naomi amea aka ma ana make elĩ, Endai, mũsyoke kĩla ũmwe nyũmba ya inyia wake: Yeova amwĩke nesa, o tondũ inyw’ĩ mwamekie ala makwie, o nakwa.'),
('kam', 'RUT', 1, 9, 'Yeova amũnenge kwona ũthũmũo, kĩla ũmwe nyũmbanĩ kwa mũũme wake. Nĩvo ĩndĩ wamamumunyie, namo mookĩlya wasya woo, na maĩa.'),
('kam', 'RUT', 1, 10, 'Na mamwĩa, Aiee, ĩndĩ ithyĩ twĩsyoka vamwe naku kwa andũ maku.'),
('kam', 'RUT', 1, 11, 'Na Naomi amea, Syokai, eĩtu makwa: mwĩendan’ya nakwa nĩkĩ? nĩ na ana angĩ ĩvunĩ yakwa, matonya kwĩthĩwa aũme menyu?'),
('kam', 'RUT', 1, 12, 'Syokai, eĩtu makwa, endai kwenyu; nũndũ nyie nĩ mũtumĩu, nditonya kwĩthĩwa na mũũme ĩngĩ. O na ethĩwa nĩngwasya, Nĩ na wĩkwatyo, o na ngethĩwa na mũũme ũtukũ ũũ wa ũmũnthĩ, o na kũsyaa tũvĩsĩ;'),
('kam', 'RUT', 1, 13, 'mwĩsa o kweteela mũvaka tweana? mwĩsa o kũmĩĩsya mũte na aũme? aiee, eĩtu makwa; nũndũ nĩngwĩw’a woo mwingĩ kwondũ wenyu, nĩkwĩthĩwa kw’oko kwa Yeova nĩkumĩte ĩũlũ wakwa.'),
('kam', 'RUT', 1, 14, 'Namo mookĩlya wasya woo, na maĩa ĩngĩ: na Oliva amumunya inyia wa mũũme; ĩndĩ Luthi alũman’ya nake.'),
('kam', 'RUT', 1, 15, 'Na amwĩa, Sisya, mũka wa mwana‐a‐inyia wa mũemeu nĩwasyoka kwa andũ make, na kwa ngai yake: syoka naku ũmũvikĩle mũka wa mwana‐a‐inyia wa mũemeu.'),
('kam', 'RUT', 1, 16, 'Na Luthi amwĩa, Eka ũnthing’ĩĩsya ngũtie, nĩthyũũe nĩeke ũkũvikĩla; nũndũ vala wĩthi, ngathi; na vala wĩĩkala, ngekala; andũ maku makeethĩwa andũ makwa, na Ngai waku Ngai wakwa;'),
('kam', 'RUT', 1, 17, 'vala wĩkw’ĩa, novo nĩkw’ĩa, na novo nĩthikwa: Yeova nambĩke ũu, o na mbee, ethĩwa ũndũ ũkandaan’ya naku ate o kĩkw’ũ.'),
('kam', 'RUT', 1, 18, 'Na yĩla wonie kana nĩweyũmbanĩtye ki kũthi nake, aeka kũneena nake.'),
('kam', 'RUT', 1, 19, 'Na ĩndĩ mathi me elĩ mũvaka mavika Mbethi‐leemu. Na kweethĩwa, mavika Mbethi‐leemu, ndũa yonthe yamaka kwondũ woo, na aka masya, Ũũ nĩ Naomi?'),
('kam', 'RUT', 1, 20, 'Nake amea, Mũikambĩte Naomi, mbĩtei Mala; nũndũ Mwene Vinya W’onthe nũmbĩkĩte maũndũ me ũũ mũno.'),
('kam', 'RUT', 1, 21, 'Nĩnaumie vaa nusũĩte, na Yeova nũndũngĩte ĩngĩ kwitũ nĩ mũthei; mwĩmbĩta Naomi nĩkĩ, nũndũ Yeova nũngũsĩĩe, na Mwene Vinya W’onthe nũnthĩnĩtye?'),
('kam', 'RUT', 1, 22, 'Na ĩndĩ Naomi asyoka, na Luthi Mũmoavi, mũka‐wa‐mwana, e vamwe nake, ũla waumie nthĩ ya Moavi; namo mavika Mbethi‐leemu wambĩlĩlyonĩ wa kũketha mbaale.'),
('kam', 'RUT', 2, 1, 'Na Naomi aĩ na mũndũ wa mbaĩ ya a mũũme wa mũvĩa wa Elimeleki, mũndũ mũthwii wĩ nguma, na syĩtwa yake eetawa Mboasi.'),
('kam', 'RUT', 2, 2, 'Na Luthi Mũmoavi amwĩa Naomi, Eka nĩthi yuyu mũũndanĩ ngekolanĩlye iia sya mbaale ĩtina wa ũla wĩmbonea ũseo. Na amwĩa, Thi, mwĩĩtu wakwa.'),
('kam', 'RUT', 2, 3, 'Na athi, na avika na akolan’ya mũũndanĩ ĩtina wa akethi: na esa kũwĩla kĩlungu kya mũũnda kĩla kyaĩ kya Mboasi, ũla waĩ wa mũvĩa wa Elimeleki.'),
('kam', 'RUT', 2, 4, 'Na, sisya, Mboasi auma Mbethi‐leemu, na amea akethi, Yeova nĩethĩwe vamwe nenyu. Namo mamũsũngĩa, Yeova nakũathime.'),
('kam', 'RUT', 2, 5, 'Nĩvo ĩndĩ Mboasi wamũkũlilye ũla mũthũkũmi wake wamwiĩte kũũngamĩa akethi, Mwĩĩtu ũũ nĩ waũ?'),
('kam', 'RUT', 2, 6, 'Na mũthũkũmi ũsu waiĩtwe kũũngamĩa akethi asũngĩa na amwĩa, Nĩ ũla mwĩĩtu Mũmoavi wokie na Naomi kuma nthĩ ya Moavi:'),
('kam', 'RUT', 2, 7, 'nake asya, Nĩngũkwĩsũva, nenga mwanya nĩkolanĩlye nũmban’ye ĩtina wa akethi katĩ wa syove. Na ĩndĩ ooka, na atindie kuma kĩoko kũvika o na yu, ate o ĩvinda ĩvũthũ wekalangile nyũmbanĩ.'),
('kam', 'RUT', 2, 8, 'Nĩvo ĩndĩ Mboasi wamwĩie Luthi, Ndũkwĩw’a, mwĩĩtu wakwa? Ndũkathi kũkolan’ya mũũndanĩ ũngĩ, o na ndũkaume vaa, ĩndĩ ĩkala vaa vakuvĩ na athũkũmi makwa eĩtu.'),
('kam', 'RUT', 2, 9, 'Metho maku nĩmasisye mũũnda o ũla meũketha, naku ũmaatĩĩe: ndimatavisye anake asu maikakũkiite? Naku weew’a waũni thi vala ve ĩkuu ũnyw’e kĩla anake matavĩte.'),
('kam', 'RUT', 2, 10, 'Nĩvo ĩndĩ wavalũkile na ũthyũ wake, na kwĩkunamya nthĩ, na amwĩa, Nũndũ wa kĩ nyie noona ũseo vala ũĩ, na wamanya nyie, nakwa nĩ mũndũ wa nthĩ ĩngĩ?'),
('kam', 'RUT', 2, 11, 'Na Mboasi amũsũngĩa, na amwĩa, Nĩnonetw’e vyũ onthe ala wamwĩkie inyia wa mũemeu kuma mũemeu akw’a; na ũndũ ũtiĩte au na mwenyu na nthĩ ĩla wasyaĩwe, na wũkĩte kwa andũ ala ũtamesĩ o na ĩndĩĩ.'),
('kam', 'RUT', 2, 12, 'Yeova nakũĩve wĩa waku, na ĩtuvi yĩanĩu wĩnengwa nĩ Yeova, Ngai wa Isilaeli, ũla wũkĩte kwĩvitha nthwaunĩ syake.'),
('kam', 'RUT', 2, 13, 'Nĩvo ĩndĩ waisye, Nĩnone ũseo vala ũĩ, mwĩaĩi wakwa; nũndũ nĩwangiakisya, na nĩwaneena nesa na mũthũkũmi waku mwĩĩtu, o na ndiilyĩ ta ũmwe wa athũkũmi maku eĩtu.'),
('kam', 'RUT', 2, 14, 'Na ĩvinda ya kũya lĩu Mboasi amwĩa Luthi, Ũka vaa, ũye lĩu, noivoka kalungu kaku ka kĩmũtũ na siki. Nake ekala nthĩ vakuvĩ na akethi; na mamũnenga lĩu wa mbaa ngetha mũkaange, na aya, na avũna, na atialya.'),
('kam', 'RUT', 2, 15, 'Na yĩla wokĩlile akolan’ye, Mboasi ameaĩa anake make, akĩmea, Mũekei akolan’ye o syovenĩ, na mũikamũsonokye.'),
('kam', 'RUT', 2, 16, 'Na ĩngĩ mũsũmũlĩlei syovenĩ, na mũekei akolan’ye, na mũikamũkan’ye.'),
('kam', 'RUT', 2, 17, 'Na ĩndĩ akolan’ya mũũndanĩ ũsu kũvika wĩoo; na avũa ila wakolanasya, na syaĩ ta eva ya mbaale.'),
('kam', 'RUT', 2, 18, 'Na eeyaĩkya, na athi ndũanĩ; na inyia wa mũũme oona ila ũkolanilye: na aumya na amũnenga lĩu ũla ũtialilye ĩtina wa avũna.'),
('kam', 'RUT', 2, 19, 'Na inyia wa mũũme amũkũlya, Wĩkolanasya va ũmũnthĩ? Na wĩtethasya wĩa va? Naathimwe ũla ũkũmanyie. Nake amũmanyĩthya inyia wa mũũme kwa ũla ũnũũtethasya wĩa kwake, na amwĩa, Mũndũ ũsu ngũtethasya wĩa kwake ũmũnthĩ syĩtwa yake nĩ Mboasi.'),
('kam', 'RUT', 2, 20, 'Na Naomi amwĩa mũka‐a‐mwana, Naathimwe nĩ Yeova, ũsu ũtaaeka kũmeka nesa ala me thayũ na ala makwie. Na Naomi amwĩa, Mũndũ ũsu nĩ waitũ, ũmwe wa mũvĩa witũ ũla wa vakuvĩ naitũ.'),
('kam', 'RUT', 2, 21, 'Na Luthi Mũmoavi asya, Ĩĩ, nũndavisye, Ĩkalaa vakuvĩ na anake makwa, mũvaka o yĩla makamina ngetha yakwa yonthe.'),
('kam', 'RUT', 2, 22, 'Na Naomi amwĩa Luthi mũka‐a‐mwana, Nĩ ũseo, mwĩĩtu wakwa, ũatĩanĩae na athũkũmi make eĩtu, o na maikakwĩthĩe mũũndanĩ ũngĩ o na wĩva.'),
('kam', 'RUT', 2, 23, 'Na ĩndĩ ekalaa vakuvĩ na athũkũmi asu eĩtu ma Mboasi, aikolan’ya kũvika mũminũkĩlyo wa ngetha ya mbaale na ngetha ya nganũ; na atũa na inyia wa mũũme.'),
('kam', 'RUT', 3, 1, 'Na Naomi inyia wa mũũme amũkũlya, Mwĩĩtu wakwa, ndikakũmanthĩe ũthũmũo, nĩ kana kwĩthĩwe ũseo kwaku?'),
('kam', 'RUT', 3, 2, 'Na ĩndĩ Mboasi ti mũndũ wa mũvĩa witũ, ũla wĩĩ na athũkũmi make eĩtu? Sisya, ũtukũ ũũ wa ũmũnthĩ eũlũkĩlya mbaale kĩvũĩonĩ.'),
('kam', 'RUT', 3, 3, 'Kwondũ wa ũu thamba, na ũyĩvaka mauta, na ũkĩkĩa ngũa syaku, na ũitheea kĩvũĩonĩ; ĩndĩ ndũkemanyĩthe ũ mũndũ, mũvaka yĩla wĩĩthĩwa anaya na kũnyw’a.'),
('kam', 'RUT', 3, 4, 'Na kũkeethĩwa, yĩla wĩkoma, nĩvo wĩsisya vandũ vala wĩkoma, na wĩlika, na ũivw’ĩkũa nyaĩĩ syake, na ũikoma; na akaũtavya ũndũ ũla wĩĩka.'),
('kam', 'RUT', 3, 5, 'Nake amwĩa, Ũu w’onthe waneena ngawĩka.'),
('kam', 'RUT', 3, 6, 'Na atheea kĩvũĩonĩ, na eeka kwĩanana na ũndũ w’onthe ũla inyia wa mũũme ũmwĩaĩie.'),
('kam', 'RUT', 3, 7, 'Na yĩla Mboasi waĩ anaya na kũnyw’a, na ngoo yake yaĩ ndanu, athi kũkoma mũthyanĩ wa kĩvumbu kya lĩu wa mbaa ngetha: nake ooka kavola, na amũvw’ĩkũa nyaĩĩ, na akoma.'),
('kam', 'RUT', 3, 8, 'Na kweethĩwa ũtukũ katĩ, mũndũ ũsu atĩsa, na eethyũũa; na, sisya, mũndũ mũka akomete nyaĩĩnĩ syake.'),
('kam', 'RUT', 3, 9, 'Na akũlya, Nue ũũ? Na amũsũngĩa, Ninyie Luthi mũthũkũmi waku mwĩĩtu: kwondũ wa ũu tambũũkya mũthya wa ngũa syaku ĩũlũ wa mũthũkũmi waku mwĩĩtu; nũndũ nue mũndu wa mũvĩa wa vakuvĩ.'),
('kam', 'RUT', 3, 10, 'Nake asya, Wĩthĩwe wĩ mũathime nĩ Yeova, mwĩĩtu wakwa: nĩwonan’ya ũseo mũminũkĩlyonĩ kwĩ yĩla ya mbee, nũndũ ndwaaatĩĩa anake, o na me ngya kana athwii.'),
('kam', 'RUT', 3, 11, 'Na yu, mwĩĩtu wakwa, ndũkakĩe; ngakwĩka w’onthe ũla ũkwasya; nĩkwĩthĩwa ndũa yonthe ya andũ makwa nĩyĩsĩ kana wĩ mũndũ mũka mwaĩlu.'),
('kam', 'RUT', 3, 12, 'Na ĩndĩ nĩ w’o kana ninyie mũndũ wa mũvĩa wa vakuvĩ; ĩndĩ ve mũndũ wa mũvĩa wa vakuvangĩ kwĩ nyie.'),
('kam', 'RUT', 3, 13, 'Ĩkala ũtukũ ũũ, na kĩoko kũkeethĩwa, kana ethĩwa akeanĩĩsya vala ũĩ ũndũ waĩle mũndũ wa mũvĩa, nĩ ũseo; nĩeke ũndũ waĩle mũndũ wa mũvĩa: ĩndĩ alea kwĩka kwaku ũndũ waĩle mũndũ wa mũvĩa, nĩvo ĩndĩ, o tondũ Yeova wĩ thayũ, nĩkwĩka ũndũ waĩle mũndũ wa mũvĩa: koma kũvika kĩoko.'),
('kam', 'RUT', 3, 14, 'Na akoma nyaĩĩnĩ syake kũvika masangya: na ookĩla mbee wa mũndũ atatonya kũmanya ũngĩ. Nũndũ aisye, Kũikamanyĩke kana mũndũ mũka nĩwokie kĩvũĩonĩ.'),
('kam', 'RUT', 3, 15, 'Na amwĩa, Ete suka ũla wĩvw’ĩkĩte, na ũiũkwata; na ookwata; nake athima ithimi thanthatũ sya mbaale, na amwaĩkya: na athi ndũanĩ.'),
('kam', 'RUT', 3, 16, 'Na yĩla wavikie kwa inyia wa mũũme, amũkũlya, Nue ũũ, mwĩĩtu wakwa? Nake amũtavya ũndũ w’onthe ũla mũndũ ũmwĩkie.'),
('kam', 'RUT', 3, 17, 'Na asya, Ithimi ii thanthatũ sya mbaale nĩwe wanenga; nũndũ ambĩie, Ndũkathi wĩ mũthei kũla kwĩ inyia wa mũemeu.'),
('kam', 'RUT', 3, 18, 'Na ĩndĩ amwĩa, Ĩkala wĩkilĩlye, mwĩĩtu wakwa, kũvika ũmanye ũndũ maũndũ meĩkĩka; nũndũ ũ mũndũ ndethũmũa, ataminĩte ũndũ ũũ mũnthĩ ũũ.'),
('kam', 'RUT', 4, 1, 'Na ĩndĩ Mboasi ambata mbingĩlonĩ, na ekala nthĩ vau: na, sisya, mũndũ ũla wa mũvĩa wa vakuvĩ ũla Mboasi ũwetie avĩtĩla vo; nake amwĩa, Ti o we, ngan’ya! athũkĩla vaa wĩkale nthĩ. Na aathũkĩla, na ekala nthĩ.'),
('kam', 'RUT', 4, 2, 'Na oosa andũ ĩkũmi katĩ wa atumĩa ma ndũa, na amea, Ĩkalai vaa nthĩ. Na mekala nthĩ.'),
('kam', 'RUT', 4, 3, 'Na amwĩa ũla mũndũ wa mũvĩa wa vakuvĩ, Naomi, ũla ũnasyokie kuma nthĩ ya Moavi, nũnũkũthoosya kĩlungu kya nthĩ, kĩla kyaĩ kya mwana‐a‐ia waitũ Elimeleki:'),
('kam', 'RUT', 4, 4, 'nakwa nĩnĩsũanĩie kũkumbũlĩla we, ngĩkwĩa, Kĩthooe aa mailyĩ vaa mene, na atumĩa ma andũ makwa mene. Ethĩwa ũkakyovosya, wĩkyovosya: ĩndĩ ethĩwa ndwĩkyovosya, ndavya ĩndĩ, nĩ kana nĩmanye; nũndũ vai ũngĩ wa ũkyovosya ate o we; nakwa nĩ ĩtina waku. Nake asya, Ngakyovosya.'),
('kam', 'RUT', 4, 5, 'Nĩvo ĩndĩ Mboasi waisye, Mũthenya ũla wĩthooa mũũnda kw’okonĩ kwa Naomi, mũvaka ũkĩthooe o ta ũu kwa Luthi ũla Mũmoavi, kĩveti kya ũla mũkw’ũ, wũkĩlye syĩtwa ya ũsu mũkw’ũ ũtiĩwanĩ wake.'),
('kam', 'RUT', 4, 6, 'Na mũndũ wa mũvĩa ũla wa vakuvĩ asya, Nditonya kũkyovosya kwondũ wakwa, ndikathũkye ũtiĩwa wakwa mwene: wĩyosee, we, kĩanda kyakwa kya kwovosya; nũndũ nditonya kũkyovosya.'),
('kam', 'RUT', 4, 7, 'Na ĩndĩ ũũ nĩw’o waĩ kĩthĩo kwa Isilaeli mavinda ma tene ũndũ wa kwovosya na ũndũ wa kũkũan’ya, kwondũ wa kũlũlũmĩlya maũndũ onthe: mũndũ aumasya kĩatũ kyake, na aimũnenga mũtũi wake; na ũu nĩw’o waĩ mũthemba wa ũkũsĩ kwa Isilaeli.'),
('kam', 'RUT', 4, 8, 'Kwondũ wa ũu wa ũu mũndũ wa mũvĩa wa vakuvĩ amwĩa Mboasi, Ĩthooee mwene. Na aumya kĩatũ kyake.'),
('kam', 'RUT', 4, 9, 'Na Mboasi amea atumĩa, na andũ onthe, Inyw’ĩ mwĩ ngũsĩ mũnthĩ ũũ, kana nĩnathooa kyonthe kĩla kyaĩ kya Elimeleki, na kyonthe kĩla kyaĩ kya Kilioni na Maloni, kuma kw’okonĩ kwa Naomi.'),
('kam', 'RUT', 4, 10, 'Na ĩngĩ Luthi ũla Mũmoavi, kĩveti kya Maloni, nĩnamũthooa atw’ĩke mũka wakwa, nũkĩlye syĩtwa ya ũla mũkw’ũ ũtiĩwanĩ wake, nĩ kana syĩtwa ya ũsu mũkw’ũ yĩikavetwe kuma katĩ wa ana‐a‐ĩthe make, na kuma mbingĩlonĩ ya vandũ vake: inyw’ĩ mwĩ ngũsĩ mũnthĩ ũũ.'),
('kam', 'RUT', 4, 11, 'Na andũ onthe ala maĩ mbingĩlonĩ, na atumĩa, masya, Twĩ ngũsĩ. Yeova namũtw’ĩkĩthye mũndũ mũka ũla walika nyũmba kwaku o ta Lakeli na ta Lea, ala maakie me elĩ nyũmba ya Isilaeli: naku waĩle nthĩnĩ wa Evilatha, na ĩthĩwa na nguma Mbethi‐leemu:'),
('kam', 'RUT', 4, 12, 'na nyũmba yaku yĩthĩwe ta nyũmba ya Velesi, ũla Tamali wamũsyaĩe Yuta, ya mbeũ ĩla Yeova wĩkũnenga ya mũndũ mũka ũũ wa mũika.'),
('kam', 'RUT', 4, 13, 'Kwondũ wa ũu Mboasi amwosa Luthi, na atw’ĩka kĩveti kyake; na alika kwakyo, na Yeova akĩnenga kũya ĩvu, na kyasyaa mwana.'),
('kam', 'RUT', 4, 14, 'Na iveti syamwĩa Naomi, Yeova nataĩwe, ũla ũtakũtia ũmũnthĩ ũte mũndũ wa mũvĩa wa vakuvĩ; na syĩtwa yake nĩyĩthĩwe na nguma nthĩnĩ wa Isilaeli.'),
('kam', 'RUT', 4, 15, 'Na kwaku akeethĩwa mũtũngĩĩi wa thayũ, na mũei wa ũkũu waku; nũndũ mũka wa mwana waku, ũla ũkwendete, ũla mũseo kwaku kũvĩtũka ana mũonza, nĩwamũsyaa.'),
('kam', 'RUT', 4, 16, 'Na Naomi oosa kana, na akaia kĩthũinĩ kyake, na atw’ĩka mũei wako.'),
('kam', 'RUT', 4, 17, 'Na iveti, atũi make, syakatw’ĩa syĩtwa, ikyasya, Ve mwana ũsyaĩtwe kwa Naomi; na syamwĩta syĩtwa yake Oveti: nĩwe ĩthe wa Yese, ĩthe wa Ndaviti.'),
('kam', 'RUT', 4, 18, 'Na ĩndĩ ii nĩsyo nzyawa sya Velesi: Velesi amũsyaie Esiloni,'),
('kam', 'RUT', 4, 19, 'na Esiloni amũsyaa Lamu, na Lamu amũsyaa Aminatavu,'),
('kam', 'RUT', 4, 20, 'na Aminatavu amũsyaa Nasoni, na Nasoni amũsyaa Salumoni,'),
('kam', 'RUT', 4, 21, 'na Salumoni amũsyaa Mboasi, na Mboasi amũsyaa Oveti,'),
('kam', 'RUT', 4, 22, 'na Oveti amũsyaa Yese, na Yese amũsyaa Ndaviti.'),
('kam', '1SA', 1, 1, 'Na kwaĩ mũndũ ũmwe wa Lamathaimu‐nzovimu, wa nthĩ yĩ iĩma ya Evalaimu, na syĩtwa yake eetawa Elikana, mwana wa Yeloamu, mwana wa Eliu, mwana wa Tou, mwana wa Nzuve, Mũevalaimu:'),
('kam', '1SA', 1, 2, 'na aĩ na iveti ilĩ; syĩtwa ya kĩmwe kyeetawa Aana, na syĩtwa ya kĩla kĩngĩ Venina: na Venina aĩ na syana, ĩndĩ Aana ndaĩ syana.'),
('kam', '1SA', 1, 3, 'Na mũndũ ũsu ambataa o kĩla mwaka kuma ndũanĩ yoo akathaithe na kũthembea Yeova wa nguthu ku Silo. Na ana elĩ ma Eli, Ovini na Vineasi, athembi ma Yeova, maĩ kw’o.'),
('kam', '1SA', 1, 4, 'Na yĩla mũthenya wavikaa wa Elikana kũthemba, amanengae Venina mũka wake, na ana make na eĩtu make onthe, ilungu:'),
('kam', '1SA', 1, 5, 'ĩndĩ anengae Aana kĩlungu kĩanĩe kũndũ kwĩlĩ; nũndũ nĩwamwendete Aana, ĩndĩ Yeova nĩwavingĩte ĩvu yake.'),
('kam', '1SA', 1, 6, 'Na nthũ yake yamũthatasya mũno, ĩtumae eew’a woo, nĩkwĩthĩwa Yeova nĩwavingĩte ĩvu yake.'),
('kam', '1SA', 1, 7, 'Na o akĩka ũu kĩla mwaka, yĩla wambataa nyũmbanĩ ya Yeova, now’o yamũthatasya; kwondũ wa ũu aĩa na ndaaya.'),
('kam', '1SA', 1, 8, 'Na Elikana mũũme wake amwĩa, Aana, nĩkĩ ũkũĩa? Na nĩkĩ ũteũya? Na nĩkĩ ngoo yaku yĩ na woo? Nyie ndi mũseo kwaku kũvĩtũka ana ĩkũmi?'),
('kam', '1SA', 1, 9, 'Kwondũ wa ũu ĩtina wa mamina kũya, na mamina kũnyw’a me ku Silo, Aana ookĩla. Na ĩndĩ Eli mũthembi ekalĩte kĩvĩlanĩ kyake vakuvĩ na mũtĩ wĩ ũtee wa mũomo wa ĩkalũ ya Yeova.'),
('kam', '1SA', 1, 10, 'Na Aana aĩ na ũũ mũnene wa ngoo, na avoya Yeova, na aĩa mũno.'),
('kam', '1SA', 1, 11, 'Na eevĩta wĩvĩto, na asya, Ame Yeova wa nguthu, ethĩwa w’o ũkasisya thĩna wa mũthũkũmi waku mwĩĩtu, na ũindilikana nyie, na ũilea kũlwa nĩ mũthũkũmi waku mwĩĩtu, ĩndĩ ũkanenga mũthũkũmi waku mwĩĩtu, mwana mũũme, nĩvo ĩndĩ nĩmũnengane kwa Yeova mĩthenya yonthe ya thayũ wake, na vati wenzi ũkavika mũtwe wake.'),
('kam', '1SA', 1, 12, 'Na kweethĩwa, o aendeee na kũvoya e mbee wa Yeova, Eli asyaĩĩsya kanyw’a wake.'),
('kam', '1SA', 1, 13, 'Na ĩndĩ Aana aneenaa ngoonĩ yake; no ilomo syake syanyaunyasya, ĩndĩ wasya wake ndwaaĩw’ĩka: kwondũ wa ũu Eli asũanĩa nũnyw’ĩte.'),
('kam', '1SA', 1, 14, 'Na Eli amwĩa, Wĩĩkala wĩ mũnywi kũvika ĩndĩĩ? Veta kũasa naku mbinyu yaku.'),
('kam', '1SA', 1, 15, 'Na Aana asũngĩa na amwĩa, Aiee, mwĩaĩi wakwa, nyie nĩ mũndũ mũka wĩ na veva wĩ woo: ndinyw’ĩte mbinyu kana kĩla kĩtoonasya, ĩndĩ nĩonoasya ngoo yakwa vala ve Yeova.'),
('kam', '1SA', 1, 16, 'Ndũkatale mũthũkũmi waku mwĩĩtu ta mũndũ mũka mũthũku; nũndũ kuma wingĩnĩ wa mũnyungunyĩsyo wakwa na kũthataw’a kwakwa nĩnĩneenete kũvika yu.'),
('kam', '1SA', 1, 17, 'Nĩvo ĩndĩ Eli wasũngĩie na amwĩa, Enda na mũuo; na Ngai wa Isilaeli nakũnenge ũndũ ũsu waku wamũvoya.'),
('kam', '1SA', 1, 18, 'Na asya, Mũthũkũmi waku mwĩĩtu nĩone ũseo methonĩ maku. Kwondũ wa ũu kĩveti kyathi, na kyaya; na ũthyũ wakyo ndwaatuka ĩngĩ.'),
('kam', '1SA', 1, 19, 'Na mookĩla kĩoko tene, na mathaithĩa vu mbee wa Yeova, na masyoka, mavika nyũmbanĩ yoo Lama. Na Elikana amũmanya Aana mũka wake; na Yeova amũlilikana;'),
('kam', '1SA', 1, 20, 'na kweethĩwa, yĩla ĩvinda yavikie, Aana aitava na asyaa mwana; na amwĩta syĩtwa yake Samueli, akyasya, Nĩkwĩthĩwa nĩnamwĩtisye kwa Yeova.'),
('kam', '1SA', 1, 21, 'Na mũndũ ũsu Elikana na nyũmba yake yonthe mambata kũmũthembea Yeova nthembo ya mwaka, o na ya wĩvĩto wake.'),
('kam', '1SA', 1, 22, 'Ĩndĩ Aana ndaambata; nũndũ amwĩie mũũme, Nyie ndiambata mũvaka mwana aaĩa; na ĩndĩ ngamũtwaa, nĩ kana aumĩle mbee wa Yeova, na akĩkalaa vau ĩndĩ yonthe.'),
('kam', '1SA', 1, 23, 'Na Elikana mũũme wake amwĩa, Ĩka ũndũ ũkwona wĩ ũseo; ĩkala kũvika wamũaĩsya; ĩndĩ Yeova nalũlũmĩlye ndeto yake. Kwondũ wa ũu kĩveti kyekala kĩkyongya mwana wakyo, kuvika, kyamũaĩsya.'),
('kam', '1SA', 1, 24, 'Na yĩla kyamũaĩisye, kyambata vamwe nake, kĩ na tũsalũ twa mũew’a tũtatũ, na eva ĩmwe ya mũtu, na kathatwa ka mbinyu na amũtwaa nyũmbanĩ ya Yeova ku Silo: na mwana aĩ mũnini.'),
('kam', '1SA', 1, 25, 'Na moaa kasalũ ka mũew’a, na matwaa mwana kwa Eli.'),
('kam', '1SA', 1, 26, 'Na kyamwĩa, We, mwĩaĩi wakwa, o tondũ kyuu kyaku kĩ thayũ, mwĩaĩi wakwa, ninyie kĩla kĩveti kyaũngamĩte vakuvĩ naku vaa, kĩimũvoya Yeova.'),
('kam', '1SA', 1, 27, 'Navoyaa mwana ũũ; na Yeova nũnengete kĩla namwĩtisye:'),
('kam', '1SA', 1, 28, 'kwondũ wa ũu o nakwa nĩnĩmũnenganĩte kwa Yeova; ĩvinda yĩla wĩĩkala thayũ we nĩ mũnengane kwa Yeova. Na amũthaithĩa Yeova vau.'),
('kam', '1SA', 2, 1, 'Na Aana avoya, na asya: Ngoo yakwa nĩnĩũtanĩa Yeova; Ũvya wakwa nĩ mũkĩlye nĩ Yeova; Kanyw’a wakwa nĩ mũnenevye ĩũlũ wa amaitha makwa; Nĩkwĩthĩwa nĩngũtana ũtangĩĩonĩ waku.'),
('kam', '1SA', 2, 2, 'Vati ũngĩ mũtheu ta Yeova; Nũndũ kũtiĩ ate o we, O na kũti ĩvia o na yĩva ta Ngai waitũ.'),
('kam', '1SA', 2, 3, 'Ndũkaneene na ngathĩĩo nene ũu ĩngĩ; Wĩnenevyo ndũkaume kanyw’anĩ waku; Nũndũ Yeova nĩ Ngai wa ũmanyi, Na meko nĩmathimawa nĩwe.'),
('kam', '1SA', 2, 4, 'Mata ma ngũmbaũ nĩ matũlĩku; Na ala malulutĩkangile nĩmavotoetwe vinya.'),
('kam', '1SA', 2, 5, 'Ala maĩ avũnu nĩmeethũkũmĩe mone lĩu; Na ala maĩ na nzaa nĩmaekie kwĩw’a nzaa: Ĩĩ, ngũngũ nĩsyaĩte syana mũonza; Na kĩla kĩ na syana mbingĩ nĩkĩũleela.'),
('kam', '1SA', 2, 6, 'Yeova nĩwũaaa, na nũthayũũkasya: Nũtheeasya kũvika Seoli, na nĩwambatasya kumya vo.'),
('kam', '1SA', 2, 7, 'Yeova nũtw’ĩkĩthasya ngya, na nũthuasya: Nũtheeasya, o na nĩwũkĩlasya.'),
('kam', '1SA', 2, 8, 'Nĩwũkĩlasya ngya yume kĩtoonĩ, Nũmũkĩlasya mũthĩni aume ũtũndanĩ wa syaa, Atume mekala na anene me mbee ũsumbĩnĩ, Na kũtiĩwa kĩvĩla kya ũsumbĩ kya ũsung’wa: Nũndũ ituĩ sya nthĩ nĩ sya Yeova, Na ailĩĩle nthĩ ĩũlũ wasyo.'),
('kam', '1SA', 2, 9, 'Akasũvĩaa nyaĩĩ sya atheu make; Ĩndĩ ala athũku makavindĩthw’a kĩvindunĩ; Nũndũ vati mũndũ ũkakĩlya nũndũ wa vinya.'),
('kam', '1SA', 2, 10, 'Ala makĩlanasya vinya na Yeova makavevenzwa; Akamatundumĩa e ĩtunĩ: Yeova akasilĩla itulu sya nthĩ; Na akamũnenga mũsumbĩ wake vinya, Na kũkĩlya ũvya wa mwĩtĩkĩw’a mauta wake.'),
('kam', '1SA', 2, 11, 'Na Elikana athi Lama nyũmba kwake. Na ũ mwana amũthũkũmaa Yeova e mbee wa mũthembi Eli.'),
('kam', '1SA', 2, 12, 'Na ĩndĩ ana ma Eli maĩ andũ athe; matyamwĩsĩ Yeova.'),
('kam', '1SA', 2, 13, 'Na kĩmanyĩo kya athembi andũnĩ kyaĩ, atĩ yĩla mũndũ o na wĩva wathembaa nthembo, mũthũkũmi wa mũthembi nĩwokaa yĩla nyama iũtheũka, akwete kĩtonyi kya nyama kĩ maeo atatũ kw’okonĩ kwake;'),
('kam', '1SA', 2, 14, 'na akĩsovelya katevenĩ, kana ĩsilianĩ, kana kĩtevenĩ, kana mbisũnĩ; kyonthe kĩla kĩtonyi kya nyama kyaumasya nĩkyo mũthembi wosaa. Ũũ nĩw’o meekaa ku Silo kwa Aisilaeli onthe ala mookaa kw’o.'),
('kam', '1SA', 2, 15, 'Ĩĩ, mbee wa matanavĩvya mathunya, mũthũkũmi wa mũthembi nĩwokaa, na akĩmwĩa mũndũ ũla ũnũkũthemba, Nenga nyama ya kũmũvĩvĩsya mũthembi; nũndũ ndekwenda kwaku nyama ila ntheũkye, ĩndĩ nĩ ila mbĩthĩ.'),
('kam', '1SA', 2, 16, 'Na ethĩwa ũ mũndũ nĩwamwĩie, Matitĩa kwamba kũvĩvya mathunya, na ĩndĩ ũkyosa o ũndũ ngoo yaku ĩnĩkwenda; nĩvo ĩndĩ wamwĩaa, Aiee, ĩndĩ wĩnenga yo oyu: na ethĩwa ti ũu, nĩngũmyosa na vinya.'),
('kam', '1SA', 2, 17, 'Na naĩ ya anake asu yaĩ nene mũno kwa Yeova; nũndũ andũ nĩmavũthisye nthembo ya Yeova.'),
('kam', '1SA', 2, 18, 'Ĩndĩ Samueli athũkũmaa vu mbee wa Yeova, e o kana, ekĩĩte evoti ya katane.'),
('kam', '1SA', 2, 19, 'Na ĩngĩ inyia wake nĩwamũtumĩaa ngũa nini ndasa, na amũtwaĩaa o kĩla mwaka, yĩla wambataa na mũũme wake kũthemba nthembo ya mwaka.'),
('kam', '1SA', 2, 20, 'Na Eli amũathima Elikana na mũka wake, na amwĩa, Yeova nakũnenge ũsyao kwa kĩveti kĩĩ nũndũ wa kyu kĩla kyeetiw’e kwa Yeova. Na menũka mũsyĩ kwoo.'),
('kam', '1SA', 2, 21, 'Na Yeova amũkĩa Aana, na aitava, na asyaa ana atatũ na eĩtu elĩ. Na kamwana Samueli keana ke o mbee wa Yeova.'),
('kam', '1SA', 2, 22, 'Na ĩndĩ Eli aĩ mũkũu mũno; na nĩwew’aa onthe ala ana make meekaa Isilaeli onthe, na ũndũ makomaa na aka ala matethasya wĩa mũomonĩ wa yĩla ĩeema ya kũmbanĩa.'),
('kam', '1SA', 2, 23, 'Na amea, Mwĩkaa maũndũ ta asu nĩkĩ? Nũndũ nĩw’aa mĩkĩle yenyu mĩthũku kuma andũnĩ aa onthe.'),
('kam', '1SA', 2, 24, 'Aiee, ana makwa; nũndũ ti ũvoo mũseo ũla nĩw’aa: nĩmũtuma andũ ma Yeova mavĩtya.'),
('kam', '1SA', 2, 25, 'Ethĩwa mũndũ ũmwe nũkũvĩtanĩsya ũngĩ, Ngai akamũsilĩla; ĩndĩ ethĩwa mũndũ nũkũvĩtanĩsya Yeova, nũũ ũla wĩmwĩsũvanĩa? Ĩndĩ mo, matyaaĩthukĩĩsya wasya wa ĩthe woo, nĩkwĩthĩwa Yeova asũanĩaa kũmoaa.'),
('kam', '1SA', 2, 26, 'Na kamwana Samueli kaendeea kwĩana, na kaendeea kwona ũseo kwa Yeova o na andũnĩ.'),
('kam', '1SA', 2, 27, 'Na kwooka mũndũ wa Ngai kwa Eli, na amwĩa, Ũũ nĩw’o Yeova ũnũũkũlya, Nĩneeyonanisye nyie mwene nyũmbanĩ ya ĩthe waku, yĩla maĩ ũkombonĩ Misili nyũmbanĩ ya Valao?'),
('kam', '1SA', 2, 28, 'Na nyie nĩnamũnyuvie kuma mbaĩnĩ syonthe sya Isilaeli atw’ĩke mũthembi wakwa, ambatae kĩthembeonĩ kyakwa, na kũtoeeasya ũvani, na kwĩkĩaa evoti e mbee wakwa? Na nĩnanengie nyũmba ya ĩthe waku nthembo syonthe sya ana ma Isilaeli ila ivĩvaw’a na mwaki?'),
('kam', '1SA', 2, 29, 'Nũndũ wa kĩ mũtheelaa nthembo yakwa ya kũtonywa na nthembo ĩngĩ yakwa, ila nĩaĩte ũtũonĩ wakwa, na kũtaĩaa ana maku kwĩ nyie, nĩ kana mwĩnoasye inyw’ĩ ene na nthembo syonthe ila syĩ vata mbee sya Isilaeli, andũ makwa?'),
('kam', '1SA', 2, 30, 'Kwondũ wa ũu Yeova, Ngai wa Isilaeli, easya, Nĩ w’o, nĩnaisye kana nyũmba yaku, na nyũmba ya ĩthe waku, ikaendaa mbee wakwa tene na tene: ĩndĩ yu Yeova easya, Ũu wĩthĩwe kũasa nakwa; nũndũ ala mandaĩaa ngamataĩa, na ala mambũthasya makatalwa ta vathei.'),
('kam', '1SA', 2, 31, 'Sisya, mĩthenya nĩyũkĩte, yĩla ngatila kw’oko kwaku, na kw’oko kwa nyũmba ya ĩthe waku, na vaikaaĩthĩwa mũtumĩa nyũmbanĩ yaku.'),
('kam', '1SA', 2, 32, 'Na nũkona ũnyamao wa ũtũo wakwa, ũthwiinĩ w’onthe ũla Ngai ũkanenga Isilaeli; na vaikaaĩthĩwa mũtumĩa nyũmbanĩ yaku tene na tene.'),
('kam', '1SA', 2, 33, 'Na mũndũ waku, ũla ndakaveta kĩthembeonĩ kyakwa, akeethĩwa wa kwananga metho maku, na wa kwĩw’ĩthya ngoo yaku woo; na mosyaanĩo onthe ma nyũmba yaku makakusaa me ma ĩika.'),
('kam', '1SA', 2, 34, 'Na ũũ ũkeethĩwa wonan’yo kwaku, ũla ũkakĩtĩka kwa ana maku elĩ, Ovini na Vineasi: makakw’a me elĩ mũthenya ũmwe.'),
('kam', '1SA', 2, 35, 'Na nĩngeyũkĩlĩlya mũthembi wĩ kĩthito, ũla ũkeka kwĩanana na ũla wĩ ngoonĩ yakwa na kĩlilikanonĩ kyakwa: na nĩngamwakĩa nyũmba nũmu; na nũkaendaa mbee wa ũla mwĩtĩkĩw’a mauta wakwa tene na tene.'),
('kam', '1SA', 2, 36, 'Na nĩkũkethĩwa, kĩla ũmwe ũkatiala nyũmbanĩ yaku nũkoka na kũtulya ndu kwake kana one kĩlungu kya vetha na kĩmũtũ kĩmwe, na akasya, Ndikya, nĩngũkwĩsũva, wĩanĩ ũmwe wa athembi, nĩ kana nĩtonye kũya kalungu kanini ka kĩmũtũ.'),
('kam', '1SA', 3, 1, 'Na kamwana Samueli kamũthũkũmĩaa Yeova vu mbee wa Eli. Na ndeto ya Yeova yaĩ vata mũno mĩthenya ĩsu; kũtyaĩ woni kaingĩ.'),
('kam', '1SA', 3, 2, 'Na kweethĩwa ĩvinda yĩu, yĩla Eli wakomete vandũ vake (na yu metho make maĩ manambĩlĩlya kũya mbindu, ũndũ ũtatonya kwona),'),
('kam', '1SA', 3, 3, 'na taa wa Ngai ndwaĩ ũnamba kũvoa, na Samueli nĩwakomete ĩkalũnĩ ya Yeova, vala yĩla ĩsandũkũ ya Ngai yaĩ;'),
('kam', '1SA', 3, 4, 'nĩvo Yeova wamwĩtie Samueli: nake asya, Nĩ vaa.'),
('kam', '1SA', 3, 5, 'Na asemba vala ve Eli, na amwĩa, Ninyioo; nũndũ nĩwambĩta. Nake asya, Ndinetana; koma ĩngĩ. Nake athi na akoma.'),
('kam', '1SA', 3, 6, 'Na Yeova eetana o ĩngĩ, Samueli. Na Samueli ookĩla na athi vala ve Eli, na asya, Ninyioo; nũndũ nĩwambĩta. Nake asũngĩa, Ndinetana, mwana wakwa; koma ĩngĩ.'),
('kam', '1SA', 3, 7, 'Na ũ Samueli ndambĩte kũmũmanya Yeova, o na ndeto ya Yeova ndĩambĩte kũvuanw’a kwake.'),
('kam', '1SA', 3, 8, 'Na Yeova amwĩta Samueli ĩngĩ ĩvinda ya katatũ. Na ookĩla na athi vala ve Eli, na asya, Ninyioo; nũndũ nĩwambĩta. Na Eli amanya kana Yeova nũkwĩtaa kamwana.'),
('kam', '1SA', 3, 9, 'Kwondũ wa ũu Eli amwĩa Samueli, Thi, ũkakome; na kũkethĩwe atĩĩ, ethĩwa nũkũkwĩta, nĩw’o wĩasya, Neena, Yeova; nũndũ mũthũkũmi waku nũkwĩw’a. Na ĩndĩ Samueli athi na akoma vandũ vake.'),
('kam', '1SA', 3, 10, 'Na Yeova ooka, na aũngama, na eetana ta metana ala angĩ, Samueli, Samueli. Nĩvo ĩndĩ Samueli waisye, Neena; nũndũ mũthũkũmi waku nũkwĩw’a.'),
('kam', '1SA', 3, 11, 'Na Yeova amwĩa Samueli, Sisya, ngeeka ũndũ nthĩnĩ wa Isilaeli, ũla matũ elĩ ma kĩla mũndũ ũla wĩĩw’a makasĩĩlĩla.'),
('kam', '1SA', 3, 12, 'Mũthenya ũsu nĩngeanĩĩsya kwa Eli w’onthe ũla nĩneenete ũndũ wa nyũmba yake, kuma wambĩlĩlyo o na kũvika mũminũkĩlyo.'),
('kam', '1SA', 3, 13, 'Nũndũ nĩnĩmũtavĩtye kana ngasilĩla nyũmba yake tene na tene, nũndũ wa ũthũku ũla wesĩ, nĩkwĩthĩwa ana make nĩmeeyĩetee kĩumo, na ndaamasiĩĩa.'),
('kam', '1SA', 3, 14, 'Na kwondũ wa ũu nĩnĩvĩtĩe nyũmba ya Eli, kana ũthũku wa nyũmba ya Eli ndũkathew’a na nthembo ya kũtonywa kana nthembo ĩngĩ tene na tene.'),
('kam', '1SA', 3, 15, 'Na Samueli akoma kũvika kwakya, na avingũa mĩomo ya nyũmba ya Yeova. Na Samueli akĩa kũmwon’ya Eli ũla woni.'),
('kam', '1SA', 3, 16, 'Nĩvo ĩndĩ Eli wamwĩtie Samueli, na asya, Samueli, mwana wakwa. Nake asya, Ninyioo.'),
('kam', '1SA', 3, 17, 'Nake amũkũlya, Nĩ ũndũ mwaũ ũla Yeova ũneenie naku? Nĩngũkwĩsũva, ndũkombithe: Ngai nakwĩke ũu, o na mbee, ethĩwa ũkambitha ũndũ o na wĩva wa maũndũ onthe ala ũneenie naku.'),
('kam', '1SA', 3, 18, 'Na Samueli amũtavya kĩla kaũndũ, na ndaamũvitha ũndũ. Nake asya, Nĩ Yeova: nĩeke ũndũ wĩona wĩ ũseo.'),
('kam', '1SA', 3, 19, 'Na Samueli eana, na Yeova aĩ vamwe nake, na ndaaĩtĩkĩla ndeto o na ĩmwe yake ĩvalũke nthĩ.'),
('kam', '1SA', 3, 20, 'Na Isilaeli onthe kuma Ndani kũvika Mbeeli‐sieva mamanya kana Samueli nĩwalũlũmĩlw’e ethĩwe mwathani wa Yeova.'),
('kam', '1SA', 3, 21, 'Na Yeova aumĩla ĩngĩ ku Silo; nũndũ Yeova nĩweyonanisye mwene kwa Samueli na ndeto ya Yeova ku Silo.'),
('kam', '1SA', 4, 1, 'Na ndeto ya Samueli yũkĩa Isilaeli onthe. Na ĩndĩ Isilaeli maenda kũkita na Avilisiti, na mamba maeema ũtee wa Eveni‐eseli: na Avilisiti mamba maeema ku Aveki.'),
('kam', '1SA', 4, 2, 'Na Avilisiti meetaũsya mokite na Isilaeli: na yĩla makwatisye kaũ, Isilaeli makũnwa nĩ Avilisiti; na mooaĩa andũ ta ngili inya ma nguthu ya kaũ weũnĩ.'),
('kam', '1SA', 4, 3, 'Na yĩla andũ mookie mwakonĩ wa maeema, atumĩa ma Isilaeli makũlya, Kĩla kĩtumie Yeova atũkũnĩthya Avilisiti ũmũnthĩ nĩ kyaũ? Tũlatyei yĩla ĩsandũkũ ya ũtianĩo ya Yeova kuma Silo tũete kũũ tũĩ, nĩ kana yũke katĩ waitũ, na kũtũtangĩĩa kuma mokonĩ ma amaitha maitũ.'),
('kam', '1SA', 4, 4, 'Kwondũ wa ũu andũ matũmana Silo, na maete kuma kw’o yĩla ĩsandũkũ ya ũtianĩo ya Yeova wa nguthu, ũla wĩkalaa ĩũlũ wa akeluvi: na ana elĩ ma Eli, Ovini na Vineasi, maĩ vo vamwe na ĩsandũkũ ya ũtianĩo ya Ngai.'),
('kam', '1SA', 4, 5, 'Na yĩla ĩsandũkũ ya ũtianĩo ya Yeova yookie mwakonĩ wa maeema, Isilaeli onthe mausya ngemi na wasya mũtũlu, mũvaka nthĩ yeetĩkĩanĩsya ĩngĩ.'),
('kam', '1SA', 4, 6, 'Na yĩla Avilisiti meewie wasya wa ngemi ĩsu nene, masya, Wasya ũsu wa ngemi nene wĩ mwakonĩ wa maeema wa Aevelania nĩ wa kĩ? Na mamanya kana ĩsandũkũ ya Yeova nĩyooka mwakonĩ wa maeema.'),
('kam', '1SA', 4, 7, 'Na Avilisiti meew’a w’ĩa, nũndũ maisye, Ngai nĩwoka mwakonĩ wa maeema. Na masya, Woo nĩ witũ! Nũndũ kũtyaamba kwĩthĩwa ũndũ ta ũũ kũvika yu.'),
('kam', '1SA', 4, 8, 'Woo nĩ witũ! Nũũ ũla wĩtũvonokya kuma kw’okonĩ kwa ngai ii syĩ vinya mũnene? Ii nĩ ngai ila syakũnĩe Amisili weũnĩ na mĩthemba yonthe ya mothĩn’yo.'),
('kam', '1SA', 4, 9, 'Ĩthĩwai na vinya, na ĩthĩwai aũme, inyw’ĩ Avilisiti, nĩ kana mũikethĩwe athũkũmi ma Aevelania, o tondũ methĩĩtwe kwenyu: ĩthĩwai aũme, na mũkyũkita.'),
('kam', '1SA', 4, 10, 'Na Avilisiti mokita, na Isilaeli makũnwa, na makũka kĩla mũndũ athi ĩeemanĩ yake: na vaĩ kũawa kũnene mũno; nũndũ kwavalũkilw’e andũ ma Isilaeli ala maendaa na maũũ ngili mĩongo ĩtatũ.'),
('kam', '1SA', 4, 11, 'Na ĩsandũkũ ya Ngai yooswa; na ana elĩ ma Eli, Ovini na Vineasi, mooawa.'),
('kam', '1SA', 4, 12, 'Na kwasemba mũndũ wa Mbenyamini kuma nguthunĩ ya kaũ, na avika Silo mũthenya o ũsu, ngũa syake syĩ ndembũange, na mũthanga ĩũlũ wa mũtwe wake.'),
('kam', '1SA', 4, 13, 'Na yĩla wavikie, sisya, Eli ekalĩte kĩvĩlanĩ kyake ũtee wa nzĩa asyaĩĩsye; nũndũ ngoo yake nĩyatelemangaa nũndũ wa ĩsandũkũ ya Ngai. Na yĩla ũ mũndũ wavikie ndũanĩ, na atavan’ya ũu, ndũa yonthe yaĩa na wasya.'),
('kam', '1SA', 4, 14, 'Na yĩla Eli wewie wasya wa kĩĩo, akũlya, Wasya ũũ wa kĩĩo nĩ wa kĩ? Na ũ mũndũ eekalaata, na ooka amũtavya Eli.'),
('kam', '1SA', 4, 15, 'Na ĩndĩ Eli aĩ wa myaka mĩongo kenda na nyanya; na metho make nĩmaĩte mbindu, ũndũ ũtatonya kwona.'),
('kam', '1SA', 4, 16, 'Na ũ mũndũ amwĩa Eli, Ninyie we ũla wauma nguthunĩ ya kaũ, na nĩkĩie ũmũnthĩ kuma nguthunĩ ya kaũ. Nake akũlya, Ũvoo ũendie ata, mwana wakwa?'),
('kam', '1SA', 4, 17, 'Na ũla waetie ũvoo asũngĩa na asya, Isilaeli nĩmakĩie Avilisiti, o na ĩngĩ kwĩthĩĩtwe kũawa kũnene andũnĩ, na ana maku elĩ namo, Ovini na Vineasi, nĩ akw’ũ, na ĩsandũkũ ya Ngai nĩ yose.'),
('kam', '1SA', 4, 18, 'Na kweethĩwa, yĩla wawetie ĩsandũkũ ya Ngai, Eli avalũka kuma kĩvĩlanĩ kyake na ngala ũtee wa mbingĩlo; na ngingo yake yatũlĩka, na akw’a: nũndũ aĩ mũndũ mũkũu, na mũito. Na nĩwasilanĩtye Isilaeli myaka mĩongo ĩna.'),
('kam', '1SA', 4, 19, 'Na mũka‐a‐mwana, kĩveti kya Vineasi, kyaĩ kĩito, vakuvĩ kũsyaa: na yĩla kyeewie ũvoo kana ĩsandũkũ ya Ngai nĩyosetwe, na kana ĩthe wa mũũme na mũũme nĩmakwie, kyakunama na kyasyaa; nũndũ woo wakyo nĩwakĩkwatie.'),
('kam', '1SA', 4, 20, 'Na ta ĩvinda ya kũkw’a kwakyo iveti ila syakĩũngamĩe syakĩtavya, Ndũkakĩe; nũndũ nĩwasyaa mwana. Ĩndĩ kĩtyaasũngĩa, o na kĩtyaaona ta ũndũ.'),
('kam', '1SA', 4, 21, 'Na kyeeta kana Ikavotu, kĩkyasya, Ũsũng’wa nĩwumĩte kwa Isilaeli; nũndũ ĩsandũkũ ya Ngai nĩyosetwe, na nũndũ wa ĩthe wa mũũme na mũũme.'),
('kam', '1SA', 4, 22, 'Na kyasya, Ũsũng’wa nĩwumĩte kwa Isilaeli; nũndũ ĩsandũkũ ya Ngai nĩ yose.'),
('kam', '1SA', 5, 1, 'Na ĩndĩ Avilisiti nĩmoosete ĩsandũkũ ya Ngai, na mayĩtwaa kuma Eveni‐eseli kũvika Asitoti.'),
('kam', '1SA', 5, 2, 'Na Avilisiti moosa ĩsandũkũ ya Ngai, na mayĩlikya nyũmbanĩ ya Ndakoni, na mayia vakuvĩ na Ndakoni.'),
('kam', '1SA', 5, 3, 'Na yĩla ala ma Asitoti mookĩlile ũnĩ ũsu kĩoko tene, sisya, Ndakoni nĩwavalũkĩte na ũthyũ wake nthĩ mbee wa ĩsandũkũ ya Yeova. Na moosa Ndakoni, na mamũũngamya ĩngĩ vandũ vake.'),
('kam', '1SA', 5, 4, 'Na yĩla mookĩlile ũnĩ ũsu ũngĩ kĩoko tene, sisya, Ndakoni aĩ o mũvalũku na ũthyũ wake nthĩ mbee wa ĩsandũkũ ya Yeova; na mũtwe wa Ndakoni na itaa syelĩ sya moko make itilĩkĩle mwalyonĩ; no kĩthũmba kya Ndakoni kyatialĩte.'),
('kam', '1SA', 5, 5, 'Kwondũ wa ũu o na athembi ma Ndakoni, kana o ũla ũkũlika nyũmbanĩ ya Ndakoni, ndakinyaa mwalyo kwa Ndakoni ku Asitoti, kũvika mũthenya ũũ.'),
('kam', '1SA', 5, 6, 'Ĩndĩ kw’oko kwa Yeova kwaĩ kũito ĩũlũ wa asu ma Asitoti, na amananga, na amakũna na mĩimũ, ku Asitoti na mĩvakanĩ yayo.'),
('kam', '1SA', 5, 7, 'Na yĩla andũ ma Asitoti moonie kana kwailyĩ ũu, masya, Ĩsandũkũ ya Ngai wa Isilaeli yĩtiĩkala naitũ; nũndũ kw’oko kwake nĩ kũthũku ĩũlũ waitũ, na ĩũlũ wa Ndakoni ngai yaitũ.'),
('kam', '1SA', 5, 8, 'Kwondũ wa ũu matũmana na moomban’ya eaĩi onthe ma Avilisiti kwoo, na mamea, Twĩĩka ata na ĩsandũkũ ya Ngai wa Isilaeli? Na masũngĩa, Ĩsandũkũ ya Ngai wa Isilaeli yĩtwawe Ngathi. Na matwaa ĩsandũkũ ya Ngai wa Isilaeli kw’o.'),
('kam', '1SA', 5, 9, 'Na kweethĩwa, yĩla maminie kũyĩtwaa, kw’oko kwa Yeova kweethĩwa ĩũlũ wa ndũa na kũthokoan’ya kũnene mũno: na amakũna andũ ma ĩ ndũa, anini o na anene; na maimba mĩimũ.'),
('kam', '1SA', 5, 10, 'Kwondũ wa ũu matwaa ĩsandũkũ ya Ngai Ekiloni. Na kweethĩwa, yĩla ĩsandũkũ ya Ngai yavikie Ekiloni, Aekiloni maua mbu, makyasya, Maete ĩsandũkũ ya Ngai wa Isilaeli kwitũ, matũaĩthye ithyĩ na andũ maitũ.'),
('kam', '1SA', 5, 11, 'Kwondũ wa ũu matũmana na moomban’ya vamwe eaĩi onthe ma Avilisiti, na masya, Twaĩthyai ĩsandũkũ ya Ngai wa Isilaeli, na ekai yĩsyoke vandũ a vayo ĩngĩ, nĩ kana yĩikatũaĩthye ithyĩ, na andũ maitũ. Nũndũ kwaĩ kũthokoanw’a kwĩ kĩkw’ũ ndũanĩ yonthe vyũ; kw’oko kwa Ngai kwaĩ kũito mũno vo.'),
('kam', '1SA', 5, 12, 'Na andũ ala mataakw’a makũniwe nĩ ĩla mĩimũ; na kĩĩo kya ndũa kyambatie kũvika ĩtunĩ.'),
('kam', '1SA', 6, 1, 'Na ĩsandũkũ ya Yeova yaĩ nthĩ ya Avilisiti myei mũonza.'),
('kam', '1SA', 6, 2, 'Na Avilisiti mameta athembi na ala maaũasya, makĩkũlya, Twĩĩka ata na ĩsandũkũ ya Yeova? Twon’yei ithyĩ ũndũ twĩyĩtwaa vandũ vayo.'),
('kam', '1SA', 6, 3, 'Namo masũngĩa, Ethĩwa nĩmũtwaa ĩsandũkũ ya Ngai wa Isilaeli, mũikayĩtwae yĩ ĩthei; ĩndĩ mũitĩa kũmũtũnganĩĩsya na nthembo kwondũ wa ĩvityo: na ĩndĩ mũkavow’a, na mũkamanya kĩtumi kya kw’oko kwake kũlea kuma kwenyu.'),
('kam', '1SA', 6, 4, 'Nĩvo ĩndĩ makũlilye, Nĩ kyaũ kĩĩthĩwa nthembo kwondũ wa ĩvĩtyo kĩla twĩmũtũnganĩĩsya? Na masũngĩa, Mĩimũ ĩtano ya thaavu, na mbĩa itano sya thaavu, kwĩanana na ũtalo wa eaĩi ma Avilisiti; nũndũ ũthĩn’yo ũmwe ũnaĩ ĩũlũ wenyu inyw’onthe, na ĩũlũ wa eaĩi menyu.'),
('kam', '1SA', 6, 5, 'Kwondũ wa ũu mũkaseũvye mĩvw’anano ĩilyĩ ta mĩimũ yenyu, na mĩvw’anano ĩilyĩ ta mbĩa syenyu ila ithũkasya nthĩ; na mũkamũnenge Ngai wa Isilaeli ndaĩa: nokwĩthĩwa aleelya kw’oko kwake vala mũĩ, na vala ve ngai syenyu, na nthĩ yenyu.'),
('kam', '1SA', 6, 6, 'Mwĩtuma ĩndĩ kũmya ngoo syenyu nĩkĩ, tondũ Amisili na Valao moomisye ngoo syoo? Yĩla wekie moseng’yo katĩ wamo, matyaaeka andũ maende, na mathi?'),
('kam', '1SA', 6, 7, 'Na yu ĩndĩ osai mũyĩseũvĩsye ĩkasya yeũ, na osai ng’ombe ilĩ ikwongya, ila itaailĩĩlwa ĩsoki; na mũkyova ng’ombe ĩkasyanĩ, na mũkĩnũkya tũsaũ twasyo tume vala iĩ;'),
('kam', '1SA', 6, 8, 'na mũkyosa ĩsandũkũ ya Yeova na mũyilĩĩla ĩkasyanĩ; na mũkĩkĩa mĩio ya wanake ya thaavu, ĩla mũũmũtũnganĩĩsya yĩthĩwe nthembo kwondũ wa ĩvĩtyo, nthĩnĩ wa kasandũkũ ke ũtee wayo; na mũiyĩeka yĩkũsye, nĩ kana yĩtonye kũthi.'),
('kam', '1SA', 6, 9, 'Na syaĩĩsyai; ethĩwa yĩkambata Mbethi‐semesi na nzĩa ya mũvaka o wayo, nĩvo ĩndĩ nĩwe ũtwĩkĩte ũthũku ũũ mũnene: ĩndĩ ethĩwa ti w’o, nĩvo twĩmanya kana ti kw’oko kwake kũtũkũnie; no ũndũ wĩkĩkĩte ũtũvikĩĩte.'),
('kam', '1SA', 6, 10, 'Na andũ meeka ũu, na moosa ng’ombe ilĩ ikwongya, na masyova ĩkasyanĩ, na mavingĩa tũsaũ twasyo mũsyĩ;'),
('kam', '1SA', 6, 11, 'na mailĩĩla ĩsandũkũ ya Yeova ĩkasyanĩ ĩũlũ, na kasandũkũ ke na mbĩa sya thaavu na mĩvw’anano ya mĩimũ yoo.'),
('kam', '1SA', 6, 12, 'Na ila ng’ombe nga syakwata nzĩa ndũngalu ĩelete Mbethi‐semesi; syaenda na lelũ, ikyan’ya o iendete, na ityaaĩthyũũa ũtee ngalĩko ya kw’oko kwa aũme kana kwa aka; na eaĩi ma Avilisiti maiatĩĩa kũvika mũvakanĩ wa Mbethi‐semesi.'),
('kam', '1SA', 6, 13, 'Na ala ma Mbethi‐semesi nĩmakethaa ngetha yoo ya nganũ mwandanĩ; na mookĩlya metho moo, na moona yĩla ĩsandũkũ, na matana ũndũ wa kũyona.'),
('kam', '1SA', 6, 14, 'Na ĩkasya yooka mũũndanĩ wa Yosua Mũmbethi‐semesi, na yaũngama vo, vala vaĩ ĩvia ĩnene: na maatũanga mbwaũ sya ĩkasya, na mathembea Yeova ila ng’ombe nga nthembo ya kũvĩvw’a.'),
('kam', '1SA', 6, 15, 'Na Alivai maumya ĩsandũkũ ya Yeova, na kasandũkũ kala kaĩ vamwe nayo, vala mĩio ya wanake ya thaavu yaĩ, na mamilĩĩla ĩũlũ wa yĩla ĩvia ĩnene: na andũ ma Mbethi‐semesi mathembea Yeova nthembo sya kũvĩvw’a na mathemba nthembo sya kũtonywa mũthenya ũsu.'),
('kam', '1SA', 6, 16, 'Na yĩla ala eaĩi atano ma Avilisiti moonie ũu, masyoka Ekiloni mũthenya ũsu.'),
('kam', '1SA', 6, 17, 'Na ĩno nĩyo mĩimũ ya thaavu ila Avilisiti matwaĩe Yeova ĩthĩwe nthembo kwondũ wa ĩvĩtyo: ũmwe nũndũ wa Asitoti, na ũmwe nũndũ wa Ngasa, na ũmwe nũndũ wa Asikeloni, na ũmwe nũndũ wa Ngathi, na ũmwe nũndũ wa Ekiloni;'),
('kam', '1SA', 6, 18, 'na mbĩa sya thaavu, kwĩanana na ũtalo wa ndũa syonthe sya Avilisiti ila syaĩ sya eaĩi asu atano, ndũa mbiie o na mĩsyĩ yĩ ndee, o kũvika yĩla ĩvia ĩnene, vala maiie ĩsandũkũ ya Yeova, o yĩ ĩvia yĩ vo kũvika mũthenya ũũ mũũndanĩ wa Yosua Mũmbethi‐semesi.'),
('kam', '1SA', 6, 19, 'Na amakũna andũ amwe ma Mbethi‐semesi, nĩkwĩthĩwa nĩmasyaisye nthĩnĩ wa ĩsandũkũ ya Yeova, amakũna andũ mĩongo mũonza, na andũ angĩ ngili mĩongo ĩtano; na andũ maĩa, nĩkwĩthĩwa Yeova nĩwamakũnie andũ na kũawa kũnene.'),
('kam', '1SA', 6, 20, 'Na andũ ma Mbethi‐semesi makũlya, Nũũ ũla ũtonya kũũngama mbee wa Yeova, Ngai ũũ mũtheu? Na akambata kwaũ aume kwitũ?'),
('kam', '1SA', 6, 21, 'Na matũma atũmwa kwa ala matwĩe Kiliathi‐yealimu, makyasya, Avilisiti nĩmatũngĩte ĩsandũkũ ya Yeova; theeai, na mũkĩyambatya kwenyu.'),
('kam', '1SA', 7, 1, 'Na andũ ma Kiliathi‐yealimu mooka, na mambatya ĩsandũkũ ya Yeova, na mayĩlikya nyũmbanĩ ya Avinatavu kĩĩmanĩ, na mamũvathan’ya Eleasali mwana wake ethĩwe mũtheu asũvĩe ĩsandũkũ ya Yeova.'),
('kam', '1SA', 7, 2, 'Na kweethĩwa, atĩ ĩvinda yaĩ ĩasa kuma mũthenya ũla yĩla ĩsandũkũ yekalaa ku Kiliathi‐yealimu; nũndũ yaĩ myaka mĩongo ĩlĩ: na nyũmba yonthe ya Isilaeli yamũĩĩa Yeova.'),
('kam', '1SA', 7, 3, 'Na Samueli aneena na nyũmba yonthe ya Isilaeli, akyasya, Ethĩwa nĩmũũmũsyokea Yeova na ngoo syenyu syonthe, vetai ĩndĩ ngai ngeni na Asetalothi kuma katĩ wenyu, na elekelyai ngoo syenyu kwa Yeova, na mũimũthũkũma e weka; nake akamũvonokya kuma mokonĩ ma Avilisiti.'),
('kam', '1SA', 7, 4, 'Na ĩndĩ ana ma Isilaeli maveta Mbaalimu na Asetalothi, na mamũthũkũma Yeova e weka.'),
('kam', '1SA', 7, 5, 'Na Samueli amea, Ũmban’yai Isilaeli onthe Misiva, na ngavoya Yeova nũndũ wenyu.'),
('kam', '1SA', 7, 6, 'Namo moombana ku Misiva, na matava kĩw’ũ, na mamwĩtĩa Yeova nthĩ, na matĩĩa kũya mũthenya ũsu, na maĩsya vau, Nĩtũvĩtanĩsye Yeova. Na Samueli amasilanĩlasya ana ma Isilaeli ku Misiva.'),
('kam', '1SA', 7, 7, 'Na yĩla Avilisiti meewie kana ana ma Isilaeli nĩmombanĩe Misiva, eaĩi ma Avilisiti mambata mokite na Isilaeli. Na yĩla ana ma Isilaeli meewie ũu, maĩ na w’ĩa ũndũ wa Avilisiti.'),
('kam', '1SA', 7, 8, 'Na ana ma Isilaeli mamwĩa Samueli, Ndũkaeke kũmwĩkaĩla Yeova Ngai waitũ nũndũ witũ, nĩ kana atũtangĩĩe kuma mokonĩ ma Avilisiti.'),
('kam', '1SA', 7, 9, 'Na Samueli oosa katena ka ĩlondu kekwonga, na akathembea Yeova katw’ĩke nthembo nima ya kũvĩvw’a: na Samueli amwĩkaĩla Yeova nũndũ wa Isilaeli; na Yeova amũsũngĩa.'),
('kam', '1SA', 7, 10, 'Na yĩla Samueli wathembaa nthembo ya kũvĩvw’a, Avilisiti mathengeea mokite na Isilaeli; ĩndĩ Yeova amatundumĩa Avilisiti na kĩtundumo kĩnene mũthenya ũsu, na amathokoan’ya; na makũnwa mavalũkw’a nthĩ nĩ Isilaeli.'),
('kam', '1SA', 7, 11, 'Na andũ ma Isilaeli mauma Misiva, na mamakũa Avilisiti, na mamakũna, mũvaka mavika ĩtheo wa Mbethi‐kali.'),
('kam', '1SA', 7, 12, 'Nĩvo ĩndĩ Samueli wosie ĩvia, na ayĩũngamya katĩ wa Misiva na Seni, na eeta syĩtwa yavo Eveni‐eseli, akyasya, Kũvika yu Yeova nũtũtethetye.'),
('kam', '1SA', 7, 13, 'Na ĩndĩ Avilisiti makĩlw’a vinya, na matyaalika ĩngĩ mũvakanĩ wa Isilaeli: na kw’oko kwa Yeova kwaĩ ĩũlũ wa Avilisiti matukũ onthe ma Samueli.'),
('kam', '1SA', 7, 14, 'Na ndũa ila Avilisiti mavenete Isilaeli syatũngĩwa Isilaeli, kuma Ekiloni o na kũvika Ngathi; na mĩvaka yayo Isilaeli mamĩvonokya kuma mokonĩ ma Avilisiti. Na kwaĩ mũuo katĩ wa Isilaeli na Aamoli.'),
('kam', '1SA', 7, 15, 'Na Samueli amasilanasya Isilaeli matukũ onthe ma thayũ wake.'),
('kam', '1SA', 7, 16, 'Na athyũlũlũkaa o kĩla mwaka Mbethi‐eli, na Ngilikali, na Misiva; na amasilanĩlasya Isilaeli kũndũ kũu kw’onthe.'),
('kam', '1SA', 7, 17, 'Na asyokaa Lama, nũndũ vau nĩvo vaĩ nyũmba yake; na vo amasilanĩlasya Isilaeli: na amwakĩa Yeova kĩthembeo vo.'),
('kam', '1SA', 8, 1, 'Na kweethĩwa, yĩla Samueli wakũie, amatw’ĩkĩthya ana make asili ĩũlũ wa Isilaeli.'),
('kam', '1SA', 8, 2, 'Na ĩndĩ syĩtwa ya ĩkithathi yake yeetawa Yoeli, na syĩtwa ya ũ wa kelĩ, Aviya: maĩ asili Mbethi‐sieva.'),
('kam', '1SA', 8, 3, 'Na ana make matyakinyaa mĩendelenĩ yake, ĩndĩ meelelũka ũtee mamanthe mbesa, na moosaa mavaki, na kwelelũkasya ũsili wa katĩ.'),
('kam', '1SA', 8, 4, 'Nĩvo ĩndĩ atumĩa onthe ma Isilaeli moombanie vamwe, na mookĩa Samueli ku Lama;'),
('kam', '1SA', 8, 5, 'na mamwĩa, Sisya, we wĩ mũkũu, na ana maku maikinyaa mĩendelenĩ yaku: yu twiĩe mũsumbĩ wa kũtũsilanasya o ta mbaĩ syonthe.'),
('kam', '1SA', 8, 6, 'Ĩndĩ ũndũ ũsu wamwĩw’ĩthisye Samueli woo, yĩla maisye, Tũnenge mũsumbĩ wa kũtũsilanasya. Na Samueli avoya Yeova.'),
('kam', '1SA', 8, 7, 'Na Yeova amwĩa Samueli, Ĩthukĩĩsye wasya wa andũ maũndũnĩ onthe ala meũkũtavya: nũndũ maikũleete we, ĩndĩ ninyie maleete, nĩ kana ndikethĩwe mũsumbĩ ĩũlũ woo.'),
('kam', '1SA', 8, 8, 'Kwĩanana na mawĩa onthe ala meekie kuma mũthenya ũla namambatisye kũmaumya nthĩ ya Misili o na kũvika mũthenya ũũ, o ũndũ mandiĩte, na makathũkũmaa ngai ingĩ, nĩmeũkwĩka o ta ũu.'),
('kam', '1SA', 8, 9, 'Kwondũ wa ũu ĩndĩ ĩthukĩĩsye wasya woo: ĩndĩ ũkamakũsĩĩe vyũ, na ũkamon’ye mũthemba wa mũsumbĩ ũla wĩmasumbĩka.'),
('kam', '1SA', 8, 10, 'Na Samueli amatavya andũ ala mamũkũlilye mũsumbĩ ndeto syonthe sya Yeova.'),
('kam', '1SA', 8, 11, 'Na amea, Mũsumbĩ ũla wĩmũsumbĩka akeethĩwa ailyĩ ũũ: akoosaa ana menyu, na kũmaia methĩwe make, nũndũ wa makasya make, na kũtw’ĩka andũ make ma ũtũlaa mbalasi; na makasembaa matongoesye makasya make;'),
('kam', '1SA', 8, 12, 'na akamaiaa methĩwe kwake makavuteni ma ngili ngili, na makavuteni ma mĩongo ĩtano mĩongo ĩtano; na akaiaa amwe ma kũĩmaa nthĩ yake, na kũkethaa ngetha yake, na kũtuaa mĩio yake ya kaũ na mĩio ya makasya make.'),
('kam', '1SA', 8, 13, 'Na akoosaa eĩtu menyu methĩawe aseũvya ma manukato, na kwĩthĩawa aui, na kwĩthĩawa aui ma mĩkate.'),
('kam', '1SA', 8, 14, 'Na akoosaa mĩũnda yenyu, na mĩũnda yenyu ya mĩsavivũ, na mĩũnda yenyu ya mĩthata, o na ĩla mĩseo mbee yayo, na aimĩnenga athũkũmi make.'),
('kam', '1SA', 8, 15, 'Na akoosaa kĩlungu kya ĩkũmi kya mbeũ syenyu, na kya mĩũnda yenyu ya mĩsavivũ, na akĩmanenga anene ma kwake, na athũkũmi make.'),
('kam', '1SA', 8, 16, 'Na akoosaa athũkũmi menyu aũme, na athũkũmi menyu eĩtu, na anake menyu ala aseo mbee, na mang’oi menyu, na kũmekĩaa wĩanĩ wake.'),
('kam', '1SA', 8, 17, 'Akoosaa kĩlungu kya ĩkũmi kya ndĩthya syenyu sya mbũi na malondu: na mũkeethĩawa mwĩ athũkũmi make.'),
('kam', '1SA', 8, 18, 'Na mũkakaya mũthenya ũsu nũndũ wa mũsumbĩ wenyu ũla mwĩĩthĩwa mwĩnyuvĩe; na Yeova ndakamũsũngĩa mũthenya ũsu.'),
('kam', '1SA', 8, 19, 'Ĩndĩ andũ malea kwĩthukĩĩsya wasya wa Samueli; na masya, Aiee; ĩndĩ tũitĩa kwĩthĩwa na mũsumbĩ waitũ,'),
('kam', '1SA', 8, 20, 'nĩ kana naitũ tũtonye kwĩthĩwa tũilyĩ ta mbaĩ syonthe, na nĩ kana mũsumbĩ waitũ atonye kũtũsilanasya, na kũendaa mbee waitũ, na kũtũkitĩthasya makaũ.'),
('kam', '1SA', 8, 21, 'Na Samueli eew’a ndeto syonthe sya andũ, nake aineena o ta ũu matũnĩ ma Yeova.'),
('kam', '1SA', 8, 22, 'Na Yeova amwĩa Samueli, Ĩthukĩĩsye wasya woo, na ũimaiĩa mũsumbĩ. Na Samueli amea andũ ma Isilaeli, Endai kĩla mũndũ ndũanĩ kwoo.'),
('kam', '1SA', 9, 1, 'Na ĩndĩ kwaĩ mũndũ wa Mbenyamini, ũla wetawa syĩtwa yake Kisu, mwana wa Avieli, mwana wa Nzeloli, mwana wa Mbekolathi, mwana wa Avia, mwana wa Mũmbenyamini, ngũmbaũ nene.'),
('kam', '1SA', 9, 2, 'Na aĩ na mwana, ũla wetawa syĩtwa yake Saulo, mũndũ wa mũika na mũmbe nesa: na kũtyaĩ katĩ wa ana ma Isilaeli mũndũ mwanake kwĩ we: kuma ituonĩ syake kwambata aĩ mũasa kũte mũndũ o na wĩva.'),
('kam', '1SA', 9, 3, 'Na mang’oi ma Kisu ĩthe wa Saulo maĩ mau. Na Kisu amwĩa Saulo mwana wake, Osa yu ũmwe wa athũkũmi ũthi nake, na ũkĩla, ũthi ũkamanthe mang’oi.'),
('kam', '1SA', 9, 4, 'Na avĩtĩla katĩ wa nthĩ yĩ iĩma ya Evalaimu, na avĩtĩla katĩ wa nthĩ ya Salisa, ĩndĩ matyaamona: nĩvo ĩndĩ mavĩtĩle katĩ wa nthĩ ya Saalimu, na matyaĩ vo: na avĩtĩla katĩ wa nthĩ ya Ambenyamini, ĩndĩ matyaamona.'),
('kam', '1SA', 9, 5, 'Na yĩla mavikie nthĩ ya Nzuve, Saulo amwĩa mũthũkũmi wake ũla waĩ nake, Ũka, tũsyoke, nau ndakese kũeka kũlilikana ũndũ wa mang’oi, na akambĩlĩlya kũũũya ũndũ witũ.'),
('kam', '1SA', 9, 6, 'Na amwĩa, Sisya yu, ndũanĩ ĩno ve mũndũ wa Ngai, na nĩ mũndũ ũla ũtaĩawa; w’onthe ũla ũneenaa ũtw’ĩkaa wa w’o ki: yu nĩtũthi vo; nokwĩthĩwa atonya kũtũtavya ũndũ wa kyalo kĩĩ kitũ tũũthi.'),
('kam', '1SA', 9, 7, 'Na ĩndĩ Saulo amwĩa mũthũkũmi wake, Ĩndĩ, sisya, ethĩwa nĩtũũthi, tũkamũtwaĩa ũ mũndũ kyaũ? Nũndũ kĩmũtũ nĩ kĩthelu mĩionĩ yaitũ, na vati mũthĩnzĩo wa kũmũtwaĩa mũndũ wa Ngai: twĩ na kyaũ ithyĩ?'),
('kam', '1SA', 9, 8, 'Na ũ mũthũkũmi amũsũngĩa Saulo ĩngĩ, na asya, Sisya, nĩ na kĩlungu kya kana kya sekeli ya vetha kw’okonĩ kwakwa: ngamũnenga ũla mũndũ wa Ngai kyo, nĩ kana atwathĩĩe nzĩa yaitũ.'),
('kam', '1SA', 9, 9, '(Ĩvinda ya tene katĩ wa Isilaeli, yĩla mũndũ waendie kũkũlya Ngai, aasya ũũ, Ũka, tũthi kwa mwoni; ũndũ we ũla yu wĩtawa Mwathani ĩvinda ya tene eetawa Mwoni.)'),
('kam', '1SA', 9, 10, 'Nĩvo ĩndĩ Saulo wamwĩie mũthũkũmi wake, Waneena nesa; ũka, tũthi. Kwondũ wa ũu mathi ndũanĩ vala ũ mũndũ wa Ngai waĩ.'),
('kam', '1SA', 9, 11, 'Na yĩla mambatĩte maendete ndũanĩ, moona eĩtu ma mũika makĩthi kũtava kĩw’ũ, na mamakũlya, Mwoni e vaa?'),
('kam', '1SA', 9, 12, 'Namo mamasũngĩa, na masya, E vo; sisyai, e vu mbee wenyu: ĩkalaatei yu, nũndũ ookie ndũanĩ ũmũnthĩ; nũndũ andũ nĩmeũthemba ũmũnthĩ vala vandũ vatũlu.'),
('kam', '1SA', 9, 13, 'O yĩla mũũlika ndũanĩ, oyu mĩtũkĩ nĩmũkũmwona, mbee wa atanambata vala vandũ vatũlu aye; nũndũ andũ matiya mũvaka ooka, nĩkwĩthĩwa nũkũathima nthembo; na ĩtina makĩya ala metĩtwe. Yu ĩndĩ ambatai; nũndũ ĩvinda ta yĩĩ nĩmũkũmwona.'),
('kam', '1SA', 9, 14, 'Na mambata ndũanĩ; na makĩlika ndũanĩ, sisya, Samueli aumaala amelekele, ambate vala vandũ vatũlu.'),
('kam', '1SA', 9, 15, 'Na ĩndĩ Yeova aĩ anamũvuanĩisye Samueli ta ĩoo Saulo atanoka, akĩmwĩa,'),
('kam', '1SA', 9, 16, 'Ũnĩ ta ĩvinda yĩĩ ngatũma mũndũ kwaku kuma nthĩ ya Mbenyamini, na wĩmwĩtĩkĩsya mauta ethĩwe mũnene wĩ mbee ũsumbĩnĩ andũnĩ makwa Isilaeli; na akamatangĩĩa andũ makwa kuma mokonĩ ma Avilisiti: nũndũ nĩnĩsyaĩtye andũ makwa, nĩkwĩthĩwa kĩĩo kyoo nĩkĩmbikĩe.'),
('kam', '1SA', 9, 17, 'Na yĩla Samueli wamwonie Saulo, Yeova amwĩa, Sisya, mũndũ ũla nĩnakũtavisye! Ũũ nĩwe wĩĩthĩwa na ũtonyi ĩũlũ wa andũ makwa.'),
('kam', '1SA', 9, 18, 'Nĩvo ĩndĩ Saulo wamũthengee Samueli mbingĩlonĩ, na amwĩa, Ndavya, nĩngũkwĩsũva, vala nyũmba ya mwoni ĩĩ.'),
('kam', '1SA', 9, 19, 'Na Samueli amũsũngĩa Saulo, na amwĩa, Ninyie mwoni; ambata ũndongoesye kũvika vala vandũ vatũlu, nũndũ mũkaya vamwe nakwa ũmũnthĩ: na kĩoko ngakũeka ũthi, na kũũtavya w’onthe ũla wĩ ngoonĩ yaku.'),
('kam', '1SA', 9, 20, 'Na ũndũ wa mang’oi maku ala manaaie yu nĩ mĩthenya ĩtatũ mĩthelu, ndũkethĩn’ye ũndũ wamo; nũndũ nĩ moneku. Na w’onthe ũla ũkwendwa katĩ wa Isilaeli nĩ ũndũ waũ? Ti ũndũ waku, na ũndũ wa nyũmba yonthe ya ithe waku?'),
('kam', '1SA', 9, 21, 'Na Saulo asũngĩa na asya, Nyie ndi Mũmbenyamini, wa mbaĩ ĩla nini mbee ya Isilaeli? Na mũvĩa wakwa tĩ mũnini mbee wa mĩvĩa yonthe ya mbaa Mbenyamini? Nũndũ wa kĩ ĩndĩ ũũneena nakwa ta ũu?'),
('kam', '1SA', 9, 22, 'Na Samueli oosa Saulo na mũthũkũmi wake, na amalikya nyũmbanĩ ya aeni, na amekalya vandũ va mbee katĩ wa ala meetĩtwe, ala maĩ andũ ta mĩongo ĩtatũ.'),
('kam', '1SA', 9, 23, 'Na Samueli amwĩa mũui, Ete kĩlungu kĩla nĩkũnengie, kĩla ngũtavisye, Ia vala ũĩ.'),
('kam', '1SA', 9, 24, 'Na mũui oosa waswa, na kĩla kyaĩ ĩũlũ waw’o, na aia mbee wa Saulo. Na Samueli amwĩa, Sisya kĩla kĩiĩtwe! Kie mbee waku na ũkĩya; nĩkwĩthĩwa kũvika ĩvinda yĩla yĩĩ ĩtw’ĩtwe nĩkiiwe nũndũ waku, nũndũ naisye, Nĩnĩmetĩte andũ. Kwondũ wa ũu Saulo aĩsanĩa na Samueli mũthenya ũsu.'),
('kam', '1SA', 9, 25, 'Na ĩtina wa matheea kuma vala vandũ vatũlu makĩlika ndũanĩ, aneenanĩsya na Saulo nyũmbanĩ ĩũlũ.'),
('kam', '1SA', 9, 26, 'Na mookĩla tene: na kweethĩwa ta w’oa watema, Samueli amwĩta Saulo nyũmbanĩ ĩũlũ, akĩmwĩa, Ũkĩla, nĩ kana nĩkũeke ũthi. Na Saulo ookĩla, na maumaala me elĩ ũtee, we na Samueli.'),
('kam', '1SA', 9, 27, 'Na makĩtheea mũminũkĩlyonĩ wa ndũa, Samueli amwĩa Saulo, Mwĩe mũthũkũmi avĩte mbee waitũ (na avĩta mbee), ĩndĩ amba kũũngama, nĩ kana nĩkũmanyĩthye ndeto ya Yeova.'),
('kam', '1SA', 10, 1, 'Nĩvo ĩndĩ Samueli wosie sũva wa mauta, na amwĩtĩkĩsya mũtwe wake; na amũmumunya, na asya, Ti kwakwĩthĩwa Yeova nũkwĩtĩkĩsye mauta wĩthĩwe mũnene wĩ mbee ũsumbĩnĩ ũtiĩwanĩ wake?'),
('kam', '1SA', 10, 2, 'Ĩtina wa wauma vaa nĩĩ ũmũnthĩ, nĩvo ĩndĩ ũkũmethĩa andũ elĩ vakuvĩ na vala vathikiwe Lakeli, mũvakanĩ wa Mbenyamini ku Nzelisa; namo makakwĩa, Mang’oi ala waendie kũmantha nĩ moneku; na, sisya, ĩthe waku nũekete kũlilikana ũndũ wa mang’oi, na eũũya ũndũ waku, akyasya, Nĩĩka ata ũndũ wa mwana wakwa?'),
('kam', '1SA', 10, 3, 'Na ĩndĩ ũkaendeea mbee kuma vau, na ũkavika mũtĩnĩ wa mwaloni wĩ Tavoli; na ũkakomanĩa vo na andũ atatũ makyambata kwa Ngai ku Mbethi‐eli, ũmwe atwaĩte tũtena tũtatũ, na ũngĩ atwaĩte imũtũ itatũ, na ũngĩ atwaĩte kathatwa ka mbinyu:'),
('kam', '1SA', 10, 4, 'namo makaũkethya, na kũũnenga imũtũ ilĩ, na wĩosa mokonĩ moo.'),
('kam', '1SA', 10, 5, 'Ĩtina wa ũu ũkavika kĩĩmanĩ kya Ngai, vala ve ngome ya asikalĩ ma Avilisiti: na kũkeethĩwa, yĩla wĩvika vau ndũanĩ, ũkakomana na nguthu ya athani matheeete makyuma vala vandũ vatũlu me na kĩnanda, na kathembe, na mũtũlilũ, na mbeve, mbee woo; namo makeethĩwa makyathana:'),
('kam', '1SA', 10, 6, 'na Veva wa Yeova akooka na vinya mũnene ĩũlũ waku, naku ũkathana vamwe nao, na ũkaalyũlwa wĩthĩwe mũndũ ũngĩ.'),
('kam', '1SA', 10, 7, 'Na kũkethĩwe, yĩla mawonan’yo asu meũkĩtĩkĩa, nĩvo ĩndĩ wĩĩka o ũndũ wĩona wĩ ũseo; nũndũ Ngai e vamwe naku.'),
('kam', '1SA', 10, 8, 'Naku ũkatheee Ngilikali mbee wakwa; na, sisya, ngatheea kũla ũĩ, nĩthembe nthembo sya kũvĩvw’a, na kũthemba nthembo sya mũuo: wĩeteela mĩthenya mũonza, mũvaka nooka vala ũĩ, na kũkwon’ya ũndũ wĩĩka.'),
('kam', '1SA', 10, 9, 'Na kweethĩwa, yĩla wethyũũie aume vala ve Samueli, Ngai amũnenga ngoo ĩngĩ: na mawonan’yo asu onthe makĩtĩka mũthenya ũsu.'),
('kam', '1SA', 10, 10, 'Na yĩla mavikie vau kĩĩmanĩ, sisya, nguthu ya athani yakomana nake; na Veva wa Ngai ooka na vinya mũnene ĩũlũ wake, na athana e namo'),
('kam', '1SA', 10, 11, 'Na kweethĩwa, yĩla onthe ala mamwĩsĩ mbee moonie atĩ, sisya, nĩwathanaa vamwe na athani, nĩvo ĩndĩ andũ maneenanisye ũmwe na ũla ũngĩ, Ũndũ ũũ nĩ mwaũ ũla wamũkĩa mwana wa Kisu? Saulo nake e o katĩ wa athanĩ?'),
('kam', '1SA', 10, 12, 'Na ũmwe wa vandũ vau asũngĩa aikũlya, Na ĩthe woo nũũ? Kwondũ wa ũũ yatw’ĩka nthimo, Saulo nake e o katĩ wa athani?'),
('kam', '1SA', 10, 13, 'Na yĩla maminie kwathana, ooka vala vandũ vatũlu.'),
('kam', '1SA', 10, 14, 'Na mwendw’a‐ĩthe wa Saulo amũkũlya we na mũthũkũmi wake, Mwaendie nakũ? Nake asũngĩa, Kũmantha mang’oi; na yĩla tũneethĩie matineoneka, tũnooka kwa Samueli.'),
('kam', '1SA', 10, 15, 'Na mwendw’a‐ĩthe wa Saulo amwĩa, Ndavya, nĩngũkwĩsũva, ũndũ Samueli ũnamũtavisye.'),
('kam', '1SA', 10, 16, 'Na Saulo amwĩa mwendw’a‐ĩthe, Nĩwatũtavisya vyũ kana mang’oi nĩmanoonekie. Ĩndĩ ũndũ wa ũvoo ũsu wa ũsumbĩ, ũla Samueli waneenie, ndaamũtavya.'),
('kam', '1SA', 10, 17, 'Na Samueli atũmana andũ onthe moke vamwe kwa Yeova ku Misiva;'),
('kam', '1SA', 10, 18, 'na amea ana ma Isilaeli, Ũũ nĩw’o Yeova, Ngai wa Isilaeli, ũnũkwasya, Nĩnambatisye Isilaeli kuma Misili, na namũvonokya inyw’ĩ mokonĩ ma Amisili, na mokonĩ ma mosumbĩ onthe ala mamũthĩnasya:'),
('kam', '1SA', 10, 19, 'ĩndĩ mũthenya ũũ nĩmwamũlea Ngai wenyu, ũla ũmũtangĩĩaa kuma mawanangĩkonĩ menyu onthe manene na mathĩnanĩ menyu; na nĩmũmũtavĩtye, Aiee, ĩndĩ twiĩe mũsumbĩ. Yu ĩndĩ ĩetei ene mbee wa Yeova kũatĩanĩa na mbaĩ syenyu, na kũatĩanĩa na ngili syenyu.'),
('kam', '1SA', 10, 20, 'Na ĩndĩ Samueli athengeesya mbaĩ syonthe sya Isilaeli, na mbaĩ ya Mbenyamini yooswa.'),
('kam', '1SA', 10, 21, 'Na athengeesya mbaĩ ya Mbenyamini kũatĩanĩa na mĩvĩa yoo, na mũvĩa wa Amatili wooswa; na Saulo mwana wa Kisu ooswa: ĩndĩ yĩla mamũmanthie, ndaatonya kwoneka.'),
('kam', '1SA', 10, 22, 'Kwondũ wa ũu mamũkũlya Yeova ĩngĩ, Ve mũndũ ũngĩ wĩũka vaa? Na Yeova asũngĩa, Sisya, nĩwĩvithĩte mĩionĩ.'),
('kam', '1SA', 10, 23, 'Namo masemba na mamũlatya kuma vo; na yĩla waũngamie katĩ wa andũ, aĩ mũasa kwĩ mũndũ o na wĩva kuma ituonĩ syake kwambata.'),
('kam', '1SA', 10, 24, 'Na Samueli amea andũ onthe, Nĩmũmwona ũla Yeova ũnyuvĩte, kana vati ũngĩ ũtilyĩ take katĩ wa andũ onthe? Na andũ onthe mookĩlya wasya, makyasya, Mũsumbĩ nĩekale thayũ ĩvinda ĩasa.'),
('kam', '1SA', 10, 25, 'Nĩvo ĩndĩ Samueli wamatavisye andũ mũthemba wa ũsumbĩ, na ooandĩka ĩvukunĩ, na ayia mbee wa Yeova. Na Samueli amombũũkya andũ onthe, kĩla mũndũ aende nyũmba kwake.'),
('kam', '1SA', 10, 26, 'Na Saulo nake athi nyũmba kwake ku Ngivea; na vaenda vamwe nake nguthu, ala ngoo syoo Ngai wakiitĩte.'),
('kam', '1SA', 10, 27, 'Ĩndĩ andũ amwe mate kĩĩĩ makũlya, Mũndũ ũũ akatũtangĩĩa ata? Namo mamũvũthya, na matyaamũetee mũthĩnzĩo. Ĩndĩ we akilya.'),
('kam', '1SA', 11, 1, 'Nĩvo ĩndĩ Naasu Mũamimoni wambatie, na amba maeema amĩtaũĩĩe Yavesi‐ngileati: na andũ onthe ma Yavesi mamwĩa Naasu Mũamimoni, Tianĩa ũtianĩo naitũ, naitũ tũkaũthũkũma.'),
('kam', '1SA', 11, 2, 'Na Naasu Mũamimoni amea, Ngootianĩa nenyu kwondũ wa ũndũ ũũ, atĩ metho menyu onthe ma ngalĩ ya kw’oko kwa aũme mavũthũangwe; na ngawia ũndũ ũũ wĩthĩwe kĩvũthya kwa Isilaeli onthe.'),
('kam', '1SA', 11, 3, 'Na atumĩa ma Yavesi mamwĩa, Tũnenge ũthei wa mĩthenya mũonza, nĩ kana tũtonye kũtũma atũmwa kũvika mĩvakanĩ yonthe ya Isilaeli; na ĩndĩ, ethĩwa vaiĩthĩwa ũmwe wa ũtũtangĩĩa, tũkaumaala kũla ũĩ.'),
('kam', '1SA', 11, 4, 'Nĩvo ĩndĩ atũmwa mavikie ku Ngivea ya Saulo, na maneena ndeto isu matũnĩ ma andũ: na andũ onthe mookĩlya wasya woo, na maĩa.'),
('kam', '1SA', 11, 5, 'Na, sisya, Saulo ooka aatĩĩe ng’ombe kuma mũũndanĩ; na Saulo akũlya, Andũ me na ũndũ mwaũ ũũtuma maĩa? Na mamũtavya ndeto sya andũ ma Yavesi.'),
('kam', '1SA', 11, 6, 'Na Veva wa Ngai ooka na vinya mũnene ĩũlũ wa Saulo yĩla wewie ndeto isu, na ũthatu wake wakana mũno.'),
('kam', '1SA', 11, 7, 'Na oosa kyove kya ng’ombe, na aitilanga ilungu, na aitwaa mĩvakanĩ yonthe ya Isilaeli na moko ma atũmwa, akyasya, O ũla ũteuma amũatĩĩe Saulo na Samueli, ng’ombe syake ikeekwa ũu. Na kũmũkĩa Yeova kũnene kwamavalũkĩla andũ, na makuthũka ta mũndũ ũmwe.'),
('kam', '1SA', 11, 8, 'Na amatalĩla Mbeseki; na ana ma Isilaeli maĩ ngili maana atatũ, na andũ ma Yuta maĩ ngili mĩongo ĩtatũ.'),
('kam', '1SA', 11, 9, 'Na mamea atũmwa ala mookie, Ũũ nĩw’o mwĩmatavya andũ ma Yavesi‐ngileati, Ũnĩ, ĩvinda ya syũa kũvyũva, mũkeethĩwa na ũvonoko. Na atũmwa mathi na mamatavya andũ ma Yavesi; namo matana.'),
('kam', '1SA', 11, 10, 'Kwondũ wa ũu andũ ma Yavesi masya, Ũnĩ tũkaumaala kũla mũĩ, na mũkeeka naitũ w’onthe ũla mũkwona wĩ ũseo.'),
('kam', '1SA', 11, 11, 'Na kweethĩwa ũnĩ, Saulo aia andũ nguthu itatũ; namo malika mwakonĩ wa maeema katĩ ũsyaĩĩsyonĩ wa kĩoko, na mamakũna Amimoni kũvika mũthenya kwavyũva: na kweethĩwa, ala matialile manyaĩĩkw’a, kũvika elĩ moo matyaaĩthĩwa vamwe.'),
('kam', '1SA', 11, 12, 'Na andũ mamũkũlya Samueli, Nũũ ũla ũnakũlilye, Saulo akatũsumbĩka? Ete andũ asu, kana tũmoae.'),
('kam', '1SA', 11, 13, 'Na Saulo asya, Vati mũndũ wĩũawa mũthenya ũũ; nũndũ ũmũnthĩ Yeova nĩwatethya wĩa wa ũvonokyo nthĩnĩ wa Isilaeli.'),
('kam', '1SA', 11, 14, 'Nĩvo ĩndĩ Samueli wameie andũ, Ũkai, tũthi Ngilikali, na tũkĩlũlũmĩĩlya ũsumbĩ vo.'),
('kam', '1SA', 11, 15, 'Na andũ onthe mathi Ngilikali; na vau Ngilikali matw’ĩkĩthĩsya Saulo mũsumbĩ Yeova ene; na vau mathemba nthembo sya mũuo mbee wa Yeova; na vau Saulo na andũ onthe ma Isilaeli matana mũno.'),
('kam', '1SA', 12, 1, 'Na Samueli amea Isilaeli onthe, Sisyai, nĩnĩthukĩĩĩtye wasya wenyu nthĩnĩ wa w’onthe ũla mũnandavisye, na nĩnĩmũsumbĩkĩsye mũsumbĩ.'),
('kam', '1SA', 12, 2, 'Na yu, sisyai, mũsumbĩ ethi mbee wenyu; nakwa nĩ mũkũu na mũtwe wĩ mbuĩ; na, sisyai, ana makwa me vamwe nenyu: na nĩnaendaa mbee wenyu kuma wana wakwa kũvika ũmũnthĩ.'),
('kam', '1SA', 12, 3, 'Nyie nĩ vaa: kũsĩĩai ĩũlũ wakwa Yeova ene, na mwĩtĩkĩw’a mauta wake ene: nosie ng’ombe yaũ? Kana nosie ĩng’oi yaũ? Kana navutie ũũ? Nathĩnisye ũũ? Kana nĩ kw’okonĩ kwaũ kũla noosie ĩvaki nĩlindwe metho makwa nĩyo? Na nĩngũmũtũngĩa inyw’ĩ.'),
('kam', '1SA', 12, 4, 'Nao mamũsũngĩa, Ndwaatũvuta, kana kũtũthĩn’ya, o na ndwaaosa o na kĩ kw’okonĩ kwa mũndũ o na wĩva.'),
('kam', '1SA', 12, 5, 'Nake amea, Yeova nĩ ngũsĩ ĩũlũ wenyu, na mwĩtĩkĩw’a mauta wake nĩ ngũsĩ mũnthĩ ũũ, kana mũinona kĩndũ kw’okonĩ kwakwa. Namo masya, Nĩwe ngũsĩ.'),
('kam', '1SA', 12, 6, 'Na Samueli amea andũ, Nĩ Yeova ũla waiie Mose na Aluni, na ũla wamaetie aaĩthe menyu kuma nthĩ ya Misili.'),
('kam', '1SA', 12, 7, 'Yu ĩndĩ kwondũ wa ũu ũngamai, kana nĩneenan’ye nenyu Yeova ene ũndũ wa meko onthe malũngalu ma Yeova, ala wekie kwenyu na kwa aaĩthe menyu.'),
('kam', '1SA', 12, 8, 'Ĩtina wa Yakovo alika Misili, na aaĩthe menyu mamwĩkaĩla Yeova, nĩvo ĩndĩ Yeova watũmie Mose na Aluni, ala mamaumisye aaĩthe menyu Misili, na amatũsya vandũ vaa.'),
('kam', '1SA', 12, 9, 'Ĩndĩ moolwa nĩ Yeova Ngai woo; na amathoosya kw’okonĩ kwa Sisela, kavuteni wa nguthu ya Asoli, na mokonĩ ma Avilisiti, na kw’okonĩ kwa mũsumbĩ wa Moavi; na mokita namo.'),
('kam', '1SA', 12, 10, 'Na mamwĩkaĩla Yeova, na masya, Nĩtũvĩtĩtye, nĩkwĩthĩwa nĩtũmũtiĩte Yeova, na nĩtũthũkũmĩte Mbaalimu na Asetalothi: ĩndĩ yu tũvonokye kuma mokonĩ ma amaitha maitũ, na tũkaũthũkũma.'),
('kam', '1SA', 12, 11, 'Na Yeova amũtũma Yelumbaali, na Mbetani, na Yevitha, na Samueli, na amũvonokya kuma mokonĩ ma amaitha menyu kĩla ngalĩko; na mwatũa mũte mũisyo.'),
('kam', '1SA', 12, 12, 'Na yĩla mwoonie kana Naasu mũsumbĩ wa ana ma Amimoni nĩwamũkĩe okite nenyu, nĩmwambĩie, Aiee, ĩndĩ mũsumbĩ akatũsumbĩka; yĩla Yeova Ngai wenyu waĩ mũsumbĩ wenyu.'),
('kam', '1SA', 12, 13, 'Yu ĩndĩ mũsisyei mũsumbĩ ũla mũnyuvĩte, na ũla mwĩtĩtye: na, sisyai, Yeova nũmũsumbĩkĩsye mũsumbĩ.'),
('kam', '1SA', 12, 14, 'Ethĩwa mũkakĩaa Yeova, na kũmũthũkũmaa, na kwĩthukĩĩasya wasya wake, na kũleaa kũng’endea mwĩao wa Yeova, na inyw’ĩ o na mũsumbĩ ũla ũnũũmũsumbĩka mũkethĩawa aatĩĩi ma Yeova Ngai wenyu, nĩ ũseo:'),
('kam', '1SA', 12, 15, 'ĩndĩ ethĩwa mũtikwĩtĩkĩla kwĩthukĩĩasya wasya wa Yeova, ĩndĩ kũng’endeaa mwĩao wa Yeova, nĩvo ĩndĩ kw’oko kwa Yeova kwĩĩthĩwa ĩũlũ wenyu, o tondũ kweethĩawa ĩũlũ wa aaĩthe menyu.'),
('kam', '1SA', 12, 16, 'Yu ĩndĩ ũngamai mwone ũndũ ũũ ũnene, ũla Yeova ũnũkwĩka metho menyu mene.'),
('kam', '1SA', 12, 17, 'Ti ĩketha ya nganũ ũmũnthĩ? Nĩngwĩkaĩla Yeova, nĩ kana aete kĩtundumo na mbua; nenyu mũkamanya na kwona kana ũthũku wenyu nĩ mũnene, ũla mwĩkĩte Yeova ene, mũkĩyĩtĩsya mũsumbĩ.'),
('kam', '1SA', 12, 18, 'Na ĩndĩ Samueli eekaĩla Yeova; na Yeova aete kĩtundumo na mbua mũthenya ũsu; na andũ onthe mamũkĩa Yeova mũno na Samueli.'),
('kam', '1SA', 12, 19, 'Na andũ onthe mamwĩa Samueli, Voyea athũkũmi maku kwa Yeova Ngai waku, nĩ kana tũikakw’e; nũndũ nĩtwongelete naĩnĩ sitũ syonthe ũthũku ũũ, kwĩyĩtĩsya mũsumbĩ.'),
('kam', '1SA', 12, 20, 'Na Samueli amea andũ, Mũikakĩe: nĩ w’o, nĩmwĩkĩte ũthũku ũũ w’onthe; ĩndĩ mũtikathũke ũtee na kũlea kũmũatĩĩa Yeova, ĩndĩ mũthũkũmei Yeova na ngoo syenyu syonthe:'),
('kam', '1SA', 12, 21, 'na mũtikathũke ũtee; nũndũ mwathũka, nĩvo ĩndĩ mwĩatĩĩa maũndũ ma mana ala matatonya kũuna kana kũvonokya, nũndũ nĩ ma mana.'),
('kam', '1SA', 12, 22, 'Nũndũ Yeova ndakamatia andũ make nũndũ wa syĩtwa yake ĩnene, nĩkwĩthĩwa nĩkũmwendeesye Yeova kũmũtw’a inyw’ĩ ũko wa andũ kwake mwene.'),
('kam', '1SA', 12, 23, 'Na ĩngĩ a vakwa nyie, kwĩthĩwe kũasa nakwa kũmũvĩtanĩsya Yeova ũndũ wa kũeka kũmũvoyea: ĩndĩ ngamũmanyĩsya mũendele mũseo na mũlũngalu.'),
('kam', '1SA', 12, 24, 'No mũkĩei Yeova, na mũkĩmũthũkũma nthĩnĩ wa w’o na ngoo syenyu syonthe; nũndũ sũanĩai ũndũ mawĩa manenevete ala wekie nũndũ wenyu.'),
('kam', '1SA', 12, 25, 'Ĩndĩ ethĩwa mũkaendeea kwĩkaa ũthũku, mũkanangwa, inyw’ĩ o na mũsumbĩ wenyu.'),
('kam', '1SA', 13, 1, 'Saulo aĩ wa myaka mĩongo ĩna yĩla wambĩlĩlye kũsumbĩka; na yĩla wasumbĩkĩte Isilaeli myaka ĩlĩ,'),
('kam', '1SA', 13, 2, 'Saulo eenyuvĩa andũ ngili itatũ ma Isilaeli, ala ngili ilĩ maĩ vamwe na Saulo ku Mikimasi na kĩĩmanĩ kya Mbethi‐eli, na ngili yaĩ vamwe na Yonathani ku Ngivea ya Mbenyamini: na andũ ala angĩ amenũkya kĩla mũndũ ĩeemanĩ yake.'),
('kam', '1SA', 13, 3, 'Na Yonathani akũna ngome ya asikalĩ ma Avilisiti ĩla yaĩ Ngeva; na Avilisiti meew’a ũu. Na Saulo avuva soo watũngana nthĩ yonthe, akyasya, Aevelania nĩmew’e.'),
('kam', '1SA', 13, 4, 'Na Isilaeli onthe meew’a kana Saulo nũkũnie ngome ya asikalĩ ma Avilisiti, o na kana Isilaeli matw’ĩkĩte kĩla kĩthatasya kwa Avilisiti. Na andũ moombana maatĩĩe Saulo ku Ngilikali.'),
('kam', '1SA', 13, 5, 'Na Avilisiti moombana mokite na Isilaeli, makasya ma kaũ ngili mĩongo ĩtatũ, na ala matũlaa mbalasi ngili thanthatũ, na andũ ta kĩthangathĩ kĩla kĩ ũtee wa ũkanga ũndũ wa kwingĩva: na mambata, na mamba maeema Mikimasi, ngalĩ ya wumĩlonĩ wa syũa ya Mbethi‐aveni.'),
('kam', '1SA', 13, 6, 'Yĩla andũ ma Isilaeli moonie kana maĩ avivinye (nũndũ andũ maĩ athĩnu), nĩvo ĩndĩ andũ meevithie ngunganĩ, na ikuthunĩ, na mavianĩ, na mawĩvithonĩ, na maimanĩ.'),
('kam', '1SA', 13, 7, 'Na ĩndĩ amwe ma Aevelania nĩmaingĩte Yolotani kũvika nthĩ ya Ngati na Ngileati; ĩndĩ ũndũ wa Saulo, we aĩ o Ngilikali, na andũ onthe mamũatĩĩa maitetema.'),
('kam', '1SA', 13, 8, 'Nake ekala mĩthenya mũonza, kwĩanana na ĩvinda yatw’ĩtwe yĩla Samueli waiĩte: ĩndĩ Samueli ndaaũka Ngilikali; na andũ maĩ anyaĩĩku kuma vala ũĩ.'),
('kam', '1SA', 13, 9, 'Na Saulo asya, Ndeteei vaa nthembo ya kũvĩvw’a, na nthembo sya mũuo. Na athemba nthembo ya kũvĩvw’a.'),
('kam', '1SA', 13, 10, 'Na kweethĩwa, o yĩla waminũkĩlye kũthemba nthembo ya kũvĩvw’a, sisya, Samueli ooka; na Saulo aumaala amũthaũe, nĩ kana amũkethye.'),
('kam', '1SA', 13, 11, 'Na Samueli amũkũlya, Weka ata? Na Saulo asũngĩa, Nĩkwĩthĩwa nĩnonie andũ nĩ anyaĩĩku kuma vaa nĩĩ, o naku ndũneũka mĩthenyanĩ ĩla mĩtw’e, na Avilisiti nĩmombanĩe ku Mikimasi;'),
('kam', '1SA', 13, 12, 'kwondũ wa ũu nasya, Yu Avilisiti nĩmekũntheeea kũvika Ngilikali, nakwa ndinamba kwĩsũvana kwa Yeova: kwondũ wa ũu nĩnĩingĩĩsye mwene, na nathemba nthembo ya kũvĩvw’a.'),
('kam', '1SA', 13, 13, 'Na Samueli amwĩa Saulo, Nĩwĩkie ũtumanu; ndũnasũvĩa mwĩao wa Yeova Ngai waku, ũla ũnakwĩaĩe: nũndũ yu Yeova ethĩwa alũlũmĩlya ũsumbĩ waku kwa Isilaeli tene na tene.'),
('kam', '1SA', 13, 14, 'Ĩndĩ yu ũsumbĩ waku ndũkaendeea: Yeova nĩwĩmanthĩe mũndũ wendeeasya ngoo yake mwene, na Yeova nũmwiĩte ethĩwe mũnene wĩ mbee ũsumbĩnĩ wa andũ make, nĩkwĩthĩwa ndũneesũvĩa ũla Yeova ũnakwĩaĩe.'),
('kam', '1SA', 13, 15, 'Na Samueli ookĩla, na ambata kuma Ngilikali kũvika Ngivea ya Mbenyamini. Na Saulo atala andũ ala maĩ vo vamwe nake, andũ ta maana thanthatũ.'),
('kam', '1SA', 13, 16, 'Na Saulo na Yonathani mwana wake, na andũ ala maĩ vo vamwe nao, mekala Ngivea ya Mbenyamini: ĩndĩ Avilisiti mamba maeema Mikimasi.'),
('kam', '1SA', 13, 17, 'Na anangi mooka kuma mwakonĩ wa maeema wa Avilisiti nguthu itatũ: nguthu ĩmwe yeelelũka na nzĩa ĩla ĩvikĩte Ovala, kũvika nthĩ ya Suali;'),
('kam', '1SA', 13, 18, 'na nguthu ĩngĩ yeelelũka na nzĩa ya Mbethi‐oloni; na nguthu ĩngĩ yeelelũka na nzĩa ya mũvaka ũla ũsyaĩtye ĩtheo kyandanĩ kya Nzevoimu kwelekela weũnĩ.'),
('kam', '1SA', 13, 19, 'Na ĩndĩ kũtyaĩ mũtwii wonekaa nthĩ yonthe ya Isilaeli; nũndũ Avilisiti maasya, Nĩ kana Aevalania matikese kwĩtuĩa mbyũ kana matumo:'),
('kam', '1SA', 13, 20, 'ĩndĩ Aisilaeli onthe matheeaa kwa Avilisiti, nĩ kana kĩla mũndũ atusye ĩembe yake ya ng’ombe, na mũthya wa ĩembe yake ya ng’ombe, na ĩthoka yake, na mũsuululu wake;'),
('kam', '1SA', 13, 21, 'ĩndĩ maĩ na tũva nũndũ wa mĩsuululu, na nũndũ wa mĩthya ya maembe ma ng’ombe, na nũndũ wa maũma ma kũĩma, na nũndũ wa mathoka, na kũseũvya mĩsenge.'),
('kam', '1SA', 13, 22, 'Kwondũ wa ũu kweethĩiwe mũthenya wa kaũ, kana kũtyaĩ ũvyũ kana ĩtumo yaaoneka kw’okonĩ kwa mũndũ o na wĩva wa ala maĩ vamwe na Saulo na Yonathani: ĩndĩ nĩsyoonekie na Saulo na Yonathani mwana wake.'),
('kam', '1SA', 13, 23, 'Na asikalĩ ma ngome ya Avilisiti maumaala mathi mwanyanĩ wa Mikimasi.'),
('kam', '1SA', 14, 1, 'Na yu kweethĩwa mũthenya ũmwe, Yonathani mwana wa Saulo amwĩa mwanake ũla wamũkuĩaa mĩio yake ya kaũ, Ũka, tũinge kũla kwĩ asikalĩ ma ngome ya Avilisiti, ala me mũingo ũya. Ĩndĩ ndaamũtavya ĩthe wake.'),
('kam', '1SA', 14, 2, 'Na Saulo ekalĩte ngalĩ ya mũminũkĩlyo ya Ngivea, ĩtina wa mũkũngũmanga ũla wĩ Mikiloni: na andũ ala maĩ vamwe nake maĩ ta andũ maana thanthatũ;'),
('kam', '1SA', 14, 3, 'na Aiya, mwana wa Aituvu, mwana‐a‐inyia wa Ikavotu, mwana wa Vineasi, mwana wa Eli, mũthembi wa Yeova wa ku Silo, ekĩĩte evoti. Na andũ matyaamanya kana Yonathani nũendete.'),
('kam', '1SA', 14, 4, 'Na katĩ wa myanya, ĩla Yonathani wamanthaa kũvĩtĩla kũvikĩa asikalĩ ma ngome ya Avilisiti, ngalĩko ĩmwe kwaĩ ĩvia yũĩ, na ngalĩko ĩla ĩngĩ ĩvia yũĩ: na syĩtwa ya yĩmwe yeetawa Mbosesi, na syĩtwa ya yĩla yĩngĩ Sene.'),
('kam', '1SA', 14, 5, 'Ĩvia yĩmwe yũĩ yaũngamĩte ngalĩ ya ĩũlũ mbee wa Mikimasi, na yĩla yĩngĩ ngalĩ ya ĩtheo mbee wa Ngeva.'),
('kam', '1SA', 14, 6, 'Na Yonathani amwĩa mwanake ũla wakuaa mĩio yake ya kaũ, Ũka, tũinge kũla kwĩ asikalĩ ma ngome ya aa mate aĩke: nokwĩthĩwa Yeova etethya wĩa nũndũ witũ; nũndũ vati kĩsiĩĩi kwa Yeova kũtangĩĩa na aingĩ kana na avũthũ.'),
('kam', '1SA', 14, 7, 'Na mũkui wa mĩio yake ya kaũ amwĩa, Ĩka w’onthe ũla wĩ ngoonĩ yaku: elelũka, sisya, nyie nĩ vamwe naku kwĩanana na ngoo yaku.'),
('kam', '1SA', 14, 8, 'Nĩvo ĩndĩ Yonathani waisye, Sisya, nĩtũkũvĩta mũingo ku kwĩ andũ, na tũkeeyumbũa kwamo.'),
('kam', '1SA', 14, 9, 'Ethĩwa makatwĩa atĩĩ, Ĩkalai mũvaka tũke kũu mũĩ; ithyĩ ĩndĩ tũkaũngama vandũ vaitũ, na tũtiambata kũla maĩ.'),
('kam', '1SA', 14, 10, 'Ĩndĩ ethĩwa makasya atĩĩ, Ambatai kũũ tũĩ; tũkambata ĩndĩ, nũndũ Yeova nũmanenganĩte mokonĩ maitũ: na ũu nĩw’o wĩĩthĩwa wonan’yo kwitũ.'),
('kam', '1SA', 14, 11, 'Namo elĩ meeyumbũa kwa asikalĩ ma ngome ya Avilisiti: na Avilisiti masya, Sisyai, Aevelania nĩmekuma maimanĩ kũla meevithĩte.'),
('kam', '1SA', 14, 12, 'Na andũ ma ngomenĩ masũngĩa Yonathani na mũkui wa mĩio yake ya kaũ, na mamea, Ambatai kũũ tũĩ, na nĩtũũmwon’ya ũndũ. Na Yonathani amwĩa mũkui wa mĩio yake ya kaũ, Ambata ũngatĩĩe; nũndũ Yeova nũmanenganĩte mokonĩ ma Isilaeli.'),
('kam', '1SA', 14, 13, 'Na Yonathani alĩsa na moko na maũũ, na mũkui wa mĩio yake ya kaũ e ĩtina wake: na mavalũkangw’a nĩ Yonathani; na mũkui wa mĩio yake ya kaũ amoaĩĩa e ĩtina wake.'),
('kam', '1SA', 14, 14, 'Na yũaa yĩu ya mbee, yĩla yeekiwe nĩ Yonathani na mũkui wa mĩio yake ya kaũ, yaĩ ta andũ mĩongo ĩlĩ, na kĩlungunĩ kya nthĩ kya nyunzu ya matambya mĩongo mũonza kĩla kĩtonya kwĩnzwa nĩ kyove kya ng’ombe.'),
('kam', '1SA', 14, 15, 'Na kwaĩ kĩtetemo mwakonĩ wa maeema, na kĩsesinĩ, na katĩ wa andũ onthe; asikalĩ ma ngomenĩ, na anangi, o namo nĩmatetemie; o na nthĩ yatetema: o ta ũu kwaĩ kĩtetemo kĩnene mũno.'),
('kam', '1SA', 14, 16, 'Na asyaĩĩsya ma Saulo ku Ngivea ya Mbenyamini masisya; na, sisya, ĩla nguthu nĩnĩũnyaĩĩka, nayo yaenda kũũ na kũũ.'),
('kam', '1SA', 14, 17, 'Nĩvo ĩndĩ Saulo wameie andũ ala maĩ vamwe nake, Talai yu, mwone ũla wumie vala tũĩ. Na yĩla matalile, sisya, Yonathani na mũkui wa mĩio yake ya kaũ matyaĩ vo.'),
('kam', '1SA', 14, 18, 'Na Saulo amwĩa Aiya, Ete ĩsandũkũ ya Ngai vaa. Nũndũ ĩsandũkũ ya Ngai yaĩ vo ĩvinda yĩu vamwe na ana ma Isilaeli.'),
('kam', '1SA', 14, 19, 'Na kweethĩwa, yĩla Saulo waneenaa na mũthembi, kĩtuu kĩla kyaĩ mwakonĩ wa maeema wa Avilisiti kyaendeea na kwingĩva: na Saulo amwĩa mũthembi, Tũnga kw’oko kwaku.'),
('kam', '1SA', 14, 20, 'Na Saulo na andũ onthe ala maĩ nake nĩmoombanĩte vamwe, na mavika kaũnĩ: sisya, ũvyũ wa kĩla mũndũ waĩ ĩũlũ wa mũtindan’ya wake, na kwaĩ kũthokoanw’a kũnene mũno.'),
('kam', '1SA', 14, 21, 'Na ĩndĩ Aevelania ala maĩ na Avilisiti tene, ala mambatanisye namo kũvika mwakonĩ wa maeema, kuma nthĩ ĩla ĩthyũlũlũkĩte, o namo maalyũka methĩwe vamwe na Aisilaeli ala maĩ na Saulo na Yonathani.'),
('kam', '1SA', 14, 22, 'O ta ũu andũ onthe ma Isilaeli ala meevithĩte nthĩ yĩ iĩma ya Evalaimu, yĩla meewie kana Avilisiti nĩmakĩie, o namo mamavikĩla mamaatĩĩe mũno mokite.'),
('kam', '1SA', 14, 23, 'Ũu nĩw’o Yeova watangĩĩe Isilaeli mũthenya ũsu: na kaũ waendeea wavĩtĩla Mbethi‐aveni.'),
('kam', '1SA', 14, 24, 'Na andũ ma Isilaeli mathĩna mũno mũthenya ũsu; nũndũ Saulo aĩ anamaavĩthya andũ na kĩavo, akyasya, Naumanĩwe mũndũ ũla wĩya kya ũya o na kĩva kũvika wĩoo, na kũvika neeĩvanĩsya kwa amaitha makwa. Kwondũ wa ũu vati ũmwe waasama lĩu.'),
('kam', '1SA', 14, 25, 'Na andũ onthe malika mũtitũnĩ; na vau vaĩ ũkĩ wa nzũkĩ ĩũlũ wa nthĩ.'),
('kam', '1SA', 14, 26, 'Na yĩla andũ malikile mũtitũnĩ, sisya, ũkĩ nĩwavolotangaa: ĩndĩ vati mũndũ waaĩkĩa kw’oko kanyw’anĩ kwake; nũndũ andũ nĩmakĩaa wĩvĩto.'),
('kam', '1SA', 14, 27, 'Ĩndĩ Yonathani ndaaĩw’a yĩla ĩthe weaĩe andũ na wĩvĩto: kwondũ wa ũu atwaa mũthya wa ndata ĩla yaĩ kw’okonĩ kwake, na amĩlikya ĩwanĩ, na aete kw’oko kwake kanyw’a; na metho make masalukya.'),
('kam', '1SA', 14, 28, 'Ĩndĩ ũmwe wa andũ asũngĩa, na amwĩa, Ĩthe waku nũmeaĩe andũ na wĩvĩto ki, akyasya, Naumanĩwe mũndũ ũla wĩya kya ũya ũmũnthĩ. Na andũ maĩ anyalu.'),
('kam', '1SA', 14, 29, 'Nĩvo ĩndĩ Yonathani waisye, Asa wakwa nũmĩthĩnĩtye nthĩ: sisya, nĩngũmwĩsũva, ũndũ metho makwa masalukya nĩkwĩthĩwa nĩnasama kanini ka ũkĩ wa nzũkĩ ũũ.'),
('kam', '1SA', 14, 30, 'Nĩ mbee veana ata, kethĩwa andũ nĩmaĩe ũndũ mekwenda ũmũnthĩ sya mũtavo wa amaitha moo ila monie? Nũndũ yu vainethĩwa kũawa kũnene kwa Avilisiti.'),
('kam', '1SA', 14, 31, 'Na mamakũna Avilisiti mũthenya ũsu kuma Mikimasi kũvika Aiyaloni. Na andũ maĩ anyalu mũno;'),
('kam', '1SA', 14, 32, 'na andũ mathanyũkĩa mũtavo, na moosa malondu, na ng’ombe, na tũsaũ, na masyũaĩa mũthanganĩ; na andũ maiĩsanĩsya na nthakame.'),
('kam', '1SA', 14, 33, 'Nĩvo ĩndĩ mamũtavisye Saulo, makyasya, Sisya, andũ nĩmamũvĩtanĩsya Yeova, nũndũ nĩmekũĩsanĩsya nyama na nthakame. Nake asya, Inyw’ĩ nĩmũvĩtĩtye mĩao: vingilityai ĩvia ĩnene yũke vaa nĩĩ mũthenya ũũ.'),
('kam', '1SA', 14, 34, 'Na Saulo asya, Nyaĩĩkaĩ andũnĩ, na mũkĩmea, Ndeteei vaa kĩla mũndũ ng’ombe yake, na kĩla mũndũ ĩlondu yake, na syũaĩe vaa, na mũkĩya; na mũikavĩtanĩsye Yeova nũndũ wa kũĩsanĩsya na nthakame. Na andũ onthe maete kĩla mũndũ ng’ombe yake ũtukũ ũsũ, na masyũaĩa vo.'),
('kam', '1SA', 14, 35, 'Na Saulo amwakĩa Yeova kĩthembeo: nakyo kyaĩ kĩthembeo kya mbee kĩla wamwakĩe Yeova.'),
('kam', '1SA', 14, 36, 'Na Saulo asya, Nĩtũtheeei tũmaatĩĩe Avilisiti na ũtukũ, tũtave mũtavo katĩ wamo kũvika kĩoko kũikya, na tũikatialye mũndũ wamo. Nao masya, Ĩka o ũndũ ũkwona wĩ ũseo. Nĩvo ĩndĩ mũthembi waisye, Tũthengeeei vaa vakuvĩ na Ngai.'),
('kam', '1SA', 14, 37, 'Na Saulo akũlya Ngai ũtao, Nĩngũtheea nĩmaatĩĩe Avilisiti? Ũkamanengane mokonĩ ma Isilaeli? Ĩndĩ ndaamũsũngĩa mũthenya ũsu.'),
('kam', '1SA', 14, 38, 'Na Saulo asya, Thengeeai vaa vakuvĩ, inyw’ĩ anene onthe ma andũ; na mũmanye na kwona vala naĩ ĩno yĩthĩĩtwe mũthenya ũũ.'),
('kam', '1SA', 14, 39, 'Nũndũ, o tondũ Yeova wĩ thayũ, ũla ũtangĩĩaa Isilaeli, o na ethĩwa yĩĩthĩwa na Yonathani mwana wakwa, ndatĩa kũkw’a. Ĩndĩ vayaĩ mũndũ katĩ wa andũ onthe ũla waamũsũngĩa.'),
('kam', '1SA', 14, 40, 'Nĩvo ĩndĩ watavisye Isilaeli onthe, Ĩthĩwai ngalĩ ĩmwe, nakwa na Yonathani mwana wakwa tũkeethĩwa ngalĩ ĩla ĩngĩ. Na andũ onthe mamwĩa Saulo, Ĩka o ũla ũkwona wĩ ũseo.'),
('kam', '1SA', 14, 41, 'Kwondũ wa ũu Saulo amwĩa Yeova, Ngai wa Isilaeli, Onan’ya ũla w’o. Na Yonathani na Saulo makwatwa nĩ kula; ĩndĩ andũ mavonoka.'),
('kam', '1SA', 14, 42, 'Na Saulo asya, Tũlimei nyie na Yonathani mwana wakwa. Na Yonathani akwatwa.'),
('kam', '1SA', 14, 43, 'Nĩvo ĩndĩ Saulo wamwĩie Yonathani, Ndavya ũndũ wĩkie. Na Yonathani amũtavya, na asya, Nĩ w’o, nyie nĩnĩsamie kalũkĩ kanini ka nzũkĩ ke mũthyanĩ wa ndata ĩla yĩĩ kw’okonĩ kwakwa; na, sisya, no mũvaka nĩkw’e.'),
('kam', '1SA', 14, 44, 'Na Saulo asya, Ngai eke ũu o na mbee; nũndũ nũũkw’a vate ndĩi we Yonathani.'),
('kam', '1SA', 14, 45, 'Na andũ mamũkũlya Saulo, Yonathani nũkũkw’a, ũla wĩkie ũtangĩĩo ũũ mũnene nthĩnĩ wa Isilaeli? Ũũ wĩthĩwe kũasa: o tondũ Yeova wĩ thayũ, vati ũsw’ĩĩ ũmwe wa mũtwe wake wĩvalũka nthĩ; nũndũ nũtethisye vamwe na Ngai ũmũnthĩ. Ũu nĩw’o andũ mamũvonokisye Yonathani, ndakakw’e.'),
('kam', '1SA', 14, 46, 'Na ĩndĩ Saulo ambata aeka kũmaatĩĩa Avilisiti; na Avilisiti mathi kwoo.'),
('kam', '1SA', 14, 47, 'Na ĩndĩ yĩla Saulo wasumbĩkĩte Isilaeli, nĩwokitaa na amaitha make onthe kĩla ngalĩko, Moavi, na ana ma Amimoni, na Etomu, na asumbĩ ma Sova, na Avilisiti: na o vala wethyũũie, nĩwamakũaa.'),
('kam', '1SA', 14, 48, 'Nake eekie na ũkũmbaũ, na amakũna Aameleki, na avonokya Isilaeli kuma mokonĩ ma ala mamanangaa.'),
('kam', '1SA', 14, 49, 'Na yu ana ma Saulo maĩ Yonathani, na Isivi, na Maliki‐sua; na masyĩtwa ma eĩtu make elĩ nĩmo aa; syĩtwa ya ũla wa mbee eetawa Melavu, na syĩtwa ya ũla wa kelĩ eetawa Mikali:'),
('kam', '1SA', 14, 50, 'na syĩtwa ya mũka wa Saulo eetawa Ainoamu mwĩĩtu wa Aimaasi. Na syĩtwa ya kavuteni wa nguthu yake eetawa Avineli mwana wa Neli, mwendw’a‐ĩthe wa Saulo.'),
('kam', '1SA', 14, 51, 'Na Kisu aĩ ĩthe wa Saulo; na Neli ĩthe wa Avineli aĩ mwana wa Avieli.'),
('kam', '1SA', 14, 52, 'Na kwaĩ kaũ mũnene na Avilisiti mĩthenya yonthe ya Saulo: na yĩla Saulo wonie mũndũ o na wĩva wĩ vinya mũno, kana mũndũ o na wĩva ngũmbaũ, nĩwamwosaa ethĩwe nake.'),
('kam', '1SA', 15, 1, 'Na Samueli amwĩa Saulo, Yeova nĩwandũmie ngwĩtĩkĩsye mauta wĩthĩwe mũsumbĩ wa andũ make, o Isilaeli: yu ĩndĩ ĩthukĩĩsye wasya wa ndeto sya Yeova.'),
('kam', '1SA', 15, 2, 'Ũũ nĩw’o Yeova wa nguthu ũnũkwasya, Ninonete ũndũ Amaleki wamwĩkie Isilaeli, o ũndũ wamũsiĩĩe nzĩanĩ, yĩla wambatĩte kuma Misili.'),
('kam', '1SA', 15, 3, 'Yu ĩndĩ enda ũkakũne Amaleki, na ũkyananga vyũ kyonthe kĩla me nakyo, na ndũkamatialye; ĩndĩ ũkoae mũndũ mũũme na mũndũ mũka, kana na kala kekwongw’a, ng’ombe na ĩlondu, ngamĩle na ĩng’oi.'),
('kam', '1SA', 15, 4, 'Na Saulo ameta andũ, na amatalĩla ku Telaimu, andũ ala maendaa na maũũ ngili maana elĩ, na andũ ma Yuta ngili ĩkũmi.'),
('kam', '1SA', 15, 5, 'Na Saulo avika ndũanĩ ya Amaleki, na ooveesya kyandanĩ.'),
('kam', '1SA', 15, 6, 'Na Saulo amea Akeni, Endai inyw’ĩ mwathũke, mũtheee mume katĩ wa Aamaleki, ndikese kũmwananganĩsya namo; nũndũ nĩmweekie ana onthe ma Isilaeli nesa, yila mambatĩte kuma Misili. Na ĩndĩ Akeni mauma katĩ wa Aamaleki.'),
('kam', '1SA', 15, 7, 'Na Saulo amakũna Aamaleki, kuma Avila vala mũndũ ũendelaa Suli, ĩla yelekanĩle na Misili.'),
('kam', '1SA', 15, 8, 'Na amũkwata Akaki mũsumbĩ wa Aamaleki, e thayũ na andũ onthe amamina vyũ kwa kũmatemanga na ũvyũ.'),
('kam', '1SA', 15, 9, 'Ĩndĩ Saulo vamwe na andũ mamũtialya Akaki, na malondu ala maseo mbee, na ng’ombe, na ila nou, na tũtena twa malondu, na syonthe ila syaĩ nzeo, na matyaaĩtĩkĩla kwimina vyũ: ĩndĩ kĩla kĩndũ kyaĩ kĩthũku na kĩte kĩseo, kyu makyanangie vyũ.'),
('kam', '1SA', 15, 10, 'Nĩvo ĩndĩ ndeto ya Yeova yokĩe Samueli, ĩkĩmwĩa,'),
('kam', '1SA', 15, 11, 'Nĩngwĩlila nũndũ nĩnamwiie Saulo ethĩwe mũsumbĩ; nũndũ nũsyokete akaeka kũngatĩĩa, na ndaneĩanĩsya mĩao yakwa. Na Samueli eew’a woo mũno; na amwĩkaila Yeova ũtukũ w’onthe.'),
('kam', '1SA', 15, 12, 'Na kĩoko Samueli ookĩla tene akomane na Saulo; na kwatavanw’a kwa Samueli, kũkyaw’a, Saulo nũvikie Kalimeli, na, sisya, nũũngamisye ũlilikan’yo, na eelelũka, na avĩta, na atheea Ngilikali.'),
('kam', '1SA', 15, 13, 'Na Samueli ooka kũla kwĩ Saulo; na Saulo amwĩa, Ĩthĩwa wĩ mũathime nĩ Yeova: nĩnĩanĩsye mwĩao wa Yeova.'),
('kam', '1SA', 15, 14, 'Na Samueli amũkũlya, Nĩ kwa kĩ ĩndĩ kwan’ya kũu kwa malondu kwĩ matũnĩ makwa, na kwan’ya kwa ng’ombe kũla ngwĩw’a?'),
('kam', '1SA', 15, 15, 'Na Saulo asũngĩa, Nĩmaietete kuma kwa Aamaleki: nũndũ andũ nĩmatialilye malondu ala maseo mbee na ng’ombe, sya kũthembea Ngai waku; na ila ingĩ nĩtwanangĩte vyũ.'),
('kam', '1SA', 15, 16, 'Nĩvo ĩndĩ Samueli wamwĩie Saulo Eteela, na nĩngũũtavya ũndũ Yeova ũndavisye ũtukũ ũu. Nake amwĩa, Neena.'),
('kam', '1SA', 15, 17, 'Na Samueli amwĩa, O na kau nĩweeyonie ta wi mũnini, ndwaatw’ĩkĩthiw’e mũtongoi wa mbaĩ sya Isilaeli? Na Yeova nĩwakwĩtĩkĩsye mauta wĩthĩwe mũsumbĩ wa Isilaeli;'),
('kam', '1SA', 15, 18, 'na Yeova akũtũma kyalo, na akwĩa, Thi, ũkamanange vyũ andũ asu athe Aamaleki, na ũkokite namo kũvika mathela.'),
('kam', '1SA', 15, 19, 'Nũndũ wa ki ĩndĩ ũtaneithukĩĩsya wasya wa Yeova, ĩndĩ ũnasembee mũtavo, na ũneeka ũla Yeova wonaa wĩ ũthũku?'),
('kam', '1SA', 15, 20, 'Na Saulo amwĩa Samueli, Ĩĩ, nĩnĩw’ĩte wasya wa Yeova, na nĩnĩnaendele nzĩanĩ ĩla Yeova ũnandũmĩle, na nĩnĩmũetĩe Akaki mũsumbĩ wa Aameleki, na ninĩmaminĩte Aamalaki vyũ.'),
('kam', '1SA', 15, 21, 'Ĩndĩ andũ nĩmanoosie sya mũtavo, malondu na ng’ombe, ila nzeo mbee sya syindũ ivathĩtwe, sya kũmũthembea Yeova Ngai waku ku Ngilikali.'),
('kam', '1SA', 15, 22, 'Na Samueli amũkũlya, Yeova nũtanĩaa nthembo sya kũvĩvw’a na nthembo sya kũtonywa, ta ũndũ ũtanĩaa ũkĩthukĩĩsya wasya wa Yeova? Sisya kwĩw’a nĩ kũseo kũte nthembo, na kwĩthukĩĩsya nĩ kũseo kũte mathunya ma ndũũme.'),
('kam', '1SA', 15, 23, 'Nũndũ ũng’endu nĩ ta naĩ ya ũoi, na kwaa matũ ta ũthaĩthi wa mĩvw’anano na telavimu. Nikwĩthĩwa we nũmileete ndeto ya Yeova, o nake nũkũieete ndũkethiwe mũsumbĩ.'),
('kam', '1SA', 15, 24, 'Na Saulo amwĩa Samueli, Nĩnĩvĩtĩtye; nũndũ nĩnivĩtĩtye mwĩao wa Yeova, o na ndeto syaku, nĩkwĩthĩwa nĩnĩnamakĩie andũ, na nĩneethukĩĩsya wasya woo.'),
('kam', '1SA', 15, 25, 'Yu ĩndĩ, nĩngũkwĩsũva, ndekea naĩ yakwa, na ũkĩsyokan’ya nakwa, nĩ kana nĩmũthaithe Yeova.'),
('kam', '1SA', 15, 26, 'Na Samueli amwĩa Saulo, Ndisyokan’ya naku; nũndũ nũmĩleete ndeto ya Yeova, na Yeova nũkũleete ndũkethĩwe mũsumbĩ wa Isilaeli.'),
('kam', '1SA', 15, 27, 'Na Samueli akĩthyũũa athi, Saulo akwata mũthya wa ngũa yake ndasa, nayo yatembũka.'),
('kam', '1SA', 15, 28, 'Na Samueli amwĩa, Yeova nũkũvenie ũsumbĩ wa Isilaeli mũnthĩ ũũ, na nũnengie mũtũi waku, ũla mũseo kwĩ we.'),
('kam', '1SA', 15, 29, 'Na ĩngĩ Vinya wa Isilaeli ndakakengana kana kwĩalyũla; nũndũ we ti mũndũ, atĩ, akeealyũla.'),
('kam', '1SA', 15, 30, 'Nĩvo ĩndĩ waisye, Nĩnĩvĩtĩtye: o na kũilyĩ ũu ndaĩĩthya yu, nĩngũkwĩsũva, kũla kwĩ atumĩa ma andũ makwa, na kũla kwĩ Isilaeli, na ũkĩsyokan’ya nakwa, kana nĩmũthaithe Yeova Ngai waku.'),
('kam', '1SA', 15, 31, 'Kwondũ wa ũu Samueli eetulũla amũatĩĩa Saulo; na Saulo athaitha Yeova.'),
('kam', '1SA', 15, 32, 'Nĩvo ĩndĩ Samueli waisye, Ndeteei vaa Akaki mũsumbĩ wa Aamaleki. Na Akaki ooka vala ũĩ na mũyo. Na Akaki aasya, Vate ndĩi ũũ wa kĩkw’ũ nĩ mũvĩtu.'),
('kam', '1SA', 15, 33, 'Na Samueli asya, O tondũ ũvyũ waku wamakw’ĩthĩsye aka methĩwe mate mwana, o ta ũu inyia waku nũkwĩthĩwa ate mwana katĩ wa aka. Na Samueli amũtilangĩla Akaki ilungu ku Ngilikali Yeova ene.'),
('kam', '1SA', 15, 34, 'Na ĩndĩ Samueli athi Lama; na Saulo ambata nyũmba kwake ku Ngivea ya Saulo.'),
('kam', '1SA', 15, 35, 'Na Samueli ndaathi ĩngĩ kũmwona Saulo kũvika mũthenya wa kũkw’a kwake; nũndũ Samueli nĩwamũĩĩaa Saulo; na Yeova eelila nũndũ nĩwamũtw’ĩkĩthĩtye Saulo mũsumbĩ wa Isilaeli.'),
('kam', '1SA', 16, 1, 'Na Yeova amũkũlya Samueli, Ũkamũĩĩa Saulo kũvika ĩndĩĩ, nakwa nĩnĩmũleete ndakethĩwe mũsumbĩ wa Isilaeli? Usũsya ũvya waku mauta, na ũkĩthi: nĩngũũtũma kwa Yese Mũmbethi‐leemu; nũndũ nĩnĩmanthĩe mũsumbĩ ananĩ make.'),
('kam', '1SA', 16, 2, 'Na Samueli asya, Ndonya kũthi ata? Ethĩwa Saulo akeew’a ũu, akambũaa. Na Yeova amwĩa, Osa moi ũthi nayo, na ũkyasya, Nĩnooka nĩthembee Yeova.'),
('kam', '1SA', 16, 3, 'Na ũkamwĩte Yese oke nthembonĩ, nakwa ngakwon’ya ũndũ wĩĩka: naku ũkamwĩtĩkĩsye mauta kwondũ wakwa we ũla nĩweta kwaku.'),
('kam', '1SA', 16, 4, 'Na Samueli eeka o ũla Yeova waneenie, na avika Mbethi‐leemu. Na atumĩa ma ĩ ndũa mathi mamũthaũe makĩtetema, na mamũkũlya, Waetwe nĩ mũuo?'),
('kam', '1SA', 16, 5, 'Nake asya, Nĩ mũuo; nĩnooka nĩmũthembee Yeova, ĩvathan’yei mwĩthĩwe atheu, na mũkĩendan’ya nakwa nthembonĩ. Na avathan’ya Yese na ana make, na ameta moke nthembonĩ.'),
('kam', '1SA', 16, 6, 'Na kweethĩwa, mavika, amũketeea Eliavu, na asya, Vate ndĩi mwĩtĩkĩw’a mauta wa Yeova e mbee wake.'),
('kam', '1SA', 16, 7, 'Ĩndĩ Yeova amwĩa Samueli, Ndũkasisye ũthyũ wake, kana ũtũlu wa kĩũngamo kyake; nĩkwĩthĩwa nyie nĩnĩmũleete: nũndũ Yeova ndasiasya ũndũ mũndũ ũsiasya; nũndũ mũndũ asiasya mũvw’anĩle wa ũtheinĩ, ĩndĩ Yeova asiasya ngoonĩ.'),
('kam', '1SA', 16, 8, 'Na ĩndĩ Yese eeta Avinatavu, na amũvĩtĩlya mbee wa Samueli. Nake asya, O na Yeova ndanyuvĩte ũũ.'),
('kam', '1SA', 16, 9, 'Na ĩndĩ Yese amũvĩtĩlya Samama. Nake asya, O na Yeova ndanyuvĩte ũũ.'),
('kam', '1SA', 16, 10, 'Na Yese amavĩtĩlya ana make mũonza mbee wa Samueli. Na Samueli amwĩa Yese, Yeova ndanyuvĩte aa.'),
('kam', '1SA', 16, 11, 'Na Samueli amũkũlya Yese, Ana maku onthe me vaa? Nake asũngĩa, Nĩvatiele o ũla mũnini, na, sisya, nũnũkũĩthya malondu. Na Samueli amwĩa Yese, Tũmana alatw’e; nũndũ tũiĩkala nthĩ mũvaka ooka vaa.'),
('kam', '1SA', 16, 12, 'Nake atũmana, na aetwe nthĩnĩ. Na ĩndĩ aĩ mũtune, na vamwe na ũu aĩ ũthyũ mũseo, na mũmbe nesa wa kũsiw’a. Na Yeova asya, Ũkĩla, mwĩtĩkĩsye mauta: nũndũ ũũ nĩwe.'),
('kam', '1SA', 16, 13, 'Nĩvo ĩndĩ Samueli wosie ũvya wa mauta, na amwĩtĩkĩsye mauta e katĩ wa ana‐a‐inyia: na Veva wa Yeova ooka na vinya mũnene ĩũlũ wa Ndaviti kuma mũthenya ũsu na kũendeea. Na ĩndĩ Samueli ookĩla, na athi Lama.'),
('kam', '1SA', 16, 14, 'Na ĩndĩ Veva wa Yeova amũtia Saulo, na veva mũthũku wumĩte kwa Yeova nĩwamũthĩnasya.'),
('kam', '1SA', 16, 15, 'Na athũkũmi ma Saulo mamwĩa, Sisya yu, veva mũthũku wumĩte kwa Ngai nũkũthĩnasya.'),
('kam', '1SA', 16, 16, 'Mwĩaĩi waitũ nĩeaĩe yu athũkũmi maku, ala me vo mbee waku, mamanthe mũndũ, mũingi mũĩ wa mbeve: na kũkeethĩwa, yĩla ũla veva mũthũku wumĩte kwa Ngai wĩ ĩũlũ waku, nĩvo ĩndĩ wĩinga na kw’oko kwake, naku ũkavoa.'),
('kam', '1SA', 16, 17, 'Na Saulo amea athũkũmi make, Manthĩai yu mũndũ ũla ũtonya kũinga nesa, na mũimũete kwakwa.'),
('kam', '1SA', 16, 18, 'Nĩvo ĩndĩ ũmwe wa anake wasũngĩie, na asya, Sisya, nĩnĩmwonete mwana wa Yese Mũmbethi‐leemu, ũla mũĩ wa kũinga, na ngũmbaũ nene, na mũndũ wa kaũ, na mũĩ wa ũneena, na mũmbe nesa; na Yeova e vamwe nake.'),
('kam', '1SA', 16, 19, 'Kwondũ wa ũu Saulo atũma atũmwa kwa Yese, na amwĩa, Tũma kwakwa Ndaviti mwana waku, ũla wĩ vamwe na malondu.'),
('kam', '1SA', 16, 20, 'Na Yese oosa ĩng’oi yakuĩthw’a imũtũ, na kathatwa ka mbinyu, na katena ka mbũi, na aitũmanĩsya na Ndaviti mwana wake kwa Saulo.'),
('kam', '1SA', 16, 21, 'Na Ndaviti avika kwa Saulo, na aũngama mbee wake: nake amwenda mũno; na atw’ĩka mũkui wa mĩio yake ya kaũ.'),
('kam', '1SA', 16, 22, 'Na Saulo atũmana kwa Yese, akĩmwĩa, Nĩngũkwĩsũva, ũeke Ndaviti aũngamae mbee wakwa; nũndũ nĩwonete ũseo methonĩ makwa.'),
('kam', '1SA', 16, 23, 'Na kweethĩwa, yĩla veva mũthũku wumĩte kwa Ngai waĩ ĩũlũ wa Saulo, nĩvo Ndaviti wosaa mbeve, na akĩinga na kw’oko kwake: kwondũ wa ũu Saulo akĩvuũka, na akĩvoa, na ũla veva mũthũku ũkyuma vala ũĩ.'),
('kam', '1SA', 17, 1, 'Na ĩndĩ Avilisiti nĩmoombanisye ita syoo syũkite, nao moombanĩe ku Soko, ĩla ya Yuta, na mamba maeema katĩ wa Soko na Aseka, ku Evesi‐ndamimu.'),
('kam', '1SA', 17, 2, 'Na Saulo na andũ ma Isilaeli moombana, na mamba maeema mwandanĩ wa Ela, na mataũsya ita mokite na Avilisiti.'),
('kam', '1SA', 17, 3, 'Na Avilisiti maũngama kĩĩmanĩ mũingo ũmwe, na Isilaeli maũngama kĩĩmanĩ mũingo ũla ũngĩ: na kwaĩ kyanda katĩ woo.'),
('kam', '1SA', 17, 4, 'Na vauma mũkiti mũnene mwakonĩ wa maeema wa Avilisiti, wetawa Ngoliathu, wa Ngathi, ũla kĩũngamo kyake kyaĩ mĩkono thanthatũ na ĩkwata ya kĩtaa.'),
('kam', '1SA', 17, 5, 'Nake aĩ na ngovia ya ũthuku mũtwe wake, na eekĩĩte kakoti ka iaa; na ũito wa kakoti waĩ sekeli ngili itano sya ũthuku.'),
('kam', '1SA', 17, 6, 'Na aĩ na ngolo sya kaũ sya ũthuku maũũnĩ make, na katumo ka ũthuku katĩ wa ituo.'),
('kam', '1SA', 17, 7, 'Na mũtĩ wa ĩtumo yake watilyĩ ta mũamba wa mũtumi wa ngũa; na ũito wa mũthya wa ĩtumo yake waĩ sekeli maana thanthatũ sya kĩaa: na mũkui wa ngao yake aendaa amũtongoesye.'),
('kam', '1SA', 17, 8, 'Nake aũngama na anĩĩsya ita sya Isilaeli, na aikũlya, Mumaalĩle kĩ kũtaũsya ita? Nyie ndi Mũvilisiti, nenyu mũti athũkũmi kwa Saulo? Ĩnyuvĩei mũndũ, na natheee kũla nĩĩ.'),
('kam', '1SA', 17, 9, 'Ethĩwa atonya kũkita nakwa, na kũmbũaa, nĩvo ĩndĩ twĩtw’ĩka athũkũmi menyu; ĩndĩ ethĩwa ngamũkĩlya vinya, na kũmũaa, mũkatw’ĩka ĩndĩ athũkũmi maitũ, na mũkatũthũkũmaa.'),
('kam', '1SA', 17, 10, 'Mũvilisiti asya, Nĩngũvũthya ita sya Isilaeli ũmũnthĩ; nengai mũndũ, nĩ kana tũkite nĩ nake.'),
('kam', '1SA', 17, 11, 'Na yĩla Saulo na Isilaeli onthe meewie ndeto isu sya Mũvilisiti, mateva, na meew’a w’ĩa mũno.'),
('kam', '1SA', 17, 12, 'Na ĩndĩ Ndaviti aĩ mwana wa ũla Mũevilathi wa Mbethi‐leemu‐yuta, ũla wetawa syĩtwa yake Yese; nake aĩ na ana nyanya: na mũndũ ũsu aĩ mũndũ mũkũũ mĩthenyanĩ ya Saulo, na e wa myaka mingĩ andũnĩ.'),
('kam', '1SA', 17, 13, 'Na ala ana atatũ akũũ ma Yese nĩmamũatĩĩĩte Saulo kaũnĩ: na masyĩtwa ma ana make atatũ ala maendie kaũnĩ nĩ Eliavu ĩkithathi, na ũla ũmũatĩĩe nĩ Avinatavu, na wa katatũ nĩ Samama.'),
('kam', '1SA', 17, 14, 'Na Ndaviti aĩ ĩlumaita; na asu atatũ akũũ mamũatĩĩĩte Saulo.'),
('kam', '1SA', 17, 15, 'Na ĩndĩ Ndaviti aendaa na kũsyokaa kuma kwa Saulo nĩ kana aĩthye malondu ma ĩthe wake ku Mbethi‐leemu.'),
('kam', '1SA', 17, 16, 'Na ũla Mũvilisiti athengeeaa kĩoko na wĩoo, na eeyonan’ya mwene mĩthenya mĩongo ĩna.'),
('kam', '1SA', 17, 17, 'Na Yese amwĩa Ndaviti mwana wake, Osa yu nũndũ wa ana‐a‐mwenyu eva ya lĩu wa mbaa ngetha mũkaange, na imũtũ ii ĩkũmi, na twaĩa ana‐a‐mwenyu mĩtũkĩ mwakonĩ wa maeema;'),
('kam', '1SA', 17, 18, 'na ũkĩtwaĩa kavuteni wa ngili yoo ngũmbwa ĩkũmi sya matulu, na ũisisya ũndũ ana‐a‐mwenyu mailyĩ, na ũkĩete ũvoo woo.'),
('kam', '1SA', 17, 19, 'Na ĩndĩ Saulo, namo, na andũ onthe ma Isilaeli, maĩ mwandanĩ wa Ela makyũkita na Avilisiti.'),
('kam', '1SA', 17, 20, 'Na Ndaviti ookĩla kĩoko tene, na atia malondu me na mũsũvĩi, na oosa, na athi, o tondũ Yese wamwĩaĩe; nake avika vala vandũ va makasya, o yĩla nguthu ĩla yaendaa kũkita yauasya ngemi nũndũ wa kaũ.'),
('kam', '1SA', 17, 21, 'Na Isilaeli na Avilisiti mataũsya ita mokite, ita syelekele ita.'),
('kam', '1SA', 17, 22, 'Na Ndaviti atia mũio wake kw’okonĩ kwa mũsũvĩi wa mĩio, na asemba itanĩ, na ooka na akethya ana‐a‐inyia.'),
('kam', '1SA', 17, 23, 'Na o yĩla waneenaa nao, sisya, kwaumĩla ũla mũkiti mũnene, Mũvilisiti wa Ngathi, syĩtwa nĩ Ngoliathu, kuma mĩkwĩlĩnĩ ya Avilisiti, na aneena o kwĩanana na ila ndeto: na Ndaviti asyĩw’a.'),
('kam', '1SA', 17, 24, 'Na andũ onthe ma Isilaeli, yĩla moonie ũ mũndũ, makũka mamũkĩĩte, na meew’a w’ĩa mũno.'),
('kam', '1SA', 17, 25, 'Na andũ ma Isilaeli makũlan’ya, Nĩmũsyaĩtye mũndũ ũũ wambata? Vate ndĩi ambata o kũvũthĩĩsya Isilaeli: na kũkeethĩwa, mũndũ ũla wĩmũaa, mũsumbĩ akamũthusya ũthwii mwingĩ, na akamũnenga mwĩĩtu wake, na kũtw’ĩkĩthya nyũmba ya ĩthe wake ũthasyo nthĩnĩ wa Isilaeli.'),
('kam', '1SA', 17, 26, 'Na Ndaviti aneena na andũ ala maũngamĩte vakuvĩ nake, akĩmakũlya, Kũkeekwa ata kwa mũndũ ũla wĩũaa Mũvilisiti ũũ, na kũveta kĩvũthya kyume kwa Isilaeli? Nũndũ Mũvilisiti ũũ ũte mwaĩke nũũ, kana avũthĩĩasye ita sya Ngai ũla wĩ thayũ?'),
('kam', '1SA', 17, 27, 'Na andũ mamũsũngĩa o ta ũũ makyasya, Ũũ nĩw’o kwĩĩkwa mũndũ ũla wĩmũaa.'),
('kam', '1SA', 17, 28, 'Na Eliavu mwana‐a‐inyia wake ũla mũkũũ eew’a yĩla waneenaa na andũ; na ũthatu wa Eliavu wamwakanĩa Ndaviti, na amũkũlya, Ũtheeie nĩkĩ? Na ũtiie malondu asu mavũthũ naũ ku weũnĩ? Nĩnĩsĩ ngathĩĩo syaku, na ũthũku wa ngoo yaku; Nũndũ ũtheeie kana ũtonye kwona kaũ.'),
('kam', '1SA', 17, 29, 'Na Ndaviti akũlya, Neka ata yu? Vati kĩtumi?'),
('kam', '1SA', 17, 30, 'Nake eethyũũa amũtia na eelekela ũngĩ, na aneena nake o ta ũla ũndũ: na andũ mamũsũngĩa o ta mbee.'),
('kam', '1SA', 17, 31, 'Na yĩla ndeto syeew’ĩkie ila Ndaviti waneenie, nĩmaineenie o ta ũu kũla kwĩ Saulo; nake amũtũmana.'),
('kam', '1SA', 17, 32, 'Na Ndaviti amwĩa Saulo, Vaikethĩwe mũndũ ũkw’a ngoo nũndũ wake; mũthũkũmi waku nũnũkũthi na kũkita na Mũvilisiti ũũ.'),
('kam', '1SA', 17, 33, 'Na Saulo amwĩa Ndaviti, Ndũtonya kũthi kũkita na Mũvilisiti ũũ; nũndũ wĩ o kĩmwana, nake nĩ mũndũ wa kaũ kuma wana wake.'),
('kam', '1SA', 17, 34, 'Na Ndaviti amwĩa Saulo, Mũthũkũmi waku nĩwaĩthasya malondu ma ĩthe; na yĩla kwookaa mũnyambũ, kana nduva, na kũkwata katena ka ĩlondu ndĩthyanĩ,'),
('kam', '1SA', 17, 35, 'nauma namĩatĩĩa, na namĩkũna, na kũkavonokya kuma kanyw’anĩ wayo; na yĩla yokĩlaa ĩmbangĩe, ngĩmĩkwata kĩng’ew’a kyayo, na ngĩmĩkũna, ngĩmyũaa.'),
('kam', '1SA', 17, 36, 'Mũthũkũmi waku nĩwakũnie syelĩ mũnyambũ na nduva: na Mũvilisiti ũũ ũte mwaĩke akeethĩwa ta imwe yasyo, nũndũ nũvũthĩĩsye ita sya Ngai ũla wĩ thayũ.'),
('kam', '1SA', 17, 37, 'Na Ndaviti asya, Yeova ũla wambonokisye kuma kĩthunĩ kya mũnyambũ, na kuma kĩthunĩ kya nduva, akambonokya nume kw’okonĩ kwa Mũvilisiti ũũ. Na Saulo amwĩa Ndaviti, Thi, na Yeova akeethĩwa vamwe naku.'),
('kam', '1SA', 17, 38, 'Na Saulo amwĩkĩa Ndaviti ngũa syake, na amwĩkĩa ngovia ya ũthuku mũtwe wake, na amwĩkĩa kakoti ka iaa.'),
('kam', '1SA', 17, 39, 'Na Ndaviti eeyova ũvyũ wake ĩũlũ wa ngũa syake, nake atatanga kũthi; nũndũ ndambĩte kwitata. Na Ndaviti amwĩa Saulo, Nditonya kũthi na ii; nũndũ ndyaamba kwitata. Na Ndaviti asyumya.'),
('kam', '1SA', 17, 40, 'Na oosa ndata yake na kw’oko kwake, na eenyuvĩa mavia atano matendeu kalũsĩnĩ, na amekĩa ngusunĩ ya mũĩthi ĩla waĩ nayo, o ngusunĩ yake; na kĩkũtha kyake kyaĩ kw’okonĩ kwake: na amũthengeea Mũvilisiti.'),
('kam', '1SA', 17, 41, 'Na ũla Mũvilisiti ookanga na athengeea Ndaviti; na mũndũ ũla wakuĩte ngao aenda mbee wake.'),
('kam', '1SA', 17, 42, 'Na yĩla Mũvilisiti wasyaisye kũũ na kũũ, na amwona Ndaviti, amũmonda; nũndũ aĩ o kĩmwana, na mũtune, na vamwe na ũu aĩ na ũthyũ mũseo.'),
('kam', '1SA', 17, 43, 'Na Mũvilisiti amwĩa Ndaviti, Nyie nĩ ngitĩ, kana ũmbũkĩe na ndata? Na Mũvilisiti amũumanĩa Ndaviti kwa ngai syake.'),
('kam', '1SA', 17, 44, 'Na Mũvilisiti amwĩa Ndaviti, Ũka vaa nĩĩ, nakwa nĩngũnenga nyũnyi sya yayaya, na nyamũ sya kĩtheka mwĩĩ waku.'),
('kam', '1SA', 17, 45, 'Na ĩndĩ Ndaviti amwĩa Mũvilisiti, We wĩmbũkĩa na ũvyũ, na ĩtumo, na katumo: ĩndĩ nyie nĩkũkĩa na syĩtwa ya Yeova wa nguthu, Ngai wa ita sya Isilaeli, ũla ũvũthĩĩsye.'),
('kam', '1SA', 17, 46, 'Mũthenya ũũ Yeova nũkũũnengane kw’okonĩ kwakwa; na nĩngũũkũna, na ngĩtila mũtwe waku; na nĩngwinenga nyũnyi sya yayaya, na nyamũ mbai sya nthĩ, simba sya nguthu ya Avilisiti ũmũnthĩ; nĩ kana nthĩ yonthe ĩmanye kana ve Ngai nthĩnĩ wa Isilaeli,'),
('kam', '1SA', 17, 47, 'na nĩ kana ĩkomano yĩĩ yonthe yĩtonye kũmanya kana Yeova ndatangĩĩaa na ũvyũ na ĩtumo: nũndũ ũ kaũ nĩ wa Yeova, na nũkũmũnengane mokonĩ maitũ.'),
('kam', '1SA', 17, 48, 'Na kweethĩwa, yĩla Mũvilisiti wokĩlile, na ooka na athengeea akomane na Ndaviti, Ndaviti eekalaata, na asemba elekele ita akomane na Mũvilisiti.'),
('kam', '1SA', 17, 49, 'Na Ndaviti eekĩa kw’oko kwake ngusunĩ yake, na aumya ĩvia vo, na ayĩkya na kĩkũtha, na amũkimĩla ũla Mũvilisiti kĩtulyanĩ; na ĩvia yalika nthĩnĩ wa kĩtulya kyake, nake avalũka nthĩ na ũthyũ wake.'),
('kam', '1SA', 17, 50, 'Ũu nĩw’o Ndaviti wakĩlilye ũla Mũvilisiti vinya na kĩkũtha na ĩvia, na amũkũna Mũvilisiti, na amũaa; ĩndĩ vatyaĩ ũvyũ kw’okonĩ kwa Ndaviti.'),
('kam', '1SA', 17, 51, 'Na ĩndĩ Ndaviti asemba, na aũngamĩĩa ũla Mũvilisiti, na oosa ũvyũ wake, na ookũa ndoonĩ yaw’o, na amũaa, na amũtila mũtwe naw’o. Na yĩla Avilisiti moonie kana mũkiti mũnene woo nĩwakw’a, makũka makĩa.'),
('kam', '1SA', 17, 52, 'Na andũ ma Isilaeli na ma Yuta mookĩla, na mausya ngemi, na mamakũa Avilisiti kũvika ũlikĩlonĩ wa Ngathi, na kũvika mbingĩlonĩ sya Ekiloni. Na ala okite ma Avilisiti mavalũkanga nzĩanĩ kũvika Saalaimu, o kũvika Ngathi, na kũvika Ekiloni.'),
('kam', '1SA', 17, 53, 'Na ana ma Isilaeli masyoka kuma kũmalũngya Avilisiti, nao moosa mũtavo mwakonĩ woo wa maeema.'),
('kam', '1SA', 17, 54, 'Na Ndaviti oosa mũtwe wa ũla Mũvilisiti, na ooete Yelusaleme; ĩndĩ ĩ mĩio yake ya kaũ aia ĩeemanĩ yake.'),
('kam', '1SA', 17, 55, 'Na yĩla Saulo wonie Ndaviti akĩthi kũkita na ũla Mũvilisiti, amũkũlilye Avineli, kavuteni wa nguthu, Avineli, kĩmwana kĩĩ nĩ mwana waũ? Na Avineli asũngĩa, O tondũ kyuu kyaku kĩ thayũ, we mũsumbĩ, nditonya kũmanya.'),
('kam', '1SA', 17, 56, 'Na mũsumbĩ asya, Kũlya ũ mwanake nĩ mwana waũ.'),
('kam', '1SA', 17, 57, 'Na yĩla Ndaviti wasyokete kuma kũaa ũla Mũvilisiti, Avineli amwosa, na amũete mbee wa Saulo e na mũtwe wa ũla Mũvilisiti kw’okonĩ kwake.'),
('kam', '1SA', 17, 58, 'Na Saulo amũkũlya, Wĩ mwana waũ, we mwanake? Na Ndaviti asũngĩa, Nyie nĩ mwana wa mũthũkũmi waku Yese Mũmbethi‐leemu.'),
('kam', '1SA', 18, 1, 'Na kweethĩwa, yĩla waminie kũneena na Saulo, ngoo ya Yonathani yakwatana na ngoo ya Ndaviti, na Yonathani amwenda o tondũ wĩyendete mwene.'),
('kam', '1SA', 18, 2, 'Na Saulo amwosa mũthenya ũsu, na ndaaĩtĩkĩla kũmũeka enũke ĩngĩ nyũmbanĩ kwa ĩthe wake.'),
('kam', '1SA', 18, 3, 'Nĩvo ĩndĩ Yonathani na Ndaviti matianĩe ũtianĩo, nĩkwĩthĩwa nĩwamwendie o tondũ wĩyendete mwene.'),
('kam', '1SA', 18, 4, 'Na Yonathani aumya ngũa ndasa ĩla wekĩe, na ngũa syake, o na kũvika ũvyũ wake, na ũta wake, na mũsivi wake, na amũnenga Ndaviti.'),
('kam', '1SA', 18, 5, 'Na Ndaviti aendaa o vala Saulo wamũtũmaa, na eeyĩkalya na kĩlĩko: na Saulo amwia ĩũlũ wa andũ ma kaũ, na waĩ ũseo woninĩ wa andũ onthe, na o wonini wa athũkũmĩ ma Saulo.'),
('kam', '1SA', 18, 6, 'Na kweethĩwa yĩla menũkĩte, yĩla Ndaviti wasyokete kuma kũaa ũla Mũvilisiti, aka mauma ndũanĩ syonthe sya Isilaeli, makina na makĩsũnga, mamũthaũe mũsumbĩ Saulo matanĩte, me na tũthembe, na me na syĩndũ sya kũinga.'),
('kam', '1SA', 18, 7, 'Na ala aka maina makĩtĩkĩanĩsya makĩinga, makyasya, Saulo nĩwũaĩte ngili syake, Na Ndaviti ngili syake makũmi.'),
('kam', '1SA', 18, 8, 'Na Saulo aĩ mũthilĩku mũno, na ndeto isu syamwĩw’ĩthya woo; nake asya, Nĩmatalĩla Ndaviti ngili makũmi, na mandalĩla o ngili: na atonya kwĩthĩwa na kĩngĩ kyaũ ate o ũsumbĩ?'),
('kam', '1SA', 18, 9, 'Na kuma mũthenya ũsu na kũendeea Saulo amũsiasya Ndaviti na itho ĩthũku.'),
('kam', '1SA', 18, 10, 'Na kweethĩwa ũnĩ ũsu, veva mũthũku wumĩte kwa Ngai wooka na vinya mũnene ĩũlũ wa Saulo, na athana e nyũmbanĩ nthĩnĩ: na Ndaviti ainga na kw’oko kwake, o tondũ wekaa o kĩla mũthenya. Na Saulo aĩ na ĩtumo yake kw’okonĩ kwake;'),
('kam', '1SA', 18, 11, 'na Saulo ekya ĩtumo; nũndũ aisye, Nĩmũtonyanĩsye Ndaviti na wako. Na Ndaviti eevonokya vala ũĩ kelĩ.'),
('kam', '1SA', 18, 12, 'Na Saulo nĩwamũkĩaa Ndaviti, nĩkwĩthĩwa Yeova aĩ vamwe nake, na nĩwamũekete Saulo.'),
('kam', '1SA', 18, 13, 'Kwondũ wa ũu Saulo amumya kwake, na amũtw’a kavuteni wake wa andũ ngili; nake aumaalaa na akĩsyoka e mbee wa andũ.'),
('kam', '1SA', 18, 14, 'Na Ndaviti eeyĩkalya na kĩlĩko mĩendelenĩ yake yonthe; na Yeova aĩ vamwe nake.'),
('kam', '1SA', 18, 15, 'Na yĩla Saulo wonie kana nĩweyĩkalilye na kĩlĩko mũno, ekala akĩmũkĩa.'),
('kam', '1SA', 18, 16, 'Ĩndĩ Isilaeli onthe na Yuta nĩmamwendaa Ndaviti; nũndũ nĩwaumaalaa na kũsyokaa e mbee woo.'),
('kam', '1SA', 18, 17, 'Na Saulo amwĩa Ndaviti, Sisya, mwĩĩtu wakwa ũla mũkũũ Melavu, nĩwe nĩkũnenga ethĩwe mũkau: ĩndĩ no wĩthĩwe wĩ na ũkũmbaũ nũndũ wakwa, na ũkyũkitĩthasya makaũ ma Yeova. Nũndũ Saulo aisye, Kw’oko kwakwa kũikethĩwe ĩũlũ wake, ĩndĩ kw’oko kwa Avilisiti kwĩthĩwe ĩũlũ wake.'),
('kam', '1SA', 18, 18, 'Na Ndaviti amũkũlya Saulo, Nyie nĩ ũũ, na thayũ wakwa nĩ kyaũ, kana mũvĩa wa asa wakwa nthĩnĩ wa Isilaeli, kana nĩtw’ĩke mũthoni wa mũsumbĩ?'),
('kam', '1SA', 18, 19, 'Ĩndĩ kweethĩwa atĩ ĩvinda yĩla Melavu, mwĩĩtu wa Saulo, waĩlĩte kũnengwa Ndaviti, anengwa Atilieli Mũmeolathi ethĩwe mũka.'),
('kam', '1SA', 18, 20, 'Na Mikali, mwĩĩtu wa Saulo, amwendete Ndaviti: namo mamũtavya Saulo, na ũndũ ũsu wamwendeesya.'),
('kam', '1SA', 18, 21, 'Na Saulo asya, Ngamũnenga we, kana atw’ĩke kĩtei kwake, na kana kw’oko kwa Avilisiti kwĩthĩwe ĩũlũ wake. Kwondũ wa ũu Saulo amwĩa Ndaviti, Mũthenya ũũ nũkũtw’ĩka mũthonua ĩvinda ya kelĩ.'),
('kam', '1SA', 18, 22, 'Na Saulo eeaĩa athũkũmi make, akĩmea, Neenan’yai na Ndaviti mwĩ nzama, na mũkĩmwĩa, Sisya, mũsumbĩ nũnũũkũtanĩa, na athũkũmi make onthe nĩmakwendete: yu kwondũ wa ũu tw’ĩka mũthoni wa mũsumbĩ.'),
('kam', '1SA', 18, 23, 'Na athũkũmi ma Saulo matonyeesya ndeto isu matũnĩ ma Ndaviti. Na Ndaviti akũlya, Kwĩoneka kwenyu ta ũndũ ũvũthũ kũtw’ĩka mũthoni wa mũsumbĩ, nakwa nĩ mũndũ ngya, na ũtalawa ta vathei?'),
('kam', '1SA', 18, 24, 'Na athũkũmi ma Saulo mamũtavya, makyasya, Ndaviti aneenie ũndũ ũtilyĩ ũu.'),
('kam', '1SA', 18, 25, 'Na Saulo asya, Ũũ nĩw’o mwĩmũtavya Ndaviti, Mũsumbĩ ndekwenda ngasya o na yĩva, ĩndĩ no ikonde sya mbinũ sya Avilisiti ĩana, aĩvanĩw’e kwa amaitha ma mũsumbĩ. Na ĩndĩ Saulo asũanĩaa kũmũvalũkĩthya Ndaviti na moko ma Avilisiti.'),
('kam', '1SA', 18, 26, 'Nayĩla athũkũmi make matavisye Ndaviti ndeto isu, nĩkwamwendeesye Ndaviti mũno kũtw’ĩka mũthoni wa mũsumbĩ. Na mĩthenya ndĩaathela;'),
('kam', '1SA', 18, 27, 'na Ndaviti ookĩla na athi, we na andũ make, na amoaa ma Avilisiti andũ maana elĩ; na Ndaviti aete ikonde sya mbinũ syoo, na mainengane na ũtalo wĩanĩe kwa mũsumbĩ, nĩ kana atonye kũtw’ĩka mũthoni wa mũsumbĩ. Na Saulo amũnenga Mikali mwĩĩtu wake ethĩwe mũka.'),
('kam', '1SA', 18, 28, 'Na Saulo oona na amanya kana Yeova aĩ vamwe na Ndaviti; na Mikali, mwĩĩtu wa Saulo, nĩwamwendete.'),
('kam', '1SA', 18, 29, 'Na Saulo amũkĩa Ndaviti mũno mbee; na Saulo aĩ mũmaitha wa Ndaviti ĩndĩ yonthe.'),
('kam', '1SA', 18, 30, 'Na ĩvinda yĩu anene ma mbee ũsumbĩnĩ ma Avilisiti maumaala: na kweethĩwa, o yĩla maumaalaa, Ndaviti eeyĩkalasya na kĩlĩko kĩnene kũte athũkũmi onthe ma Saulo; kũvika syĩtwa yake yataĩĩwa mũno.'),
('kam', '1SA', 19, 1, 'Na Saulo aneena na Yonathani mwana wake, na athũkũmi make onthe, mamũae Ndaviti. Ĩndĩ Yonathani, mwana wa Saulo, nĩwamũtanĩaa Ndaviti mũno.'),
('kam', '1SA', 19, 2, 'Na Yonathani amũtavya Ndaviti, akĩmwĩa, Saulo ĩthe wakwa nũnũũmantha ũkũaa: yu ĩndĩ, nĩngũkwĩsũva, wĩĩsũvĩa ũnĩ kĩoko, na kwĩkala wĩvithonĩ, ũkĩvitha mwene:'),
('kam', '1SA', 19, 3, 'nakwa ngaumaala na ngĩũngama vakuvĩ na asa wakwa kĩsesinĩ vala ũĩ, na nganeenan’ya na asa ũndũ waku; na ethĩwa ngoona ũndũ, ngakũtavya.'),
('kam', '1SA', 19, 4, 'Na Yonathani aneenea Ndaviti nesa kwa Saulo ĩthe wake, na amwĩa, Mũsumbĩ ndakavĩtanĩsye mũthũkũmi wake, o Ndaviti; nĩkwĩthĩwa we ndakũvĩtanĩsye, na nĩkwĩthĩwa mawĩa make makwelekele nĩmethĩĩtwe maseo mũno:'),
('kam', '1SA', 19, 5, 'nũndũ nĩwaiie thayũ wake kw’okonĩ kwake, na akũna ũla Mũvilisiti, na Yeova eeka ũkĩlyo mũnene ũndũ wa Isilaeli onthe: we nĩwoonie ũu, na watana; nũndũ wa kĩ ĩndĩ ũkwenda kũvĩtanĩsya nthakame ĩte ĩvĩtyo, ũae Ndaviti vate kĩtumi?'),
('kam', '1SA', 19, 6, 'Na Saulo eethukĩĩsya wasya wa Yonathani: na Saulo eevĩta, O tondũ Yeova wĩ thayũ, ndakoawa.'),
('kam', '1SA', 19, 7, 'Na Yonathani amwĩta Ndaviti, na Yonathani amwon’ya maũndũ asu onthe. Na Yonathani amũete Ndaviti kũla kwĩ Saulo, nake aĩ mbee wake, o ta tene.'),
('kam', '1SA', 19, 8, 'Na kwaĩ kaũ ĩngĩ: na Ndaviti aumaala, na okita na Avilisiti, na amoaa ũai mũnene; namo makũka mamũkĩĩte.'),
('kam', '1SA', 19, 9, 'Na veva mũthũku wumĩte kwa Yeova waĩ ĩũlũ wa Saulo, yĩla wekalĩte nyũmbanĩ yake e na ĩtumo yake kw’okonĩ kwake; na Ndaviti nĩwaingaa na kw’oko kwake.'),
('kam', '1SA', 19, 10, 'Na Saulo amantha kũmũtonyanĩsya Ndaviti na wako na ĩtumo yake; ĩndĩ eevonokya kuma vala Saulo ũĩ, nake atonya wako na ĩtumo: na Ndaviti akũka, na aindũka ũtukũ ũsu.'),
('kam', '1SA', 19, 11, 'Na Saulo atũma atũmwa nyũmbanĩ kwa Ndaviti, makamũsyaĩĩsye, na kũmũaa kĩoko: na Mikali, mũka wa Ndaviti, amũtavya, akyasya, Ethĩwa ndũũtangĩĩa thayũ waku ũtukũ ũũ, ũnĩ ũkooawa.'),
('kam', '1SA', 19, 12, 'Na ĩndĩ Mikali amũtheelelya Ndaviti mbũthinĩ: nake athi, na akũka, na avonoka.'),
('kam', '1SA', 19, 13, 'Na Mikali oosa mũvw’anano wĩtawa telavimu, na awia ũkomonĩ, na aia mũto wa w’ĩa wa mbũi mũtwenĩ waw’o, na oovw’ĩka ngũa.'),
('kam', '1SA', 19, 14, 'Na yĩla Saulo watũmie atũmwa makamũkwate Ndaviti, asya, Nĩ mũwau.'),
('kam', '1SA', 19, 15, 'Na Saulo atũma ala atũmwa makasisye Ndaviti, akĩmea, Mwambatyei kũũ nĩĩ e ũkomonĩ, nĩ kana ndonye kũmũaa.'),
('kam', '1SA', 19, 16, 'Na yĩla ala atũmwa malikile nthĩnĩ, sisya, telavimu waĩ ũkomonĩ wĩ na mũto wa w’ĩa wa mbũi mũtwe waw’o.'),
('kam', '1SA', 19, 17, 'Na Saulo amũkũlya Mikali, Nĩkĩ ũngengie ta ũu, na waeka mũmaitha wakwa athi, na ĩndĩ avonoka? Na Mikali asũngĩa Saulo, We ambĩie, Eka nĩthi; nĩkũaĩa kĩ?'),
('kam', '1SA', 19, 18, 'Na ĩndĩ Ndaviti akũka, na aindũka, na avika kwa Samueli ku Lama, na amũtavya onthe ala Saulo wamwĩkie. Nake na Samueli mathi na matũa Naiothi.'),
('kam', '1SA', 19, 19, 'Na kwatavanw’a kwa Saulo, kũkyaw’a, Sisya, Ndaviti e Naiothi yĩ Lama.'),
('kam', '1SA', 19, 20, 'Na Saulo atũma atũmwa makamũkwate Ndaviti: na yĩla moonie nguthu ya athani ĩkyathana, na Samueli aũngamĩte e mũtongoi woo, Veva wa Ngai ooka ĩũlũ wa atũmwa ma Saulo, na o namo mathana.'),
('kam', '1SA', 19, 21, 'Na yĩla kwatavaniw’e kwa Saulo, atũma atũmwa angĩ, na o namo mathana. Na Saulo atũma atũmwa ĩngĩ ĩvinda ya katatũ, na o namo mathana.'),
('kam', '1SA', 19, 22, 'Na ĩndĩ o nake athi ku Lama, na avika kĩthimanĩ kĩnene kĩla kĩ ku Seku: nake akũlya akyasya, Samueli na Ndaviti maĩva? Na ũmwe asya, Sisya, me Naiothi yĩ Lama.'),
('kam', '1SA', 19, 23, 'Nake athi vau Naiothi yĩ Lama: na Veva wa Ngai ooka ĩũlũ wake nake, na aendeea mbee, na akyathana, mũvaka avika Naiothi yĩ Lama.'),
('kam', '1SA', 19, 24, 'Na ũndũ ũngĩ aumya ngũa syake, nake athana e mbee wa Samueli, na akoma nthĩ e mũthei mũthenya ũsu w’onthe na ũtukũ ũsu w’onthe. Kwondũ wa ũu maneenanasya, Saulo nake e o katĩ wa athani?'),
('kam', '1SA', 20, 1, 'Na Ndaviti akĩa auma Naiothi yĩ Lama, na ooka na aneena mbee wa Yonathani, Nĩkĩte ata? Ũthũku wakwa nĩ mwaũ? Na naĩ yakwa nĩ myaũ kũla kwĩ au, kana amanthe thayũ wakwa?'),
('kam', '1SA', 20, 2, 'Nake amwĩa, Ũu wĩthĩwe kũasa; we ndũkakw’a: sisya, asa ndekaa ũndũ ũnene o na ũnini, ate o ambumbũĩe w’o; na asa embithĩa ũndũ ũũ kĩ? Ũu ti w’o.'),
('kam', '1SA', 20, 3, 'O na ĩngĩ Ndaviti eevĩta, na asya, Au nĩwĩsĩ nesa kana nĩnonete ũseo methonĩ maku; na easya, Yonathani ndakamanye ũũ, ndakese kwĩw’a woo: ĩndĩ w’o o tondũ Yeova wĩ thayũ, na o tondũ kyuu kyaku kĩ thayũ, no ĩtambya yĩ katĩ wakwa na kĩkw’ũ.'),
('kam', '1SA', 20, 4, 'Nĩvo ĩndĩ Yonathani wamĩie Ndaviti, O ũndũ ũla ngoo yaku ĩnĩkwenda, ngakwĩka o w’o.'),
('kam', '1SA', 20, 5, 'Na Ndaviti amwĩa Yonathani, Sisya, ũnĩ nĩ mũtiso wa mwei, na ndyaĩlwe nĩ kũtĩa kwĩkala vamwe na mũsumbĩ lĩunĩ: ĩndĩ eka nĩthi, ngevithe kĩthekanĩ kũvika mũthenya wa katatũ wĩoo.'),
('kam', '1SA', 20, 6, 'Ethĩwa au akesa kwona nde vo, nĩvo ĩndĩ wĩasya, Ndaviti anangũlilye ũthei mũno kana asembe ku Mbethi‐leemu ndũanĩ kwoo; nũndũ kwĩ nthembo ya kĩla mwaka kw’o kwondũ wa mũvĩa w’onthe.'),
('kam', '1SA', 20, 7, 'Ethĩwa akasya atĩĩ, Nĩ ũseo; mũthũkũmi waku akeethĩwa na mũuo: ĩndĩ ethĩwa akeethĩwa na ũthilĩku, manya ĩndĩ kana ũthũku nũtw’ĩtwe nĩwe.'),
('kam', '1SA', 20, 8, 'Kwondũ wa ũu ĩka mũthũkũmi waku nesa; nũndũ nũmũlikĩtye mũthũkũmi waku ũtianĩonĩ wa Yeova vamwe naku: ĩndĩ ethĩwa ve ũthũku nthĩnĩ wakwa, mbũaa eue; nũndũ wĩndwaa kũla kwĩ au nĩkĩ?'),
('kam', '1SA', 20, 9, 'Na Yonathani amwĩa, Ũu wĩthĩwe kũasa naku; nũndũ kethĩwa nĩthĩwa nĩsĩ kana ũthũku nũtw’ĩtwe nĩ asa wakwa wũke kwaku, nyie ĩndĩ ndikũtavya?'),
('kam', '1SA', 20, 10, 'Na ĩndĩ Ndaviti amũkũlya Yonathani, Nũũ ũla wĩndavya ethĩwa au akakũsũngĩa na vinya?'),
('kam', '1SA', 20, 11, 'Na Yonathani amwĩa Ndaviti, Ũka, tũthi kĩsesinĩ. Na maenda me elĩ kĩsesinĩ.'),
('kam', '1SA', 20, 12, 'Na Yonathani amwĩa Ndaviti, Yeova, Ngai wa Isilaeli, nĩethĩwe ngũsĩ: yĩla nĩĩthĩwa nĩmũthimĩte asa wakwa ĩvinda ta yĩĩ ũnĩ, kana mũthenya wa katatũ, sisya, ethĩwa nĩvethĩwa ũseo welekele Ndaviti, nyie ndikatũmana ĩndĩ kwaku, na ngĩkumbũĩa?'),
('kam', '1SA', 20, 13, 'Yeova eke ũu kwa Yonathani, o na mbee, kũkethĩwa kwendeesya asa wakwa akwĩke naĩ, ethĩwa ndikakumbũĩa, na ngĩũeka ũthi, nĩ kana ũende na mũuo: na Yeova ethĩwe vamwe naku, o tondũ wĩthĩĩtwe na asa wakwa.'),
('kam', '1SA', 20, 14, 'Na ti o yĩla nĩ thayũ ũkambon’ya ũseo wĩ wendo wa Yeova, kana ndikakw’e;'),
('kam', '1SA', 20, 15, 'ĩndĩ o na ĩngĩ ndũkaavete ũseo waku nyũmbanĩ yakwa tene na tene; aiee, o na yĩla Yeova ũkethĩwa amavetete amaitha ma Ndaviti kĩla ũmwe aume kũũ nthĩ.'),
('kam', '1SA', 20, 16, 'Kwondũ wa ũu Yonathani atianĩa ũtianĩo na nyũmba ya Ndaviti, akyasya, Na Yeova nũkaandũa ũndũ ũũ kw’okonĩ kwa amaitha ma Ndaviti.'),
('kam', '1SA', 20, 17, 'Na Yonathani atuma Ndaviti evĩta ĩngĩ, nũndũ wa wendo ũla waĩ naw’o kwake; nũndũ amwendete o tondũ wĩyendete mwene.'),
('kam', '1SA', 20, 18, 'Na ĩndĩ Yonathani amwĩa, Ũnĩ nĩ mũtiso wa mwei: naku ũkooneka ũte vo, nĩkwĩthĩwa kĩvĩla kyaku kĩkeethĩwa kĩ kĩthei.'),
('kam', '1SA', 20, 19, 'Na yĩla wĩĩthĩwa wĩkalĩte mĩthenya ĩtatũ, wĩtheea mĩtũkĩ, na ũkyũka vala vandũ weevithĩte yĩla maũndũ asu masiaw’a, na wĩĩkala vakuvĩ na ĩvia Eseli.'),
('kam', '1SA', 20, 20, 'Nakwa ngekya mĩsyĩ ĩtatũ ũtee wayo, ta ngũathaa vandũ.'),
('kam', '1SA', 20, 21, 'Na, sisya, ngatũma kamwana, ngĩkea, Enda, ũmanthe mĩsyĩ. Ethĩwa ngakea kamwana, Sisya, mĩsyĩ yĩ ngalĩ ĩno yaku; myose, na ũkyũka; nũndũ ve mũuo kwaku na vati ũthũku, o tondũ Yeova wĩ thayũ.'),
('kam', '1SA', 20, 22, 'Ĩndĩ ethĩwa ngatavya kamwana atĩĩ, Sisya, mĩsyĩ yĩ mbee waku; wĩĩendea; nũndũ Yeova nũkũtumĩte ũthi.'),
('kam', '1SA', 20, 23, 'Na ũndũ wa ũvoo ũla we nakwa tũnaneenanisye, sisya, Yeova e katĩ wakwa naku tene na tene.'),
('kam', '1SA', 20, 24, 'Kwondũ wa ũu Ndaviti eevitha kĩthekanĩ: na yĩla mũtiso wa mwei wavikie, mũsumbĩ ekala nthĩ aye lĩu.'),
('kam', '1SA', 20, 25, 'Na mũsumbĩ ekala kĩvĩlanĩ kyake, ta mavinda ala angĩ, o kĩvĩlanĩ vakuvĩ na wako; na Yonathani aũngama, na Avineli ekalĩte vakuvĩ na Saulo: ĩndĩ vandũ va Ndaviti vaĩ vathei.'),
('kam', '1SA', 20, 26, 'Ĩndĩ Saulo ndaaneena ũndũ mũthenya ũsu: nũndũ asũanĩie, Ve ũndũ ũmũkwatĩte, ti mũtheu; vate ndĩi ti mũtheu.'),
('kam', '1SA', 20, 27, 'Na kweethĩwa ũnĩ ũsu ĩtina wa mũtiso wa mwei, ũla waĩ mũthenya wa kelĩ, atĩ vandũ va Ndaviti vaĩ vathei: na Saulo akũlya Yonathani mwana wake, Nũndũ wa kĩ mwana wa Yese ũtaneũka lĩunĩ, ĩoo, o na ũmũnthĩ?'),
('kam', '1SA', 20, 28, 'Na Yonathani amũsũngĩa Saulo, Ndaviti anangũlilye mũno ũthei wa kũthi Mbethi‐leemu:'),
('kam', '1SA', 20, 29, 'na anaisye, Eka nĩthi, nĩngũkwĩsũva; nũndũ mũvĩa witũ wĩ na nthembo ndũanĩ; na mwana‐a‐ia, nũnambĩaĩe nĩthĩwe vo: na yu, ethĩwa nĩnonie ũseo methonĩ maku, eka nĩthi, nĩngũkwĩsũva, ngamone ana‐a‐asa. Kwondũ wa ũu ndokĩte mesanĩ ya mũsumbĩ.'),
('kam', '1SA', 20, 30, 'Nĩvo ĩndĩ ũthatu wa Saulo wamwakanĩe Yonathani, na amwĩa, We mwana wa kĩveti kĩema na kĩng’endu, nyie ndyĩsĩ kana we nĩweenyuvĩe mwana wa Yese kwa nthoni syaku mwene, na sya mwenyu e mũthei.'),
('kam', '1SA', 20, 31, 'Nũndũ o yĩla mwana wa Yese wĩ thayũ kũũ nthĩ, we ndũkalũlũmĩlw’a, o na ũsumbĩ waku. Kwondũ wa ũu yu tũmana na ũimũete kwakwa, nũndũ we vate ndĩi akakw’a.'),
('kam', '1SA', 20, 32, 'Na Yonathani amũsũngĩa Saulo ĩthe wake, na amũkũlya, Nũndũ wa kĩ waĩle kũawa? Ekĩte ata?'),
('kam', '1SA', 20, 33, 'Na Saulo amwĩkya ĩtumo yake amũtonye; kwondũ wa ũu Yonathani amanya kana nĩkwatw’ĩtwe nĩ ĩthe wake kũmũaa Ndaviti.'),
('kam', '1SA', 20, 34, 'Kwondũ wa ũu Yonathani ookĩla kuma mesanĩ e na ũthatu mwai, na ndaaya lĩu mũthenya wa kelĩ wa mwei; nũndũ nĩwewie woo nũndũ wa Ndaviti, nĩkwĩthĩwa ĩthe wake nĩwamũsonoketye.'),
('kam', '1SA', 20, 35, 'Na kweethĩwa kĩoko kyu, atĩ Yonathani aumaala kĩsesinĩ e na kamwana ĩvinda yĩla ũtw’ĩte na Ndaviti.'),
('kam', '1SA', 20, 36, 'Na atavya kamwana kake, Semba, mantha yu mĩsyĩ ĩla ngwĩkya. Na kamwana kakĩsemba, ekya mũsyĩ mbee wako.'),
('kam', '1SA', 20, 37, 'Na yĩla kamwana kavikie vandũ vala ve mũsyĩ ũla Yonathani wekĩtye, Yonathani anĩĩsya kamwana, na asya, Mũsyĩ ti ũsu mbee waku?'),
('kam', '1SA', 20, 38, 'Na Yonathani anĩĩsya kamwana, Semba mĩtũkĩ, ĩkalaate, ndũkekale. Na kamwana ka Yonathani koomban’ya mĩsyĩ; na kooka kwa vwana wako.'),
('kam', '1SA', 20, 39, 'Ĩndĩ kamwana katyaamanya ũndũ o na wĩva: no Yonathani na Ndaviti meesi ũndũ ũsu.'),
('kam', '1SA', 20, 40, 'Na Yonathani anenga kamwana kake mĩio yake ya kaũ, na akea, Enda, ũtwae ndũanĩ.'),
('kam', '1SA', 20, 41, 'Na o yĩla kamwana kaĩ kanathi, Ndaviti ookĩla kuma vandũ kwelekela ngalĩ ya Ĩtheo, na avalũka nthĩ na ũthyũ wake, na eekunamya mavinda atatũ: na mamumunyana, na maĩanĩa ene kwa ene, kũvika Ndaviti aĩa avĩtũkya.'),
('kam', '1SA', 20, 42, 'Na Yonathani amwĩa Ndaviti, Thi na mũuo, nũndũ twevĩtie ithyelĩ syĩtwanĩ ya Yeova, tũkyasya, Yeova akeethĩwa katĩ wakwa naku, na katĩ wa ũsyao wakwa na ũsyao waku, tene na tene. Nake ookĩla athi: na Yonathani athi ndũanĩ.'),
('kam', '1SA', 21, 1, 'Nĩvo ĩndĩ Ndaviti wokie Novu kwa mũthembi Aimeleki: na Aimeleki ooka amũthaũe Ndaviti akĩtetema, na amũkũlya, Nĩkĩ wĩ weka, na vati mũndũ wĩ vamwe naku?'),
('kam', '1SA', 21, 2, 'Na Ndaviti amwĩa mũthembi Aimeleki, Mũsumbĩ nũmbĩaĩe ũndũ, na nũmbĩie, Mũndũ o na wĩva ndakamanye ũndũ o na wĩva wa wĩa ũla ngũũtũmĩa, na ũndũ ngwĩaĩĩte: nakwa nĩniĩte anake vandũ vana na vana.'),
('kam', '1SA', 21, 3, 'Yu ĩndĩ kĩla wĩ nakyo kw’okonĩ kwaku nĩ kyaũ? Nenga kw’okonĩ kwakwa imũtũ itano, kana o kĩla kĩ vo.'),
('kam', '1SA', 21, 4, 'Na mũthembi amũsũngĩa Ndaviti, na amwĩa, Vati imũtũ ite ntheu kw’okonĩ kwakwa, ĩndĩ ve imũtũ ntheu; no ethĩwa anake mesiĩĩe na aka.'),
('kam', '1SA', 21, 5, 'Na Ndaviti amũsũngĩa mũthembi, na amwĩa, Nĩ w’o, aka nĩmasiĩĩĩkĩte vala tũĩ vandũ va mĩthenya ĩno ĩtatũ; yĩla naumie, mĩĩ ya anake yaĩ mĩtheu, o na kau kyaĩ o kyalo kya myangangĩle; nĩ veana ata mbee ĩndĩ ũmũnthĩ mĩĩ yoo yĩĩthĩwa yĩ mĩtheu?'),
('kam', '1SA', 21, 6, 'Kwondũ wa ũu mũthembi amũnenga imũtũ ntheu; nũndũ vatyaĩ imũtũ vau ate o imũtũ ila siĩawa Yeova, ila syaumiwe mbee wa Yeova, kwĩkĩa imũtũ mbyũ mũthenya ũla syavetiwe.'),
('kam', '1SA', 21, 7, 'Na ĩndĩ mũndũ ũmwe wa athũkũmi ma Saulo aĩ vo mũthenya ũsu, asiĩĩĩkĩte mbee wa Yeova; na syĩtwa yake eetawa Ndoeki Mũetomu, mũnene mbee wa aĩthi ala maĩ ma Saulo.'),
('kam', '1SA', 21, 8, 'Na Ndaviti akũlya Aimeleki, Na vaa vatyĩthĩwa ĩtumo kw’okonĩ kwaku kana ũvyũ? Nũndũ ndineekua ũvyũ wakwa kana mĩio yakwa ya kaũ, nĩkwĩthĩwa wĩa wa mũsumbĩ wĩendwa ũkalaatwe.'),
('kam', '1SA', 21, 9, 'Na mũthembi amwĩa, Ũvyũ wa Ngoliathu Mũvilisiti, ũla wamũaĩe mwandanĩ wa Ela, sisya, wĩ vaa ũvw’ĩkĩtwe ngũa mbĩlĩlo wa evoti: ethĩwa ũkenda kwosa ũsu, wose; nũndũ vati ũngĩ ate o ũsu vaa. Na Ndaviti asya, Vati ũngĩ ũtilyĩ ta ũsu; nenga w’o.'),
('kam', '1SA', 21, 10, 'Na Ndaviti ookĩla, na akũka mũthenya ũsu nũndũ wa kũkĩa Saulo, na athi kwa Akisi, mũsumbĩ wa Ngathi.'),
('kam', '1SA', 21, 11, 'Na athũkũmi ma Akisi mamwĩa, Ũũ ti Ndaviti mũsumbĩ wa ĩ nthĩ? Matyaaina makĩtĩkĩanĩsya ene kwa ene ũndũ wake makĩsũnga, makyasya, Saulo nĩwũaĩte ngili syake, Na Ndaviti ngili syake makũmi?'),
('kam', '1SA', 21, 12, 'Na Ndaviti aia ndeto isu ngoonĩ yake, na amũkĩa Akisi, mũsumbĩ wa Ngathi, mũno.'),
('kam', '1SA', 21, 13, 'Na aalyũka mwĩkalĩle wake kwamo, na eeyĩkalya mwene mokonĩ moo ta wĩ na ndũũka, na akalakalya mĩomonĩ ya mbingĩlo, na aeka ũta wake ũnyũlũlũke kĩng’ew’anĩ kyake.'),
('kam', '1SA', 21, 14, 'Nĩvo ĩndĩ Akisi wameie athũkũmi make, Sisya, nĩmũkwona mũndũ ũũ e na ndũũka; nũndũ wa kĩ ĩndĩ mũmũetete kwakwa?'),
('kam', '1SA', 21, 15, 'Nĩnĩnyivĩwe nĩ andũ ma ndũũka, kana mũnandetee mũndũ ũũ ekanasye maũndũ ma mũndũ wa ndũũka vala nĩĩ? Mũndũ ũũ akalika nyũmbanĩ yakwa?'),
('kam', '1SA', 22, 1, 'Kwondũ wa ũu Ndaviti auma kw’o, na aindũkĩĩa ngunganĩ ya Atulamu: na yĩla ana‐a‐ĩthe na nyũmba yonthe ya ĩthe meewie ũu, matheea ku ũĩ.'),
('kam', '1SA', 22, 2, 'Na kĩla ũmwe ũla waĩ thĩnanĩ, na kĩla ũmwe waĩ na thiĩ, na kĩla ũmwe waĩ na ũũ ngoonĩ, moombanĩa vala ũĩ; nake atw’ĩka kavuteni woo: na vamwe nake vaĩ andũ ta maana ana.'),
('kam', '1SA', 22, 3, 'Na Ndaviti auma vu athi Misiva yĩ Moavi: na, amwĩa mũsumbĩ wa Moavi, Nĩngũkwĩsũva, ũeke asa na mwaitũ moke, mekale vamwe naku, kũvika namanya ũndũ Ngai wĩmbĩka.'),
('kam', '1SA', 22, 4, 'Na amaete kũla kwĩ mũsumbĩ wa Moavi: namo matũaa vamwe nake ĩvinda yonthe yĩla Ndaviti waĩ ngomenĩ yĩ vinya.'),
('kam', '1SA', 22, 5, 'Na mwathani Ngati amwĩa Ndaviti, Ndũkekale ĩla ngomenĩ yĩ vinya; uma, na ũkĩenda nthĩ ya Yuta. Na ĩndĩ Ndaviti athi, na avota mũtitũnĩ wa Elethi.'),
('kam', '1SA', 22, 6, 'Na Saulo eew’a kana Ndaviti nĩwumbũkĩte, na andũ ala maĩ vamwe nake: na ĩndĩ Saulo ekalĩte ku Ngivea, ĩtina wa mũtĩ wa mweseli ku Lama, e na ĩtumo yake kw’okonĩ kwake, na athũkũmi make make onthe maũngamĩte mamũthyũlũlũkĩte.'),
('kam', '1SA', 22, 7, 'Na Saulo amea athũkũmi make ala maũngamĩte mamũthyũlũlũkĩte, Ĩw’ai yu, inyw’ĩ Ambenyamini; mwana wa Yese akamũnenga kĩla ũmwe wenyu isesi na mĩũnda ya mĩsavivũ, akamũtw’a inyw’onthe makavuteni ma ngili ngili na makavuteni ma maana,'),
('kam', '1SA', 22, 8, 'ũndũ inyw’onthe mũnzamĩĩte, na vati ũmwe ũla waamanyĩthya yĩla mwana wakwa ũnũkũseũvya wĩw’ano na mwana wa Yese, na vati ũmwe wenyu ũla ũmbĩw’ĩaa tei, kana kũmanyĩthya kana mwana wakwa nũmbulũanĩtye na mũthũkũmi wakwa, amboveesye, o tondũ ũilyĩ ũmũnthĩ?'),
('kam', '1SA', 22, 9, 'Nĩvo ĩndĩ Ndoeki Mũetomu, ũla waũngamĩte na athũkũmi ma Saulo, wasũngĩie, na amwĩa, Nĩnamwonie mwana wa Yese okĩte ku Novu, kwa Aimeleki mwana wa Aituvu.'),
('kam', '1SA', 22, 10, 'Nake nĩwamũkũlilye Yeova nũndũ wake, na amũnenga lĩu, na amũnenga ũvyũ wa Ngoliathu Mũvilisiti.'),
('kam', '1SA', 22, 11, 'Na ĩndĩ mũsumbĩ atũmana mũthembi Aimeleki, mwana wa Aituvu, etwe, na nyũmba yonthe ya ĩthe, athembi ala maĩ Novu: namo mooka onthe kwa mũsumbĩ.'),
('kam', '1SA', 22, 12, 'Na Saulo amwĩa, Ĩw’a yu, we mwana wa Aituvu. Nake asũngĩa, Ninyioo, mwĩaĩi wakwa.'),
('kam', '1SA', 22, 13, 'Na Saulo amũkũlya, Nĩkĩ mũnzamĩĩte, we na mwana wa Yese, ũndũ wamũnengie imũtũ, o na ũvyũ, na wakũlilye Ngai nũndũ wake, nĩ kana ambũkĩlĩle, na kũmboveesya, o tondũ ũilyĩ ũmũnthĩ?'),
('kam', '1SA', 22, 14, 'Nĩvo ĩndĩ Aimeleki wamũsũngĩie mũsumbĩ, na amũkũlya, Nũũ ĩndĩ katĩ wa athũkũmi maku onthe ũla mũĩkĩĩwa ta Ndaviti, ũla mũthoni wa mũsumbĩ, na nũlikĩtw’e nzamanĩ yaku, na nũtaĩawa nyũmbanĩ yaku?'),
('kam', '1SA', 22, 15, 'Nyie nĩnambĩlĩlye ũmũnthĩ kũkũlya Ngai kwondũ wake? Ũu wĩthĩwe kũasa nakwa: mũsumbĩ ndakatalĩthye ũndũ o na wĩva kwa mũthũkũmi wake, kana kwa nyũmba yonthe ya asa wakwa; nũndũ mũthũkũmi waku ndesĩ ũndũ o na wĩva wa ũu w’onthe, ũnini kana ũnene.'),
('kam', '1SA', 22, 16, 'Na mũsumbĩ asya, Vate ndĩi nũũkw’a, Aimeleki, we, na nyũmba ya au yonthe.'),
('kam', '1SA', 22, 17, 'Na mũsumbĩ amea asũvĩi ala mamũũngamĩe, Ĩthyũũei, na ũaai athembi ma Yeova; nĩkwĩthĩwa kw’oko kwoo nakw’o kwĩ vamwe na Ndaviti, na nĩkwĩthĩwa mo nĩmamanyie kana nĩwakĩĩte, na matyaamanyĩthya ũndũ ũsu. Ĩndĩ athũkũmi ma mũsumbĩ matyaaĩtĩkĩla kũtambũũkya kw’oko kwoo kũvalũkĩle athembi ma Yeova.'),
('kam', '1SA', 22, 18, 'Na mũsumbĩ amwĩa Ndoeki, Ĩthyũũe we, na ũimathũũmũkĩa athembi. Na Ndoeki Mũetomu eethyũũa, na athũũmũkĩa athembi, na ooaa mũthenya ũsu andũ mĩongo nyanya na atano ala meekĩaa evoti ya katane.'),
('kam', '1SA', 22, 19, 'Na akũna Novu, ndũa ya athembi, kwa kũtemanga na ũvyũ, aũme o na aka, twana na tũla tũkwongw’a, na ng’ombe na mang’oi na malondu, o kwa kũtemanga na ũvyũ.'),
('kam', '1SA', 22, 20, 'Na ũmwe wa ana ma Aimeleki, mwana wa Aituvu, wetawa Aviathali, avuthũka, na akĩa aatĩĩe Ndaviti.'),
('kam', '1SA', 22, 21, 'Na Aviathali atavya Ndaviti kana Saulo nũmoaĩte athembi ma Yeova.'),
('kam', '1SA', 22, 22, 'Na Ndaviti amwĩa Aviathali, Nĩnamanyie mũthenya ũsu, yĩla Ndoeki Mũetomu waĩ vau, kana vate ndĩi akamũtavya Saulo: ninyie kĩtumi kya andũ onthe ma nyũmba ya au kũkw’a.'),
('kam', '1SA', 22, 23, 'Ĩkala vamwe nakwa, ndũkakĩe; nũndũ we ũla ũmanthaa thayũ wakwa emantha thayũ waku: nũndũ wĩ vamwe nakwa ũkeethĩwa ũsũvĩonĩ mũlũmu.'),
('kam', '1SA', 23, 1, 'Na mamũtavya Ndaviti, makyasya, Sisya, Avilisiti nĩmekũkita ku Keila, nao nĩmeũvutana ngetha ivũĩonĩ.'),
('kam', '1SA', 23, 2, 'Kwondũ wa ũu Ndaviti akũlya Yeova, akyasya, Nĩende na kũmakũna Avilisiti aa? Na Yeova amwĩa Ndaviti, Thi, na kũna Avilisiti, na ũitangĩĩa Keila.'),
('kam', '1SA', 23, 3, 'Na andũ ma Ndaviti mamwĩa, Sisya, nĩtũũkĩa vaa Yuta: nĩ mbee veana ata ĩndĩ ethĩwa tũkathi ku Keila tũkite na ita sya Avilisiti?'),
('kam', '1SA', 23, 4, 'Na ĩndĩ Ndaviti akũlya Yeova o ĩngĩ. Na Yeova amũsũngĩa, na amwĩa, Ũkĩla, theea ku Keila; nũndũ ngamanengane Avilisiti kw’okonĩ kwaku.'),
('kam', '1SA', 23, 5, 'Na Ndaviti na andũ make mathi Keila, na mokita na Avilisiti, na matava indo syoo, na mamoaa ũai mũnene. Na ĩndĩ Ndaviti amatangĩĩa ala matwĩe Keila.'),
('kam', '1SA', 23, 6, 'Na kweethĩwa, yĩla Aviathali mwana wa Aimeleki wakĩie athi kũla kwĩ Ndaviti ku Keila, atheea e na evoti kw’okonĩ kwake.'),
('kam', '1SA', 23, 7, 'Na kwatavanw’a kwa Saulo kana Ndaviti nĩwũkĩte ku Keila. Na Saulo asya, Ngai nũmũnenganĩte kw’okonĩ kwakwa; nũndũ nũvingĩwe nthĩnĩ, kwondũ wa kũlika katũla ke na mbingĩlo na ivingi.'),
('kam', '1SA', 23, 8, 'Na Saulo ameta andũ onthe kaũnĩ, matheee ku Keila, mathyũlũlũke matw’ĩkanĩsye Ndaviti na andũ make.'),
('kam', '1SA', 23, 9, 'Na Ndaviti nĩwesĩ kana Saulo nũsũanĩĩte kũmwĩka naĩ; na amwĩa mũthembi Aviathali, Ete evoti vaa.'),
('kam', '1SA', 23, 10, 'Na ĩndĩ Ndaviti asya, Ame Yeova, Ngai wa Isilaeli, mũthũkũmi waku nĩwĩw’ĩte vate ndĩi kana Saulo emantha kũka Keila, anange ndũa nũndũ wakwa.'),
('kam', '1SA', 23, 11, 'Andũ ma Keila makanengane nyie kw’okonĩ kwake? Saulo akatheea, o tondũ mũthũkũmi waku wĩw’ĩte? Ame Yeova, Ngai wa Isilaeli, nĩngũkwĩsũva, mũtavye mũthũkũmi waku. Na Yeova amũsũngĩa, Akatheea.'),
('kam', '1SA', 23, 12, 'Na ĩndĩ Ndaviti akũlya, Andũ ma Keila makanengane nyie na andũ makwa kw’okonĩ kwa Saulo? Na Yeova amũsũngĩa, Makaũnengane.'),
('kam', '1SA', 23, 13, 'Na ĩndĩno Ndaviti na andũ make, ala maĩ ta maana thanthatũ, mookĩla na mauma Keila, na maenda o vala maĩ matonya kũthi. Na kwatavanw’a kwa Saulo kana Ndaviti nũindũkĩte kuma Keila; nake aeka kũthi.'),
('kam', '1SA', 23, 14, 'Na Ndaviti ekala weũnĩ ngomenĩ syĩ vinya, na ekala nthĩ yĩ iĩma weũnĩ wa ku Nzivu. Na Saulo amũmantha kĩla mũthenya, ĩndĩ Ngai ndaamũnengane kw’okonĩ kwake.'),
('kam', '1SA', 23, 15, 'Na Ndaviti oona kana Saulo nĩwumaalĩte amanthe thayũ wake: na Ndaviti aĩ weũnĩ wa ku Nzivu mũtitũnĩ.'),
('kam', '1SA', 23, 16, 'Na Yonathani mwana wa Saulo ookĩla, na aenda kwa Ndaviti mũtitũnĩ, na amwĩkĩa kw’oko kwake vinya nthĩnĩ wa Ngai.'),
('kam', '1SA', 23, 17, 'Na amwĩa, Ndũkakĩe; nũndũ kw’oko kwa Saulo ĩthe wakwa kũikakwona; naku ũkeethĩwa mũsumbĩ wa Isilaeli, nakwa ngeethĩwa nĩ wa kelĩ ũsumbĩnĩ; na Saulo ĩthe wakwa nĩwĩsĩ ũu naw’o.'),
('kam', '1SA', 23, 18, 'Na me elĩ matianĩa ũtianĩo me mbee wa Yeova: na Ndaviti atũa mũtitũnĩ, na Yonathani athi nyũmba kwake.'),
('kam', '1SA', 23, 19, 'Nĩvo ĩndĩ Anzivu mambatie kwa Saulo ku Ngivea, makĩmwĩa, Ndaviti ndevithĩte kwitũ ngomenĩ syĩ vinya mũtitũnĩ, kĩĩmanĩ kya Akila, kĩla kĩ ngalĩya ĩtheo ya yalata?'),
('kam', '1SA', 23, 20, 'Yu ĩndĩno, we mũsumbĩ, theea, kwĩanana na kwenda kw’onthe kwa thayũ waku kwa kũtheea; na ũndũ witũ ũkeethĩwa kũmũnengane kw’okonĩ kwa mũsumbĩ.'),
('kam', '1SA', 23, 21, 'Na Saulo amea, Ĩthĩwai mwĩ aathime nĩ Yeova; nũndũ nĩmũmbĩw’ĩe ĩnee.'),
('kam', '1SA', 23, 22, 'Endai, nĩngũmwĩsũva, mũmine nzika, na mũkĩmanya na kwona vandũ vake vala kĩtumũlo kyake kĩĩ, na ũla ũmwonete vau; nũndũ nĩndavĩtw’e ekaa na ũseleke mũno.'),
('kam', '1SA', 23, 23, 'Kwondũ wa ũu, sisyai, na mũimanya nesa mawĩvitho onthe kũla wĩvithaa mwene, na mũkyũka ĩngĩ kwakwa mwĩsĩ ki, nakwa ngathi nenyu: na kũkeethĩwa, ethĩwa akeethĩwa ĩ nthĩ, ngamũmantha vyũ katĩ wa ngili sya Yuta syonthe.'),
('kam', '1SA', 23, 24, 'Namo mookĩla, na mamba kũthi Nzivu kũte Saulo: ĩndĩ Ndaviti na andũ make maĩ weũnĩ wa Maoni, o ku Alava ngalĩ ya ĩtheo ya yalata.'),
('kam', '1SA', 23, 25, 'Na Saulo na andũ make mathi kũmũmantha. Na mamũtavya Ndaviti: kwondũ wa ũu atheea ĩvianĩ, na ekala weũnĩ wa Maoni. Na yĩla Saulo wewie ũu, amũatĩĩa Ndaviti ku weũnĩ wa Maoni'),
('kam', '1SA', 23, 26, 'Na Saulo aendela ngalĩ ĩno ya kĩĩma, na Ndaviti na andũ make ngalĩ ĩya ya kĩĩma: na Ndaviti eekalaata athonoke nũndũ wa kũkĩa Saulo; nũndũ Saulo na andũ make nĩmamathyũlũlũkĩte Ndaviti na andũ make ngalĩ syonthe mamakwate.'),
('kam', '1SA', 23, 27, 'Ĩndĩ Saulo ookĩwa nĩ mũtũmwa, akĩmwĩa, Ĩkalaate, na ũkyũka; nũndũ Avilisiti nĩmavithũkĩe nthĩ.'),
('kam', '1SA', 23, 28, 'Na ĩndĩ Saulo asyoka aeka kũatĩĩa Ndaviti, na aenda okite na Avilisiti: kwondũ ũu meeta vandũ vau Sela‐amalekothi.'),
('kam', '1SA', 23, 29, 'Na Ndaviti ambata kuma vau, na atũa ngomenĩ syĩ vinya sya Eni‐ngeti.'),
('kam', '1SA', 24, 1, 'Na kweethĩwa, yĩla Saulo wasyokie kuma kũmaatĩĩa Avilisiti, kwatavanw’a kwake, kũkyaw’a, Sisya, Ndaviti e weũnĩ wa Eni‐ngeti.'),
('kam', '1SA', 24, 2, 'Na ĩndĩ Saulo oosa andũ ngili itatũ manyuvĩtwe kuma Isilaeli onthe, na athi amanthe Ndaviti na andũ make mavianĩ ma mbũi sya kĩthekanĩ.'),
('kam', '1SA', 24, 3, 'Na avika syengonĩ sya malondu nzĩanĩ, vala vaĩ ngunga; na Saulo alika evw’ĩke maũũ make. Na yu Ndaviti na andũ make nĩmekalĩte kũndũ kwĩ nthĩnĩ mũno ngunganĩ.'),
('kam', '1SA', 24, 4, 'Na andũ ma Ndaviti mamwĩa, Sisya, mũthenya nĩ ũũ ũla Yeova wakwĩie, Sisya, nganengane mũmaitha waku kw’okonĩ kwaku, na ũkamwĩka o ũndũ wĩona wĩ ũseo. Nĩvo ĩndĩ Ndaviti wũkĩlile na atila mũthya wa ngũa ndasa ya Saulo kĩmbithĩ.'),
('kam', '1SA', 24, 5, 'Na kweethĩwa ĩtina ngoo ya Ndaviti yamũthĩn’ya, nũndũ nĩwatila mũthya wa ngũa ya Saulo.'),
('kam', '1SA', 24, 6, 'Na amea andũ make, Yeova ndakandeke nĩke mwĩaĩi wakwa, mwĩtĩkĩw’a mauta wa Yeova, ũndũ ũũ, kũmũtambũũkĩsya kw’oko kwakwa, nũndũ nĩ mwĩtĩkĩw’a mauta wa Yeova.'),
('kam', '1SA', 24, 7, 'Ũu nĩw’o Ndaviti wavatie andũ na ndeto isu, na ndaamaeka mamwĩke Saulo ũndũ. Na Saulo ookĩla auma ngunganĩ, na eeyĩendea.'),
('kam', '1SA', 24, 8, 'Ndaviti nake ookĩla ĩtina, na auma ngunganĩ, na amwanĩĩsya Saulo, akyasya, Mwĩaĩi wakwa, mũsumbĩ Na yĩla Saulo wasiisye ĩtina, Ndaviti akunamya ũthyũ wake nthĩ, na kwĩkunamya vyũ.'),
('kam', '1SA', 24, 9, 'Na Ndaviti amwĩa Saulo, Wĩthukĩĩasya ndeto sya andũ nĩkĩ, makyasya, Sisya, Ndaviti nũmanthaa kũkwĩka naĩ?'),
('kam', '1SA', 24, 10, 'Sisya ũmũnthĩ metho maku nĩmonie ũndũ Yeova ũkũnenganie kw’okonĩ kwakwa ũmũnthĩ wĩ ngunganĩ; na amwe mambĩa nĩkũae; ĩndĩ itho yakwa yakũeka; na nasya, Ndikatambũũkĩa mwĩaĩi wakwa kw’oko kwakwa; nũndũ nĩ mwĩtĩkĩw’a mauta wa Yeova.'),
('kam', '1SA', 24, 11, 'O na mbee wa ũu, asa wakwa, sisya, ĩĩ, sisya mũthya wa ngũa yaku ndasa kw’okonĩ kwakwa; nũndũ o ũndũ natila mũthya wa ngũa ngũanĩ yaku ndasa, na ndinakũaa, manya na kwona ki kana vati ũthũku o na ĩvĩtyo kw’okonĩ kwakwa, na kana ndikũvĩtanĩsye, o na kau nũmanthaa thayũ wakwa ũmbene.'),
('kam', '1SA', 24, 12, 'Yeova nasilan’ye katĩ wakwa naku, na Yeova andĩvanĩsye vala ũĩ; ĩndĩ kw’oko kwakwa kũtikethĩwa ĩũlũ waku.'),
('kam', '1SA', 24, 13, 'O tondũ nthimo ya ala ma tene ĩkwasya, Ũthũku nĩwumaa kwa ala athũku; ĩndĩ kw’oko kwakwa kũtikethĩwa ĩũlũ waku.'),
('kam', '1SA', 24, 14, 'Mũsumbĩ wa Isilaeli aumĩte aatĩĩe ũũ? Ũatĩĩaa ũũ we? Ũatĩĩaa ngitĩ ngw’ũ, ũatĩĩaa ngala.'),
('kam', '1SA', 24, 15, 'Yeova nĩethĩwe mũsili ĩndĩ, na aitw’a sila katĩ wakwa naku, na akyona, na akĩndetea, na akĩmbonokya kw’okonĩ kwaku.'),
('kam', '1SA', 24, 16, 'Na kweethĩwa, yĩla Ndaviti waminie kũmũtavya Saulo ndeto isu, Saulo akũlya, Ũsu nĩ wasya waku, mwana wakwa Ndaviti? Na Saulo ookĩlya wasya wake, na kũĩa.'),
('kam', '1SA', 24, 17, 'Na amwĩa Ndaviti, We wĩ mũlũngalu kwĩ nyie; nũndũ nũmbĩkĩte nesa, o na kau nĩkwĩkĩte ũthũku.'),
('kam', '1SA', 24, 18, 'Na nĩwonanisye mũthenya ũũ ũndũ ũmbĩkie nesa, nũndũ yĩla Yeova ũnenganie kw’okonĩ kwaku, ndũnambũaa.'),
('kam', '1SA', 24, 19, 'Nũndũ ethĩwa mũndũ nũnũkwona mũmaitha wake, akamũeka athi e mũvoo? Kwondũ wa ũu Yeova akwĩke nesa kwondũ wa ũndũ ũsu ũmbĩkie ũmũnthĩ.'),
('kam', '1SA', 24, 20, 'Na yu, sisya, nĩnĩsĩ kana ũkeethĩwa mũsumbĩ vate ndĩi, na kana ũsumbĩ wa Isilaeli ũkalũlũmĩlw’a kw’okonĩ kwaku.'),
('kam', '1SA', 24, 21, 'Mbĩavĩe yu ĩndĩ na Yeova, atĩ ndũkaveta ũsyao wakwa ĩtina wakwa, na kana ndũkananga syĩtwa yakwa yume nyũmbanĩ ya asa wakwa.'),
('kam', '1SA', 24, 22, 'Na Ndaviti eevĩta kwa Saulo. Na Saulo enũka; ĩndĩ Ndaviti na andũ make mambata ngomenĩ yĩ vinya.'),
('kam', '1SA', 25, 1, 'Na Samueli akw’a; na Isilaeli onthe moombana, na mamũĩĩa, na mamũthika nyũmbanĩ yake ku Lama. Na Ndaviti ookĩla, na atheea weũnĩ wa Valani.'),
('kam', '1SA', 25, 2, 'Na kwaĩ mũndũ ku Maoni, ũla ũthwii wake waĩ ku Kalimeli; na mũndũ ũsu aĩ nguma mũno, na aĩ na malondu ngili itatũ, na mbũi ngili ĩmwe: na atilĩlaa malondu w’ĩa ku Kalimeli.'),
('kam', '1SA', 25, 3, 'Na ĩndĩ syĩtwa ya mũndũ ũsu eetawa Navali; na syĩtwa ya mũka wake Avikaili; na mũndũ mũka ũsu aĩ na ũmanyi mũseo na ũthyũ mũseo: ĩndĩ ũ mũndũ aĩ mwai na mũthũku mĩkĩlenĩ yake; nake aĩ wa nyũmba ya Kalevu.'),
('kam', '1SA', 25, 4, 'Na Ndaviti eew’a e weũnĩ atĩ Navali nũnũũtila malondu make w’ĩa.'),
('kam', '1SA', 25, 5, 'Na Ndaviti atũma anake ĩkũmi, na Ndaviti atavya ala anake, Ambatai Kalimeli, na mũkĩthi kwa Navali, na mũkĩmũkethya syĩtwanĩ yakwa:'),
('kam', '1SA', 25, 6, 'na ũũ nĩw’o mwĩneena nake ũla wĩkalaa athimĩkĩte, Mũuo wĩthĩwe kwaku, na mũuo wĩthĩwe kwa nyũmba yaku, na mũuo wĩthĩwe kwa syonthe ila wĩ nasyo.'),
('kam', '1SA', 25, 7, 'Na yu nĩnĩw’ĩte kana wĩ na atili ma w’ĩa: na aĩthi maku nĩmekalanĩtye naitũ, na tũtyaameka naĩ, o na kũtyaĩ kĩndũ kyaaa kwoo, ĩvinda yonthe yĩla maĩ ku Kalimeli.'),
('kam', '1SA', 25, 8, 'Kũlya anake maku, na makakũtavya: kwondũ wa ũu anake nĩmone ũseo vala ũĩ; nũndũ nĩtũkũka mũthenya mũseo: nĩngũkwĩsũva, nenga athũkũmi maku, na Ndaviti mwana waku, o kĩla kĩkoneka kw’okonĩ kwaku.'),
('kam', '1SA', 25, 9, 'Na yĩla anake ma Ndaviti mavikie, maneena na Navali syĩtwanĩ ya Ndaviti kwĩanana na ndeto isu syonthe, na makilya.'),
('kam', '1SA', 25, 10, 'Na Navali asũngĩa athũkũmi ma Ndaviti, na amea, Ndaviti nũũ? Na mwana wa Yese nũũ? Kwĩ athũkũmi aingĩ matukũ aa ala mevithaa kĩla mũndũ kuma kwa vwana wake.'),
('kam', '1SA', 25, 11, 'Ngoosa ĩndĩ imũtũ syakwa, na kĩw’ũ kyakwa, na nyama syakwa ila nũaĩe ala makwa matilaa w’ĩa, na ngĩnenga andũ ala ndesĩ kũla maumĩte?'),
('kam', '1SA', 25, 12, 'Kwondũ wa ũu anake ma Ndaviti meetulũla na nzĩa yoo, na masyoka, na mavika mamũtavya kwĩanana na ndeto isu syonthe.'),
('kam', '1SA', 25, 13, 'Na Ndaviti amea andũ make, Ĩvotoei kĩla mũndũ ũvyũ wake. Na meevotoa kĩla mũndũ ũvyũ wake; nake Ndaviti eevotoa ũvyũ ũla wake: na kwambata andũ ta maana ana maatĩĩe Ndaviti; na andũ maana elĩ mekala na mĩio.'),
('kam', '1SA', 25, 14, 'Ĩndĩ mwanake ũmwe aneena na Avikaili, kĩveti kya Navali, aikĩtavya, Sisya, Ndaviti atũmie atũmwa kuma weũnĩ makethye vwana waitũ; nake amauma.'),
('kam', '1SA', 25, 15, 'Ĩndĩ ala andũ matwĩkaa nesa mũno, na tũtyaaĩkwa naĩ, o na tũtyaasya kĩndũ, o yĩla twaendanasya nao, yĩla twaĩ weũnĩ:'),
('kam', '1SA', 25, 16, 'mailyĩ ta ũvai kwitũ ũtukũ o na mũthenya, ĩvinda yonthe yĩla twaĩ namo tũkĩĩthya malondu.'),
('kam', '1SA', 25, 17, 'Yu ĩndĩ manya na ũisũanĩa ũndũ wĩĩka; nũndũ ũthũku nũtw’ĩtwe ĩũlũ wa vwana waitũ, na ĩũlũ wa nyũmba yake yonthe; nũndũ nĩ mũndũ ũte kĩĩĩ ũndũ mũndũ ũtatonya kũneena nake.'),
('kam', '1SA', 25, 18, 'Nĩvo ĩndĩ Avikaili wekalaatile, na oosa imũtũ maana elĩ, na tũthatwa twĩlĩ twa mbinyu, na malondu atano me mathĩnze, na ithimi itano sya lĩu wa mbaa ngetha mũkaange, na itũngo ĩana sya nzavivũ mbovu, na tũkũmbwa maana elĩ twa makũyũ, na aĩkya mang’oi.'),
('kam', '1SA', 25, 19, 'Na amea anake make, Endai mbee wakwa; sisya, nĩngũmũatĩĩa. Ĩndĩ ndaatavya mũũme wake Navali.'),
('kam', '1SA', 25, 20, 'Na kweethĩwa, yĩla wakuĩtwe nĩ ĩng’oi yake, na akĩtheea athw’ĩkĩtwe nĩ kĩĩma, sisya, Ndaviti na andũ make matheea mamwelekele; na akomana namo.'),
('kam', '1SA', 25, 21, 'Na ĩndĩ Ndaviti aĩtye, Vate ndĩi nasũvĩie mana syonthe ila mũndũ ũũ wĩ nasyo weũnĩ, ũndũ vate kĩndũ kĩmwe kyaaie kya syonthe ila syake: nake nũndũngĩĩte ũthũku vandũ va ũseo.'),
('kam', '1SA', 25, 22, 'Ngai eke amaitha ma Ndaviti ũu, o na mbee, ethĩwa nĩngũmũtialĩlya o na mwana mũũme ũmwe kũvika kĩoko kũikya.'),
('kam', '1SA', 25, 23, 'Na yĩla Avikaili wamwonie Ndaviti, eekalaata, na auma ĩng’oinĩ yake, na avalũka na ũthyũ wake mbee wa Ndaviti, na eekunamya kũvika nthĩ.'),
('kam', '1SA', 25, 24, 'Na avalũka maũũnĩ make, na amwĩa, Ĩũlũ wakwa, mwĩaĩi wakwa, ĩũlũ wakwa wĩthĩwe ũla ũthũku; na nĩngũkwĩsũva, mũthũkũmi waku mwĩĩtu naneene matũnĩ maku, naku wĩthukĩĩsye ndeto sya mũthũkũmi waku mwĩĩtu.'),
('kam', '1SA', 25, 25, 'Nĩngũkwĩsũva, mwĩaĩi wakwa ndakasisye mũndũ ũũ ũte kĩĩĩ, o Navali; nũndũ o ũndũ syĩtwa yake yĩtilyĩ, now’o ũtilyĩ; Navali nĩ syĩtwa yake, na ũtumanu wĩ nake: ĩndĩ mũthũkũmi waku mwĩĩtu ndaneona anake ma mwĩaĩi wakwa, ala ũnatũmie.'),
('kam', '1SA', 25, 26, 'Yu ĩndĩ, mwĩaĩi wakwa, o tondũ Yeova wĩ thayũ, na o tondũ kyuu kyaku kĩ thayũ, nũndũ Yeova nũkũsiĩĩie ndũkethĩwe na ĩvĩtyo ya kwĩtĩkya nthakame, na kana ndũkekũlanĩlye na kw’oko kwaku mwene, yu ĩndĩ amaitha maku, na ala mamanthaa kwĩka mwĩaĩi wakwa naĩ, methĩwe ta Navali.'),
('kam', '1SA', 25, 27, 'Na yu mũthĩnzĩo ũũ ũla mũthũkũmi waku ũetee mwĩaĩi wakwa, ũnengwe anake ala maatĩĩaa mwĩaĩi wakwa.'),
('kam', '1SA', 25, 28, 'Nĩngũkwĩsũva, ekea ĩvĩtyo ya mũthũkũmi waku mwĩĩtu: nũndũ Yeova ndatĩa kũseũvĩsya mwĩaĩi wakwa nyũmba nũmu, nĩkwĩthĩwa mwĩaĩi wakwa nĩwũkitĩthasya makaũ ma Yeova; na ũthũku ndũkoneka nthĩnĩ waku matukũ maku onthe.'),
('kam', '1SA', 25, 29, 'Na o na ethĩwa mũndũ nĩwũkĩlĩte akũatĩĩe, na kũmantha thayũ waku, ĩndĩ thayũ wa mwĩaĩi wakwa ũkoovanĩw’a kyovenĩ kya thayũ vamwe na Yeova Ngai waku; na mathayũ ma amaitha maku akamekya ũtee, o ta kamatanĩ ka kĩkũtha.'),
('kam', '1SA', 25, 30, 'Na kũkeethĩwa, yĩla Yeova wĩĩthĩwa amwĩkĩte mwĩaĩi wakwa kwĩanana na ũseo w’onthe ũla ũneenete ũndũ waku, na ethĩwa akwiĩte mũnene wĩ mbee ũsumbĩnĩ ĩũlũ wa Isilaeli,'),
('kam', '1SA', 25, 31, 'atĩ ũndũ ũũ ndũkethĩwa wa woo kwaku, o na ũlulutĩkyo wa ngoo kwa mwĩaĩi wakwa, ũndũ wetĩkĩsye nthakame vate kĩtumi, o na kana mwĩaĩi wakwa nĩwĩkũlĩte. Na yĩla Yeova wĩĩthĩwa amwĩkĩte mwĩaĩi wakwa nesa, yu ĩndĩ wĩlilikana mũthũkũmi waku mwĩĩtu.'),
('kam', '1SA', 25, 32, 'Na Ndaviti amwĩa Avikaili, Nataĩwe Yeova, Ngai wa Isilaeli, ũla ũkũtũmie ũmũnthĩ ũkomane nakwa:'),
('kam', '1SA', 25, 33, 'na ũathimwe ũmanyi waku, na ĩthĩwa wĩ mũathime we, ũla ũnziĩĩie ũmũnthĩ ndikethĩwe na ĩvĩtyo ya kwĩtĩkya nthakame, na ndikekũle na kw’oko kwakwa mwene.'),
('kam', '1SA', 25, 34, 'Nũndũ nĩ w’o ki, o tondũ Yeova, Ngai wa Isilaeli, wĩ thayũ, ũla ũnziĩĩie ndikakwĩke naĩ, keka wĩkalaatile na kũka ũnthaũe, kĩoko kũikya kũtyĩthĩwa Navali atialĩlwa nĩ mwana mũũme o na ũmwe.'),
('kam', '1SA', 25, 35, 'Kwondũ wa ũu Ndaviti oosa kw’okonĩ kwake ila wamũetee: na amwĩa, Ambata na mũuo nyũmbanĩ yaku; sisya, nĩnĩthukĩĩisye wasya waku, na nĩnakwĩtĩkĩlĩla.'),
('kam', '1SA', 25, 36, 'Na Avikaili avika vala ve Navali; na, sisya, avokete mboka nyũmbanĩ yake, o ta mboka ya mũsumbĩ; na ngoo ya Navali yatanĩaa o nthĩnĩ wake, nũndũ amilĩtwe mũno: kwondũ wa ũu ndaamũtavya ũndũ ũnini kana ũnene, kũvika kĩoko kũikya.'),
('kam', '1SA', 25, 37, 'Na kweethĩwa kĩoko kyu, yĩla mbinyu yaĩ ĩnamũlekya Navali, kĩveti kyake kyamũtavya maũndũ asu, na ngoo yake yakw’a nthĩnĩ wake, na atw’ĩka ta ĩvia.'),
('kam', '1SA', 25, 38, 'Na kweethĩwa ĩtina wa ũu ta matukũ ĩkũmi, Yeova amũkũna Navali, na ĩndĩ akw’a.'),
('kam', '1SA', 25, 39, 'Na yĩla Ndaviti wewie kana Navali aĩ mũkw’ũ, asya, Nataĩwe Yeova, ũla ũteteete ũndũ wa kũvũthw’a kwakwa kũla kumĩte kw’okonĩ kwa Navali, na nũsiĩĩĩte mũthũkũmi wake ndakeke ũthũku: na Yeova nũtũngĩte wĩko mũthũku wa Navali mũtwenĩ wake mwene. Na Ndaviti atũmana Avikaili akaneenwe nake amũtwae ethĩwe mũka.'),
('kam', '1SA', 25, 40, 'Na yĩla athũkũmi ma Ndaviti mavikie kwa Avikaili ku Kalimeli, maneena nake, makĩmwĩa, Ndaviti nũtũtũmĩte kwaku, kũkũtwaa kwake wĩthĩwe mũka.'),
('kam', '1SA', 25, 41, 'Nake ookĩla, na eekunamya na ũthyũ wake kũvika nthĩ, na asya, Sisya, mũthũkũmi waku mwĩĩtu nĩ mũthũkũmi wa kũthambya maũũ ma athũkũmi ma mwĩaĩi wakwa.'),
('kam', '1SA', 25, 42, 'Na Avikaili eekalaata, na ookĩla, na athi akuĩtwe nĩ ĩng’oi, e na eĩtu atano ala mamũatĩĩaa; na avikĩla atũmwa ma Ndaviti, na atw’ĩka mũka wake.'),
('kam', '1SA', 25, 43, 'Na Ndaviti atwaa Ainoamu wa Yesileeli nake; na matw’ĩka me elĩ aka make.'),
('kam', '1SA', 25, 44, 'Na ĩndĩ Saulo aĩ ananenga Valiti mwana wa Laisa, ũla wa ku Ngalimu, Mikali mwĩĩtu wake, kĩveti kya Ndaviti.'),
('kam', '1SA', 26, 1, 'Na Anzivu mooka kwa Saulo ku Ngivea, makyasya, Ndaviti ndevithĩte kĩĩmanĩ kya Akila, kĩla kyelekele yalatanĩ?'),
('kam', '1SA', 26, 2, 'Nĩvo ĩndĩ Saulo wokĩlile, na atheea weũnĩ wa ku Nzivu, e na andũ anyuve ngili itatũ sya Isilaeli vamwe nake, amanthe Ndaviti weũnĩ wa Nzivu.'),
('kam', '1SA', 26, 3, 'Na Saulo amba maeema nzĩanĩ, kĩĩmani kya Akila, kĩla kyelekele yĩla yalata. Ĩndĩ Ndaviti atũaa weũnĩ, na oona kana Saulo nũmũatĩĩe weũnĩ.'),
('kam', '1SA', 26, 4, 'Kwondũ wa ũu Ndaviti atũma athiani, na amanya kana Saulo nĩ mũku vate nzika.'),
('kam', '1SA', 26, 5, 'Na Ndaviti ookĩla, na avika vandũ vala Saulo wambĩte maeema; na Ndaviti oona vandũ vala Saulo wakomete, e na Avineli mwana wa Neli, kavuteni wa nguthu yake: na Saulo akomete katĩ wa vala vandũ vaĩ makasya, na andũ nĩmambĩte maeema mamũthyũlũlũkĩte.'),
('kam', '1SA', 26, 6, 'Nĩvo ĩndĩ Ndaviti wasũngĩie na akũlya Aimeleki Mũititi, na Avisai mwana wa Nzeluia, mwana‐a‐inyia wa Yoavu, akyasya, Ũla wĩtheea nakwa kwa Saulo mwakonĩ wa maeema nũũ? Na Avisai amwĩa, Nyie nĩngũtheea naku.'),
('kam', '1SA', 26, 7, 'Na ĩndĩ Ndaviti na Avisai mavika kũla kwĩ andũ ũtukũ: na, sisya, Saulo akomete too katĩ wa vala vandũ vaĩ makasya, e na ĩtumo yake yĩtonyete nthĩ mũtwenĩ wake; na Avineli na andũ makomete mamũthyũlũlũkĩte.'),
('kam', '1SA', 26, 8, 'Nĩvo ĩndĩ Avisai wamwĩie Ndaviti, Ngai nũnenganĩte mũmaitha waku kw’okonĩ kwaku ũmũnthĩ: yu ĩndĩ, nĩngũkwĩsũva, eka nĩmũtonyanĩsye na nthĩ na ĩtumo ĩtonya o yĩmwe, na ndimũtonya ĩvinda ya kelĩ.'),
('kam', '1SA', 26, 9, 'Na Ndaviti amwĩa Avisai, Ndũkamwanange; nũndũ nũũ ũtonya kũtambũũkĩsya mwĩtĩkĩw’a mauta wa Yeova kw’oko kwake, na akethĩwa ate ĩvĩtyo?'),
('kam', '1SA', 26, 10, 'Na Ndaviti asya, O tondũ Yeova wĩ thayũ, Yeova akamũkũna; kana mũthenya wake ũkavika akw’e; kana akatheea kaũnĩ, na kwaa.'),
('kam', '1SA', 26, 11, 'Yeova ndakandeke nĩtambũũkĩsye mwĩtĩkĩw’a mauta wa Yeova kw’oko kwakwa: ĩndĩ yu, nĩngũkwĩsũva, osa ĩtumo yĩla yĩ mũtwenĩ wake, na sũva wa manzĩ, na tũkĩthi.'),
('kam', '1SA', 26, 12, 'Na ĩndĩ Ndaviti oosa yĩla ĩtumo na ũla sũva wa manzĩ mũtwenĩ wa Saulo; namo mathi: na vati mũndũ waaona ũndũ ũsu, kana akomanya, o na vati waaamũka; nũndũ onthe nĩmakomete, nĩkwĩthĩwa too mũnene waumĩte kwa Yeova nĩwamavalũkĩle.'),
('kam', '1SA', 26, 13, 'Nĩvo ĩndĩ Ndaviti wainganĩsye ngalĩ ĩla ĩngĩ, na aũngama kũasa mũtumbĩnĩ wa kĩĩma; ve mwanya mũnene katĩ woo;'),
('kam', '1SA', 26, 14, 'na Ndaviti anĩĩsya andũ, na Avineli mwana wa Neli, akyasya, Ndũtumũa, Avineli? Nĩvo ĩndĩ Avineli wasũngĩie na akũlya, Nue ũũ ũkwanĩĩsya mũsumbĩ?'),
('kam', '1SA', 26, 15, 'Na Ndaviti amwĩa Avineli, Ndwĩ o mũndũ ngũmbaũ? Na nũũ nthĩnĩ wa Isilaeli ũilyĩ taku? Na nĩkĩ ũtanasũvĩa mwĩaĩi waku mũsumbĩ? Nũndũ kũlikile ũmwe wa andũ anange mũsumbĩ mwĩaĩi waku.'),
('kam', '1SA', 26, 16, 'Ũndũ ũũ wĩkie ti ũseo. O tondũ Yeova wĩ thayũ, inyw’ĩ nĩmwaĩle kũkw’a, nĩkwĩthĩwa mũtinasũvĩa mwĩaĩi wenyu, mwĩtĩkĩw’a mauta wa Yeova. Na yu onai ĩtumo ya mũsumbĩ kũla yĩĩ, na sũva wa manzĩ ũla wĩĩ mũtwenĩ wake.'),
('kam', '1SA', 26, 17, 'Na Saulo amanya wasya wa Ndaviti, na akũlya, Wasya ũũ nĩ waku, mwana wakwa Ndaviti? Na Ndaviti asũngĩa, Nĩ wasya wakwa, mwĩaĩi wakwa, we mũsumbĩ.'),
('kam', '1SA', 26, 18, 'Na akũlya, Mwĩaĩi wakwa aatĩĩaa mũthũkũmi wake nĩkĩ? Nũndũ nĩkĩte ata? Kana nĩ ũthũku mwaũ wĩ kw’okonĩ kwakwa?'),
('kam', '1SA', 26, 19, 'Na yu ĩndĩ, nĩngũkwĩsũva, mwĩaĩi wakwa mũsumbĩ nĩew’e ndeto sya mũthũkũmi wake. Ethĩwa nĩ Yeova ũkũthokoanĩtye nakwa, nĩetĩkĩle nthembo: ĩndĩ ethĩwa nĩ ana ma andũ, nĩmaumanĩwe kũla kwĩ Yeova; nũndũ nĩmandũngĩtye ũmũnthĩ ndikalũman’ye na ũtiĩwa wa Yeova, makĩmbĩa, Thi, ũkathũkũme ngai ingĩ.'),
('kam', '1SA', 26, 20, 'Yu ĩndĩ, nthakame yakwa ndĩkavalũke nthĩ kuma kũla kwĩ Yeova: nũndũ mũsumbĩ wa Isilaeli nĩwumaalĩte amanthe ngala o ta ũmwe ũsyĩmaa ngwae iĩmanĩ.'),
('kam', '1SA', 26, 21, 'Nĩvo ĩndĩ Saulo waisye, Nĩnĩvĩtĩtye: syoka, mwana wakwa Ndaviti; nũndũ ndikakwĩka ũthũku ĩngĩ, nĩkwĩthĩwa thayũ wakwa wĩĩ na vata kwaku ũmũnthĩ: sisya, nĩnĩkanganĩtye ta ndia, na nĩnĩvĩtĩtye mũno mũnene.'),
('kam', '1SA', 26, 22, 'Na Ndaviti asũngĩa na amwĩa, Sisya yĩla ĩtumo, we mũsumbĩ! Mwanake ũmwe ĩndĩ nĩoke ayose.'),
('kam', '1SA', 26, 23, 'Na Yeova akatũngĩa kĩla mũndũ ũlũngalu wake na kĩthito kyake; nũndũ Yeova nũkũnenganie kw’okonĩ kwakwa ũmũnthĩ, na ndinetĩkĩla kũtambũũkĩsya mwĩtĩkĩw’a mauta wa Yeova kw’oko kwakwa.'),
('kam', '1SA', 26, 24, 'Na, sisya, o tondũ thayũ waku wĩĩ na vata kwakwa mũthenya ũũ, o ta ũu thayũ wakwa wĩthĩwe na vata kwa Yeova, na nambonokye ũnyamaonĩ w’onthe.'),
('kam', '1SA', 26, 25, 'Nĩvo ĩndĩ Saulo wamwĩie Ndaviti, Ĩthĩwa wĩ mũathime we, mwana wakwa Ndaviti: ũkeeka na ũtonyi, o na ũkakĩlya vinya vate ndĩi. Na ĩndĩ Ndaviti eeendea, na Saulo asyoka vandũ vake.'),
('kam', '1SA', 27, 1, 'Na Ndaviti aneena ngoonĩ yake, Ngaaĩa ĩndĩ mũthenya ũmwe kw’okonĩ kwa Saulo: kũti ũndũ ũseo kwakwa kwĩ kwĩvonokesya nthĩ ya Avilisiti; na Saulo akeeyĩtũka ũndũ wakwa, kũmantha ĩngĩ mĩvakanĩ yonthe ya Isilaeli: na ĩndĩ ngavonoka kuma kw’okonĩ kwake.'),
('kam', '1SA', 27, 2, 'Na Ndaviti ookĩla na ainga, we na ala andũ maana thanthatũ ala maĩ vamwe nake, mathi kwa Akisi mwana wa Maoki, mũsumbĩ wa Ngathi.'),
('kam', '1SA', 27, 3, 'Na Ndaviti atũa na Akisi ku Ngathi, we na andũ make, kĩla mũndũ na andũ ma nyũmba yake, o Ndaviti e na aka make elĩ, Ainoamu Mũyesileeli, na Avikaili Mũkalimeli, ũla waĩ kĩveti kya Navali.'),
('kam', '1SA', 27, 4, 'Na kwataviw’e Saulo atĩ Ndaviti nĩwakĩie athi Ngathi: na ndaamũmantha ĩngĩ nongi.'),
('kam', '1SA', 27, 5, 'Na Ndaviti amwĩa Akisi, Ethĩwa yu nĩnonete ũseo kwaku, nĩmanenge vandũ ndũanĩ ĩmwe yĩ nthĩ yĩ ũtee, nĩ kana nĩtũe vo: nũndũ mũthũkũmi waku etũa naku ndũanĩ ya kĩũsumbĩ nĩkĩ?'),
('kam', '1SA', 27, 6, 'Nĩvo ĩndĩ Akisi wamũnengie Nzikilaki mũthenya ũsu: kwondũ wa ũu Nzikilaki nĩyĩkalaa ya asumbĩ ma Yuta kũvika ũmũnthĩ.'),
('kam', '1SA', 27, 7, 'Na ũtalo wa matukũ ala Ndaviti watũie nthĩ ya Avilisiti waĩ mwaka mũima na myei ĩna.'),
('kam', '1SA', 27, 8, 'Na Ndaviti na andũ make mambata, na mavithũkĩa Angesuli, na Angilisi, na Aamaleki; nũndũ mbaĩ isu syaĩ ĩla syatwĩe nthĩ ĩsu, ila syaĩ sya tene, ũendete Suli, o kũvika nthĩ ya Misili.'),
('kam', '1SA', 27, 9, 'Na Ndaviti akũna ĩ nthĩ, na ndaatialya mũndũ mũũme kana mũndũ mũka e thayũ, na atwaa malondu, na ng’ombe, na mang’oi, na ngamĩle, na ngũa; na asyoka, na avika kwa Akisi.'),
('kam', '1SA', 27, 10, 'Na Akisi amũkũlya, Ũvithũkie kwaaũ ũmũnthĩ? Na Ndaviti amũsũngĩa, Tũvithũkie ngalĩ ya Ĩtheo ya Yuta, na ngalĩ ya Ĩtheo ya Ayelameeli, na ngalĩ ya Ĩtheo ya Akeni.'),
('kam', '1SA', 27, 11, 'Na Ndaviti ndaatialya mũndũ mũũme o na mũndũ mũka e thayũ, nĩ kana amaete Ngathi, akyasya, Matikese kumbũla ũndũ witũ, makyasya, Ũu now’o Ndaviti wekaa, na now’o wailyĩ ĩvinda yonthe yĩla wekalaa nthĩ ya Avilisiti.'),
('kam', '1SA', 27, 12, 'Na Akisi eetĩkĩla Ndaviti, akyasya, Nũtumĩte andũ make Isilaeli mamũthĩtha mũno vyũ; kwondũ wa ũu akeethĩwa mũthũkũmi wakwa tene na tene.'),
('kam', '1SA', 28, 1, 'Na kweethĩwa mĩthenya ĩsu, Avilisiti moomban’ya nguthu syoo kwondũ wa kaũ, mokite na Isilaeli. Na Akisi amwĩa Ndaviti, Manya vate ndĩi, kana ũkaumaala vamwe nakwa nguthunĩ, we na andũ maku.'),
('kam', '1SA', 28, 2, 'Na Ndaviti amwĩa Akisi, Kwondũ wa ũu ũkamanya ũndũ mũthũkũmi waku wĩĩka. Na Akisi amwĩa Ndaviti, Kwondũ wa ũu ngaũtw’ĩkĩthya mũsũvĩi wa mũtwe wakwa tene na tene.'),
('kam', '1SA', 28, 3, 'Na yu Samueli aĩ mũkw’ũ, na Isilaeli onthe nĩmamũĩĩĩte, na mamũthikĩte ku Lama, o ndũanĩ yake mwene. Na Saulo aĩ anaveta asu mesene na maveva, na ala mombasya ithitũ, makauma nthĩ.'),
('kam', '1SA', 28, 4, 'Na Avilisiti moombana, na mooka na mamba maeema Sunemu; na Saulo oomban’ya Isilaeli onthe vamwe, na mamba maeema Ngilivoa.'),
('kam', '1SA', 28, 5, 'Na yĩla Saulo wonie nguthu ya Avilisiti aĩ na w’ĩa, na ngoo yake yatetema mũno.'),
('kam', '1SA', 28, 6, 'Na yĩla Saulo wakũlilye Yeova, Yeova ndaamũsũngĩa, na ndoto, o na Ulimu, o na athani.'),
('kam', '1SA', 28, 7, 'Nĩvo Saulo wameie athũkũmi make, Manthĩai mũndũ mũka wĩsene na veva, nĩ kana nĩende kwake, na ngĩkũlya kwake. Na athũkũmi make mamwĩa, Sisya, kwĩ mũndũ mũka wĩsene na veva ku Eni‐ndoli.'),
('kam', '1SA', 28, 8, 'Na Saulo eeyũlan’ya, na eekĩa ngũa ingĩ, na athĩ, we na andũ elĩ vamwe nake, na mavika kwa ũla mũndũ mũka ũtukũ: na amwĩa, Nĩngũkwĩsũva, ngaũĩsya na ũla veva wĩsene naw’o, na ũimbũkĩlĩlya o ũla nĩweta kwaku.'),
('kam', '1SA', 28, 9, 'Na ũla mũndũ mũka amwĩa, Sisya, nĩwĩsĩ ũndũ Saulo wĩkĩte, ũndũ ũvetete asu mesene na maveva, na ala mombasya ithitũ, makauma nthĩ: nĩkĩ ĩndĩ ũũtea kĩtei ũndũ wa thayũ wakwa, ũtume nĩkw’a?'),
('kam', '1SA', 28, 10, 'Na Saulo amwĩavĩa na Yeova, akĩmwĩa, O tondũ Yeova wĩ thayũ kũtikethĩwa ũsilĩlo o na wĩva ũkũkwata kwondũ wa ũndũ ũũ.'),
('kam', '1SA', 28, 11, 'Nĩvo ĩndĩ ũla mũndũ mũka wamũkũlilye, Nĩkumĩlĩlya ũũ? Nake asũngĩa, Mbumĩlĩlya Samueli.'),
('kam', '1SA', 28, 12, 'Na yĩla ũ mũndũ mũka wonie Samueli, akaya na wasya mũnene; na ũla mũndũ mũka aneena na Saulo, akyasya, Wangengea kĩ? Nũndũ nue Saulo.'),
('kam', '1SA', 28, 13, 'Na mũsumbĩ amwĩa, Ndũkakĩe: wĩona kyaũ ĩndĩ? Na mũndũ mũka amwĩa Saulo, Nĩngwona ngai yũkĩte kuma nthĩnĩ wa nthĩ.'),
('kam', '1SA', 28, 14, 'Nake amũkũlya, Avw’ana ata? Nake asũngĩa, Mũtumĩa mũkũũ nĩwambatĩte; na evw’ĩkĩte ngũa ndasa. Na Saulo amanya kana nĩ Samueli, na akunamya ũthyũ wake nthĩ, na eekunamya vyũ.'),
('kam', '1SA', 28, 15, 'Na Samueli akũlya Saulo, Ũnthokoanĩsye kĩ ũmbambatye? Na Saulo asũngĩa, Nĩ mũthĩnu mũno; nũndũ Avilisiti nĩmeũkwatya kaũ nakwa, na Ngai nũndiĩte, o na ndanzũngĩaa ĩngĩ, na athani, o na ndoto: kwondũ wa ũu nakwĩta, nĩ kana ũmanyĩthye ũndũ ngwĩka.'),
('kam', '1SA', 28, 16, 'Na Samueli amũkũlya, Wĩngũlya nĩkĩ ĩndĩ, na Yeova nake nũkũtiĩte, na atw’ĩkĩte mũmaitha waku?'),
('kam', '1SA', 28, 17, 'Na Yeova nũkwĩkĩte, o tondũ waneenie na kanyw’a wakwa: na Yeova nũvenanĩte ũsumbĩ kw’okonĩ kwaku, na akonenga mũtũi waku, o Ndaviti.'),
('kam', '1SA', 28, 18, 'Nĩkwĩthĩwa ndwĩw’aa wasya wa Yeova, na ndwaaĩka Amaleki kwĩanana na ũthilĩku wake mwai, kwondũ wa ũu Yeova nũkwĩkĩte ũndũ ũũ ũmũnthĩ.'),
('kam', '1SA', 28, 19, 'O na ĩngĩ Yeova akanengane Isilaeli o vamwe naku kw’okonĩ kwa Avilisiti; na ũnĩ we na ana maku mũkeethĩwa vamwe nakwa: Yeova nake akanengane nguthu ya Isilaeli nayo kw’okonĩ kwa Avilisiti.'),
('kam', '1SA', 28, 20, 'Nĩvo ĩndĩ o mĩtũkĩ Saulo wavalũkile nthĩ na mwĩĩ w’onthe, na aĩ na w’ĩa mũno, nũndũ wa ndeto sya Samueli: o na vatyaĩ vinya nthĩnĩ wake; nũndũ ndaĩte lĩu mũthenya ũsu w’onthe, na ũtukũ ũsu w’onthe.'),
('kam', '1SA', 28, 21, 'Na ũla mũndũ mũka amũkĩa Saulo, na oona kana aũũyĩte mũno, na amwĩa, Sisya, mũthũkũmi waku mwĩĩtu nĩwĩthukĩĩisye wasya waku, na nĩniie thayũ wakwa kw’okonĩ kwakwa, na nĩnĩthukĩĩisye ndeto syaku ila ũneenie nakwa.'),
('kam', '1SA', 28, 22, 'Yu ĩndĩ, nĩngũkwĩsũva, ĩthukĩĩsye naku wasya wa mũthũkũmi waku mwĩĩtu, na ndeka nĩkũathĩsye lĩu mũnini; na ũiya, nĩ kana wĩthĩwe na vinya, wĩendeete.'),
('kam', '1SA', 28, 23, 'Ĩndĩ alea, na asya, Ndiya. Ĩndĩ athũkũmi make, vamwe na ũ mũndũ mũka mamũingĩĩsya; nake eethukĩĩsya wasya woo. Kwondũ wa ũu ookĩla nthĩ, na ekala ũkomonĩ.'),
('kam', '1SA', 28, 24, 'Na ũ mũndũ mũka aĩ na kasaũ kanou nyũmbanĩ; na eekalaata, na akoaa; na oosa mũtu, na awũmba, na eekĩa iko aseũvya kĩmũtũ kĩte ĩlawa naw’o:'),
('kam', '1SA', 28, 25, 'na akĩete mbee wa Saulo, na mbee wa athũkũmi make; na maya. Na ĩndĩ mookĩla, na mathi ũtukũ ũsu.'),
('kam', '1SA', 29, 1, 'Na ĩndĩ Avilisiti moombanĩsya nguthu syoo syonthe Aveki: na Aisilaeli mamba maeema vakuvĩ na nthongo ĩla yĩ Yesileeli.'),
('kam', '1SA', 29, 2, 'Na eaĩi ma Avilisiti maenda mbee me maana, na me ngili ngili, na Ndaviti na andũ make maenda ĩtina me na Akisi.'),
('kam', '1SA', 29, 3, 'Nĩvo ĩndĩ anene me mbee ũsumbĩnĩ ma Avilisiti makũlilye, Aevelania meĩka ata vaa? Na Akisi amea anene me mbee ũsumbĩnĩ ma Avilisiti, Ũũ ti Ndaviti, mũthũkũmi wa Saulo mũsumbĩ wa Isilaeli, ũla wĩkalĩte nakwa matukũ asu, kana o myaka ĩsu, na ndyaaona ĩvĩtyo nthĩnĩ wake kuma yĩla wetilile ooka kwakwa kũvika ũmũnthĩ?'),
('kam', '1SA', 29, 4, 'Ĩndĩ anene me mbee ũsumbĩnĩ ma Avilisiti mamũthilĩkĩla; na anene me mbee ũsumbĩnĩ ma Avilisiti mamwĩa, Tũngĩthya ũ mũndũ, nĩ kana asyoke vandũ vake vala ũmũtw’ĩĩte, na ndũkamũeke atheee naitũ kaũnĩ, ndakese ũtũtw’ĩkĩa nthũ kaũnĩ: nũndũ mũndũ ũũ akeyĩw’anĩthya na mwĩaĩi wake ata? Ti o na mĩtwe ya andũ aa?'),
('kam', '1SA', 29, 5, 'Ũũ ti Ndaviti, ũla mamwinĩe makĩtĩkĩanĩsya ene kwa ene makĩsũnga, makyasya, Saulo nĩwũaĩte ngili syake, Na Ndaviti ngili syake makũmi?'),
('kam', '1SA', 29, 6, 'Nĩvo ĩndĩ Akisi wamwĩtie Ndaviti, na amwĩa, O tondũ Yeova wĩ thayũ, nĩwĩthĩĩtwe mũlũngalu, na kumaala kwaku na kũlika kwaku vamwe nakwa nguthunĩ nĩ kũseo vala nĩĩ; nũndũ ndyaaona ũthũku nthĩnĩ waku kuma mũthenya ũla wookie kwakwa kũvika ũmũnthi: ĩndĩ ala eaĩi matyonaa wĩ mũseo.'),
('kam', '1SA', 29, 7, 'Kwondũ wa ũũ ĩndĩ syoka, na ũkĩthi na mũuo, nĩ kana ndũkew’ĩthye eaĩi ma Avilisiti woo.'),
('kam', '1SA', 29, 8, 'Na Ndaviti akũlya Akisi, Ĩndĩ nĩkĩte ata? Na wonete ata mũthũkũminĩ waku ĩvinda yĩu yonthe nĩthĩĩtwe vala ũĩ kũvika ũmũnthĩ, kana ndikatonye kũthi na kũkita na amaitha ma mwĩaĩi wakwa mũsumbĩ?'),
('kam', '1SA', 29, 9, 'Na Akisi asũngĩa na amwĩa Ndaviti, Nĩnĩsĩ wĩ mũseo kwakwa, o ta mũlaĩka wa Ngai: ĩndĩ vamwe na ũu anene me mbee ũsumbĩnĩ ma Avilisiti nĩmaĩtye, Ndakaenda naitũ kaũnĩ.'),
('kam', '1SA', 29, 10, 'Kwondũ wa ũu ĩndĩ ũkĩla kĩoko tene wĩ na athũkũmi ma mwĩaĩi waku ala manokie vamwe naku; na o yĩla mwĩũkĩla kĩoko tene, na kwona nthĩ, endai.'),
('kam', '1SA', 29, 11, 'Kwondũ wa ũu Ndaviti ookĩla tene, we na andũ make, nĩ kana mathi kĩoko, masyoke nthĩ ya Avilisiti. Na Avilisiti mambata ku Yesileeli.'),
('kam', '1SA', 30, 1, 'Na kweethĩwa, yĩla Ndaviti na andũ make mavikĩte Nzikilaki mũthenya wa katatũ, Aamaleki maĩ manavithũkĩa ngalĩ ya Ĩtheo, na Nzikilaki, na maĩ manakũna Nzikilaki, na kũmĩvĩvya na mwaki,'),
('kam', '1SA', 30, 2, 'na maĩ manatava aka na onthe ala maĩ nthĩnĩ wayo, anini o na anene: matyaaũaa o na ũmwe, ĩndĩ mamatwaa, na meeendea.'),
('kam', '1SA', 30, 3, 'Na yĩla Ndaviti na andũ make mavikie ndũanĩ, sisya, yaĩ mbĩvye na mwaki; na iveti syoo, na ana moo, na eĩtu moo, maĩ atave.'),
('kam', '1SA', 30, 4, 'Nĩvo ĩndĩ Ndaviti na andũ ala maĩ nake mookĩlilye wasya woo na kũĩa, kũvika matyaĩ na ũtonyi ũngĩ wa kũĩa.'),
('kam', '1SA', 30, 5, 'Na iveti ilĩ sya Ndaviti nĩsyataviwe, Ainoamu Mũyesileeli, na Avikaili ũla waĩ kĩveti kya Navali Mũkalimeli.'),
('kam', '1SA', 30, 6, 'Na Ndaviti aũũya mũno; nũndũ andũ maneenie ũndũ wa kũmũkima na mavia, nĩkwĩthĩwa ngoo sya andũ onthe syeew’aa woo, kĩla mũndũ ũndũ wa ana make na eĩtu make: ĩndĩ Ndaviti eeyĩkĩa vinya nthĩnĩ wa Yeova Ngai wake.'),
('kam', '1SA', 30, 7, 'Na Ndaviti amwĩa mũthembi Aviathali, mwana wa Aimeleki, Nĩngũkwĩsũva, ndetee evoti vaa. Na Aviathali amũtwaĩa Ndaviti ĩla evoti.'),
('kam', '1SA', 30, 8, 'Na Ndaviti akũlya Yeova, akyasya, Ethĩwa nĩngũatĩĩa nguthu ĩno, ngamĩwĩla? Nake amũsũngĩa, Atĩĩa; nũndũ nĩ w’o ũkamĩwĩla, na ũkeetũngĩa syonthe vate ndĩi.'),
('kam', '1SA', 30, 9, 'Kwondũ wa ũu Ndaviti athi, we na andũ maana thanthatũ ala maĩ vamwe nake, na mavika kalũsĩnĩ ketawa Mbesoli, vala ala matiĩtwe ĩtina mekalĩte.'),
('kam', '1SA', 30, 10, 'Ĩndĩ Ndaviti aatĩĩaa, we na andũ maana ana; nũndũ maana elĩ matiĩlĩtwe ĩtina, ala maĩ anyalu ũndũ matatonya kũinga kala kalũsĩ Mbesoli.'),
('kam', '1SA', 30, 11, 'Na meethĩa Mũmisili weũnĩ, na mamũetee Ndaviti, na mamũnenga lĩu, na aya; na mamũnenga manzĩ anyw’e;'),
('kam', '1SA', 30, 12, 'na mamũnenga kĩlungu kya kakũmbwa ka makũyũ, na itũngo ilĩ sya nzavivũ mbovu: na amina ũya, veva wake wamũsyokea ĩngĩ; nũndũ ndaĩte lĩu, o na kũnyw’a manzĩ mĩthenya ĩtatũ na matukũ atatũ.'),
('kam', '1SA', 30, 13, 'Na Ndaviti amũkũlya, Wĩ waũ? Na wumĩte va? Na asũngĩa, Nyie nĩ mwanake wa ku Misili, mũthũkũmi wa Mũamaleki; na vwana wakwa nĩwandiie, nĩkwĩthĩwa yu nĩ matukũ atatũ nĩ mũwau.'),
('kam', '1SA', 30, 14, 'Nĩtwavithũkie ngalĩ ya Ĩtheo ya Akelethi, na kũla kwa Yuta, na ngalĩ ya Ĩtheo ya Kalevu; na twavĩvya Nzikilaki na mwaki.'),
('kam', '1SA', 30, 15, 'Na Ndaviti amũkũlya, Ũkandwaa kũla kwĩ nguthu ĩsu? Na asũngĩa, Mbĩavĩa Ngai, kana ndũkambũaa, o na kũnengane mokonĩ ma vwana wakwa, nakwa ngakũtheesya kũla kwĩ nguthu ĩsu.'),
('kam', '1SA', 30, 16, 'Na yĩla wamũtheeisye, sisya, manyaĩĩkĩte nthĩ yonthe, makĩya, na makĩnyw’a, na makĩsũnga, nũndũ wa mũtavo ũsu w’onthe mũnene ũla matavĩte nthĩ ya Avilisiti, na nthĩ ya Yuta.'),
('kam', '1SA', 30, 17, 'Na Ndaviti amakũna kuma kwĩ ũmithi o kũvika wĩoo wa ũnĩ ũla ũngĩ: na kũtyaavonoka mũndũ wamo, ate o anake maana ana, ala makuĩtwe nĩ ngamĩle na makĩie.'),
('kam', '1SA', 30, 18, 'Na Ndaviti atũnga syonthe ila Aamaleki matwaĩte, na Ndaviti atangĩĩa iveti syake ilĩ.'),
('kam', '1SA', 30, 19, 'Na kũtyaĩ kĩndũ kyaatiala kwoo, kĩnini kana kĩnene, ana o na eĩtu, o na mũtavo, o na kĩndũ o na kĩva kĩla meetavĩe: Ndaviti nĩwatũngie syonthe.'),
('kam', '1SA', 30, 20, 'Na Ndaviti oosa ndĩthya syonthe sya mbũi na malondu na sya ng’ombe, ila maingĩte mbee wa indo ila ingĩ, na asya, Ii nĩ mũtavo wa Ndaviti.'),
('kam', '1SA', 30, 21, 'Na Ndaviti avika vala ve ala andũ maana elĩ, ala maĩ anyalu mataĩ matonya kũmũatĩĩa Ndaviti, o ala mamatiĩlĩte kalũsĩnĩ Mbesoli; na mauma mamũthaũe Ndaviti, na kũthaũa andũ ala maĩ nake: na yĩla Ndaviti wathengeeie andũ, amakethya.')
